INSERT INTO `blog_diary` VALUES (575, 1, '今天完成了明天答辩用到稿子，顺便熟悉了一下ppt，感觉差不多了，机器人联调那边把变电站名字中文乱码的问题解决了，今天就不把稿子放进来了，等明天再说，然后go语言的接口也可以写了，明天答辩完成之后试试从数据库中取数据返回接口，go每次使用数据库都要重新连接吗，好麻烦啊。', '2021-12-08', '2021-12-08 22:23:00', '2021-12-08 22:23:00', 1);
INSERT INTO `blog_diary` VALUES (576, 1, '今天继续ice和netty的连接，现在已经可以实现从netty发送信息，在eims中收到信息，然后转换格式将信息发送到ice并且将成功收到的相应返回netty，明天应该是要做在ice中调用我在eims中写好的接口然后请求机器人返回数据，这个中间等待的过程没办法，只能等30s，超时就返回空值，这个难点我觉得是在ice客户端这我不会调用eims的接口，明天过去试试这个实现了我这个项目的任务就算完成了，顺便我自己copy下代码，留作纪念，也算是学习笔记，以后要是用到netty也可以拿出来看看，晚上弄我的博客，今天晚上仔细看了看vuex的分模块，然后就实现了，之前一直没做一是因为太马虎了，没有仔细看，也没有去实践，再就是看着小游的博客弄vuex的分文件，一直有问题就放弃了，今天才知道可能他那个格式是nuxt的写法，因为我没有使用nuxt，所以才会报错，总之今天还算是可以的，晚上回家之后把鞋刷了，还交了这个月的房租，9-10月的电费，7-8-9-10月的水费，又没钱了，坐等10号发工资。', '2021-11-08', '2021-11-08 22:55:44', '2021-11-08 22:55:44', 1);
INSERT INTO `blog_diary` VALUES (577, 1, '今天将博客的文章功能实现了，后端增删改查也没什么问题，就是晚上改了几个接口，文章类型出现了bug，等明天修复，然后博客部署还是得等等，因为旧的xshell没了，新的xshell还没找到破解版。', '2021-10-08', '2021-10-08 22:56:42', '2021-10-08 22:56:42', 1);
INSERT INTO `blog_diary` VALUES (578, 1, '今天一天真是个大废物，玩了一天手机，今天开始下定决心走出舒适圈，可能会找找兼职，也要开始锻炼自己的社交能力，别再那么内向。', '2021-08-28', '2021-08-29 00:10:38', '2021-08-29 00:10:38', 1);
INSERT INTO `blog_diary` VALUES (579, 1, '昨天上下午培训，之后和旭福一起去西湖走了走，不过去的晚了雷峰塔已经关门了，只在外面看了看，第一次去西湖，感觉西湖好小啊，我一直以为西湖是那种一眼看不到边的特别大的湖泊，晚上吃饭说的是等他来杭州第一次吃饭我请客，结果我又白嫖了。', '2021-09-11', '2021-09-12 21:29:26', '2021-09-12 21:29:26', 1);
INSERT INTO `blog_diary` VALUES (580, 1, '今天完成了springboot整合mybatis的那个联系demo，下午开会，然后就是收到了http培训的邮件，下周就要去培训了，总共俩周。', '2021-08-11', '2021-08-11 22:26:30', '2021-08-11 22:26:30', 1);
INSERT INTO `blog_diary` VALUES (581, 1, '忘了写日记，再次打开电脑。今天虽然没做什么事，但感觉好累啊，白天在公司弄好了Ubuntu的可视化，本来打算用centos装个邮件发送功能就好，结果整出这么多事，最后没办法了才用了Ubuntu的可视化界面，不过这样也好，方便在公司上gitee，晚上回来node，不知道什么原因之前的node不能用了，只好重装，换新的node也花了不少时间，最后还是解决了，不过那个傻逼博客真草啊，把错的写上去，离大谱，看来自己搞博客还是有必要的，一是能聚集些志同道合的小伙伴，再就是还可以共同学习，国庆假期要加油啊。', '2021-09-28', '2021-09-29 00:02:10', '2021-09-29 00:02:10', 1);
INSERT INTO `blog_diary` VALUES (582, 1, '今天也好冷啊，冬天到了吗，工作今天是开始看icc的pmms代码，虽然不是完全理解，但感觉还可以吧，任务的话最近要看restServiceApi的一个模块，大概看了一下好像是管理模块日志的，不过应该是我理解错了，今天要让我去优化数据库，具体需求是这样的：因为设备频繁的上下线，导致数据库中的设备上线记录数据特别庞大，所以要对这个服务优化，让数据不那么多，所以很自然的想到在线时间较短的不要放在这个数据库中影响查询效率，所以就要把在线时间低于某个值的记录存在其它地方，或者以文件的形式存在电脑上，显然存在电脑上这个成本要高一些，所以我的解决方法就是新建一个表用来存放上线时间低于某个值的数据，不过知道是这样解决，新建数据库表会不会对其它数据产生影响，以及查看时对俩个表的读写，感觉好像也不是那么简单，不知道领导交给我这个任务是为什么，是要摸查我的工作能力吗？这几天再考虑考虑。然后就是最近玩星露谷物语好肝啊，一有时间就玩，真的停不下来，博客也一直没有更新，尽快恢复状态吧。', '2021-10-18', '2021-10-18 23:15:42', '2021-10-18 23:15:42', 1);
INSERT INTO `blog_diary` VALUES (583, 1, '周日没写日记，因为玩浮岛物语太肝了，忘了写，不过一天也没做什么就玩游戏了。', '2021-12-26', '2021-12-27 23:53:24', '2021-12-27 23:53:24', 1);
INSERT INTO `blog_diary` VALUES (584, 1, '今天一天只完成了一个功能，甚至没有学习，进度最近是真慢啊。先说功能，博客实现了在后台管理系统保存文章时新增选择文章分类的选项，如果没有选择会提示选择文章分类，然后保存，如果已经选择了文章分类可以直接保存，点击已有的文章进行修改时会在文章分类选项默认选择该文章的分类，另外之前遗留的bug无法生成当前日期和文章阅读点赞的数量现在也已经修复，文章默认阅读点赞数量都为一，一是因为就当我自己的点赞，再就是如果设置为零在Navcat中查看会显示null值，不知道是因为在公司的版本低还是其它原因，总之设置为一就没有任何问题。然后今天真是倒霉的一天啊，大早上骑车就把车锁子丢了（虽然这个锁子开关极其不方便，我也想换了），然后我又公司吃完饭回来找，结果也没找到，到公司的时候都已经九点多了（还好我在总部已经打开，没有迟到）。晚上下班走那条常走的那条小路，因为下雨积水，路上好多泥，车子陷进去了我只好防止摔倒一脚踩了进去，白鞋都变成了黑色的，虽然有点郁闷，不过还好吧，正好把鞋子刷一下，前几天买的鞋刷刚好派上了用场，希望明天鞋子能干了，今天就早点休息了，明天继续完成博客文章分类展示的功能。', '2021-07-28', '2021-07-28 23:13:10', '2021-07-28 23:13:10', 1);
INSERT INTO `blog_diary` VALUES (585, 1, '今天早晚跑步，早上感觉跑不掉，晚上继续打破五公里记录（31分40秒），明天开始在公司的第一个写代码任务。', '2021-09-01', '2021-09-01 22:50:56', '2021-09-01 22:50:56', 1);
INSERT INTO `blog_diary` VALUES (586, 1, '26号，公司抓图的那个项目完成了，等下周最后一次测试完成让导师评审完就可以结束这个任务了，博客今天没时间写，下午忙那个接口的修改，加了个分页和时间格式，今天把代码从公司发回来，等明天整理一下，这周大周舒服啊。', '2021-11-26', '2021-11-27 01:58:56', '2021-11-27 01:58:56', 1);
INSERT INTO `blog_diary` VALUES (587, 1, '今天本来是没任务的，到晚上突然直接来了俩个任务，还都不会弄，明天好好看看吧，一个是测试的任务，应该就是按照需求测试吧，这个感觉还是可以处理的，另一个任务是使用netty对服务器的请求进行转发，大概是这样吧，然后就是今天开始了博客的修改，今天开始修改了用户和角色的界面，大概还可以吧，还是要尽快部署新的博客。', '2021-10-26', '2021-10-26 23:50:58', '2021-10-26 23:50:58', 1);
INSERT INTO `blog_diary` VALUES (588, 1, '周六，要上班所以没啥想做的事情，今天去了公司完成了那个改密码的项目，最近也没啥事情了，感觉要来大活了，玩浮岛物语到现在，正好看看epic送啥游戏。', '2021-12-18', '2021-12-19 01:03:20', '2021-12-19 01:03:20', 1);
INSERT INTO `blog_diary` VALUES (589, 1, '今天周日，上午写完了三篇博客，下午睡了一觉，结束。', '2021-08-01', '2021-08-01 23:37:12', '2021-08-01 23:37:12', 1);
INSERT INTO `blog_diary` VALUES (590, 1, '国庆第一天，博客前端整理了一部分，今天还学习了vuex，虽然说是学习了vuex但是感觉vuex内容也不是很多，目前应该是只能看懂简单的vuex使用。博客进度现在是打算admin管理页面较大修改，现在还只是开始。', '2021-10-01', '2021-10-01 23:39:20', '2021-10-01 23:39:20', 1);
INSERT INTO `blog_diary` VALUES (591, 1, '这次分的任务完全没有头绪，看了一天的代码头疼，但还是没看明白要怎么做业务，这个项目到30号截至，所以大概就是下周要完成，之后也不知道会怎样。因为今天有项目博客也没有心情写，今天算是啥也没做吧，晚上玩了玩缺氧，做出了气压服。', '2021-11-18', '2021-11-18 23:04:08', '2021-11-18 23:04:08', 1);
INSERT INTO `blog_diary` VALUES (592, 1, '今天走了一天，从海宁的回头潮到西湖的飞来峰，跨越了整个杭州，潮还有点意思，虽然没有想像中的那么高，但感觉还是可以的，然后就在海宁吃完饭到了西湖的飞来峰，我们是骑自行车上去的，然后自行车刚骑上去就被别人骑走了，感觉我就是一个骑自行车上山的工具人，然后就买了门票上山，才300多米，中间擦了一下汗，感觉就是一口气直接上去了，上去之后稍微有点雾看下面不是特别清楚，之后下山路上等都没有，简直太差劲了，下山就没有找到自行车，一路走来下来顺便就去了断桥，本以为断桥就是字面意思，没想到是段家桥简称断桥，最后感觉西湖这风景也没有人们说的那么好，果然眼见为实，最后晚上就去请旭福吃个晚饭，160r感觉太tm贵了，不过偶尔一次还算可以接受。今天晚上回来就不早了，今天又是没有写博客的一天，明天又要写博客还要下载xshell，还不想早起，尽力吧。', '2021-10-06', '2021-10-07 00:03:30', '2021-10-07 00:03:30', 1);
INSERT INTO `blog_diary` VALUES (593, 1, '昨晚熬夜看完了edg的比赛，没想到居然能赢，今天项目也就那样，刚刚开始写，弄了好多类，到时候测试肯定是个问题，博客一天没看，不过前后端暂时不会有大的修改，所以今天开始看看安装，没想到第一步就难住了，所以这周任务就是把安卓运行起来。', '2021-11-01', '2021-11-01 23:24:52', '2021-11-01 23:24:52', 1);
INSERT INTO `blog_diary` VALUES (594, 1, '博客权限管理功能基本完成，明天可以继续tinymce，完善日记功能。', '2021-08-05', '2021-08-05 23:12:06', '2021-08-05 23:12:06', 1);
INSERT INTO `blog_diary` VALUES (595, 1, '周日早上起来就玩泰拉瑞亚，一个人盖了好几个环境的房子，还有打了几个boss，下午玩云顶之奕，当晚上玩了下缺氧，顺便买了缺氧的新dlc，这个周末总结一下好像啥也没干，还好把博客的整理弄了一下，也算唯一有意义的事情了。', '2021-11-14', '2021-11-15 21:09:22', '2021-11-15 21:09:22', 1);
INSERT INTO `blog_diary` VALUES (596, 1, '今天锁子又丢了一次，还好我找到了，晚上六点下班，到八点去公司嫖哥餐补，回来打王者比赛惨败。', '2021-08-18', '2021-08-19 00:05:08', '2021-08-19 00:05:08', 1);
INSERT INTO `blog_diary` VALUES (597, 1, '上午调休三个小时，没想到主管竟然联系我，今天是第一次调休，主要还是因为昨天晚上打游戏太晚了，下午去了公司还是之前那个项目，把抓图计划的功能增删改查都弄好了，但是没有测试，不过写完之后项目还能跑起来，应该是问题不大，第一次启动报没有数据库表的异常，联系张崇要到了数据库表添加完成之后就没问题了，博客这几天应该是没时间写了，倒是可以在晚上偷偷弄一下，最近看了俩部动漫，一个是女武神驱动这个好色情啊，没想到这个也看完了，还有一个是凉宫春日的忧郁2009，不知道2009是年的意思吗，还有重制版？这个最近才看了几集也很好看，缺氧今天都没玩，这几天沉迷云顶之奕双人模式无法自拔。', '2021-11-22', '2021-11-22 23:24:56', '2021-11-22 23:24:56', 1);
INSERT INTO `blog_diary` VALUES (598, 1, '周日忘了写日记，结果今天（周二）误操作把周一写的日记删了，我操了。', '2021-11-28', '2021-12-01 00:11:34', '2021-12-01 00:11:34', 1);
INSERT INTO `blog_diary` VALUES (599, 1, '今天把那个需求改完了，但是没办法测试，我只好等前端写好然后发请求，我测试这个能行不能行，今天的算法题还是昨天那个，我就说并查集肯定可以的，出错是因为检查是否同一组没写过滤条件，今天发现了，第一次并查集过的，然后又看了下Kruskal算法，其实也是并查集的思想，学会之后用Kruskal算法也过了一次，之后看Floyd算法，发现好像Floyd算法好像不能过，晚上回来玩了下盐与避难所，怎么说呢，没看视频那么有感觉，不是很想玩了，现在半夜了，都31号，等epic领古墓丽影游戏，不知道是不是这个，epic又炸了。', '2021-12-30', '2021-12-31 00:13:28', '2021-12-31 00:13:28', 1);
INSERT INTO `blog_diary` VALUES (600, 1, '今天的模拟答辩好紧张啊，果然得好好写个稿子，上场一懵逼啥也不知道了，今天玩了下泰拉瑞亚，白天公司任务就是联调机器人项目，没做其他事情。', '2021-12-06', '2021-12-06 23:45:32', '2021-12-06 23:45:32', 1);
INSERT INTO `blog_diary` VALUES (601, 1, '博客新加入了swagger和log4j2，然后今天开始了小游博客的学习，打算将这个博客改成spring的。', '2021-09-26', '2021-09-27 00:10:44', '2021-09-27 00:10:44', 1);
INSERT INTO `blog_diary` VALUES (602, 1, '周六，没做啥特别的事情，博客把设置弄好了，现在只差其它页面对设置功能的兼容了，然后就是博客现在使用了scss，感觉这个写css非常棒，结构特别清晰，晚上看lol的比赛，今晚是t1和dk的四强，太刺激了，虽然我还在边玩星露谷，不知不觉星露谷也玩到了第二年冬天，但是我节奏依然很慢，不过无所谓，休闲游戏嘛。', '2021-10-30', '2021-10-30 23:54:16', '2021-10-30 23:54:16', 1);
INSERT INTO `blog_diary` VALUES (603, 1, '今天在公司一整天就弄了一个邮箱激活注册账号，本地测试完全没有问题了，但是部署到服务器又有了一点小问题，感觉我一天效率好低，晚上回来把新旧页面以及接口部署到服务器上了，虽然还是遇到了一点小问题，不过这次部署服务器熟练多了。再就是今天杭州的补贴到了，从申请到钱到账就十几分钟，必须赞一个啊。', '2021-07-26', '2021-07-26 22:55:48', '2021-07-26 22:55:48', 1);
INSERT INTO `blog_diary` VALUES (604, 1, '今天完成了第二个项目，虽然遇到了不少困难，但是通过问导师还是解决了，对项目也进一步熟悉了，然后就是今天公司发了中秋节月饼，美滋滋，想想东方国信就来气。', '2021-09-13', '2021-09-13 22:44:10', '2021-09-13 22:44:10', 1);
INSERT INTO `blog_diary` VALUES (605, 1, '周末依旧是啥也不干，睡一天，晚上看看英雄联盟比赛。', '2021-10-24', '2021-10-25 00:09:54', '2021-10-25 00:09:54', 1);
INSERT INTO `blog_diary` VALUES (606, 1, '今天博客写了文章分类的功能，现在可以做到文章写完之后按分类对文章管理，然后前端页面也做了按分类查询文章，这么一总结好像今天确实没做什么事情，可能是因为好多东西都不会吧，动漫的话最近还在追的大概就是86一个了，别的要么是看完了，要么是不想看了，86等多出几集一次性看吧，一集一集太慢了，最近在看丁菊长的7日杀视频，搞得我也好想玩，可惜电脑不太行，然后就是也没太多时间，就算开完一个人也无聊，还害怕游戏里面那些突然吓人的元素，还是算了吧。今天还发了工资，扣除五险一金等到手9k，然后就交了房租，不过现在我攒的钱也有15k了，还是攒钱舒服啊。博客明天做什么还没想好，可以看看日记功能顺便再弄一下小游博客里面的markdown，然后写博客的时候可以选择用那种markdown编辑器，不过这应该是以后的事情了，现在还是先做完，以后再考虑那种个性化的设置。', '2021-10-11', '2021-10-11 23:42:56', '2021-10-11 23:42:56', 1);
INSERT INTO `blog_diary` VALUES (607, 1, '一定要坚持下去啊，最近都不想写日记，今天上午调休，下午去了也没做啥特别的事情，就日常把一周的文章等打包发回家，做了道水题，今天使用picgo的时候发现那个不能多端同步，有点难受，不过凑合用吧，我再找找有没有其它的管理根据，实在没有就在gitee上管理也行，晚上打游戏，不想睡觉，有点想买荒野大镖客2，看最低配置要求我的电脑也能玩，犹豫几天，万一e宝送了呢，不过今天圣诞节的游戏不太行啊，还想着是啥3a呢，差不多刷个牙睡觉了。', '2021-12-24', '2021-12-25 01:10:08', '2021-12-25 01:10:08', 1);
INSERT INTO `blog_diary` VALUES (608, 1, '今天导师给分配了一个比之前那个任务稍微难一点的任务，，不过我觉得还算OK，也就是几个接口的事情，麻烦的地方就是admin代码有点难懂，还要看jsp的代码，然后再加一个选择框，感觉这个应该是最费时间的任务，剩下的接口实现应该难度不大。个人学习进度的话，今天看了mongodb和springboot的整合，感觉这个mongodb使用比MySQL还要简单一点，所有查询spring都已经弄好了，使用时只需要按需调用就行，但是以我使用MySQL多年的经验来考虑，不知道mongodb有没有自定义查询语句这一说法，毕竟是第一次使用非关系型数据库，具体细节也不太清楚，再就是因为公司不能使用腾讯的云服务器，最近打算把阿里云上的博客迁移到腾讯云上面，然后在公司使用阿里云服务器，折腾并写出安装各种软件的博客文章，明天上午代码svn权限下来之后开始实现接口，我觉得大概1天半就能弄好，剩下的时间可以写博客文章，最近优先安装软件的教程。跑步已经俩天没跑了，晚上是不过俩小时，早上是没力气跑不动，哎。', '2021-09-08', '2021-09-08 23:11:16', '2021-09-08 23:11:16', 1);
INSERT INTO `blog_diary` VALUES (609, 1, '今天在公司依然没有分配任务，不过我并不着急，打卡就上一个项目偷偷的填几次，今天弄netty连接还是不行，百度了那么多，最后决定用netty4，看各种文章好像说netty5不更新了，然后就是博客了，昨天说的开始写doc的功能，没想到今天就弄好了，现在有前端页面的展示和后端页面的修改，个人感觉整体布局还是可以的，就是一些小地方可以在修改一下，博客最近又发现一个bug，不知道为啥登录之后有时候不显示用户的数据信息，还有登陆页面的图片有时会加载不出来，今天先记录一下，等知道原因之后再修改，晚上回来把缺氧的新坑开了，每天玩一点大概10-15个周期，还有博客中关于游戏的动漫的功能也打算开始设计一下，毕竟现在可以上传文件了。', '2021-11-16', '2021-11-16 23:44:06', '2021-11-16 23:44:06', 1);
INSERT INTO `blog_diary` VALUES (610, 1, '今天进厂工作第二天，上课讲的ipc等一些项目完全不懂，又算混了一天日子；再就是偶然得知组内好多研究生，可能只有我一个是本科弟弟，又TMD受刺激了，为啥大家全是大佬。先定一个小目标，俩年之后要卷进大厂。最后就是今天是连续跑步的第二天，好久不跑五公里现在跑到了33分29秒，继续努力，等周围大学开学之后可以去学校跑步，顺便看看妹妹[doge]。', '2021-08-21', '2021-08-21 23:18:02', '2021-08-21 23:18:02', 1);
INSERT INTO `blog_diary` VALUES (611, 1, '今天应该是休息日，结果远程支持公司4个多小时，打游戏都不能好好打，中午吃饭回家还下了雨，我发现我玩缺氧总是坚持不下去，不知道为啥，玩个几周期就想换下一个档，今天又开了一个，但是又不想玩了。', '2021-12-12', '2021-12-12 22:47:16', '2021-12-12 22:47:16', 1);
INSERT INTO `blog_diary` VALUES (612, 1, '这几天感觉日记没什么想写的，今天完成了博客的标签功能，对标签的增删改查、按标签查询文章、写完文章对文章分类等都完成了，接下来想去实现博客的日记功能，打算使用富文本编辑器在后台写日记，前台展示想做成日历界面，然后点击某一天查看，还有就是日记加密码的功能也在考虑，但是完全没有想法。明天继续ActiveMQ的学习，要是没有别的事情也可以想想日记功能的实现。', '2021-08-03', '2021-08-03 22:48:10', '2021-08-03 22:48:10', 1);
INSERT INTO `blog_diary` VALUES (613, 1, 'HTTP培训第一天，因为昨天视频弄得今天一整天瞌睡，总的来说今天还行吧，虽然啥也没干。一天下来印象最深的还是红黑大战，游戏规则是双方队伍各选一张牌，然后都是红色就都扣五分，一红一黑的话黑色放扣五分，都黑色就都加五分，简单来说还是考研交流的，再就是害怕对方背刺，往深一点就是诚信问题了，虽然我一开始也没想到，就把它当一个游戏，甚至我们都开始选对方的牌，玩起了刺激的，还有最近博客网站暂停更新半个月，一是因为最近http培训没什么时间，然后就是也没想到要加什么功能，可以试试优化，网站加载太慢是因为我服务器太差，还是被攻击的原因啊，不太清楚。对了，昨天好像没有记录王者荣耀比赛胜利的事，虽然是被大佬带飞了。', '2021-08-16', '2021-08-16 22:25:06', '2021-08-16 22:25:06', 1);
INSERT INTO `blog_diary` VALUES (614, 1, '今天好累啊，工作实在是太难了，netty啥的ice啥的完全不懂，还要建立连接，实在是太难了，今天不想努力了，明天再加油吧，希望明天的我好运。忘了还有博客，博客应该是我现在的精神支柱了，这个无论如何我都要弄到完美，今天看了图片上传，感觉还是有希望这周实现的，明天晚上加油尝试弄好，今天已经可以展示出图片了，算是进步吧。', '2021-11-03', '2021-11-03 23:15:26', '2021-11-03 23:15:26', 1);
INSERT INTO `blog_diary` VALUES (615, 1, '今天是流水线第二天，早上迷路了然后过去就没打卡，不知道今天会不会影响总部的打卡记录扣我工资，今天流水线工作量应该是比昨天更大，但是感觉还好点没有昨天那么累，晚上跑步五公里，然后走了大概也有三公里，再坚持俩天就好了，马上脱离苦海。', '2021-08-24', '2021-08-24 22:49:52', '2021-08-24 22:49:52', 1);
INSERT INTO `blog_diary` VALUES (616, 1, '今天算是公历生日，没想到还收到了公司的祝福和不知道怎么使用的积分，今天博客几乎没有写，就晚上弄了一下博客的分页，目前不打算用pagehelper这个插件了。然后就是可能这几天都不会在有时间写博客了，最近接了一个新的任务，要升级项目的依赖版本，大概就这些，最近打王者荣耀上头，哎。', '2021-10-12', '2021-10-13 00:57:58', '2021-10-13 00:57:58', 1);
INSERT INTO `blog_diary` VALUES (617, 1, '2021年7月16日19点51分服务器终于部署成功了，写个日记庆祝一下部署遇到的问题还挺多的先是nginx、tomcat、mysql下载就搞了好几天，因为服务器只是一核两G一M，所以我不能在服务器上面下载mysql8，最后没办法只好选择了5.6版本的mysql，具体安装过程我会在博客中写出来，只不过安装服务器是在公司干的，公司对信息保密要求比较高，所以我当时的截图没办法带出来，只好偷偷的把截图拍了下来，环境安装完成之后就开始着手部署我的博客，最初的博客部署也遇到了许多bug，不过最深刻的还是跨域问题，具体细节我之后也会在博客说明（还没开始写博客就挖了这么多坑），先出去锻炼身体，毕竟这周部署只能在晚上下班之后搞，天天干到12点。钱塘江骑行15公里，今天早睡。', '2021-07-16', '2021-07-16 22:34:22', '2021-07-16 22:34:22', 1);
INSERT INTO `blog_diary` VALUES (618, 1, '今天完成了那个任务，不过只是代码实现完成了，明天还要再去试试有没有bug测试一下，今天我又当倒霉蛋了出门没带钥匙到晚上下班回家才发现，找钥匙找了半天，晚上回家之后去找房东借了我这个房间的钥匙，在柜子上发现的，我都准备好钥匙丢了，打算周末去配钥匙，不过这样也好能省点时间，博客最近一直没有看，工作稍微有点忙，再加上我还不是很熟悉，一直做的很慢，加油吧。杭州真冷啊，这还没到冬天。', '2021-10-20', '2021-10-20 23:29:16', '2021-10-20 23:29:16', 1);
INSERT INTO `blog_diary` VALUES (619, 1, '最近没状态写代码，博客进度有点慢，而且也不想学习，明天尽力吧，写写博客。今天周六小周，在公司就打游戏了，王者荣耀五个小时都打满了，还蹭了公司的各种福利，今天就当咸鱼吧。', '2021-08-07', '2021-08-07 23:06:52', '2021-08-07 23:06:52', 1);
INSERT INTO `blog_diary` VALUES (620, 1, '今天写了一篇博客，然后琢磨怎么剪视频，搞到了半夜，可算是弄好了。', '2021-08-15', '2021-08-16 00:36:24', '2021-08-16 00:36:24', 1);
INSERT INTO `blog_diary` VALUES (621, 1, '今天弄了半天多的springboot的源码环境，结果还是不行，不知道是不是因为公司墙的原因，总之就是没弄好，然后继续mongodb，完善了一下代码，晚上没有开会，所以又没有去跑步。', '2021-09-15', '2021-09-16 07:38:52', '2021-09-16 07:38:52', 1);
INSERT INTO `blog_diary` VALUES (622, 1, '双十一没买啥特别的东西，就买了洗衣液和掏耳勺，今天从家里邮的衣服也到了，甚至我带来了羽绒服，就是不知道杭州冬天能有多冷，公司任务今天导师过来评审了代码，提出了几个要修改的地方，下午也大概改完了，剩下明天检查一下提交，这个项目就告一段落了，晚上依旧是修改我的博客前端页面，把之前遗留的页面刷新会404的bug修复了，bug原因是我在vue的路由中加入了通配符跳转到404页面，动态路由会加载到后面，所以导致先被通配符匹配就跳转到了404页面，大概是这个原因，在页面调整完成之后，又把tab标签因为刷新而导致vuex缓存清空，修改了一下，在页面刷新之前先保存tags里面的内容，刷新之后加载出来，暂时应该没有其它bug了，之后可以继续完善博客的设置功能。', '2021-11-11', '2021-11-11 23:44:04', '2021-11-11 23:44:04', 1);
INSERT INTO `blog_diary` VALUES (623, 1, '昨天忘了写日记，仔细想想昨天干什么都忘干净了，果然日记还得天天写啊。今天上午把新版本博客的查看博客功能实现了，感觉也没有特别难，下午就整理了mybatis的笔记，写了一篇博客，虽然一天也没玩游戏，但感觉也没做多少事情，对了今天还研究了markdown编辑器，我计划是直接用markdown存储图片，结果测试发现base64编码的图片好像只能放一张，所以我就只能够先在csdn上写好博客，然后再发我自己的博客上面，不过图片存储这个功能我还是要实现的，毕竟用自己的博客还是舒服点。', '2021-07-24', '2021-07-25 21:57:34', '2021-07-25 21:57:34', 1);
INSERT INTO `blog_diary` VALUES (624, 1, '周六，一觉醒来都快中午了，然后去公司上班，在总部吃的饭，总部餐厅食堂还真是便宜啊，再一次羡慕，下午去了就没啥事情，看go语言，我学的是echo框架，暂时也不考虑其它的框架，今天完成了连接MySQL、redis和ActiveMQ的收发信息，下午做的事情还挺多，今天小周不知道为啥没有下午茶，太遗憾了少白嫖一次，晚上就下下棋，没有玩单机，我本来是边下棋边看动漫，然后看到李超凡也在线就开语音一起玩，没看动漫 -- 现实主义的勇者的王国再建记，好长的名字...', '2021-12-04', '2021-12-04 23:47:12', '2021-12-04 23:47:12', 1);
INSERT INTO `blog_diary` VALUES (625, 1, '开始学习go语言，然后使用了echo框架，实在是太简单了，卧槽，我以为spring以及很牛逼了，没想到还有更简单的。然后就是今天跑步五公里继续破纪录，现在是30分20秒，本周有希望迈进30分钟以内。在公司的项目任务的话，今天完成了几个api的修改，因为是熟悉的spring项目，所以修改起来也很简单，今天还算充实吧。不知道昨天有没有写自行车爆胎的事情，买的补胎工具都不发货，真慢啊。', '2021-09-06', '2021-09-06 23:34:00', '2021-09-06 23:34:00', 1);
INSERT INTO `blog_diary` VALUES (626, 1, '周六一天呆在家，起的很晚，下午李超凡一起玩泰拉瑞亚，打完了蜜蜂，骷髅王没打过，之后我又玩了一小会，还有周六收到了李超凡送的游戏无尽旅图。', '2021-11-13', '2021-11-15 20:59:16', '2021-11-15 20:59:16', 1);
INSERT INTO `blog_diary` VALUES (627, 1, '周一，应该是今天会有很长的日记，不过今天不太想写，今天在公司算是改完了中石化项目的那个bug，整整一个下午都在部署服务器，最后发现其实是我这电脑的问题，也不知道为啥我这打包部署上去就会报错，但是同事的电脑就没问题，也不知道是为啥，今天把阿里云服务器的系统换成了windows，然后用Windows远程我的腾讯服务器，真是个好的解决方案，最近要加快博客的进度了,操刚刚失误操作，我以为又把日记删了，还好。快一点了，vue项目打包呢，提示一个警告，要更新node，我看我node版本是14，最新是17，就因为是我的版本太低先升级到16，结果到16还是不行，网上找结果是要降版本，我换到12直接error，然后13还是不行，现在又换到了14，警告还是没有，不过已经无所谓了，还好代码能跑起来。', '2021-12-13', '2021-12-14 00:29:32', '2021-12-14 00:29:32', 1);
INSERT INTO `blog_diary` VALUES (628, 1, '今天有点累，也没有学习，就是因为昨天打游戏上头了，一直玩到半夜，游戏已经卸了，垃圾云顶之奕，赢一把就这么难吗。今天睡到了中午，下午又睡一会，然后出去打疫苗，晚上看比赛。明天一定要早起，整理一下笔记。', '2021-07-31', '2021-07-31 21:51:26', '2021-07-31 21:51:26', 1);
INSERT INTO `blog_diary` VALUES (629, 1, '周五，大周，一直下棋到现在，没胡一把，难受。', '2021-12-10', '2021-12-11 02:25:14', '2021-12-11 02:25:14', 1);
INSERT INTO `blog_diary` VALUES (630, 1, '今天完成了博客日记功能，并且部署到了服务器上面，现在博客主要的功能都有了，其它想要添加的以后可以慢慢考虑，然后就是对现在博客的优化，加载是真的慢，不知道是阿里云网的问题还是服务器被攻击的问题，反正都不会解决，以后再慢慢做优化。明天应该是要学习公司的任务了，第一个应该是spring boot项目搭建，再就是spring源码阅读也可以开始准备了。', '2021-08-09', '2021-08-09 21:42:16', '2021-08-09 21:42:16', 1);
INSERT INTO `blog_diary` VALUES (631, 1, '今天完成了那个项目，然后写了俩个小篇文章，一个是记录MySQL存储过程和事件的，另一个记录spring的@scheduled注解的cron表达式的，明天要去团建，也不知道怎么样。', '2021-10-22', '2021-10-23 00:51:42', '2021-10-23 00:51:42', 1);
INSERT INTO `blog_diary` VALUES (632, 1, '今天开始整理博客前端页面，博客的head部分今天弄好了。', '2021-09-23', '2021-09-24 00:04:00', '2021-09-24 00:04:00', 1);
INSERT INTO `blog_diary` VALUES (633, 1, '今天基本完成了开源项目修改的任务，留下的都是一些不会修改的，博客好几天没有更新了，前几天新写的博客分页类以后打算在博客后台使用，使用分页发现一个bug，所以前端打算使用那种懒加载的格式，页面拉到下方会自动更新新的内容，今天把我电脑的maven仓库给公司那边发一份。', '2021-10-14', '2021-10-14 23:54:36', '2021-10-14 23:54:36', 1);
INSERT INTO `blog_diary` VALUES (634, 1, '昨天又忘了写日记，今天补上，昨天起床比较迟，然后一天都没有什么干劲，然后就一直看动漫，看了海贼王女、黄昏乙女·失忆还有笨拙之极的上野不过还好都没有看完，再就是异世界四重奏这个也只是看了一点，我发现同时看到动漫太多都看不过来，所以今天再定一个看番规矩∶同时追番数不能超过三个。然后就是昨天还和旭福约好的去看潮，现在正在路上，今天的事情就不在昨天的日记里面记录了，等晚上回来再写吧，关于博客更新明天无论如何也要发一版，第一版可能会有很多bug，现计划今天晚上和明天还能写写，马上到站了就这样吧。', '2021-10-05', '2021-10-06 23:13:06', '2021-10-06 23:13:06', 1);
INSERT INTO `blog_diary` VALUES (635, 1, '今天下班挺早的，回家就开始下棋，然后不知不觉就0点了，这个赛季比上个赛季强不少，还是可以玩的，在公司今天完成了ice的客户端连接，虽然完全是靠着导师完成的，博客今天没有写，等明天打棒球回来把图片上传的功能同步了，然后可以再把页面的设置写了，毕竟只有一个设置也没啥用得有功能。', '2021-11-05', '2021-11-06 00:07:06', '2021-11-06 00:07:06', 1);
INSERT INTO `blog_diary` VALUES (636, 1, '时隔半个多月又开始了个人博客的开发，今天主要是对博客性能的优化，加入了redis。', '2021-08-30', '2021-08-30 22:29:48', '2021-08-30 22:29:48', 1);
INSERT INTO `blog_diary` VALUES (637, 1, '今天博客2.0界面已经设计完成了，明天要开始博客数据库的设计，应该是以目前的数据库为基础，再新增一些内容，后端依然是使用原来的后端，预计是前端界面有两个项目，api全部写在springboot中。今天主要就是把前端页面大体做完了，还看了一集ssm的那个视频，晚上折腾go语音，不知道go语言开发咋样，先看看go语言的lris框架，后端接口有想法使用go开发一部分。', '2021-07-22', '2021-07-22 23:13:12', '2021-07-22 23:13:12', 1);
INSERT INTO `blog_diary` VALUES (638, 1, '今天上午学习使用markdown编辑器，发现使用markdown自带的上传图片功能竟然可以在我的服务器上上传图片，毕竟我还没有实现这个功能，于是我就开始各种百度，查找markdown的图片存放位置，还有怎么对图片命名的，可惜并没有发现任何关于markdown存放图片位置的相关信息。然后我开始查看我本地的markdown依赖包，使用tree查看目录可惜没有任何收获，最后机缘巧合之下看到了我MySQL中存放文章的那个库中虽然只保存一张图片，但还是会有很长的一串字符，顺着这个线索找发现了markdown编辑器是使用base64编码将我的图片保存在了数据库中，看来我格局又小了。下午躺着没动过甚至晚饭都没去吃，我为什么会这么懒。', '2021-07-18', '2021-07-19 22:54:22', '2021-07-19 22:54:22', 1);
INSERT INTO `blog_diary` VALUES (639, 1, '今天公司任务是要开始看icc的项目的代码功能了，正合我意，n8000的admin代码架构是structs，因为没学过看都看不懂，每次修改功能需求都要卡老半天，今天主要是使用了icc的那个客户端，不过也没发现些啥，都只是点了点，没看接口，甚至要我负责的模块功能我都不太清楚，明天继续看，最近项目也不多，机器人的算是结束了，之前天天看日志，现在也能看懂些，知道该怎么排查问题了，今天算法还做了俩道题，确切来说是一道，另外一道题是昨天卡着没完成，今天修该完了，最后发现是因为我的并查集join方法写错了，晚上回家把我的app框架弄好，现在网页不打算开发新的功能，可能会对性能进行优化，之后主要开始学习app怎么开发，尽快用上我自己的app，预期功能要做到可以登陆，看博客文章，登陆之后可以添加我的steam和epic类似小黑盒的样子，其它功能暂时还没想好，这几个也应该会做好久了吧，公司电脑不会弄安卓开发，只能在周末自己写写，还要学习怎么开发。今天把那个动漫《贫乏神来了》看完了，搞笑动漫还是可以的，有好多动漫梗，我知道的和不知道的都有，之后追鬼灭之刃第二季和86，其它待定。最后就是浮岛物语全成就太难了，一个银行产生100w看来要挂机好几个晚上，服了，啥jb设计啊。', '2021-12-28', '2021-12-28 22:55:10', '2021-12-28 22:55:10', 1);
INSERT INTO `blog_diary` VALUES (640, 1, '今天小周周六，去总部参加青苗计划的培训，晚上也没有跑步。', '2021-09-04', '2021-09-05 09:24:18', '2021-09-05 09:24:18', 1);
INSERT INTO `blog_diary` VALUES (641, 1, '今天上午开会，下午参加http见面会，接下来俩周就要开始上流水线了，拧螺丝万岁。', '2021-08-13', '2021-08-14 00:08:38', '2021-08-14 00:08:38', 1);
INSERT INTO `blog_diary` VALUES (642, 1, '今天开始写博客游戏模块的功能，公司没有任务，我是傻逼，把昨天的日记覆盖了，今天没心情写了，整整3k啊，卧槽。', '2021-11-30', '2021-12-01 00:14:28', '2021-12-01 00:14:28', 1);
INSERT INTO `blog_diary` VALUES (643, 1, '今天把中石化那个bug又测了一次，发现昨天一直能够上线2003个设备的原因是之前添加的那个设备的32个通道只启用了29个，所以就导致我能够上线2003个，其实上线的数量还是2000个，这个就解决了，添加了一个查询数据库在线的通道的sql，还有另外一个bug是添加通道超过一页，我要是不去看下一页，那么下一页的设备报到后端就是在线的状态（其实我这里说的在线，并不是真正的通道设备在线，而是这个通道启用，不过也就这样吧，反正就是那个意思），所以就导致了添加多页离线的设备会禁止，第二个bug我不管了，还要看html，也不知道为啥，而且也没要求改... 今天又给了一个需求，就是每次启用或禁用通道就要重新输入这个通道的密码，中石化的客户那边强烈要求去掉这个功能（其实我也很烦这个每次输入密码，改动正合我意，可惜是定制的，不会改基线），然后就去看代码，找到了这个设备的密码，返回前端就行，这样就省的每次输入密码，工作上的内容大概就这些，今天机器人测试也没叫我，可能是发现了我没啥作用。阿里云的服务器今天安装了git、idea、webstorm等软件，晚上又激活了，下载好了博客项目用到的依赖包，明天那个改密码的需求其实我已经弄完了，明天可以写写博客，还忘了一点，今天开始弄修改application.properties配置文件的工具类，这样就可以把配置文件中的一些数据动态修改了，不过今天晚上测试修改没有成功，明天再试试。', '2021-12-15', '2021-12-15 23:43:50', '2021-12-15 23:43:50', 1);
INSERT INTO `blog_diary` VALUES (644, 1, '流水线实习最后一天，可算是结束了，今天下雨没有跑步。', '2021-08-26', '2021-08-26 20:49:18', '2021-08-26 20:49:18', 1);
INSERT INTO `blog_diary` VALUES (645, 1, '今天没有任务，然后就把前几天下载的netty聊天室的项目弄到了springboot里面，出现一个问题就是，传输的message消息类需要序列化，然后才能正常使用，不知道什么原因，最近看完了凉宫春日、鬼灭之刃无限列车篇还有幼女战记剧场版，晚上下班回家打游戏霓虹深渊出bug了，真搞心态。', '2021-12-02', '2021-12-02 23:28:04', '2021-12-02 23:28:04', 1);
INSERT INTO `blog_diary` VALUES (646, 1, '周日，依旧是不想起床，爆肝游戏的一天，明天早上早点起来弄一下博客。', '2021-11-07', '2021-11-07 23:28:48', '2021-11-07 23:28:48', 1);
INSERT INTO `blog_diary` VALUES (647, 1, '今天依然没有新的任务，然后就开始了对博客后端以及性能的优化，现在主要还是对博客函数命名的规范以及博客注释的添加，再就是博客中使用了redis，减轻了对数据库的压力，也提高了博客的反应速度，今天晚上跑步只有3公里，可能是今天晚上跑的有那么一点快，后面稍微有点肚子疼，不过走了一会也好了，今天三公里15分12秒大概，一公里打破记录，现在是4分47秒。今天看视频感觉刀和弓好帅啊。', '2021-09-17', '2021-09-17 23:18:12', '2021-09-17 23:18:12', 1);
INSERT INTO `blog_diary` VALUES (648, 1, '第二天补的日记，昨天大概是把查找抓图的任务做了，完成了之前dms下发不成功的bug，然后博客大话就是开始了css的样式整理，打算把页面中所有的css整理成scss，这样我认为是整齐一点。', '2021-11-24', '2021-11-25 21:18:56', '2021-11-25 21:18:56', 1);
INSERT INTO `blog_diary` VALUES (649, 1, '今天做了道算法题，还是因为没事干闲的，算法用到了并查集，本来都忘了，还好复习了一下，然后就是博客今天算是正式发布第一版，该有的功能都有了，明天把数据库整理一下，算是第一版部署的sql，保留结构sql就行，内容的全删了。', '2021-12-21', '2021-12-22 00:25:36', '2021-12-22 00:25:36', 1);
INSERT INTO `blog_diary` VALUES (650, 1, '中秋节，又开始玩群星了。', '2021-09-21', '2021-09-22 00:52:04', '2021-09-22 00:52:04', 1);
INSERT INTO `blog_diary` VALUES (651, 1, '差点忘了写日记，还好想起来了，今天其实啥任务没做，上午弄了弄git把下一个要做的项目代码弄好了，下午就是在等下班，主要是代码已经通过邮件发出来了，我也不想再去修改，然后再发送，所以就啥也不想做，剩下的时间差不多算是学习吧，想了想vuex该怎么分文件，echars图标之类的，还计划博客要弄一个关于读书笔记的这么一个功能，晚上回家在楼下又遇到俩只小猫，顺手就喂了俩根猫条，结果这俩只小猫还是不让我摸一下，明天大周，今晚稍微迟点睡觉，不过这epic真慢啊，领个游戏磨磨唧唧的。', '2021-10-29', '2021-10-29 23:48:40', '2021-10-29 23:48:40', 1);
INSERT INTO `blog_diary` VALUES (652, 1, '肝帝竟是我自己，爆肝星露谷物语，打完了矿洞，到冬天了，还是不太会玩。', '2021-10-16', '2021-10-17 02:13:08', '2021-10-17 02:13:08', 1);
INSERT INTO `blog_diary` VALUES (653, 1, '回看昨天的日记，今天相比会用了vuex，并且能够调用单独的api，然后把博客中文章展示的列表和文章详情页面完成了，虽然页面样式不太好看，感觉今天还是有些收获的，然后晚上绕大街走了走，计划晚上整理的博客菜单没有完成，明天一定要把博客管理页面的框架弄好，现在api等请求都会了，剩下的工作靠努力肝就好了。', '2021-10-03', '2021-10-03 23:05:02', '2021-10-03 23:05:02', 1);
INSERT INTO `blog_diary` VALUES (654, 1, '公司最近这个项目也算是完成了，明天去了把那个文档整理一下就可以交付了，然后还有一个声音检测的项目和之前机器人项目的联调，不过明天应该是没什么事情了，能放松一下。博客项目今天是把文章展示的页面css整理了一下。', '2021-11-25', '2021-11-25 23:26:48', '2021-11-25 23:26:48', 1);
INSERT INTO `blog_diary` VALUES (655, 1, '这个周末什么事情都没做，唯一有意义的事大概就是去打疫苗了吧，大概。博客的日记功能想要修改一下，然后就是小功能想要增加一个照片墙的功能，大功能想要弄一个运动展示的这么一个界面。租房这边打算搬到这几天才搬走的那个租户的房间，跑步的话准备以后开始晨跑，一是因为夜跑没有合适的跑道，再就是晨跑是不是空气不太好啊。', '2021-08-29', '2021-08-29 22:15:40', '2021-08-29 22:15:40', 1);
INSERT INTO `blog_diary` VALUES (656, 1, '今天没有分配任务，然后我问导师，问主管都不回复我，所以我就开始了写博客，这绝对不是因为我想写博客才写的，只是因为闲的没事干了，不知道明天会咋样，等等早点睡觉，等衣服洗完。', '2021-10-25', '2021-10-25 23:51:56', '2021-10-25 23:51:56', 1);
INSERT INTO `blog_diary` VALUES (657, 1, '补日记，昨天玩浮岛物语太晚了，本来想着直接结档，没想到还差挺多东西的。', '2021-12-25', '2021-12-26 10:51:44', '2021-12-26 10:51:44', 1);
INSERT INTO `blog_diary` VALUES (658, 1, '今天没什么可写的，就是累，博客项目完全看不懂，再就是社保信息有了但还是没领到补助，洗洗睡了。', '2021-07-20', '2021-07-20 23:08:14', '2021-07-20 23:08:14', 1);
INSERT INTO `blog_diary` VALUES (659, 1, '8月2日，今天公司也没有任务，学习了redis但没写笔记，博客开始了日记功能的实现，博客按照文章类型分类基本完成，差最后一个不会实现，这周就慢慢实现吧。', '2021-08-02', '2021-08-02 23:37:40', '2021-08-02 23:37:40', 1);
INSERT INTO `blog_diary` VALUES (660, 1, '今天开始第一个代码任，但感觉啥也不会，主要是那个代码框架不是spring看着有些吃力，最近跑步倒是非常有感觉，今天一公里破纪录（5分31秒），五公里破纪录31分02秒，然后就是手环和摄像头回来了，今天也搬到了小房间，虽然房间小，但还挺舒适的，唯一缺点就是用电不太方便，价格也实惠才1100，今天因为搬家没能早睡，唉。', '2021-09-02', '2021-09-02 23:31:22', '2021-09-02 23:31:22', 1);
INSERT INTO `blog_diary` VALUES (661, 1, '今天也是肝帝的一天，玩到了第二年，因为没干什么事情，所以日记就一句话吧。', '2021-10-17', '2021-10-17 23:25:36', '2021-10-17 23:25:36', 1);
INSERT INTO `blog_diary` VALUES (662, 1, '昨晚玩缺氧忘了写，第二天早上补日记。昨天在公司接到了新的任务，主管说要让我先看代码，我也不知道具体要我做什么，然后就是收到了要准备转正答辩的ppt了吧，昨天下班早周三我五点半就走了，然后博客昨天弄好了文档页面展示的样式，暂时只是先把markdown导出的样式弄好了，之前一直都是纯文字排版，现在至少看着不会太难受，然后就是新加了一个v-md-editor的插件，这个有中文文档，应该会舒服一点，还有marked，不过暂时没发现这个有什么作用，最后就是昨晚玩的缺氧现在30周期了，好像昨天多玩了几个周期，目前已经到了第二个星球，但并不打算双线程开始游戏，只是先过去看看，今天应该可以完成气压服。', '2021-11-17', '2021-11-18 08:02:32', '2021-11-18 08:02:32', 1);
INSERT INTO `blog_diary` VALUES (663, 1, '今天计划的整理博客文档服务端代码完成了，博客发送邮件应该是在公司发送不了，ping邮箱smtp.qq.com都没有相应，明天回家做这个，然后明天加班去了还没想好要干啥，博客应该是明天不会写，可以看看别的，最近追番弃了好几个，暗杀者已经没救了，完全变成后宫番了说好的战斗番呢？还有慢生活那个应该还要看，只不过最近在看日常，之后再说，晚上在家想玩缺氧来着，一直给我出黑洞，卸了好几次可算是好了，那个minibase的mod也不能用了，实在是太可惜了。', '2021-12-17', '2021-12-18 00:27:38', '2021-12-18 00:27:38', 1);
INSERT INTO `blog_diary` VALUES (664, 1, '今天答辩结束了，感觉总体还行吧，就是因为我是最后一个问了不少问题，还有几个我也不太清楚，最近在看日常（动漫），今天还是没啥想写的，go语言使用echo框架也没什么进展，现在也没解决MySQL的insert语句要怎么做一个通用的方法，今天把答辩的草稿粘上。各位评委老师好，我是软件开发部-能源组的李新侃，入职时间是在今年的七月份，目前任职的岗位是助理应用软件工程师，我的导师是陈梦燕导师。本次答辩我主要从以下几个方面讲解，首先要介绍我的个人资料，然后对试用期个人业绩重点产出和试用期个人业绩达成分析进行详细讲解，最后就是对试用期这段时间的总结，以及未来的一些计划。首先是个人资料，我毕业于黑龙江大学软件工程专业，大四期间我自行参加了招聘，入职北京市东方国信股份有限公司实习了8个月，在实习期间我主要负责当时项目的接口开发和服务器维护相关的任务，积累了大量的工作经验，之后因为回校准备毕业设计离开了当时实习的公司。在大华实习期间我主要参加了以下项目的开发，这里最早的日期是8月31，是因为之前参加的项目没有进行统计，或者没有明确的文档。首先是动环子系统一卡通子系统数据库信息表格整理这个任务，这个任务目标很明确，就是把这俩个系统的sql数据库表整理到文档之中，因为把数据库表格中的字段以及字段类型等数据整理到表格只是一个简单的重复任务，我当时就使用了python脚本对数据库字段进行了整理。下一个项目是山东省枣庄市枣矿矿灯项目，这个项目需求是对矿灯在线数、总数、和故障率进行统计，还有要在编辑设备页面添加矿灯这个设备分类和设备是否故障选项，这个任务数据查询这几个接口并不是很难，而是要在设备页面添加矿灯选项和勾选故障遇到了问题，事后分析主要还是在前端代码这块不是很理解。Java开源漏洞修复这个任务就是把项目中用到的一些依赖包版本升级，主要就是找到之后修改版本即可。智慧能源综合业务平台对MySQL数据库和接口逻辑优化，这个需求有俩个任务，一个是对数据入库进行过滤，比如某时间段一个设备一直在在线和离线状态切换，如果要是把这些切换的数据都计入数据库不仅没有意义而且还浪费存储空间，所以需要对这些没用的数据进行过滤，还有一个任务就是我数据库中存放的数据并不是永久存放，我可能只保存最近几个月的数据，所以需要写一个存储过程，数据库中表以月为单位存放数据定时删除超过设定日期的数据。接下来是icc新服务器的测试，这也是我做的第一个测试任务，总体来说我做的这个测试工作比较简单，按照文档的操作流程查看界面功能是否符合预期结果。机器人项目应该是我做的最复杂的一个项目了，在这个项目中我主要负责对机器人平台和上级平台数据传输的桥梁，虽然不涉及太多的业务逻辑，但是需要对上下级协议文档阅读到位，要把机器人传输上来数据和上级平台需要的数据字段对应，还有一个难点就是怎样和上下级建立联系，和上级是使用的ice框架，虽然在项目进行时对这个框架有一些学习，但是在开发过程中主要还是依靠导师帮我完成的，和机器人是使用的netty框架，这个框架因为在之前有学习过，所以开发过程中遇到的问题相对较少。最后这个南通水利抓图项目和钢铁厂的项目稍微详细一点，因为在之前中期评审中发现我对项目需求转化成开发任务这方面能力比较欠缺所以这里就分析一下这俩个项目的项目需求：先看这个南通水利的项目需求，原始需求是：需要对标黄的车辆进行上报，上报报警数据，报警图片，车牌，报警时间，地点为设备名，推送信息上报给第三方平台或者提供接口由对方来取，在实际开始实现时最终决定使用提供接口供对方来取数据，所以这一条需求就是一个简单的查询接口；然后下一条需求：对特定通道进行定时抓图，时间间隔暂停3小时，抓拍的图片保存在平台中心存储，~~~后面的ppt上都有，临时发挥吧  果然是有史以来最长的一篇日记。', '2021-12-09', '2021-12-09 23:24:14', '2021-12-09 23:24:14', 1);
INSERT INTO `blog_diary` VALUES (665, 1, '明天准备去富阳工厂，要当拧螺丝工人了。', '2021-08-19', '2021-08-19 23:31:06', '2021-08-19 23:31:06', 1);
INSERT INTO `blog_diary` VALUES (666, 1, '睡觉一天，上午10点起床，下午又睡一觉，晚上出去理发，今天顺便把腾讯云服务器的系统软件弄好了，果然写博客还是有必要的。', '2021-09-19', '2021-09-20 00:45:30', '2021-09-20 00:45:30', 1);
INSERT INTO `blog_diary` VALUES (667, 1, '今天把图床弄好了，这下写博客可以在我的网站上面写了，公司把那个修改页面的也提交了，下午在看算法约瑟夫（Josephus）问题这个问题，想了一下午没明白那个递推公式怎么得出来的，还有就是递归怎么写成循环的，看到了的算法10亿都是一秒钟的事情，我写的6w爆栈了，还得好好学算法。晚上回家都不让休息，还看现场的问题，直到11点都没解决。刷完牙回来感觉还能写一点，最近可能是手冷，不想多写，今天看完了日常和无职转生，都是非常不错的动漫，其它的番也没个特别想追的，又到了番荒的时候。', '2021-12-23', '2021-12-24 00:40:12', '2021-12-24 00:40:12', 1);
INSERT INTO `blog_diary` VALUES (668, 1, '今天完成了博客的文章分类功能，感觉实现的还是挺顺利的，也没遇到什么大的问题就完成了，明天计划把博客的写文章功能再完善一下，然后就是下载xshell，希望能找个免费的吧，顺便保留好安装包。感觉最近写日记都是在应付，每天写一点点就没了，而且都没有把主要的事情写上去，昨天看完了致不灭的你，感觉动漫整体还挺好的，甚至有点感动，唯一不好的地方就是太多刀了，本来挺喜欢的一个角色一会就没了，今天在看上课小动作，一集就五分钟，实在不够看啊。最后就是跑步了，因为有点膝盖疼，大概快半个月没跑步了，手腕也一直没好，希望能快点好吧，等下周试试你不能跑步。', '2021-10-09', '2021-10-09 23:15:04', '2021-10-09 23:15:04', 1);
INSERT INTO `blog_diary` VALUES (669, 1, '今天公司任务大概是完成了，就剩一个data数据类型转byte[]的一个数据不能接收然后转发，其它的功能都测试完成了，明天看可以考虑考虑怎么发送，网上也没有这个类型的讲解，偶尔找到一个还是因为date写错了，真气人，明天研究一下把，不然就没事干了，博客昨天不是弄完了vuex的分文件嘛，今天就把博客中调用接口的地方修改了一下，现在博客可以正常访问了，之前后台管理一直有一个第一次打开个人信息无法展示的bug，今天排查发现是因为用户名从vuex中取数据发生了错误，修改之后就没问题了，然后今天晚上还查了查为什么我的博客管理页面刷新会出404的原因，暂时我认为是vuex在刷新的时候会清空数据，所以导致我缓存在vuex中的动态路由就被清空了，然后找不到路径就报404错误，之后这几天看看怎么解决这个bug。然后就是最近看了好几部动漫有暗杀者、无职转生、慢生活、国王排名还有神薙，因为都是追新番没什么看的所以就追了这么多，以后就不限制追动漫的数量的，但是12集的动漫至少要看三天，大概就写这些吧。', '2021-11-09', '2021-11-09 23:42:54', '2021-11-09 23:42:54', 1);
INSERT INTO `blog_diary` VALUES (670, 1, '今天继续admin的任务，结果啥也没做成，打算再看一次jvm书，之前看的那本pdf应该还在，不知道要不要买实体书。自行车补胎拆开发现车胎没问题，打气口掉下来了，只能再买一个新的内胎。今天还看到了好多早上不吃饭跑步猝死的，我害怕了，以后早上依旧早起，不过要做一下瑜伽之类的，还有练肌肉。', '2021-09-10', '2021-09-10 22:54:12', '2021-09-10 22:54:12', 1);
INSERT INTO `blog_diary` VALUES (671, 1, '今天日记早点写，先记录博客进度吧，因为工作也没什么任务。博客今天完成了角色和用户的页面，暂时没什么问题了，在角色页面增加了点击禁用的开关，然后下一步打算继续修改博客分类标签的页面，把之前设计的表格改成树形表格，这样看标签也方便，再增加一个每个标签有多少文章的数据，然后就是处理博客前端页面的展示了，虽然现在也能用，但是不够美观，所以计划中还是要修改的，公司任务今天差不多是没有进度，主要是测试服务器今天一直没弄好，所以我才有时间写博客，今天学习了vxe-table，使用体验比element的表格强太多了，虽然我还不是很熟练。今天李超凡发的那个es6说是可以解决vuex按模块分文件的问题，但是也没看，不过还是先记录一下，vuex的index分文件也是必须要做的事情，现在就感觉index的文件内容太多了，但还是要缓一下，我想尽快把博客2.0的部署完成，最近也没怎么写博客。', '2021-10-27', '2021-10-27 22:46:42', '2021-10-27 22:46:42', 1);
INSERT INTO `blog_diary` VALUES (672, 1, '爆肝一天游戏，霓虹深渊和浮岛物语，今天早点睡觉。', '2021-11-27', '2021-11-28 22:56:10', '2021-11-28 22:56:10', 1);
INSERT INTO `blog_diary` VALUES (673, 1, '我现在非常生气，epic啥破服务器啊，游戏不能离线模式开启，我tm有网，连不上你那破服务器，连上还一会就掉，就算掉了，弄一个离线启动模式也行啊，啥也有没有，本来想买的游戏都不想在epic\'上买了，来气，一晚上了古墓丽影都没玩上，一开始开了，选了那个中文语言结果不知道为啥变成了韩语，弄了一晚上，重启一次就要等sb epic连半天服务器，还连不上，我tm就要弄一个epic游戏在steam里面启动的插件。消消气，今天在公司新修改了一个接口，是用来查看角色数据的，把新加的组织代码也查找出来，剩下的就是在公司摸鱼了，今天看了一个新的算法，题还是昨天那个，今天用了prim算法做了一次，不过这个算法当时理解了，代码怎么编写还没有熟悉，晚上稍微加个班把这周的算法题整理了一下发回家里，最近收到了公司的新年礼物，虽然不怎么样，但都是免费领的也不能说些什么，现在已经开始休元旦假期了，有三天，希望这个假期稍微做点有意义的事情。', '2021-12-31', '2022-01-01 00:01:04', '2022-01-01 00:01:04', 1);
INSERT INTO `blog_diary` VALUES (674, 1, '今天一天没有写博客功能，上午导师给拉下了代码，讲解了代码里面的一些功能的实现，下午又让自己去尝试加个展示标签，前端页面那个我完成了，可是后端修改的那部分修改完成一直没有成功部署到服务器，不知道是什么原因，本来服务器上面那个war包没有问题，我重新部署几次都可以正常运行，自己提交上去的即使不修改也没办法启动，应该是配置的问题吧，等明天去了看导师怎么处理。今天晚上我把服务器账号注册的那个完成了，并且发布到服务器上面，用户注册之后可以在自己的邮箱里面确认，并点击激活，下一个功能就开始实现博客分类标签的功能吧，希望不会太慢，个人预计2周左右吧，因为最近可能没办法在公司干活了。', '2021-07-27', '2021-07-27 23:27:24', '2021-07-27 23:27:24', 1);
INSERT INTO `blog_diary` VALUES (675, 1, '今天就开始了公司的学习计划，第一天搭建完成了spring boot项目，整合完成了mybatis，下午就去总部参加论坛，虽然我只是个咸鱼听各种大佬发言。', '2021-08-10', '2021-08-10 23:36:20', '2021-08-10 23:36:20', 1);
INSERT INTO `blog_diary` VALUES (676, 1, '今天回家了，收到了公司送的葡萄。', '2021-08-27', '2021-08-27 23:06:32', '2021-08-27 23:06:32', 1);
INSERT INTO `blog_diary` VALUES (677, 1, '今天开始了小游博客的学习，后端结构很清晰，主要是前端不是很明白，今天晚上搞明白了博客前端应该是通过this.$store.dispatch调用vuex的actions异步方法，具体细节明天再研究，现在短期目标应该是把小游博客弄到vue3里面去，之后再弄接口，数据库还没想好用哪个，不过应该还是MySQL，毕竟换数据库代价有点大，也有可能俩种数据库都使用，走一步看一步吧。', '2021-09-27', '2021-09-28 07:28:48', '2021-09-28 07:28:48', 1);
INSERT INTO `blog_diary` VALUES (678, 1, '今天部署博客出了点问题，也不知道为什么一直访问不到接口，本地测试就没问题，看来要留到之后博客完成在测试寻找了，今天也没有打泰拉瑞亚，感觉有点无聊，晚上看比赛，不知道edg会咋样。', '2021-10-31', '2021-10-31 23:37:00', '2021-10-31 23:37:00', 1);
INSERT INTO `blog_diary` VALUES (679, 1, '周日，自然是玩游戏了，今天浮岛物语差不多快接档了，想着明天上午调休，但是明天早饭必须吃，所以就算了。', '2021-12-19', '2021-12-19 23:06:30', '2021-12-19 23:06:30', 1);
INSERT INTO `blog_diary` VALUES (680, 1, '昨天晚上打游戏上头了，艹。玩了一晚上都没赢一把，中午刚刚起床补写昨天的日记，昨天在公司学习了ActiveMQ，也没做其它事情，这周预计三篇博客，Mybatis的总结再写一下，然后就是新开ActiveMQ的学习记录，博客网站的话尽量完成博客分类功能。', '2021-07-30', '2021-07-31 11:57:16', '2021-07-31 11:57:16', 1);
INSERT INTO `blog_diary` VALUES (681, 1, '今天参加了软研青苗计划的结业典礼，其实就是一个团建，上午玩了三个游戏，下午就一个去各个地点打卡的活动，没想到我们组居然卷到了第一名，喜提1k团建基金，上午游戏印象最深的感觉还是那个毛毛虫，因为是第一个玩的游戏，而且感觉也挺好，中午吃完饭看了看羊驼，也是第一次看到，下午就在湘湖度假区看了看，流水账文章，不想写了，丢人。', '2021-10-23', '2021-10-24 01:23:40', '2021-10-24 01:23:40', 1);
INSERT INTO `blog_diary` VALUES (682, 1, '昨天忘了写日记，只好第二天补，昨天把博客的导航页面弄好了，因为放假，就没做什么事情，再就是自行车前胎爆了，去补胎因为着急，结果补好又开了，果然这东西也是需要学习的，并不是有手就行。', '2021-09-30', '2021-10-01 23:38:54', '2021-10-01 23:38:54', 1);
INSERT INTO `blog_diary` VALUES (683, 1, '周一上班早上打卡系统出了点小故障，还好我每次打卡之后都会看看有没有成功，发现了这个问题。今天学习了...好像没有学习，下午算是看了看servlet但是没有看明白，还查了一下jdk和sdk的区别，简单说jdk算sdk的一种，不过应该写一个博客记录一下（再次挖坑），下午吃饭之前以及晚上加班给同事解决bug顺便我也安装了redis（我觉得redis安装过程也有必要记录一下），等redis安装完成我用服务器测试了几次发现安装没有问题了，然后就开始与springboot整合，直到晚上才弄完成，原来是redis没有密码无法远程连接，添加密码之后使用我的小demo测试，顺利添加了数据，顺便还给自己本机下载了redis，也成功连接到了服务器。之后就开始学习hexo打算找一个hexo的模板美化一下我的博客，准确的来说是抄袭一个，但是最后也没找到一个喜欢的主题，就放弃了hexo转向vue框架，有幸发现一个大佬的博客http://www.mangoya.cn/#/Home，star了，计划明天上午分析一下大佬的博客页面，并以此修改自己的博客，然后将此博客vue版本升级到3.0，感觉这次修改比较大，可能要放弃之前博客1.0时的预计实现功能了，不过这几个功能要在新版本的博客上要有体现，预计完成时间应该在8月中旬吧，vue3.0要学，希望和2.0变化不大。明天下午就...不知道该学啥，啥也不会看也看不懂，首先就从项目开始吧。', '2021-07-19', '2021-07-19 23:17:22', '2021-07-19 23:17:22', 1);
INSERT INTO `blog_diary` VALUES (684, 1, '今天的admin任务还没有完成，不过截至下周三，还有时间。现在学习计划有变，想了想还是好好学习Java别的语言先不考虑，毕竟是靠Java吃饭的，然后就是各种数据库等中间件要学习，明天要按这个制定计划。今天去江边跑步，第一次五公里进入30分钟以内（28分14秒，继续加油，明天跑六公里），然后就是晚上回家要做俯卧撑，明天开始，今天没做几个，俯卧撑标准5个，深蹲30个，其它明天再想。', '2021-09-09', '2021-09-09 23:20:24', '2021-09-09 23:20:24', 1);
INSERT INTO `blog_diary` VALUES (685, 1, '又是一次凌晨写的日记，不过今天还是有原因的不是我单纯的熬夜。首先呢，就是上午组内唱歌练习，一首张震岳的《再见》啊，中午就简简单单的吃个午饭下午继续练习，虽然我也没多少歌词，但还是有那么一点点的紧张，然后就是晚上的晚会了，大家的节目都非常棒，都有点意料之外的感觉，印象最深刻的还是七组小姐姐的辣舞，虽然我看不啊懂，但我大受震撼，可惜啊最后冠军还是我们组，晚会结束后我去跑步，然后被队员叫去一起分享冠军的喜悦（指聚餐吃饭）。不行了，就算是今天生活比较丰富，我还是写不了2K。明天是上流水线实习的第一天。加油，打工人。', '2021-08-22', '2021-08-23 00:18:46', '2021-08-23 00:18:46', 1);
INSERT INTO `blog_diary` VALUES (686, 1, '昨天说的任务今天明确了，不是我当时想的那样，只是改一下数据的存储方式，对数据insert的时候稍微处理一下，还需要使用定时任务，明天学习一下，尝试用到我的博客里面，今天大概就这样吧，买的裤子太难穿了。', '2021-10-19', '2021-10-19 23:40:26', '2021-10-19 23:40:26', 1);
INSERT INTO `blog_diary` VALUES (687, 1, '今天周一之前那个任务完成之后还没有给新的任务，所以今天就整理了之前的项目代码和博客，先说公司项目的整理吧，之前那个项目用到了netty和ice，因为ice用到的比较少所以打算先整理netty，ice等之后写个笔记就行，整理netty我先建立的客户端和服务端，今天把netty服务端和客户端连接成功了，但是不知道为什么收不到客户端发送的消息，等明天去了在仔细看看，然后博客今天完成了登陆页面的设置功能，后端也写了可以设置每一个页面的设置，还有就是从今天开始打算把博客doc做出来，今天弄好了doc前端页面的展示，之后就是做doc在管理页面的的编写功能，可能又要费点时间吧，手机app端还得再等等。', '2021-11-15', '2021-11-15 21:43:44', '2021-11-15 21:43:44', 1);
INSERT INTO `blog_diary` VALUES (688, 1, '最近还挺忙的，今天把netty连接机器人调试通了，然后又看了看业务，但是业务没实现，明天应该是去把业务弄好，不过到时候再说吧，现在还没有思路。再就是最近看到了一款游戏挺好玩的，叫浮岛物语，等打折入手。', '2021-11-02', '2021-11-02 23:03:34', '2021-11-02 23:03:34', 1);
INSERT INTO `blog_diary` VALUES (689, 1, '今天博客部署更新，也是玩群星的一天。', '2021-09-25', '2021-09-25 23:57:22', '2021-09-25 23:57:22', 1);
INSERT INTO `blog_diary` VALUES (690, 1, '不得不说今天啥也没干，计划推迟一天，上下午都睡觉了，结果晚上睡不着。', '2021-10-07', '2021-10-08 00:10:36', '2021-10-08 00:10:36', 1);
INSERT INTO `blog_diary` VALUES (691, 1, '今天主要是写答辩的稿子，不然害怕到时候紧张一下全忘了，机器人测试那边也做了一点，发现一个bug不过已经修改完成了，晚上和领导一起喝酒，虽然我只是陪领导喝，今天还好鼓起勇气和导师喝了一杯，也算没有遗憾吧，就是因为我酒力不太行，喝完就吐了，晚上早点睡觉。', '2021-12-07', '2021-12-07 22:42:40', '2021-12-07 22:42:40', 1);
INSERT INTO `blog_diary` VALUES (692, 1, '一整天上了八节课，每节课一个小时，比上班还累，卧槽。', '2021-08-17', '2021-08-18 00:06:24', '2021-08-18 00:06:24', 1);
INSERT INTO `blog_diary` VALUES (693, 1, '今天缺氧、泰拉瑞亚和云顶之奕都玩了好久，晚上也没吃饭。', '2021-11-21', '2021-11-21 23:57:38', '2021-11-21 23:57:38', 1);
INSERT INTO `blog_diary` VALUES (694, 1, '今天学习ActiveMQ没看明白，明天上午继续，但也想继续博客。博客最近日记功能有点眉目了，尽快完成，博客权限管理也想快点整完。今天没学新知识，就记录博客进度，今天晚上刚刚把tinymce整合进博客，有些小bug明天修复。', '2021-08-04', '2021-08-04 23:52:06', '2021-08-04 23:52:06', 1);
INSERT INTO `blog_diary` VALUES (695, 1, '电子厂打工记，今天是进厂的第一天，上午完成了http培训的考试，然后下午一点坐车到了富阳，进厂找到了宿舍，虽然一个宿舍有六个人，但凑合住几天还行吧，下午没啥事情，收拾完成之后去外面跑步，虽说是五公里，但路上水太多，走了好长一段路。然后就是旁边看到了富春江（应该是吧），到了晚上就练习唱歌，我只能说我唱的真TM难听。今天走路算是比较多的总共2w步+。', '2021-08-20', '2021-08-20 23:20:22', '2021-08-20 23:20:22', 1);
INSERT INTO `blog_diary` VALUES (696, 1, '今天的日记失误覆盖了，并且没有备份，，因为是覆盖的，所以没有办法恢复，我操。', '2021-11-29', '2021-12-01 00:13:08', '2021-12-01 00:13:08', 1);
INSERT INTO `blog_diary` VALUES (697, 1, '今天周日，今天的日记算是一周总结吧，不过还是先记录今天做了些什么事。首先上午把新旧博客都调整了一下，以后旧版博客页面保留，但是前台展示博客页面可能不会再更新了，后台管理系统还是需要的，写博客就在旧版的管理系统，查看以及展示就使用新版的博客，下午写了mybatis笔记的第二篇，感觉写的还是很慢，带上功能的验证，写代码加博客发送用了好几个小时，之后对新版博客的注册功能修改了一下，现在博客注册需要输入自己的邮箱，然后我发送验证码，从邮箱中激活才能使用注册的账号，具体发送链接还没有实现，不过发送邮箱的功能已经完成，接下来的工作应该不会很难了吧。最后就是这周周末的计划应该是完成了吧，对博客功能的实现、以及周末写两篇博客都做到了，唯一可惜的就是这周有台风（烟花），这周没有跑步。', '2021-07-25', '2021-07-25 22:05:20', '2021-07-25 22:05:20', 1);
INSERT INTO `blog_diary` VALUES (698, 1, '今天一天啥也不想干，好几个周末没有写文章了，笔记也没有看。', '2021-09-12', '2021-09-12 21:30:18', '2021-09-12 21:30:18', 1);
INSERT INTO `blog_diary` VALUES (699, 1, '一不小心玩缺氧又不早了，今天上班啥事没做，之前那个项目还没完成，又要给一个新的测试任务，就离谱啊，缺氧新开档了，之前那个因为一直拖，都没水了，制氧炸了。', '2021-11-20', '2021-11-21 00:43:42', '2021-11-21 00:43:42', 1);
INSERT INTO `blog_diary` VALUES (700, 1, '今晚打的霓虹深渊恶心爆了，尼玛玩啥不来啥，操。公司今天还是没有任务，就偶尔过去看看机器人的日志，博客今天开始弄文章列表无限滚动的方式，之前页面刷新404的bug还有，上次修复只是掩耳盗铃，注释了，这周想想办法。', '2021-12-20', '2021-12-21 00:17:04', '2021-12-21 00:17:04', 1);
INSERT INTO `blog_diary` VALUES (701, 1, '周五忘了写日记，今天周一开始补上，顺便还有周六和周日的，周五做了啥事已经忘记了，好像是弄设置功能，但应该是没弄好，然后因为是大周，回家就玩游戏，啥也不记得了。', '2021-11-12', '2021-11-15 20:56:40', '2021-11-15 20:56:40', 1);
INSERT INTO `blog_diary` VALUES (702, 1, '9-8早上写，昨天忘了写日记，今天早上补上。昨天上午参见N8000产品的培训会，感觉还是有点看不懂架构，不过没关系，系统慢慢熟悉，下午看go语言的echo框架，echo的web接口是真简单呐，比springboot的方便，不过主要还是学习spring，echo框架弄完还看了看mongodb，甚至还想继续看nginx，感觉想学的太多了，今天去了公司做个计划，不然真不知道该看啥了。', '2021-09-07', '2021-09-08 07:46:58', '2021-09-08 07:46:58', 1);
INSERT INTO `blog_diary` VALUES (703, 1, '今天ice的连接还没有成功，因为昨天晚上看动漫（月光下的异世界之旅），今天就看完了，因为这次看动漫太快，导致一整天都很累，所以决定12集的动漫要分三天看完，工作就不仔细说了，各种尝试ice的连接都没有成功，晚上把博客图片上传弄好了，但是因为我设置没弄好不能访问本地图片，明天摸鱼的时候把前端改改，然后写好图片的删除方法，剩下的还没想好，到时候再说。', '2021-11-04', '2021-11-04 23:16:46', '2021-11-04 23:16:46', 1);
INSERT INTO `blog_diary` VALUES (704, 1, '放假真好啊，又玩到了现在，不过今天都按时吃饭了。今天睡到了中午，下午陈嘉容问杭州大学生补贴的事情，不过我也不清楚，晚上下棋，缺氧都玩了。', '2021-12-11', '2021-12-12 01:20:04', '2021-12-12 01:20:04', 1);
INSERT INTO `blog_diary` VALUES (705, 1, '今天完成了博客后端管理的界面，顺便完成了博客文章的页面，都是新的ui，剩下的工作都是重复的，明天打算肝完博客后端管理的剩余功能，应该都是些重复的工作了吧，可能角色管理页面费电时间，但应该问题不会很大吧，大概。然后就是最近看了好多动漫，打算以后在日记中记录近期看的动漫，比如什么时候开始，什么时候看完之类的，就从今天开始：今天看了幼女战记，没有看完，昨天看的86-不存在的战区，因为没有完结，这个也没有看完的日期，10月2日--10月3日看的东京卍复仇者，看完了我tm真来气啊，男主没有一集不哭，但是女主感觉还行，总来说这个动漫我不是很喜欢，然后就是之前看的见面五秒开始战斗（也是在国庆假期看的）这个动漫前期还行，到后面我感觉有点失望，总体还算凑合吧。最后就是小林第二季了，京都动画吹爆，复出之后的第一部动漫就这么好，期待之后的作品，这些就是国庆到现在看的全部动漫，然后再给自己定一个规矩，就是12集的动漫绝对不能一天看完，至少要看俩天。', '2021-10-04', '2021-10-05 00:07:36', '2021-10-05 00:07:36', 1);
INSERT INTO `blog_diary` VALUES (706, 1, '今天一整天都在部署服务器测试，现在这个任务的版本依赖会改的都已经改完了，现在就是剩下一些修改完会有bug的依赖，然后就是要部署看看修改完成之后能不能正常运行，今天就测试了一个admin的代码，明天再努力吧，晚上开会都提到了这个事情，希望这次我能不影响大家的进度。', '2021-10-13', '2021-10-13 23:37:36', '2021-10-13 23:37:36', 1);
INSERT INTO `blog_diary` VALUES (707, 1, '周一，也是开始拧螺丝的第一天（本以为是开玩笑的话，没想到真的有拧螺丝的任务），分到了前端工厂的某流水线，上午就是检验前面人组装任务是否合格，下午和旁边的人换了下任务，感觉这一天还是还是挺累的，以至于晚上上课都睡着了，然后就是夜跑甚至五公里都懒得跑了。总之这流水线不是人干的活，这辈子都不可能再来的。', '2021-08-23', '2021-08-23 22:44:40', '2021-08-23 22:44:40', 1);
INSERT INTO `blog_diary` VALUES (708, 1, '暑假的最后一天，往年这个时候应该在补作业吧，哈哈。今天完成了导师给的一个小任务，把数据库中的表格整理到word文档中，本意是要我熟悉一下项目的数据库结构，结果却被我直接弄个脚本整理完成了，最后还被导师表扬你咋这么快。今天主要是弄python脚本的事，以为公司有内网，所以下载一些包都很费劲，无奈只得请朋友帮忙下载，pycharm安装完成之后，下载一些项目所依赖的包也是一个问题，最后在公司的研发论坛网站上找到了相关的解决方案，果然论坛是个好东西，所有配置都弄好之后开始写代码，主要实现的功能是通过输入的MySQL建表语句提取关键字，将其中的字段、字段类型以及描述提取出来写入excel表格中，然后我通过手动整理将表格整理好写入文档，在写的过程中发现写文档其实一直都在重复一个过程，每个表格都一样，所以计划开发一个sql语句转文档的脚本，能够实现自定义某几个列名的选择，脚本输入为navicat导出的表结构类型（.sql文件），输出为word文件，虽然是计划制作脚本，但制作完成时间暂定。', '2021-08-31', '2021-08-31 22:15:34', '2021-08-31 22:15:34', 1);
INSERT INTO `blog_diary` VALUES (709, 1, '补日记，昨天晚上又忘记了，今天早上起来开始补日记，昨天一天也没做啥事情，早上起来就十点了，打了会王者荣耀，中午就随便吃了点月饼，下午看丁菊长的七日杀视频，结果又睡了一下午，晚上下载了xshell，然后又不想学习了，打王者一直输，正好也不想睡觉，结果就玩到了半夜三点，还好今天现在不是很瞌睡。', '2021-10-10', '2021-10-11 07:52:04', '2021-10-11 07:52:04', 1);
INSERT INTO `blog_diary` VALUES (710, 1, '今天的工作任务几乎可以忽略顺便摸鱼写博客，又过上了咸鱼的日子，但是白天也意思意思看了看ice和netty数据传递的解决方法，大概是俩个问题，第一个是Data数据类型转byte[]，因为网上几乎找不到有关Data转byte[]的解决方法，所以我也没什么思路，而且在解析xml的文件中有那个Data类型就会报xml解析错误，所以这个一直没有解决，另一个是在xml解析的数据中有一个数据不是单纯的String，而是类似key:value类型的数组结构，我就自己写了一个解析这种字符串的方法，虽然是能解析了，但是如果发送方在内容中加入了我用来解析字符串的分隔符我就会解析错误，还有就是在向ice发送我解析的数据时如果key的名字变了我也无法获取数据，不过这个用json解析也会是一样的问题吧，毕竟key的名字是约定好的，明天就去了尝试用json解析那个content字符串，博客方面今天做了用sessionStorage（localStorage会永久缓存到本地，cookie没试过）缓存vuex的数据信息，经过测试缓存用户登陆信息没有问题，而且多次刷新也能够在页面中加载出用户的相关信息，但是用来缓存用户登陆之后的菜单信息就出现了问题，我一开始以为是以为缓存的语句写错了，所以测试了很多了，结果每次都可以打印出来，所以暂时（不能完全保证）排除了这个原因，所以我猜测是另一个原因--我的动态路由会因为页面刷新而清空数据，这一点也可以在每次刷新/admin/index不会404，而其它页面会进入404页面得到了验证，所以就在晚上回家之后百度确定了vue的动态路由会因为页面刷新而清空，现在也没有其它的解决方法，明天就试试怎样能在页面刷新之后重新加载路由信息。都已经关了，但是还想再写一点，就说说最近看完的神薙吧，总的来说还是挺喜欢这部动漫的，不知道有没有第二季，动漫内容就没必要记录了，就写写感受吧，虽然是06年的动漫（可能是漫画06年动漫08年），但是画风还可以接受，关于动漫整体题材应该是那种校园后宫搞笑类型的吧，后宫类型的动漫我其实是不太喜欢的，就当搞笑类型的动漫来看还是可以的，最后几集明显感受到了经费不足，甚至在卡拉OK那一集直接开始ppt，其实别的都不是最重要的，还得看女主啊，只可惜不是黑长直，其它我也想不到了，差不多就这样吧。再写最后一点点，明天双十一，晚上稍微迟一点睡觉，买个洗衣液和掏耳勺，也不知道为啥非要搞到半夜。', '2021-11-10', '2021-11-10 23:14:50', '2021-11-10 23:14:50', 1);
INSERT INTO `blog_diary` VALUES (711, 1, '有点无聊，不知道干啥，游戏也玩着没劲，早点睡觉了，明天早上起来整理代码。', '2021-12-05', '2021-12-05 22:16:02', '2021-12-05 22:16:02', 1);
INSERT INTO `blog_diary` VALUES (712, 1, '今天玩了一天的泰拉瑞亚，啥事没干，下午说的王者荣耀比赛也没人回话，估计没人愿意打了，晚上修改了泰拉瑞亚的代码，初次试用了dnSpy，完成了泰拉瑞亚自动钓鱼的脚本（不算脚本吧，毕竟是修改了源码），但是有一个小bug，我用来监测钓鱼的那个线程在泰拉瑞亚结束的时候没有给我关掉，导致了正常的退出无法结束游戏，这个bug过几天试试能不能解决。', '2021-08-14', '2021-08-14 23:59:02', '2021-08-14 23:59:02', 1);
INSERT INTO `blog_diary` VALUES (713, 1, '今天项目交付完成了，下午搭建springboot源码环境失败，晚上搭建springboot环境失败。', '2021-09-14', '2021-09-14 23:30:10', '2021-09-14 23:30:10', 1);
INSERT INTO `blog_diary` VALUES (714, 1, '今天公司给了一个任务，但是因为客户那边没谈妥，所以暂时不需要去做，，所以差不多算是没有任务，因为导师要让看业务熟悉产品，结果自己的计划也没好好做，业务也不知道从哪看，今天五点半就下班了，回来通关了霓虹深渊的暴君boss？到8点出去吃饭，顺便去公司白嫖餐补，晚上回来看完了鬼灭之刃。', '2021-12-01', '2021-12-01 23:48:58', '2021-12-01 23:48:58', 1);
INSERT INTO `blog_diary` VALUES (715, 1, '今天把那个中石化的项目提交了，但是导师说要我仔细了解需求之后在确定再提交，晚上也没干自己的事情，应该半个月多了博客一点没看，下午调试的机器人，要先看注册，然后看消息的响应，又是忙忙碌碌的一天过去了，眨眼间都要周三了，日子过得真快。', '2021-12-14', '2021-12-14 23:36:32', '2021-12-14 23:36:32', 1);
INSERT INTO `blog_diary` VALUES (716, 1, '今天把博客后端的代码整理完成了，下一步优化前端vue框架，尽力看看css吧，感觉还是有些难度，下午公司发了奶茶和鹌鹑蛋，又白嫖了，晚上去江边跑步一口气能四公里了，五公里依旧是稳定27分钟左右。', '2021-09-18', '2021-09-19 00:16:42', '2021-09-19 00:16:42', 1);
INSERT INTO `blog_diary` VALUES (717, 1, '这周小周，明天还要上班，今天项目任务算是做了一点点，算了没啥写的，就这样吧，今天晚上缺氧玩了好久主要是下班太早了。', '2021-11-19', '2021-11-20 00:19:40', '2021-11-20 00:19:40', 1);
INSERT INTO `blog_diary` VALUES (718, 1, '今天团建打棒球，就开始练习的时候打了几次好球，之后就打不远了，不过好在我们队伍很强，最后拿了二等奖，太幸运了，第一名也是我们部门，还有中午吃的烤肉自助，因为没烤过，吃的稀碎，还有炉子一直冒烟，呛死我了，中午的烤肉自助就是一个水果自助，全靠吃水果饱的，晚上看edg比赛，本来打算edg能赢一把就行没想到直接夺冠了，好吧是我格局小了，dwg原来也不是不可战胜的，不太早了先睡觉，虽然还有很多要写的。', '2021-11-06', '2021-11-07 01:15:16', '2021-11-07 01:15:16', 1);
INSERT INTO `blog_diary` VALUES (719, 1, '今天回来把浮岛物语差不多要通关了，差一个100w金币的成就，然后在公司改之前那个bug，就是设备通道在线的数量不能超过一个固定值，当时只计算了一类设备的数量，没有计算另外俩类，今天看了看应该是可以加好的，忘了今天上午因为不想起调休了一上午，错过了晨会，早上说了到过年都是大周了，其实我还是想周六过去的，加几天班正好过年调休，可惜了，动漫就最近开始看贫乏神来了，鬼灭之刃第二季，没别的了，暗杀者和另一个看不下去了。又想到些事情，因为epic下载游戏，这个月翻墙的流量全没了...  还有今天做acm的题，有一道一直ac不了，明明就是一个并查集，不知道为什么数字多了就会wa，后面的几个超时我能理解，但那几个wa是啥意思啊，不懂。', '2021-12-27', '2021-12-28 00:01:46', '2021-12-28 00:01:46', 1);
INSERT INTO `blog_diary` VALUES (720, 1, '今天周日一如既往的没动力，把网站发到邮箱睡觉了。', '2021-09-05', '2021-09-05 20:18:42', '2021-09-05 20:18:42', 1);
INSERT INTO `blog_diary` VALUES (721, 1, '今天开始了测试抓图的那个任务，目前抓图计划没问题了，剩下下发dms的任务没有测试成功，不过应该也快了，毕竟晚上找到了失败的原因，博客今天没写新的功能页面，只是把以前写的css样式整理了一下，打算把css全部弄成scss这样看着比较直观，不会那么乱，也可以乘这次整理把css学习一下，然后晚上开了三个小时的新员工中期会议，汇报了下最近的工作，还是对项目不熟悉，业务需求不会转化成功能实现，还有今天总算是把凉宫春日漫长的八月看完了，我吐了连着8集都是一样的内容，水出了新高度，不过每一集的衣服都不一样，这几集勉强合格吧。', '2021-11-23', '2021-11-23 23:46:24', '2021-11-23 23:46:24', 1);
INSERT INTO `blog_diary` VALUES (722, 1, '22号，公司有了新的任务，算是个小的改动，要把页面上的一个输入框弄宽一点，还有之前的一个任务出了bug，不过也不算bug，因为我当时就没做那个在线通道的计算，等这个宽度修改完再说吧，今天的oj我真菜啊，还得努力刷题，今天做了双向指针，昨天做的那个并查集，都写好了笔记。', '2021-12-22', '2021-12-22 23:48:42', '2021-12-22 23:48:42', 1);
INSERT INTO `blog_diary` VALUES (723, 1, '今天就没什么任务，一天就看了看项目，也没啥具体的收获，今天玩了玩星露谷物语，说实话有点好玩啊，之前玩的波希亚时光，因为明天是大周，晚上就没着急睡觉，玩王者荣耀的觉醒之战。', '2021-10-15', '2021-10-16 01:14:30', '2021-10-16 01:14:30', 1);
