INSERT INTO `blog_diary` VALUES (727, 1, '今天上午去了同事那边要了一份学习资料而且是60G的那种顺便参观房子，瞬间感觉我的房子弱爆了。唉，等之后在好好找吧，现在就这样凑合着。下午发表了我的第一篇个人博客，由于我的个人网站还在测试阶段，所以只好先使用csdn记录以下，之后我在搬家。到晚上把我电脑的MySQL版本换到了5.6.51，又碰上了房子灯坏了，今天过得也是马马虎虎吧。', '2021-07-17', '2021-07-17 21:18:14', '2021-07-17 21:18:14', 1);
INSERT INTO `blog_diary` VALUES (728, 1, '今天一天没有出去，在家里弄服务器，本来下午已经弄好了，结果不小心把redis开放到网络，然后就被人攻击了，各种重置redis，然后不得已重新再来一次，现在已经没问题了，然后就没做其他事情，最离谱的是今天就吃一顿饭，我真乃神人也。', '2021-09-20', '2021-09-20 23:54:44', '2021-09-20 23:54:44', 1);
