INSERT INTO `blog_diary` VALUES (737, 1, '今天应该算公司项目应该算没啥事情，改密码的那个昨天就做完了，今天测试的服务器有别人使用，所以我就没测试，到晚上那会去看了下机器人调试，现在稍微能懂一点了，还有下午去吃了生日蛋糕，每次我都是去吃不唱歌。因为今天项目上事情不多我就又开始了博客的进度，昨天说的修改properties配置文件今天弄完了，现在是使用的俩个配置文件，一个是存放一般情况不会发生修改的配置，另一个是用来存放需要修改的配置选项，现在配置弄好了，然后测试发送邮件，结果出问题了，之前都调试没问题的，也不知道为啥，还有就是博客页面上都添加了壁纸设置的功能，今天做的事情还算可以，明天主要调试邮件的发送，还有对doc添加redis缓存，主要重心是后端的优化，当然前提是明天没啥事情。', '2021-12-16', '2021-12-16 23:42:46', '2021-12-16 23:42:46', 1);
INSERT INTO `blog_diary` VALUES (738, 1, '今天还是没有任务，上午把spring boot和ActiveMQ整合弄好了，果然简单，下午做答辩的ppt，顺便听相声，因为今天是周五，就把这周所有的代码都复制回家了，netty、activeMQ和我的博客都有。', '2021-12-03', '2021-12-03 23:49:30', '2021-12-03 23:49:30', 1);
INSERT INTO `blog_diary` VALUES (739, 1, '今天学习了mybatis的一对一、一对多和多对多的查询，明天可以看看分布查询的延迟加载。', '2021-08-12', '2021-08-12 23:48:34', '2021-08-12 23:48:34', 1);
INSERT INTO `blog_diary` VALUES (740, 1, '2022年了，去年的日记放一个文件夹，这是今年的第一篇日记，首先说2022年计划吧，工作暂时没有要离职的打算，今年就好好在大华干活，学技术，这一年一定要加快成长速度，然后就是在今年要把Android的app做出来，稍微定个期限把，今年6月份，差不多6个月开发一个简单的app应该还行把，其次算法也要跟上，在洛谷要打100道题，平均三天一道不算多，其他的想到再写，今天晚上也不早了，下午睡了一觉到晚上不瞌睡，刚刚看了几集饥荒视频，有点想开一个档玩玩了，但是那个泰拉瑞亚还没结束，不打算等李超凡联机玩了，太慢了，还要每次叫他，搞得我就好像求人打游戏一样，还是一个人方便，最后就是今天把这周的博客稍微整理了一下，写了三篇放到了自己的博客网站上，使用体验还是可以的，然后文章页面也行，要改进的地方就展示文章的那个列表，明天继续整理博客文章，收藏了那么多好文章一个都不看，现在已经不早了，估计明天是没有上午了，那就下午吃完饭先整理日常的算法题，之后把csdn上面的文章搬到博客这边，正好我试一下图床的感觉，先前配置好还没用过，到晚上玩泰拉瑞亚，修好刷怪场，之后搞其它建筑，也不着急，今天就这样吧，不早了没心情继续写，去年总结和今年计划再找个时间好好记录一下。', '2022-01-01', '2022-01-02 01:34:10', '2022-01-02 01:34:10', 1);
INSERT INTO `blog_diary` VALUES (741, 1, '今天开发调用算法接口以及相关操作逻辑，没啥可写的特殊事情，好像有了，早上车胎又给爆了，这个内外胎都挂了，买了新的，晚上现在和同事一起打王者，过几天开始王者比赛。', '2022-08-26', '2022-08-26 23:19:36', '2022-08-26 23:19:36', 1);
INSERT INTO `blog_diary` VALUES (742, 1, '黄河鑫业bug太多了，今天就改bug，还有导师说要把ppt大部分都重写，还要修改每个项目对应的那个要求点上，感觉好难啊，计划是今晚写的，但是实在是不想写，只好推迟到明天，就这样吧，先睡觉了。', '2022-11-14', '2022-11-14 23:32:10', '2022-11-14 23:32:10', 1);
INSERT INTO `blog_diary` VALUES (743, 1, '这俩天有点消沉，因为没有回家，所以干啥都没劲，明天一定要振作起来，算法题也要做起来，昨天和今天看了俩部动漫，一个是战斗员派遣中，还有就是棍之勇者了，说实话好黄好变态，不过我喜欢，今天上午还做了第二次核酸，明天还要再做一次，第二天隔离，和合租的大哥一起吃饭，不过一直都是我只管吃，每次都给我做好，还不用我洗餐具，都不好意思了，晚上还得知王鹏也在杭州，和我一样被隔离了，这些好多了，至少在杭州还有认识的人，这算是他乡遇故知了吧，立个flag，明天算法一题，再搞搞博客。', '2022-01-28', '2022-01-28 22:04:44', '2022-01-28 22:04:44', 1);
INSERT INTO `blog_diary` VALUES (744, 1, '小周周日，没有玩游戏，仔细想想好像很久没玩单机了，最近做博客挺忙的，还有这周12道算法大概率的完成不了了，一道题大概一个小时，也要12小时，实在没时间了，今天计划是部署一下微服务的博客但是因为是久违的休息日，稍微睡个懒觉起来就11点了，下午吃饭回来先处理博客接口文档的问题，不使用飞书是因为它没办法导出md格式的文档，我写完接口肯定是要最后放在我的博客里面的，但是因为飞书不能导出md格式的文档，所以以后要版就需要重新写，很麻烦，今天找了几个但都不太满意，所以打算用离线的md格式写作软件来写，保存文件之后也方便搬上博客去，之后新建了一个vue3的项目，这次使用的是vite+vue3+ts，具体细节还要之后在处理，因为vue3实在是不会弄，主要还是参考之前的博客前端页面吧，下午搭好框架之后还整合进来vuex等一些必要的组件，界面还是慢慢来吧，下周主要还是公司的项目，对接ai模块的协议都不清楚，啥字段都不知道，明天找项目经理联系一下ai模块的对接人，大概就这些了。', '2022-06-26', '2022-06-26 23:45:10', '2022-06-26 23:45:10', 1);
INSERT INTO `blog_diary` VALUES (745, 1, '一点了，不过只要我还没睡觉，今天就还是周日，今天除了把衣服都洗干净，还有把哈迪斯通关了，初次之外就没别的了，休息一天果然还是不太够啊。', '2022-11-06', '2022-11-07 00:53:44', '2022-11-07 00:53:44', 1);
INSERT INTO `blog_diary` VALUES (746, 1, '打包是可以了，但是又出现了新的问题，自己做博客前后端还是要学不少东西的，最近杭州大降温，最近实在是太冷了，公司的项目最近做到还行，压力也不是很大。', '2022-11-30', '2022-11-30 23:57:48', '2022-11-30 23:57:48', 1);
INSERT INTO `blog_diary` VALUES (747, 1, '今天博客第二版的后端正式开写了，差不多弄了些配置，其它的逻辑都好说，在第一版的基础上稍微修改就行，还有今天把那个vue项目的前端做完了，其实就是看着文章粘贴，第二版的前端可能要慢点，vue考虑一下使用vue3，算法刷了几道水题，入门的那种，项目就那样，没新的，写的逻辑都乱了，不想写了，睡觉。', '2022-03-28', '2022-03-28 22:58:34', '2022-03-28 22:58:34', 1);
INSERT INTO `blog_diary` VALUES (748, 1, '今天调试完成了所有已有算法的下发，但是没有报警，找那么多人也没一个和我对接，不知道怎么开发了，不过我的任务应该是完成了。', '2022-09-08', '2022-09-08 23:09:32', '2022-09-08 23:09:32', 1);
INSERT INTO `blog_diary` VALUES (749, 1, '周六休息一天，晚上忘记写日记了，不过也没做啥有意义的事情。', '2022-05-28', '2022-05-29 23:48:08', '2022-05-29 23:48:08', 1);
INSERT INTO `blog_diary` VALUES (750, 1, '心情可算是恢复了，上午就正常休息，一觉睡到十点半，起来吃饭做核算，保住我的绿码，下午和旭福去爬宝石山，应该是做错路了，爬到了一个山顶，之后下来准备去另一个山顶然后看西湖，结果走错了路，不小心到了西湖，就没有再返回，西湖旁边坐了一小时，吹吹风看看风景，还是非常的惬意，然后绕西湖走走路过苏堤断桥，之前因为苏堤只有苏小小墓，这次又发现了武松墓，不知道和有其它名人墓吗，每次去都会有新发现。还有还有，今天又满血复活了，那本小说的结局不是很满意，但也就那样了，要是璐瑶也在杭州上班该多好，能一起出去，平时也不至于太孤独，今天能陪我聊聊天也行吧，休息了。', '2022-10-16', '2022-10-16 23:24:28', '2022-10-16 23:24:28', 1);
INSERT INTO `blog_diary` VALUES (751, 1, '昨天(周六补的日记)和占晴调算法几乎没进度，因为周六要我加班昨晚就没心情开电脑了，躺着看看视频，然后睡觉。', '2022-09-16', '2022-09-17 23:25:40', '2022-09-17 23:25:40', 1);
INSERT INTO `blog_diary` VALUES (752, 1, '不懂为啥10.24是程序员节，拿5.12呢还有1.28，3.2，1.6那么多就挑一个10.24当程序员节，不过我倒是无所谓，今天还能早半小时领水果，晚上1199园区有音乐会，稍微去看了一下，不过我可没心情一直看这个，去了领到餐补水果直接开溜，今天澜沧江门禁项目可算是有进度了，门禁现在多通道也可以使用了，短时间应该是没我的事情了，现在主要就专注俩个算法下发的任务，一个是下发ai，另一个下发dms顺带报警信息推送，明天去了计划先完成安工院报警推送的失败重发，也就是一个定时任务的现场，问题不大，还有盈科mqtt的报警推送，这个和没开始看，应该也不会太难，明天还有ai下发的sql修改，然后部署现场，这个今天已经又改一版bug，到现场应该是没太大的问题，小修改调整应该是会有的，不过这个代码完全是我修改的调整也就是看愿不愿意，技术上不会有太大问题，好了，今天就这样。', '2022-10-24', '2022-10-24 23:21:02', '2022-10-24 23:21:02', 1);
INSERT INTO `blog_diary` VALUES (753, 1, '今天几乎没啥症状了，也没发烧，有那么一点咳嗽，晚上打泰拉瑞亚骷髅王一直没打过，本来就很菜的一个boss我打了四次没过，这一定是因为阳了，导致我反应变慢，绝对不是我菜。', '2022-12-24', '2022-12-24 23:22:38', '2022-12-24 23:22:38', 1);
INSERT INTO `blog_diary` VALUES (754, 1, '这个周周六还是很完美的，今天午饭和晚饭都吃了，博客开发今天主要是弄部署，之前加的文件中心之类的今天都一次性部署上去，而且修改shell脚本把nginx部署文件服务器也写进去了，最后也没有问题也不清楚，因为我刚刚启动上，等明天起床之后才知道结果，最近突然想给博客各个模块改个名字，因为部署的时候发现名字好乱啊，这个明天处理一下，最后就是晚上出去吃饭把耳机拉在餐馆了，还好回去找的时候找到了。', '2022-07-16', '2022-07-17 00:06:26', '2022-07-17 00:06:26', 1);
INSERT INTO `blog_diary` VALUES (755, 1, '无事发生的一天，非要写的话算是把囤积好几天的水果吃了一半，实在是吃不了这么多，坏了又太可惜，还有今天是戒电子书的第一天。', '2022-10-20', '2022-10-20 22:56:46', '2022-10-20 22:56:46', 1);
INSERT INTO `blog_diary` VALUES (756, 1, '都钻被窝了才想起来没写日记，就简短的记录下，今天部门又少了很多人，庆幸自己又苟活了一天，今天主要开发用户的权限修改，还有博客文章自动保存也做好了，感觉该有的功能都差不多了，可以部署之后慢慢使用了，明天去主要弄一下数据库，争取发布第一版，显然今天也是摸鱼的一天，摸鱼挣钱最开心了。', '2022-12-20', '2022-12-20 23:20:48', '2022-12-20 23:20:48', 1);
INSERT INTO `blog_diary` VALUES (757, 1, '感叹宇宙之大，人类之渺小，混吃等死又过了一天。', '2022-02-03', '2022-02-03 23:17:12', '2022-02-03 23:17:12', 1);
INSERT INTO `blog_diary` VALUES (758, 1, '这个南通的项目应该是结束了，今天叫导师过来评审完代码，稍微做了下小的修改，要是再大修改时间来不及，具体代码出问题再说吧，到时候再看看哪个地方会有问题，感觉我这样好不负责任，不过我这边测试的也都测试过了，应该是没什么问题，今天把那个代码优化了一下，感觉影响不是很大，明天把代码提交了可能要再测试一次，测试也只能是压力测试我觉得可能会有问题，其它问题不大，总体还行吧，这个项目最烦的不是逻辑啥的不好实现，主要是那个Hibernate用起来太不方便了，还是自己写sql比较习惯，项目进度大概就这些，然后就是微服务的视频今天学习一个小时，进度正常进行，明天要是没其他项目就开始补这个月的算法题和博客文章了，这个月可以试着写几篇刚学习微服务组件的博客，记录一下，以后找起来也方便。补充一下，从明天开始接下来的六天是早睡周，最近有点累了。', '2022-05-16', '2022-05-16 23:13:46', '2022-05-16 23:13:46', 1);
INSERT INTO `blog_diary` VALUES (759, 1, '南通的项目又来了新的需求，不过今天没开始看，明天开始投入，今天下午做了道算法题，虽然是过了，但是我这个方法感觉是碰巧才过的，因为太暴力了，数据稍微换一换就可能会wa，新的解法也想到了，明天休息时间可以试试，不过明天主要还是看任务吧，晚上继续微服务，最近经常看shell，写了几个shell脚本，以后部署微服务shell应该是必不可少的，最近也要学习一下。', '2022-05-24', '2022-05-24 22:53:54', '2022-05-24 22:53:54', 1);
INSERT INTO `blog_diary` VALUES (760, 1, '今天有个朋友阳了，整的我也有点慌，不过应该问题不大吧，我尽量少出门，博客项目今天前端还写不少，我决定了，好看不好看以后不再纠结这个问题了，做出来能用就行，主要放在后端，添加各种各样的功能。', '2022-12-16', '2022-12-16 23:13:36', '2022-12-16 23:13:36', 1);
INSERT INTO `blog_diary` VALUES (761, 1, '玩缺氧上头，睡觉有点晚了。', '2022-07-24', '2022-07-25 00:34:30', '2022-07-25 00:34:30', 1);
INSERT INTO `blog_diary` VALUES (762, 1, '小周周六，去了完成经验库中人员图片数据增删改查的功能，差不多黄河鑫业这个项目的开发就完成了。', '2022-09-24', '2022-09-26 22:58:46', '2022-09-26 22:58:46', 1);
INSERT INTO `blog_diary` VALUES (763, 1, '今天算是有点累了，项目倒是没什么问题，就是找人太麻烦了，因为新增的几个报警类型需要添加分类的编号，问谁都是不知道，最后处理了一天，晚上还拖到9点，其它的没什么事情，不过今天问导师感觉我有点准备的不充分，因为我的代码都没仔细看，就问了，而且还是俩次，以后还是尽量自己看问题，来了快一年了，业务上的事情还是不熟悉，这个也要多看看了。今天dnf脱坑了，我看下日记是什么时候开始玩的，看了一下日记大概是2月25开始玩的，正好一个月，玩dnf的这段时间有时间就挂机，周末经常就是一玩一整天，经常中午还不吃饭，所以我一定要戒毒（毒奶粉，我可没吸毒），这段时间一是没学习，再就是浪费时间，还影响休息吃饭，之后要在周末多看看大佬的课程视频，最近看到spring security大概是看完了，为什么是大概，因为前端没看... 明天先用课程带着的视频测一下我写的全部功能，然后这个周末看完这个视频的前端，主要学习vue的一些，这个视频之后继续vue的教学视频，博客开始第二版的开发，博客现有的功能肯定要全部搬过去，旧版博客代码也留着吧，毕竟是第一次独立开发的成果，虽然都是CTRLcv的，暂时就是这些了之后的计划到时候再说，微信小程序、app、qq聊天机器人都想学习，还有买的单片机（arduino也算是吧）也想玩玩，所以很缺时间啊，dnf戒了是真的不能在下回来了，人家玩的别人都是在校大学生，有的是时间，我这社畜还得用课余时间加强自己，不然以后没工作了，其它的也不会，干啥啥不行，乘年轻多卷一下吧，虽然我也不愿意，但是没办法，要是考公务员，参加山西的省考，我想考刑警，不过估计是没什么机会，还是好好学习计算机吧，正好计算机这些的我都挺喜欢的，今天就这样了，早点休息。', '2022-03-24', '2022-03-25 00:06:14', '2022-03-25 00:06:14', 1);
INSERT INTO `blog_diary` VALUES (764, 1, '看电子书。', '2022-10-04', '2022-10-10 22:53:06', '2022-10-10 22:53:06', 1);
INSERT INTO `blog_diary` VALUES (765, 1, '周六玩异星工厂忘了写日记，周日补。昨天和今天一样，在家无聊就到了公司，下午解决了一道题，这种还差俩题...先说昨天的事情，晚上在记录今天的，不然没得写了，昨天怎么说，痴迷dnf早上起那么早就开肝，晚上就懒得玩了，开了个异星工厂玩到1点多，日记都给忘了，不管玩啥游戏都开始不会建造，要么就一直拖，等，要么就造的很乱，规划差之后又不想改，又想起来我缺氧的档还没完了，之前玩的泰拉瑞亚也没结束，为啥我就不能好好完成一个游戏呢，写博客也是，好高骛远，想的啥都好，到做的时候啥都不想做，或者说不知道从哪开始，不管怎么说这个一下改不了还是慢慢来吧，先每周的算法题跟上，这周还差俩题，等等补完，下周要是有时间写博客就从最基本的开始，反正这个博客之后肯定是要重构的，先把功能弄好，等重构的时候在考虑界面美观等问题。', '2022-02-26', '2022-02-27 19:38:38', '2022-02-27 19:38:38', 1);
INSERT INTO `blog_diary` VALUES (766, 1, '文明六一个人干到了一点。', '2022-11-26', '2022-11-27 00:44:24', '2022-11-27 00:44:24', 1);
INSERT INTO `blog_diary` VALUES (767, 1, '说好的这周玩消光，结果玩了泰拉瑞亚，这次泰拉瑞亚一定要完整流程通关。', '2022-12-04', '2022-12-04 23:48:46', '2022-12-04 23:48:46', 1);
INSERT INTO `blog_diary` VALUES (768, 1, '这周应该也算是一个完美周末了，俩天都有按时吃饭，周六休息一整天，周日下午继续开发vue3的界面，进度还算是可以，现在pinia和ts都比较熟练了，后端管理的主体框架这周算是弄好了，之后只要单独开发一些具体的页面就行，之前换了elementui导致之前写的博客文章展示页面结构样式都没了，有时间再考虑重新写。公司下周的任务还很忙，之前的机器人调试项目应该是告一段落了，把以实现的功能都调试完成，还有一些未实现的可能之后要做定制，下周调试的任务还有对接算法平台的一个基线项目，还有这周做的海康门禁项目的现场环境测试，对接ai算法平台的那个也不知道是怎么回事，一直没有消息，可能是不做了，具体我也不清楚。最近情况大概就这样吧，今天中午睡了俩小时，所以都快写到十二点了还是不怎么瞌睡。', '2022-08-14', '2022-08-14 23:42:44', '2022-08-14 23:42:44', 1);
INSERT INTO `blog_diary` VALUES (769, 1, '今天把最近做的俩个项目都提交了，所以今天不是很忙，做了几道算法题，晚上继续看微服务，zookeeper因为要安装没看，另外一个也没看，名字没记住，然后看了负载均衡Ribbon，没什么想写的了，就这样吧。', '2022-04-26', '2022-04-26 23:09:18', '2022-04-26 23:09:18', 1);
INSERT INTO `blog_diary` VALUES (770, 1, '今天开发智慧加油站的一个项目，主要是修改json格式，为了对接dms，今天把格式修改完成了，测试感觉也没问题，就是不知道格式对不对，明天去了和dms对接测试一下，不过感觉应该是没什么大问题吧，然后博客开发进度几乎没有，也不能说是完全没有，稍微写了几个博客分类的接口，这个暂时不打算对外开放，也就是我这个虽然是博客社区，但是文章分类还是只有我的管理员账号可以进行操作，主要是考虑到开放之后，随便来个人都给我创文章分类，而且这个文章分类肯定是要在文章首页面展示的，数量肯定不能太多，所以这个文章分类只有管理员才可以操作，相对的文章标签这个可以开放，就是需要修改一下数据库表，新增一个创建标签的用户id，考虑到这个博客大概率也是只有我一个人使用，就不做一些每个用户创建标签的限制了，加一个标签搜索的功能和无法插入相同标签的功能就行，博客内容服务的功能再有俩周也差不多了，暂时还没加入redis，基础功能开发完成之后就开始考虑这个模块的优化了，优化之后下一步考虑文件上传的模块，和微服务的环境部署。今天就写这些了，最近失眠四天了，希望今天能睡着。', '2022-06-14', '2022-06-14 23:03:52', '2022-06-14 23:03:52', 1);
INSERT INTO `blog_diary` VALUES (771, 1, '今天任务依旧很多，重要的那几个任务还是没完成，明天任务依旧很多，这周的计划怕是没一个完成的，不过今天晚上抽时间看了几个vue的视频，今天学的父子组件的数据交互，主要是这个，才想起来之前的那个搜索算法还没完成，还是尽快吧，明天项目上的任务是要把南方电网的台账接口修改完成，还有evo-admin、evo-brm和evo-eims这三个项目中添加好白名单，作业管控的调试还得继续，智慧加油站的那个修改完成bug的版本要是明天提交了（我这边没权限提交）还得测试，今天完成的就一个版本文档的任务算是完全做完了，快十一点了，要记得也大概就这些，今天是坚持早睡的第五天。水痘还没好了，这周日过去再配一点药，周末计划是学习vue，不写了思路有点乱，都不知道刚刚写了些啥东西。', '2022-04-14', '2022-04-14 23:01:58', '2022-04-14 23:01:58', 1);
INSERT INTO `blog_diary` VALUES (772, 1, '公司那个任务还没有解决，主要是没找到前端页面调用后端接口的位置，现在就是需要找到调接口的位置，传入我特定的一个参数，然后我对那个查组织树的方法在封装一次，保证我这个修改不会影响其它页面的组织树，最笨的办法就是用原来的那个方法查出来数据，我用当前user的权限字段进行过滤，不过这也是最简单的方法，每天去了看看能不能修改原来组织树创建的逻辑，还有就是找到调用的那个接口，不得不说admin是真烦呐。白天啥事也没做成，到晚上看那道算法题，学习了二分图的判断算法（对点染色，深搜或者广搜都行）和匈牙利算法（就是配对的一个算法，尽可能多的完成二分图中左右俩点的匹配，用深搜（应该广搜也行）的方法一个一个配对），然后晚上稍微加下班把笔记写完了，这是这周的第一道题；还有就是今天下载了一个网易读书软件，开始看看小说不然也挺无聊的，手机游戏和b站今年尽量少用，去年一年使用了1000多小时，换算一下就是40多天，太可怕了。', '2022-01-05', '2022-01-05 23:40:12', '2022-01-05 23:40:12', 1);
INSERT INTO `blog_diary` VALUES (773, 1, '周六去了公司摸鱼，剩下的时间就是用来玩dnf了，最近还算感觉肚子胀气，总是想打饱嗝，就是打不出来。', '2022-03-05', '2022-03-06 00:30:56', '2022-03-06 00:30:56', 1);
INSERT INTO `blog_diary` VALUES (774, 1, '今天有点累啊，因为做完没睡好，上午开会讲南通桐昆的项目需求，流了些问题下午项目经理再去和甲方确定，到晚上差不多就好了，然后导师还给了个bug，大概确定是MySQL密码的问题，因为好几个地方都连不上，其它没了，哦下午还写了三篇题解。', '2022-05-05', '2022-05-05 23:12:12', '2022-05-05 23:12:12', 1);
INSERT INTO `blog_diary` VALUES (775, 1, '和纸片人共度情人节，哈哈开个玩笑。最近挽救计划看一半了，每天一个小时稍微有点不够啊，晚上去理了个发，博客今天每进度，不过上午稍微做了个小的项目修改，算是摸鱼的一天吧。', '2022-02-14', '2022-02-14 23:27:34', '2022-02-14 23:27:34', 1);
INSERT INTO `blog_diary` VALUES (776, 1, '月底但是因为昨晚忘记写日记了，今天周五补上。刚刚看五月计划是要学习oauth2.0这个完成了，而且我把oauth2.0整合到了我的微服务框架中，实现了鉴权中心，除此之外其它的算法题，博客文章都没完成，当然这个月也没闲着，这个月主要是看了微服务这些，还有vue3，还学习了shell脚本，今天也就是7月1日把centos7的一键部署博客完成一半，因为现在只实现了一键部署博客的各种依赖，shell脚本这个难点主要是在脚本中修改MySQL密码，整了好久，还有之前使用rpm安装MySQL，现在在脚本中使用的是编译安装MySQL，每次安装会要很久，现在测试从初始的centos7.6系统开始装机需要一个小时才能安装完成，测试了好多次，安装目前没什么问题，还有做了一个nginx的文件下载服务器，因为每次都从网站上下载会很慢，而且有时候会下载失败，总之六月还是感觉很漫长的，收获也还可以。七月计划是完成vue界面，以及博客的一键部署功能，这个可能会写好几个脚本，包括博客的启动暂停和服务器的一键安装配置脚本，大概就写这些吧，今晚在玩云顶之奕一直输，所以就一直玩到了现在。', '2022-06-30', '2022-07-02 00:23:10', '2022-07-02 00:23:10', 1);
INSERT INTO `blog_diary` VALUES (777, 1, '晚上玩无主之地2，眩晕，服了，还有找不到游戏退出键，还好不是虚拟现实的游戏，不然我出不来了。', '2022-12-27', '2022-12-27 23:29:10', '2022-12-27 23:29:10', 1);
INSERT INTO `blog_diary` VALUES (778, 1, '一天没什么任务，今天就把博客的openfeign调用弄好了，现在可以直接使用请求接口的用户的authention来调用其它服务模块的接口，然后还加上了nacos的config功能，今晚测试有些小bug，等明天去了再看看。', '2022-07-13', '2022-07-13 23:12:24', '2022-07-13 23:12:24', 1);
INSERT INTO `blog_diary` VALUES (779, 1, '昨天忘了写日记，还是补上吧，把前几天的项目提交了，感觉写的还不是很好，今天都周三了，上午调休，想想这周还没做题，下午过去再说。', '2022-02-22', '2022-02-23 10:38:10', '2022-02-23 10:38:10', 1);
INSERT INTO `blog_diary` VALUES (780, 1, '今天博客内容模块大概完成了，剩下一些后续的业务修改和接口权限的设置，不过大概都是完成了，明天开始以及接下来的几周就要开始公司项目的开发，这次是作业管控对接ai子系统，这个主要是替换这个使用dms下发算法配置，修改之后就不经过dms，而是直接下发到ai子系统，这个开发给的时间还是很长的，所以今天就没着急看，明天及之后就要加急开发了，还有这月还没看算法，博客文章也没动，主要时间都用来微服务的开发了，不过好在今天差不多接口都写完了，之后就可以抽时间看看算法，这个月的任务还是一定要完成的。', '2022-06-22', '2022-06-22 23:30:20', '2022-06-22 23:30:20', 1);
INSERT INTO `blog_diary` VALUES (781, 1, '月底总结最近不想写，今天杭州下大雪，今天降温到0度了，实在是太冷了，都不想摸键盘，晚上就裹被子里面吃吃零食，看视频，手套还没回来，明天还得继续挨冻，好在今年夏天已经买好了电热毯，这是今年做的最机智的事情了，然后公司项目调用第三方接口我在博客的那个项目中模拟写了几个，测试没什么问题了，然后明天就和前端对接口还有和金融的数据引擎对接，计划进度正常，还有今天把前端打包总算是弄好了，但是晚上回家不想看啊，冻手，日记就写这么多了。', '2022-12-01', '2022-12-01 23:18:34', '2022-12-01 23:18:34', 1);
INSERT INTO `blog_diary` VALUES (782, 1, '今天项目啥事情没有，早上开早会我都不知道该怎么说，非常难受，不过上班时间搞自己的博客确实爽，今天把博客相关的标签、分类都整完了，稍微测试了一下测出的问题都改了，剩下的等前端搬完再测，晚上回家继续昨天的妹同居2游戏，然后就出了坏结局妹妹有了孩子，也没备份存档...早知道我就该当个正人君子，可惜了我的进度，有时间继续玩，看看还有什么结局，今天手柄回来了，还不是特别会用，不过躺床上打游戏确实舒服，再就是最近上海疫情，搞的那么严重，还有人死了，我吃到的瓜有：老头撒币跳楼的，志愿者被打死的，志愿者被推下楼的，不做核酸被警察带走的，不知道该怎么说，上海人不愧是天龙人，有很多上海人还跑出来，万一疫情影响到了杭州，杭州也被封城，我怕没吃的，就网上买了点干粮，还有啥事呢.. 大概就这些把，总感觉还有一件事没记录。刷了个牙想起来了，最近应该是消化不良，偶尔反酸，喉咙下面感觉有什么东西堵着，明天去医院看看，计划是今天但是因为没带身份证，，对了还有计划没定，明天主要搞前端，尽量搭建完成vue的基本框架，当然是在没任务的前提之下做，要是有其他事情后延一天，今天睡觉。', '2022-04-06', '2022-04-06 23:17:14', '2022-04-06 23:17:14', 1);
INSERT INTO `blog_diary` VALUES (783, 1, '今天几乎没什么要做的任务，就学习前端界面，稍微写了几个界面框架，具体细节还要之后完善，不过之后也按照这个模式来做吧，后端把用户模块的权限完善了下，还没测试，不过因为没什么问题。今晚还去新的园区看了看，各位还是挺好的，就是刚刚装修完，空气有点呛，新楼五层还有个跑道，以后跑步都不用去河边了，总之新园区还是挺好的。', '2022-07-21', '2022-07-21 23:36:40', '2022-07-21 23:36:40', 1);
INSERT INTO `blog_diary` VALUES (784, 1, '今天公司好多羊，我们部门也有，就和我是一排，我们这排四人阳了三个就剩我一个，不管怎么说又苟了一天，许愿明天也不会被感染，今天新给的项目到晚上都没把权限申请下来，明天应该会好，所以今天就继续博客的开发，把用户查看编辑页面弄好了。而且图片也可以上传，个人感觉进步巨大，明天有时间继续。现在还是肚子疼，嗓子也不舒服，不清楚原因，肚子疼应该还是胃酸，嗓子这都是老毛病了，一年了就算想喝水，等阳了康复之后去医院看看，最近实在是不敢去医院，万一因为去挂号阳了真得不偿失。', '2022-12-19', '2022-12-19 22:59:36', '2022-12-19 22:59:36', 1);
INSERT INTO `blog_diary` VALUES (785, 1, '玩了一天dnf，计划的看看学习视频也一直拖，最后也没看，而且这周三题没做，拖把，至少这个月必须完成任务，实在没写的写游戏进度？算了吧。', '2022-03-13', '2022-03-13 22:27:08', '2022-03-13 22:27:08', 1);
INSERT INTO `blog_diary` VALUES (786, 1, '周一看山东钢铁云存储查询的优化，具体业务感觉看的也差不多了，有个问题就是我看代码中请求云存储总容量是用数据库中的第一个服务器的容量，这个不太清楚，也不知道要不要改，是不是bug，明天继续看这个，今天把定时任务等框架都弄好了，明天就是细节完善。博客开发最近前后端都没动，一直在忙碌shell脚本，现在应该是可以一键完成部署了，今晚再测试最后一次，现在已经启动上博客的部署服务了，重装一次需要一个多小时，主要时间都用在了MySQL的编译上，光编译MySQL就要半小时，我自己的博客服务等操作都很快的，毕竟都是修改文件。明天就开始vue的开发，前几天看的那个视频先跟着把框架路由弄好，之后看我之前学习的security项目把动态路由弄上去，大概就是这些，然后前端项目有个变化，css不打算用原生的css了看着也不方便，改起来也很累，打算使用tailwindcss这个包其它的依赖没有变化，还有七天发工资，总感觉六月过的好漫长啊，可能是因为发生了很多事情，还有我博客开发，服务器等都在上个月弄好的，总之七月计划把前端弄好，八月初必须要把微服务版博客上线，之后是学习c++还是安卓还没确定，现在我的技术路线还没确定，我现在想的是弄好我自己的博客网站，app和客户端软件，所以这些都需要我自己去学习，尽量抽时间学习吧，看网上好多人都是技术要学的深而不是广，但是我真的想弄一个自己的app和电脑软件，而且c++和安卓在大学都学习过，现在还是先开发完web再说吧，不管深还是广总比闲着强，整博客这东西我就是没事干给自己找点事情，学习其它技术Java我也不能拉下。最后记录一个今天出现的bug（要是有博客这个写在博客里面多好），就是今天用阿里云1核2g的服务器执行我的启动脚本的时候，服务总是会莫名其妙的挂掉，具体我看着系统的资源占用情况，一个一个jar包开始启动，开三个的时候就会使所有博客服务的jar包和nacos直接挂掉，但是换到2核4g的服务器就没出现这个问题，所以应该是跑微服务的时候内存不够了。还想写点，但是都十一点了，就这样吧，先休息了，我之前在公司睡觉的床位那来人了，最近只能留在新搬来的这个位置趴着睡觉，有点期待公司的新大楼，希望我的工位后面的空间能大一点。', '2022-07-04', '2022-07-04 23:10:34', '2022-07-04 23:10:34', 1);
INSERT INTO `blog_diary` VALUES (787, 1, '十月月底总结应该当天应该写的，但是当天忘了，今天也没心情继续写，而且时间也不早了，就简单记录今天，最近这周一直都没太忙，今天就看dms下发和orms的合并代码，不过这个合并代码不是很着急，十一月八号完成就行，今天把盈科的项目结束了，之后测试可能需要再花点时间，不过这都是自己写的代码，不管怎样都非常了解，就算是有bug也会简简单单（就在这立flag了），最近晚上回家打打哈迪斯，最近的生活还是很惬意的，睡觉。', '2022-11-02', '2022-11-02 23:32:52', '2022-11-02 23:32:52', 1);
INSERT INTO `blog_diary` VALUES (788, 1, '玩游戏又不早了，今天早上上班堵车，自行车也堵了，早上没吃饭，那个项目今天做的差不多，等明天前端来了测试一下，应该进度是正常的。', '2022-03-21', '2022-03-22 00:31:12', '2022-03-22 00:31:12', 1);
INSERT INTO `blog_diary` VALUES (789, 1, '喉咙这还是难受，今天爆肝缺氧到凌晨，先睡觉了，明天上班。', '2022-02-07', '2022-02-08 01:21:36', '2022-02-08 01:21:36', 1);
INSERT INTO `blog_diary` VALUES (790, 1, '今天的晚上看了好几个vue的视频，感觉总体的看vue视频的计划还是可以的，可惜的是那个算法题一直没时间看，要不周末看看？项目那个作业管控的新增的三个报警有俩个可以上来了，然而开发和我没啥关系，我这边的都可以复用之前写的，主要都是dms那边需要修改和添加，然后智慧加油站的那个稍微测试了一下，还有些问题，不过那边说是因为没有部署到服务器上所以测试的时候还有些问题，这个任务应该不是最着急的，还有南方电网的这个接口没修改完成，删除的这个逻辑好像稍微有点问题，不知道是什么意思，周日去配药的时候顺便去看看吧，最后还有一个，今天晚上走的迟了被葛老板发现了，就又给我一个修改log4j版本的任务，这个应该好修改，之前做个，稍微看看之前记录就行，主要任务就这些，算法又留到月底了，这个月的八篇博客也要完成，所以这个周末不能一直玩游戏了，操看计划还要把博客第二版上线，尽力吧，这个周末是学习周，俩天三篇博客，把vue学习的笔记也写个文档，放在第一版博客的文档中，还有十五天，即使博客上线也不会太完美，今天是周五明天不上班，但是睡觉也稍微有点迟了，那就日记就这样把，马上睡觉。', '2022-04-15', '2022-04-15 23:15:58', '2022-04-15 23:15:58', 1);
INSERT INTO `blog_diary` VALUES (791, 1, '今天测试所有算法的下发，进度正常，明天开始经验库接口开发，开发之前写个文档，给前端使用，总体进度正常，国庆假期之前应该是可以完成开发的，晚上回家继续缺氧，第二次开火箭忘记断氢气了，火箭舱里又充满了氢气，这次在二星多等等，做出高级的火箭仓，然后就准备去拿超冷，dlc超冷怎么做还不清楚，现在就是等科技吧，全靠冰萝卜的三级科技。', '2022-09-20', '2022-09-20 23:45:02', '2022-09-20 23:45:02', 1);
INSERT INTO `blog_diary` VALUES (792, 1, '马上周五了，这周好忙啊，天天就改接口，不过今天算是把需求的改动都改完了，现在就剩一个返回总存储容量的接口，这个稍微有点不太清楚，不知道怎么查全部的容量，明天看吧，反正其它的接口都改完了，暂时测试也没发现问题，明天主要就看这个要怎么查，晚上继续看网关的视频，还是不太会用，学完之后在写博客之前得弄个demo练习一下，明天就可以试试，周五就放假了，可算是能休息了。这周好累，每天也没早睡觉。', '2022-05-12', '2022-05-12 22:39:28', '2022-05-12 22:39:28', 1);
INSERT INTO `blog_diary` VALUES (793, 1, '因为前俩天开的缺氧存档玩上头了，所以又玩一天。', '2022-09-12', '2022-09-13 23:05:36', '2022-09-13 23:05:36', 1);
INSERT INTO `blog_diary` VALUES (794, 1, '今天一整天都很烦，不过现在好了，我觉得现在与其当个舔狗一直缠着一个人不放，不如努力提升自己，这样也能活的开心点，不至于被别人影响心情，以后就要做一个外向的没心没肺的人，不管别人怎么对我我都没啥感觉的那种，左耳进右耳出，最后再不忘补上一句，啊对对对。今天项目一点都不忙，但是因为心情不好整的晚上回家都很烦，活一天少一天我真的需要好好对待自己，除了我没人在意我的感受，甚至都不会去了解，像学笛子，以后肯定也会有各种烦心事，会吹笛子给自己解解闷确实是一个不错的选择，这次我不会太在意感情，今天其实我就已经决定好了，先预判一下，这次肯定会在将来的某一天晚上主动找我聊天，然后说我们没有共同语言（确实如此），觉得和我在一起特别无聊，而且我也不是她喜欢的那种外向，会照顾别人的那种人，所以肯定是没办法走到一起的，然后就觉得我们不合适（应该是本来也没在一起过），还有未来计划，我是不打算会山西的，大城市的房子我是一定买不起，以后可能在南方的某个小县城买个房子，如果上天可怜我希望我能遇到一个不讨厌我的人就行，已经不再奢求会有人喜欢我这样性格的人了，还想养只猫，今年都年底了，等明年看看能不能领养一直出生不久的流浪小猫，这不是说我舍不得花钱在网上买，我是觉得网上用来交易的小猫虽然是作为了商品，但终究还是算含着金汤匙出生的小猫，至少这辈子吃喝不愁，回归主题，她的话应该会一直留在太原吧，之后可能遇到一个两情相悦的人（我也是真心祝福这样，个人日记我没必要撒谎）也可能会在家里介绍通过相亲遇到一个比我更合适的，总之我们的人生计划都不一样又怎么可能有结果呢，高中也就是唯一的交集了，初次之外还可能又单身一辈子的选择，但是这个现在大家都只是说说，没几个人是认真的，就算现在是认真的以后也顶不住压力，我也一样，可能会在遇到一个让我心动的人（我持悲观态度，就算是真有也会是一个影子）或者以后被爸妈逼着相亲，现在都开始忙活给我找人介绍对象了，然后就马马虎虎的凑合过日子，之后就是柴米油盐酱醋茶，循规蹈矩的凑合过完这一生，这么说来追求一些我喜欢做到事情，学一下喜欢的东西确实挺重要的，那就决定了要学习笛子还有前端（对不起我自己，博客拖了这么久没上线，给公司做的项目倒是一个比一个认真），最后留一个小愿望，璐瑶将来某天肯定会觉得我这人很无趣，..，不过我从今天就开始准备，到将来的那一天肯定不会再受打击了，我的愿望是给她看我今天的预言，就算她直接给我删了我也要在加上发了今天日记的截图，然后滚蛋。（ps：以后不管发生什么事情都不能修改今天的日记，只要我不修改保存windows会给我证明的，现在时间是： 2022年10月28日  23点43分 秒就算了）再加一句，明天大周今晚稍微晚睡会，昨天才买的hades，这不得来干一把，天不会亮的放心吧。 23点45分', '2022-10-28', '2022-10-28 23:45:18', '2022-10-28 23:45:18', 1);
INSERT INTO `blog_diary` VALUES (795, 1, '依旧是在打游戏，最近应该是要歇会了，缺氧肝了一下午，整得一塌糊涂，一直拆了重建，也不知道在干啥，过段时间继续玩。', '2022-01-16', '2022-01-16 23:05:22', '2022-01-16 23:05:22', 1);
INSERT INTO `blog_diary` VALUES (796, 1, '放假了，不过明天要去爬山，今天没看微服务视频，进度又慢了一点，明天早起去爬山，不能睡懒觉，非常难受。', '2022-05-20', '2022-05-21 01:24:28', '2022-05-21 01:24:28', 1);
INSERT INTO `blog_diary` VALUES (797, 1, '看了一天oauth2.0还是完全不懂啊，今晚下班的时候找到了一个博客，明天去了要是没任务再看看吧，还有今天现场那边有个bug，不过是前端的，明天打包给陆总发布一下，还是惦记oauth2.0，微服务的基础啊，这个整明白了微服务这些都不是啥大问题，微服务现计划主要分为鉴权中心、用户中心、博客文章类服务，其它的图片服务中心、监控中心等之后熟练微服务之后再弄，今晚就这样吧，再看看风来之国之后睡觉。', '2022-06-07', '2022-06-07 23:24:54', '2022-06-07 23:24:54', 1);
INSERT INTO `blog_diary` VALUES (798, 1, '端午假期本来是去打算找房子，没想到去了那边看房感觉放假应该会更高，所以暂时应该是不搬了吧，可能等年底在看房子，今天就当是去白马湖转悠了，晚上看oauth就看了一点点，明天上午继续吧。', '2022-06-03', '2022-06-03 23:25:54', '2022-06-03 23:25:54', 1);
INSERT INTO `blog_diary` VALUES (799, 1, '对接ai模块的这个任务虽然还没有做完，但是要停一段时间了，因为ai那边的人没时间对接，所以我就准备找导师要其它项目，今天下午看了一个现场的设备树问题，定位还是比较简单的，因为设备树显示不出来，我第一想法是先看看数据库，看设备的父节点对不对，没想到果然是这个问题，这个问题的基线的eims问题，所以修复就由导师找基线的人来完成，定位的问题是设备设备树没展示完整，是因为下级目录记录的上级节点出错了，对于正常的三位一个节点，比如001根节点下级就是001001这样就不会有问题，问题出在其它系统上报的数据，他们的节点不是三位一组，而是六位，为了区分这六位的一位是字母，将级联上报的数据经过eims处理之后他的001a00001上级应该是001，但是eims处理成了001a00所以就会找不到。然后今天主要学习了linux的命令，几乎一个下午都在操作linux系统，最近想弄一个shell脚本一键安装博客所需的软件，还有部署博客系统，所以最近就在学习shell，不过这个语言很简单，多写写问题不大，下午主要在学习sed命令，这个是用来修改文件的，我用这个主要是修改一下jdk的环境变量，redis的配置之类的，今晚遇到个问题一直解决不了，大概是这样的通过shell定义一个变量test=\'/opt\'然后使用cd命令：cd ${test}这样应该是会进入/opt目录，但是我实际操作一直是进入了root目录，一晚上都没搞清楚是为什么，明天有时间看看吧，晚上还抽时间打了一下公司的oj，也就是做了一道签到题，还错了好几次，真是丢人啊，大概就这些，今天操作了一整天的服务器，最大的感受就是腾讯的云服务器实在是太垃圾了，阿里云不得不说确实好用，尤其是那个分屏功能，而且服务器连上能够保持在线很长时间，腾讯云服务器分屏功能没有，还特别卡，之后还得再买个阿里云服务器，在公司学习使用。', '2022-06-29', '2022-06-29 23:43:08', '2022-06-29 23:43:08', 1);
INSERT INTO `blog_diary` VALUES (800, 1, '今天没写博客，因为发到公司的文件没有git提交，就没写，明天吧，下午看了看算法，拓扑排序模板是会了，但是没有解决那道题，看来这周末要做题了，不然这周三题完不成，晚上玩异星工厂不早了，就差不多这样吧。', '2022-01-20', '2022-01-21 00:21:22', '2022-01-21 00:21:22', 1);
INSERT INTO `blog_diary` VALUES (801, 1, '今天看算法最长上升子序列最长下降子序列，最长不上升子序列和最长不下降子序列，动态规划的解法是看明白了，但是贪心加二分的那种方法没看明白，明天继续看这个吧，后天就可以回家了，再写写昨天的聚餐吧，去的饭店叫巴国布衣，吃饭的菜都好有特色，造型都比较独特，然后还有个变脸表演，感觉和电视上的不太一样，看他变脸可以明显看到撕面具的那一瞬间，在电视上就看不到，果然现场和电视还是有区别的，昨天吃饭喝了好多酒，晚上骑车都不知道是怎么回来的，一路上特别小心，差不多算了其他的也就那样。', '2022-01-25', '2022-01-26 00:16:04', '2022-01-26 00:16:04', 1);
INSERT INTO `blog_diary` VALUES (802, 1, '公司依旧是没有任务，然后我开始了博客后端的改造，先把博客文章的分类和标签弄好，今天加上了标签的后端服务，前端页面写了一点，只是刚刚有那个样子，还得继续修改，晚上回来玩缺氧，不知不觉都已经1点多了，赶紧写完睡觉，玩缺氧主要是今天minibase可以使用了，毕竟等了好久，今天终于能玩了，希望能够尽快适配dlc。', '2022-01-12', '2022-01-13 01:34:40', '2022-01-13 01:34:40', 1);
INSERT INTO `blog_diary` VALUES (803, 1, '玩了一下午的缺氧，到现在还没发展啥科技感觉电脑就不太行了，真空世界的只有几个图，而且别的图少东西，还有minibase还是不能使用，再等等吧。', '2022-01-08', '2022-01-08 23:58:02', '2022-01-08 23:58:02', 1);
INSERT INTO `blog_diary` VALUES (804, 1, '明天休息稍微迟睡一会，白天加班，最近又改成大小周了，这个难受啊，双休的快乐时光再没有了，白天在公司看那个admin的bug但是因为环境啥问题也没看出原因，何伟导师说这块的功能都没修改过，我把服务器上的代码下载下来看那个文件确实没问题，但是不知道为啥客户那边就会出问题，周一去了看吧，明天是属于我的日子，还有今天座位搬了，跑道了部门中间的位置，坐这感觉好有压力，导师领导都在这儿，不过Java的几个大佬也在我后面，这样有问题请教大佬也方便不少，总之有好有坏吧，之后摸鱼时间少了，大概吧，毕竟摸鱼是传统艺能了，总会抽出时间的。项目之外就是我的微服务了，今天把自定义token弄好了，现在使用jwt可以加入了我自己的数据，这样之后验证用户会简单不少，也不用频繁查数据库或者redis，今天也是收获满满的一天，晚上回来整了一下github，因为gitee恶心人，我没办法，而且github也好用多了，晚上把博客2.0的仓库创建好了，明天把lck拉进来，之后一起弄一个博客社区的项目，不过我还是计划自己也弄一个前端的，只不过最近任务重心放在微服务上，先把微服务的博客相关功能搭建好，而且这个之前写过，再写一个都是照搬，顺便引入mybatis-plus单表sql都不用自己写了，几乎完成了50%的任务，预计明天就能弄完这个接口，部署可能要稍等等，还有明天写一个博客的接口文档，发给lcf毕竟是之前说好的。', '2022-06-11', '2022-06-12 00:19:30', '2022-06-12 00:19:30', 1);
INSERT INTO `blog_diary` VALUES (805, 1, '发工资是真的快乐，期待了一个下午，一直看招商银行的消息，最后等到了12400左右的工资，其实月工资应该是10400，多出来的2k是年中的不知名奖金，下个月还有2k，还有公积金也增加了，之前是1200，现在好像是1400了，因为我算我的公积金账户余额多出来了，可能不是这个数，就粗略的看了一眼，没记住。对接海康门禁今天看了门禁下发之后的接收响应，因为没有设备就没办法测试，加了一个海康的虚拟设备，我下发请求之后没收到响应，这个不知道是哪出的问题，看日志我的下发是正常的，还有俩天时间，应该是可以按时完成的，今天没有加班，晚上回家把衣服洗了，差不多了，感觉最近没啥想写的，还是日子太过平淡了，博客最近应该也不会有进度。', '2022-08-10', '2022-08-10 23:18:04', '2022-08-10 23:18:04', 1);
INSERT INTO `blog_diary` VALUES (806, 1, '今天被盈科的mqtt连接烦死，不用正常的mqtt连接，非要用阿里云的mqtt，配置整整的独一无二网上都不好搜，还好最后是连接成功了，ftp上传文件夹目录的这个今天在内部环境测试目录也是正常的，明天去了对一下盈科mqtt上传的协议，看看需要修改参数吗，晚上答辩有点匆忙，稿子还没写就答辩了，还是有点紧张，我以为我念完用不了十五分钟，结果还超了几分钟，明天以及这个周末去了看看ppt再改改，争取周二去了流畅的讲完，今晚回来把文明6买了，等答辩完成之后开始开发。', '2022-11-17', '2022-11-17 23:47:02', '2022-11-17 23:47:02', 1);
INSERT INTO `blog_diary` VALUES (807, 1, '今天也不是很忙，晚上继续博客功能完善，不知道为啥我的博客加载那么慢。', '2022-12-12', '2022-12-13 00:13:36', '2022-12-13 00:13:36', 1);
INSERT INTO `blog_diary` VALUES (808, 1, '最近买了好多东西，还是因为消费券的那个，我买了热水壶蒸蛋器这俩个是用杭州给的红包，因为这次隔离我觉得做饭还是有必要的，所以就下单了，还有卫生纸，健胃消食片，纯奶，牙刷和雨伞，日用品就这些吧，明天给家里买点零食，我这边因为疫情邮不过来，已买的快递都通知商家等解封之后发货，希望可以都到了吧，别浪费了我的红包。公司今天接到一个任务，不是很难，可以明天过去修改，虽然明天是周六，但我实在是不想呆家里面了，一个假期憋坏了，算法题今天看了一道，有很多解法，但是我一个都不会，还是看的解析才完成的，明天去了公司写一下笔记。今天嗓子这还是难受，要是明天再不好周日就去医院看看，希望不是什么大问题，不知道最开始是因为吃那个馒头噎住引起的还是因为吃外卖太多引起的，反正以后没什么特殊原因再也不吃外卖了，等公司搬家我换房子之后一定要自己做饭啊，蒸蛋器都买好了。', '2022-02-11', '2022-02-11 23:48:28', '2022-02-11 23:48:28', 1);
INSERT INTO `blog_diary` VALUES (809, 1, '休息一天，明天又要上班了，去了就测试之前写的接口吧，希望问题不大。今天就联机群星，看看动漫。', '2022-05-08', '2022-05-08 22:42:48', '2022-05-08 22:42:48', 1);
INSERT INTO `blog_diary` VALUES (810, 1, '今天调试机器人这边，我能做的都做好了，之前巡检不能选择机器人点位，今天这个重新导入之后也可以使用了，最后一个问题就是机器人那边不难控制云天，这个要让机器人那边的人来修改接口，没我的什么事情了，还有机器人的一些数据没有上报，这个等巡检弄好再说，明天就周五了，总感觉这周少活了一天，还有七月份过的真快啊，一个月的服务器体验卡到期了，dnf也没怎么玩，还是一个人太无聊了，还有就是这个魔改版本的dnf没有当年大学宿舍刷图的那种感觉，所以有点无聊，最后博客今天调试主页面调用文章分类接口，测试较为顺利吧，主要是修改后端接口的逻辑，现在前端这有点卡住了，有个功能不知道怎么实现，明天去了看吧，反正最近我也没什么事情，天天摸鱼，总感觉心里过不去，虽然白嫖确实开心。', '2022-07-28', '2022-07-28 23:12:04', '2022-07-28 23:12:04', 1);
INSERT INTO `blog_diary` VALUES (811, 1, '今天项目上依旧不是很忙，收到个修改bug的任务，是svn项目，等我权限申请完成都下班了，博客把前端好几个bug都修复完成了，明天主要是该项目的bug，有时间在看前端，这周把一键部署脚本完成，最近胃酸，我估计可能是前几天晚上回家就吃很多零食，导致身体判断晚上需要消化很多东西，所以就分泌很多胃酸，结果我最近不吃了，还是规律饮食吧（这个点写日记，可能作息也要考虑规律下...）。', '2022-12-08', '2022-12-09 00:43:44', '2022-12-09 00:43:44', 1);
INSERT INTO `blog_diary` VALUES (812, 1, '周日去医院看病的一天，本以为一上午就可以了，但是稍微遇到那么一点点麻烦，最开始是预约好去缴费，结果最开始医保卡不能用，所以只好我自费交了预约的钱，中间的一些曲折就不提了，我就是个皮球，缴费之后就去排号，不知道是我没听到还是没念我的号，前俩次都没听到，从十点开始排队等，到了十一点四十才做完，然后开了好多药，我猜药应该会很贵，就没考虑自费，出去自助刷医保，发现可以刷了，幸好能用了（开药花了340多），然后又回去找医生把药开完，然后要让我去抽血，抽血也找了好几次，本来三楼就可以，但是因为是急诊，所以我要去一楼，但是那个医生没说清楚，她直接和我说一楼急诊不就好了嘛，化验血的结果要等一个小时，反正没事干就回公司去了，还有早上接的自行车脑子抽了没先还自行车，还车的地方据我这就几步，可惜没看到，中午也没出来吃饭，之后就是等下午医生上班之后去取验血结果，拿药，说实话这辈子都没吃过这么多药，忘了写，医生查出来的结果是水痘，算好还是坏呢，也不知道，之后就去公司做了一道算法题，这个月的任务还差很多，vue视频也没看，本月已经过去三分之一了，之后进度要稍微快点，不能都留到最后几天，差不多了，接下来的一周是早睡周（学习妹同居 -_- ）十一点睡觉吧，再早也是开玩笑，根本做不到，奖励暂时还没想好，今天快到点了，先睡觉吧。', '2022-04-10', '2022-04-10 22:43:18', '2022-04-10 22:43:18', 1);
INSERT INTO `blog_diary` VALUES (813, 1, '小周周六，去了完成上半年绩效的表格，还有周五写的日报被批评不认真，我又重新写一份发过去，机器人还没调试玩，对接海康门禁的任务已经开始了。', '2022-08-06', '2022-08-06 23:01:06', '2022-08-06 23:01:06', 1);
INSERT INTO `blog_diary` VALUES (814, 1, '3月9日，今天被隔离了，下午收到消息，晚上没加班直接回家收拾了东西，立即前往隔离的地方，现在就是在宾馆写日记，在宾馆是和合租的那个大哥一直住，虽然是被隔离了，但是还可以出去，不影响上班，然后就是今天白天在看spring security，一直在找别人做好的demo，到晚上是找到一个比较好一点的，先看看吧，还有就是之前王张慧分享的他之前报班的视频，那里面有个ssm整合spring security的项目，最近也抽时间学习一下，剩下今天就没干啥事情，差不多了，休息，体验住宾馆的第一天，十六天隔离的第一天。', '2022-03-09', '2022-03-09 23:22:56', '2022-03-09 23:22:56', 1);
INSERT INTO `blog_diary` VALUES (815, 1, '今天总算是把海康的门禁调试完成了，现在黄河鑫业的项目也在催进度，真累啊，明天继续看算法下发，应该是可以把已有算法调试通的，今晚回家就九点半了，躺床上不想动，现在才写日记，不过也就写这么多了，有点累。', '2022-09-01', '2022-09-01 23:41:14', '2022-09-01 23:41:14', 1);
INSERT INTO `blog_diary` VALUES (816, 1, '准备睡觉了才想起来没写日记，算法任务莫名其妙又会多了，真烦啊，排查了那么多可能出现这个问题的原因，都解决了还是会出现，我现在实在是没招了，现在就剩一个前端的问题，等这个修改之后我再看看吧，昨天穿插一个动环报警类型的修改就是之前把消警的字段数据填错了，就算一个小修改，都没邮件同步，还有前几天岑帆帆给的中石化项目因为需求一直没确定，所以这个暂时不开发，要我做另一个项目，但是也没给分支，只是大概知道要使用金融那边的一个什么引擎，之后还要我做这个引擎的培训，这个任务看来也得费点劲，今天还是在做博客的开发，解决了一些小问题，其它还有什么事吗，今天正式宣布我存款突破了十万大关，要是算上公积金和借出去的1.5w现在我有接近16w的资金了，卧槽啊，这辈子没见过这么多钱，还有这个月22号要答辩，ppt得提前准备好，计划周六去公司写，原来准备和旭福爬山只能放弃了，因为下周六还要团建，最近事多，虽然不是忙，但是这些事情需要准备和惦记着，答辩要准备充足一点，不过我对通过不太期待，要过不过吧，主要这次就当是一次历练，以后要大方一点，不能总是像个女孩一样害羞，就这些吧，睡觉。', '2022-11-10', '2022-11-10 23:48:16', '2022-11-10 23:48:16', 1);
INSERT INTO `blog_diary` VALUES (817, 1, '今天忙经验库人员下发和海康门禁现场的问题，今天把人脸下发的卡号改成了海康需要是十进制，晚上人都不在了，最新的包没测试，不知道这次行不行，我现在真是有点不太自信了，都是些内部测试没遇到的问题，总之明天看吧，今晚买了点零食，国庆大概是回不去了。', '2022-09-27', '2022-09-27 23:35:42', '2022-09-27 23:35:42', 1);
INSERT INTO `blog_diary` VALUES (818, 1, '虽然今天什么都没做，但是我的健康码变黄了，不知道明天早上能不能变回去。最近在看广东石化的项目，但是还没开始，环境分支都没提供。', '2022-10-13', '2022-10-13 23:19:48', '2022-10-13 23:19:48', 1);
INSERT INTO `blog_diary` VALUES (819, 1, '周二过去了，下发算法感觉做的差不多了，今天在导师的指导下做好了多通道多算法的配置下发，明天应该能把多通道多算法的下发和状态修改都弄好，这周任务应该是可以准时完成，最近又要开始写日报了，看了现在经济确实不太好，应该不会被裁员吧，毕竟刚涨工资，最近这个对接ai任务稍微有点难，今天也是第一次使用正则表达式修改字符串，感觉还挺好用的，这个先留个记录，之后一定要做个笔记，还有昨天说的耳机没到，原来是人家发了俩个包裹，看来还是不能随便发火，还好对方的店家，不会和我吵起来。今晚买了电热毯和毛毯，这个冬天就是再冷也不会着凉了，昨天还买了墙纸，打算贴在窗台旁边的墙上，现在应该是不会在搬家了，下次搬家就是从大华离职的时候。最后在日记里面写一下璐瑶吧，也不知道为什么最近又愿意找我聊天了，我倒是不介意，反正我的时间也不珍贵，闲着也是闲着，有人陪我聊天更好，这次就是突然再删我微信我也有准备了，不得不感慨，我tm真是舔狗啊。', '2022-08-23', '2022-08-23 23:22:32', '2022-08-23 23:22:32', 1);
INSERT INTO `blog_diary` VALUES (820, 1, '昨晚又忘记写日记了，不过知道今天完成查看才发现，我都找不到昨晚是为什么会忘记，不过也无所谓了，昨天本来计划是玩一上午游戏，结果那局游戏开太久了，一直玩到晚上吃饭，之后得知周日还要上班，心情非常悲痛，就没有然后了，睡觉还失眠。', '2022-04-23', '2022-04-24 23:07:48', '2022-04-24 23:07:48', 1);
INSERT INTO `blog_diary` VALUES (821, 1, '2022最后一天，今天休息中午才醒，然后又睡了一下午，所以现在一点多了还不瞌睡，今年就以星露谷结束，年终总结之后再找个时间写。', '2022-12-31', '2023-01-01 01:10:52', '2023-01-01 01:10:52', 1);
INSERT INTO `blog_diary` VALUES (822, 1, '五一当天没有上午，下午找群友开了一把群星联机，玩到了半夜，我不说几点，反正就是半夜。', '2022-05-01', '2022-05-04 23:39:24', '2022-05-04 23:39:24', 1);
INSERT INTO `blog_diary` VALUES (823, 1, '小周，去了公司做巡检任务取消报警的这个需求，今天我做的是报警之后自动消警，等项目经理晚上开完会之后看结果要我重做，做成那种完全不报警的情况，这个需求还有下周一周时间，现在情况是导出表格的昨晚了一半，这个是因为其中一个字段在eims数据库中不保存设备的预置点数据，所以导出的时候要么去请求设备获取预置点的数据，或者我新增一个数据库表格存放这些字段，再加个定时任务也是可以解决的，我觉得应该是加个定时任务好一点，第一个导出表格的需求请求设备这个接口需要找前端看看，因为icc这个版本的客户端ctrl+shift+i打不开接口调试的界面，只能去找前端问这个接口，第二个需求就是今天做的这个取消报警，感觉应该不会很难吧，这个现在的问题的设备没有对着开关每次都不会报警，之后在巡检完成之后提示没有识别之类的信息，我猜对准开关就可以报警了吧，这是第二个需求，第三个就是在巡检的主页面加俩个接口返回一些界面数据的信息，这个只要有数据库，查找是没什么问题的，要是在和其它接口一起交互可能就会麻烦，总之这个需求还有最后一周的时间，这周从周四开始投入，感觉没做多少进度，希望下周有重大突破。接下来就是博客的记录了，今天整了一个前端调用我文件上传的那个接口，之前使用postman测试，在获取文件创建信息的时候报错，我以为是postman没有上传原文件，今天写了一个简单的上传功能（其实是网上百度找的，又稍微修改了一点，感觉前端还是很麻烦）测试调用的时候和postman报错是一样的，所以之后要怎么处理上传这个还得再想想，现在有俩个思路，一个是看前端上传的时候能不能获取上传文件的创建信息，再就是改改后端的接口，看看能不能获取文件的创建信息，这个希望是后端能解决吧，因为获取创建信息对于我日记的上传还是挺重要的，今天上传日记接口测试其实是成功了，只要我不取文件的信息就没事，测试过程中发现一个新的问题，我跨模块调用接口的时候需要鉴权信息，这个在系统内部还没想到解决方法，暂时我把需要调用的接口都放白名单了，这样肯定是不行的，之后修改也是有俩个思路，首先是看oauth2有个对系统内部调用授权的方法，可以看看这个接口是要怎么处理，再就是我觉得可以写一个定时任务，再创建一个超级管理员的账号每天定时请求接口获取权限的token然后放到redis中，跨系统调用的时候可以取出这个token调用，感觉最近到了瓶颈期，博客也弄不好，项目也有问题，明天下午具体是要看前端还是服务接口还没想好，可能是前端吧，接口写这么多，具体也没有用，怎么使用还不清楚，现在写接口都是靠1.0的博客凭感觉写的，这还是第一次写社区版的博客服务端，差不多就这样了，希望下周进度快一点，博客啥的技术也有提高，可能这个月的算法又要鸽了。', '2022-07-09', '2022-07-10 00:04:38', '2022-07-10 00:04:38', 1);
INSERT INTO `blog_diary` VALUES (824, 1, '最近这周有点忙，博客都没时间看，不过博客最近不打算写，标签功能还没完成，那个分页的bug一直没修复，准确的说是修复了，但是因为标签功能没完成，所以就一直没部署新的版本，再等等吧，最近学习vue，都学明白了再继续博客的开发，之前vue开发一直都是知道是这样用但不知道为什么，最近看到v-on,v-bind才豁然开朗，这个vue的教学视频还挺多的，也不知道什么时候能看完，反正有时间了就慢慢看，等到之后这个老师带领做项目的时候再跟着写项目，最近讲的这些知识点我在之前开发过程中多少用过些，学起来稍微容易。再说公司的这个项目，本来就是很简单的一个接口的开发，但是不知道它怎么搞的里面有个服务跟我这个开发的接口实在是太像了，但是数据库有些不同，搞得我现在也不知道要不要用它这个，是真的烦，昨天主管还找我谈话，应该是所有人都要找一次，算是访谈吧，也没说啥重要的事情，就是总结去年，展望今年，顺便还说了公司搬家的事情，大概在四月份，这个到时候再说吧，大概率搬家，再买个电瓶车，上下班也方便些。这周的算法题在前几天没任务的时候做完了，明天去了看看那些要写博客，这个做完，然后看看博客或者其它，差不多就这些吧，偶尔想写日记就能稍微多写几句。', '2022-02-18', '2022-02-18 23:58:06', '2022-02-18 23:58:06', 1);
INSERT INTO `blog_diary` VALUES (825, 1, '今天是周日，昨晚忘了写日记，今天起的早就先补一下，免得之后忘了。昨天是八点半在公司集合，但是好多人八点半之后才来的，可能我去太早了，八点就到，等了好长时间，然后就是乘坐大巴车去宁波，本以为是宁波市的方特乐园，结果跑到了附近的慈溪市，看路边的路牌之类的写着宁波市慈溪市，还带前缀呢，果然是宁波真大。之后就是进游乐园玩耍，好多项目玩之前看着好可怕，我去体验的有跳楼机、大摆锤(不知道是不是这么叫，看网上的和我玩的那个不一样，网上都像荡秋千一样，我玩的那个还会把人头朝下转过来)、过山车、过山车升级版、过山车阴曹地府版、海盗船差不多这几个，因为是第一次玩，看着确实有点害怕，但是上去之后也没什么，过山车之类的主要是玩一些从高处加速冲下来有一会会的失重感(可能不是这么说，但我是文盲)然后就是之后的加速，加速转弯，旋转之类，甚至玩多了有些无聊。阴曹地府版那个加速不是很快，但是全程急转有点刺激，但是因为周围全黑，也不让带眼镜，看不到前面的路，一楼随车摇摆就是了，也不会掉下去。升级版的那个过山车路程很短，但是分为俩段，当然不是断开的那种，是正走一次，倒走一次，第二次看不到背后就可能会有点慌，总体评价还是可以的跳楼机体验的是极速上升和下降还有周围人的尖叫，我感觉没什么吧，上升的时候我直接抬头一点感觉都没有，下降时那个失重很舒服，但只能体验一次，之后就没啥好说的了，只能说他这个跳楼机不是很刺激，还有这个是在一个塔楼里面，本以为周围会有点屏幕，来点不一样的感觉，结果白白期待了，还有海盗船没写，不过海盗船就算了，这个是真的随处可见。去玩各种项目都是一个人，甚至还有几个项目只有我一个人，给我单人开车，只能感叹啥时候能找到对象啊，我还不会也打光棍了吧。今天上午还能玩，下午俩点集合回去，但是天气好像不太行，不过算了，该玩都昨天都体验过了，今天随便吧。日记纯流水账，我也不打算提升啥文采，记录日常生活就行，这算是我第一次去大型游乐园，还正巧赶上了疫情，进去园区都没什么人，我玩的所有项目都没满员，还有几个给我单人玩耍的，疫情影响真是太大了，希望疫情早日结束，到时候我肯定会记录在日记中的。', '2022-06-18', '2022-06-19 22:12:00', '2022-06-19 22:12:00', 1);
INSERT INTO `blog_diary` VALUES (826, 1, '今天计划的博客和算法题都没有完成，不过是有原因的，上午完成了机器人那个文档，下午刚睡醒那会稍微修改一下提交了，然后就开始写orms的文档，然后项目经理改了一个小的修改，虽然也就一会就修改完了，但还是打乱了我的计划，还有晚上，大好时光被叫去开会培训，我就呆了俩小时，主要是讲的业务也没听懂，是我太笨了吗，今天的计划推到明天，尽量完成，不过我感觉明天会有个业务需求，我猜的，晚上到家就不早了9点30好像，打开异星工厂稍微看了看新手教程，操作不太熟，不过游戏挺好的。', '2022-01-19', '2022-01-19 23:45:20', '2022-01-19 23:45:20', 1);
INSERT INTO `blog_diary` VALUES (827, 1, '今天依旧没有任务，应该是五一之前不会有新任务了吧，不过也正好，忙碌好久了，休息一下，下午继续算法题，看了单调队列的算法，还有一道啥题忘了，最后看Kruskal算法看的头疼，没看明白，就放弃了，之后就稍微测试一下作业管控的那个bug，之前不是设备一直上报数据嘛，今天设备那边改好了，然后第二轮测试应该不会有啥问题了吧，大概，晚上继续微服务，学习了feign，算是一个服务调用的组件，之前使用的一个函数发送请求调用服务，feign算是把原来服务的controller弄道一个接口里面，然后调用接口，算是符合正常习惯吧，看完这个就下班了，明天主要任务是把ppt写完，毕竟出来打工就是为了挣钱，万一涨工资了呢。', '2022-04-27', '2022-04-27 23:21:24', '2022-04-27 23:21:24', 1);
INSERT INTO `blog_diary` VALUES (828, 1, '周日又忘了写日记，淦，昨天就去了公司计划的2道算法题完成了，之后弄好了阿里云的服务器环境，之前因为部署dnf换了，现在又换回来了，差不多就这些吧。', '2022-02-27', '2022-02-28 23:43:28', '2022-02-28 23:43:28', 1);
INSERT INTO `blog_diary` VALUES (829, 1, '今天把家里收拾干净了，本来是国庆要做的事情，但是因为国庆回家，乱了很多计划，今天把床上的衣服都洗完了，总之假期之后的生活可算是步入了正轨，之前因为看小说导致生活日程全部乱了，今天调整过来也来得及，小周要尽快完成项目。', '2022-10-23', '2022-10-23 23:11:26', '2022-10-23 23:11:26', 1);
INSERT INTO `blog_diary` VALUES (830, 1, '昨天周六的日记到今天周日晚上才开始补日记，昨天可算是从宾馆隔离结束了，除此之外也没去公司，最近这几周玩游戏真的好懒啊，下周要控制一下了。', '2022-03-19', '2022-03-20 22:14:46', '2022-03-20 22:14:46', 1);
INSERT INTO `blog_diary` VALUES (831, 1, '今天博客前端还写挺多，把登陆的那个菜单返回做完了，用户也可以鉴权登陆，现在感觉大体框架完成了，剩下的主要是复制粘贴，设计页面样式的内容，还有做动态路由，今晚刚刚把东西搬完，换了一个房间，现在东西很乱，等明天再收拾吧，每天去公司要对接ai模块了，还要把之前写的代码重新搬到另一个项目中，也不知道多久能对接完成，，今天就这样吧，有点晚了。', '2022-08-17', '2022-08-18 00:00:10', '2022-08-18 00:00:10', 1);
INSERT INTO `blog_diary` VALUES (832, 1, '今天也确认健康，毫无疑问我又苟活了一天，今天在公司的项目并不是啥也没干，今天开始了dssas的项目，不过只看了代码，具体要怎么实现还没开始考虑，最近虽说一直没阳，但还是感觉有些不舒服，不知道为啥天天特别饿，就想吃东西，还有就是可能带点头晕，不过不严重，几乎没感觉，不知道是不是因为饿的，反正就是特别想吃东西，最近还在看动漫，今天把电锯人看到了最新的11集，其它动漫还在寻找中，好像有点不太舒服，继续祈祷明天不会发烧吧，先休息了。', '2022-12-21', '2022-12-21 23:25:58', '2022-12-21 23:25:58', 1);
INSERT INTO `blog_diary` VALUES (833, 1, '周日去的方特东方欲晓，今天没怎么玩，可能是昨天玩太多，或者玩太刺激了，不知道为啥有点头晕，今天就完了一个突围和鹰击长空，其它的都没啥可说的，突围就是一个vr，比昨天的女娲补天差太多了，鹰击长空不出，算是过山车类的项目，比昨天的几个过山车都刺激，而且这个过山车特别稳，所以有些旋转之类的也不是很慌，今天就写这些吧，有点头晕，早休息了。', '2022-06-19', '2022-06-19 22:18:14', '2022-06-19 22:18:14', 1);
INSERT INTO `blog_diary` VALUES (834, 1, '这个周末真是模范周末啊，没玩游戏，俩天都按时吃饭，衣服都洗了，剩下的时间解决博客，真是完美的周末啊，斯巴拉西，今天处理博客shell脚本的问题，今天把博客各个模块都统一名字了，本来没这个想法，毕竟改名字太麻烦了，还怕某个地方没改出问题也找不到，主要是因为昨天在shell文件中加文件中心的代码，发现名字起的很乱，改的时候有点无从下手，所以就想要同意博客模块的名字，好在今天测试一天弄好了，下一步计划博客权限划分把，权限系统弄好，一直没使用，所有接口都是登陆就可以请求，最近一直没看前端，明天中午看看把，毕竟这个博客界面总得做，不然光有接口操作可太麻烦了，明天中午计划看40分钟左右，晚上七点到八点也看博客前端，然后就是项目了，上周那个导出excel的任务，项目名字忘了，周五任务结束了，现场也没问题，好像我写过了，周一就是空调控制的任务，听项目经理说不难，毕竟只给我俩天时间，明天先看吧，做完可以搞搞博客接口，今晚就这样。', '2022-07-17', '2022-07-17 23:28:48', '2022-07-17 23:28:48', 1);
INSERT INTO `blog_diary` VALUES (835, 1, '今天对接ai模块请求发送成功了，但是参数好多不清楚怎么获取，明天还要再看看，然后博客我自己写的界面太丑了，还有很多不规范的，css也是瞎搞，还是先看几个项目吧，之后再考虑怎么完成，都拖这么长时间了，也不差这几周。', '2022-08-19', '2022-08-19 22:58:30', '2022-08-19 22:58:30', 1);
INSERT INTO `blog_diary` VALUES (836, 1, '又熬过一天，没什么想写的，期待上班的第二天。', '2022-02-02', '2022-02-02 21:43:18', '2022-02-02 21:43:18', 1);
INSERT INTO `blog_diary` VALUES (837, 1, '对接ai的任务今天下发差不多了，顺便做好了任务的定时启动和结束，还有一些细节要再修改修改，这周虽然很累，总之任务还是按时完成了，今天还看了乌兰察布辅控任务，错误原因是动环联动的通道singalCode没上来，经排查是因为前端没推送上来，然后找原因找到了对应的那个字段，选这个的下拉框，这个没选就提交上来了，所以这个修改不需要动代码，前端加个限制就行，还有就是设备通道重复了，这个是因为导入通道数据不规范吧，最后报警还是不能正常使用，再排查找到一个通道，这个通道和报警配置的没对应上，应该是报警源和报警类型是同一个设备通道，这个也是前端给错了，排查下来好像不需要修改代码。有点累了，日记写的有点迷糊，就这样吧，还有买的电热毯和墙纸到了，昨天好像还有件事没记下来，先看看日记，想不起来了，还是尽快做完自己的app比较好，但是短时间我也做不出来，前端看这么久还做不出个样子，这个周末大周多看看吧，以后工作只会更忙。', '2022-08-25', '2022-08-25 23:18:20', '2022-08-25 23:18:20', 1);
INSERT INTO `blog_diary` VALUES (838, 1, '周六因为是小周所以必须要去公司，早上不太想起，去的稍微迟了点还被领导催，心累，好在今天去了也没啥任务，对接ai模块的因为项目经理没来，我也不知道该找谁，所以就写了写博客的接口文档，写差不多一半了发现飞不能导出md格式，感觉我要换个文档了，明天再找找，然后就是明天部署一下微服务，差不多是完成了，内容之后还会有一些小的修改，接下来就是开发其它模块了。', '2022-06-25', '2022-06-25 23:32:54', '2022-06-25 23:32:54', 1);
INSERT INTO `blog_diary` VALUES (839, 1, '周日实在是无聊，又开了一个缺氧新档，之前那个因为一时冲动开了debug，然后实在是因为没有成就玩不下去了，还玩了之前超凡送的啥旅图，好像是无尽旅图，又卡关了。', '2022-09-25', '2022-09-26 23:05:16', '2022-09-26 23:05:16', 1);
INSERT INTO `blog_diary` VALUES (840, 1, '最近人人都怕变羊，昨天应该是公司园区有几个阳性，上午都没多少人来了，我还是胃不舒服，好难受啊，都快一年了。', '2022-12-15', '2022-12-16 00:15:06', '2022-12-16 00:15:06', 1);
INSERT INTO `blog_diary` VALUES (841, 1, '博客后端第二版的重构今天把框架搞好了，主要就是security，没什么好说的，主要框架和之前学习的demo几乎没区别，可惜的是下午写的不认真，自定义的过滤器把过滤器链丢了，就直接导致调用接口没有任何报错，后端给出的响应也有，但就是前端页面上收不到数据，最后到晚上才解决了，除此之台今天没做其它的事情，明天要是还没有项目就继续博客的编写，接口逻辑并不打算有较大修改，预计这周完成吧，还有...算法题差四道，月底前完成，大概就这些。', '2022-03-29', '2022-03-29 23:22:34', '2022-03-29 23:22:34', 1);
INSERT INTO `blog_diary` VALUES (842, 1, '看了下昨天的日记，稍微补一句昨天健康码变黄了，忘了写，这是第二次变黄，心里完全不慌，甚至今天早上还用这个理调休了半天，今天下午过去看周末找我的黄河鑫业问题，现在是dp那边会有很多脏数据，这个今天猜想是因为我这删除的时候没做判断，默认dp都正常删除了，这个还是当时考虑不全，应该得有这个功能，今天下午过去加上，晚上又出现了新的问题，九点多了找我聊了半小时，看那个报错是我这下发了然后任务开启不了，也不知道dp那边是啥原因，每天去了再继续看，今天晚上回来在土耳其去冲了一百块，买了一个消逝的光芒，虽然以前玩过一点，但还是想买下完整流程通关一次，应该问题不是很大，主要怕我电脑不给力，换新电脑得早点提上日程了，但是最近又不想买，矿卡太多了，谁知道会买到啥样的，不写了，都一点了。草消逝的光芒下载好了，但是今天不能玩，这个周末试试，或者明天晚上，最近又开始博客更新了，大概俩个月没动，实在是因为这俩个月太忙了，最近才好点。', '2022-11-07', '2022-11-08 00:20:22', '2022-11-08 00:20:22', 1);
INSERT INTO `blog_diary` VALUES (843, 1, '周日看了几个视频，然后就去看比赛了，算是有一点点进度吧，但是还有俩天得快点了，大概20个视频，不过时间都不是很长。', '2022-05-29', '2022-05-29 23:49:24', '2022-05-29 23:49:24', 1);
INSERT INTO `blog_diary` VALUES (844, 1, '文明六和绍哲一起干到了四点。', '2022-11-25', '2022-11-27 00:44:04', '2022-11-27 00:44:04', 1);
INSERT INTO `blog_diary` VALUES (845, 1, '博客终于部署了，这个版本从开始到现在也五个月了，最满意的一键部署脚本也弄好了，之后我也考虑做一个web部署的功能，不过这个需要另外一个单独的项目，还有对应的前端，所以还是先等等吧，前端这个有点难，后端接口还行，现在的接口我这都熟练了，总之以后的事慢慢来，今天部署完成之后考虑功能修改和优化，现在功能主要放在博客写文章相关的地方，自动保存文章也得加上，这个问题之前遇到过，好不容易写那么多最后失误给关了，今天就这样，没怎么玩游戏，就坐着看视频了，今天肚子又有点不太舒服，抱着暖水瓶稍微可以舒服点，这个周末可都有按时吃饭，也算是稍微合格的周末了。', '2022-12-11', '2022-12-11 23:19:24', '2022-12-11 23:19:24', 1);
INSERT INTO `blog_diary` VALUES (846, 1, '当天开了一个缺氧，导致玩了一整天游戏，啥事没干。', '2022-09-10', '2022-09-13 23:04:26', '2022-09-13 23:04:26', 1);
INSERT INTO `blog_diary` VALUES (847, 1, '今天公司任务有了新的需求，要再次对admin项目进行修改，我最讨厌的那个项目，没有之一，要加一个对设备的过滤功能，比如某个user只能看到他有权限的设备，现在是可以看到所有设备，应该是查询设备要通过参数过滤，博客没时间开发，算法也没看，晚上看了下echarts，晚上回来在我的项目文件夹中新建的app的项目，要在2022年6月之前开发完成第一版，还有晚上做了2021年的年终总结，本来很早就写完了，但是因为我在博客后台在线时间过长导致我的博客掉线了，但是我并不知道，就点了提交，导致我第一次写的总结全没了，没错是第一次，所以我又花了快一个小时写了第二次，明天去了公司先做那个项目的需求，争取明天昨晚，然后就是算法题一定要来一道，晚上就稍微加个班搞搞博客的前端页面，回来还可以弄下安卓的新项目，编码肯定是不太可能的，毕竟一天也很累了，不过可以把项目的文件夹创一下，把app请求我后端接口的那个util弄好就差不多了，回家就打开的鬼灭之刃到现在还没看完，都快第二天了，现在12点睡觉都已经习惯了。', '2022-01-04', '2022-01-04 23:43:58', '2022-01-04 23:43:58', 1);
INSERT INTO `blog_diary` VALUES (848, 1, '昨晚三点才睡觉，今天很累，更烦的是那个菜单一直注册不上去，别人打包就能用，我这打包就报错，无语了。', '2022-10-17', '2022-10-17 22:45:34', '2022-10-17 22:45:34', 1);
INSERT INTO `blog_diary` VALUES (849, 1, '智慧加油站的项目明天应该就开发完成了，下午在测试，今天下午测试了一下下发dms的接口，我这边应该是没有问题，因为我发送请求得到的响应是成功的，但是响应里面的数据确实请求失败，我猜可能是dms掉设备的时候请求参数错误，导致设备那边报错，然后dms直接把设备返回的报错信息给我了，一定是这样，不然我真不知道该怎么处理... 明天上午尽量把最后的一点代码写完，不过这个测试还得等dms把那个请求的bug修复之后才能测试。今天五点下班就溜了，回家本以为能认真的开发接口，没想到一心二用看lol比赛，不过也凑合，把内衣洗了，博客标签的差不多也开发完成了，总之还算凑合，忘了一件事，下午快下班那会也没继续那个智慧加油站项目，看一下油猴脚本，写了一个解析json的网站界面整理的一个小脚本，可能有歧义..，不过算了日记也不会被其他人看到，今天中午都没睡觉就为了晚上别失眠，已经失眠五天了，我今天早点睡。', '2022-06-15', '2022-06-15 22:33:34', '2022-06-15 22:33:34', 1);
INSERT INTO `blog_diary` VALUES (850, 1, '胃里好酸，太难受了，今天做了一道题，没什么难度的水题，博客也稍微写了下，晚上玩dnf，现在有些难受不写了。', '2022-03-04', '2022-03-04 23:47:20', '2022-03-04 23:47:20', 1);
INSERT INTO `blog_diary` VALUES (851, 1, '昨晚吃瓜忘记写日记了，看佩罗西去台湾，本以为会有什么严重的后果，没想到等来的却是强烈谴责。昨天公司的项目是控制一个继电器的任务，fsugw模块的，这个模块以前没做过，而且gitlab的仓库都是昨天才创建了，拉好代码之后结果不用我做开发了，由动环的人做定制，然后就没怎么看代码，博客主要是新建日记管理页面，算是刚刚把日历弄好，使用了几次ant design的日历组件总之就是非常不满意，好多东西都不能自定义，还是自己从网上找一个自己做日历比较好。', '2022-08-02', '2022-08-03 09:18:46', '2022-08-03 09:18:46', 1);
INSERT INTO `blog_diary` VALUES (852, 1, '早睡周才第一天就没做到，实在是生气，今天开了盐与避难所第一个boss就被虐了，所以越打越来气，所以就晚睡觉了，项目今天提交了，虽然有些bug，但最后还是都改完了，总的来说问题不大。', '2022-05-17', '2022-05-17 23:34:26', '2022-05-17 23:34:26', 1);
INSERT INTO `blog_diary` VALUES (853, 1, '今天开始了开发经验库的功能，ftps连接不成功的这个问题也反馈了，这个问题我是真的无从下手，根本就没有思路，这样稍微好点了，大佬解决的时候我也学习学习，新算法明天开始调试，我估计最早也要明天下午，尽快吧，经验库这个肯定不能因为我这的进度影响了开发，今天完成一个接口，还有修改了之前算法更新的接口，之前只是取出code值然后和返回的列表去匹配，这样本来是没有问题的，但是如果有一个算法对应多个报警，或者说一个算法用于多个算法功能的实现，这样就会导致匹配的时候数据丢失，不过今天这个问题已经解决了，以我配置的算法表为主表，这样就没问题，晚上回来玩了会缺氧，第二个火箭的鱼蛋卷模块已经更新好了，预计不久就可以发射第二艘火箭，也可能会很久，因为第二艘火箭我要使用超冷。', '2022-09-19', '2022-09-19 23:51:32', '2022-09-19 23:51:32', 1);
INSERT INTO `blog_diary` VALUES (854, 1, '今天没有做任何事情，先看看周五应该的计划内容，周四没写计划，然后周四应该的计划是搭建博客前端vue的框架，这个周四是做了，但是稍微有些问题，该怎么说呢，因为vue是使用可视化页面搭建的，所以弄出来没有config和build目录，其它目录结构也和我之前的不太一样，然后我用引入了font awesome这个图标库，引入的方式和之前是一样的，但是不知道为什么就是出不来图片，这个问题一直没解决了（其实也就是周四没解决，周五没时间看），然后就是前端调接口的这个没弄好，因为不知道要怎么弄，我之前是把axios封装过一次，然后调用我封装好的方法，但是学习的前端视频中的写法也是封装的，我现在不太愿意放弃我之前封装的方法，视频中学习的这种方式也不能舍弃，因为后端就是按照这个来的，这个也要解决，其它的问题还好把，前端把旧版的搬过来就行，稍微整理一下格式，关于工作学习的就写这么多。今天看完了双城之战，可惜的是只有9集，还没看过瘾就没了，总的来说我感觉动漫质量非常高，特效也很棒，印象最深的就是瑞兹的那个传送，特效拉满，而且非常流畅，其它关于剧情的我不太会评价，差不多就这样把，实在是不会评价动漫，对比现实我也是一个祖安人；剩下的时间就躺床上玩空洞骑士，二周目了还在三螳螂卡了好久，算了我就不写流水账了，明天要早点起床去医院看病，希望问题不大吧。', '2022-04-09', '2022-04-11 22:12:54', '2022-04-11 22:12:54', 1);
INSERT INTO `blog_diary` VALUES (855, 1, '明天又要上班了，社恐人士要准备年底答辩了，但是这次应该不会给我过，才升了岗级，不能这么快就给我升职级吧，今天在家打了一下午消光，一直没推进主线，玩支线，解锁安全区才有意思，下午还把博客安装包启动的脚本弄好了，本以为前端打包完成放上去，nginx启动就行，没想到打包报错了，平时都可以正常执行，不知道为啥打包就会报错，看报错原因是ts中有js，这些完全不懂啊，我觉得能写出来执行不报错就不错了，没想到打包的时候还要校验一次，不过也行，在花一周时间完善下，然后在公司也解决下这个问题，明天还要准备答辩的稿子，可以参考下去年的稿子，项目我还算熟悉，应该不会问到我太难的问题，今天合租的这还吵架了，不知道是谁把厕所的门开了没关好，风吹着一直响，然后那个住户就以为是我，就吵起来了，还好最后解决了问题，不至于有太大的矛盾。', '2022-11-13', '2022-11-13 23:23:56', '2022-11-13 23:23:56', 1);
INSERT INTO `blog_diary` VALUES (856, 1, '人生第一次做梦中梦，第一个梦是见了个高二女网友一起在外面聊天，周围还有好多人在捉麻雀，我们应该是在一个平台上坐着，有个麻雀飞过来了，我们准备下来，不小心把冰棒弄地上了，我捡起来丢到了旁边的垃圾桶，这时候梦醒了，我醒了看了看手机是九点零九，然后我说估计今天又要用调休了，前几天才刚刚调休过一次，而且周围还有一男一女在抱怨另一个女生洗衣服吧，估计是我梦中的合租舍友，但是这也不应该住一起吧，然后我就起床，随手拿起一件半袖穿，把衣服翻正之后看到那个不是我的半袖，问旁边那个女生她说是她的，然后我就醒了，是被我自己的闹钟叫醒的。这次做梦有些奇怪啊，第二个梦明明知道睡的那个房间不是我的房间，还是没感觉出来那是在梦中，而且上班迟到的感觉好真实啊。先贴上昨晚做的梦，因为印象特别深刻，所以写到了日记中，然后就是最近oauth2的学习进度（最近我都没活干，不会要被辞退吧T_T），还是鉴权这块问题最大，现在打算在整理下我的鉴权中心，计划token使用jwt，之前使用的随机字符串还是弃掉吧，说一下原因吧，因为下一个博客计划是做一个社区版本的，所以会经常有一些需要用户信息的接口，比如我要查询当前请求用户的文章信息，这个如果使用之前的方式我就只能再用户登陆的时候将用户的token和用户名放到redis中，等用户调用查询个人博客文章接口的时候就需要先从请求头中取出token，再根据token从redis中获取用户名，之后使用用户名调用用户服务查询用户信息，最后才能取出用户id获取他的文章，这个调用链路实在是太长了，而且我买服务器性能也不可能太好，所以优化服务接口这个必须要考虑上，所以就打算使用jwt，换成jwt之后要是用户获取个人文章信息我就可以直接解析jwt取出用户的id，然后查找数据库，这样只需要一次就行，而且不用调用其它服务，当然这个只是我理想的方式，具体能不能这样明天再去看看，不过大概率是可行的吧，因为jwt可以存储一些信息，还有另外一个问题使用jwt之后也可以很方便的解决，就是我的已经登陆了，但是我要查询别人的主页博客文章，只需要传入当前要查询的人的id即可，在后端如果有token，我可以解析token判断这个用户是不是自己，如果是自己本人可以有一些快速编辑的路径也行，如果不是只返回文章，具体参考csdn，还有解析token明天去了看看能不能通过自定义注解来实现，这个也是初看，具体还得明天写demo测试，反正最近没啥项目，总不能闲着。', '2022-06-09', '2022-06-09 23:18:00', '2022-06-09 23:18:00', 1);
INSERT INTO `blog_diary` VALUES (857, 1, '周六今天去了西溪游玩，因为西溪湿地水很多，每个景点都需要坐船前往，所以买的船票是60，然后坐船依次走的四个风景区，感觉每个景区都差不多，就那几个样式，去西溪主要也就是玩水，还有第一次坐船，坐船转弯都是漂移，太爽了，要是有机会开船可以试试，晚上去西湖旁边吃了个饭，最后去公司躺一躺新工位，太棒了，今天还是没话说，就这样吧，都快一点了。', '2022-07-23', '2022-07-24 00:54:12', '2022-07-24 00:54:12', 1);
INSERT INTO `blog_diary` VALUES (858, 1, '上周那个项目在今天被导师找到了bug，无奈只能继续修改，花了一下午时间可算了考虑到了所有查找的可能，并且自己测试也通过了，等导师过来评审完代码准备结束这个项目，没想到过来直接就把我写的全部注释了，然后通过传入参数解决，我TM吐了，操啊，一下午辛苦全白费了，再次吐槽一句admin项目结构真烦，要不找段时间看看struct2框架吧，反正学啥都是学，Java后端这块弄的明白些，其次再学习其它语言的框架，晚上培训icc去听到了9点，下班回来就9点40了，今天因为路上有雨，所以骑车比较慢，从今天开始我要开始玩玩单片机，初学就用到arduino uno板子，先做一个3*3*3的光立方，然后在做一个指纹结束的模块，这个不一定用到我的房间，只是因为有需求，所以做一个玩玩，房间就找时间再配一把钥匙放在门口鞋里面就好。还有今天发工资了，但是我忘了招商银行的登陆密码，不知道该咋搞，短信登陆也收不到验证码，明明我手机号没问题。', '2022-01-10', '2022-01-11 00:01:18', '2022-01-11 00:01:18', 1);
INSERT INTO `blog_diary` VALUES (859, 1, '今天上班有些累，因为第一天睡宾馆有些不习惯，昨晚没睡好，白天有些了，白天依旧没做题，不过项目这个任务做完了，个人测试也没问题，每天去了除了学习Spring Security之外还要看看算法题，可能明天还要加班吧，不过还可以，也可能早回来玩dnf，看情况。累了，睡觉。', '2022-03-10', '2022-03-10 23:25:16', '2022-03-10 23:25:16', 1);
INSERT INTO `blog_diary` VALUES (860, 1, '稍微有点迟了，就简而言之吧，今天处理了一个现场问题，还有桐昆的一个bug，不过bug应该是还没解决，晚上学习nacos，遇到点问题，一直处理到现在还没解决，都快十二点了，明天在看吧', '2022-05-23', '2022-05-23 23:41:22', '2022-05-23 23:41:22', 1);
INSERT INTO `blog_diary` VALUES (861, 1, '做核酸，准备返杭，看电子书。', '2022-10-05', '2022-10-10 22:53:40', '2022-10-10 22:53:40', 1);
INSERT INTO `blog_diary` VALUES (862, 1, '新开坑的泰拉瑞亚打完了克眼和史莱姆，这周就继续玩泰拉瑞亚吧，今天收到通知，杭州不再要求做核酸了，以后防疫就靠自己，还有今天上午调休，还有因为国家领导人过失然后就让全国禁游戏一天，臭打游戏的果然好欺负。', '2022-12-05', '2022-12-06 00:20:40', '2022-12-06 00:20:40', 1);
INSERT INTO `blog_diary` VALUES (863, 1, '今天redis优化的任务完成，又来一个新的具体没看，明天开始这个任务，所以今天就不记录这个任务的内容了。博客的shell脚本开发先停一下，因为现在能做的都做好了，今天看前几天的那个vue视频开始开发我博客的前端界面，css引入了tailwindcss，下午测试使用的时候感觉不错，没啥想写的今天就这样。', '2022-07-05', '2022-07-05 22:43:26', '2022-07-05 22:43:26', 1);
INSERT INTO `blog_diary` VALUES (864, 1, '今天调试门禁人脸下发的功能，我这边是没问题了，但是门禁返回的有点问题，所以今天没测试完成，明天看门禁那边怎么样吧，对接ai的今天把下发事件中心的任务完成了，明天应该做定时任务这个，和作业管控之前的定时任务不一样，之前那个是定时开启和停止任务，是在一个时间段内，明天要做的是在任务开启的时间段内再次细分任务是否执行，比如我要在一天的白天时间执行任务，晚上停止这样的。今天项目不是很忙，晚上稍微看了看博客，虽然没写多少，今天也是八月底，这个月总体还是很忙的，幸好博客没定在这个月完成，国庆回家之前应该能部署一个非常简陋的版本，所以九月份我尽快吧，也不知道下个月会忙不忙，反正对接ai的这个任务还得很久，有个经验库还没做，可能还有其他的需求，大概就这样吧，不太想写了，最近确实有点懒。', '2022-08-31', '2022-08-31 23:01:26', '2022-08-31 23:01:26', 1);
INSERT INTO `blog_diary` VALUES (865, 1, '今天稍微反省了一下，每次周末都休息不好，啥事也不做，今天分析原因我觉得还是因为没有按时吃饭，因为没吃饭，所以下午就没什么干劲，每个充实的周末都肯定会按时吃饭的，所以制定一个计划，就算九月份每个周末都要保证每天去按时吃饭，当然早饭可以随便吃的零食，最近也在屯一点零食，上次吃完之后就再没买。还有上午调休，中午去了公司收到了中秋礼盒，今年的礼盒就挺好的没有那些花里胡哨的东西，月饼加个盲盒我觉得不错，公司项目就是继续黄河鑫业算法下发任务的开发，这周主要就是把旧算法下发调试完成，然后就算时间模板这个功能做完，不过今天去了把代码都写完了，明天过去测试完成这个功能，然后就可以开始算法配置的修改了，一周时间应该是充足的，晚上熊勇大哥给了一个新的任务，不过不着急，等我这周的任务完成之后再看。还有今天开始公司晚上领水果时间变了，之前是八十分牛奶面包，九点再加上水果，现在八点半就都有了，感觉还是可以的。', '2022-09-05', '2022-09-05 23:23:56', '2022-09-05 23:23:56', 1);
INSERT INTO `blog_diary` VALUES (866, 1, '周五不是很忙，这周就看微服务的这个视频，明天上午可能会玩群星，这周算是学习Java的周末。', '2022-04-22', '2022-04-22 23:03:48', '2022-04-22 23:03:48', 1);
INSERT INTO `blog_diary` VALUES (867, 1, '周六继续躺一整天，不过到晚上好点了，至少有点精神了，明天就要继续博客的修改，争取月底做完。', '2022-08-13', '2022-08-13 23:43:18', '2022-08-13 23:43:18', 1);
INSERT INTO `blog_diary` VALUES (868, 1, '周一没有新的项目，白天有个测试之前写的接口的任务，但是没给设备，添加不了，所以就没干啥事情，因为这个月缺了好几道算法题，本想着今天补几道，但是没心情就没写，下午抽时间看spring security算是有点进度吧，vue等看完这个在看，后端优先，最近打王者，钟无艳真强。', '2022-03-14', '2022-03-14 23:54:08', '2022-03-14 23:54:08', 1);
INSERT INTO `blog_diary` VALUES (869, 1, '今天开发了经验库的四个接口吧，进度还算可以，明天要完成大部分接口，因为后天要测试，即使这么忙，下午还要看现场ftp连接不上的问题，按照新的demo参考修改完成了，但是使用weci打包失败，我猜应该是那个jar包的问题，因为在公司maven仓库中没这个包，之后我使用本机打包发给了现场，不知道会不会有问题，先就这样吧，有问题再说。今晚早下班，然后八点半又去公司嫖一个餐补，白嫖是真的快乐。', '2022-09-21', '2022-09-21 23:39:52', '2022-09-21 23:39:52', 1);
INSERT INTO `blog_diary` VALUES (870, 1, '今天又是任务繁忙的一天，不过今天确实很高效，把昨晚定位的华能澜沧江bug改了，今天内部测试发现其它地方也不能正常显示海康门禁设备通道的问题也修改了，然后是黄河鑫业项目之前提出的一大堆bug都改完了，其它的bug之前都大概知道怎么修改，主要是导出压缩包这开始一直没定位到是什么原因，最开始以为是请求oss图片重复的原因，虽然这个原因可以解释大部分情况，但是之后总觉得还有点问题，因为我提交完问题单之后发现一个无法解释的情况，但当时问题单已经提交了，后续继续测试也没找到原因，最后看代码突然就悟了，我是要把文件放到压缩包里去压缩，但是忘了确保要压缩的文件名字唯一，这样就导致名字重复的文件在压缩的时候被覆盖了，这样也会解释我最初找到的重复图片去重，其实本质是因为上传的图片名字是一样的，最后还有广州中国石化项目，这个上报盈科的代码写好了，明天过去测试，项目进度控制正常。晚上看璐瑶给写的好多问题，好多都不知道要怎么回答，这个就一笔带过吧，如果有后续也不差这一天的记录，没有也就那样了，至少我认为是尽力了，不至于后悔，今天就写这么多，这个周末是大周，周日看看前端，差点忘了，今晚看阿根廷账号不能充值了，没办法只好去当云土耳其人，九块买了哈迪斯，过去竟然要四十八，这羊毛不薅白不薅，又快十二点了，赶紧睡觉，明天是周五不是周六。', '2022-10-27', '2022-10-27 23:39:32', '2022-10-27 23:39:32', 1);
INSERT INTO `blog_diary` VALUES (871, 1, '国庆第一天，因为昨天晚睡，今天起来就下午了，然后急急忙忙去做了核酸检测，还好今天小区有核酸检测，我怕人家国庆第一天休息，然后下午到晚上开了群星联机，还有之前的水果都坏了，晚上下去才丢的，以后有水果一定要及时吃，明天是早上七点的火车，定五点的闹钟，要早点出发。', '2022-10-01', '2022-10-01 22:57:50', '2022-10-01 22:57:50', 1);
INSERT INTO `blog_diary` VALUES (872, 1, '十一点了粗略的写一点睡觉，博客新增了文档内容的几个接口，然后还需要和文档目录的对接一下，把对应的功能绑定，项目还是改bug，浙江那个ar全景添加标签失败的具体好没好一直没说，然后就是今天修改系统自定义菜单无法添加的bug，问题出在eims，今天把版本恢复到之前的版本暂时是可以使用了，具体相关细节之后再说，睡觉。', '2022-06-21', '2022-06-21 23:04:02', '2022-06-21 23:04:02', 1);
INSERT INTO `blog_diary` VALUES (873, 1, '可算是熬到周五放假了，那个接口还有一点点没做完，是关于服务器的那个都测试没什么问题，晚上就玩游戏，现在都半夜俩点了。', '2022-05-13', '2022-05-14 01:44:00', '2022-05-14 01:44:00', 1);
INSERT INTO `blog_diary` VALUES (874, 1, '马上就可以上班了，最近都是一整天都在睡觉，今天嗓子着还是难受，不知道为啥堵得慌。', '2022-02-06', '2022-02-06 23:54:42', '2022-02-06 23:54:42', 1);
INSERT INTO `blog_diary` VALUES (875, 1, '今天俩个项目，对接海康的门禁设备卡片下发现在是没问题了，还有一个人脸下发没调试，这个是因为第三方设备没有人脸下发这个功能，所以每天需要改这个，下发逻辑改成是否为第三方设备，如果是第三方设备就下发人脸和卡片，正常的大华设备下发逻辑不修改，今天还做了对接ai的这个，主要是上报事件中心将算法和报警事件绑定，因为是要改善用户体验，所以算法对应的报警类型要在代码中写死，我计划加个数据库将算法和报警事件绑定，这样后续维护只需要维护数据库就行，对接ai这个今天主要是澄清需求，之前说的太乱了，还有我把新的算法code发给了前端，这个加好算法下发的config，这个任务就大概差不多了，连续忙了俩周，博客啥的完全没看，周末也只想休息会，希望开发完成这个需求之后下一个项目能够稍微简单点，最好时间也不紧张。', '2022-08-30', '2022-08-30 23:28:52', '2022-08-30 23:28:52', 1);
INSERT INTO `blog_diary` VALUES (876, 1, '因为打游戏忘了写日记，不过确实没得写，因为一直在玩游戏。', '2022-01-15', '2022-01-16 22:44:06', '2022-01-16 22:44:06', 1);
INSERT INTO `blog_diary` VALUES (877, 1, '长话短说吧，今天上午调休了，结果下午去上班忘了打卡，明天应该是可以补卡的，然后就是最近桐昆的项目真是痛苦啊，下午把新的需求调试好了，然后就是修改bug，现在要了解ss服务具体是干啥的，了解下协议，这个明天去了主要看这个，晚上继续看微服务，这个月应该是可以完成，但是算法题可能有点困难。', '2022-05-30', '2022-05-30 23:17:52', '2022-05-30 23:17:52', 1);
INSERT INTO `blog_diary` VALUES (878, 1, '今天把oauth的demo搭好了，感觉可以试试先写一个微服务的架构，计划使用阿里巴巴体系的微服务，带网关、鉴权中心，监控的一些服务暂时不写，下一个微服务的demo主要是看看oauth的配置要怎么搞，明天就开始。', '2022-06-04', '2022-06-05 00:22:38', '2022-06-05 00:22:38', 1);
INSERT INTO `blog_diary` VALUES (879, 1, '小周还是好累，在家一整天都不想学习，然后每天就又要上班了，也不能调休，项目还很着急，好累啊，今天甚至考虑我为啥要工作，也不知道挣钱干啥，向小学的时候我的任务就是考初中，大学的任务就是找工作，一直都有一个明确的目标，但是现在就不知道为啥要工作，除了为了能吃口饭想不到其它的理由，现在有自己的工资了，攒的钱也不知道想要做什么，买游戏没时间玩，周末也懒得开游戏，买其它电子产品我也没啥想要的，就算是买零食我吃的也少，而且就算买也花不了多少钱，然后攒钱结婚，买房买车这个还是算了吧这辈子不可能当房奴、车不太喜欢，有个电动车就行，我是不可能在再舔狗了，应该不会有人瞎了看上我吧，最近餐厅吃饭是不会像之前那样抠抠搜搜了，一是因为涨了工资，再就是攒钱也没啥想要的，就算有要买的也不会很贵，所以最近吃饭就想吃啥吃啥，大概就这样吧，虽然现在没有长期目标，但是短期目标还算有的，最近九月就先把博客搭起来，界面丑也无所谓，重要的是搭起来，然后慢慢修改。其实最近突然有了去各种娱乐场所逛逛的想法，找个店泡个脚，出去嫖，做一些以前没做过的事情，我再也不想当父母眼中的乖孩子了，我要放飞自我、享受人生，这个不知道会不会有人去带我体验第一次，然后我第二次就轻车熟路了，哈哈哈，可能还是不太现实，因为我还是很内向的，但是不影响我有这个想法，万一呢。', '2022-09-04', '2022-09-04 23:40:56', '2022-09-04 23:40:56', 1);
INSERT INTO `blog_diary` VALUES (880, 1, '今天把金华的那个项目做完了，至少我这边接口都开发完成了，导出表格没有问题，今天写的俩个接口其实可以算是一个，整了一天，实在是因为这个接口涉及的数据库太多了，查表要考虑好多情况，好在晚上都修改完成，到目前位置项目进度还是处于可控范围的，明天和前端联调，然后葛老板要在现场环境测试，这个说实话有点慌，虽然本地测试没什么问题，但是每次到现场环境就会慌，万一出啥问题我还得担责任，搞不好工作都没了，明天项目会闲一点，计划修补一下接口，优化啥的，上传功能优化一下，可能在加个日志中心，最近还是重心放在后端微服务上面把，今天下载了一个前端的实战项目视频，先看完这个视频再继续开发我的博客，说起来我好像还没系统的看过前端的实战开发视频，之前的博客界面都是这抄一块那搬一块，就那样拼凑起来的，2.0的博客前端要做到完美一点。', '2022-07-12', '2022-07-12 23:43:06', '2022-07-12 23:43:06', 1);
INSERT INTO `blog_diary` VALUES (881, 1, '小周？不过是换个地方吹空调玩手机罢了。', '2022-08-20', '2022-08-20 23:37:54', '2022-08-20 23:37:54', 1);
INSERT INTO `blog_diary` VALUES (882, 1, '该写啥呢，今天学习了拓扑排序，基本的算是明白了，后来看的状态压缩dp还不清楚，博客前端页面有想法但是不会写，也要看看前端的视频。', '2022-01-21', '2022-01-22 00:08:48', '2022-01-22 00:08:48', 1);
INSERT INTO `blog_diary` VALUES (883, 1, '升职的ppt写的太烂了被领导批评，估计这次是没戏了，不过也无所谓，再呆一年左右就离职，找个工资高点的，今天去理发了，算了不写这个了。今天项目把那个接口稍微整理了下，存储功能快下班才弄好，所以今天没开始测试，还有五天，时间应该是足够的，下周继续吧，明天看看视频，玩玩游戏，不做计划。', '2022-05-07', '2022-05-07 23:26:06', '2022-05-07 23:26:06', 1);
INSERT INTO `blog_diary` VALUES (884, 1, '今天虽然是周六，但是实在是不想呆在家，就去了公司，写了这周做的三道算法题的解析，记录一下，不过还有一道题不是很明白，虽然明天是周日，但我还是想过去，毕竟呆在家太烦了，明天看吧，可能去了要出去理发，今天的嗓子这好多了，明天就不去医院了。晚上回来看三国演义上瘾了，一口气好几集，不过古人带兵作战确实牛逼，就依三国演义来说司马懿和诸葛亮博弈完全是输在了猪队友身上，还有看三国里面古人是真的会骂人啊，啥诸葛村夫、司马老贼、三姓家奴一个比一个有特点，招招命中要害。', '2022-02-12', '2022-02-13 00:31:14', '2022-02-13 00:31:14', 1);
INSERT INTO `blog_diary` VALUES (885, 1, '今天来了好多事情，要测试海康的门禁，还有ai下发，还有一个机器人现场问题，虽然一个都没解决，要留给明天看了，这周应该也会很忙。', '2022-08-29', '2022-08-29 23:05:26', '2022-08-29 23:05:26', 1);
INSERT INTO `blog_diary` VALUES (886, 1, '今天上午调休，下午继续看机器人的现场调试，弄了ftp的服务器，之后机器人那边又让去测试，我测试发现还是不能正常开始巡检任务，最后和机器人确认，结果是双方互推责任，机器人那边也不想开发，icc我看他们是想让机器人来做，不过反正没我的责任，我测试找到问题就行，现在应该是机器人这个项目结束了吧，不知道下一个任务是什么，博客今天把日记模块的日历单独做了一个组件，明天继续修改。', '2022-08-03', '2022-08-03 23:53:48', '2022-08-03 23:53:48', 1);
INSERT INTO `blog_diary` VALUES (887, 1, '周六又是通宵玩游戏，早睡周的最后一天没做到，周六看了看vue的视频计划去整理笔记结果晚上回来就打游戏没注意时间玩到了晚上俩点，其它事情没啥可记得。', '2022-04-16', '2022-04-17 22:19:56', '2022-04-17 22:19:56', 1);
INSERT INTO `blog_diary` VALUES (888, 1, '因为周六小周，所以今天一整天都不愿意起来学习，还是躺着舒服，然后就躺了一整天，明天再努力吧。', '2022-08-07', '2022-08-07 23:32:14', '2022-08-07 23:32:14', 1);
INSERT INTO `blog_diary` VALUES (889, 1, '今天继续摸鱼，主要测试下发dms这块功能，还有修改了一点算法预案的保存逻辑，新增了名字校验，这些工作量都可以忽略的，反正摸鱼快乐，晚上我们Java组去聚餐吃饭，自助179呢好贵啊，第一次去这么高档的地方，反正花的不是自己的钱不心疼，我就正常吃饱就好了，本来也不是爱吃什么山珍海味的人，随便吃点大厨做好的熟食就行，我看旁边还有好多活的螃蟹龙虾等等很多海鲜，然后拿回来直接开煮，倒不是说感觉很残忍，至少自己煮好的能有啥味，唯一的调料就是自己配的蘸料，只能说这种吃法不适合我，吃了一个外面一些很细的面包裹的东西，我以为里面会是虾，没想到是榴莲，服了，是真的服了嘴里到现在还有榴莲的味道。博客今天前后端都写了，后端主要是改原来的接口，前端就适配新改的接口，博客这个月总不能再拖了吧，给本月底的我自己留个言。对了现在去楼下给自行车打个气。', '2022-11-03', '2022-11-03 23:09:30', '2022-11-03 23:09:30', 1);
INSERT INTO `blog_diary` VALUES (890, 1, '昨天的抓图bug修改完成了，今天又接一个项目，大体上有想法了，等明天给了测试环境可以测试一下，今天剩下的时间就看看oauth2，自己做了个demo但是没跑起来，很烦，有时间继续，这周的三题还没开始，上周还有一道题没完成，睡觉吧。', '2022-03-08', '2022-03-08 23:08:54', '2022-03-08 23:08:54', 1);
INSERT INTO `blog_diary` VALUES (891, 1, '又是爆肝一天游戏，12车，再次刷新了记录，下周的任务会很多，首先周一周二要完成葛老板的任务，这个是优先级最高的，然后就是要做6道算法题（本来一周三题，因为前几周在拖，所以要补上，下下周补剩余的），然后就是要跟着继续spring security的项目，周末没搞，太懒了，等了半小时写不出来了差不多就这些，希望明天有进步。', '2022-03-20', '2022-03-20 23:00:02', '2022-03-20 23:00:02', 1);
INSERT INTO `blog_diary` VALUES (892, 1, '今天是公历的生日，收到了公司的祝福，项目就门禁和算法这个，这俩个都是调试bug，还有广东石化的项目，今天没怎么看，给了七天开发时间，可能算是充足吧，因为没仔细了解。', '2022-10-12', '2022-10-12 23:15:46', '2022-10-12 23:15:46', 1);
INSERT INTO `blog_diary` VALUES (893, 1, '忙碌的一天，没干多少活，倒是问题不少，报警的还没解决，这个就等dms那边给类型了，我这没什么可以修改的，然后就是门禁子系统又出问题了，这个也不知道咋处理，看日志就是一个简单的空指针问题，但是我不能debug，只能阅读代码，看了半个下午感觉大体位置找到了，不过后来这个bug没说怎么解决，就让换个版本打包发到现场，不过换完版本的还有问题，只能周一去看了，计划是明天开始博客第二版的开发，但是因为水平不够，第二版还就是spring boot+spring security的开发吧，暂时不做微服务的，这次写之前把名字等都定义好，尽量写的完整一点，然后就是接口文档也写上，稍微规范一些，等之后开发微服务版本的博客的时候看文档也不那么困难，前端也重构一下，主要是路由的问题，在就是名字起的规范一下，第一版本感觉很乱，还有几个名字重复了，前端就等看完markerhub的视频在开发，暂时计划就这些，明天优先算法题，到月底了。', '2022-03-25', '2022-03-26 00:12:08', '2022-03-26 00:12:08', 1);
INSERT INTO `blog_diary` VALUES (894, 1, '最近的计划不太好写计划，怎么说呢，前端本来就不怎么会，再定计划总是完成不了，稍微优化一下，明天计划就是把vue的那个视频看至少5集，然后一道算法题，找时间做吧，工作应该不至于很忙，这样计划就明确了，明天晚上也好评价是否完成，今天算是把项目完成了，俩个项目现在都差测试接口，eims的那个今天部署到服务器上，但是好像服务器有别人使用，就没测试完成了，明天上午过去用我现在的这个服务器测试一下，希望问题不大吧，其它事情应该没了，今天水痘又多了几颗，白天可能是衣服的原因，明天换一件半袖。', '2022-04-11', '2022-04-11 22:41:18', '2022-04-11 22:41:18', 1);
INSERT INTO `blog_diary` VALUES (895, 1, '今天也不是很忙，现场的项目都没人找我，就算今天大降温，昨晚一直刮风，今晚估计也风很大，明天要大降温，稍微再穿厚一点，最近看前端的vite项目打包，在公司以为是下载不了我需要的哪些依赖包，没想到回家还是不行，明天去公司再抽时间看看吧，还是得尽快完成项目部署。', '2022-11-29', '2022-11-29 23:41:46', '2022-11-29 23:41:46', 1);
INSERT INTO `blog_diary` VALUES (896, 1, '三天了，高强度工作，今天作业任务对接ai的各种接口都没啥问题了，现在难点是作业任务原有逻辑从下发ivs修改到下发ai，今天没看明白，明天去了在看看，就这样了，有点累。', '2022-08-24', '2022-08-24 22:38:46', '2022-08-24 22:38:46', 1);
INSERT INTO `blog_diary` VALUES (897, 1, '五月二日没有上午，下午继续昨天开的群星，好在晚上七点多打完了，这次没有玩到半夜，主要是也累了。', '2022-05-02', '2022-05-04 23:40:54', '2022-05-04 23:40:54', 1);
INSERT INTO `blog_diary` VALUES (898, 1, '昨天实在是太累了，躺床上完全不想动，做完还看了看git，可能是很久没更新了，导致git失效，这个周末配置下看看，昨天主要是改config的配置，然后今天下发算法测试，调到了晚上八点半，到现在算法下发都没问题了，大部分算法的报警也上来了，报警没上来的那几明天去了算法那边看，我这是作业广场没产生报警记录，应该是要我这主动去订阅报警，这个需要明天我去看看，今晚还看了机器人的问题，这次俩个问题，多次启动任务不会产生记录这个问题是机器人的，一个任务不能下发多个机器人的点位这个是平台的问题，但是因为现场用的这个是第一次发测的包，这个问题在后续的版本中修复了，也不知道为啥现场还是用最开始的版本，今天进度可以，明天继续加油。', '2022-09-15', '2022-09-15 23:32:42', '2022-09-15 23:32:42', 1);
INSERT INTO `blog_diary` VALUES (899, 1, '主管找我进行了访谈，主要说了最近的情况，和遇到的困难，也灭别的其它事情，4月份可能就要去公司新的地方，到时候再找房子。', '2022-02-17', '2022-02-17 23:15:00', '2022-02-17 23:15:00', 1);
INSERT INTO `blog_diary` VALUES (900, 1, '周五弄好了MySQL的编译安装，然后测试了将近一整天可算是吧服务器一键部署弄好了，项目今天来了一个redis优化的任务，主要是因为这个接口要请求好几个服务器节点然后整理各个服务器的数据最终返回，因为要请求好多接口，导致这个接口响应就很慢，我的任务就是写个定时任务每天晚上请求接口把数据放到redis中，白天请求的时候直接查redis，虽然这样数据会延迟，不过听说现场对这个变化要求不高，所以下周等任务就是把这个定时任务完成。', '2022-07-01', '2022-07-02 00:49:58', '2022-07-02 00:49:58', 1);
INSERT INTO `blog_diary` VALUES (901, 1, '阳了第五天，今天就是瞌睡，下午睡了一觉，现在就感觉鼻子难受，想打喷嚏但是又打不出来。', '2022-12-26', '2022-12-26 22:21:48', '2022-12-26 22:21:48', 1);
INSERT INTO `blog_diary` VALUES (902, 1, '工资到账了，慢慢攒钱确实快乐，还有今天我旁边的那个同事走了，差不多也习惯了，当时实习的那个公司离职率更高，我实习没多久时间就有好几个人离职了。昨天说好的要解决token鉴权的这个问题，昨晚想的是通过自定义注解来解决鉴权用户请求数据的这个功能的，但是发现注解里面解析jwt是可以拿到用户的账号，但是用户id在jwt里面没有，之后考虑下能不能给jwt里面添加个自定义的字段信息，如果不能也还有其它解决方式，这个现在已经问题不大了，然后就是博客的token今天改成了jwt，mybatis-plus的测试也没问题，今天对oauth2的理解感觉又深了一点，今天的进步还是很大了，还有就是自定义注解这个，我在注解执行的时候可以加一个打印日志的功能，想打印日志只要在那个接口的位置添加这个注解即可，不知道这个算不算aop，我感觉应该是这个了吧。今天没收到新的项目，最后快下班的时候来了个bug，但是这个我看日志里面也没报错，感觉这个应该是代码中的缺陷，而不是一个bug，正好赶上明天小周，去了处理这个bug，明晚就在重构一下我的微服务，主要把common的这个结构改一下，把openfeign的接口调用都放到common中省得在每个项目中都引入，用户中心和鉴权中心不变，博客文章接口也不做修改，配置中心之后在做，日志中心和文件中心暂时不打算弄，不过之后也是肯定要去实现的，还有太多的坑等我去踩，今天就到这了，昨晚一直想oauth2的这个鉴权想到失眠了，还好今天都解决了。', '2022-06-10', '2022-06-10 23:21:24', '2022-06-10 23:21:24', 1);
INSERT INTO `blog_diary` VALUES (903, 1, '先补昨天的日记，因为回家就开始部署dnf忘了写日记，弄了一晚上部署是没问题了，但是客户端开不了。', '2022-02-23', '2022-02-24 19:24:44', '2022-02-24 19:24:44', 1);
INSERT INTO `blog_diary` VALUES (904, 1, '昨天晚上处理前端问题忘记写日记了，今天早上起来补，昨天还是机器人调试，现在可以从平台上直接控制机器人了，今天过去主要是配置巡检任务，之前巡检配置不成功是机器人没办法移动，现在应该是可以了，但是配置巡检会出什么问题也说不准，然后博客是对文章首页面进行了一些修改，测试调用接口也成功了，昨晚远程找李超凡处理了一个数据无法展示的问题，然后定位到了出错的地方，今天去修改，还有后端接口也修改了一点，主要是为了适配前端页面展示的需要，差不多就这样，先上班了。', '2022-07-27', '2022-07-28 08:18:16', '2022-07-28 08:18:16', 1);
INSERT INTO `blog_diary` VALUES (905, 1, '月底了，稍微的记录一下本月情况，不过等写完今天的再说，今天计划的都做完了，博客的用户和角色接口，只不过没时间测试，测试就等明天继续，估计有不少问题，总之今天的计划是完成了算法题和接口，明天计划就测试这几个接口，要是项目有事就调试项目，没事就继续博客开发，计划把博客文章这块写一点，因为这个涉及的挺多，所有一天应该是做不完，计划俩天吧，到清明放假整好这几个接口，然后今天是月底，这个月12道算法题是完成了，但是质量是实在是太差了，都调入门题，是个人都会的那种，所以算法的博客文章都没得写，下个月要认真对待，主要这个月还是玩那个地下城了，没认真学习，每个周末都是一玩就是俩天，从这个月开始指定一下每个月的计划吧，四月份计划看完vue视频，博客第二版的前后端完成上线，博客文章至少写6篇，算法题12道，主要就这些，等四月30回来记录完成情况。对了再补一点，昨晚太过焦虑，还想学日语，去日本打工，仔细想想有这时间学习日语不让多卷一下算法和其它编程，不管怎样现在还是能找到工作的，出国一个人生活只会更艰难。', '2022-03-31', '2022-03-31 23:31:52', '2022-03-31 23:31:52', 1);
INSERT INTO `blog_diary` VALUES (906, 1, '今天玩了一天缺氧，测试了一个三人基地的模块，还有一个搭配的发电厂，测试玩感觉还是可以的以后开新基地可以用上，晚上吃饭忘了带钥匙，又被所外面的，然后等了快一个小时才找房东要下钥匙，等钥匙期间出去骑车转了转，回来之后整理了下博客，可惜的是这周没搞app，我发现只要中午不吃饭，这一天就不会学习，哎，下周努力。', '2022-01-09', '2022-01-09 22:47:34', '2022-01-09 22:47:34', 1);
INSERT INTO `blog_diary` VALUES (907, 1, '周五把盈科的mqtt下发弄完成了大半，剩下oss图片上传不会，说的要周一继续看，晚上回家玩文明6就忘了写日记。', '2022-11-18', '2022-11-20 23:37:26', '2022-11-20 23:37:26', 1);
INSERT INTO `blog_diary` VALUES (908, 1, '喜迎中秋假期，这周工作进度正常，晚上稍微看了看招聘信息，我又觉得我行了，再努力卷一卷，明天继续看前端，再就是假期要按时吃饭，没有其它注意的了。', '2022-09-09', '2022-09-09 23:35:32', '2022-09-09 23:35:32', 1);
INSERT INTO `blog_diary` VALUES (909, 1, '昨天计划是要完成博客文章的这部分，和接口调试，还有vue2的框架搭建，都算是完美完成了，（因为计划内容本来就不多）然后看色批群友的聊天记录发现了一个galgame游戏妹同居2，首先我承认我也是色批群友，算是第一次接触galgame游戏，然后我发现我开启了新世界的大门（吉尔被绑架了，我得去救，>_< 开个玩笑），不说了反正是周三补日记，剩下的时间写今天的日记。', '2022-04-05', '2022-04-06 23:08:40', '2022-04-06 23:08:40', 1);
INSERT INTO `blog_diary` VALUES (910, 1, '晚上回家把房间打扫了一次，床位置也摆了摆，这样感觉符合我的布局，然后现在好累啊，公司就对接ai模块，但是那边没弄好，再等等，还有看别人的博客都感觉好nb，我的就那样垃圾，这个周末再找个视频学习一下吧，虽然有很多功能是实现了，但是总感觉我的方式不太对。', '2022-08-18', '2022-08-18 23:01:12', '2022-08-18 23:01:12', 1);
INSERT INTO `blog_diary` VALUES (911, 1, '肚子疼了一整天，不过今天没有胃酸，应该还是之前晚上吃东西导致的，这几天都没敢吃，项目就那样，进度正常，今天不想多写了。', '2022-12-09', '2022-12-09 23:57:18', '2022-12-09 23:57:18', 1);
INSERT INTO `blog_diary` VALUES (912, 1, '不知不觉就十一点四十了，首先应该是庆幸自己没阳，明天再继续坚持一天就到周末了，项目依旧没进展，我已经习惯了，摸鱼嘛，不丢人，博客项目就今天把导航页面弄好了，等明天起来看看效果，感觉还是很棒的，毕竟终于可以使用自己的网站了，之前虽然也有，但是那些都不满意，明天任务就算别阳了，工作啥的哪有我的博客重要。', '2022-12-22', '2022-12-22 23:49:30', '2022-12-22 23:49:30', 1);
INSERT INTO `blog_diary` VALUES (913, 1, '国庆回家的火车票还没买到，可能是回不去了，今天应该是测试算法下发，但是啥都没发，之处理了门禁系统的因为读卡器问题的bug，今天很闲，好久没这么爽了。', '2022-09-26', '2022-09-26 23:17:18', '2022-09-26 23:17:18', 1);
INSERT INTO `blog_diary` VALUES (914, 1, '今天把b站删了，以后不用手机看视频了，手机留几个游戏，看看电子书差不多就行，最近看的明朝生活书也差不多快看完了，下一本看科幻小说，今天对接mqtt的这个可算是完成了，弄一个下午加晚上，最开始是配置的问题，之后是配置完成要一个字段，这个是因为我没看到mq推送上来的数据，不然早就弄好了，博客今天没写，感觉我怎么弄都是那么丑，无语了。', '2022-12-14', '2022-12-14 23:23:30', '2022-12-14 23:23:30', 1);
INSERT INTO `blog_diary` VALUES (915, 1, '基线的机器人项目现场问题处理了一天，先是弄好机器人注册问题，之后现场又说设备通道不能配置，都是写配置的问题，自己就可以看了，让我看日志，白忙活，就当今天有点事干吧，剩下今天也没做别的事情，博客界面稍微改了一点，还有新的项目不打算用vuex了要使用新的pinia（应该没写错），这个比vuex快，主要还是被自己博客第一版的速度吓到了，实在是太慢了，之后可能还要使用nuxt在服务端渲染，这个也是优化使用体验，明天开始和接口一起调试，尽快使用起来博客。公司搬到新园区这几天还是不太习惯，早上出门还没提早太多，主要是去了公司等电梯太慢了，这个看之后公司有什么解决方法，不过估计也没办法，毕竟电梯速度就那样，可以参考1199早上等电梯的速度，还有公司餐厅好贵啊，本以为能够便宜点和1199差不多价格，没想到餐厅价格是参考了华业园区，有点难受。', '2022-07-26', '2022-07-26 23:19:32', '2022-07-26 23:19:32', 1);
INSERT INTO `blog_diary` VALUES (916, 1, '广东中国石化项目开始，但是完全没有头绪，最近莫名其妙想换个微信头像，还有我这微信名字当时别人给注册的，到现在都没改过，好多年了都，我还记得当时是杜飞用我的手机号注册领了一本书，记得好像是高考作文相关的，薄薄的一本。', '2022-10-14', '2022-10-14 23:39:36', '2022-10-14 23:39:36', 1);
INSERT INTO `blog_diary` VALUES (917, 1, '最近忙中州换流站的项目，这个就是加一个接口，需要改动brm和eims，晚上回家继续泰拉瑞亚。', '2022-12-06', '2022-12-07 00:22:14', '2022-12-07 00:22:14', 1);
INSERT INTO `blog_diary` VALUES (918, 1, '桐昆的上一个项目写的有点问题，我之前以为只是统计数据，没想到是真的在控制设备，所以之前写的逻辑都要修改，明天看来是闲不下来了，然后今天微服务的那个视频没看，看了下微服务鉴权的demo，最后晚上看的那个demo还有些bug，明天要是有时间看看能不能改掉，我的微服务博客也要开始搭建了，主要有网关，nacos，security之类的，具体还有些啥还不清楚，这个周末看看。', '2022-05-26', '2022-05-26 23:03:30', '2022-05-26 23:03:30', 1);
INSERT INTO `blog_diary` VALUES (919, 1, '月底了，本月计划的12道算法题完美完成，今天又接到了一个项目开发，总算是有事干了，无聊摸鱼虽然可以开发博客或者写写算法，但是总的来说还挺无聊的，不过到晚上都没把权限审批完成，只好等明天看项目，到底做什么，怎么做还没想法，不过问题不大，下午本来是看分块算法的，不过那道题数据有点大，我的方法没解决的，有一组数据超时，还有一组错了，超时可以理解，但是为什么会wa呢，想不通，一般情况是数据范围的问题，但是这题范围应该是没问题，那只能是算法不完善，有一组数据卡了，等有时间看吧，项目优先。', '2022-02-28', '2022-02-28 23:51:00', '2022-02-28 23:51:00', 1);
INSERT INTO `blog_diary` VALUES (920, 1, '周日玩哈迪斯，有点上头，再就是实在不想看代码，明天再继续努力吧，上班好累，在外漂泊也心累。', '2022-10-30', '2022-10-30 22:45:26', '2022-10-30 22:45:26', 1);
INSERT INTO `blog_diary` VALUES (921, 1, '今天dssas的项目没进度，大哥说的下午过来看，结果没看，所以我就摸鱼开发博客，现在这鱼是能摸一天算一天，博客日记功能大概是可以了，现在开始整文档这块，周末要是有时间可以看看，还有这个假期把博客数据库整理下我觉得可以使用了。', '2022-12-30', '2022-12-30 23:13:42', '2022-12-30 23:13:42', 1);
INSERT INTO `blog_diary` VALUES (922, 1, '前一天的核酸结果一点半才出，但是因为之前结果没出我把火车票都退了，申请了8 9 号俩天的调休，看电子书。', '2022-10-06', '2022-10-10 23:01:40', '2022-10-10 23:01:40', 1);
INSERT INTO `blog_diary` VALUES (923, 1, '下午导师给了个定位bug的任务，我是真傻了，就忘了看日志这个步骤，好丢人啊，后来看日志报错都那么明显，实在是丢人，然后就是今天计划的ppt算是完成了60%吧，剩下的明天去了修改修改，差不多就行了，然后算法做了一道题，明天最后一题，a完这周任务就完成了，然后就是买的自行车内胎气口太短了，真是ctml，傻逼玩意，买轮胎把型号字写在图片里面，还不让手动选择型号，不说了，想起来就生气，以后注意点把，只能怪自己了，最近天天加班，晚上都不想早睡，想玩玩手机，还好后天就可以放假休息了。', '2022-04-28', '2022-04-28 23:43:06', '2022-04-28 23:43:06', 1);
INSERT INTO `blog_diary` VALUES (924, 1, '不早了，稍微写几句睡觉，今天买了腾讯云的2核4g6m的共享性轻量服务器，晚上计划把博客和dnf都部署好的，但是因为dnf也是用mysql，一台电脑上安装俩个MySQL可能会产生很多麻烦，所以博客暂时先部署到旧的tx云服务器上面，晚上只弄好了dnf，博客应该也快，但是下载jdk实在是太慢了，等明天吧。', '2022-06-28', '2022-06-29 00:16:58', '2022-06-29 00:16:58', 1);
INSERT INTO `blog_diary` VALUES (925, 1, '今天晚上有了一个新的开发任务，还有下午改了之前做的云存储查询时间优化，稍微有点bug，修改之后应该没问题了，最近不知道为啥就是感觉累，可能是这就是年龄大了吧，博客今天主要是写路由登陆拦截这块，还弄了md文章编辑插件，之前使用的mavonEditor现在换成了v-md-editor，应该是没写错，今天做完有几个报错提示，但是不影响代码执行，暂时还没想好要怎么修改，现在优先完成功能，之后再考虑优化。最近感觉累可能是因为看b站多了，天天被传递一些买房难，还贷和结婚育子，这东西离我太远了，我完全不需要考虑这个，还有就是网上好多传递离职焦虑的，真是烦人啊，我也是明知道烦人还要点开看，没事找抽啊，有这时间不如多卷一卷，现在也不需要考虑离职问题，谁知道网上那人们是干啥的，现在下定决心少使用b站，改成每天限时半小时，娱乐时间不如找找动漫看，实在不行找本书看也行，远离b站，现在都低龄化成啥样了，都是些降智言论，还搞得我天天心烦。', '2022-08-16', '2022-08-16 23:09:56', '2022-08-16 23:09:56', 1);
INSERT INTO `blog_diary` VALUES (926, 1, '今天还是不想写日记，昨天玩文明六到了俩点，今天实在是太累了，就等这个大周好好休息下，把家里打扫下。', '2022-11-24', '2022-11-24 23:20:12', '2022-11-24 23:20:12', 1);
INSERT INTO `blog_diary` VALUES (927, 1, '今天也好忙啊，大庆油田的bug改了一个又来一个，不过好在智慧加油站的这个项目差不多完成了，明天去看ar项目的这个bug，今晚初步排查了一下应该是调用admin系统返回数据失败了，明天看看admin系统具体是因为什么报错了，感觉又是一个较难的bug，只能希望明天能够解决吧，今天博客是真的没开发，啥也没修改，马上周六了，去宁波方特公园玩玩，放松一下，体验一把过山车。', '2022-06-16', '2022-06-16 22:18:54', '2022-06-16 22:18:54', 1);
INSERT INTO `blog_diary` VALUES (928, 1, '果然不出我所料，今天啥也没干，中午也没出去吃饭，就吃了一包饼干和方便面，在被子里钻到了晚上，然后下去吃了个黄焖鸡，其实上次吃完这个黄焖鸡就有点再也不想吃了，感觉上次吃的那个黄焖鸡味道不对，今天这个还是可以的，然后今天还开了个饥荒档，但是我感觉一是没时间玩，再就是一个人也玩不下去，看看视频还是可以的，真就上手玩还是有点困难，晚上吃完饭回来继续昨天那个app，今天弄好了调用我Java后端接口的功能，之后又发现一个问题就是我项目中使用了lombok但是使用的时候都报红，卧槽突然间我知道是为什么了，我的软件没装lombok，刚刚开了软件装上没问题了，太舒服了，昨晚上我以为是没有get/set方法，然后全加上了get/set方法，结果今天软件直接报错，测试新功能我以为是我新加的代码出错了，整了好久，差不多就这样吧，躺下了，睡不睡是另外一回事。', '2022-01-03', '2022-01-04 00:25:50', '2022-01-04 00:25:50', 1);
INSERT INTO `blog_diary` VALUES (929, 1, '今天去公司把ppt改了一半，但是没改完，后面的问题解决不知道怎么写，明天去了再继续想想吧，或者就随便找一个sql优化的问题，烦人，周二赶快答辩完成啥都轻松了。', '2022-11-20', '2022-11-21 00:03:54', '2022-11-21 00:03:54', 1);
INSERT INTO `blog_diary` VALUES (930, 1, '今天也不知道忙什么，一天下来好累啊，上午打算是看公司的代码，也看了，但是和不看也差不多，下午把登陆返回token的demo做完了，看sprint boot的这个鉴权的类还有俩个方法没看明白，不过现在用的这个应该就可以完成用户的鉴权了吧，大概吧，最近看的书有点迷惑，到这儿有好多人名记不住了，我还是高估自己了，再就是最近有些累，不太想看，这周好好歇息一下，明天去了至少要a一题，不然周末就不能好好休息了。', '2022-03-03', '2022-03-03 23:09:24', '2022-03-03 23:09:24', 1);
INSERT INTO `blog_diary` VALUES (931, 1, '昨天晚上下载好的消光，今晚开玩，刚开始有点不习惯，后来玩一会太熟了了，今晚我就是哈兰超人，主线跟了一点，主要还是先支线，之前完成走主线，这样玩的剧情都跟的上，主线走完再开支线就没啥意思了，不说游戏了，毕竟是日记开门见山的都是游戏，搞得我好像不务正业似的。今天在公司任务不是很忙，上午开早会得知我不是很忙就给我分配了一个项目，这个今天看他们聊了一天也不知道啥情况，是还在澄清需求吗，最后也没搞清楚要开发啥，就知道项目名字叫中石化；现场问题的黄河鑫业我还在看，这个现在的问题主要是下发算法之后算法给我报的错，这个问题和我没啥关系，和我有关的那个dp库中大量脏数据，前天改完也一直没测试，我觉得修改没啥大问题，之前就是我没加删除的校验，所以导致我这删了，dp没删，不出问题就行；明天有一个动环模块的修改，这个应该是在别人的指挥下我该，据说是个小需求，只是据说啊，具体我也不清楚，就这样，总觉得有件事没写，先想想，对，最近在看宋史，比看一些短视频有趣多了，哈兰超人差不多要睡觉了。', '2022-11-08', '2022-11-09 00:03:26', '2022-11-09 00:03:26', 1);
INSERT INTO `blog_diary` VALUES (932, 1, '今天计划正常吧，查找的那个接口又修改了一次，这次逻辑应该是没问题了，之后就是优化一下代码，还剩一个存储空间的那个接口没写完，然后就是统计数据的那个还有增删改，任务好多啊，这个需求也算是我做的比较有挑战的任务了，最近算法博客什么的都没时间，今晚把车胎换了，所以也没看视频。', '2022-05-11', '2022-05-11 23:37:06', '2022-05-11 23:37:06', 1);
INSERT INTO `blog_diary` VALUES (933, 1, '可算是明天就要上班了，卧槽等太久了，过年呆这啥也没干，博客啥的一点进度没有，房间太冷了，打游戏都不愿意，整体钻被子里面，这周去了公司进度要稍微快一点。', '2022-02-08', '2022-02-08 21:38:28', '2022-02-08 21:38:28', 1);
INSERT INTO `blog_diary` VALUES (934, 1, '周五，上午继续那个项目，没看博客，下午计划是去医院看看身上这是怎么回事，不过没预约上，但是假都请了，也没必要留在公司，就回家打游戏，正好用一下买的手柄，第一次使用手柄确实难用，不过稍微熟练点了，再就是躺着玩游戏太舒服了，新开了一个空洞骑士存档，没事干就可以玩玩，晚上看双城之战，也是因为看这个才误了写日记，总体感觉这动漫还是可以的，因为是周六补日记，所以动漫是今天看完的，动漫评价写在周六的日记中（在打游戏，所以写的内容有点散）。', '2022-04-08', '2022-04-09 22:44:30', '2022-04-09 22:44:30', 1);
INSERT INTO `blog_diary` VALUES (935, 1, '期待了一个半月的六月份工资结果没涨，不涨就不涨吧，也由不得我，难不成我还以为工资没涨跳槽呢，怎么说也要待两年吧，今天周一做导出的接口大概是完成了，本地测试没什么问题，和前端调试可能还要改改，也不知道为啥前端导出会把名字搞的乱码，这个乱码的问题明天抽时间看，还有开关报警的问题，代码是修改完成了，但是没环境测试，明天主要的任务就是把巡检主页面的接口完成，新增接口这个应该问题不大，这周完成任务进度还是可控的，今天看了七月新番，整体质量感觉不错，要追三到四个吧。', '2022-07-11', '2022-07-11 23:16:34', '2022-07-11 23:16:34', 1);
INSERT INTO `blog_diary` VALUES (936, 1, '今天还是没有做算法题，这周很有可能完不成了，下午看了下博客，把博客优化了一下，还有博客的数据库也完成了，服务器上的可以更新下一个版本了。', '2022-03-11', '2022-03-11 23:34:16', '2022-03-11 23:34:16', 1);
INSERT INTO `blog_diary` VALUES (937, 1, '今天有什么要记录的事情吗，项目上黄河鑫业又出一个包，这次是关于任务暂停的包，下午测试没什么问题，之后考虑加一个启动单算法的接口，其它事情也没啥可写的，最近看完了灰幻，博客开始了日记功能的开发，开始玩星露谷了，大概就这些吧，阳康之后的日子平平无奇，也希望就这样一直平静下去吧。', '2022-12-29', '2022-12-29 23:21:46', '2022-12-29 23:21:46', 1);
INSERT INTO `blog_diary` VALUES (938, 1, '因为前一天开的缺氧，所以啥事没干。', '2022-09-11', '2022-09-13 23:04:50', '2022-09-13 23:04:50', 1);
INSERT INTO `blog_diary` VALUES (939, 1, '闲着的一天又回来了，今天就把博客后端页面不能翻页的bug修复完成，然后优化了一下查询数据库的语句，晚上回来把app的首页copy了一个，等这个周末尽量能看博客文章把，不过应该还有好多事情要做，可能这周没法实现，尽量，然后算法题解决了一个简单的dp和另一个也可以dp做的但是我用的dfs，明天试试用dp解决，算法最近主要看看dp，还是状态转移方程不会找，差不多得了没其他要记录的事情了。', '2022-01-11', '2022-01-11 22:38:52', '2022-01-11 22:38:52', 1);
INSERT INTO `blog_diary` VALUES (940, 1, '这周是大周，上午部署了博客，但是好像没成功，等明天上午测试一下看是哪块出错了，下午去公司完成答辩的ppt，ppt我觉得写的还是挺好的，应该不会是自我感觉良好，晚上回家打打消光，平平淡淡的一个周六，就是可惜今天公司组织的爬山没去，虽然不是部门那种团建，还是挺可惜的，组织的活动我一般都愿意去，就算这次爬的北高峰我上过也想在上一次，公司领的水果又坏了，我该考虑买个苍蝇拍。', '2022-11-12', '2022-11-13 00:01:26', '2022-11-13 00:01:26', 1);
INSERT INTO `blog_diary` VALUES (941, 1, '微服务的鉴权中心算是搭建完成了，微信qq三方登陆这个之后再弄，现在oauth2的具体配置还不清楚，现在只是搭建完成了鉴权中心，这个还得花点时间学习一下配置的具体作用，之后还计划写一篇，应该是写一个文档的oauth2的配置计划是这样，七月份吧，这个月先搭建微服务的博客api接口中心，还有微服务的这么多技术，啥流控、配置中心、注册中心太多内容了，之前看的那个就教了这些东西是干什么的，然后配置就随便弄了一个demo，在我这次搭建微服务环境虽然不能说完全没用，但还是用处不大，还是靠自己慢慢踩坑弄出来的，gateway和nacos整合的坑最多，还有就是搭建的时候各个依赖完全都不明白是什么意思，就oauth2的一个依赖就有还几个不同的名字，还是慢慢学习吧，这个百度查也会踩很多坑，最后这个月尽快写完我这个微服务的后端接口，以前觉得各种配置还是要自己掌握比较好，但是最近开发感觉重复的东西不太愿意去做，比如mybatis的一些单表查询sql，以后把mybatis plus也学习一下，这样sql只需要写多表等复杂的查询就好，微服务博客这个版本还是不弄服务降级了吧，不太清楚应该怎么去做，现在已经是网关直接调用我的服务接口了，难不成要再加一层，使用feign再加一层转发吗，不懂的实在是太多了，慢慢来吧，先从oauth2开始，今天就这样了，还有公司六月份的旅游报名今天我报了宁波方特乐园，去体验一下过山车。', '2022-06-08', '2022-06-08 23:28:08', '2022-06-08 23:28:08', 1);
INSERT INTO `blog_diary` VALUES (942, 1, '昨天也是划水的一天呢，周一写的，一天大概就是把自行车胎补好，衣服洗了，其它事情都没做，上周有点忙，周末只想躺着。', '2022-08-28', '2022-08-29 21:03:26', '2022-08-29 21:03:26', 1);
INSERT INTO `blog_diary` VALUES (943, 1, '今天涨工资了，快乐的一天，现在月薪是11600，这下应该可以说月入1w了，扣除五险一金应该还够吧，项目就看门禁的那个，用的mq下发，具体流程还是不太清楚，明天继续看，还有四天时间，进度应该是正常的，个人博客还是改回之前的写法吧，新的样式实在是不会写，以后慢慢来吧，优先完成开始使用。', '2022-08-08', '2022-08-08 22:58:30', '2022-08-08 22:58:30', 1);
INSERT INTO `blog_diary` VALUES (944, 1, '今天也是平平无奇的一天，主要做ai算法下发的config配置，机器人那边有现场问题稍微过去看看，算法调好了第一个，希望明天进度稍快点。', '2022-09-06', '2022-09-06 22:53:08', '2022-09-06 22:53:08', 1);
INSERT INTO `blog_diary` VALUES (945, 1, '都八月了，今天主要调试机器人，把所有的功能都过了一次，然后整理出了一些问题等机器人那边修改，所以我这是没事情了，然后晚上就继续修改我的博客页面，加了后台管理系统的首页，风格就按找公司的icc系统来的，甚至css样式都是扒过来直接使用，然后还做了路由跳转，今天还没少做，今天嗓子堵得很不舒服，还是找时间去医院看看吧，可能这周末，挂个号直接过去，第二次了稍微熟悉点流程。', '2022-08-01', '2022-08-01 23:23:18', '2022-08-01 23:23:18', 1);
INSERT INTO `blog_diary` VALUES (946, 1, '今天项目也没看，前端也没写成个样子，最后决定还是手写css吧，毕竟前端我是要认真学习的，现在不学习css，以后也得学习，今天想了下css基础的语法我还是知道的，至于今天为什么还是啥也写不出来，我觉得是css的布局语法这方面我完全不懂，之前写的都是靠百度，也没认真学习过，所以最近这几天有时间就看css的布局吧，明天还是优先项目，今天因为没有环境所以没怎么看，只申请好了权限，具体怎么操作、修改明天解决。', '2022-07-06', '2022-07-06 23:02:46', '2022-07-06 23:02:46', 1);
INSERT INTO `blog_diary` VALUES (947, 1, '工资到账，没想到十一月又有1600的项目奖金，虽然不知道是哪个项目给的，反正给钱拿着就行了，问那么多没用的干啥，今天没怎么肚子疼，晚上抱着热水瓶舒服多了，今天玩哈迪斯和消光，没学习，明天把博客整体部署的脚本完成。', '2022-12-10', '2022-12-10 23:38:10', '2022-12-10 23:38:10', 1);
INSERT INTO `blog_diary` VALUES (948, 1, '周日去公司没人啊，二楼餐厅也不开门，下午过去就看了看洛谷的比赛，只做了一道题，别的题甚至看不懂，之后去找理发店，找了好半天还好找到了，等明天晚上过去理发，今天人太多，排队要等很久。', '2022-02-13', '2022-02-13 22:45:34', '2022-02-13 22:45:34', 1);
INSERT INTO `blog_diary` VALUES (949, 1, '广东中国石化的这个项目终于有点眉目了，还有还有卡了一整天的打包问题也终于ok了，就莫名其妙换个包就可以了，可能是因为之前是用的软连接吗，今天加好了接口，明天过去实现功能，还有答辩ppt，稍微有点烦啊，害怕答辩，ppt也不知道要怎么写。', '2022-10-18', '2022-10-18 23:19:08', '2022-10-18 23:19:08', 1);
INSERT INTO `blog_diary` VALUES (950, 1, '经验库接口开发的差不多了，明天先和dp测试下发经验库的配置，先测试经验库的增删改查，今天写的一个分页查询的接口好大啊，虽然没几行代码，但是这个sql做个功能很多，最近用左连接也很熟练了，晚上加班赶出来了经验库的接口，fpt现场打包的问题张崇大哥也给解决了，降了一个jar包的版本，因为这个版本在公司maven仓库中有，突然感觉这个问题我其实多思考下可以解决的，每次都是事后诸葛亮，四愣子跳槽工资也11.5k了，我的博客就在国庆期间写吧，最近实在是太忙了。', '2022-09-22', '2022-09-22 23:51:56', '2022-09-22 23:51:56', 1);
INSERT INTO `blog_diary` VALUES (951, 1, '周末就玩了玩游戏，哈迪斯快全成就了，周末还是不想写代码浪费，明天希望园区不用查72小时健康码。', '2022-12-18', '2022-12-19 00:05:00', '2022-12-19 00:05:00', 1);
INSERT INTO `blog_diary` VALUES (952, 1, '今天任务挺多的，上午做完了sgs那个项目的一个报警类型上报的功能，不过都是从eims搬过去的，下午看新疆的那个新增报警调试，而且还开了2小时的会也不算开会，是培训MySQL讲了俩小时，然后到晚上腰疼，不想看项目，累了，今天的计划推迟到明天，明天是周六，因为清明节调休了，然后就是三天的假期，先不写了，不想坐着，有事等假期再写。', '2022-04-01', '2022-04-01 22:43:30', '2022-04-01 22:43:30', 1);
INSERT INTO `blog_diary` VALUES (953, 1, '七月二十二又想到了不愉快的会议，多年之前就是在今天被某人再次甩掉了，所以我再不可能去主动追她了，现在还留着微信，之前还找过我几次，不过最近还好点，没联系了，一直就这样吧，虽然还是有点期待，但现在我主要还是好好工作多攒点钱比较好。今天公司搬家了，我的新工位还是非常满意的，新大楼的餐厅也很大，五楼还能跑跑步，开始有点期待新环境了，又不想写了，随缘今天就这样。', '2022-07-22', '2022-07-22 23:24:04', '2022-07-22 23:24:04', 1);
INSERT INTO `blog_diary` VALUES (954, 1, '没想到今天公司又发了六一的礼包，里面一大堆小时候的那种零食，好怀念小时候啊，一点压力没有，还能开心的玩游戏，今天开始看oauth2.0的微服务框架，这个学习完成之后就可以开始搭建我的博客了，网关和注册中心这些都比较熟悉了，尽快看完，早日用上我的微服务架构博客。', '2022-06-01', '2022-06-01 22:03:56', '2022-06-01 22:03:56', 1);
INSERT INTO `blog_diary` VALUES (955, 1, '918大清早就被楼下大学军训的吵醒了，然后回笼觉又被防空警报吵醒，实在是太烦了，今天休息，没看啥代码视频，最近项目很累，没啥心情去看代码，要是周末休俩天还行，但是加班之后只剩一天休息时间，再爆肝代码实在是顶不住，下午玩了会缺氧，已经熔好了第二个火箭仓，我计划弄好多个火箭，组建我的太空舰队，也不知道要弄几个火箭，到时候看吧，肯定是越多越好，今天就这样吧，下午洗了衣服，好像内裤和袜子忘记了，明天晚上洗吧，现在也不早了，下楼丢个垃圾，顺便看看能不能喂只猫，然后上来睡觉，我今天是真的下定决心不当舔狗了，九月三十一一定要给我自己一个交代。', '2022-09-18', '2022-09-18 23:30:12', '2022-09-18 23:30:12', 1);
INSERT INTO `blog_diary` VALUES (956, 1, '小周，听说本来今天是要去团建玩去，结果因为疫情影响不去了，只能老老实实公司干活，今天写定时任务的这块，写了一半不想写了，剩下的周一再说，明天看情况学习。', '2022-10-22', '2022-10-22 22:53:34', '2022-10-22 22:53:34', 1);
INSERT INTO `blog_diary` VALUES (957, 1, '大年初一，实在太惨了，今天本来是打算学习的，但是太冷了，晚上就随便吃了点零食，不想点外卖了，吃吐了，快开始上班吧。今天看B型H系，我现在真是阅片无数了。', '2022-02-01', '2022-02-02 00:40:00', '2022-02-02 00:40:00', 1);
INSERT INTO `blog_diary` VALUES (958, 1, '机器人的文档今天完成了，现在还有orms的文档没写完，isms的文档今天也完成了，博客等明天早上起来整理一下，明天上班的时候有时间可以写写，最近又没有项目可以打卡的，最近都是写文档的任务，也不知道要打哪个项目的卡，还有晚上回来买了一个异星工厂，之前就想买，但是因为太贵了，就一直没买，这次正好用上之前注册的阿根廷账号，90的游戏不到24就买下了，实在是太香了，算法题这周已经过去了2天，每天状态都不好，也没心情看，每天一定要解决一题，不然这周可能就做不到3题了，还是早点完成比较好，博客计划每天也整理一下，之前做的那个标签还没完成，做一半过段时间忘了就不好办了。', '2022-01-18', '2022-01-18 23:15:54', '2022-01-18 23:15:54', 1);
INSERT INTO `blog_diary` VALUES (959, 1, '今天开始了之前添加报警类型的任务，不过除了添加数据库字段之外还有个修改数据库以及接口的任务，到周二截至，下周去了尽快完成吧，虽然到今天还不清楚具体怎么开发，到时候看吧，最近看的spring security+vue的项目后端在开发中，具体进度也就那样，周末可能会看看前端的，因为公司前端不太方便。', '2022-03-18', '2022-03-19 00:02:40', '2022-03-19 00:02:40', 1);
INSERT INTO `blog_diary` VALUES (960, 1, '南通的项目差不多要完了，今天下午还学习了那个微服务视频，晚上也看了一个小时，今天的进度应该是稍快了点，只不过晚上玩盐与避难所有点来气啊，我太菜了，不小心又超了十一点，真的是不打过不想睡觉啊。', '2022-05-18', '2022-05-18 23:21:24', '2022-05-18 23:21:24', 1);
INSERT INTO `blog_diary` VALUES (961, 1, '今天晚上开会，是看代码评审，下班回家就十点了，所以今天不写日记是有理由的，我要睡觉了。', '2022-07-18', '2022-07-18 23:05:04', '2022-07-18 23:05:04', 1);
INSERT INTO `blog_diary` VALUES (962, 1, '博客微服务框架开始搭建，现在有个问题就是不知道版本依赖该选哪个，还有oauth2相关的依赖也有好多，不知道该选用哪个，明天再看吧，今天下午睡了一觉，晚上还是很瞌睡，明明早上也没早起床。', '2022-06-05', '2022-06-05 22:58:30', '2022-06-05 22:58:30', 1);
INSERT INTO `blog_diary` VALUES (963, 1, '连着三天一点半，今天依旧没什么重要的任务，我就整理那个isms的文档，下午机器人那边有点事情，看了看现场的bug，不过也没花多长时间，想不到其它的事情了，周五照常整理一周的文件发回家，晚上玩缺氧，今天把岩浆掏空了，回过头发现制氧不够了，按理来说一个制氧机五个小人应该没问题的，等睡醒再看看吧。', '2022-01-14', '2022-01-15 01:39:48', '2022-01-15 01:39:48', 1);
INSERT INTO `blog_diary` VALUES (964, 1, '昨晚除夕夜，晚上稍微迟了一会睡觉，和高中同学聊天，不过真没想到啊，小二都要准备和张倩结婚了，我现在还是光棍一个，随缘吧，反正也急不来，而且我这工作还要继续漂泊，王德宇去哈尔滨当兵了，还是军官，说实话还挺羡慕的，毕竟是铁饭碗啊，我也没什么打算，今天就继续在大华奋斗一年，之后跳槽，想进大厂啊，还有今年能找到对象吗，我这工资和我的性格会有人看得上吗，不说这个了。22年一月份结束了，一月份四周多几天，应该是最少12题算是完成了，二月份继续努力，放假也休息好几天了，该好好学习了，在不卷工作都没得，最后仔细想想我也不适合当兵，还是计算机这个适合我，上班能摸鱼，纪律也没那么多，反正我选择的路绝对不会后悔，昨天看完了异种族风俗娘评鉴指南，好色哦，还有说好的看书，之前看的摆渡人暂时等等吧，我不太喜欢二刷，剧情都知道了，看着有点无聊，最近在看挽救计划虽然这个剧情也知道，但还是想看完。', '2022-01-31', '2022-02-01 14:59:02', '2022-02-01 14:59:02', 1);
INSERT INTO `blog_diary` VALUES (965, 1, '不得不说痛苦面具戴了一天，又是admin项目，不过今天似乎对Struts2框架稍微有那么一内内的理解，今天还是继续那个过滤组织树的任务，痛苦一整天之后把组织树过滤的功能完成了，现在还有对设备的过滤，不过一晚上的努力也找到了Hibernate查找设备的那个接口，参数也看到了，明天去了只要对这个参数定位然后修改了传入参数应该就可以解决设备过滤的这个问题，这个需求明天完成我觉得还是有希望的，求早日脱离N8000的苦海，看icc的项目是真的舒服，每个接口都有对应文档，甚至输入输出都有，然后今天算法没有任何进步，看了一个题，但是感觉短时间做不出来，毕竟是省选题，还有这原题是因为，看翻译的中文题意完全没有说清楚啊，靠着翻译才明白题意，回家没玩游戏，把安卓项目的util写了写，那个对okhttp3的封装感觉还是有点问题，慢慢琢磨吧。', '2022-01-06', '2022-01-06 23:58:10', '2022-01-06 23:58:10', 1);
INSERT INTO `blog_diary` VALUES (966, 1, '周六去团建，玩的项目挺多的，最喜欢的还是射箭，晚上回来还是文明6.', '2022-11-19', '2022-11-20 23:57:00', '2022-11-20 23:57:00', 1);
INSERT INTO `blog_diary` VALUES (967, 1, 'N8000的那个bug也不是很难嘛，虽然请教了下导师，知道了是哪个数据库，要是我自己找可能会花点时间，但也应该能找到，因为接口没报错，排查问题只能从数据库和前端页面俩个方向，最后就是加了几句sql，然后功能都可以正常使用了。下午就开发我的博客，现在把博客文章的增删改查弄好了，因为是要做一个博客社区版的，所以接口的业务和之前的不太一样，每个接口请求都要确定身份，今天写的这几个应该是没什么问题，然后今天何伟导师好像给了个icc的任务，但是也没再提这个，不知道还要不要开发，不过没人给我需求我就开发我的博客，我正缺时间呢。', '2022-06-13', '2022-06-13 23:03:18', '2022-06-13 23:03:18', 1);
INSERT INTO `blog_diary` VALUES (968, 1, '今天一天我就是尸体，躺尸一整天，中午吃饭都是草草泡了袋面，现在泡面吃完了，还有今天把衣服洗了，学了一点点flex布局，感觉还是挺简单的，下周有时间试试。', '2022-08-21', '2022-08-21 23:46:10', '2022-08-21 23:46:10', 1);
INSERT INTO `blog_diary` VALUES (969, 1, '缺氧的一天，明天去做核酸检测，准备回家了。', '2022-01-22', '2022-01-22 23:44:14', '2022-01-22 23:44:14', 1);
INSERT INTO `blog_diary` VALUES (970, 1, '周日妥妥的咸鱼，躺一天，把衣服都洗了。', '2022-05-22', '2022-05-22 23:04:18', '2022-05-22 23:04:18', 1);
INSERT INTO `blog_diary` VALUES (971, 1, '今天做了核酸检测，要准备回家了，下了一天雨，出去都不方便，缺氧今天可算是完成了液氢火箭，这周三题没完成，下周要补上。', '2022-01-23', '2022-01-23 23:23:52', '2022-01-23 23:23:52', 1);
INSERT INTO `blog_diary` VALUES (972, 1, '南通的项目开始做了，还有昨天的bug不是MySQL密码改了，是其它问题，百度出来是配置文件的问题，但我对比其它服务器的配置问题这个是没问题的，最后直接烧机了，晚上去理发人爆满，要预约明天的。', '2022-05-06', '2022-05-06 22:43:36', '2022-05-06 22:43:36', 1);
INSERT INTO `blog_diary` VALUES (973, 1, '今天一天是真的烦，写博客的时候有个东西卡住了，不想写特别垃圾的代码，所以就想思考一个效率高点的算法来整理树形结构，结构一下午没想出来，整的头疼，晚上就选择了早点回家，回家之后不小心看到了杭州it行业好多公司裁员，说实话我也害怕被裁员，不知道怎么办，总之得给自己想一条后路，至少得有个能养活自己的工作，想过回家参加省考，考个公务员吗，但是这个太难了，也想出国打工，不管怎样国外挣的钱肯定比国内高，其实我想学习日语，但是每次都是坚持不下去，视频看一会就累了，就算看完课下也不去自己看看书，不多练习一下，先考虑几天，再想想要不要学习日语，今天也是啥也没做成，以后日记尽量写上第二天的计划吧，不然一点进度都没有，天天磨蹭，不干活，也没啥进步，首先说明天的，明天是月底算法俩道题必须做完，即使是水题也要做，然后就是博客博客菜单结构整理写完，然后把用户和角色的接口写完，差不多就先这些完成之后再考虑其它，等明天晚上记录进度，然后调整下一天的计划。还有一件事是之前忘了的，周一看完了法医秦明逝者之书，不能说学到什么，看完就是觉得好多日常中不注意的事情也会引起人的死亡，还有就是喝酒之后踢肚子一脚就会肝脏破碎（喝酒之后腹部肌肉不会反射性收缩，力量就直接作用到器官之上，肝脏又比较脆），还有喝酒引起的其它事情，总之就是喝酒的危害实在是太多了，能不和还是少喝，最后看完这本书印象最深的话就是：喝酒聚餐的时候带一片头孢药，以此拒绝所有的喝酒行为，虽然是开玩笑，但是这应该是最有效的方法了吧，今天早点休息。', '2022-03-30', '2022-03-30 22:57:56', '2022-03-30 22:57:56', 1);
INSERT INTO `blog_diary` VALUES (974, 1, '最然是周六，躺床上一天也好烦啊，啥事没做，正常操作吧，明天再看看前端。稍微多写点吧，合租的那个租独卫的今天搬走了，剩下根网线我就拉到我这边了，现在是有线网络，速度比之前快了3m，还是有线用着爽，等今年十月之后找个新房子吧，住这时间长了，换个新环境，一个地方呆久了有点无聊，能随时搬家还是租房舒服。', '2022-07-30', '2022-07-30 23:11:52', '2022-07-30 23:11:52', 1);
INSERT INTO `blog_diary` VALUES (975, 1, '孤独的七夕，今天有调试机器人，那边还没好，不知道是哪出问题了，明天要开始新的项目了，具体细节我还没看，最近一有时间就瞎搞我的vue项目，虽然做的还是不怎么样。', '2022-08-04', '2022-08-04 22:53:48', '2022-08-04 22:53:48', 1);
INSERT INTO `blog_diary` VALUES (976, 1, '10月2日到9日日记都在10补写，2号坐动车回家，晚上8点左右到家，火车上看电子书。', '2022-10-02', '2022-10-10 22:52:48', '2022-10-10 22:52:48', 1);
INSERT INTO `blog_diary` VALUES (977, 1, '草，最后一把王者打的真来气，尼玛，不说这个了，先卸游戏，也玩好几天了，差不多了，然后就是现在还玩dnf，这个再等等。今天上午调休，下午去了因为没有任务就继续看spring security，现在这个项目感觉看的差不多了，关于security的基础配置都讲了，还有之后的视频都是讲微服务整合spring security我现在微服务都没看，spring cloud也不懂这个就算看完了，现在看vue和spring security的整合，这个关系到我博客重构之后的框架，所以优先学习，说到博客，博客该有的功能目前能想到的，可以实现的都差不多了，然后就是准备重构，前后端都重构，这个版本应该不会大更新了，重构的话打算前端用vue3和element-ui后端想分模块做，就是博客一个模块，文档一个模块等等，把鉴权单独做出来，算是我最近的计划，也是未来博客实现的方向，还有现在的博客不知道为啥接口加载不稳定，访问有时候能访问到，有时候就访问不到，我觉得可能是我优化太差，加载很慢，超时了就给跳转，网好的时候就加载出来，不过也不确定，因为这个前后端基础框架都不是我做的，所以之后分模块做之前先多学习一下，最近算法题稍微的拖一下，不过这个月12题肯定不能拖到下个月，差不多就这些吧，最近这几天都好累，今天早点睡觉。', '2022-03-15', '2022-03-15 23:33:04', '2022-03-15 23:33:04', 1);
INSERT INTO `blog_diary` VALUES (978, 1, '最近又有好几个项目，但不是特别忙，抽空摸鱼还是可以做到的，今天下班回家发现钥匙没带，希望是落在了公司，别真丢钥匙了。', '2022-11-28', '2022-11-28 23:33:46', '2022-11-28 23:33:46', 1);
INSERT INTO `blog_diary` VALUES (979, 1, '最近越来越觉得自己太菜了，vue的学习稍等等吧，博客也再等等，容我先学习一下微服务，现在微服务这么火，公司也在用，打算继续重构博客的后端，所以前端更是遥遥无期，然后就是今天公司没什么任务，估计明天任务也不会很多，就继续学习微服务吧。', '2022-04-21', '2022-04-21 23:21:36', '2022-04-21 23:21:36', 1);
INSERT INTO `blog_diary` VALUES (980, 1, '周五不知道为什么太累了，回家之后就躺着，直到睡觉。', '2022-08-12', '2022-08-13 23:42:26', '2022-08-13 23:42:26', 1);
INSERT INTO `blog_diary` VALUES (981, 1, '打了一晚上深渊，不早了。今天是周日，一直拖着日记没补，先补周四的，周四看完了《火星救援》和《易中天中华史：三国记》，先说火星救援吧和之前看的《挽救计划》是一个作者，全书读完感觉很懵逼，虽然作者叙述的风格挺幽默的（不知道是不是因为翻译）但是对比《挽救计划》这本书开头没有配个图之类的，实在想象不出作者描述的火星基地是怎么样子的，还有14w升（不知道是不是记错了）空间大小的漫游车到底长啥样子，因为不能把这些东西具象化就看的有点迷惑，再就是改造备用漫游车的时候要在备用车上开个口子，我就想想成在面包车顶上开洞，还有漫游车怎么连接等等都没太明白，最后离开的时候那个敞篷火箭确实nb，( . Y . )哈哈哈；三国记稍微就有点无聊了，虽然我对三国演义中很多地方都保持怀疑，但是看完三国记之后我发现我还是保守了，除了对历史人物的各种事件稍微有了一些了解，还学到了三国这是各种社会阶级的斗争，曹操刘备都是寒门庶族，孙权也算是庶族，曹操和袁绍的斗争算是阶级斗争，算了这些东西我不理解，反正都过去了，我最开始考虑读历史书只是想知道历史的真实情况，然后自己思考得出结论，但是这个确实有点困难，毕竟看的每一本书都会有作者自己的主观意见，当然易中天的这个也一样，最近看大唐历史，之后找一些由一个问题而辩论的书吧，这样思考的多一点，而且都会是我自己思考的结果。周四的书评就这样了，最近玩私服dnf有点上头，最近又好些了。', '2022-02-24', '2022-02-27 19:36:40', '2022-02-27 19:36:40', 1);
INSERT INTO `blog_diary` VALUES (982, 1, '今天把ai算法的任务弄完了，海康门禁下发我看都可以，但是设备还是不行，这个等设备看吧，明天有个新的任务，广东的，也是作业管控的算法，具体明天再说。', '2022-10-11', '2022-10-11 23:19:40', '2022-10-11 23:19:40', 1);
INSERT INTO `blog_diary` VALUES (983, 1, '今天突然变得好热啊，不过上班在办公室没感觉，中午出来也没感觉多热，但是晚上下班特别闷热，快要下雨了吗，回归正题，今天工作任务好多，虽然都是测试，不过南方电网的这个测试完成了，我觉得差不多可以提交了，然后就是一个下午都在弄新疆这个项目，说实话我也不知道一直在忙啥，一直重复，到晚上还没好，下午还看了道算法题，搜索类型的，不知道为啥一直出错，感觉思路没问题啊，明天再去看看，还有说好的看五个视频但是晚上又要调试那个项目抓包看了好久，应该是dms的问题，估计还要等，不知道啥时候是个头，晚上八点之后，因为视频没看完，就留下来看了三个，因为视频实在是太长了，所以只看了三个，不过也没记啥笔记，明天计划一道算法题和至少俩个视频，有时间尽量吧，可能会有其它事情，因为最近这个项目完了，可能会有新的。', '2022-04-12', '2022-04-12 22:56:36', '2022-04-12 22:56:36', 1);
INSERT INTO `blog_diary` VALUES (984, 1, '今天好难受啊，肚子疼了一天，还有项目来了俩个bug，不知道咋处理，明天看吧，今天早点休息了，肚子还是好疼，博客进度是开发完成了文档的目录接口，具体细节还需要以后修改。', '2022-06-20', '2022-06-20 23:04:38', '2022-06-20 23:04:38', 1);
INSERT INTO `blog_diary` VALUES (985, 1, '今天也不是很忙，以后没事干就早回家了，待公司时间长了虽然是玩手机还是会累，而且一晚上也就十七块，没啥可在意的，不如回家玩玩歇会，对自己好一点，这么努力挣钱不就是为了让我享受吗，干嘛把自己搞这么累，为了一个餐补和零食实在是不值得，明天就要放假了，回家的车票还没抢到，感觉是回不去了，但是我现在好想回家啊，项目可以少写点了，最近公司日报每天写那么多，找个时间把我写的日报都拷回来。', '2022-09-29', '2022-09-29 23:39:34', '2022-09-29 23:39:34', 1);
INSERT INTO `blog_diary` VALUES (986, 1, '今天事好多，给我都整乱了，公司代码权限申请了2个，一个是因为失误填错了，因为权限太大被领导驳回，另一个是完全的申请错了，抓图的那个代码权限我本来就有，还给领导打电话，领导批了，之后我撤回，不知道领导看到了会怎么想，之后就是下午改bug的时间，看不懂还得硬上，最后叫过大哥帮我解决问题，还因为我开会把大哥给留我位置上，给我处理问题，开会就是我们几个校招的一起聊聊天，也没啥好说的，晚上就因为白天烦躁，和朋友搞的都生气，处理朋友之间的关系，互相说说为啥生气，还是算可以的吧，希望我以后也一直能够这样，别等以后结婚了成了我爸那样，动不动都打我出气。没想到啊，今天还是不想多写，发生了这么多事情不到2k的空间就写完了。卧槽再水几句。还没2k啊。算了。尼玛。这样应该是够够的了。草。', '2022-03-07', '2022-03-08 00:24:12', '2022-03-08 00:24:12', 1);
INSERT INTO `blog_diary` VALUES (987, 1, '五月三日手痒下载了王者荣耀，没事干就玩了一天（可以学习，但是实在是没干劲啊 T_T ），也没有玩到半夜，主要是被禁赛了，王者荣耀全责，之后也没学习，就那样磨蹭到了睡觉。', '2022-05-03', '2022-05-04 23:44:16', '2022-05-04 23:44:16', 1);
INSERT INTO `blog_diary` VALUES (988, 1, '今天开始写那个导出文件的功能，还是很顺利吧，框架写好了，就是不知道内容是从哪个数据库中获取，因为前端不太会写，今天就开始写博客文件上传和下载的功能，写了一部分，周末继续吧，还有昨天忘了一件事情，昨天是我工作一周年的纪念日，今天差不多就写这么多了，早上起太早了晚上有点瞌睡。', '2022-07-07', '2022-07-07 22:17:34', '2022-07-07 22:17:34', 1);
INSERT INTO `blog_diary` VALUES (989, 1, '小周周六，去了本来打算调通几个算法，但是因为config配置类不知道要怎么填，看文档测试了俩种都不行，也不知道算法那边要怎样，啥也不提供就要调，太难了，今晚打了王者荣耀比赛，去年还进了一轮，应该是48强了吧，今年直接96强，没办法对面实在是太厉害了，真打不过。', '2022-09-03', '2022-09-03 23:43:16', '2022-09-03 23:43:16', 1);
INSERT INTO `blog_diary` VALUES (990, 1, '好几个之前的项目出问题了，还是当时做的不够仔细，也可能是当时没看懂代码逻辑不敢随便修改，今天把公司电脑玩脱了，删了好几个证书，开网页都要验证，图片打不开，没办法只好重装系统，最近这个需求应该是做完了。', '2022-02-16', '2022-02-16 23:32:10', '2022-02-16 23:32:10', 1);
INSERT INTO `blog_diary` VALUES (991, 1, '周五继续看那个对接ai模块的任务，今天可以连上ai模块了，主要是有四个对接的请求，其它三个都好说，都是get类型，主要是有一个保存任务的这个接口有点麻烦，看协议有好多字段我不知道要怎么获取，ai也没有和我对接的人，所以也不知道要怎么办，就先看看下发之前的准备吧，我看先前下发要做好多东西，晚上继续写了一下用户模块，初步完成了角色的增删改查，但是角色授权的还没做，登陆菜单返回的接口也完成了，今天还做好了一个我自认为非常nice的建树算法，以前一直在纠结怎么样能适应任何深度的一颗树，这个今天解决了，因为我写的是一个一个找，所以效率可能会很低，不过好在菜单这个树不可能会有很多数据，所以这个没问题，大概就这样，明天主要写写文档，周日可以部署一下微服务，还有尽量做俩道算法题，不然实在是时间不够了。', '2022-06-24', '2022-06-24 23:26:50', '2022-06-24 23:26:50', 1);
INSERT INTO `blog_diary` VALUES (992, 1, '周五，今天收到了公司搬家的通知，下周五六要搬到新大楼，看群里发的图片感觉新大楼还是挺好的，就是不知道甲醛含量咋样，应该不会超标吧。金华的项目今天结束了，总的来说没出现严重的bug，唯一的一个问题的导出表格的时候因为现场有很多枪机，枪机是没有预置点这个功能的，所以就导致取预置点的时候查找为空，这样插入表格就会报错，其实这个我之前是考虑到的，但不知道为啥没走我之前设置的路线，刚刚想了一下，我之前写的的查找出来的数据长度如果是0则走我设置的路线，可能现场可以根据一个设备编号和通道查出多个预置点吗，只能是这样想了，查到多组数据，而且第一组数据的值还是空的，有点不清楚了，也不知道现场设备预置点有6w多是哪来的，可能会有很多脏数据吧，博客今天继续文件处理模块，新增了图片上传接口，新增了一个存储图片url的数据库，每次图片上传之后图片放到服务器上，现在从服务器上获取图片还没写在服务中，不过现在可以使用nginx代理的服务器下载获取图片，明天可能会写在服务中获取图片的方法，到时候看吧，也不一定。', '2022-07-15', '2022-07-15 23:14:18', '2022-07-15 23:14:18', 1);
INSERT INTO `blog_diary` VALUES (993, 1, '有点瞌睡，明天不去上班，今天先躺床上了。steam在土耳其区购买了王国保卫战4部，塔防慢慢玩。', '2022-12-25', '2022-12-25 20:32:08', '2022-12-25 20:32:08', 1);
INSERT INTO `blog_diary` VALUES (994, 1, '周日没啥干劲，昨天晚睡，今天早上起来都没状态，说好的要学习，结果躺了一天，到晚上都没出去好好吃个饭，一天都在吃储备粮，下周依然是早睡周，今天是真的没啥可写的，水痘药不吃了，感觉差不多要好了，剩下的好靠免疫力。', '2022-04-17', '2022-04-17 22:52:16', '2022-04-17 22:52:16', 1);
INSERT INTO `blog_diary` VALUES (995, 1, '普普通通的周六，今天弄了dnf的90黑岩版本，玩着还行吧，不让国服舒服，但是凑合吧，毕竟是私服。', '2022-07-02', '2022-07-03 00:00:44', '2022-07-03 00:00:44', 1);
INSERT INTO `blog_diary` VALUES (996, 1, '累，今天准备看看token的鉴权，之后考虑博客后端鉴权系统更换。', '2022-03-02', '2022-03-02 23:36:14', '2022-03-02 23:36:14', 1);
INSERT INTO `blog_diary` VALUES (997, 1, '现在是四月五日凌晨一点，因为明天还是清明假期所以晚点睡觉也是可以的，既然都这么迟了就把日记也写了吧，也不差这么一会，今天主要记录俩件事情吧，一是上午去社区那边打完了新冠疫苗的第三针，看了下胳膊上的针口还在，打疫苗是上午去的，但是不知道是因为上午不开门还是我去迟了（11点40左右过去的，虽然10点就出去了，但是旭福说打疫苗不能空腹，又找了个管子吃完饭才去），总之就是上午不能打疫苗，中午回家躺了一会下午一点半去打疫苗，观察半小时俩点二十出来的，之后去了西湖，计划是去某个公园，但是因为人多还是其它没去成，就顺便去了雷峰塔（之前来过几次都是因为太晚了，关门没进去），花门票40进去除了到楼顶看西湖其它的也就那样吧，雷峰塔就看一个遗址，现在看的雷峰塔是在旧雷峰塔上面建造的，没错就是上面，雷峰塔遗址在新建造的这个里面保护起来了，就是一堆砖头，要不是因为历史谁看这玩意，除去保护旧址的俩层上面还有五层里面放着很多木雕，我是外行人，但是那些木雕做的特别精致，而且连起来就是雷峰塔的故事，这个算是印象最深刻的，然后就是到楼顶看西湖风景了，今天天气不错，所以看着特别迷人，简直就是人间仙境（我也吹一波西湖，虽然我不是什么名人），之后就没啥事情了，吃饭、散步、回家，今天又在思考人生了，不知道35岁以后程序员没办法做我还能干啥，走一步看一步吧，人艰不拆。（写日记快一年了，还是流水账，不过我主要是记录生活的，这样也行吧，希望一直坚持下去。）。补充关于计划的事情，周六接口调试还有些问题，明天下午继续，然后就是前端框架搭起来，第二版还准备用Vue2，因为3还没学，用也是瞎搞，2现在起码瞎搞也能下手就这样，明晚记录完成情况。', '2022-04-04', '2022-04-05 19:54:38', '2022-04-05 19:54:38', 1);
INSERT INTO `blog_diary` VALUES (998, 1, '今天公司给过生日，去年把我给丢了，但是今年没忘了，虽然有点紧张，但还是很开心的，从小到大家里都没给过几次生日，没想到在上班之后公司给我过，还有今天璐瑶找我聊天，这么想其实我之前还是不应该决定这样的，还是因为交流太少互相都不了解，我现在都开始摆烂了，现在都在等她啥时候再给我删了，我都已经做好了心里准备，没想到这次剧本变了，之后要怎么做突然有点茫然，首先要慢慢改变性格，别总是内向羞涩，和别人说话又不会把我吃了，就定一个目标，等十二月答辩的时候大方点，给各位大领导展示下我自己，也为了升职加薪，高一我能做到在全班人面前讲题，现在给几个评委讲我做的ppt问题不大，项目最近很忙，澜沧江门禁这个设备树显示异常今晚花俩小时定位了，这个之前我是修改过来的，只不过前端参数没改，直接给我把三方门禁给过滤了，这个前端改改参数就行，下一个黄河鑫业新提出的俩个问题单，一个是经验库布控之后在停用会导致已配置这个经验库的算法出现问题，这个只需要判断已布控的经验库不能停用就行，另一个是导出图片的时候只能导出十二张，也不知道为啥是十二张，我在接口中没有限制过，难道是因为http传输限制大小吗，应该不会这样吧，http导出压缩文件这样的接口很多，也没见网上有相关的文章，明天debug定位下问题，还有就是广东中国石化项目，监听到报警再给盈科也发一份，今天把接口相关的类和接口逻辑都写完了，明天去了完善数据，主要难点是把已有数据转换到盈科需要的数据，目前主要就是这三个项目，都是加急，服了，就这样吧，好久没写长篇日记(流水账)了。', '2022-10-26', '2022-10-26 23:42:32', '2022-10-26 23:42:32', 1);
INSERT INTO `blog_diary` VALUES (999, 1, '周六啥事没干，但至少还弄好了项目，看了看学习视频。', '2022-03-26', '2022-03-27 20:36:50', '2022-03-27 20:36:50', 1);
INSERT INTO `blog_diary` VALUES (1000, 1, '晚上回来躺着不想动，刚刚处理了下git提交不了的问题，但是没解决，今天做了啥不想写了，明天再写，太累了。', '2022-09-14', '2022-09-14 23:45:46', '2022-09-14 23:45:46', 1);
INSERT INTO `blog_diary` VALUES (1001, 1, '周五记得写日记呢，但是因为周六不用早起就玩到十二点多了（保守估计，可能更晚），所以就没写日记，但是周五除了公司项目也没做其他，倒是最近稍微有点闲了，可以开始看看博客。', '2022-11-04', '2022-11-07 00:14:40', '2022-11-07 00:14:40', 1);
INSERT INTO `blog_diary` VALUES (1002, 1, '解封了，可算是快上班了，今天又是睡了一天，上午做的核酸，结果正常，是我想多了，但还是感觉呼吸道里面有什么东西。', '2022-02-05', '2022-02-05 23:20:20', '2022-02-05 23:20:20', 1);
INSERT INTO `blog_diary` VALUES (1003, 1, '27号，算是隔离的第一天，昨天没写日记，懒得再补了，心累，这几天操作都好迷啊，先是提前好几天做了核酸检测，之后同事去做核酸的时候我没一起去，也不知道为啥既然不去做核算还要回家取上身份证，本来想去蓝臣那边去做核算，结果路上看到了好像是长江小区被隔离了好多人站在铁网墙边上等外卖，看着好吓人就像丧尸被隔离了一样，因为蓝臣宾馆就在长江小区那边，因为害怕感染（可能是吧，有可能怕影响回家反正就是没去）就走半路上回公司了，昨天下午也没做啥事情，到晚上突然要求所有人去做核酸检测，没办法就下去做了，虽然我应该也不会感染吧，可别是伏笔啊，今天早上醒了果然东冠社区查出来了，现在滨江区都不让回去了，火车票退了扣了60多，留杭州的补贴也没了，春节吃饭都是问题，不知道咋搞，心情沉重，游戏都没办法好好玩，因为是合租就和一起租房的大哥一起吃饭，现在就盼望能够正常恢复上班吧，想哭，太绝望了。我为啥没回家呢，是害怕传染到家里人吗，不写了，越写越心酸，明天找个书看看吧，看看别人悲惨的经历我可能也会更有勇气，还有一个人在杭州好孤独啊，要回北京吗，哎。', '2022-01-27', '2022-01-27 20:38:48', '2022-01-27 20:38:48', 1);
INSERT INTO `blog_diary` VALUES (1004, 1, '正常的周六，没看啥学习的，玩游戏，看视频，休息一天，晚上看rng比赛。月中了，视频不抓紧看可能会看不完，之后稍微计划一下学习内容。明天起来看看。', '2022-05-14', '2022-05-15 00:03:52', '2022-05-15 00:03:52', 1);
INSERT INTO `blog_diary` VALUES (1005, 1, '又到了月底，先记录五月份的情况这个月计划的微服务视频看完了，12道算法题也正常完成，博客文章写了四篇，其实还可以写几篇最近学习微服务的文章，但是学艺不精下个月还要再练练，所以这个月总体情况还是可以的，进度都正常，下个月计划是学习oauth2.0，学这个主要是做一下微服务的鉴权中心，现在其它框架都可以做好，但是这个鉴权中心是最重要的，所以要单独学习一下，具体要看哪个视频还没想好，六月的计划大概就这些，然后是今天的任务和一些事情。项目上把南通桐昆的项目提交了，但是晚上发现个小bug，这个是因为前端传的一个参数改了，之后测试没发现，其它的问题暂时还没发现，明天和前端调试一下赶快把这个bug修改了，也不知道为啥定制的需求没有测试专门给测一下，每次都只能自测，自测那总会用忘了的测试功能，还有测过一次但是发生修改变化的功能，不过只要不出大问题就行吧，下午还发了端午礼盒，有四个粽子和四个鸭蛋，晚上看微服务视频的时候领导叫道洽谈室聊了聊，得知喜讯现在岗位级别升了一级，到了11级，不知道会不会涨工资，非常期待。', '2022-05-31', '2022-05-31 23:34:22', '2022-05-31 23:34:22', 1);
INSERT INTO `blog_diary` VALUES (1006, 1, '到了杭州，排了俩小时做核酸的队伍才做完出站，看电子书。', '2022-10-09', '2022-10-10 23:11:58', '2022-10-10 23:11:58', 1);
INSERT INTO `blog_diary` VALUES (1007, 1, '周日是真啥事没做，现在想睡觉了，好无聊。', '2022-03-27', '2022-03-27 20:37:26', '2022-03-27 20:37:26', 1);
INSERT INTO `blog_diary` VALUES (1008, 1, '今天真是离谱，之前南通的项目有部分逻辑没看懂，所以写完就产生了一个严重的bug，所以我要在本地环境测试一下，为了搭建修改之前的系统环境我就用那个运维平台反向升级，结果导致服务器的数据库删了不少，要是没有导师我就凉凉了，下午也是修改那个bug我没太明白那部分代码的作用，还是在导师的指导下修改的那个bug，现在应该是没啥问题了，之后再具体测试一下，不想写了，打打游戏。', '2022-05-27', '2022-05-27 23:06:36', '2022-05-27 23:06:36', 1);
INSERT INTO `blog_diary` VALUES (1009, 1, '今天主要学习了shell，把安装MySQL，nginx等软件都写到了shell里面，以后安装就方便多了，然后就没做其他了，还是今天太懒了，晚上都没看微服务，可能今天进度稍微慢了一点，周末希望会看一下吧，不过周末也就是周日了，周六要团建去爬山，有点期待，晚上玩盐与避难所，打到了牢笼红厅，就是可惜最后丢了1w盐，难受。', '2022-05-19', '2022-05-19 23:19:06', '2022-05-19 23:19:06', 1);
INSERT INTO `blog_diary` VALUES (1010, 1, '今天去了把作业广场调试好了，还有河南机器人项目给升级了数据库，机器人版本也升级了，希望不会再有那些莫名其妙的bug，虽说是周六，今天上班也是6点才下班，稍累。', '2022-09-17', '2022-09-17 23:27:10', '2022-09-17 23:27:10', 1);
INSERT INTO `blog_diary` VALUES (1011, 1, '玩了四小时文明6，不早了，赶快睡觉。', '2022-11-23', '2022-11-24 01:59:08', '2022-11-24 01:59:08', 1);
INSERT INTO `blog_diary` VALUES (1012, 1, '今天阳了，主要就是头晕，不知道有没有发烧，因为没温度计，晚上现在好多了，昨天部署的博客导航页面的图片加载不出来，晚上还稍微看了看问题，先躺下了，睡不睡另说。', '2022-12-23', '2022-12-23 21:54:38', '2022-12-23 21:54:38', 1);
INSERT INTO `blog_diary` VALUES (1013, 1, '最近好累，就不该看那个电子书，公司项目今天我把我能做的都做完了，剩下的也不知道要怎么搞，明天去了再说，晚上下班的时候路上有很多积水，并且当时还在下雨，路过一个水坑的时候被旁边的一个电动车溅了一身水，真tm来气啊，同一个位置第二次了，真是日了狗，以后来一个我骂一个，没点素质的傻逼玩意，算了控制一下情绪，下午还抽时间写了一下博客，博客的日志中心我计划就做在网关里面，因为所有请求都是通过网关转发的所以这样会省点事，但是今天获取请求用户ip的时候出了点问题，实在不行写个注解也可以，只不过要单独创一个模块，明天抽时间再看看，之后再做决定。', '2022-07-19', '2022-07-19 23:23:34', '2022-07-19 23:23:34', 1);
INSERT INTO `blog_diary` VALUES (1014, 1, '22年的第二天，过的还算充实，正如昨天说的，今天是没有上午的日子，下午整理了几篇博客然后就不想再继续整理了，有点烦，就看了之前收藏的博客，是做qq机器人的，用qq号发一些定义的好的消息，然后我就跟着博客敲代码，等我写好用我自己的qq测试结果俩个号都没通过，问我之前用过什么头像，这我咋知道啊，都好年没换过了，无奈申请了一个新的qq号，这次倒是没问我验证登陆，但是它代码报错了（连接失败等报错，还有换协议之后有一个滑块验证的错误），因为不是我自己写的代码，报错我也不会解决，只好等待大佬接下来的文章看看怎么解决，还有下午打算出去理发，结果去了旁边社区里面发现那个社区里面的房子都改造了，不让开商店，自然那个理发店也关门了，好不容易出去一次都是这个样子，还是等回家理发吧，正好今天买了把梳子，还买了个usb口扩展槽，最近感觉usb口不够用了笔记本就三个口，我鼠标键盘都需要，旁边的那个屏幕也需要，还有搞安卓连手机也要用，所以就买了一个，应该不会吃灰，最后就是晚上原计划去玩泰拉瑞亚，但是今晚有点冷，手都不想伸出来，所以就没玩，一直在找安卓的开源项目，看了好多他们都是好几年前的项目，安卓技术更新又那么快我就没使用，不过功夫不负有心人，我在gitee上面找了一个几个月前的项目，下载好之后看他那个样子也没写多少只有个页面，还没有操作数据库的方法，这个还需要我之后通过百度查询，最近vpn流量因为我下载游戏全用完了，太难受了github打不开，epic也进不去，上网的乐趣少了不少，今天就这样吧，躺下看看动漫，年底总结等到春节再做？假期明天还有一天，可以看看那本书，希望能做到，然后就是安卓稍微写写，尽量弄好连接数据库的这一步。', '2022-01-02', '2022-01-02 23:04:16', '2022-01-02 23:04:16', 1);
INSERT INTO `blog_diary` VALUES (1015, 1, '周六不想睡觉啊，下午去了公司写了一篇半博客，另一篇题解差一点，需要画个图，之后就看vue，大概就这些。', '2022-02-19', '2022-02-20 00:17:18', '2022-02-20 00:17:18', 1);
INSERT INTO `blog_diary` VALUES (1016, 1, '今天任务不是很多，但是南方电网的这个项目有点烦啊，需求都不说清楚，直接让我怎么怎么改，改完了又说有问题，真的服了，今天就用空闲的时间做了下博客，不过又要月底了，算法题还没开始，先不说这个，今天把自行车胎补好了，外胎换了一个，明天就不用走路上班了，昨晚起的杭州自行车还没给确认还车成功，看来免费的效率确实低。', '2022-04-19', '2022-04-19 22:56:38', '2022-04-19 22:56:38', 1);
INSERT INTO `blog_diary` VALUES (1017, 1, '今天虽然什么都没干，但还是不快乐，明天赶紧答辩完成，好让我松一口气。', '2022-11-21', '2022-11-21 23:12:36', '2022-11-21 23:12:36', 1);
INSERT INTO `blog_diary` VALUES (1018, 1, '因为耽误了火车，不过也正好赶上了妈妈过生日，做核酸，看电子书。', '2022-10-07', '2022-10-10 23:11:06', '2022-10-10 23:11:06', 1);
INSERT INTO `blog_diary` VALUES (1019, 1, '今天心情不好，晚上去江北走了走，主要是路上骑自行车散散心，莫名其妙啊，是因为那本电子书看完了吗，不过书里的爱情故事毕竟的最理想的，现实中怎么可能会有，不过看完还是很感动。', '2022-10-15', '2022-10-15 23:21:08', '2022-10-15 23:21:08', 1);
INSERT INTO `blog_diary` VALUES (1020, 1, '今天好几个现场都要修改bug，黄河鑫业，海康门禁，盈科三个现场发了四个包，黄河鑫业应该暂时没我啥问题了，明天准备ppt修改，晚上去理发除此之外就是平平淡淡的一天了。', '2022-11-15', '2022-11-15 23:29:08', '2022-11-15 23:29:08', 1);
INSERT INTO `blog_diary` VALUES (1021, 1, '昨天还看了shell的定时任务，忘记写了，今天主要是开始项目，不过现在大概是完成了，修改brm项目的时候看到了好多没见过的写法，明天去了记录一下，以后在博客中也试着用一下，下午做完项目需求之后写了一道算法题，不过昨天说的优化昨天ac的那道题，今天没做，明天要做吗，大概吧，到时候看情况，晚上微服务看了半小时，还有最后30个视频，这个月应该是能完成，这周末要不写篇博客？到时候随缘吧。', '2022-05-25', '2022-05-25 23:12:02', '2022-05-25 23:12:02', 1);
INSERT INTO `blog_diary` VALUES (1022, 1, '今天没什么事情，然后就开发博客的前端页面，算是把首页完成了一大部分，做好的页面个人感觉还是可以的，明天有个机器人的项目，这个不要求开发，算是要解决现场的问题，晚上吃饭还给我打了个电话，实在没听清楚要干啥，之后联系应该是现场机器人注册到服务器的时候报错了，晚上看了看基线的这个项目代码，还找了机器人注册时候的协议，就差明天现场看日志，定位问题原因，再说一下昨天，昨天下午都打开准备看看代码了，但是我手抽打开了steam，然后等关的时候就晚上12点了，中间具体发生了什么我也不知道，时间就那么凭空飞走了。', '2022-07-25', '2022-07-25 23:18:58', '2022-07-25 23:18:58', 1);
INSERT INTO `blog_diary` VALUES (1023, 1, '今晚把南方电网的这个项目提交完成了，不出意外的话应该是五一之前只剩新疆刺火项目的bug调试任务了，这个希望一切顺利吧，因为之前都调试好了，等明天设备那边把后智能服务器弄好测试一下，希望明天不出问题，然后到五一没其他任务，是不是有点想的太美好了，这些是项目的任务，今天下午不是很忙做了几道算法题，主要都是搜索的算法，熟悉了一下dfs和bfs总体还行吧，主要思路都还记着，五一放假了把笔记写一下，晚上除了调试项目还继续看微服务的视频，最近学到了eureka的集群，稍微立个flag，等学完微服务，我自己把博客也弄成微服务类型的，这个就不好说多久了，只能尽快把，因为之后还要继续学习vue，还是差太多了，啥都不会。', '2022-04-25', '2022-04-25 23:14:54', '2022-04-25 23:14:54', 1);
INSERT INTO `blog_diary` VALUES (1024, 1, '可算是五一放假了，今天写完了岗位升级的ppt，然后开始写在公司做的一些项目的总结，还有本月的12道算法题也做完了，今天稍微放纵一下，毕竟好不容易刚刚放假了。', '2022-04-29', '2022-04-30 00:03:40', '2022-04-30 00:03:40', 1);
INSERT INTO `blog_diary` VALUES (1025, 1, '居家隔离的第三天发生了好多事情，首先是我的快递全没了，被拦截了，滨江区全面隔离，快递都不让进来，毒圈真可怕，然后就是合租的那大哥不知道为啥那么敏感，可能是我的原因吧，之后就要自己吃饭了，这几天还能点外卖，过几天要饥荒了，这是真的饥荒，希望快点过去吧，还有今天公司的年终奖到了，一个月的工资10088，比周围好多人都高，果然得开卷啊，还有今天第三次核酸没做，想出去都不行，还有啥事呢，算法今天做了一道，没看博客，算是事情较多，好烦啊，只能看动漫了，祭坛看了未来都市No.6。', '2022-01-29', '2022-01-29 23:59:32', '2022-01-29 23:59:32', 1);
INSERT INTO `blog_diary` VALUES (1026, 1, '今晚回来把博客部署完成了，本来在公司测试还有点问题，回家之后修改了nginx的配置之后就可以了，还可能是之前执行部署脚本文件的时候没给权限，导致sql没写进去，不过不管怎么说可算是部署成功了，明天去了完善下脚本，之后就要及时更新博客的版本，新增功能和完善已有功能，之后还完泰拉瑞亚，今天打完了黑长直和蜂王，之后几天就不挑战新boss了，先探下地图，合几个饰品，今天都没说项目，主要最近没有开发任务，现在这几个项目都开发完成了，都是在现场测试，所以我这只能等现场把其他工作完成之后再测试接口，海康门禁的bug和新增的一个功能，还有一匙通对接第三方接口的任务，这个也在等第三方弄好环境，接口内部都测试过，应该不会有太大的问题了，中州换流站的项目就是加一个接口，改完测试也没啥问题，最近胃酸，不知道是不是因为我每天晚上回来吃夜宵的原因，之后得少吃点，因为之前没发生过这样的事。', '2022-12-07', '2022-12-08 00:00:02', '2022-12-08 00:00:02', 1);
INSERT INTO `blog_diary` VALUES (1027, 1, '小周周六，衣服脱了太冷了着急睡觉。', '2022-12-03', '2022-12-03 23:54:48', '2022-12-03 23:54:48', 1);
INSERT INTO `blog_diary` VALUES (1028, 1, '今天调好了大部分算法，有几个算法因为前端一开始不支持，所以之后就没调，明天可以完成剩下的算法下发，然后测试定时任务这个功能，晚上有时间看了看博客，稍微写了一点界面，但是还是太差了，js还是差太多。最近看平家物语，感觉还不错，但是有点看不懂。', '2022-09-07', '2022-09-07 23:09:40', '2022-09-07 23:09:40', 1);
INSERT INTO `blog_diary` VALUES (1029, 1, '今天去了公司几乎没做什么事情，本来打算写写博客，结果因为重装系统了，电脑上没有MySQL，光是安装MySQL就搞了很久（因为公司的电脑d盘有时候会没权限创建文件夹），之后本以为可以运行了，又发现redis也没弄好，整完这些差不多就没时间了，还有《挽救计划》看完了，怎么说呢，这个是我看的第二部科幻小说，因为我看过的科幻小说不是很多，所以也不知道该怎么写书评，我就写写我的观后感吧，首先文章是双线叙述，刚开始看的时候真的是一脸懵逼，最近看的《火星救援》也是这个作者，同样的双线叙述，不过这个好多了，说回《挽救计划》，总体感觉还是可以的，本以为主角是大公无私，为人类牺牲自己，毅然决然的去执行计划，到最后才知道是被别人“绑架”（也差不多）出去的，再到为了拯救朋友愿意放弃自己的生命，人物形象塑造的还是还好（我瞎写的），最后一句话概括全书内容大概就是：为了拯救太阳、拯救人类，不得不去外星系远航的故事。好像我把最重要的外形接触删了，不过算了，毕竟我只是个文盲，也没太多文采，看书也就是看个热闹，写书评就当是记录人生了。', '2022-02-20', '2022-02-20 23:49:36', '2022-02-20 23:49:36', 1);
INSERT INTO `blog_diary` VALUES (1030, 1, '大周的周五真是快乐啊，只是可惜明天要在家远程，现场的机器人问题好多，今天调试一整天，可算是把机器人云台和本体的控制弄好了，不过机器人那边说机器人本体不能左右转，但是我记得之前好像左右操作过，不知道是不是他们偷懒不做了，还有机器人那边真的效率太低了，明明指令都发下去了，还改了俩天，到今天下班了才弄好，剩下我的任务就只能周末加班处理，真是越想越来气，明天上午看问题的开发人员说没时间，然后只能下午看了，不过我倒是没啥事，我只负责定位问题，因为这个不是我开发的，我就管定位问题，找开发人员解决，我感觉这个问题得改代码，总不可能我操作错了把，毕竟按钮就那几个，随便点几次总会有一次可以触发，但是机器人那边就是没收到任务开始的指令，博客开发今天几乎没进度，因为一整天都在调试机器人。还有晚上宿舍群里面豪哥竟然复活了，大四之后没当兵回去高考，还是理转文，考了211，人和人之间还是有差距了，虽然有些羡慕，但是我对我自己的工作和专业也都很满意。', '2022-07-29', '2022-07-29 23:50:52', '2022-07-29 23:50:52', 1);
INSERT INTO `blog_diary` VALUES (1031, 1, '看电子书。', '2022-10-03', '2022-10-10 22:52:58', '2022-10-10 22:52:58', 1);
INSERT INTO `blog_diary` VALUES (1032, 1, '拖着，明天写。周五搞了一晚上自己的地下城，最后还是放弃了，现在玩的那个服务器上的地下城现在也懒得玩了。', '2022-02-25', '2022-02-27 19:38:00', '2022-02-27 19:38:00', 1);
INSERT INTO `blog_diary` VALUES (1033, 1, '周五忘了写日记，具体就是开发经验库接口吧，图片上传接口找oss人解决了。', '2022-09-23', '2022-09-26 22:49:42', '2022-09-26 22:49:42', 1);
INSERT INTO `blog_diary` VALUES (1034, 1, '桐昆现场又出个问题，服了啊，不过这个应该是他们清理数据库删错数据了，所以导致有个设备删不掉，但是啊今天放假了，管他什么问题等下周一再说吧，明天出去看看房子吧，想换个房间。', '2022-06-02', '2022-06-02 23:29:08', '2022-06-02 23:29:08', 1);
INSERT INTO `blog_diary` VALUES (1035, 1, '今天又是焦虑的一天，公司没啥可做的，算是摸鱼，做做自己的项目，即使被裁也有信心找下一家公司，我要当卷网，今天vue又稍微熟练了一点。', '2022-08-15', '2022-08-15 23:24:38', '2022-08-15 23:24:38', 1);
INSERT INTO `blog_diary` VALUES (1036, 1, '明天是清明节，放三天假，假期也没什么事情，今天除了公司的任务，还吧博客的用户和角色接口测试完了，问题也不是很大，现在腰疼，就像躺着，日记先这样吧，今天也没什么其它事情了。', '2022-04-02', '2022-04-02 21:34:00', '2022-04-02 21:34:00', 1);
INSERT INTO `blog_diary` VALUES (1037, 1, '又盼到了周末，可惜明天是小周，一天一天的好快，今天项目进度稍慢了点，定时任务的线程没写，下午还提交了职级晋升的ppt，但是我几乎没写，之后补齐把，这次职级晋升没多大希望，反正刚涨工资，晋升也不会再涨工资，没太大期望，睡觉。', '2022-10-21', '2022-10-21 23:47:40', '2022-10-21 23:47:40', 1);
INSERT INTO `blog_diary` VALUES (1038, 1, '今天做了之前的那个添加报警类型的任务，我觉得应该是写完了，可能明天去了还要修改一下log4j的版本号，其它没什么问题，然后就是今天做了博客后端的开发，还是那个vue的项目，不过先看后端，前端之后再说。', '2022-03-17', '2022-03-17 23:13:06', '2022-03-17 23:13:06', 1);
INSERT INTO `blog_diary` VALUES (1039, 1, '周一上班好累，每次周末都不会好好休息，今天上班写那个机器人调试bug的文档，写了一天，不知道要怎么写，不过最后还是写了一点出来，因为瞌睡今天没干啥事情，又是混日子的一天。', '2022-01-17', '2022-01-17 23:46:44', '2022-01-17 23:46:44', 1);
INSERT INTO `blog_diary` VALUES (1040, 1, '春节假期之后上班的第一天，还有好多人今天没来，晚上留下了加班的也不是很多，不过无所谓了，因为春节假期留杭州，在家呆的太烦了，所以就晚上九点回家，在公司既不冷，还有电脑和同事，晚上还能拿个水果，真是不要太爽，还有今天因为是复工第一天，去了公司还有个盲盒和一个刮刮乐，盲盒看说明是有9个礼物，然后我就中了那个隐藏的算是欧皇吗，还有刮刮乐领导给我的就是一个中奖的，虽然给我的时候没刮开，然后去找hr兑换了100块，这一天太棒了，不过福祸相依，最近小心一点，博客半个月没看今天完成了那个博客文章标签的功能，算是有点进度，现在有点难受，不写了，睡觉，还有最近没事干打三国杀，还挺好玩。', '2022-02-09', '2022-02-09 23:31:44', '2022-02-09 23:31:44', 1);
INSERT INTO `blog_diary` VALUES (1041, 1, '本周小周，下午过去公司把博客项目的角色管理页面写了写，目前进度有70%，明天再稍微努力下估计能完成，今天四愣子阳了，我现在好慌啊，防疫物品啥都没，甚至口罩都用完了，总之现在是能躲一天算一天吧，年底到底是要不要回家我也不确定，车票是肯定能买到的，就是怕路上新冠阳了，不过我也没必要考虑那么久没准这几天我也阳了，希望是个flag，别真阳了，我还是稍微有那么一点点害怕的，明天中午吃法就不去餐厅堂食了，中午过去打包几个饺子回来吃，晚上就泡面，就一天假期凑合凑合就过去了，马上年底了，该总结今年的任务，这几天就赶赶博客，争取把博客的基础功能都完成了，最近vue也熟练多了，设计不出好看的界面，至少弄出来的功能是有的。游戏最近哈迪斯和消光都在玩，哈迪斯要完成全成就，消光就不追求了吧，不过可以看看具体的成就好不好做，之后就是泰拉瑞亚，这个拖了有点久，最近不太想玩这个。', '2022-12-17', '2022-12-17 23:53:30', '2022-12-17 23:53:30', 1);
INSERT INTO `blog_diary` VALUES (1042, 1, '每个月最快乐的发薪日，虽然不多，但是每个月攒个6k也行，争取今年攒个10w，不说这个了。今天项目任务主要就是完成了那个搜索和统计的接口，功能应该是没啥问题，但是我代码写的实在是太乱了，明天去了把这个接口稍微优化一下，然后就是其它的还有三个接口要添加（删除，容量，自定义信息的三个），还有统计详细页面修改的那个接口，添加的那三个问题不是很大，主要是详细页面统计的这个，业务有点复杂，明天去了理一理应该是周四能写完这个，微服务的视频现在学到了网关，这个在公司项目里面也经常看到，希望学完之后能够熟练使用吧，整个学习的笔记之后再开始记录，五月份还是专注视频吧。', '2022-05-10', '2022-05-10 23:29:20', '2022-05-10 23:29:20', 1);
INSERT INTO `blog_diary` VALUES (1043, 1, 'spring security的那个项目快看完了，最近游戏时间得减少，每天晚上都想现在一样玩到半夜，这周vue的前端要开始做一下了，不然后端都写完了，不做没啥意义，今天项目上没什么事情，昨天改的电视墙也没说有没有问题，然而今天晚上加密狗的那个现场有说有问题，不过晚上看了一下，好像是不需要修改的，每天就继续spring security的这个项目，对了应届生的那个讨论小组要分享一些内容，我抽到了第五名，不过也应该开始考虑要分享什么东西了，今天璐瑶也入职了（我不当天舔狗），偶尔会有聊天，也不知道她在想什么，差不多了，不想再写了，刷个牙睡觉。', '2022-03-23', '2022-03-24 00:12:06', '2022-03-24 00:12:06', 1);
INSERT INTO `blog_diary` VALUES (1044, 1, '虽然昨天说的今天要看前端，但是今天没看，睡个懒觉起来十点半左右吧，看看视频吃完饭就下午了，然后做了计划很久的收拾房间，总之还是可以的，把很多没用的东西都丢了，收拾完才发现我真是个破烂王啊，有好多没用的东西比如买摄像头下面的支架，买车胎送的拆胎工具，还有那个气嘴太短的车胎等等，最初没直接丢了，想着毕竟东西刚买直接丢了也不合适，然后放了这么长时间最后还是丢了，以后还是没用的东西直接丢吧，再也不当破烂王了。博客今天就整理下在公司写的代码，把前后端都提交上去了，明天去了一定要理清巡检的代码逻辑，巡检这个是一条任务调用链，一共有九个类，主调用链路是九步还有其它其它错误的支线链路，这个可以说是我做过最难的项目了，虽然改动就是将一个报警改成不报警，但是这个不懂代码的执行链路逻辑根本没办法修改，所以只好硬着头皮去看，报警的明天一定要处理完成啊，再拖就没时间了，项目截至这周五，最后一周时间，周二计划主页面的接口新增，以及导出表格的调试，最后到周三实在有些不会的再请教导师。', '2022-07-10', '2022-07-10 23:40:42', '2022-07-10 23:40:42', 1);
INSERT INTO `blog_diary` VALUES (1045, 1, '对接了ai模块，协议还是有几个不太清楚，明天继续吧，找找数据，再看看，感觉这个任务也不简单，博客我还是继续开发接口吧，接下来做文件上传的功能。', '2022-06-27', '2022-06-27 22:17:52', '2022-06-27 22:17:52', 1);
INSERT INTO `blog_diary` VALUES (1046, 1, '今天任务就是在家躺尸，而且超额完成任务，下午睡着了一觉睡到晚上八点半，晚饭都没得吃，导致现在睡不早。', '2022-08-27', '2022-08-28 00:07:02', '2022-08-28 00:07:02', 1);
INSERT INTO `blog_diary` VALUES (1047, 1, '今天买的显示屏到了，因为我俩个显示屏都是hdmi的线，所以找曹邵哲借了一根vga的线，然后就可以双屏工作了，这样写前端，百度之类的屏幕多，看着舒服，博客这周没时间做，也就晚上可以看一下，前端暂时不设计新的了，写也写不出来，太难了css，不会调样式，就用旧的博客风格，明天就发工资了，有点期待，工资是11600还有2000的不知名奖金，可以到手12000吗？', '2022-08-09', '2022-08-09 23:34:08', '2022-08-09 23:34:08', 1);
INSERT INTO `blog_diary` VALUES (1048, 1, '中石化项目今天还没给分支，明天去找项目经理问问，别人家认为我已经开始开发了，我这边却是在等分支，今天也没完全闲着，黄河鑫业现场脏数据又出来了，不是我之前分析的那种情况，今天猜可能是前端保存任务没有设置点击之后禁用，所以就会下发多次，当然我的算法任务也会创很多，可能是因为这样导致很多脏数据产生的，所以今天把下发改成了异步的操作，本来要把删除也改成异步的，但是因为删除要等待dp返回的结果来判断我这是否要删除这条数据，所以就没修改这个接口，没事的时候继续开发我的博客，进度依然很慢，但这次要一个一个的开发，之前都是想的很美好，创好几个，结果一个都做不好，这次慢慢来，就是从开发到设计都是边想边做有点累，晚上本来是要参加一个会议，但是人满了，就没进去，不过正合我意，今天开发前端遇到不少问题，不过都解决了，不是什么难好几天的大问题没必要记录，晚上回家就绪消光，我玩着玩着来了个大佬，准备给我送武器，但是我没要，用那些超进度的武器通关没啥成就感，还有我的衣服不知道为啥调楼下了，然后被人挂在楼道门口，当时看到还以为是遇到同款了，不过那种几率可以忽略不记，我就拿上来了，去哪边确认果然是我的，也不知道为啥衣服就飞下去了，还有早上洗漱完，洗脸盆也没拿回来，今天是真的郁闷，啥都忘，又到一点了，出去刷个牙准备睡觉。', '2022-11-09', '2022-11-10 00:05:42', '2022-11-10 00:05:42', 1);
INSERT INTO `blog_diary` VALUES (1049, 1, '今天上班，去了公司给我说之前做的ai下发config是错的，我人懵逼了，之前做了俩周，这个格式都是算法给的，现在给我说弄错了，真服了，没办法只能我来改，晚上下发还是有问题，明天去了继续看，这个中秋假期玩了三天游戏，其实也是想玩了，有好几个月都没看steam，想玩了，最近还是继续公司的项目，有时间看博客。', '2022-09-13', '2022-09-13 23:08:14', '2022-09-13 23:08:14', 1);
INSERT INTO `blog_diary` VALUES (1050, 1, '今天开始一定要戒了电子书，这周还没怎么加班，也不打算加班，最近好心累。', '2022-10-19', '2022-10-19 23:04:28', '2022-10-19 23:04:28', 1);
INSERT INTO `blog_diary` VALUES (1051, 1, '十一月了今天还是摸鱼，看博客那个前端日记这块有点不会搞了。', '2022-11-01', '2022-11-01 23:58:14', '2022-11-01 23:58:14', 1);
INSERT INTO `blog_diary` VALUES (1052, 1, '周日把攒一周多的衣服都洗完了，今天没玩游戏，但是想找一个类似dnf那样的刷子游戏，但肯定不能是dnf，因为只是怀念以前和朋友一起玩dnf的日子，并不是想玩dnf，之前一个人搭服务器玩也就那样，有的是魔改版本，还有的和我想象中的不一样，反正就是现在台服dnf不想玩，想找个类似的刷子游戏，今天看到了无主之地2，看评价还算可以就在土区买了一个，不过不着急玩，最近一直在玩文明六，下周先不玩了，要先把消光通关了，不能打一半放弃，文明六也不卸载，等之后联机一起玩，还有其它的游戏，比如饥荒之类的都要自己玩通关一次，下周就消光，还有最近在考虑要不要捡垃圾，当个垃圾佬随便凑一个能玩3A的电脑配置，不过就算是买新卡也不是买不起，有点纠结，不知道是随便买一个凑合用还是要买个好点的，还是在考虑考虑吧，就算是捡个垃圾，新主机还是要配的。', '2022-11-27', '2022-11-27 23:53:58', '2022-11-27 23:53:58', 1);
INSERT INTO `blog_diary` VALUES (1053, 1, '稍微关注了一下昨天飞机坠毁的消息，几乎是垂直扎地上的，应该是没人能够活下来吧，毕竟飞机残骸都没一个大块的，逝者安息吧。今天的项目进展还是挺快的，和前端测试完了，到8点我都要走了突然发现个问题，等明天去了看看，还有之前做的电视墙任务，出问题了，任务加载不出来，这个问题测试的时候其实就有，我以为是其它的问题，因为我测试的时候重新开一下就好了，不过还是我测试的不全面，今天下午紧急打了个包，发过去，不知道有没有改对，毕竟是靠直觉感觉那有问题，修改之后也没测试，学习的spring security晚上又看了一点，还有个事就是档案的事情，需要我把身份证和毕业证邮寄回家，不过毕业证我好像没带走，明天问问家里，然后这几天写好那个文档一起都做完，还有这周得a6题，今天看来一道，我是没思路，但那个题是数学公式题，可以写一篇博客，又想到博客，博客旧版不更新了，学完spring security就开始搞新版本的博客。', '2022-03-22', '2022-03-23 00:26:56', '2022-03-23 00:26:56', 1);
INSERT INTO `blog_diary` VALUES (1054, 1, '今天白天都在肝dnf，不过还好吧，因为不想做别的，晚上看了下博客服务器不知道为啥有了些问题，部署的时候调用后端接口请求不到数据，等明天晚上回来看看吧，今天又借出去11k，现在都累计15k了，倒不是担心钱还不回来，但是还是有些担心把，算了，这不是个大问题，总不能不给借吧，写不出来了，差不多就这样。', '2022-03-06', '2022-03-06 23:56:26', '2022-03-06 23:56:26', 1);
INSERT INTO `blog_diary` VALUES (1055, 1, '返工第一天，没什么事情，主要在做海康门禁这个，新包已经给到了现场，明天部署，对接ai算法的也没出现太大问题，今天还算可以，因为国庆一直在看电子书，这个月可能需要稍微重视下博客了，之前忙，假期也没怎么学习。', '2022-10-10', '2022-10-10 23:13:48', '2022-10-10 23:13:48', 1);
INSERT INTO `blog_diary` VALUES (1056, 1, '不得不说今天的任务又没完成，实在不是因为我偷懒，今天项目任务太多了，一点时间都没有，即使今天是周三晚上都加班到了9点，现在是有四个项目，首先就是作业管控的这个dms还是没调通，卡好久了，实在是难受啊，然后就是今天晚上给的这个比较紧急，要明天上午做完，这个算是稍微简单一点的，只要把centos服务器上的那些软件的版本信息整理到文档中，明天上午的事情，然后就是南方电网的这个，做完了也测试过，我觉得是可以提交了，最后一个项目是智慧加油站修改了几个bug，要在测试一下是不是改对了，算是修改完成之后的确认，大概就是这四个项目了，希望明天别出什么问题，明天就是把南方电网的这个修改提交完成，word整理的这个必须完成，智慧加油站的这个尽量测试，剩下就是继续调试作业管控的这个，计划就不敢乱写了，尽量把之前定的这个完成，尽快把，也快十一点了就写这个，先睡觉了，晚上十点回家，真的太辛苦了，钱不好挣啊。', '2022-04-13', '2022-04-13 23:00:22', '2022-04-13 23:00:22', 1);
INSERT INTO `blog_diary` VALUES (1057, 1, '五一第一天也是四月最后一天，稍微总结一下四月份的任务完成情况，以及五月份的计划。首先是四月份的任务完成情况，我先看看三月底当时的计划。怎么说呢，任务大部分都没完成，就不找借口了，主要还是因为懒，其次还有一些计划的变更，第一条vue视频看完，这个算是任务变更，因为时间就那些，视频我也不能加速去看所以这个任务稍微变更了一下，改成了看微服务的另一个视频，截至目前已经看了大概三分之一了吧，仔细多少集我没看过，但是进度差不多是这个样子的，这个计划在五月份看完，然后是算法题，这个没什么问题，12题都是仔细思考过的不是那种入门的水题，所以是应该写完六篇博客文章的但是我没完成，还有计划的博客第二版上线这个也算是任务修改吧，因为之前计划是做成单个服务使用spring boot和spring security做后端，这个其实已经做好了，只是前端界面没修改，但是后来觉得第二版又想改成微服务，方便以后增加新功能所以就没有继续看vue，也是因为这个原因才开始学习微服务的，上个月的任务主要就这写，总体完成情况不是很好。然后是五月份的计划，算法题12道是肯定要做的，然后补一下上个月的博客文章，主要是把上个月做的算法题思路和算法记一下，方便以后查找，那就12篇吧，这个尽量完成，最后就是看完微服务的这个视频，并且确定下来我微服务要选用的技术体系，搭建好微服务的框架方便之后开发。今天没有上午，下午在看泰拉瑞亚的视频，看的上瘾了，开了一把玩到了半夜。', '2022-04-30', '2022-05-04 23:38:24', '2022-05-04 23:38:24', 1);
INSERT INTO `blog_diary` VALUES (1058, 1, '今天做了核酸上午去超市走了一圈，稍微买了点过年的食物，我已经不在乎味道了，现在就看能量够不够，一天大概需要2000大卡，因为没有餐具过年只能吃面，而且没热水，凑合着过吧，反正和平时也没什么区别，今天算是又废了，明天会努力吗？', '2022-01-30', '2022-01-30 22:38:30', '2022-01-30 22:38:30', 1);
INSERT INTO `blog_diary` VALUES (1059, 1, '今天冲浪又发现一个大佬，博客界面弄得真舒服，不知道能不能看看源码学习一下，公司开始了一个新的项目需求，卡了一天，最近有些松懈，得加油了。', '2022-02-15', '2022-02-15 23:45:54', '2022-02-15 23:45:54', 1);
INSERT INTO `blog_diary` VALUES (1060, 1, '今天处理了一个bug，然后就继续微服务的鉴权中心，还是有很多问题，oauth2的配置好多都不明白是什么意思，还得慢慢学习啊，最近收到了李超凡买的零食，拆盲盒还是挺好玩的，下午一直以为是我的蚊香到了，没想到是零食。', '2022-06-06', '2022-06-06 22:58:56', '2022-06-06 22:58:56', 1);
INSERT INTO `blog_diary` VALUES (1061, 1, '今天还好学习了，虽然上午也打了王者荣耀，下午也玩了，不过把微服务的那个视频中的hystrix看完了，主要学习的服务降级和服务熔断，这个具体内容就不在日记中写了，因为几句也说不清楚，写日记里面也没太大必要，这不上和降低耦合嘛，也跟着视频练习了一下，总体今天还是可以的至少今天不是个废物，然后还补完了前几天的日记（前几天指整个五一假期），因为天天干到半夜就没时间写日记了，虽然上班很累，但是上班的时候我还是很自律的，突然有点期待上班，也正好明天就开工了。哦对了还有前几天小二订婚了和张倩，也不知道我啥时候能有个对象，我其实还是不愿意凑合的，不过我找女朋友要求也不高，但愿能找到吧，也不强求，反正我就这样了，虽然不是完全摆烂，但也是那种得过且过的人，整理一下项目睡觉了。', '2022-05-04', '2022-05-04 23:59:26', '2022-05-04 23:59:26', 1);
INSERT INTO `blog_diary` VALUES (1062, 1, '昨天放假，实在是太累了，知道日记没写，但是也懒得写了，黄河鑫业的项目我的开发任务是完成了，ftp连接也没问题，后来的海康门禁的现场有问题，总结，合别人的代码就是最大的坑，以后一定要自己写，别人的最多只能参考，都是什么jb玩意。', '2022-09-30', '2022-10-01 22:54:54', '2022-10-01 22:54:54', 1);
INSERT INTO `blog_diary` VALUES (1063, 1, '普普通通的一天，项目算是写完了，明天去了再修修补补，大概就这样了。晚上请教大佬，没有看vue。', '2022-02-21', '2022-02-21 23:27:10', '2022-02-21 23:27:10', 1);
INSERT INTO `blog_diary` VALUES (1064, 1, '周日精神抖擞一把，把博客都提到github上了，然后博客的几个模块代码都弄好了单模块都测试过，总体还没弄，下午睡了一觉，然后醒了就八点了，更新一下博客文章模块的代码，差不多也不早了，明天主要是去修改现场的那个bug，感觉这个稍微难定位啊，测试服务器上没办法复现现场的环境，我只能猜，而且日志里面看样子也没报错，如果是单纯是数据没存进去也不应该啊，这个功能其它地方都是可以正常使用的，有点麻烦，到时候再说吧，然后有时间把博客内容模块完善了，之后就可以部署，算法也要开始做了，这个月别等月底在完成，然后微服务的视频暂时就不看了吧，找个vue3的视频，或者之前看的那个vue视频就行，反正快点开始吧，今天就到这了最近每天都晚睡，太累了。', '2022-06-12', '2022-06-12 23:11:08', '2022-06-12 23:11:08', 1);
INSERT INTO `blog_diary` VALUES (1065, 1, '今天把admin项目那个开发需求做完了，今天测试是没有bug的，这个开发应该是告一段落了吧，可能后续还有其它admin的修改，希望少来点吧，受不住了，整整一周都没好好摸鱼，没写博客，算法也没做到3题，周六日抽时间做一道动态规划，感觉这个类型的题还是有难度，多练点应该是可以掌握，再就是app，这个周末把小游博客app的界面学习一下，看怎么做app的界面，接口我已经写好了，没准app博客还能早日使用，至少能看看文章，差不多了，睡觉（躺床上玩手机）。', '2022-01-07', '2022-01-07 23:55:02', '2022-01-07 23:55:02', 1);
INSERT INTO `blog_diary` VALUES (1066, 1, '周一有聚餐，喝了点酒，晚上都不知道怎么回来的，太难受了，白天没项目，今天也不想看博客，算法做了一个记忆化搜索，今天的代码算是自己完成的，看来还是有进步的，差不多睡觉了，难受。', '2022-01-24', '2022-01-24 22:21:22', '2022-01-24 22:21:22', 1);
INSERT INTO `blog_diary` VALUES (1067, 1, '控制空调的那个项目第一次提的需求做完了，测试也没问题，下午顺便还改了南通项目的admin模块的一个bug，现场问题是对角色进行权限修改的时候会报错，排查原因是list没有判空，改了之后还没测试，估计要过几天，然后博客今天开始做日志这部分功能，现在就决定做在网关模块里面了，因为所有请求都会经过网关，所以写在这比较合适，而且还加了黑名单ip的功能，晚上计划看vue视频，但是参加了公司项目的培训，不过最近中午也有再看这个视频，预计这个月应该是可以看完的，最后就是公司搬家，改到了周五，都可以吧我现在倒是无所谓，搬家之后就要早起了，每天要少睡20分钟。', '2022-07-20', '2022-07-20 23:19:24', '2022-07-20 23:19:24', 1);
INSERT INTO `blog_diary` VALUES (1068, 1, '明天是小周，但是我不打算上午就到，下午过去稍微改改项目，主要还是博客的进度，这周有希望部署，只能说是有希望了，今天部落冲突十四本了，重新在国际服创的号，进度都快赶上超凡国服的等级了，明天上午起来把博客的git提交下，今天就写这么多，实在是冻手，手套不知道明天啥时候能到。', '2022-12-02', '2022-12-02 23:50:30', '2022-12-02 23:50:30', 1);
INSERT INTO `blog_diary` VALUES (1069, 1, '周六去团建爬山，去的五云山，山不是很高，40分钟没休息就到顶了，这次团建没其他特殊活动，反正我只管爬山，等到中午去干饭，然后在公司躺了一下午，吃完饭没休息就坐公交回来了，走到公司实在是不想动了，晚上回来打游戏，把盐与避难所通关了，二周目稍微打了一点。', '2022-05-21', '2022-05-22 23:03:38', '2022-05-22 23:03:38', 1);
INSERT INTO `blog_diary` VALUES (1070, 1, '周六没写日记，我承认我是故意的，昨天学吹笛子，总觉得我的笛子5的中音不对，怎么吹都感觉有点问题，然后躺床上思考人生，晚上玩哈迪斯晚到了一点，好像是没仔细看。', '2022-10-29', '2022-10-30 22:34:08', '2022-10-30 22:34:08', 1);
INSERT INTO `blog_diary` VALUES (1071, 1, '复工第一天，因为熊勇大哥不在，给我的那个项目又卡住了，先把请求第三方的接口写好了，明天再看看对数据的处理过程，今天博客开始写日记功能，上传这块有点复杂，我又想读取源文件的创建信息，还想批量上传，不知道要怎么搞，马上今年就结束了，不过博客功能完成了，今年已经没有遗憾了，最近晚上在玩星露谷。', '2022-12-28', '2022-12-28 23:31:06', '2022-12-28 23:31:06', 1);
INSERT INTO `blog_diary` VALUES (1072, 1, '今天博客带标签的这个版本也部署上去了，但是不知道为啥总会请求不到接口，在本地调试没问题，服务器上面就访问不到，而且这个bug不是每次都会出现，是有概率出现的，暂时不知道怎么解决，然后就是今天开始学习spring security，并且是爆肝dnf的一天。', '2022-03-12', '2022-03-12 23:31:12', '2022-03-12 23:31:12', 1);
INSERT INTO `blog_diary` VALUES (1073, 1, '昨天周日测试shell脚本结果忘了写日记，昨天测试把nacos的配置以及数据库导入都弄好了，花了一个下午和晚上的时间，然后昨天我竟然又有了想玩马服dnf的想法，太可怕了，还好我忍住了，玩那个太费时间了，有那时间不如开发下vue，现在接口和脚本都差不多了，可以腾出时间来开发vue，明天开始吧。', '2022-07-03', '2022-07-04 22:33:38', '2022-07-04 22:33:38', 1);
INSERT INTO `blog_diary` VALUES (1074, 1, '今天早点写日记，想躺床上了，昨晚买了个路由器，主要是现在这个公用的太不稳定了，经常断网，所以我打算买一个放自己房间里，正好我还拉了一个网线进家，博客今天没怎么开发，除了处理公司项目的问题，剩余时间我改了下博客部署的shell脚本，原来的脚本需要一个文件服务器，但是我现在只剩一个服务器了，不方便搭建，所以就写了一个需要上传安装包，然后一键安装的脚本，等明天早上起来测试吧，现在不想整理安装包，明天虽然是大周周六，但是我得过去完成答辩ppt，然后要给导师和评委看一下，给我提点问题改正，这个是工作职级晋升的ppt，还是要认真对待的，出来打工就是为了工资，这个职级晋升就是为了给涨工资的，我之前竟然还想着不答辩，真是羞愧啊，明天过去一定要认真做，导师提出修改之后也要好好修改，还有把答辩的稿子写一下，我记得去年转正答辩就有稿子，可以参考着来。', '2022-11-11', '2022-11-11 22:54:40', '2022-11-11 22:54:40', 1);
INSERT INTO `blog_diary` VALUES (1075, 1, '今天好累啊，虽说是周三但是大家都在加班，到晚上八点才下班，不过我今天倒不是很忙，就那几个接口的问题，一直磨蹭，反正我喜欢，博客页面都搞差不多了，但是现在这个感觉不太好，怎么说呢，结构什么的都不是我喜欢的那种，现在api都不能统一放在一起了，还有用可视化界面创建的这个项目少很多文件，感觉又想换一个了，明天可以重新创一个项目，前端页面统一复用第一版的博客页面，路由结构用视频中学习的这个，大概就这么定了，明天开始弄新的项目，或者我现在弄好吧。', '2022-04-20', '2022-04-20 22:53:12', '2022-04-20 22:53:12', 1);
INSERT INTO `blog_diary` VALUES (1076, 1, '博客前端搭建了一点，但主要还是在犹豫，今天有了新的项目，就没太多时间看博客，还有最近疫情，搞的整天心慌，还有从上海过来投毒的傻逼妇女俩人，操了，最后就是这段时间多买点干粮，万一杭州封了也有吃的。', '2022-04-07', '2022-04-08 00:02:58', '2022-04-08 00:02:58', 1);
INSERT INTO `blog_diary` VALUES (1077, 1, '周三本来是要开早会的，不过今天没开，上午就简单的把上一个电视墙的项目bug修好，测试了一次，测试是下午刚睡醒测的，然后就坐那太煎熬了，没事干，晚上早点回来打游戏，就不说了，记录游戏进度没意义，睡觉，王者虽然卸了，但是又下载了云顶之奕手游。', '2022-03-16', '2022-03-16 23:47:38', '2022-03-16 23:47:38', 1);
INSERT INTO `blog_diary` VALUES (1078, 1, '清明假期第一天，腰疼就没干啥的事情，躺了一天，晚上和网友联机打群星，今天还买了一个无线手柄，以后躺着打游戏。还有一件事，因为腰疼，我尽量少翘二郎腿，不过是真的难受啊。', '2022-04-03', '2022-04-04 00:21:56', '2022-04-04 00:21:56', 1);
INSERT INTO `blog_diary` VALUES (1079, 1, '今天不是很忙，但是因为是周五没什么干劲啊，况且明天还要上班，下午摸鱼，顺便写好了config的配置校验类，明天主要就测试已有算法的下发，然后摸鱼。', '2022-09-02', '2022-09-02 23:35:52', '2022-09-02 23:35:52', 1);
INSERT INTO `blog_diary` VALUES (1080, 1, '今天累啊，澜沧江的门禁处理完了多通道下发问题现在又来一个设备树不显示完整的问题，不过新的这个问题还没开始看，实在是没时间了，晚上看黄河鑫业的现场问题，差不多总共俩个问题，最开始是下发ai任务无法创建，这个定位到是因为ai获取dp的服务器ip失败，是ai报错的，还一直找我看，怀疑是我这下发失败了，后续的问题是事件中心报警无图，这个和我的关系不大，所以加班到八点半我就溜了，后续也没继续看花茶，不管找不找我反正今天是结束了，还有一个安工院的报警重发，总体大概也是完成了，加了一个定时任务，一小时启动一次，把下发失败的重发一次，重发成功之后删除这条记录，总的逻辑应该是没啥问题，明天优先海康门禁这个设备树的问题吧，后续的修改不需要别人来配合，我这定位到问题修改一版就行，现在这三个任务都比较着急，明天去了尽快吧，这次不能慢慢来了。', '2022-10-25', '2022-10-25 23:14:24', '2022-10-25 23:14:24', 1);
INSERT INTO `blog_diary` VALUES (1081, 1, '今天是黄河鑫业、国网、盈科三个现场项目折磨，晚上回来给茹旭英装电脑，今天备受折磨，心情复杂，晚上回家都没来得及玩游戏，马上又准备接受第二天的折磨了。', '2022-11-16', '2022-11-16 23:27:10', '2022-11-16 23:27:10', 1);
INSERT INTO `blog_diary` VALUES (1082, 1, '因为昨晚没睡好，今天一整天都状态不是很好，今天项目还挺多的，作业管控的那个测试之后又在另一个地方发现了bug，还要修改，希望五一之前能完成（话说为啥我好几次都把五一写成过去，刚刚这个五一也是第一次写错了），五一说的是休息三天，其实就放一天假，剩下的俩天都是调休，还有俩天是周末，打工人真是太惨了，不得不感慨在中国的劳动法是个人都可以上去写几句，反正也用不到，然后就是分布式这个项目今天又看了一些，今天学的是eureka，虽然已经不更新了，但是这个算是我学分布式的第一个服务注册的模块（可以这么叫吧），虽然中间遇到了一些问题，不过最终还是解决了，还有一个修改hosts文件那个，dns解析时用到了，我应该是正常写对了，但是不知道为什么就是不能使用，使用49.232.129.253就可以访问到页面，但是使用49.232.129.253绑定的eureka7001.com就会有问题，不知道是为什么，明天去了公司用公司电脑试试，最后就是今天现在已经11.17了，但是因为在洗衣服，所以稍微迟一点，现在去搭衣服，搭完马上睡觉，以后就不会必须是11点前睡觉了，但是也要在无特殊原因的情况下11点前睡觉。', '2022-04-24', '2022-04-24 23:18:54', '2022-04-24 23:18:54', 1);
INSERT INTO `blog_diary` VALUES (1083, 1, '加了个班，回家就十点了，好累，睡觉了，今天不想写。', '2022-08-11', '2022-08-11 23:35:28', '2022-08-11 23:35:28', 1);
INSERT INTO `blog_diary` VALUES (1084, 1, '还没买到火车票，国庆大概是回不去了，最近ftp的那个项目稍微缓一会，现在海康门禁这个又来折磨我，晚上作业管控还发现一个新的bug，不知道为啥总有些任务会莫名其妙丢失id，我这都更新了那边还在报警，明天去看吧，最后俩天，时间应该是来得及，马上国庆了，国庆还没想好干啥，前俩天休息。', '2022-09-28', '2022-09-28 23:27:56', '2022-09-28 23:27:56', 1);
INSERT INTO `blog_diary` VALUES (1085, 1, '今天做项目的导出excel表格，导出测试成功，应该是没什么问题的，因为我在自己的博客系统中测试过了，项目中有个问题就是数据不好取，可能之后会用再调用设备的接口，然后我在新建一个表保存数据，因为每次导出的时候临时获取速度可能会很慢，然后就是看巡检的流程，任务是修改开关类型的巡检任务不会报警，这个今天看代码实在是没看明白，巡检一共是有九步，明天是小周去了再看看吧，还有今天吃瓜也算是见证历史了，日本前首相安倍晋三被枪击了，一下午都在吃瓜。', '2022-07-08', '2022-07-08 23:32:58', '2022-07-08 23:32:58', 1);
INSERT INTO `blog_diary` VALUES (1086, 1, '果然还是对周末的我不能有太大的期待，今天又是躺平的一天，到晚上才起床，上午打王者荣耀，下午看看视频，反正就是啥也没做，然后就一天过去了，中午还想着起来吃完饭下午学习呢，结果啥也没做成，衣服就等明天晚上洗吧，明天就又要上班了，任务的话不是很多，就剩最后一个接口，但是这个不太好处理，不知道最后要怎么办，如果要修改得改好多接口，但是不修改又不行，明天和项目经理具体说说看最后要怎么处理，反正我都行要修改就再看看brm的结构，肯定是一俩天看不完，可能又是一周，其它的需求都完成了，测试也没啥问题，等明天看看能不能再加一个存储服务器，了解具体的存储，要是没事的话抽时间学习一下运维平台的那个系统，我也想弄一个，看起来好炫酷，最后就是五月份必须要完成的微服务视频学习，今天粗略的计算了一下，按照十四天的学习时间，每天需要一个小时，上班每天都可以学习一个小时但是只有周一到周四，这是有八个小时，剩下的六小时得找时间看完，应该是问题不大吧，应该吧。', '2022-05-15', '2022-05-15 22:53:28', '2022-05-15 22:53:28', 1);
INSERT INTO `blog_diary` VALUES (1087, 1, '返杭，上火车，看电子书。', '2022-10-08', '2022-10-10 23:11:20', '2022-10-10 23:11:20', 1);
INSERT INTO `blog_diary` VALUES (1088, 1, '为啥最近感觉嗓子这里面有个东西，难受啊，该不会我感染了吧，最初是在前几天核酸检测那个医生捅了一下有点疼，之后就是有次吃馒头吃了一大口噎住了，应该没啥事吧。', '2022-02-04', '2022-02-04 22:55:46', '2022-02-04 22:55:46', 1);
INSERT INTO `blog_diary` VALUES (1089, 1, '快乐的周五啊，而且还是大周，要是现在开一瓶快乐水就更好了，不过算了，刚刚刷完牙，而且明天要去宁波方特公园，期待中...  或者wakuwaku？  哈哈哈，太搞笑了。今天晚上快下班的时候项目经理竟然还想让我明天加班，就离谱，上周都已经是小周了，这周再去加班，那下周我能不去，显然不行啊，加班又没工资，我正常上班就行了，平时晚上加班一是为了晚上在公司只少能学点东西，写几个接口也比在家呆着强，再就是能拿个餐补嘿嘿嘿，挣钱嘛，不丢人...差不多就这样了，准备休息，明天早起去宁波，还是第一次，对了还有明天去就不带电脑了，所以明天的日记就只能在手机上写了，等周日回来之后记录下旅游感受。', '2022-06-17', '2022-06-17 23:17:54', '2022-06-17 23:17:54', 1);
INSERT INTO `blog_diary` VALUES (1090, 1, '月底了，看六月定的目标是完成vue界面，和博客的一键部署功能，vue界面没做完，因为每个界面都要写，vue3还有好多不会的用法，所以就没完成，还有个任务是完成博客一键部署功能，这个做好了，博客一键部署没问题，我都用了好几次了，这几天文件服务器到期了，再买个阿里云的服务器，刚刚看没有活动，直接买服务器实在是太贵了，还是再等等，八月计划干啥啊，vue3界面写完吧，其它的没胆量计划了，次次完成不了。六月感觉过的好慢，但是七月好快啊，虽然是月底，但是没啥想写的，今天给博客前端页面上加个后台管理的窗口标签页，一大堆bug还没改。', '2022-07-31', '2022-07-31 22:51:02', '2022-07-31 22:51:02', 1);
INSERT INTO `blog_diary` VALUES (1091, 1, '周一把南通项目那个都做差不多了，明天去了再修修补补，差不多就可以和前端一起测试一下，还有今天可算是想起来了，我刚入职的时候路上有个饭店同时开门，我当时就感觉他开不了多就不过竟然能撑到现在，之后这个饭店估计也开不久，那个位置就不太对劲。就这样吧，不早了。', '2022-05-09', '2022-05-09 23:37:28', '2022-05-09 23:37:28', 1);
INSERT INTO `blog_diary` VALUES (1092, 1, '今晚开了个会，回家都9点40了，开会培训的是我之前那个机器人项目，但是我没听懂各位大佬说的啥，呆着坐了一晚上，白天算法a了一题，博客开发标签分类的时候用了mybatis的一对多关系，因为我数据库表内名字好多重复的，所以就出bug了，一个下午都是在调这个，以后可一定要注意数据库名字的事情，晚上继续缺氧，液冷现在有了，但是没有塑料，我那唯一的滑鳞壁虎快长大啊，现在都卡进度了，就应该先养壁虎，还有回家的火车票今天买下了，27号。', '2022-01-13', '2022-01-14 01:27:22', '2022-01-14 01:27:22', 1);
INSERT INTO `blog_diary` VALUES (1093, 1, '博客实在是不会搞了，前端页面写不出来，先学习一下吧，界面说实话是真烦人啊，但是不好看又用的不舒服，今天还写了21年的绩效总结，等明天粘进来吧，还有完成了一道动态规划题，我没想出来，但是看答案明白了，这个也要写题解，就这吧，胸口这还是稍微有点难受。', '2022-02-10', '2022-02-10 23:19:32', '2022-02-10 23:19:32', 1);
INSERT INTO `blog_diary` VALUES (1094, 1, '不管睡不睡今天是早点躺下了，肚子疼，不吃东西饿，晚上回家吃点东西有点不舒服，躺一会到现在好点了。', '2022-12-13', '2022-12-13 23:13:32', '2022-12-13 23:13:32', 1);
INSERT INTO `blog_diary` VALUES (1095, 1, '周四看了半天作业管控的接口，对接ai模块还是有点问题，下午看ar全景模块那个问题，今天是浙江哪的项目，名字忘了，查日志，又是找dms最后发现问题是设备不支持这个添加标签的功能，问题算是解决了吧，明天专心看作业管控对接ai模块的这个，争取明天先把任务开启下发做完，今天对接的这部分代码是写完了，去注册中心获取ai模块的接口和ip就是不正确，不知道是啥原因，网站上直接调用接口是没问题的，这个明天晚上记录，还有最近继续vue的视频学习，微服务接口开发内容模块差不多可以先停一段时间了，之后做用户管理的模块和算法吧，算法这周12道题还没开始。', '2022-06-23', '2022-06-23 23:07:24', '2022-06-23 23:07:24', 1);
INSERT INTO `blog_diary` VALUES (1096, 1, '今天对接ai子系统，我是只和ai对接，但是因为调用链路那么长，最后就让我和算子那边对接，结果俩次透传数据发到了算子那边，也不知道为什么下午测试数据会变化，测了半个下午，找各种对接的人，最后算是好了吧，之后换了一个算法版本，又出现了问题，到晚上都没弄好，最后出现的问题是算子那因为没有空闲算子，这个应该是我下发成功了，是算子那边的问题，具体怎么解决明天过去看，博客今天没空看，这周应该会很忙，晚上收到的快递竟然是只有个套子，一整天的快乐心情都被毁了，还遇了个傻逼送外卖的，出门直接把外卖丢下跟我抢电梯，服了。', '2022-08-22', '2022-08-22 23:36:24', '2022-08-22 23:36:24', 1);
INSERT INTO `blog_diary` VALUES (1097, 1, '过生日，嘤嘤嘤，爸妈都没给个红包，又是一个孤独的生日，周六是小周，上午睡个懒觉，下午去公司把内蒙古通威的项目代码提交了，这个开发很简单就算把之前写的定时任务合并过来，然后稍微修改适配下，问题不是很大，下周就没任务了，周六晚会回家在打哈迪斯，睡觉也很晚。', '2022-11-05', '2022-11-07 00:48:48', '2022-11-07 00:48:48', 1);
INSERT INTO `blog_diary` VALUES (1098, 1, '不知不觉都十一点半了，今天完成了博客日记上传的功能，但还是不会获取日记文件的创建日期，昨天看了一个代码是js在前端获取的文件创建日期，后端怎么获取还不太清楚，好多都是file获取本地文件的，但是我这个上传不行，公司项目应该是完成了，今天代码打包好了，明天生产环境测试，我觉得应该问题不大，最有可能出问题的是那个报警，其它我都测试过了，一般情况没问题，今晚理了个发，感觉又变呆了，明天有新的项目，不是ai模块的那个，是又来一个新的任务，要对接啥系统忘了，反正是控制空调的一个功能，不想写了，差不多就这样。', '2022-07-14', '2022-07-14 23:37:14', '2022-07-14 23:37:14', 1);
INSERT INTO `blog_diary` VALUES (1099, 1, '今天很闲啊，没啥事情找我，每天都是这样该多好，晚上有时间看我博客了，稍微写了点登陆保存token的逻辑，上周思考人生一个重要的结论忘记写了，那就是我一定要再去一次广州，去看看当年打工的那个店，当时住的楼，但短时间可能没办法去，至少也得好几年之后，三十岁之前吧，大概，找下一份工作就可以看看广州的。', '2022-10-31', '2022-10-31 23:20:28', '2022-10-31 23:20:28', 1);
INSERT INTO `blog_diary` VALUES (1100, 1, '开始看新的项目，是对接海康门禁的任务，但是因为还在调试机器人，没怎么看，晚上呆着准备写博客，但是被岑帆帆叫过去干活，修改了现场的数据库，没其它什么事情。', '2022-08-05', '2022-08-05 23:14:08', '2022-08-05 23:14:08', 1);
INSERT INTO `blog_diary` VALUES (1101, 1, '答辩就那样算是结束了，今天晚上点文明六，没想到现在俩点了。', '2022-11-22', '2022-11-23 01:25:50', '2022-11-23 01:25:50', 1);
INSERT INTO `blog_diary` VALUES (1102, 1, '昨天的那个分块算法题今天做完了，wa第9个还是有原因的，因为我有个地方写错了，不过就算写错了还能过其它8个测点就离谱，然后学习了大佬的解法，主要还是我之前的查询太慢，不过ac就好了，剩下的时间也不知道在干啥，一天就这样过去了。', '2022-03-01', '2022-03-01 23:34:26', '2022-03-01 23:34:26', 1);
INSERT INTO `blog_diary` VALUES (1103, 1, '这周最迟睡觉改成11点半吧，至少今天不瞌睡，然后今天公司项目不是很忙，做了下博客前端界面，稍微写了点，再就是晚上骑杭州单车我还车了，不给我停止计时，真tm倒霉，不知道明天咋办，要走着上班吗。', '2022-04-18', '2022-04-18 23:08:38', '2022-04-18 23:08:38', 1);
INSERT INTO `blog_diary` VALUES (1104, 1, '公司项目今天搭建好了自动化测试代码开发的环境，语言是要用python，这个还好我稍微会点，具体要怎么开发明天过去得仔细看看，博客已经很久没写了，手机单机小游戏下载了个土豆兄弟，玩的还挺有意思的，晚上璐瑶找我借钱，我倒是无所谓就五百，而且她也不可能不还，之前吃饭都要AA，可惜啊，我没那缘分，就是没想到她辞职了，现在准备靠事业编，祝好运吧。', '2023-03-16', '2023-03-16 23:40:20', '2023-03-16 23:40:20', 1);
INSERT INTO `blog_diary` VALUES (1105, 1, '今天继续改bug，晚上搞博客。先说bug，剩下八九个，都是需要和其它模块对接的，设备同步问题，总之都不好改，然后博客还是计划使用nginx代理图片吧，springboot代理太慢了，晚上还加了图片切割依赖包，还没用上。', '2023-05-24', '2023-05-25 00:07:44', '2023-05-25 00:07:44', 1);
INSERT INTO `blog_diary` VALUES (1106, 1, '今天啊，今天我失忆了，在星露谷过了一个月，早点睡吧。', '2023-01-08', '2023-01-08 22:50:30', '2023-01-08 22:50:30', 1);
INSERT INTO `blog_diary` VALUES (1107, 1, '总算是放假了，明天去大明山。', '2023-10-20', '2023-10-20 23:33:24', '2023-10-20 23:33:24', 1);
INSERT INTO `blog_diary` VALUES (1108, 1, '准备睡觉了才想起来没写日记，今天是年前在杭州的最后一个晚上，明天晚上八点半的火车，后天晚上七点到家，今晚没收拾东西，明天早点起来收拾，定的闹钟是早上七点，现在不管睡不睡先躺下了，其实大概率是不睡觉的，太早了。', '2023-01-16', '2023-01-16 23:11:58', '2023-01-16 23:11:58', 1);
INSERT INTO `blog_diary` VALUES (1109, 1, '开始测试的第一天，好多问题需要修改，明天继续，应该剩下的问题不多了吧，应该是这样的。', '2023-05-16', '2023-05-16 23:22:34', '2023-05-16 23:22:34', 1);
INSERT INTO `blog_diary` VALUES (1110, 1, '上周说的整理数据库的任务，我以为至少要给我俩天时间吧，没想到要我一下午完成，好在最后还是完成了，然后还有一个李楠那边要修改的一个接口，具体怎么搞还没看，估计也不好说，晚上加班改下午说的俩个接口，我没测试，但是应该感觉问题不大，明天上午任务大概是测试今天写的升级数据库代码，这个不能算是接口，但是看大佬的代码今天又学到了新的写法，弄个笔记回来在博客中使用下，十号之前要改完全部接口，也就是就差明天一天了，现在个人感觉除了算法管理平台的接口其它不会有太大问题，算法管理平台我能想到的就有没对密码进行解密，剩下的主要就是参数的格式校验，还有一个实时巡检的俩个接口还没写前端数据推送，明天优先这个，先找盛鹏问一下实时巡检的结果是从哪个类上来的，然后我在后面接着写一下数据的推送，总体任务量还是可控的没有太大风险。晚上回来打王者最后一把被对面守约打爆了，我也是守约，总感觉对面开了，没我视野也能打到我，还是好几次，但应该不太可能，可能就是技术强，我单纯的被碾压了。久违的2k日记，最近工作量非常足，晚上回家懒得写，今天是五一之后恢复锻炼的第一天，先睡觉了。', '2023-05-08', '2023-05-08 23:46:00', '2023-05-08 23:46:00', 1);
INSERT INTO `blog_diary` VALUES (1111, 1, '在家坐了一天，明天上班，打地铺的第二天。', '2023-08-06', '2023-08-06 22:56:12', '2023-08-06 22:56:12', 1);
INSERT INTO `blog_diary` VALUES (1112, 1, '今天抽到了公司妇女节的花篮，果然每次倒霉之后必有好事发生，去年做的山东钢铁现场出了问题，是因为当时我修改之后现场没测试，发包之后现场也没替换，一直到上个月才换我修改过的包，所以就出了问题，项目版本回退的时候退到我修改过给到现场的那个版本，自然回退也会出问题，所以今天开了分锅大会，总之锅是我的，基线今天在看用例测试，点了一半，剩下的一半直接过，都没看，晚上做博客，新版博客好久没看了，今天把文章编辑功能完成。', '2023-03-08', '2023-03-09 00:17:02', '2023-03-09 00:17:02', 1);
INSERT INTO `blog_diary` VALUES (1113, 1, '每天都是在怀疑自己的日子的度过，白天上班的状态是这个bug怎么搞，然后好不容易改完几个之后，突然刷新一看，怎么又来这么多bug，之后自闭一小会，然后继续改，真的所有的压力都来自工作，别人在我这么大都结婚了，我大概是注孤身，活的这人生是真的悲惨啊，从明天开始继续看书吧，最近都是一有时间就玩金铲铲，接着之前看的进度继续看百年孤独，但是我估计还是需要从开始看，人名实在是有点多，还有点乱，好在每次都看的可以快一点，前面的剧情我也直到了，一些回忆的坑也可以看懂。之前买的小单筒望远镜回来了，早下班回来玩了一会，看远处比较亮的地方还是很清楚的，要是看的地方没有灯就完全看不清楚了，考虑到价格还算可以吧，最近晚上回家都在玩缺氧，我觉得这个存档有可能会一直玩下去，又想到一件事，听外包的胡俊杰说他们大概十二月底释放，所以意思是这个加班的状态我要坚持到十二月底啊，还是希望赶紧把我开了算了，如果是真被开了又想要年终奖，一年都坚持到这个时候了被裁又觉得舍不得，超凡说他收到了裁员通知，下个月八号就走人了，赔偿2.7w，还是好羡慕。', '2023-11-29', '2023-11-30 00:41:28', '2023-11-30 00:41:28', 1);
INSERT INTO `blog_diary` VALUES (1114, 1, '下午过去完成了sql优化的功能，下周一再点测试用例吧，反正能拖一会是一会，晚上回来我都没开gta，塞尔达终于出了初始空岛了，正式开始了我的塞尔达旅程，这个通关准备再买一个旷野之息，还有明天拍照记录下我的switch。', '2023-07-08', '2023-07-08 23:25:16', '2023-07-08 23:25:16', 1);
INSERT INTO `blog_diary` VALUES (1115, 1, '虽然今天是十月十二但是我今天不过生日，一直都是按照农历来的，点位模型同步和更新的逻辑大概都清楚了，细节方面也大概可以说清楚了，就是做起来有点烦，下午写的很是暴躁，希望明天可以做出初版，睡觉。', '2023-10-12', '2023-10-12 23:38:14', '2023-10-12 23:38:14', 1);
INSERT INTO `blog_diary` VALUES (1116, 1, '忙碌一天又多了几个问题单，修改起来应该是难度不高，明天希望可以全部解决，今晚还加了个班，想着是把excel导入校验做完，但是有了新的问题单，推迟到明天上午，晚上回家搞缺氧，总算是挖空了全图，然后下一步就开始着手优化，现在玩的平均帧也就20多，还好这个游戏不需要太高的刷新率，睡觉了。', '2023-12-12', '2023-12-13 00:16:40', '2023-12-13 00:16:40', 1);
INSERT INTO `blog_diary` VALUES (1117, 1, '工资没涨，多的2k是项目奖金，今天也不是很忙，但是没怎么开发博客，晚上按照计划就跑了2公里，主要是跑一半肚子有点疼，璐瑶又找我，学籍的问题，但是我也不知道怎么弄。', '2023-08-14', '2023-08-14 23:30:24', '2023-08-14 23:30:24', 1);
INSERT INTO `blog_diary` VALUES (1118, 1, '今天一天都没事干，所以就开始继续整博客，写了一个简单的bat脚本，晚上回家启动的时候发现博客一直连不上rocketmq，结果多次排查问题才发现是c盘空间不够用了，先是把f盘格式化准备合入c盘，但是发现f盘格式化之后的空间和c盘不相连，没办法只好继续格式化d盘，现在正在把d盘数据复制出来，今晚上应该是要开机一晚上了，也不知道明天能不能合在一起，因为中间还有一个占用的系统空间，挂机一晚上明天试试看。', '2023-12-04', '2023-12-05 00:38:08', '2023-12-05 00:38:08', 1);
INSERT INTO `blog_diary` VALUES (1119, 1, '明天就要去千岛湖了，好期待啊。', '2023-09-08', '2023-09-09 00:08:50', '2023-09-09 00:08:50', 1);
INSERT INTO `blog_diary` VALUES (1120, 1, '周日下午俩点半车到的，装好车就五点了，主要是在挑前刹车片，总之最后是调好了，骑车也没问题，今天来回骑了三十公里应该是有的，过去的时候均速有20，之前骑不快果然是因为车的问题，现在一定要搬过去，今天看了俩间房，第一个是中介月租1100，但是要和房东一起住，还要收550的中介费，第二个也是单间独卫，但是这个独卫太小了，不适合去住，而且楼层高，上下楼很慢，房间大小不如第一个，卫生间太小不方便洗澡，住户还很多，价格也高一百，这么对比第一个确实还挺好的，先记一下下周继续过去看。', '2023-02-26', '2023-02-26 23:20:38', '2023-02-26 23:20:38', 1);
INSERT INTO `blog_diary` VALUES (1121, 1, '今天和明天俩天测试，应该测完成一半了吧，还有作业管控的环境没有ivss设备，那些关于算法分析报警的用例就没办法测试，这样明天需要一个ivss的设备测试作业管控，配置ftps和mqtt测试算法，还有几个用例是辅助决策的，这些今天好像测试完了，记不清了，明天过去看看。博客修改了查询文档目录树的接口，展示文档页面新增查看用户文档，现在只是接口添加完成了，还要到前端页面去调试，预计问题不大，现在就是慢慢调试页面吧，这个功能改好之后还没想好接下来干嘛，可能搞博客的全局设置，一些标签的跳转查询，博客的公告设置，轮播图的设置，仔细想想还有挺多任务的，慢慢来吧，反正现在的功能也支持我写文章了，现在计划就是在公司晚上加班的时间搞自己的博客代码，完善功能，周末放假可以写写文章，还有把博客的接口文档完成，技术栈总结完成，印象笔记的迁移，感觉这些任务完成起码得七月份，之后做http转https吧，反正有的是时间，不着急，硬件还是没时间搞，到时候学硬件的时候自己装个电脑，就用些最低端的配置就可以，机箱买个塑料盒装起来，虽然写的有点乱，感觉我这计划安排的满满当当，周末还想打游戏。然后从今天开始继续之前的锻炼，之前是因为胃难受，现在胃溃疡应该是好了，之后又复阳，现在也好了俩周了，恢复的差不多，最近晚上也有食欲，嗓子这不舒服了一年半，最近开始吃除幽门螺旋杆菌的药也感觉有好转的迹象，锻炼暂时就设置20个俯卧撑30个深蹲10个俯卧撑30个深蹲10个俯卧撑，按这个顺序来，睡觉了，还有最近看阿西莫夫的基地三部曲，但是最近又有点想看网络小说，俩本随缘看，网络小说也看不了几天，都是那个套路，一直在重复，寻宝、武斗大会、得第一，然后继续循环，主线可能就是给家族复仇，或者妈被人抓走了，还是一个非常nb的家族，实力强大，等他去救，写着写着我都笑了，这东西我竟然也能看下去，可能是平时生活压力太大，看看网文放松下，睡觉了，快十二点了。d', '2023-06-14', '2023-06-14 23:36:30', '2023-06-14 23:36:30', 1);
INSERT INTO `blog_diary` VALUES (1122, 1, '这篇日记又是第二天补写的，昨天晚上是在火车上度过的，所以很显然，今天又到了杭州，最近感觉上班也就那样吧，没有之前那样的抵触了，写着写着就变成了今天的日记，又删了一段，昨天在火车上看了百度孤独，大概看了15%，剩下的就在平时上班吃饭排队打饭期间看吧，所以也不确定什么时候可以看完，差不多就这样吧，昨晚火车上睡的还挺舒服。', '2023-10-04', '2023-10-05 23:03:04', '2023-10-05 23:03:04', 1);
INSERT INTO `blog_diary` VALUES (1123, 1, '今天装好了树莓派的系统，但是这个不是我要的centos，所以还要等线回来在看问题，今天睡了一下午，晚上不瞌睡。', '2023-06-22', '2023-06-23 02:47:40', '2023-06-23 02:47:40', 1);
INSERT INTO `blog_diary` VALUES (1124, 1, '上午星露谷，下午说的晚dnf，结果就没玩几分钟就懒得玩了，已经找不回当年玩dnf的感觉了，然后就联机玩泰拉瑞亚，晚上稍微玩了下缺氧，现在要睡觉了。', '2023-02-18', '2023-02-18 22:40:46', '2023-02-18 22:40:46', 1);
INSERT INTO `blog_diary` VALUES (1125, 1, '锻炼完成了，今天早点躺床上，虽然也不睡觉，公司新巡检开发算是完成了吧，明天过去继续写接口参数校验类，今天在公司理发了，十块快剪，感觉还是可以的就是只有剪吹，没有洗。', '2023-04-26', '2023-04-26 22:46:38', '2023-04-26 22:46:38', 1);
INSERT INTO `blog_diary` VALUES (1126, 1, '下午睡了三小时，所以晚上不想睡，明天周日但是因为五一调休所以要上班，今晚锻炼做了一半，现在不早了，就算了。se', '2023-04-22', '2023-04-23 00:30:42', '2023-04-23 00:30:42', 1);
INSERT INTO `blog_diary` VALUES (1127, 1, '写了一天接口文档，下午收到了七夕礼物，睡觉了。e', '2023-08-22', '2023-08-23 00:10:18', '2023-08-23 00:10:18', 1);
INSERT INTO `blog_diary` VALUES (1128, 1, '终于周末了，今天给我少了太多工作量的，现在应该可以确保下周完成第一版，明天心情好可以过去弄下萤火虫。', '2023-10-27', '2023-10-28 00:13:06', '2023-10-28 00:13:06', 1);
INSERT INTO `blog_diary` VALUES (1129, 1, '今天瞌睡了，写完日记躺着吧，下午去找王鹏学习单片机，最后是因为环境没弄好了所以就没后续了，然后得知树莓派可以当一个小服务器，所以晚上回来买了一个，买了个内存大的，回来之后先装上win10玩玩，之后换centos7.6的版本以后就是我在家调试代码的小服务器了，先看这个使用怎么样，要是感觉还行，性能差不多以后还可以再买个当服务器，之后在研究怎么可以通过外网访问到，不写了，躺下休息会，最近脖子疼。se', '2023-06-18', '2023-06-19 23:08:40', '2023-06-19 23:08:40', 1);
INSERT INTO `blog_diary` VALUES (1130, 1, 'bug改差不多了，可以准备第二轮测试了，这一轮主要问题还是excel点位的导入，大部分都是这上面的问题，今晚在1199对面的群乐饭店聚餐，晚上绍哲喝吐了，感觉他就没少喝，还好我一口都没喝，开饭前就机智的找了一个没人喝酒的桌子，刚刚把欧卡的1200公里的任务跑完，足足跑了一个小时，还是有点累的，还有游戏之前研究了steam倒余额，我倒了俩个箱子，第一个1.41买入的1.8卖出，这个是平台扣费用之后剩下的，第二个3.09买入3.92卖出。俩个箱子一共花了4.5元，入steam账户5.72，大概就是7.8折，既然学会了这一招，以后没有了土区和阿区就只能在国区倒余额购买了。还有之前卖了很多游戏的卡片，也卖了4块左右，不过这都是之前买的游戏攒了很久的卡片，突然有开箱子的想法了，既然能卖箱子，那肯定也可以开箱子赌运气，找个运气好的一天可以开几个玩玩，反正开出来的东西也能继续卖，大不了就是亏几块钱，我又不会玩太大，稍微多写了一点日记，已经十二点半了，准备睡觉。', '2023-11-22', '2023-11-23 00:19:58', '2023-11-23 00:19:58', 1);
INSERT INTO `blog_diary` VALUES (1131, 1, '装树莓派失败的一天，从今天开始博客要使用rocketmq了。', '2023-06-26', '2023-06-27 00:23:08', '2023-06-27 00:23:08', 1);
INSERT INTO `blog_diary` VALUES (1132, 1, '小周，但是去了公司啥也没干，混了俩个餐补和一份下午茶，晚上到家看直播，赌了一晚上硬币，最后不赢不输。e', '2023-08-26', '2023-08-27 00:28:46', '2023-08-27 00:28:46', 1);
INSERT INTO `blog_diary` VALUES (1133, 1, '昨天忘了写日记，总之昨天就是玩了一天那个国战游戏，最后卸载了。草想起来了，昨天是4-30，我这写的就是昨天的日记，现在凌晨了，我就是说咋感觉时间对不上，那昨天其实是玩了一天星穹铁道，最后因为一个视频以为是兑换码，结果被人骗了给他快手扫了个码，我恼羞成怒就卸了这个游戏，其实游戏还是可以的，但是因为这个游戏剧情不能跳，还有抽卡太黑了，然后玩的也心累就卸了，就这样，睡觉。', '2023-04-30', '2023-05-01 00:23:44', '2023-05-01 00:23:44', 1);
INSERT INTO `blog_diary` VALUES (1134, 1, 'bug也不多了，晚上回家缺氧，做好了厨房相关的建筑，小人直接一步到位吃高级食物。se', '2023-11-30', '2023-12-01 00:24:54', '2023-12-01 00:24:54', 1);
INSERT INTO `blog_diary` VALUES (1135, 1, '这周总算结束了，今天下班下的雨好大，这周主要还是休息吧，一周弄mq也没搞明白。', '2023-06-30', '2023-07-01 00:00:16', '2023-07-01 00:00:16', 1);
INSERT INTO `blog_diary` VALUES (1136, 1, '2023年了，今年是星露谷陪我跨年的，去年的年终总结过几天再写，不差这几天。', '2023-01-01', '2023-01-01 23:30:48', '2023-01-01 23:30:48', 1);
INSERT INTO `blog_diary` VALUES (1137, 1, '写点啥呢，今天做接口清单，还差点东西，明天补充，然后后天开始接口的那个文档总结，晚上博客登陆好像有点问题，第二次就好了，不知道啥原因，睡觉。', '2023-09-04', '2023-09-04 23:54:16', '2023-09-04 23:54:16', 1);
INSERT INTO `blog_diary` VALUES (1138, 1, '今天也没啥事情，计划是早下班去骑车，结果下雨，晚上八点半下班的，明天去体检。', '2023-08-18', '2023-08-18 23:56:12', '2023-08-18 23:56:12', 1);
INSERT INTO `blog_diary` VALUES (1139, 1, '今天有点累，稍微早点躺床上了，自从查出胃病之后没过过舒坦的日子，搞得每天吃饭吃药都得定闹钟，晚上锻炼也经常忘记，或者是懒得锻炼，找借口不做了，从今天开始日记要继续认真写，锻炼也要开始每天坚持，公司巡检的项目开发差不多了，剩下俩个需要新增的接口一个需要修改的接口，大概还有一周，时间还是很充足的，今天甚至有时间搞自己的博客，说到博客，早上部署的博客nacos配置有点问题，晚上又换了新包，明天早上看情况，感觉是没啥问题，现在博客有的功能就是博客文章相关的都有，今天新写的是日记相关的，日记暂时计划只做在管理端写，不做界面上展示，这周应该是可以完成，大概就写这些，有点累，不知道是喝药头晕还是我没睡好，最近中午都不去床上躺着了，怕刚吃完饭就躺下胃里面的胃酸流出来，不知道有没有这个可能，我也没这方面相关知识，突然想起来最近看的书，明朝那些事看到80%了，再有俩周应该是看完了，睡觉。', '2023-04-18', '2023-04-18 22:33:40', '2023-04-18 22:33:40', 1);
INSERT INTO `blog_diary` VALUES (1140, 1, '今天好倒霉啊，公司任务有个难题卡住了，一直解决不了，问题是我的服务启动了有个接口一直报404错误，今天是没想到解决方法，晚上下班去去快递，键盘的按键回来了，但是路上不小心掉地上被一个汽车碾了过去，新回来的俩个按钮都报废了，而且还丢了一只手套，出去找都没找到，烦人，看到之前薛璐瑶给我发了消息我就像傻逼一样去找人家，我tm是真贱啊，短时间不找对象了，再找一个甩我的不是给自己找罪受吗，博客今天总算是好了，但是加载有点慢，下一步前端优先处理加载速度优化，后端最近可以暂缓开发，最近任务重心放在写文章和整理笔记上，这周不打算出去，可以把在公司做的项目整理到博客上去，还有去年年终总结这周必须写完；晚上锻炼现在可以保持每天40个俯卧撑和三十个深蹲，最近做个还是比较标准的，等过段时间现在这个运动量习惯之后可以再加一个仰卧起坐，锻炼腹肌，十一点多了，早点睡觉。还有一件事，今天看完了高木同学，甜甜的真好，只可惜...', '2023-02-06', '2023-02-06 23:04:08', '2023-02-06 23:04:08', 1);
INSERT INTO `blog_diary` VALUES (1141, 1, '今天美食节，因为洗牙的原因啥也不敢吃，晚上去公司理发，本来定的今晚打王者比赛，结果对面投降了，一场没打就24强了。', '2023-08-30', '2023-08-30 23:57:00', '2023-08-30 23:57:00', 1);
INSERT INTO `blog_diary` VALUES (1142, 1, '今天改bug是真的累，有好几个第一轮的bug给我退了回来，但是我看有也没太大问题，不清楚退回来的原因，联系了测试也没给我个答复，还有今天调整的阈值模板的参数校验，我现在是没太大问题，但是产品经理还要继续修改，我是真的服了，没几天了还要大改，现在手里的bug还有俩个辅助决策的改起来可能有点困难，最后三天了吧，希望不会很难，明天可能还要修改阈值模板的功能，甚至大概率要我改数据库，还有今天说的啥平台的一个问题，我也没看，累到不想动，现在不能睡完全是因为还在洗袜子，最近真的是瞌睡。晚上回家奖励自己买了switch，还买了塞尔达王国之泪，虽然有点小贵，但是挣钱也得给自己花，也不能一直攒着当个守财奴，总共下了消费2.5k，也就是一部手机的钱，还是可以消费起的，买这个主要还是因为显卡价格不当人，不降就不降吧，我又不是刚需，买显卡是为了玩游戏，现在就玩switch也行等降价之后再入显卡，一直不降那我就一直不买，等等党还能亏了不成。', '2023-07-04', '2023-07-04 23:47:40', '2023-07-04 23:47:40', 1);
INSERT INTO `blog_diary` VALUES (1143, 1, '博客的mq几乎算是重写了，之前的发送消息和接受消息看着都很难受，所以就都优化了代码，公司的项目最近我的bug并不多，可能是之前着重测试我的功能吧，现在还好，过去就处理下测试找的问题，英雄旧忆俩个角色通关主线了，第二个法师等级还早，而且还没定要玩什么职业，做什么装备，肯定不能玩近战法师吧，晚上在公司十元理了个发，回来比较晚，打会游戏就不早了，又是一点睡。', '2023-12-27', '2023-12-28 00:39:52', '2023-12-28 00:39:52', 1);
INSERT INTO `blog_diary` VALUES (1144, 1, '今天头晕，不想锻炼，睡觉了，明天要评审接口协议。', '2023-04-06', '2023-04-06 22:55:34', '2023-04-06 22:55:34', 1);
INSERT INTO `blog_diary` VALUES (1145, 1, 'switch有点，不小心没忍住，赶紧睡觉了。e', '2023-07-20', '2023-07-21 00:31:10', '2023-07-21 00:31:10', 1);
INSERT INTO `blog_diary` VALUES (1146, 1, '明天要去做胃镜，博客前端ts语法错误改完了。', '2023-03-28', '2023-03-28 23:26:46', '2023-03-28 23:26:46', 1);
INSERT INTO `blog_diary` VALUES (1147, 1, '十月工资才9.4k，真是对不起我天天辛苦加班啊，累死累活就给这点，真打发要饭的呢，晚上和绍哲联机饥荒，之后自己刷无主之地爆了第二把橙装，不知道是不是剧情给的，反正就是出了，感觉挺好用的。', '2023-11-10', '2023-11-11 00:23:48', '2023-11-11 00:23:48', 1);
INSERT INTO `blog_diary` VALUES (1148, 1, '明天要高考了，还记得多年前的这个晚上我紧张到失眠，现在还好，至少不用再像那样餐厅炒菜了，今天晚上没有加班，最近上班不知道为啥好累，还有赶紧之前看的胃病还是没好，胃溃疡可能只是意外发现的，最近消化还是不好，今晚先睡觉了，瞌睡了。se', '2023-06-06', '2023-06-06 22:45:48', '2023-06-06 22:45:48', 1);
INSERT INTO `blog_diary` VALUES (1149, 1, '昨晚在火车上，中午俩点的火车，走的时候忘了带手套。', '2023-01-28', '2023-01-29 22:26:44', '2023-01-29 22:26:44', 1);
INSERT INTO `blog_diary` VALUES (1150, 1, '今天博客重新部署了下，测试部署没问题了，现在整包部署中，结果怎样应该不会有太大问题吧，都是用的验证过的配置，等明天去公司看看，要去公司因为晚上做的核酸检测正常了，等了大概一个小时还是阴性，算上周末总共休息了三天半，复阳这次症状并不是很严重，差不多睡觉吧，下午也没睡好。稍微等了几分钟，博客部署好了，简单测试都没问题。', '2023-05-28', '2023-05-28 23:30:46', '2023-05-28 23:30:46', 1);
INSERT INTO `blog_diary` VALUES (1151, 1, '玩王国之泪的一周，甚至没开gta，好像steam也没上线，想躺下了，能不能早睡再说。', '2023-07-16', '2023-08-10 23:38:02', '2023-08-10 23:38:02', 1);
INSERT INTO `blog_diary` VALUES (1152, 1, '开始投递了简历，这次不着急慢慢来，找到好的工作再离职，晚上打无主之地出了第一个橙装，还是无限子弹的，爽爆了。', '2023-11-06', '2023-11-06 23:59:44', '2023-11-06 23:59:44', 1);
INSERT INTO `blog_diary` VALUES (1153, 1, '今天休息好了，准备部署一个dnf的服务器，但是没有pvf，还在下载，所以就恢复博客数据了，明天写完博客然后保存好数据继续搭建，虽然弄好dnf估计我也不怎么玩。se', '2023-09-16', '2023-09-16 23:42:48', '2023-09-16 23:42:48', 1);
INSERT INTO `blog_diary` VALUES (1154, 1, '可算是看完了，真的上瘾。', '2023-12-20', '2023-12-21 00:36:10', '2023-12-21 00:36:10', 1);
INSERT INTO `blog_diary` VALUES (1155, 1, '今天妈妈带着李玉婷来了杭州，希望最近的一段时间天气好点吧，公司项目一堆bug，改的头疼，最近主要我去做优化，明天要是不下雨就去西湖走走。', '2023-07-28', '2023-07-29 00:36:02', '2023-07-29 00:36:02', 1);
INSERT INTO `blog_diary` VALUES (1156, 1, '普通点位上传差不多是可以了，明天再测试一天应该不会有问题，现在存在一个创建组织和主设备数据没有及时响应，因为调接口创建之后mq再收到处理消息也需要时间，所以我需要记录下这些数据然后获取组织编码，主设备这个不应该吧，我这创建了那边是可以直接入库的，但是这个也有问题明天再处理下，然后导入应该就没太大问题了，我把这个导入流程记录下来，这个和我自己想的导入不太一样，用到了好多线程，我自己的导入就一个线程慢慢来，也不需要啥特殊功能，大佬写的流程有点长，值得学习，这些问题应该是今天下午处理的，但是下午吃了蛋糕然后就开会，所以啥事都没干成，晚上我肯定不会干活，看看docker或者锻炼下，今天锻炼的时候那个玩滑板的小姐姐好漂亮。晚上使用超凡的服务器安装docker部署nginx的文件服务器，处理了一个小时，大概是被俩个问题卡住了，一个是部署好nginx不知道为啥一直404，现在解决之后应该是docker没有添加文件目录映射，学习了docker的-v命令添加映射之后一直是403，按道理来说应该是可以访问到了，但是一直是有问题，最后是因为我关闭了文件目录展示的功能所以403有问题，现在还有个疑问我改基础路径一直没成功，明天再看吧，今天睡觉了。', '2023-09-20', '2023-09-20 23:53:40', '2023-09-20 23:53:40', 1);
INSERT INTO `blog_diary` VALUES (1157, 1, '520结果只能去公司爬山，下午继续博客文档，现在创建文档差不多了，晚上联机泰拉瑞亚，充实的一天，明天博客文档功能完成之后，写一下团建等，最近好多要写的文档。', '2023-05-20', '2023-05-21 00:10:34', '2023-05-21 00:10:34', 1);
INSERT INTO `blog_diary` VALUES (1158, 1, '今天回村，公司发了年终奖，我的绩效考核给了个D，我应该是要另谋出路了，年终奖发了1w。', '2023-01-20', '2023-01-20 23:31:08', '2023-01-20 23:31:08', 1);
INSERT INTO `blog_diary` VALUES (1159, 1, '今天第一次写自动化脚本，用到的语言是python，第一次写，感觉还是挺简单的，明天过去要做定制，最近一直在定制和基线切换，还有半个月要讲，ppt还没开始做，得抓紧了。', '2023-03-20', '2023-03-20 23:22:18', '2023-03-20 23:22:18', 1);
INSERT INTO `blog_diary` VALUES (1160, 1, '因为亚运会闭幕式，所以今天下午四点就让下班了，公司就做模型同步更新的这块设备同步吧，还有完成了明天反串讲的md文档，这块功能流程清楚之后感觉也不是很复杂，应该有一周就可以完成主体功能，细节校验的还要慢慢调试。', '2023-10-08', '2023-10-08 23:50:46', '2023-10-08 23:50:46', 1);
INSERT INTO `blog_diary` VALUES (1161, 1, '今天开始写新巡检的接口，时不时来几个现场问题，好烦啊，今天也没写多少，明天希望能够认真写点，至少这周完成50%的总进度，周末还想着躺平俩天呢，结果这周要去团建，就当是白嫖午餐吧，天上掉下来的免费午餐。', '2023-04-11', '2023-04-11 23:20:50', '2023-04-11 23:20:50', 1);
INSERT INTO `blog_diary` VALUES (1162, 1, '周六加班回家都十一点了，晚上打开steam准备玩玩无主之地，才发现因为之前重装电脑把存档没了，不是说有云存档吗，真是搞心态啊，洗洗睡了。', '2023-12-16', '2023-12-17 00:50:24', '2023-12-17 00:50:24', 1);
INSERT INTO `blog_diary` VALUES (1163, 1, '今天开始博客就做些优化的功能吧，晚上玩泰拉瑞亚，肉后的boss还没开始打，刚做了些装备，今晚还把博客部署了新版本，还是按照昨天的记录，没有新创今天的备份。瞌睡了，先躺下了，明天去看看租房的房间，但是也就是去看看吧，太累了不想搬。看了眼博客，打jar包忘记修改配置到开发环境了，fuck。', '2023-06-02', '2023-06-02 23:48:14', '2023-06-02 23:48:14', 1);
INSERT INTO `blog_diary` VALUES (1164, 1, '终于到家了，火车上就玩玩游戏，明天开始学习，这个假期争取完成docker的安装部署。', '2023-09-28', '2023-09-28 23:58:20', '2023-09-28 23:58:20', 1);
INSERT INTO `blog_diary` VALUES (1165, 1, '今天和茹旭英算是谈了一晚上，我还是要坚持我得原则，一个是守约，一个是诚信。明天准备讲作业管控子系统，原定明天的接口协议、DB讲解推迟到周四。', '2023-04-03', '2023-04-03 23:51:26', '2023-04-03 23:51:26', 1);
INSERT INTO `blog_diary` VALUES (1166, 1, '������װ�����û�뵽��СС��һ��nodejs����ס�ˣ��������������ӹ�������ʵ����̫���ˣ����Ҿ�������ʧ�ܣ���������������Ȼ����ǲ�֪������Ŀ�õ���sass��Ҫʹ���ĸ��汾��nodejs����Ϊ���õ���scss����Щ�汾��nodejs���ز��ˣ��Ժ������������ɾ�˰ɣ����а�git�ύ����ҲŪ���ˣ���֪��֮ǰ����ô�ύ�ģ���������idea����ֱ��ʹ��github����ֱ�ӵ�½��ȡtoken����Ҫ�Լ�ȥgithub��������ø��Ƶ������������Ҳ����С���⣬��������о���������ֵüӰ࣬��tm������kpi��Ҳ���ں���û��û�ˣ��ܲ��ܱ����ҼӰడ�������ʼ�����ˣ�ûɶ�¾��Բ��Ӱ࣬����¹��ʷ�����Ӧ�þ���30w�Ĵ���ˣ���Ȼ��Ҫ���Ϲ������Ҹ�ʱ��ѹ�����Ҳȡ������Ȼ���һ��20w�������궨�ڣ���һֱ�����﷢ù������Ҳ���Կ���֧��������֮��ģ���һ�㱸�õ�Ӧ��Ǯ�����ˡ�', '2023-12-07', '2023-12-07 23:54:36', '2023-12-07 23:54:36', 1);
INSERT INTO `blog_diary` VALUES (1167, 1, '五一第一天，打了一晚上轨子，该睡觉了。那个国战游戏满满的都是氪金选项，已卸。', '2023-04-29', '2023-04-30 00:42:16', '2023-04-30 00:42:16', 1);
INSERT INTO `blog_diary` VALUES (1168, 1, '下午去洗牙，有好多牙结石啊，医生说几乎每颗牙上都有，处理完感觉还挺舒服的，就是可惜明天餐厅有活动，啥东西都不敢吃了，带色素的完全不能吃，晚上回家把树莓派弄好了，可以连wifi了，顺便写好了文档，以后就可以随便部署，我觉得可以再买张卡，部署一个dnf服务器，没事干的时候可以玩玩，睡觉了。', '2023-08-29', '2023-08-29 23:01:06', '2023-08-29 23:01:06', 1);
INSERT INTO `blog_diary` VALUES (1169, 1, '妈的真他妈的累啊，晚上游戏都没精力打，天天上这个b班，啥时候是个头。', '2023-11-25', '2023-11-26 00:18:04', '2023-11-26 00:18:04', 1);
INSERT INTO `blog_diary` VALUES (1170, 1, '小周周六，但是因为之前加过班了，所以今天就没去上班，算是躺了一天，中午吃完饭就开始睡觉，一直睡到了晚上吃饭，下午醒了就吃饭，这样的日子真快乐，要是一直都这样就好了，晚上玩泰拉瑞亚了星露谷，因为睡了一下午，晚上不瞌睡，现在才写日记，差不多也该睡觉了。se', '2023-06-10', '2023-06-11 23:11:02', '2023-06-11 23:11:02', 1);
INSERT INTO `blog_diary` VALUES (1171, 1, '最终没有搬家，上午走了不少路，但是没看房，街上也没广告，所以就不打算搬家了，出去看了看，我觉得这个房间已经很不错了，唯一的缺陷就是在阴面，夏天去楼顶晒晒被子应该也是可以的。', '2023-03-04', '2023-03-04 23:42:22', '2023-03-04 23:42:22', 1);
INSERT INTO `blog_diary` VALUES (1172, 1, '工资到账9800，快乐，今天博客弄的https本地也可以访问了，证书这个只在网关加了https的证书校验，调用内部接口没有验证，前端是关闭了https的证书校验，也不知道是怎么回事，现在已经是https，晚上回来星露谷联机好卡，一直掉线，体验非常差，最近锻炼40个俯卧撑也不是很费劲了，碎片化日记，就这样了，明天小周继续上班。', '2023-02-10', '2023-02-10 22:48:14', '2023-02-10 22:48:14', 1);
INSERT INTO `blog_diary` VALUES (1173, 1, 'md，没忍住，又不早了。睡觉。', '2023-07-27', '2023-07-28 00:13:34', '2023-07-28 00:13:34', 1);
