INSERT INTO `blog_diary` VALUES (1175, 1, '夏促，买了gta5，稍微玩了会，我的电脑竟然不卡，而且画面也不算是开的最低，既然能玩那就有时间就玩玩，下载gta的时候忘记关vpn了，给我把120g流量全走完了，只能等半个月之后恢复了，下午睡了一觉，晚上不是很困，但是也改躺下了。se', '2023-07-01', '2023-07-03 00:15:50', '2023-07-03 00:15:50', 1);
