INSERT INTO `blog_diary` VALUES (1187, 1, '今天把新修改的博客部署上了，刚刚才开始部署，还改了MySQL的密码能不能成功我也不确定，不知道有没有忘了什么配置，总之等明天早上看结果吧，博客现在基础的功能都能使用了，这周把去年的年终总结写完，今天晚上没加班想的是回来部署博客，但是玩了游戏，但是问题不大，今天也有锻炼，早睡早起也继续坚持，所以现在就关机睡觉了。', '2023-02-02', '2023-02-02 22:41:04', '2023-02-02 22:41:04', 1);
