INSERT INTO `blog_diary` VALUES (1194, 1, '又是一年平安夜，这周只能休息一天，明天继续上班，白天爆肝游戏把前几天才买的英雄旧忆通关了，当然通关只是开始，这种刷子游戏还是很耐玩的，今年马上结束了，整整一年都没白金一个游戏。', '2023-12-24', '2023-12-25 00:33:50', '2023-12-25 00:33:50', 1);
