INSERT INTO `blog_diary` VALUES (1196, 1, '发了工资，现在我所有的钱加起来有30w了，当时攒到第一个一万、第一个十万、第一个二十万都很开心，但是现在三十万了感觉也就那样，没有太大的心情变化，这周也不考虑加班实在是心情不好，最近天天都是处理问题，现在问题单还有七个，应该是要在周四全部处理完成，现在才十一点半，躺下了吧，有点累，晚上挂机缺氧，最近没有多余的精力设计模块。', '2023-12-11', '2023-12-11 23:15:38', '2023-12-11 23:15:38', 1);
INSERT INTO `blog_diary` VALUES (1197, 1, '今天把模型同步这块都弄差不多了，之后我应该是可以慢慢来调试了，明天过去就摸摸鱼，摆烂一天是一天，计划周末还是打游戏，心情好可以整理下笔记，还有简历要做好，准备跑路了。', '2023-11-03', '2023-11-03 23:55:12', '2023-11-03 23:55:12', 1);
INSERT INTO `blog_diary` VALUES (1198, 1, '从今天开始要给博客加websocket了，还不是很熟悉，晚上第一次去公司的机房，风好大，吹的好冷啊。', '2023-06-07', '2023-06-07 23:36:10', '2023-06-07 23:36:10', 1);
INSERT INTO `blog_diary` VALUES (1199, 1, '最近整理下博客部署脚本，准备部署新的版本吧，改动还挺多的，加上了socket和mq，返回的token信息也修改了，设置功能加好了，还没和其它地方联动，文件服务功能接口也做好了，没有页面，这么说可以再等等，最近可以测试新版本博客的部署脚本，树莓派都快忘了。', '2023-08-07', '2023-08-07 23:54:14', '2023-08-07 23:54:14', 1);
INSERT INTO `blog_diary` VALUES (1200, 1, '不想睡觉，还想再玩玩王国之泪。', '2023-07-15', '2023-07-16 00:34:20', '2023-07-16 00:34:20', 1);
INSERT INTO `blog_diary` VALUES (1201, 1, '昨天好像还有话要说，但是现在想不起来要写啥了，今天就玩了一上午的缺氧，下午就有点玩不动了，一直都是十几二十多帧，玩的真难受，该整理下地图，处理下杂气了，现在水、点、食物都不缺，可以开始自由发挥了，但是啊，一想到明天还要上班就真的啥心情都没了，想离职。se', '2023-12-03', '2023-12-03 23:25:28', '2023-12-03 23:25:28', 1);
INSERT INTO `blog_diary` VALUES (1202, 1, '今天没有走亲戚，在家呆了一上午，下午鼻子好难受啊，我感觉我这应该就是鼻炎，难受躺床上看动漫的时候菠萝叫出去吃饭，也算一起聚一聚，下次见面应该就是24年了吧，都出去打工漂泊不容易啊，还有今天把博客文章整理了一下，看印象笔记上的文章时发现当时写的差不多算是笔记，和现在博客上的文章稍微不太一样，文章都是那种介绍一个知识点的，但是笔记都很杂乱零散，不知道要不要做个笔记本功能，还是要把文章当笔记本使用，或者整理下当时的笔记做成文章，还没决定好，博客把新文章也放上去了，最近这几个月就仔细雕琢下，改改bug，打磨下功能，还有看看还有什么需要的功能加一下，界面样式以及使用体验还能再缓缓，关于博客的介绍先就这样，然后是今晚去吃饭，菠萝请客，还有刘鑫森，张森没来，明天就要走了，我是大后天去杭州，晚上吃饭聊了很多高中的事情，大家都有好的工作，收入也不错，都交过好几个女朋友，我到现在还没正经处过一个，说真的好羡慕啊，我想找，但是没遇到合适的，或者说我社恐没啥社交所以才会这样吧，真的好羡慕别人能找到女朋友啊，23年也就那样，随缘分了，喜欢薛璐瑶那样子的女生，但是又害怕遇到像他那样甩我好几次的人，有时候也想过，这个真的是我的问题吗，当然我情商低这个是肯定的，就是搞不懂既然知道我是这样的人，为啥还要来回找我那么多次，这个问题我也想过好多次，但是我没想明白，有俩个猜测可能是有那么一点点的喜欢我（就当我是自恋狂吧），想要改变我，让我能够注意到她的一些变化，多哄哄她，多关注下，但是这个我自己都做不到，然后就是为了甩我而找我，希望不是这样吧，我心里觉得他还是挺单纯的，都过去了，我也要试着放下，伤感时间就到此为止了。缺氧这个档打算弄五个火箭，组我的舰队，这句话好像之前也说过，但是这个档是绝对不会弃-3，所以没问题的。', '2023-01-25', '2023-01-25 23:48:14', '2023-01-25 23:48:14', 1);
INSERT INTO `blog_diary` VALUES (1203, 1, '第三次拿药，今天刚排上队就叫我，甚至都没在医院的椅子上坐一会，接口都差不多完成了，现在就是调试bug，还有把数据的范围，格式限制，以及数据来源确定下，这次开发大概是结束了，然后就是一轮一轮的发测，最近没别的事情，赶快五一吧，累了想歇会。', '2023-04-25', '2023-04-25 23:14:20', '2023-04-25 23:14:20', 1);
INSERT INTO `blog_diary` VALUES (1204, 1, '躺了一天，感觉是休息过来了，以至于晚上都不想睡觉。se', '2023-03-25', '2023-03-26 23:15:08', '2023-03-26 23:15:08', 1);
INSERT INTO `blog_diary` VALUES (1205, 1, '今天又来好多问题，好在都可以处理了，现在有几个是设备在离线同步的问题，还有几个的admin接口问题，这个我应该是无能为力，找人协调处理吧，今天早上实在是起不来，早上就调休了，下午状态也不好，很累，晚上稍微早点睡觉吧，还有一件事，昨天晚上想着搞博客，但是页面一直不行，今天我又处理好了，这次应该是node版本太高，我就换了一个低版本的，然后就可以了，晚上修改登陆推出功能，测试了好多次总算是可以了，还加上了文档选中的动画，之后就慢慢优化博客吧，下一步要做登陆注册和设置功能。', '2023-05-23', '2023-05-23 23:07:30', '2023-05-23 23:07:30', 1);
INSERT INTO `blog_diary` VALUES (1206, 1, '今天也是混吃等死的一天，巡检接口文档可算是写完了，博客文章的页面也整理好了，明天开始文档页面整理。e', '2023-08-23', '2023-08-23 23:49:52', '2023-08-23 23:49:52', 1);
INSERT INTO `blog_diary` VALUES (1207, 1, '喉咙异物感，今天上午去医院看完了，耳鼻喉科那边说杓间区略肿，然后要去消化科看看，消化科要确定是不是食道管反流引起的，所以要我预约一下胃镜，所以我约了下周三去做，有点害怕，感觉我平时都很健康，新冠也没啥大影响，，突然要我做一个胃镜，总感觉这个问题好严重啊，然后一上午预约挂号的总费用花了六百，我还认为是个小问题，没想到都华这么多，果然是真的生不起病，最近在公司也是，完全没心情干活，去了就先摸鱼，最近真的是状态不好，总之四月四号快点来吧，赶紧讲完我这也可以松一口气，现在ppt还没写好，明天认真一下，既然工作上没给我太多任务，我得抓紧把ppt弄好，别总是等到周末专门花时间过来，我这还是喜欢拖时间，磨磨蹭蹭的，想改，但是又不知道怎么改，ppt也是，不知道怎么做，总之就算心烦，博客也没写，四月就上线现在这个版本吧，反正文章也可以写，注册账号暂时就手动后台注册吧。现在想调整心情都调不过来，寄希望业务讲完之后吧，现在的心烦压力我觉得都是因为这个原因，最近看手机上的千恋万花，gal确实好玩，比之前玩的那个黄油好多了。', '2023-03-23', '2023-03-23 23:13:28', '2023-03-23 23:13:28', 1);
INSERT INTO `blog_diary` VALUES (1208, 1, '大明山旅游回来了，明天写记录吧，晚上看芙莉莲真感动，我愿称其为2023年十月最强新番。', '2023-10-21', '2023-10-21 23:48:02', '2023-10-21 23:48:02', 1);
INSERT INTO `blog_diary` VALUES (1209, 1, '这周真是开了一周的会，啥事都没时间做，还有要写的自动化脚本，好多都已经写过了，还有好多明明已经完成了，但是不修改状态，真是坑人，熟悉场景了，准备开发，发现已经做完了，明天小周，下午过去继续开会，今天的会开了四小时，到后面我是坐不住了，明天还不知道要开多久，今天陈嘉容找我看电脑问题，虽然我也不会解决。', '2023-03-17', '2023-03-17 23:33:12', '2023-03-17 23:33:12', 1);
INSERT INTO `blog_diary` VALUES (1210, 1, '正常博客项目的一天，不赘述了，晚上实在是无聊下载了王者荣耀和超凡玩了几把，突然聊到dnf就约了明天下午俩点开打dnf，一起组队玩玩，明天看起来还挺充实的，上午晚上约星露谷，下午打dnf，博客表示那我呢？周日一定。没其它事情了睡觉。se。', '2023-02-17', '2023-02-17 23:10:08', '2023-02-17 23:10:08', 1);
INSERT INTO `blog_diary` VALUES (1211, 1, '今天真不是我忘了写日记，是因为刚刚下班，现在打开电脑单纯的只是写篇日记，写完了，睡觉。', '2023-05-17', '2023-05-18 01:50:10', '2023-05-18 01:50:10', 1);
INSERT INTO `blog_diary` VALUES (1212, 1, '今天的面试简直稀碎，果然面试还是得靠背题。', '2023-11-13', '2023-11-13 23:59:34', '2023-11-13 23:59:34', 1);
INSERT INTO `blog_diary` VALUES (1213, 1, '博客页面新版明天可以按时部署，这周就不去骑车了，明天过去把ppt完善下，下周二就要讲了。', '2023-03-31', '2023-03-31 23:21:56', '2023-03-31 23:21:56', 1);
INSERT INTO `blog_diary` VALUES (1214, 1, '公司项目不想写了，没啥进度，就那样，然后还要改数据库，简直了，产品经理真是不考虑工作量，随便就改了，当时也不把需求一次说清楚，到现在一直修改，然后还有俩个辅助决策的问题可能改的会有点难度，真的是不想想这些事啊，晚上回家继续看树莓派的问题，centos装上是没啥问题，但一直就是连不上WiFi，愁死了啊，今天装Debian系统倒是挺顺利，连接wifi也可以，要是实在没办法我就转个系统吧，不知道工作量多大，还有今天推送socket功能完成了，之后就是前端页面上写接收数据处理的流程，太多任务了，给我休息一个月多好。总结下未来计划，首先博客是要弄完成，家里买的这个树莓派跑一个文件服务，可以使用mqtt上传和下载文件，然后就是硬件这块要计划买个太阳能板，在弄一套WiFi控制的功能，可以实时监控家里的情况，要做我的智能家庭管理系统，一步一步来，这个一年之内完成就行。', '2023-07-05', '2023-07-05 23:00:44', '2023-07-05 23:00:44', 1);
INSERT INTO `blog_diary` VALUES (1215, 1, '今天依然没任务，摸鱼快乐，今天继续开发博客，现在博客的文档功能开发完成了，新增文档图片上传功能，之前修改过上传图片的接口参数，所以最开始的上传用户头像这个不能用了，晚上加班弄好了这个功能，现在做日记压缩包上传导入日记功能，以为直接上传日记文件会丢失日记的创建信息，所以弄成了按年导入日记功能，这个功能现在还没好晚上测试的时候保存配置文件的问题，所以今天提交保存一次代码明天去更新nacos配置信息没其它事情我继续开发博客，最近这几天的开发效率确实很高，说做啥功能一会就完成了，还有啥忘了，看视频回忆童年dnf和cf不过我当时只玩dnf，真的不说了说的早睡，今天是坚持锻炼的第三天。', '2023-01-31', '2023-01-31 23:06:48', '2023-01-31 23:06:48', 1);
INSERT INTO `blog_diary` VALUES (1216, 1, '假期结束了，睡觉，明天要去医院拿几盒药。', '2023-04-09', '2023-04-09 23:01:20', '2023-04-09 23:01:20', 1);
INSERT INTO `blog_diary` VALUES (1217, 1, '好久没有今天这样快乐的打游戏了，塞尔达和gta都那么好玩，甚至有点选择困难了，约的下午看硬件，结果到点王鹏没说话，迟了一个小时多，当时我正刺激的跑gta任务呢，所以就没回复，晚上塞尔达开了好几个地图，真快乐啊，星露谷，缺氧啥的没时间玩了，缺氧还特别费时间，这个档估计又弃了。se', '2023-07-09', '2023-07-09 23:54:40', '2023-07-09 23:54:40', 1);
INSERT INTO `blog_diary` VALUES (1218, 1, '今天俩个项目都有阶段性成果，黄河鑫业的几乎完成了，对接赛迪平台的本地测试也没问题了，盈科现场的问题是对方使用了预生产环境的ak、sk所以图片上传失败，晚上早下班，现在坐着有点无聊，把内裤洗了，锻炼下睡觉吧，感觉我的日子好无聊，不过还好每天都有追求，今天买了博客的域名，gszero.asia，明天备案，再试试能不能https，这个一定得弄完，早下班还是有点不习惯，无聊，躺下看看动漫。se', '2023-02-09', '2023-02-09 21:39:42', '2023-02-09 21:39:42', 1);
INSERT INTO `blog_diary` VALUES (1219, 1, '今天买了个无线键盘，东方国信实习那会买的那个实在是太难用了，这个买回来看看手感吧，现在这个机械键盘不适合平时使用，也就打打游戏比较方便。公司早上开早会，最近的项目就一个对接赛迪平台，今天把这周要做的四个接口用到的参数类都写好了，再有俩天大概就可以完成，剩下周四周五开始测试，这周应该是可以完成的，下周俩天计划摸鱼，周二晚上就回家，计划不错，最近博客有点不想做，虽说现在已经部署可以使用了，但还是一直没用，文档这块弄完优先弄登陆页面吧，感觉登陆这块没弄好整个网站用起来都不舒服，注册也考虑弄一下，还有文档这块今天出现一个bug，在考虑界面展示和后台展示要不要使用同一个接口，我觉得可以使用同一个，但是有没想好怎么做，还有文档目录结构表稍微加点字段，现在在后台展示都没什么数据，最近晚上也在看动漫，没心情思考，慢慢来吧。最后就是星露谷了，已经到了第二年春天，这个档下矿，酿酒，养动物都弄上吧，反正都是瞎玩，早日星露谷全成就。', '2023-01-09', '2023-01-09 23:41:00', '2023-01-09 23:41:00', 1);
INSERT INTO `blog_diary` VALUES (1220, 1, '昨天去了千岛湖，所以没有写日记。', '2023-09-09', '2023-09-10 23:17:12', '2023-09-10 23:17:12', 1);
INSERT INTO `blog_diary` VALUES (1221, 1, '从今天开始吃杀菌的药，第一天感觉还行，嗓子这也感觉要好了，继续吃药吧，还有十三天，然后博客还是改成http的吧，https问题太多，websocket都连不上，上网搜索看教程可以使用nginx来配置https，博客开发就先这样，下一步优化一些已有功能，然后添加mq推送数据，mq还没想好要加在哪个模块，可能就和socket放一起了吧，mq应该是每个模块都要用到，到时候具体看，现在还不知道要怎么用，睡觉。', '2023-06-13', '2023-06-13 23:37:18', '2023-06-13 23:37:18', 1);
INSERT INTO `blog_diary` VALUES (1222, 1, '清明去西湖压马路，想着去公司写写接口协议，结果没写成，预约了明天上午的消化科门诊，希望是真的问题不大。e', '2023-04-05', '2023-04-05 23:06:38', '2023-04-05 23:06:38', 1);
INSERT INTO `blog_diary` VALUES (1223, 1, '博客总算是部署成功了，弄了一上午加半个下午，开始是rocketmq启动失败，只后是rocketmq报错，报错弄好了还是不行，配置文件有问题，配置文件弄好了现在打开网站随机概率打不开，不知道啥原因，慢慢看吧，下午出去骑了45公里，休闲骑匀速16公里，晚上把代码提交了，准备明天上班了，下周计划跑步2332，睡觉。', '2023-08-13', '2023-08-13 23:44:24', '2023-08-13 23:44:24', 1);
INSERT INTO `blog_diary` VALUES (1224, 1, '晚上打泰拉瑞亚，白天打无主之地，这一天是真的舒服，明天要玩啥还没想好，要是每天都这样多好，就可以玩一些需要肝的游戏了。', '2023-11-18', '2023-11-19 00:55:54', '2023-11-19 00:55:54', 1);
INSERT INTO `blog_diary` VALUES (1225, 1, '周六也结束了，明天最后一天，周一继续上班，今天开了一个缺氧的新档，估计是玩不下去的，马上要上班了，也没时间玩，明天应该做做博客了。se', '2023-05-27', '2023-05-28 00:20:02', '2023-05-28 00:20:02', 1);
INSERT INTO `blog_diary` VALUES (1226, 1, '国庆当天回村里吃席，结婚应该也可以这么说吧，不知道是不是吃席一定是用于白事，早上六点就要起床，一天也没睡好，中午吃完下午去滹沱河旁边走了走，没想到那边河水还挺宽，一直以为那就是个小溪，晚上吃杂碎但是我不吃这些内脏，明天中午吃完要去王德语那边，这个假期是真的忙。然后说我的博客，nacos一直连不上数据库的问题找到了，应该是配置文件的问题，明天用超凡的服务器测试一下，争取早日完成docker的安装脚本，在家完成不了就得去杭州做了，反正是这个国庆假期一定要完成，nacos之后还要装rockermq，mq应该是不会有太大的问题，新的部署脚本执行时间应该会很快，安装速度主要取决于服务器下载安装包的时间，测试了很多次安装很快，今天就睡了几个小时，现在有点迷糊了，日记内容是不是一直在重复，今天就这样吧，晚上没有回家去，就住在姥爷这边，电脑要没电了，就这样。', '2023-10-01', '2023-10-01 20:51:34', '2023-10-01 20:51:34', 1);
INSERT INTO `blog_diary` VALUES (1227, 1, '锻炼了一半，打王者上头了，先睡觉吧。', '2023-04-19', '2023-04-20 00:58:58', '2023-04-20 00:58:58', 1);
INSERT INTO `blog_diary` VALUES (1228, 1, '总算是最后一天了，最近应该会有很多问题，但是我晚上不想写日记，这周有时间做下总结。', '2023-12-21', '2023-12-22 00:40:16', '2023-12-22 00:40:16', 1);
INSERT INTO `blog_diary` VALUES (1229, 1, '事件中心的报警可算是弄上来了，结果原因还是因为时间格式的问题，最开始是要时间戳我给的是日期，然后改成时间戳又太长了，单位是秒，只好再次修改，博客最近实在是没心情写，新车还没回来啊，等的我好着急，旧车速度最快也就是15，有点怀疑人生了，网上都说普通人也能上20的速度，我感觉我已经很尽力了，还是15，最近多做点深蹲，锻炼下腿，手腕疼，正好少几个俯卧撑。', '2023-02-23', '2023-02-23 23:14:26', '2023-02-23 23:14:26', 1);
INSERT INTO `blog_diary` VALUES (1230, 1, '普通点位导入做好了，还要新增xml格式导入的边缘点位，真的感觉这个好难啊，流程复杂，重要的是不清晰整体流程，一直都是走一步看一步，像1.3版本开发，我就明确知道要做什么，这次虽然也知道最终要做的结果，但是过程就不清楚，现在导入点位制作好了普通点位的导入，还有机器人点位导入和边缘设备点位导入，机器人点位导入已经是做好了，边缘设备点位导入需要先判断这个导入的设备是不是边缘设备，然后再处理后续流程，边缘设备点位导入之后要在单独的边缘设备点位表中放一份，还要在区域的点位表中存放一份，这个是导入，导入暂时缺一点数据，还要支持导入xml个excel格式的数据，所以这个也要新增，导入导入主要是这些内容，明天过去看模型同步，先做点位的模型同步吧，大佬说的不难，但是我还是多申请了几天开发时间，睡觉了，最近这几天都在坚持锻炼，每天晚上走走，做几个俯卧撑，还是周一到周四，之前的跑步还是算了，万一我姿势不对伤膝盖。还没睡，刚刷牙回来，今天收到了公司发的中秋礼盒，六个月饼，一个玩偶吧，没确认不知道是不是，这次感觉最有用的还是这个装东西的收纳盒，甚至在公司论坛上看到了5r收盒子的评论，睡觉了。', '2023-09-21', '2023-09-21 23:38:46', '2023-09-21 23:38:46', 1);
INSERT INTO `blog_diary` VALUES (1231, 1, '又是一点了，还好明天小周周六只去半天就行，今天把第四轮测试发测了，之后可能会稍微轻松点，不知道下一个项目是什么。', '2023-07-21', '2023-07-22 01:08:40', '2023-07-22 01:08:40', 1);
INSERT INTO `blog_diary` VALUES (1232, 1, '今天除夕，但是因为熬夜现在才休息，今天下午和张凯杰辛勍波出去玩，先打台球，之后去的猫咖，一个小时59好贵啊，我是第一次去，那边的猫都是一些比较贵的猫，种类还挺多的，但是我感觉还是村里的狸花猫比较好，猫短，体型也比较小，猫咖有几个长毛的猫，脱了好多毛，还有他俩都有了自己的车，我突然有点羡慕，其实我也不需要，上班也用不着，起个自行车就好，晚上玩缺氧，开了一个绝对不会弃的存档，但是我弃了，现在已经开到了绝对不会弃的存档-3，快三点了，思维混乱，先睡觉了。', '2023-01-21', '2023-01-22 02:36:52', '2023-01-22 02:36:52', 1);
INSERT INTO `blog_diary` VALUES (1233, 1, '周日说好今天要完成docker的脚本，我又没做到，下午看天气挺好的就临时决定了出去骑车，发生了很多事情，都写在了骑行记录里面，日记就不赘述了，晚上回家看了朝花夕誓，治愈或者致郁都有吧，我现在都免疫了，生老病死都是自然规律，谁都会有那一天的，只要不留遗憾就好了吧，甚至有些期待死后会是什么样子呢，就像我来之前什么都没有，什么都不知道，然后就突然有了我，不感慨人生了，明天还上班呢，靓仔。', '2023-10-15', '2023-10-16 00:50:46', '2023-10-16 00:50:46', 1);
INSERT INTO `blog_diary` VALUES (1234, 1, '快乐时光总是短暂的，马上就结束了，弄了俩天树莓派还是部署有问题，暂时不清楚原因。', '2023-09-03', '2023-09-04 00:17:06', '2023-09-04 00:17:06', 1);
INSERT INTO `blog_diary` VALUES (1235, 1, '最近天天睡不着，所以这几天晚上就不加班了，白天忙一天实在是太累，今晚回来继续看那个单片机模块，连接wifi的包已经弄好了，现在编译也正常，但是上传的时候就有问题，现在真的是不知道怎么解决了，之后慢慢百度，主题框架是chatGPT给我写的，这个东西好强啊，啥都知道。公司最近开始了第二轮测试，上周五发测的版本，现在还有好多bug，慢慢修改吧，这个月月底还要完成25条自动化测试用例，这个月还有八天，一天得完成三条自动化用例，自动化用例还不好找，好写的都被别人抢走了，今天找到了十几条，能不能写，有没有人完成还不确定。洗洗睡吧。', '2023-06-19', '2023-06-20 22:56:56', '2023-06-20 22:56:56', 1);
INSERT INTO `blog_diary` VALUES (1236, 1, '瞟了一眼没想到这几天的日记都是第二天零点写的，我真的太强了，公司的bug单不是很多，最近也不忙，晚上整体搬工位，我现在坐到了原来技术支持那边，我的显示屏和外包的那个胡俊杰换了，体验下2k的显示屏，之后我也可以整一个。晚上是因为刷无主之地的双发哈罗德和打哈迪斯所以晚睡了，好在装备也刷到了，开的一局哈迪斯也很爽，可以安心睡觉了。', '2023-11-23', '2023-11-24 00:35:50', '2023-11-24 00:35:50', 1);
INSERT INTO `blog_diary` VALUES (1237, 1, '消消乐真好玩，玩了一晚上，之前树莓派的系统的Ubuntu，这周要换成centos。', '2023-06-25', '2023-06-26 00:07:28', '2023-06-26 00:07:28', 1);
INSERT INTO `blog_diary` VALUES (1238, 1, '继续改bug的一天，明天好像周五了，时间真快，这周都没时间看博客，新版本希望三月底能完成，但是最近实在是没时间，今天没去看租房，明天和周六看吧，还没想好去哪边租，希望是1700左右租个阳面次卧，尽可能近一点。明天继续改bug，今天是一个没提交。新的巡检估算了开发时间，我觉得我估计的25个工作日稍微会有点多，不过保险起见多一点稳，别等最后要我加班赶进度就行，这个周六应该是小周，但是我得看房。', '2023-03-02', '2023-03-02 23:19:36', '2023-03-02 23:19:36', 1);
INSERT INTO `blog_diary` VALUES (1239, 1, '收到了阿里巴巴的面试，压力好大，晚上开会讨论模型同步，点位这块要修改，明天继续干吧，因为晚下班回家还像打游戏放送下，所以就玩到了现在。', '2023-11-07', '2023-11-08 00:29:34', '2023-11-08 00:29:34', 1);
INSERT INTO `blog_diary` VALUES (1240, 1, '今天降温，在家里也好冷啊，就钻被窝了，今天甚至没怎么玩游戏，在杭州的倒数第二天，明天晚上就收拾东西，周二带着行李去公司，下班之后直接滚蛋。', '2023-01-15', '2023-01-15 22:43:52', '2023-01-15 22:43:52', 1);
INSERT INTO `blog_diary` VALUES (1241, 1, '今天修改了无数bug，最难的那个6w点位导出问题也解决了，不过是由州华大佬搞定的，下午又把四十多个自动化的问题单处理了，明天应该就不忙了，先睡个懒觉，下午过去弄博客，反正不会干活的，今天救助了茹旭英300的伙食费，月薪3000好像真的很可怕，还好我现在工资够花。', '2023-12-15', '2023-12-16 00:47:12', '2023-12-16 00:47:12', 1);
INSERT INTO `blog_diary` VALUES (1242, 1, '虽然昨天没写日记，但是今天也不想写，睡觉了。', '2023-09-10', '2023-09-10 23:18:54', '2023-09-10 23:18:54', 1);
INSERT INTO `blog_diary` VALUES (1243, 1, '累啊，昨天喂了猫，今天楼下就贴了不让喂的通告，物业是傻逼吗，不让喂你们抓走啊，老子干啥你们也管得着，晚上下班又碰了一辆车，这次是把人家后视镜壳子撞下来了，那车看着还很高级，还好问题不大，不然我这几个月白干，jb人生。', '2023-10-16', '2023-10-17 00:04:10', '2023-10-17 00:04:10', 1);
INSERT INTO `blog_diary` VALUES (1244, 1, '小周周六，晚上联机玩了会星露谷，现在写日记也不是很迟，今天看第三方登陆，好难啊，Java这知识体系真不是我网上到处抄点就能学会的，今天看三方登陆，一直不明白前后端分离的项目三方登陆要怎么让前端获取信息，我先在的流程是前端点击三方登陆链接跳转到了三方的登陆页面，然后登陆第三方，第三方回调我的接口，我这也可以获取到用户的账号信息，然后把这个用户的账号信息入我自己的数据库，然后用这个账号登陆之后怎么把这个登陆的token传给前端，这个不清楚，然后今天发现一个巨佬的博客，代码还开源，前端也是vite项目，打算学习下大佬的操作，我本来只是想看看大佬怎么做的三方鉴权登陆，但是大佬不是用Java，所以就没办法了，其它语言应该也可以把，反正前后端分离都是json字符串交互的，最近把我页面的展示和设计也改改吧，正好这还有源码，就顺便学习下，这次css也自己写，多熟练下前端代码，今年1还是不想太多了，就好好学习前后端，争取做一个全栈开发，为了前途，也是为了钱途。今晚做俯卧撑还有点体力，稍微加了几个俯卧撑，现在是20、15、10、15、20这几组（15是深蹲），锻炼效果还是很显著的，今晚就这样，睡觉了。', '2023-02-11', '2023-02-11 23:11:08', '2023-02-11 23:11:08', 1);
INSERT INTO `blog_diary` VALUES (1245, 1, '这个季度的自动化用例完成了，明天过去改bug，最近看的mq实在是不懂为啥group名称必须唯一，只能这样写那就先这样用吧，今晚回来很累，没看硬件，也没玩游戏，睡觉了。', '2023-06-29', '2023-06-29 22:43:22', '2023-06-29 22:43:22', 1);
INSERT INTO `blog_diary` VALUES (1246, 1, '最近开始写博客一键部署脚本，晚上又在赌硬币，最后俩吧血亏，200币没了，明天去洗牙。', '2023-08-28', '2023-08-29 00:10:42', '2023-08-29 00:10:42', 1);
INSERT INTO `blog_diary` VALUES (1247, 1, '晚睡了，明天是小周，但我要请假去看房。', '2023-03-03', '2023-03-04 01:37:58', '2023-03-04 01:37:58', 1);
INSERT INTO `blog_diary` VALUES (1248, 1, '今晚上应该是要安装nodejs的，但是我用来装游戏了，毕竟明天要休息，计划赶不上变化，晚上和胡俊杰一起推拿，之后打了会台球。se', '2023-12-08', '2023-12-09 00:12:12', '2023-12-09 00:12:12', 1);
INSERT INTO `blog_diary` VALUES (1249, 1, '今天去做了胃镜，结果是慢性胃炎+十二指肠溃疡，身体还得是好好保养的，这次好了之后希望能长点记性吧。', '2023-03-29', '2023-03-29 23:05:34', '2023-03-29 23:05:34', 1);
INSERT INTO `blog_diary` VALUES (1250, 1, '好久没写长一点的日记了，虽然今天也不早了，但是现在有心情写，可能今天有希望突破2k，最近公司开发1.1.3的巡检服务要开始第五轮转测了，我最近都是做到sql优化，之前写的时候只考虑能用就行，所以现在就很麻烦，最多的一个数据库要测试1300w的数据量，像我之前写的左连接几乎完全不能使用，连接起来的表实在是太大了，所以就把之前写的连接都拆开，然后尽可能在代码逻辑中优化好查询，取数据只要需要的数据，现在我把我能想到的优化全加上了，不知道实际测试会怎么样，有几个接口还是会慢，查询报警的应该会好点，昨天加了字段把左连接去掉了，只是一句查询我觉得MySQL应该没问题吧，明天去公司看吧。博客今天开始做文件上传管理功能，设置功能开发完了，但是还没有加数据，加数据之后还要做和页面相关的联动，这个是长久的计划，而且设置我也是想到啥弄啥，有个轮播图需要图片和跳转路径，现有的设置工具不满足，新的页面配置样式还没想好，这个可以拖一拖，不是很急，博客开发暂时就这样，有时间把树莓派用起来，买了就一直吃灰。晚上回家玩王国之泪，今晚没加班，回家大概是六点半，出了找boss位置，然后打boss大概有将近三小时，没想到好难打啊，几乎是要无伤，挨三下我就挂了，打到最后boss套路都完全熟悉了，真是我的闪避导师，现在打魔王进入林克时间已经非常熟练了，最难的还是第三阶段，第一阶段完全可以无伤，吃个加攻击的buff魔王冲我四次几乎可以完全接上秒了，第二阶段就是一直跑，别让分身蹭到，等那几个帮手（不知道改怎么叫）过来就可以拖分身可以认真输出，尽可能无伤就好，第三阶段最难了，前几次打到第三阶段不知道该怎么打，只能多次送死摸清楚套路，而且第三阶段闪避不能用，我闪之后去突进攻击，然后boss也闪了然后在反打我，开始我以为是在boss反打我的时候我再次闪避，可能是我太菜了一直点不出来，最后只好放弃了，使用弓箭输出，弓箭绑上炸弹花，虽然伤害很低，但是也算是可以打，慢慢消耗，就是一直想贪伤害，经常就是我的炸弹花刚爆炸给boss掩护的他的进攻，导致我来不及闪避，最后一次也算是贪伤害过了，最后的第四阶段boss玩不起吃了秘石变黑龙，开始我以为是更难的一个阶段，但是没想到意外的好大，但也算是谨慎的过了，万一暴毙再从第一阶段开始我真的会心态炸裂，今天算是一周目通关，暂时不考虑开二周目，先把一周目的全收集了，这次打boss的装备是真的惨，弓箭都是临时找商店买来的，现在一周目通关了，只后一定要休闲玩，慢慢做下全收集，留点时间看看硬件，最近打游戏鸽了好多事情，差不多这样，该睡觉了。', '2023-08-02', '2023-08-03 00:34:24', '2023-08-03 00:34:24', 1);
INSERT INTO `blog_diary` VALUES (1251, 1, '周日，总算完成了2022年的年终总结，又借出去2k，这次说的最后一次希望真的是最后一次，继续日记，年终总结现在只完成了总结和计划部分，还有一些数据的记录，过几天整理好数据补上，今天上午和晚上和网友星露谷联机，下午整理博客文章，新建了一个vite项目，用来学习大佬的前端页面样式，有点不想写了，就这样，今晚锻炼又加了10个深蹲，现在是50个俯卧撑40个深蹲，20、20、10、20、20，睡觉了，时间不早了。', '2023-02-12', '2023-02-12 23:17:14', '2023-02-12 23:17:14', 1);
INSERT INTO `blog_diary` VALUES (1252, 1, '发薪日，到手1w，舒服。今天去医院拿了第二次的药，再吃一次然后隔俩周除幽。', '2023-04-10', '2023-04-10 23:35:02', '2023-04-10 23:35:02', 1);
INSERT INTO `blog_diary` VALUES (1253, 1, '圣诞节，e宝也没送啥好游戏，不过我就是要饭的，给点就行，这几天又不玩缺氧了，实在是英雄旧忆太好玩了，第一个游侠满级了，准备刷下一个法师，前期确实太弱了，要伤害没伤害，要坦度没坦度，刷子游戏完成了坐牢，只好改低点游戏难度，这周就不打算调休了，应该也不会很忙，就去公司坐着摸鱼吧，正好有大把时间搞搞博客，现在大部分功能都算完善了，界面改版也做好了，下午开始看mq，到下班时间把mq的框架重新弄了一遍，现在差不多就是我理想的样子了，明天要是不忙争取把mq都做好，还有下午写了一个py脚本把在大华的打卡记录都copy出来了，还有我的工资单，bug修改单，差不多可以充当我博客之后的第一批数据，不然我正愁数据怎么弄，然后是公司的巡检，今天没给我提bug，但是有一个问题需要看，这个算是以前的缺陷吧，点位创建的入口太多，通过模板导入点位没有给我发送文件，导致这块点位没有同步上来，倒也不算是太严重的问题，应该可以托，最后还有中午去楼下填了一个问卷，领到了一个腕力球，小玩一会，感觉还行吧，就是领了之后就后悔应该拿护颈的，毕竟这个腕力球实用性不强，不过要是真领了护颈也会后悔没拿腕力球吧，在此之前都不知道腕力球是什么东西，睡觉了。se', '2023-12-25', '2023-12-26 00:24:32', '2023-12-26 00:24:32', 1);
INSERT INTO `blog_diary` VALUES (1254, 1, '我的反串讲玩了，开发需求也大概确认了，明天开始就是听别人讲和开始开发我的这块功能。', '2023-10-09', '2023-10-09 23:46:46', '2023-10-09 23:46:46', 1);
INSERT INTO `blog_diary` VALUES (1255, 1, '明天清明假期，但是要去准备新巡检的协议，今晚讲作业管控虽然只有俩个观众，但正和我意，不管怎样都是度过了这次讲解。', '2023-04-04', '2023-04-04 23:03:42', '2023-04-04 23:03:42', 1);
INSERT INTO `blog_diary` VALUES (1256, 1, '今天发工资，就正常工资吧，没其它奖金，然后还有键盘回来了，但是少了接收器和充电线，真不知道是怎么搞的，我还以为是我拆的时候给丢了，等过几天补发吧，9-12月水电加起来才291，看来这个电热毯也不是很费电嘛。', '2023-01-10', '2023-01-10 23:30:08', '2023-01-10 23:30:08', 1);
INSERT INTO `blog_diary` VALUES (1257, 1, '最近又是看动漫上瘾啊，俩天追完了影之实力者，明天虽然小周，但是我上周加过了，所以不去。', '2023-11-17', '2023-11-18 00:06:02', '2023-11-18 00:06:02', 1);
INSERT INTO `blog_diary` VALUES (1258, 1, '骑车去绍兴一共一百二十多公里骑了九小时，我也是真强啊虽然有点慢，但是我这是山地和负重，骑车仙人就是我，今天先睡觉了，详细的内容记录在明天日记里，还有年终总结。se', '2023-12-31', '2024-01-01 14:28:36', '2024-01-01 14:28:36', 1);
INSERT INTO `blog_diary` VALUES (1259, 1, '今天就继续任务，感觉是差不多，功能大部分都有了，还剩一个组织这块没弄好吗，所以不能测试，明天继续，晚上回来星露谷，已经到第一年秋天了，看我这个进度应该可以在第一年完成温室。', '2023-01-04', '2023-01-04 23:40:24', '2023-01-04 23:40:24', 1);
INSERT INTO `blog_diary` VALUES (1260, 1, '本来是要写昨天为啥被骗扫二维码和今天西湖出行，但是现在不早了，今天是在玩异星工厂，先睡觉吧。se', '2023-05-01', '2023-05-02 01:01:42', '2023-05-02 01:01:42', 1);
INSERT INTO `blog_diary` VALUES (1261, 1, '上周天天熬夜，这周工作日回家可千万不能打开星露谷了，看了看日记记录的时间1点0点的有三篇，再加上昨天晚上三点才睡的觉，这周一定要准时休息，大概就十一点半吧，今天下午反串讲开始有点紧张，后来还好，主要是我就是提问的，然后大家一起讨论，四月的讲解作业管控可怎么半啊，还是紧张，最近应该开始准备了，还有上周打游戏攒了一堆衣服没洗，今天算是处理完了。', '2023-03-13', '2023-03-13 22:52:36', '2023-03-13 22:52:36', 1);
INSERT INTO `blog_diary` VALUES (1262, 1, '02.05 04:45~05:38记录梦境做梦了，一个故事，我从开始慢慢写吧，虽然是慢慢写当我可能也忘了很多细节，可能字数不是很多。最开始我我哥可能是带着我和几个妹妹去了一个城中村看烟花，说城中村是因为我在梦中好像还打听过这的租房房价，不装修过的房间一个月是660块，之后就去找看烟花的地方，因为我看到带我来的哥哥找了一个二层小楼去楼顶看烟花了，虽说是二层小楼，但这个楼一层也就一个人高，感觉像是一个临时住的小破房间。然后我就想要不我要找一个房子去高处看，然后就看到旁边一个大爷家里，梦中这个楼房应该是三层的，一楼最大，因为没有墙厨房和院子外面直接是相连的，我就从门口走进去问大爷我能不能上楼顶去看看烟花，拍个照给我妈发回去也看看，但是这个大爷说楼上太丑了，很脏就不让我上去，我们说一会之后奶奶也走过来了，看着年纪也挺大了，我就夸奶奶年纪都这么大了还帮忙做家务，给你照顾家庭，真让人羡慕，然后奶奶就帮我说服大爷让我上去了，这个楼算是长条形，楼梯在大门附近，二楼楼梯口记不清了，应该是梦中就没这个印象，然后到了三楼楼梯口正对面窗口我看到了一直黑猫，三楼室内应该是养鸽子之类的地方吧，我也没进去，楼梯到外面这个走廊被封起来了，只有楼梯口正对面一个窗户，侧面一个窗户(说是窗户，但是都没个玻璃，给人的整体感觉就好像是废弃小屋，而且我走上来的路确实又脏又臭，某楼层转角处还有很多动物便便，好像是牛、马一类的吧)，还有楼梯到外面一个斜坡也能看到外面，但是三楼还是太矮了，在俩个窗户旁边怎么拍都不合适，我只好去楼梯口这斜坡看，因为是斜的所以感觉还好，之后从三楼里面走出一个小男孩，和我一起看，我们应该是有过聊天，但是聊天和烟花过程在梦中都没出现过，不是我忘了，可以肯定我问过你们是做什么的，他说是做葡萄酒和草莓酒的，当时还脑补了俩老人光脚踩葡萄的场景；烟花之后下楼那个男孩给我带出一瓶葡萄酒，不知道是没有了还是要我带上，反正就是没喝，然后给我找了一个碗，倒了些热水，这个碗应该是吃完饭还没洗，里面好的菜叶子啊，白色透明的，应该是白菜，所以我喝的时候就吹(男孩还问我咋不喝呢)，把菜吹开喝水，喝了一点点之后放下了，之后男孩也喝了一口，但没像我一样吹。之后我就开始修键盘，新买的这个白色无线键盘，修的过程中这个家里还来了几个人，但是我没注意，旁边有什么人我也没注意，只顾自己修，应该是我在刚才的聊天时候说过把键盘留下来送给这个男孩吧，因为我走的时候可能是割舍不下对新键盘的爱，假装不在意偷偷的装好带走了，之后去火车站的路上男孩追出来送我，还给我我一盒新的烟，半盒他没抽完的还有打火机，这个时候旁边还有一个士兵拿着枪在我旁边站着(只有这一个印象，应该是去北京的火车要检查)，还路过一个内蒙古到北京的火车，我只注意到两节车厢，准确的说是车厢连接处，其他地方都看不到，前一节车厢正常，后一节车厢前面就好像被锤子咋过一样都扁了一块(车厢侧面一个角凹回去了)，然后我感觉非常尴尬，刚刚还想着食言带走键盘，所以就把键盘掏出来给他，我已经想不到我该有多尴尬了，脚趾扣一套三室一厅，告别之后我就准备去火车站了，路上好多送小孩的家长看他们小孩有没有带打火机，检查呢，然后我准备回去把刚给我的打火机还回去，扭头才发现他还在目送我。告别之后我去火车站的路上路过一个拍电影的地方，听到周围有人在说现在的群众演员身体素质也太差了，群众演员都做不好(附近环境应该是我在大路上走着，左转有个巷子，俩边都是农村那种瓦房，墙壁都挺高的，人在巷子里说话我听到了)，我当时就不乐意了，飞檐走壁从屋顶进了这个拍电影的院子，里面最开始是一个小院，然后有什么东西挡住了，对面有人，不过梦也到此为止了，隔壁空调声吵醒了我，后续剧情应该是我从群众演员起步，直接爆红，迎娶白富美，走上人生巅峰了吧，按这个剧情发展指定是这样(确信>_<)。四点四十五开始写的，现在都五点四十了，一个小作文。今天是正月十五元宵节，约王鹏出来一起去杭州亚运会体育场看烟花展，有那么几个好看的，其它都一般般，下午还找了个网友一起玩星露谷，当然我自己的那个存档也是要完成的，只不过是时间问题罢了，缺氧绝对不弃档-3也是绝对不会弃的，晚上去吃了重庆鸡公煲，今天外面人是真的多，地铁也很挤，回来路上还下雨，今天确实不知道改写点啥，就这样吧，回来晚了，到家就十点十分，刷牙睡觉。还有博客上传图片好像还有bug，可能是因为win和linux系统的原因，但是也不应该，Java不都是跑在自己的虚拟机里面吗，一次编译到处运行，有时间再看吧，今天说的写去年年终总结也没写，又是混日子的一天，我活在世上只会把米吃贵。', '2023-02-05', '2023-02-05 22:57:00', '2023-02-05 22:57:00', 1);
INSERT INTO `blog_diary` VALUES (1263, 1, '导入文件再次弄好了，但是效率感人，烦死了，这周没加班，晚上天天回家打游戏，今晚玩了GTA5和泰拉瑞亚，还是静不下心来。', '2023-10-26', '2023-10-27 00:13:32', '2023-10-27 00:13:32', 1);
INSERT INTO `blog_diary` VALUES (1264, 1, '第一天基线干活，一下给了我十几个bug，都是之前鲁南遗留的，看bug确实烦人，还有给我定了4月4日讲作业管控的任务，烦死了啊。', '2023-02-27', '2023-02-27 22:51:16', '2023-02-27 22:51:16', 1);
INSERT INTO `blog_diary` VALUES (1265, 1, '今天睡觉稍微迟了，正常下班回家，回家之后看了看头盔，我觉得还挺合适的，明天上班就带上，晚上锻炼右手手腕有点不舒服，最近俯卧撑尽量用左手，今天的锻炼改成了30个俯卧撑和60个深蹲，今晚下班骑车匀速15了，网上都说正常人能上20，但是我骑十五都好累啊，我不是正常人吗？', '2023-02-22', '2023-02-22 23:39:50', '2023-02-22 23:39:50', 1);
INSERT INTO `blog_diary` VALUES (1266, 1, '周日，稍微玩了会游戏，主要还是休息，把昨天的旅游记录写完了。', '2023-10-22', '2023-10-23 00:18:08', '2023-10-23 00:18:08', 1);
INSERT INTO `blog_diary` VALUES (1267, 1, '假期第三天，玩星露谷，空洞骑士，空洞骑士也就是看看，不打算一直玩下去，星露谷争取这个假期全成就，然后还有今天理发，明天计划回村。', '2023-01-19', '2023-01-19 23:23:52', '2023-01-19 23:23:52', 1);
INSERT INTO `blog_diary` VALUES (1268, 1, '博客开发文章分类和文章标签，感觉最近开发进度还是可以的，公司项目也就那样，摸鱼挣钱。', '2023-03-30', '2023-03-30 23:04:18', '2023-03-30 23:04:18', 1);
INSERT INTO `blog_diary` VALUES (1269, 1, '王国之泪今天地图没开完，不过也就剩右上角一点点地图了，大概1/5，可能不到，就差几个树根，公司项目今天来了俩个bug，我真的是服了，那个机器人为啥还会有问题，之前我测试都是正常啊，还会有问题，明天看吧，我真的是服了，博客今天把设置功能弄好了，上传图片都没问题，支持单图多图，睡觉了。', '2023-07-26', '2023-07-26 23:59:20', '2023-07-26 23:59:20', 1);
INSERT INTO `blog_diary` VALUES (1270, 1, '今天到了杭州，家里也没收拾，明天起来再弄吧，洗洗衣服，骑车就算了，然后博客部署脚本明天也要弄好。', '2023-10-05', '2023-10-05 23:27:44', '2023-10-05 23:27:44', 1);
INSERT INTO `blog_diary` VALUES (1271, 1, '二月了，这个月是十二点吃饭，今天才知道我们部门少的人都被辞了，还好我苟活过了这一波，不过被辞的补贴还挺多的，据说有2n，暂时我还是不考虑被离职吧，被辞了找新的工作也挺煎熬的，现在不管工资多少至少有一份工作，不至于没工作，最近项目也不着急今天改了evo-dssas模块的名字，因为这个改动我没办法部署测试（配置文件都改了很多，需要整包部署测试），所以今天也没什么事情，所以就继续博客开发，今天主要是文件上传这块现在把日记上传弄好了，包括可以读取文件的创建时间，这样就不会丢失数据，下一步开发还没想好，开发可以先缓缓，下一步计划是把在公司做的项目都写成文档，放到我博客文档中，这个也算是一个工作记录吧，突然想到下一步博客开发可以做日记的展示模块，展示需要登陆，然后只能看自己的日记，日记在数据库中都会记录用户的id所以这个是可以实现的，开发量也就是一个前端的界面而已，日记展示怎么设计还没想好，就随便弄一个，反正我的css水平可以忽略，周末有空可以跟着视频练习下css，今天也坚持早睡，坚持锻炼，不知道是不是错觉，晚上做完三十个俯卧撑好像没昨天那么乏力，最近这几个肌肉都有点算，但也要坚持下去，日记到此为止先休息了，博客还可以开发文档、日记、文章的统计功能，还有文章标签和分类还没弄，还有好多事啊，刚刚没想起来，慢慢来，今年还要把app和微信小程序弄好，电脑客户端这个就随缘了，c++的QT框架还没学过。', '2023-02-01', '2023-02-01 22:42:04', '2023-02-01 22:42:04', 1);
INSERT INTO `blog_diary` VALUES (1272, 1, '没事干的日子真快乐，最近就不做新功能了，优化下前端，把代码整理下，没用的东西都删了，日志啥的也清理下。', '2023-08-17', '2023-08-17 23:16:12', '2023-08-17 23:16:12', 1);
INSERT INTO `blog_diary` VALUES (1273, 1, '模型同步和更新初步确定应该是要写三个接口，第一个是本级触发模型同步，这个接口只是下发模型同步的命令，没有其他业务逻辑功能，第二个是下级上报模型同步之后robotgw调用的具体业务逻辑，暂时捋的大概就是先校验、然后入库，这块说的简单，做起来还是很麻烦的，还有一个是本机模型同步的进度接口，就是缓存map里面的，这个简单，处理业务逻辑里面加上就行，最近事情还是有点多，这个季度的自动化用例大概是写不完了，之后补吧，后天回家的车票，明晚就可以收拾东西了，回来的车票是买的10月4号，睡觉了。', '2023-09-25', '2023-09-25 23:38:50', '2023-09-25 23:38:50', 1);
INSERT INTO `blog_diary` VALUES (1274, 1, '明天休息，稍微晚了点，可能不是稍微。', '2023-04-21', '2023-04-22 00:36:00', '2023-04-22 00:36:00', 1);
INSERT INTO `blog_diary` VALUES (1275, 1, '虽然是大周，但是明天要过去加班，烦人。e', '2023-05-12', '2023-05-13 00:33:14', '2023-05-13 00:33:14', 1);
INSERT INTO `blog_diary` VALUES (1276, 1, 'bug剩7个了，而且这一轮测试结束了，明天解决完剩下的准备第二轮，那个excel点位导入的问题还是没能解决。', '2023-11-28', '2023-11-28 23:54:38', '2023-11-28 23:54:38', 1);
INSERT INTO `blog_diary` VALUES (1277, 1, '今天又分了点任务，这次是升级数据库的，初步感觉开发难度不大，但是要写在哪个位置之类的需要思考下，突然想起来结果映射的修改接口有点问题，修改不能重名，但是我没有过滤id，这个问题今天下午修改阈值模板出现过，所以突然想起来了，问题不是很大，周一过去修改就行，最近给我的那些接口新增参数校验总体还算是顺利，但是还没有测试，想想就麻烦，还有算法管理平台接口上传没测试，推送数据的没测试，还差好多。', '2023-05-06', '2023-05-06 23:46:12', '2023-05-06 23:46:12', 1);
INSERT INTO `blog_diary` VALUES (1278, 1, '点位导入明天应该可以做出初版开始测试。', '2023-09-19', '2023-09-19 23:29:50', '2023-09-19 23:29:50', 1);
INSERT INTO `blog_diary` VALUES (1279, 1, '周六正常休息，下午联机玩泰拉瑞亚，打了史莱姆女皇，下周继续。', '2023-06-03', '2023-06-03 23:51:12', '2023-06-03 23:51:12', 1);
INSERT INTO `blog_diary` VALUES (1280, 1, '团建，没玩任何项目，看那些项目都是家长带小孩玩的，就像农家乐一样，我就算是观光吧，玩了一天就是累，还晕车。', '2023-04-15', '2023-04-15 23:39:44', '2023-04-15 23:39:44', 1);
INSERT INTO `blog_diary` VALUES (1281, 1, '听电子书上瘾，日记不想写了，游戏不想玩了，工作不想上了，睡觉也可以拖一拖了，不写了我还要继续听。', '2023-12-19', '2023-12-20 00:43:12', '2023-12-20 00:43:12', 1);
INSERT INTO `blog_diary` VALUES (1282, 1, '好久没写长一点的日记了，但是今天也不打算多写，现在都十一点半了，最近这周都没早睡，今天还算稍微早点的，主要是星露谷下矿暴毙了，吃药慢了一步，背包丢了一大堆物品，今天公司还是在调试之前开发的定制项目，基线这来了一个测试的任务，我看了一下有六十多个测试用例，都点一下应该没啥问题，反正出了问题也不是我这修改，博客今天总算是知道了怎么用阿里的图标，接下来就认真开发吧，但是这个月可能没太多时间，因为我要在四月四号讲作业管控，多准备下吧，还有周四要讲新巡检的串讲反串讲，主要是说我对这个开发的理解吧，没啥问题应该就快要投入开发了。', '2023-03-07', '2023-03-07 23:42:02', '2023-03-07 23:42:02', 1);
INSERT INTO `blog_diary` VALUES (1283, 1, '阈值模板新的需求做完了，明天可能会稍微轻松点，不过要把阈值模板的邮件发出来，问题不大，睡觉了，晚上玩王国之泪很开心。', '2023-07-11', '2023-07-12 00:10:34', '2023-07-12 00:10:34', 1);
INSERT INTO `blog_diary` VALUES (1284, 1, '妈的是真累啊，今天把模型同步大部分流程弄好了，后续还要修补。', '2023-11-02', '2023-11-03 00:02:06', '2023-11-03 00:02:06', 1);
INSERT INTO `blog_diary` VALUES (1285, 1, '周五，白天不想干活，晚上不想睡觉。', '2023-03-24', '2023-03-25 00:51:26', '2023-03-25 00:51:26', 1);
INSERT INTO `blog_diary` VALUES (1286, 1, '应该是开完会了吧，都三天了，反串讲都差不多了，明天希望能让我安安静静的开发，要做的功能大概也了解的差不多，最后盘点可能会出问题的地方还是业务处理逻辑这块，框架流程应该没太大问题，数据怎么保存，以及测试可能会发现的各种各样的问题，这块时间不好把握，晚上稍微整理了下docker的部署脚本，这个周末是真的一定要完成了，从国庆拖到了现在，而且这周确实没啥时间，一天天的都在开会。', '2023-10-11', '2023-10-12 00:10:14', '2023-10-12 00:10:14', 1);
INSERT INTO `blog_diary` VALUES (1287, 1, '睡了，最近好多自动化测试用例，就跟菜市场挑菜一样，今天把25条挑完了，实现了四条，明天继续，最近第二轮的bug先等等。晚上小玩一会星露谷，姜岛地现在种好了，接下来就会有稳定的收入，等全成就再玩别的游戏。', '2023-06-20', '2023-06-20 23:01:54', '2023-06-20 23:01:54', 1);
INSERT INTO `blog_diary` VALUES (1288, 1, '放假咯，明天开始总结吧，看最近空气不好就不骑车了，周日或者周一要是可以就去绍兴。', '2023-12-29', '2023-12-30 00:09:36', '2023-12-30 00:09:36', 1);
INSERT INTO `blog_diary` VALUES (1289, 1, '今天很快乐，昨天留下的海康门禁项目顺利解决，基线定制的接口也差不多了，明天过去做最后的修改测试，今晚继续坚持锻炼，差不多要睡觉了。', '2023-04-24', '2023-04-24 23:40:34', '2023-04-24 23:40:34', 1);
INSERT INTO `blog_diary` VALUES (1290, 1, '下午整arduino板子，现在是接入wifi模块正常了，wifi的板子指示灯也亮了，上传也没问题，但是就是连接不上WiFi，郁闷，晚上玩小黄油魔镜，被刀了，为啥那么好的一个角色非要给写死，好在还有另外一个结局，一晚上差不多通关了，之后买了dlc看看，睡觉了。', '2023-06-24', '2023-06-24 23:37:00', '2023-06-24 23:37:00', 1);
INSERT INTO `blog_diary` VALUES (1291, 1, '周末正常发挥，下载了好几个游戏，手游，单机都有，总之就是休息好了。se', '2023-04-16', '2023-04-16 23:56:48', '2023-04-16 23:56:48', 1);
INSERT INTO `blog_diary` VALUES (1292, 1, '今天就是普通的一天，看看项目，博客几乎没写，晚上50+40，联机打星露谷，不想写了，睡觉。', '2023-02-16', '2023-02-16 22:51:32', '2023-02-16 22:51:32', 1);
INSERT INTO `blog_diary` VALUES (1293, 1, '公司项目的测试任务昨天就完成了，今天就做了一点点的小修改，剩下的时间弄我的博客开发，现在注册功能弄完成了，也不能说是完全完成，还差个邮件发送，自己下午测试是没有问题的，还有发验证码，明天要是不下雨可以出去骑车，晚上泰拉瑞亚也没怎么好好玩，有点瞌睡，先睡了，今天也没锻炼，失眠俩天了，我猜可能是因为晚上锻炼了，导致太活跃所以睡不着。', '2023-06-16', '2023-06-17 00:05:42', '2023-06-17 00:05:42', 1);
INSERT INTO `blog_diary` VALUES (1294, 1, '今天搬到了大房间，最近喝药有点头晕，不知道是不是吃药副作用。', '2023-04-08', '2023-04-08 22:40:22', '2023-04-08 22:40:22', 1);
INSERT INTO `blog_diary` VALUES (1295, 1, '明天去公司工作状态应该会好很多，今天玩了饥荒、GTA5、异星工厂等好几个游戏，从来没有这么自由舒服过，主要是最近也想打游戏，准备睡觉了。', '2023-10-29', '2023-10-29 23:24:02', '2023-10-29 23:24:02', 1);
INSERT INTO `blog_diary` VALUES (1296, 1, '开始中移接口文档的总结，下周要开始开发1.1.4版本的巡检，具体什么功能还不清楚，但是基线小伙伴们都挺忙的，像我一样参加到了定制项目，我是下周开始投入，今天还买了电动牙刷和骨传导耳机，体验一下。', '2023-09-06', '2023-09-06 23:31:16', '2023-09-06 23:31:16', 1);
INSERT INTO `blog_diary` VALUES (1297, 1, '可能是因为明天又要上班吧，晚上不想睡觉，去旁边几个楼顶吹风，没想到被困在了电梯里面，大概十几分钟，还好是一楼，我也没慌，今天一整天没怎么打游戏，努力一天把博客的本地启动弄好了，晚上又重新换了一次服务器上的博客jar包，感觉每次都换整包实在是太慢了，但是最近腾不出时间修改，就这样吧，再写就不早了，下午本想着安装等待的时间把记录的安装文档放到服务器上，但是发现之前的文章功能有问题，很久没写都不知道这不能用，一直都是写的文档。', '2023-12-10', '2023-12-11 01:05:40', '2023-12-11 01:05:40', 1);
INSERT INTO `blog_diary` VALUES (1298, 1, '今天的收获非常大，把websocket整合进了博客项目中，暂时还没想明白要怎么做推送，应该是把消息体中加个topic吧，然后发给前端来区分是哪块数据要更新，现在的点对点和群发都测试没有问题了，我要做个群组聊天应该也是点对点吧，只不过是点比较多，完全群发收到消息的人是会有点多的，这样顺便也解决了私聊的功能，现在聊天室功能差不多了，之前还想的是做netty的聊天室，但是现在决定还是就使用websocket吧，晚上还把接口权限调用这块做好了，之前弄好一直没测试今晚测试出了问题，顺便改过来了，是因为有个注解我没加上，现在加这个socket我主要的目的是要展示用户的在离线状态，并且实现管理员手动让指定账号下线的功能，下线功能这个我已经改好了token，之前用的是jwt，用户登陆之后一段时间之内肯定是可以登陆的，我这控制不了，所以前些天把token改成了redis缓存的字符串，测试是可以控制用户的在离线的，下一步就是websocket在页面上看到哪个用户在登陆，哪个用户离线了，需要websocket给我发个在离线状态，这样顺便也可以解决聊天功能的用户在离线查看，现在想法是有了，然后就是慢慢来实现吧，预计下一次升级在八月份，今晚就睡了。再写写公司项目吧，今天点完成了1.1.2的第六轮测试用例，最近bug已经很少了，现在还有俩条，应该是都没办法修改了，下午除了和那个测试去机房处理问题还解决了黄河鑫业的定制现场问题，原因是我这一直下发删除任务的数据其实cv那边早就删除了，不懂是为什么会出现这种情况，改个版本删除固定次数吧，删多少次没处理完成我这直接丢弃数据，现在的情况大概就是这样吧，没有其他事情了，这周应该是大周，周末我觉得可以去骑车了，最近好点了，下周开始吃除菌的药。睡觉了。', '2023-06-08', '2023-06-08 23:38:42', '2023-06-08 23:38:42', 1);
INSERT INTO `blog_diary` VALUES (1299, 1, '昨天的bug导师给解决了，导师真是我的神，但还有其它小问题，设备一直没同步上去，应该是配置问题吧，但是我请求返回的数据都是正确的，不知道为啥没入库，每天再说，还有俩天时间，黄河鑫业新增算法的代码改完了，不知道他们测试工作咋样，明天过去配合看看，说好的明天晚上不加班，和网友一起玩星露谷，开局第一周就出上古种子，这个档弃了是真的没天理；博客开发最近在搞第三方登陆，但是第三方登陆要求双飞都是https协议（不确定是不是），要弄https协议我就要申请证书，申请证书又要买域名，一环套一环，也不知道啥时能用上我的https协议博客网站，还有微信登陆，计划三个月以内吧，博客前端加载太慢了，想优化体验，今天也在弄nuxt，但是一个demo都没搭建好，不知道是不是因为我的node版本等级低了。', '2023-02-08', '2023-02-08 23:02:24', '2023-02-08 23:02:24', 1);
INSERT INTO `blog_diary` VALUES (1300, 1, '最近真的是不想写太长的日记，在做的这个项目太折磨人了，明天还要面试，不过我倒是不报太大希望，今晚早睡。', '2023-11-12', '2023-11-12 22:39:38', '2023-11-12 22:39:38', 1);
INSERT INTO `blog_diary` VALUES (1301, 1, '从今天开始继续锻炼吧，身体好才是最重要的，初次恢复体能锻炼，三公里跑了二十分钟，今天在公司也没什么任务，就继续写博客，遇到一个rocketmq的bug，处理了一下午总算是弄好了，下午做文件管理的功能，感觉界面样式做的还算凑合。se-dl', '2023-08-08', '2023-08-08 23:26:36', '2023-08-08 23:26:36', 1);
INSERT INTO `blog_diary` VALUES (1302, 1, '大周，晚上王国之泪到了地下世界，好黑啊，怪物还那么强，还是先跑跑主线任务吧，好像说起来到地面之后一个主线都没做呢。睡了，都一点了。', '2023-07-14', '2023-07-15 00:46:48', '2023-07-15 00:46:48', 1);
INSERT INTO `blog_diary` VALUES (1303, 1, '小周，但是没干活，我觉得进度应该还是可以控制的。se', '2023-11-04', '2023-11-05 19:42:56', '2023-11-05 19:42:56', 1);
INSERT INTO `blog_diary` VALUES (1304, 1, '博客今天出了点问题，但是最终还是弄好了，白天回村以为手机丢了，没想到是落家里了，经常忘带手机，还有晚上用壁纸引擎做了我的第一个壁纸，看前端css好想学啊，我的博客太丑了，一是服务器响应慢，再就是太丑了，还是要个好看的界面，这个2.0版本先把好看的样式都弄进来，等以后3.0再优化。', '2023-01-26', '2023-01-26 23:42:16', '2023-01-26 23:42:16', 1);
INSERT INTO `blog_diary` VALUES (1305, 1, '从今天开始要准备开发1.4版本了，这个季度才完成4条，还需要继续努力，回家的车票已经买到了，正好还能找个借口在国庆前休假一天。', '2023-09-14', '2023-09-14 23:18:26', '2023-09-14 23:18:26', 1);
INSERT INTO `blog_diary` VALUES (1306, 1, '原本以为今天能把博客文档这块写差不多，结果就完成了目录树接口，开始没想好怎么设计，想了半天，最后这个接口满足了我所有地方的需求，感觉还是不错的，锻炼最近就算了吧，经常忘记，记着有时候也懒得做，以后想起来再说吧，还有本来计划今天买一个新的服务器，但是后来想了想我可以等618，到时候应该也会便宜，所以我在等等，最近这个服务器还有一个半月可以坚持到那时候，今天也没玩游戏，差不多是想了一天博客接口，写写想想就那样效率也不高，总之还是做完了，下周按照计划应该是可以完成博客文档这个功能的，然后把游戏的设计文档也放进来，算是一个记录，游戏设计暂时也就缺氧和异星工厂，感觉主要还是缺氧，以后买的游戏，新开的档一定要坚持玩下去，现在没完成的有一个缺氧、泰拉瑞亚和星露谷的存档，想了想有这么多，缺氧应该是没时间玩这个了，一是游戏又出了新版本，二是也没太多时间，不过时间不是问题，可以慢慢玩，不要求几天之内完成，所以现在要继续的存档就星露谷和泰拉瑞亚，下周开始继续我的星露谷酿酒，估计这个存档完成博客的文档功能也有了，到时候把第一次通关异星工厂的和星露谷的一起总结到博客上面，今天就这样，明天继续上班，还有今天家里联系说暑假不来了，李雨婷考试没考好，所以就不来杭州了，正好给我省钱，旅游的钱足够给我换个电脑的，今天就这样，睡觉。', '2023-05-14', '2023-05-15 00:01:14', '2023-05-15 00:01:14', 1);
INSERT INTO `blog_diary` VALUES (1307, 1, '感觉休息好了，明天可以上班，准备把ppt的最后部分修改完成。', '2023-03-26', '2023-03-26 23:15:50', '2023-03-26 23:15:50', 1);
INSERT INTO `blog_diary` VALUES (1308, 1, '今天好多了，感觉周一可以正常上班。', '2023-05-26', '2023-05-27 00:33:02', '2023-05-27 00:33:02', 1);
INSERT INTO `blog_diary` VALUES (1309, 1, '到家了，火车上一路看电子书时间过的确实快，不过回家之后就删了，不看了。', '2023-01-18', '2023-01-18 23:44:56', '2023-01-18 23:44:56', 1);
INSERT INTO `blog_diary` VALUES (1310, 1, 'ue评审会进去听了一下，发现有好几个人都没去，我就出来了，今天加班也没做事。e', '2023-03-18', '2023-03-18 23:46:38', '2023-03-18 23:46:38', 1);
INSERT INTO `blog_diary` VALUES (1311, 1, '小周，上午和晚上继续游戏，现在地表地图都开完了，地下也开1/4了，明天稍微少玩会吧，最近太沉迷了，已经累计六十多小时了。', '2023-07-22', '2023-07-23 00:29:02', '2023-07-23 00:29:02', 1);
INSERT INTO `blog_diary` VALUES (1312, 1, '最近上班感觉就在梦游，明天上午去医院看看，我觉得应该问题不大。', '2023-03-22', '2023-03-22 23:58:26', '2023-03-22 23:58:26', 1);
INSERT INTO `blog_diary` VALUES (1313, 1, '处理了一天的bug单，到晚上还有10个单子，还有几个根本没得改，我这处理不了，也不知道要找谁去处理，晚上准备看看博客web，写写，结果npm下载还报错，烦死了，晚上躺床上一晚上没动过，写完日记也就该睡觉了，上班真累啊。se', '2023-05-22', '2023-05-23 00:16:48', '2023-05-23 00:16:48', 1);
INSERT INTO `blog_diary` VALUES (1314, 1, '看来一天代码算是把模型同步主路线弄明白了，差不多是在iscsgw网关基础上做新功能，之前的版本没有边缘节点，所以平台只作为下级向上级同步数据，但是现在加入了边缘节点这个概念，所以就需要平台即作为下级又作为上级来处理，区域作为下级的时候是向上级同步区域的数据，区域作为上级的时候是将边缘的点位数据同步上来，新增的同步触发分为俩种情况，第一种就是区域主动触发同步边缘的点位信息，另一种是边缘的点位数据修改之后触发同步向上级发送，边缘修改向上级同步这个是已经做好的功能，所以不需要我修改，需要新增的是在robotgw服务中添加处理下级上报数据的流程，发送命令，数据入库等操作，当然数据入库这些要做到eims中，因为之前的同步功能就在eims里面。再记录一件开心的事情，上午干活的时候突然有人联系我收不收手工夫券，就是公司推拿的券20一张，开始我还犹豫，因为人家一次就出15张，我就需要用5张，就想了会，然后找到公司论坛看到一个20收一张、110收五张的人，我就找他联系，正好他回消息挺快的，说要，我就300收了十五张，转手220就出了10张，血赚20，美滋滋。', '2023-09-22', '2023-09-23 00:05:08', '2023-09-23 00:05:08', 1);
INSERT INTO `blog_diary` VALUES (1315, 1, '周六下了一天雨，醒了就玩星露谷，困了睡觉，累了看视频，饿了去吃饭，悠闲的一天。', '2023-01-14', '2023-01-15 00:07:26', '2023-01-15 00:07:26', 1);
INSERT INTO `blog_diary` VALUES (1316, 1, '今天也没什么项目，最近都是在准备新巡检子系统的开发，每天下午参加反串讲会议，昨天算是早岁，今天继续，博客开发遇到瓶颈了，不知道要怎么搞，有个文章就行，其它功能像加，但是开发不出好看的页面，想到的样子还不会搞，真难搞啊。', '2023-03-14', '2023-03-14 23:09:30', '2023-03-14 23:09:30', 1);
INSERT INTO `blog_diary` VALUES (1317, 1, '听了一晚上小说，时间好快啊，很好奇一个人要是可以长生会怎样。', '2023-12-14', '2023-12-15 00:19:58', '2023-12-15 00:19:58', 1);
INSERT INTO `blog_diary` VALUES (1318, 1, '上周看群里说是大周，今天也没通知说是小周，我就没去，在家里上午磨蹭把博客环境弄好了，现在应该不会再出啥bug了，下午躺着是真的瞌睡，游戏都没精神玩，下午是睡好了，但是现在不瞌睡了，但是躺着应该也能睡着，晚上整理博客的自动化部署，今天把最近所有的更新都打包好了，刚刚开始执行，整包部署的压缩包现在都1G了，慢慢开发的功能越来越多，用到的三方组件也越来越多，当时考虑加的rocketmq还以为不会超了内存，但是最后还是内存溢出了，解决方法是我又给博客添加了4g的虚拟内存，不知道使用效果具体咋样，要是效果还行，不影响正常使用完全可以明年买一个1G或者2G内存的服务器，就是网速可能会慢点，还是等明天升级完成看效果吧，修改之后这是第一次部署，应该会有一些意想不到的问题吧，要是一次就好只能说我现在已经是一个熟练的博客部署工了。', '2023-08-12', '2023-08-12 23:36:46', '2023-08-12 23:36:46', 1);
INSERT INTO `blog_diary` VALUES (1319, 1, '今天上午和晚上都在联机消逝的光芒，一个人玩的有点吓人，而且我电脑玩着卡，没啥意思，一起联机就好玩了，今天终于刷到了幸存者12级，拿到了钩爪，走出了贫民窟，来到了旧城区，这几天一直再跑支线，好多都是绍哲带过的，我自己也是拿了后期的武器乱杀，要是一个人打可能得肝好几天，有舍有得吧，可能一个人玩，慢慢肝进度都不知道啥时候能打完这个游戏，我现在也没多少时间，平时周末还想出去骑车，还想学硬件，总之是时间真不够用，好想辞了工作，但是没工作又没钱，工作了又烦没时间，属于自己的时间真的是太少了，真就是把自己卖给了公司，躺下看动漫吧，睡觉了，明天一定要写写部署脚本啊，一定啊，别到时候又不想动。在写几句，就在刚刚把玩了半个月的三国杀卸载了，玩的是真的搞心态，一个大将四上上下下几天都是这个段位，别人英雄那么强，不充钱就真没得玩吗，还有那来牌机制，就tm一坨屎，在玩一下三国杀我就是狗，傻逼三国杀。', '2023-10-14', '2023-10-14 23:43:00', '2023-10-14 23:43:00', 1);
INSERT INTO `blog_diary` VALUES (1320, 1, '今天巡检接口还写挺多的，最近晚上都不愿意锻炼。e', '2023-04-12', '2023-04-13 22:48:36', '2023-04-13 22:48:36', 1);
INSERT INTO `blog_diary` VALUES (1321, 1, '上班好累啊，还好我没还房贷的压力，哪天实在是顶不住了就滚蛋回家，今天一天看adms（辅助决策）的问题，结果也没啥进展，晚上还有点头晕，睡觉吧，从明天开始吃杀菌的药。', '2023-06-12', '2023-06-12 23:27:00', '2023-06-12 23:27:00', 1);
INSERT INTO `blog_diary` VALUES (1322, 1, '今天参加了表妹的婚礼，晚上去王德宇的婚礼，一个是嫁入豪门，一个是迎娶豪门千金，都活成我人生羡慕不来的样子，我也不知道我想要的是什么，现在只是简单的追求技术，想搞好自己的博客，以后要慢慢的接入自己的平台，做全屋智能，但是现在的我距离目标还是太遥远了，博客现在大概是完成了，最近在更新部署脚本，脚本完成之后可能慢慢完善博客功能，再学点c++的框架做客户端，晚上喝了点酒，又在感慨人生了，不羡慕别人，现在就追求自己想做的事，毕竟短短几十年，别给自己太大压力，追求我的理想，别留下遗憾，当然要是能遇到一个像我一样想法的人那就更完美了，今天就睡觉了，明天还得早起。', '2023-10-02', '2023-10-02 22:59:50', '2023-10-02 22:59:50', 1);
INSERT INTO `blog_diary` VALUES (1323, 1, '假期第一天，回家上坟，没有看docker，明天开始看。', '2023-09-29', '2023-09-29 23:38:52', '2023-09-29 23:38:52', 1);
INSERT INTO `blog_diary` VALUES (1324, 1, '博客前端整理的差不多了，现在进度应该有50%，这周可以考虑再部署一个版本，赌了一晚上硬币，现在应该输100个了，好难受，赌博确实很不爽，最近晚上不想跑步，每天下去走走。', '2023-08-24', '2023-08-24 23:51:16', '2023-08-24 23:51:16', 1);
INSERT INTO `blog_diary` VALUES (1325, 1, '周末结束了，晚上挂卡卖了近三块，今天也是啥游戏都玩，真的玩不够，不想上班了，先攒钱，攒个60w就差不多了，以后慢慢玩。', '2023-11-19', '2023-11-20 00:31:22', '2023-11-20 00:31:22', 1);
INSERT INTO `blog_diary` VALUES (1326, 1, '今天车还没回来，博客完成了登陆功能，然后就不写继续写了，明天去公司把车装起来，感觉这个周末可能搬不了家，还是看周六去看房顺利不，找到差不多的周日就直接搬走，不行就找俩天，然后工作日找一天去请假搬个家。', '2023-02-24', '2023-02-24 23:17:46', '2023-02-24 23:17:46', 1);
INSERT INTO `blog_diary` VALUES (1327, 1, '加班一天真是来气，可算是把点位导入弄好了，几乎把这个流程都重新搞了一次，最后晚上因为公司的打包服务出了问题没能发测，怪我咯？', '2023-12-02', '2023-12-03 01:10:08', '2023-12-03 01:10:08', 1);
INSERT INTO `blog_diary` VALUES (1328, 1, '今天过生日，但是又改了一天bug，咋就这么多呢，改了一波又一波，明天还得过去加班，大小周完全和别人反过来了。', '2023-11-24', '2023-11-24 23:51:54', '2023-11-24 23:51:54', 1);
INSERT INTO `blog_diary` VALUES (1329, 1, '都2023年了，我还没反应过来，今年28岁了，春节放假公司是十一天假期，我自己又调休一天，这个假期有十二天，太爽了，非常期待，今天就随意抢回家的车票没想到就成功了，十七号晚上的，白天还要上班，晚上八点半的火车，所以我得在十六号晚上收拾好行李，十七号早上坐公交去公司，等下班之后就收拾行李滚蛋。今天在公司继续赛啥平台的对接开发，一直摸鱼，都没做啥，明天要认真干活了，这个任务要在年前完成，还有博客日记展示这块在家里就有问题，在公司看就没问题，不知道是那块出问题了，有可能是sql的原因，但还没确定，晚上回家就像玩星露谷，也没学习，明天任务就是把公司项目进度加快，晚上把博客文档功能这块写写，今天就看动漫了，手机屏幕亮的时间快十一小时了，之前都是七八个小时，今天有点夸张，不过刀剑神域确实好看，看了下手机app使用时长，看动漫的软件加起来六小时，我tql。今天就这样吧，年终总结之后写，好像上面说过，忘了。', '2023-01-03', '2023-01-03 23:44:46', '2023-01-03 23:44:46', 1);
INSERT INTO `blog_diary` VALUES (1330, 1, '晚上好无聊啊，睡觉吧，躺着看动漫。se', '2023-11-16', '2023-11-16 21:43:24', '2023-11-16 21:43:24', 1);
INSERT INTO `blog_diary` VALUES (1331, 1, '今天虽然不是很忙，但还是很累，下午搞了搞博客的文件服务，整理了下接口，现在比较规范了，今晚身体不舒服，就没锻炼，停药晚上有点胃酸。se', '2023-05-11', '2023-05-11 23:28:34', '2023-05-11 23:28:34', 1);
INSERT INTO `blog_diary` VALUES (1332, 1, '晚上没有加班，最近真的干活好累，坚持完这周应该会好些，晚上游戏都没太多精力玩，这周还要准备面试。', '2023-11-08', '2023-11-08 23:06:14', '2023-11-08 23:06:14', 1);
INSERT INTO `blog_diary` VALUES (1333, 1, '阳康之后的第一天上班，处理了好几个bug，昨天说的博客部署脚本没问题，但是今天去测试发现图片没配置好，但是昨天我自己测试图片是没问题的，所以应该昨天的图片是从我本地浏览器中取的，所以没发现，今天就早点睡吧，第一天上班还是有点头晕，站的稍微时间长一点就感觉供血不足，晚上没有加班，会家稍微玩了会缺氧。', '2023-05-29', '2023-05-29 22:19:24', '2023-05-29 22:19:24', 1);
INSERT INTO `blog_diary` VALUES (1334, 1, '今天也是玩了一天的异星工厂，没啥可写的，就写下前台为啥卸那个游戏和被骗之后的反思吧，事情是这样的，当时玩星穹铁道就想着抽几发卡，出个五星角色，但是这个游戏需要很肝，而且氪金抽卡非常贵，看视频说是有兑换码，所以我就开始找视频，看b站上很多视频都是说的一个文档，但是看这个文档是要求下载快手，说的是快手和米哈游的联动活动，开始还犹豫，但是实在是经受不住诱惑，实在是想抽卡，最后就下了个快手极速版，然后给人扫码了，那个码是邀请新人给红包的那种，我实在是傻逼啊，以后绝对不可能再下载这俩逼软件了，最后我恼羞成怒卸了星穹铁道。最后反思下，虽然我一直自信绝对不可能被骗，但看这个还是得多加小心，以后涉及钱的事情绝对不可能轻易决定，不管是诱惑我买什么东西都一样，这次就当是给我长个记性吧。', '2023-05-02', '2023-05-03 00:45:34', '2023-05-03 00:45:34', 1);
INSERT INTO `blog_diary` VALUES (1335, 1, '双休是真爽，躺了一整天，但是我还有一天，已经不敢想上四休三的日子了，今天把博客部署好了，测试正常，明天看看树莓派和上传图片也没有问题。se', '2023-09-02', '2023-09-02 23:45:42', '2023-09-02 23:45:42', 1);
INSERT INTO `blog_diary` VALUES (1336, 1, '今天到杭州了，又要开始上班，今天下午把家里稍微收拾了一下，还有点垃圾没扔，下午计划写去年的年终总结的，但是做了博客的图片上传功能，好在这个功能弄好了，晚上测试图片上传也没问题。还有今天码代码发现新买的这个无线键盘有俩个键的重复的，联系了客服给我再邮一个按键，晚上早点睡，先躺下了。se', '2023-01-29', '2023-01-29 22:30:36', '2023-01-29 22:30:36', 1);
INSERT INTO `blog_diary` VALUES (1337, 1, '今天发的工资里面还有1500的项目奖金，相比去年少了1.5k，今年工资也没涨，发测完成了，明天开始测试第三轮，我没事干可以写写博客了，应该不会太忙了吧。', '2023-07-10', '2023-07-10 23:39:36', '2023-07-10 23:39:36', 1);
INSERT INTO `blog_diary` VALUES (1338, 1, '点位导出excel和xml文件大体上是好了吧，但是导出的时候会报错，偶现问题，下午累了不想看，明天继续，同步是真麻烦，还有大概俩周时间吧，或者就十几天了，今天微博热搜除夕不放假，不过无所谓我会调休。昨晚开的文明六俩天打完了，走的科技胜利。', '2023-10-25', '2023-10-25 23:44:36', '2023-10-25 23:44:36', 1);
INSERT INTO `blog_diary` VALUES (1339, 1, '今天早上部署的博客成功了，但是晚上上传图片的时候文件上传服务那边报错了，简单看了下日志应该是个小问题，明天早上起来处理，上午和群友联机玩群星，中午十二点的时候房东打电话说这个房子她和原房东的合同到期了，原房东要涨价，但是我租房签合同的这个房东没同意所以我们只能搬走滚蛋了，中午一直搬到了下午四点左右才全收拾完，到这边新的房间应该是比那边小一点的，不过也还好，整体感觉是比那边要好一点的，今年夏天还要搬家吗，有点犹豫，在大华我肯定是再干不够一年了，打算是明年年初离职（体力好了先做第二组锻炼），继续写，所以在大华大概也就呆不到一年的时间了，找新房东不一定好说话，也不一定找的房间便宜，马上夏天了，这个房间通风感觉还挺好的，要不就这继续住下去，离职找下一家的时候再说，还在犹豫，新房间这儿今天没有无线，还好我手机流量足够多，上周日开始的锻炼吧，到今天可以一口气二十个俯卧撑，还是有进步的，昨天俯卧撑调整到了三十五个今天感觉可以四十个，差不多也快十一点了，做完最后十个睡觉，最近高木同学要看完了，有点舍不得，现在每集op、ed都在听，确实太好听了，像高木这样的人这个世界上真的存在吗？', '2023-02-04', '2023-02-04 22:47:14', '2023-02-04 22:47:14', 1);
INSERT INTO `blog_diary` VALUES (1340, 1, '躺了一天真快乐，晚上赌硬币，血亏200多个。se', '2023-08-27', '2023-08-28 00:27:30', '2023-08-28 00:27:30', 1);
INSERT INTO `blog_diary` VALUES (1341, 1, '今晚星露谷突然暴毙，一气之下打开了泰拉瑞亚，然后到了现在。', '2023-03-10', '2023-03-11 01:04:48', '2023-03-11 01:04:48', 1);
INSERT INTO `blog_diary` VALUES (1342, 1, '项目要开始发测第五轮，bug算是阶段性改完了，晚上跑主线，明天就准备收拾加侬多夫，小小加侬，可笑可笑，实在是太弱了，至少这一路的小怪是这样，明天可能就主线通关了。', '2023-08-01', '2023-08-02 00:16:50', '2023-08-02 00:16:50', 1);
INSERT INTO `blog_diary` VALUES (1343, 1, '没想到装环境最难的确实安装nodejs，还是因为版本选择不合适，好在最终装好了，现在选择的nodejs版本是16，安装文档和安装包，下午没啥动力，游戏都没玩，干躺了一下午，明天优先装Java环境吧，下午打游戏。', '2023-12-09', '2023-12-09 23:59:12', '2023-12-09 23:59:12', 1);
INSERT INTO `blog_diary` VALUES (1344, 1, '去公司做ppt。', '2023-04-01', '2023-04-01 23:44:38', '2023-04-01 23:44:38', 1);
INSERT INTO `blog_diary` VALUES (1345, 1, '开始准备1.4版本开发了，还没有头猪（绪），晚上本来要写千岛湖记录的，但是晚上装docker的时候把环境拆了，所以就啥也没干，最近几乎恢复晚上锻炼，就快走吧，不跑步了，免得伤膝盖。e', '2023-09-18', '2023-09-18 23:10:16', '2023-09-18 23:10:16', 1);
INSERT INTO `blog_diary` VALUES (1346, 1, '今天黄河鑫业和对接赛迪的项目都没动静，处理了一个现场问题，是之前做过的自定义菜单消失问题，也就新建个分支合并下代码的事情，剩下的时间我就抄大佬的博客页面，今天一下午就弄好了主页菜单导航条，当然还弄了很多配置的问题，导航上的切换主题，切换代码风格都做好了，我觉得还是有很大进步的，这个项目可能要修改我的后端接口，所以计划新建个分支这样旧的版本也可以保留，新的开发也不会影响，不出什么意外的话也就是这个周末的事情，这周尽可能多的完成前端也面，之后有时间就弄这个新的页面吧，虽然我旧的前端也可以使用，但是体验有点不太好，最近五十个俯卧撑和四十个深蹲感觉到极限了，可能要保持这个运动量得一段时间。今天就这样睡觉了。', '2023-02-13', '2023-02-13 22:43:42', '2023-02-13 22:43:42', 1);
INSERT INTO `blog_diary` VALUES (1347, 1, '天天累到半死，真想有点自由时间提升自己。', '2023-10-17', '2023-10-17 23:31:42', '2023-10-17 23:31:42', 1);
INSERT INTO `blog_diary` VALUES (1348, 1, '今晚早点躺下了，有点累也无聊，躺下看看动漫，明天准备博客开发，假期也玩好几天了。', '2023-01-22', '2023-01-22 21:54:54', '2023-01-22 21:54:54', 1);
INSERT INTO `blog_diary` VALUES (1349, 1, '好不甘心啊，神话三这么难打吗，最后一步了暴毙，完全是秒我。', '2023-12-26', '2023-12-27 00:53:50', '2023-12-27 00:53:50', 1);
INSERT INTO `blog_diary` VALUES (1350, 1, '今天去医院去除幽门螺旋杆菌的药，本以为是停药一周就可以去，但是没想到是俩周，现在买下药了等下周四开始吃，然后晚上写博客文档功能，进度还行，这周可以完成，博客前端不知道为啥在公司启动不了，在家里就没问题，非常难受，晚上因为写代码没玩游戏。', '2023-05-18', '2023-05-18 23:31:10', '2023-05-18 23:31:10', 1);
INSERT INTO `blog_diary` VALUES (1351, 1, '一整天没打游戏，把积攒好几周的衣服都洗干净了，把博客的新版本也部署服务器了，明天计划是汽车去绍兴，不着急骑，慢慢走，过去看看鲁迅纪念馆，明晚回来写几篇文章，然后计划后天也就是24年写年终总结，暂时就这样，睡觉。', '2023-12-30', '2023-12-31 00:37:04', '2023-12-31 00:37:04', 1);
INSERT INTO `blog_diary` VALUES (1352, 1, '博客文档图片的切图和上传都做好了，测试也没问题，这周就可以部署完美的博客了，之后优化前端和加上设置功能，再就是可以加下mq，和博客聊天功能。今天就先睡觉了，昨天早睡，今天又忘了。', '2023-05-30', '2023-05-31 00:07:54', '2023-05-31 00:07:54', 1);
INSERT INTO `blog_diary` VALUES (1353, 1, '一不小心玩的不早了，赶紧收拾，明天还要早起回家，模型同步大概好了，晚上去推拿。', '2023-09-26', '2023-09-27 01:05:26', '2023-09-27 01:05:26', 1);
INSERT INTO `blog_diary` VALUES (1354, 1, ' 新买了一个游戏，又玩的不早了，明天还得加班去，感觉连续一个半月小周了。', '2023-12-22', '2023-12-23 02:35:24', '2023-12-23 02:35:24', 1);
INSERT INTO `blog_diary` VALUES (1355, 1, '休假一天，心情不好。', '2023-12-18', '2023-12-18 23:38:28', '2023-12-18 23:38:28', 1);
INSERT INTO `blog_diary` VALUES (1356, 1, '今天就没开发，上午调一会接口，然后一整个下午都在开会，所以今天也没干啥事，明天是五一前最后一天了，估计也干不了多少事情，今天下载了一个手游，正好是我喜欢的那种攻城略地的游戏，玩了一下午，晚上也在玩，建造、收集、攻城都有，虽然是个融合怪，但是我喜欢。se', '2023-04-27', '2023-04-27 23:19:10', '2023-04-27 23:19:10', 1);
INSERT INTO `blog_diary` VALUES (1357, 1, '﻿今天继续写博客，整理文章这块，把接口优化下，页面优化下，今天日记写的早，但并不是我要睡觉了，因为笔记本c盘空间实在是不够了我要重装下系统，日记写好备份一下。系统重新装好了，虽然所有数据都在，但感觉已经不是我熟悉的那个电脑了，我永远的失去了我的朋友。新装好的系统还得慢慢调教。', '2023-12-05', '2023-12-05 23:20:52', '2023-12-05 23:20:52', 1);
INSERT INTO `blog_diary` VALUES (1358, 1, '假期结束了，我就说时间很快嘛，感觉就是昨天才放的假，先看看放假当天的日记，应该是放假前一天，当天我还在火车上，瞅了瞅没写啥内容，那天就公司摸鱼，晚上推拿，划水的一天，也可能是那会实在是太累了，累的时候就没心情写日记，还记得那天都没睡几个小时，晚上失眠，包括假期期间，在家里也睡不着，来了之后就好多了，可能是现在一个人住习惯了，家里有人就有点不适应，今天一整天躺着，顺便把衣服都洗干净了，被罩床单都换成了干净的，准备迎接新的一周，就是这周要上七天，想想就烦啊，最近好像买个帐篷，这样出去骑车的时候就可以考虑去更远一点的地方，晚上就找个空地就地露营，但是最近天气变凉了，还在考虑要不要买，今天把docker的脚本大体上是弄好了，用到的组件安装脚本都写好了，剩下的就是整理下安装流程，可能还差点，jar包的启动还没弄，看样子是完成不了了，希望jar包启动简单些，前端倒是问题不大，只要把东西丢给nginx就行，这个测试过，那就明天抽时间看看吧，估计第一天上班应该有不少人请假不去，用年假多凑几天假期，我是在放假之前申请了，所以再申请明天休息不太合适，工作进度还得赶赶，摩擦摩擦也十一点多了，本来今晚还想着十一点就睡下呢，日记就这样了，这个国庆假期是真的烦人，回去都没休息几天，四处吃席，想起来就有点暴躁，还是不要再日记里写这些了，我要看空中飞人。', '2023-10-06', '2023-10-06 23:23:00', '2023-10-06 23:23:00', 1);
INSERT INTO `blog_diary` VALUES (1359, 1, '代码开发算是结束了，开始联调，还不知道是啥结果，烦人。晚上到家还没无线，游戏也没玩。', '2023-11-01', '2023-11-01 23:38:22', '2023-11-01 23:38:22', 1);
INSERT INTO `blog_diary` VALUES (1360, 1, '博客部署好了，我把一些项目数据都同步的博客上了，接下来继续整理公司的定制项目，还有把之前做的印象笔记上的数据也搬过来，晚上整理文档的时候发现一个重要的问题，我应该加一个文件管理的页面，用来删除上传错误的文件，现在删除文件我都是去服务器上手动删除的，然后未来一个月的博客重点放在数据的整理上面，公司先把定制的项目整理完成，然后整理基线这个项目还有改的问题单，之后就是博客项目的优化，说的加文件功能暂时没计划，手动删文件也不是不能用，先就这样凑合这，在家就有时间整理整理印象笔记，暂时想不到其它的事情了，刚刚突然想到上传文件要不要加一个用户id的分组，这样看到清楚点，还有晚上写文档发现五级文档目录还是不够用，想再加几级，但是这个改动是有点大，就这样先用吧，刚写好还没用就要修改，代价实在是太大了，十一点半了，赶紧睡觉。最近看的书也要整理下，先前看的火星救援和挽救计划就不写了，把明朝那些事写完，然后阿西莫夫的基地小说也要继续看了，最近一直懒得看，距离上一本书看完也快一个月了吧，每天中午都在看视频，我得自己先静下心来。睡觉了。', '2023-06-04', '2023-06-04 23:35:38', '2023-06-04 23:35:38', 1);
INSERT INTO `blog_diary` VALUES (1361, 1, '小玩一会星露谷，今天开始博客开发，项目现在是定制的项目再测试，今天是南钢赛迪，明天要对接事件中心报警那个，项目名字忘了。se', '2023-03-06', '2023-03-07 00:10:24', '2023-03-07 00:10:24', 1);
INSERT INTO `blog_diary` VALUES (1362, 1, '感觉假期已经结束了，每天都被安排好了。e', '2023-09-30', '2023-10-01 00:09:52', '2023-10-01 00:09:52', 1);
INSERT INTO `blog_diary` VALUES (1363, 1, '今天是坚持锻炼的第二天也是早睡的第二天，公司项目对接赛迪平台的这个没进度，开发的是黄河鑫业单算法启停的接口，今天现场的问题也是算法下发的问题，等前端来了之后把单个算法的启停也加上，这样就黄河鑫业把我能想到的都开发完成了，晚上开发博客文档在后台管理的保存，开发完成，认真开发效率还是可以的，今天的关键字是锻炼早睡早起和高效吧，锻炼主要是常跑步骑车、晚上做做深蹲和俯卧撑锻炼臂力，高效主要是在博客开发的时候别瞎想其它没用的，这个版本博客注重使用界面只要能操作就行，在开发的时候要认真开发，去年经常就是打开开发软件然后玩游戏一天也过去了，去年的年终总结周六写，周日约了王鹏去西湖转悠，正好是元宵节，也出去走走。今天的就写这么多了，最近看高木同学还挺好看，现在已经看一半了，还有一季加5级左右。', '2023-01-30', '2023-01-30 22:39:50', '2023-01-30 22:39:50', 1);
INSERT INTO `blog_diary` VALUES (1364, 1, '上班一天解决了很多bug，但是下班数了数发现比早上还多，明天还要再测试一天，真顶不住了，赶紧结束吧，希望bug测试不会发现，用户不会遇到，遇到不是我的，我的bug都简简单单。se', '2023-11-27', '2023-11-27 23:54:18', '2023-11-27 23:54:18', 1);
INSERT INTO `blog_diary` VALUES (1365, 1, '手腕有点难受，不知道是不是因为做俯卧撑引起的，今天回家路上骑车稍微记了下速度，我才12km/h，怀疑人生了，第一步计划先到15km/h再说吧，搬过去上班可能要一个小时，但是也要搬，公司项目进度正常，但是今天收到通知我要被调到基线开发了，可能基线回很忙吧，也不清楚，现在休闲的日子到头了，不过做一些大项目也有利于找下一份工作。今天的五十个俯卧撑也很累、', '2023-02-21', '2023-02-21 23:02:30', '2023-02-21 23:02:30', 1);
INSERT INTO `blog_diary` VALUES (1366, 1, '服了啊，俩个板子每一个争气的，arduino和树莓派都是连不上网，烦。今天写了九条自动化测试。', '2023-06-21', '2023-06-21 23:39:32', '2023-06-21 23:39:32', 1);
INSERT INTO `blog_diary` VALUES (1367, 1, '明明上了四天班，但是今天为什么不是周四呢，又开了一天会，真的烦，工资到账9.7k，现在没有高温补贴连10k都上不去。se', '2023-10-10', '2023-10-11 00:30:28', '2023-10-11 00:30:28', 1);
INSERT INTO `blog_diary` VALUES (1368, 1, '昨晚睡得真爽啊，十点半就开始睡觉，一直睡到今天早上八点四十，都迟到了，所以不得不请假一小时，今天也稍微早点休息，公司最近不是很忙，今天就一个bug，改完我自己学习，最近做博客设置功能，大体的框架是已经弄好了，剩下就是爆肝，设置这块要做到东西很多，现在也只是设置功能开始做，其它地方还得写和设置的联动，也是一个大工程，最近晚上是真的忍不住不玩王国之泪啊，现在地下开图也开了3/4，要是没啥意外明天应该能开完地下的图，还有几个小格子不知道怎么进去，完全没有路，可能是要等剧情开。', '2023-07-25', '2023-07-25 23:33:50', '2023-07-25 23:33:50', 1);
INSERT INTO `blog_diary` VALUES (1369, 1, '又忙了一整天，累死，买的switch明天就到了，明天还要处理好多事情，小二结婚随了500的礼金，就这样，累了，睡觉。', '2023-07-06', '2023-07-06 23:09:54', '2023-07-06 23:09:54', 1);
INSERT INTO `blog_diary` VALUES (1370, 1, '今天又搬了一次工位，现在到基线这边也开始工作了，今天总共开了五个半小时的会议，到晚上十点多才回家，这周日计划搬家，但是今天还没看房间，还是就在公司附近租房吧，回家路上时间不能超过半小时。还有博客最近应该是没时间开发，工作日比较忙，休息日还有其他事情。', '2023-02-28', '2023-02-28 23:18:18', '2023-02-28 23:18:18', 1);
INSERT INTO `blog_diary` VALUES (1371, 1, '今天也没什么任务，博客也不想开发，感觉写的好乱啊，是真的想重构，最近不开发了，今天就写之前做的项目，定制的项目写完了，基线的刚开始写，晚上跑步三公里十六分钟，不知道是不是软件出问题了，之前都跑不到20，今天突然16，睡觉了。', '2023-08-16', '2023-08-16 23:10:14', '2023-08-16 23:10:14', 1);
INSERT INTO `blog_diary` VALUES (1372, 1, '树莓派安装好centos了，但是不能连wifi，想换回之前的debin系统但是树莓派的那个软件不能用了，真的是服了，总得给我找点事，明天继续吧。', '2023-06-28', '2023-06-28 23:14:50', '2023-06-28 23:14:50', 1);
INSERT INTO `blog_diary` VALUES (1373, 1, '今晚真是疲劳驾驶了，就想着把这个长途跑完，但是一路上都是小路，还堵车，到现在可算是完成了，最近公司就是改bug，不是很忙。', '2023-11-20', '2023-11-21 00:22:26', '2023-11-21 00:22:26', 1);
INSERT INTO `blog_diary` VALUES (1374, 1, '今天上午看现场的问题，没开发，下午没想到有年会，开完年会直接去那边吃饭，从下午开始手机就没电了，一直省着用电，晚上吃完饭抢红包都不敢一直亮着屏幕，评价下晚上去的餐厅，首先是感觉非常差，杭帮菜没吃习惯，没啥味，然后就是上菜速度是真的慢，非常不满意，最后抢红包抢到了66块吧，俩天的饭钱，下午部门抽奖没中，不过这就是随缘的东西，奖品也就几百块的东西，无所谓，今天还有一个开心的事就是杭州的补贴到账了，余额加5k，快乐的一天。', '2023-01-11', '2023-01-12 00:04:36', '2023-01-12 00:04:36', 1);
INSERT INTO `blog_diary` VALUES (1375, 1, '休息一天，感觉休不过来，今天都没开异星工厂，算是通关一次，下次等下周末在开始，今天计划写一下游戏总结，但是博客的文档功能没加上，等之后写吧，反正游戏存档不会丢，今天就把博客稍微升级一次，这次加上了博客图片上传功能，顺便修改了博客部署脚本，下午睡了一觉，今天大概就这样过去了，然后又开始了新的一周，最近都没锻炼，从明天开始继续吧，这个锻炼大概也只是会在工作日晚上才锻炼，周末根本记不住。', '2023-05-07', '2023-05-07 23:53:04', '2023-05-07 23:53:04', 1);
INSERT INTO `blog_diary` VALUES (1376, 1, '累了，明天再说，甚至晚上还开会到9点。', '2023-09-11', '2023-09-11 21:59:48', '2023-09-11 21:59:48', 1);
INSERT INTO `blog_diary` VALUES (1377, 1, '周末一天在玩星露谷，起来写日记发现中午泡面的碗还没洗，周末在家真是怠惰啊，晚上又给李玉婷交学费，我是真的服了，我当时啥也舍不得，给她上个初中一年2.4w学费都可以，心理不平衡，烦，不想写了，睡觉。', '2023-01-07', '2023-01-08 00:01:08', '2023-01-08 00:01:08', 1);
INSERT INTO `blog_diary` VALUES (1378, 1, '今天锻炼完成，公司接口开发正常吧，最后俩个数据卡住了，不知道从哪来获取数据，博客这几天还是没时间开发，其实今天晚上可以写写，但是我打游戏了，稍微找个借口可以说是因为电脑另一个屏幕不亮一个屏幕用的不舒服，看到的数据太少了，写前端没多屏实在是难受，后端接口可以暂时就用已有的这些，可能做些修改。', '2023-04-20', '2023-04-20 23:27:18', '2023-04-20 23:27:18', 1);
INSERT INTO `blog_diary` VALUES (1379, 1, '今天上午去看了牙医，然后预约的29号过去洗牙，我这个不知道算不算严重，最后肯定是只能洗牙处理，以后多注意点吧，在家都不想打游戏有点emo，然后下午正好旭福不去上班，我就骑车过去了，去了蹭顿饭，玩了三把云顶之奕输了三把，真难受，看别人电脑显卡好，屏幕大，玩起来是真的舒服，真想早点换张显卡啊，40系能不能别这么恶心人，只能等等，晚上骑车回来，今天总骑行差不多60公里，晚上把该洗的衣服都洗了，代码也更新了，把骑行截图也总结好了，能做的事情都完成了，没啥事情是真的轻松，现在最应该打打王国之泪，想想都惬意，但是已经不早了，要准备睡觉，晚上写博客接口一直出问题，不知道啥原因，会不会因为socket占用网络，或者我前段优化不行导致的，总之就是上传不了图片，有时候请求接口数据也会报错，晚上我这看视频也会卡，有可能也是我这的原因，等下个版本修复之后我再测试下。', '2023-08-20', '2023-08-20 23:21:40', '2023-08-20 23:21:40', 1);
INSERT INTO `blog_diary` VALUES (1380, 1, '到昨天刚刚好是在大华工作满俩年，但是昨天没想起来，今天也来得及，今天项目主要是忙萤火虫那个打包构建，四处找人问，可算是弄完了，然后有个查询数据的性能问题，应该是可以解决的，一万的数据问题不大，主要是我技术菜，写的sql有问题，in之后的数据太长了所以导致查询时间很长，晚上回家和超凡联机就玩了半小时，实在是太累了，还开箱了switch，没啥问题，塞尔达很惊艳，玩的很爽，这次购物体验不亏。', '2023-07-07', '2023-07-07 23:46:14', '2023-07-07 23:46:14', 1);
INSERT INTO `blog_diary` VALUES (1381, 1, '昨晚又是失眠，四点多才睡着，不知道今天怎样，下午还睡了一会，感觉情况也不乐观。se', '2023-10-03', '2023-10-03 22:29:04', '2023-10-03 22:29:04', 1);
INSERT INTO `blog_diary` VALUES (1382, 1, '今天弄socket给我整不自信了，甚至一度想再重构一次博客，但是想想成本实在是太大了，现在的rocketmq也想换，但是才弄好没几天，就忍忍吧，想想还能不能找到好用的方法，今天跑步总感觉跑了很多，平二十分钟都快跑完了，今天二十分钟才跑了二公里多一点，应该是新换场地gps不准吧，明天要是没啥事还能摸鱼。e', '2023-08-15', '2023-08-16 22:59:18', '2023-08-16 22:59:18', 1);
INSERT INTO `blog_diary` VALUES (1383, 1, '忙碌了一整天，可算是把测试用例点完了，还花了挺长时间的，上午下午都在忙，一刻没歇，晚上本来想早点下班，但是看同事一个没走（其实走了一个），我也就留下来陪陪他们，我得测试用例下午就完成了，晚上继续博客，完成了文档根据用户选择的功能，还加了一个小小的细节，用户登陆之后文档默认展示登陆用户的，这就是高手，现在文档这个完成了，下一步搞注册，注册流程是必填是用户名、密码、邮箱和昵称，和之前的博客第一版一样注册的账号需要去邮箱中激活，我发送个链接，去邮箱中点击激活，这个功能之前做过，再来一次问题不大，昨晚做噩梦了，梦到被人追杀，还是个女生，一直失眠到两点，早上六点又被吓醒，但是今天没瞌睡，中午也没睡着，现在不早了，要睡觉了。d', '2023-06-15', '2023-06-15 23:45:32', '2023-06-15 23:45:32', 1);
INSERT INTO `blog_diary` VALUES (1384, 1, '火车上过夜，所以没写日记，到放假项目进度正常。', '2023-01-17', '2023-01-18 23:44:10', '2023-01-18 23:44:10', 1);
INSERT INTO `blog_diary` VALUES (1385, 1, '今晚忍住没打王国之泪，把家里收拾了下，整理了桌面，今天感觉又像个住的地方了，不再是猪圈，代码也提交了，还没计划换新版本。', '2023-07-23', '2023-07-24 00:08:34', '2023-07-24 00:08:34', 1);
INSERT INTO `blog_diary` VALUES (1386, 1, '等了一天自行车都没发货，看周日咋样吧，下午晚上都在联机泰拉瑞亚。', '2023-02-25', '2023-02-26 00:13:28', '2023-02-26 00:13:28', 1);
INSERT INTO `blog_diary` VALUES (1387, 1, '小周上班好累啊，弄了一下午netty没弄好，睡觉了。se', '2023-09-23', '2023-09-24 00:11:14', '2023-09-24 00:11:14', 1);
INSERT INTO `blog_diary` VALUES (1388, 1, '躺了一天，写完了明朝那些事的总结，今天就睡了，明天要是天气好就去王鹏那边看看arduino的问题，为啥上传老是失败。', '2023-06-23', '2023-06-23 23:08:30', '2023-06-23 23:08:30', 1);
INSERT INTO `blog_diary` VALUES (1389, 1, '周日，但是因为五一调休不得不去加班干活，海康门禁那个项目今天又说卡片下发不下去了，不得不去看现场问题，我是真服了，最近还有基线的开发任务，总之先慢慢来吧，之前能调好一次就能弄好第二次，只不过稍微费点时间，基线新开发的功能基本也差不多了，有时间看这个问题，但还是很烦，晚上下班路上还被一个电瓶溅了一身水，真是缺德玩意，明天周一，等明天继续看问题吧，拿钱就要给人办事，最近看明朝那些事就差最后百分之几了，再有俩三天应该可以看完，晚上也坚持锻炼了。', '2023-04-23', '2023-04-23 23:50:06', '2023-04-23 23:50:06', 1);
INSERT INTO `blog_diary` VALUES (1390, 1, '今天重新部署了博客新版本，希望没啥问题吧，明天早上看消息，今天就主要调试修改接口，明天搞信息展示页面的哪些接口，算法管理平台的前端暂时不对接，还有就是要开始考虑盛鹏给的那个接口要怎么实现，数据从哪来，最近晚上不想锻炼，近期项目很忙，博客这些要等等了，最近开发发现mybatisplus是真的好用，计划在我博客中大量使用，能省不少时间。', '2023-04-17', '2023-04-18 00:00:32', '2023-04-18 00:00:32', 1);
INSERT INTO `blog_diary` VALUES (1391, 1, '又玩的不早了，今天搞机器人缓存的问题，应该是可以了，晚上回家王国之泪，第一次找攻略，可算是把栏杆拆下来了。', '2023-07-31', '2023-08-01 00:08:48', '2023-08-01 00:08:48', 1);
INSERT INTO `blog_diary` VALUES (1392, 1, '今天自行车卖出去了，卖了120，也算是处理了一件事，以后就不用看咸鱼了，今天继续改bug，也不算是忙，晚上加班也没看项目，没看博客，看了一晚上动漫，新番我推的孩子还行。睡觉了。', '2023-05-31', '2023-05-31 23:54:04', '2023-05-31 23:54:04', 1);
INSERT INTO `blog_diary` VALUES (1393, 1, '休息一天，和绍哲开了一个文明六，晚上还完了泰拉瑞亚，明天找王鹏学习单片机，不知道能学咋样。', '2023-06-17', '2023-06-18 00:00:56', '2023-06-18 00:00:56', 1);
INSERT INTO `blog_diary` VALUES (1394, 1, '本以为今天会不忙，结果改了一天bug，晚上十点多才到家，回来开开车放松一下。se', '2023-11-21', '2023-11-22 00:21:26', '2023-11-22 00:21:26', 1);
INSERT INTO `blog_diary` VALUES (1395, 1, 'switch没电了，不然感觉我现在真停不下来，火之神殿打完了，今天在打风，明天晚上就能完成，之后剧情不知道是不是就要打魔王了，如果真是这样我就要肝其它事情了，神庙、电池啥的有很多。公司bug那可以说是一言难尽了，洪斌出差了，把他的bug也分给了我，有些改起来都不知道怎么处理，我还有几个机器人的问题，也是服务之间的问题，不好改。', '2023-07-17', '2023-08-10 23:38:04', '2023-08-10 23:38:04', 1);
INSERT INTO `blog_diary` VALUES (1396, 1, '公司没啥任务，搞博客搞出一个bug，希望好解决吧，然后博客前端也整合的socket和mitt，这下之后的一些和后端交互的数据就剩下爆肝了，应该不会在引入其它的依赖的，就剩下对已有技术的熟悉，晚上的泰拉瑞亚没有打新的boss就做了些装备。', '2023-06-09', '2023-06-10 00:03:26', '2023-06-10 00:03:26', 1);
INSERT INTO `blog_diary` VALUES (1397, 1, '今天小周，但是请假了，送走妈妈，但是晚上因为最近的台风带来大量降雨，河南那边发洪水，所以火车停了，可能会再多住几天吧。', '2023-08-05', '2023-08-05 23:17:36', '2023-08-05 23:17:36', 1);
INSERT INTO `blog_diary` VALUES (1398, 1, '无聊的一天，最近听b站的动漫小说，感觉不错，中移的接口清单完成了。', '2023-09-05', '2023-09-06 00:06:58', '2023-09-06 00:06:58', 1);
INSERT INTO `blog_diary` VALUES (1399, 1, '不是很累，早下班了躺了一晚上，但是不想写，明天再说吧，把衣服洗完了。', '2023-09-13', '2023-09-13 23:05:58', '2023-09-13 23:05:58', 1);
INSERT INTO `blog_diary` VALUES (1400, 1, '肚子好疼啊，从下午开始就是，是不是因为吃了那根坏了的香蕉，好烦，还有b站的赌硬币，再也不玩了，几天就输了我三年攒的硬币，就剩900多了。', '2023-08-31', '2023-09-01 00:03:22', '2023-09-01 00:03:22', 1);
INSERT INTO `blog_diary` VALUES (1401, 1, '博客文件查询的功能算是比较完善了，今天还可以修改了细节，个人感觉是不错的，晚上继续锻炼，三公里还是没突破二十分钟。dl', '2023-08-09', '2023-08-09 23:56:10', '2023-08-09 23:56:10', 1);
INSERT INTO `blog_diary` VALUES (1402, 1, '今天实在是忙，昨天说的任务今天都做完了，顺便发现了昨天写的数据库升级脚本的一个bug，改过来了，但是没听说今天升级，然后就是改接口，改了好几个还有之前说的阈值模板的问题，算是改完了，明天看去了干啥吧，反正最近事挺多的，不可能歇下来，虽然累，但盼着明天就要发工资了，日子有个盼头。补充下，今天第二天也坚持锻炼了。', '2023-05-09', '2023-05-09 23:26:30', '2023-05-09 23:26:30', 1);
INSERT INTO `blog_diary` VALUES (1403, 1, '又是一堆问题，不想看了，开摆。se', '2023-12-13', '2023-12-13 23:36:14', '2023-12-13 23:36:14', 1);
INSERT INTO `blog_diary` VALUES (1404, 1, '总算是放假了，连上七天，晚上和绍哲联机玩消逝的光芒，最近巴以冲突好严重啊，庆幸这边没有战争。', '2023-10-13', '2023-10-14 00:25:10', '2023-10-14 00:25:10', 1);
INSERT INTO `blog_diary` VALUES (1405, 1, '今天更迟，暴毙一次，但是当时有点早，所以之后谨慎下矿。', '2023-03-09', '2023-03-10 01:03:08', '2023-03-10 01:03:08', 1);
INSERT INTO `blog_diary` VALUES (1406, 1, '今天没出门，在家就搞搞博客，有个问题不知道怎么经常出现，但是最近几次部署可以了，把博客编译安装MySQL修改了下，不过不打算修改我的部署脚本，晚上的这次部署MySQL配置信息也可以正常使用了，就是部署的时候忘了备份图片，还好现在的图片不多不用大修改，手动加上了，现在有个问题，以后换服务器但是现在的图片都是写死了ip，还没有好的结局方法，不过买个域名好像可以，把域名放到sql里面回解析到域名对应的ip，以后换服务器也好修改，以后再说吧，可能还想自己弄个服务器，随便装个机放家里，这样问题的没公网ip，总之都不够完美，还是我现在水平不够高，慢慢来吧，博客最近就完善已有功能，主要是接口的修改和使用优化，界面样式先等等，现在能用就行的阶段，不能好高骛远。', '2023-01-27', '2023-01-27 23:45:46', '2023-01-27 23:45:46', 1);
INSERT INTO `blog_diary` VALUES (1407, 1, '虽然今天白天都在打游戏，但是晚上努努力还是完成了新的简历，从明天开始就要准备复习了，也不报太大的希望马上就能找到新工作，反正我也不着急，现在就慢慢投，期望薪资那就18-20吧，毕竟是准备去北京，生活成本高，为啥不在杭州呢，主要是杭州这工资还是偏低，我出来就是为了挣钱的，还有杭州实在是太卷了，真是一点都卷不动了，动不动就加班。今天玩无主之地，开始还没啥劲，后来刷装备是真的好玩，还有之前用的繁体字，虽然能看懂，但是肯定比简体看的要慢，打了语言汉化之后可以瞬间看完剧情，最近好像没啥心情写日记，而且打游戏特别上瘾。', '2023-11-05', '2023-11-05 23:55:50', '2023-11-05 23:55:50', 1);
INSERT INTO `blog_diary` VALUES (1408, 1, '公司的项目今天是写的mysql存储过程，给测试造数据，之前写过，看博客之前的记录写的今天的存储过程，果然博客还是很重要的，然后空闲时间还写了几个项目的记录，博客近期应该是不会更新了，等六月二十多买了新服务器换版本，可能还是当前版本，最近不打算有大修改。', '2023-06-05', '2023-06-05 23:42:04', '2023-06-05 23:42:04', 1);
INSERT INTO `blog_diary` VALUES (1409, 1, '之前写的ppt丢了，然后今天又花时间重新写，最近在调试赛迪平台对接，第三方开发响应速度好慢。', '2023-03-27', '2023-03-27 23:58:06', '2023-03-27 23:58:06', 1);
INSERT INTO `blog_diary` VALUES (1410, 1, '新巡检接口几乎开发完了，剩下几个有点不好搞的接口，慢慢来，还有好几天，这周团建，周六不干活。', '2023-04-13', '2023-04-13 23:47:12', '2023-04-13 23:47:12', 1);
INSERT INTO `blog_diary` VALUES (1411, 1, '大周周日，休息好了，准备迎接新的一周，距离杭州亚运会还有6天，距离国庆回家还有10天，公司最近项目是开发1.1.4版本，还有很多1.1.3测试新提的bug，大概十几个吧，天天看jira，看到那些问题单我就烦，这个季度的自动化测试用例完成6条剩余19条，想要完成需要每天都写俩个，花点时间应该没问题，每天开始恢复晚上跑步，但是我不打算跑步了，走快一天也行，跑步可能会伤膝盖，我现在以养生为主，下午去骑行近俩小时，总共才走了30公里，和别人一起还是不如自己一个人方便，本来今天想着是去看看奥体广场那边，但是陪罗登城去修自行车了，我是没骑多少路，还没去成奥体广场，啥也没办成，晚上回来写文档，把今天的骑行记录下，准备写上周千岛湖旅游，但是看到了去年方特想起来把去年的也写一下，没想到写完就十一点了，明天晚上要是有时间可以把千岛湖的总结完成，今天就这吧。准备睡觉，博客备份也完成了，最近写的脚本有点好用，但是还有个小问题，不知道为啥文章中的图片ip修改错误，最近学习docker，这个部署速度很快，不用像我之前那样，一个半小时的部署时间，其中一个小时多的时间都是在编译安装mysql，前几天在公司测试安装docker速度很快，新的脚本完成之后理论上是可以在树莓派和服务器上使用，还需要到时候慢慢测试，今天就这样了，晚上也没时间洗澡了，明天需要早点起床。', '2023-09-17', '2023-09-17 23:33:34', '2023-09-17 23:33:34', 1);
INSERT INTO `blog_diary` VALUES (1412, 1, '晚上开车，今天累了，早点睡觉。', '2023-10-31', '2023-10-31 23:35:34', '2023-10-31 23:35:34', 1);
INSERT INTO `blog_diary` VALUES (1413, 1, '都十二月了，博客这几个月是一点没动，天天加班实在是没时间再看了，晚上或者周末也没精力去学习，真的感觉应该换个工作了，明天又是小周。', '2023-12-01', '2023-12-02 00:34:44', '2023-12-02 00:34:44', 1);
INSERT INTO `blog_diary` VALUES (1414, 1, '今天做五十个俯卧撑好累啊，最后几个都做不动了，还有一天就上午玩了玩游戏，之后没事干坐着看视频，无聊的一天。', '2023-02-19', '2023-02-19 22:53:52', '2023-02-19 22:53:52', 1);
INSERT INTO `blog_diary` VALUES (1415, 1, '今天开始有任务了，整理些接口，修改请求类型，感觉工作量不大，就是怕修改之后接口出问题，晚上骑车去湘湖，那边骑车的人好多，跟着大佬蹭风，可惜忘了开记速，也不知道跑多快。', '2023-08-25', '2023-08-26 00:38:04', '2023-08-26 00:38:04', 1);
INSERT INTO `blog_diary` VALUES (1416, 1, '今天把博客文档版本的功能部署了，但是根据图片加载速度看好像使用nginx代理的图片服务器加载速度更快一点，不知道要怎么取舍了，能下次有时间测试下相同文件大小的图片加载速度，暂时就这样先用着，近期考虑优化博客功能，把已有功能加点住宿，注释这个在家的时候加，公司有时间还是要维护功能的，今天写了一天代码，差不多是一天吧，除了给璐瑶下载了个文件休息了半小时，晚上稍微玩了会星露谷，剩下时间大部分在搞博客，但是最后还是出问题了，部署之后鉴权服务和文件服务一直起不来，查看日志是因为nacos配置的问题，我手动修改配置之后现在是可以使用了，等下次有时间整体部署下，把这个版本记录下来，整理下数据，今天下午整理部署了三次每次都是前端出问题，不知道是怎么搞的部署之后页面一直是上个版本的页面，改了三次才该对，按理来说这个不应该啊，我都是西现打包的，看服务器是的时间也是今天，每次启动之后就是上个版本的页面，最后一次是手动部署的前端文件，晚上还解决了一个问题，之前一直刷新页面会404，百度之后发现是nginx代理单文件前端页面找不到其它路径，所以提示404，这个是百度的结果，加了这么一行就没问题了（try_files 表示检查文件是否存在，返回第一个找到的文件，这里设置是index.html内部重定向），先就这样，差不多也是2k的日记了。', '2023-05-21', '2023-05-21 23:57:40', '2023-05-21 23:57:40', 1);
INSERT INTO `blog_diary` VALUES (1417, 1, '今天投入定制，对接联丰的协议改了，稍微修改代码，下午测试没完成，主要是懒得动，就想偷懒摸鱼，下午还吃了生日蛋糕，预约了周四上午去医院的，快递的挎包和水瓶都回来了，感觉这水杯真不值那么贵。', '2023-03-21', '2023-03-21 23:32:30', '2023-03-21 23:32:30', 1);
INSERT INTO `blog_diary` VALUES (1418, 1, ' 芜湖，太爽了，刷了好多装备，就是现在不早了，代码也没整理。', '2023-12-28', '2023-12-29 01:35:16', '2023-12-29 01:35:16', 1);
INSERT INTO `blog_diary` VALUES (1419, 1, '体检完了，心凉了一半，三个问题吧，耳朵这个我知道，初中那会摔的，体力是有点差，喉咙扁桃体肿最近在看，牙结石这个准备去医院洗洗吧，也没啥大不了的，今天是真的无聊，游戏不想玩，干啥都没劲。e', '2023-08-19', '2023-08-19 23:49:52', '2023-08-19 23:49:52', 1);
INSERT INTO `blog_diary` VALUES (1420, 1, '今天改bug，但是完全没有动力，坐那就是想摸鱼，不过到最后还是把新版的阈值模板数据校验写完了，等明天测试，能改的bug还有七个，都是不好处理的，晚上写mq的数据初始化上报，写了一半，明天晚上继续吧。', '2023-07-03', '2023-07-03 23:31:40', '2023-07-03 23:31:40', 1);
INSERT INTO `blog_diary` VALUES (1421, 1, '今天是完完全全躺了一天，看着视频躺床上，明天再继续努力吧，今天虽然今天已经过去了，看了下去年写了364篇日记，我还是很勤快的嘛。', '2023-01-02', '2023-01-02 23:09:28', '2023-01-02 23:09:28', 1);
INSERT INTO `blog_diary` VALUES (1422, 1, '今天确实不忙，抽时间就写写博客，现在文档我决定弄成五级，如果以后还想加也很简单，稍微改几行就行，这周应该有希望完成博客文档这块，也只能是个大概，细节还得以后慢慢来维护，今天开始玩星露谷，下一个游戏开始之前必须要把星露谷全成就。', '2023-05-15', '2023-05-15 23:41:36', '2023-05-15 23:41:36', 1);
INSERT INTO `blog_diary` VALUES (1423, 1, '最近沉迷王者荣耀，晚上都没写博客。', '2023-03-15', '2023-03-15 23:16:20', '2023-03-15 23:16:20', 1);
INSERT INTO `blog_diary` VALUES (1424, 1, '异星工厂六色瓶完成，但是蓝色的产量有点低，原因是钢产量有点少。', '2023-05-03', '2023-05-04 00:00:34', '2023-05-04 00:00:34', 1);
INSERT INTO `blog_diary` VALUES (1425, 1, '喜提双休，但是明天可能需要在家看现场问题。', '2023-04-07', '2023-04-07 23:57:42', '2023-04-07 23:57:42', 1);
INSERT INTO `blog_diary` VALUES (1426, 1, '杭州的补贴到了，现在全部家当突破了24w，白天开发博客，晚上出去骑行，今晚骑了33公里，不早了，睡觉。', '2023-08-11', '2023-08-12 00:12:08', '2023-08-12 00:12:08', 1);
INSERT INTO `blog_diary` VALUES (1427, 1, '今天看了看代码，那个bug肯定和socket有关系，在公司的socket没问题，但是http有问题，在家是http没问题，socket连不上，我觉得还是和证书有关系，实在不行就换回http，这个问题慢慢来看吧，一时半会我也处理不了，今天玩了玩星露谷，把公司的项目笔记总结了，完成了异星工厂第一次通关的记录，也算是有点事做，不至于浪费一个周末，不过说的要出去骑车，结果还是太累，想在家里躺着。睡觉吧，不一定睡，先躺下，还有今天房东过来装了个纱窗。', '2023-06-11', '2023-06-11 23:21:26', '2023-06-11 23:21:26', 1);
INSERT INTO `blog_diary` VALUES (1428, 1, '今天好累啊，不是说项目很忙，虽然是只有一个问题，但是这个问题实在是太难了，弄了一整天没进度，下午还叫导师一起看，晚上找熊勇大哥帮忙看，但是服务器在升级，其实我晚上也不想看了，太累，晚上自己学习oauth2的第三方登陆今天弄码云的登陆，后来报错应该是需要我自己的服务也颁发个证书，不然不让请求第三方，不知道是不是这个问题导致了，总之这周有时间先给博客申请个证书，以后博客就是https服务了，今天还有个好消息，上午交房租房东给退了50，以后房租也降50，快乐。', '2023-02-07', '2023-02-07 22:48:40', '2023-02-07 22:48:40', 1);
INSERT INTO `blog_diary` VALUES (1429, 1, '太爽了，打了一整天gta5，确实是一个经典的游戏。', '2023-10-28', '2023-10-28 23:44:40', '2023-10-28 23:44:40', 1);
INSERT INTO `blog_diary` VALUES (1430, 1, '大周加班干活，好在最后发测了，明天还要复习下，周一有一个面试。', '2023-11-11', '2023-11-12 00:06:20', '2023-11-12 00:06:20', 1);
INSERT INTO `blog_diary` VALUES (1431, 1, '今天在公司的项目还挺忙的，赛迪平台dssas改名和作业管控新增算法，俩个项目，作业管控这还加了一个接口没测试，等周一再说吧。黄河鑫业这个应该是今天可以调试的，但是算法返回的数据有问题，不知道是不是算法的唯一编码变了，总之就是不太对劲了可能这块又要修改，今天因为是算法列表不是黄河鑫业的算法所以没修改，今天周五，有点想晚睡，但是习惯给坚持所以就算了吧，晚上俯卧撑状态挺好做了三十个之后还有力气，就加了五个，做完部署的博客没改nacos的配置，服务器用开发环境的配置文件导致服务没起来，今晚又部署一次明早起来再看看，应该不会有其他问题了吧，最近看高木同学，因为时间比较少，大概是一天两集，这个周末应该就能看完，下一个动漫要看啥还没想好，再次补充，前几天和淘宝客服反馈的案件重复问题今天补发到货和我这个键盘的按键不是一套的，楼下拆开的时候就觉得不对劲，这次购物体验实在是太差了，好在客服每次响应都非常及时，几乎都是秒回，不然这绝对得给我退货，现在应该没补充的了，睡觉。se', '2023-02-03', '2023-02-03 22:49:52', '2023-02-03 22:49:52', 1);
INSERT INTO `blog_diary` VALUES (1432, 1, '今天骑行68公里，平均速度是20.公里每小时，晚上联机打泰拉瑞亚，有点累了，休息。', '2023-03-11', '2023-03-11 23:44:16', '2023-03-11 23:44:16', 1);
INSERT INTO `blog_diary` VALUES (1433, 1, '出去走了一整天，去了白堤断桥和雷峰塔，总体感觉就是人多，到处都是人，雷峰塔之前我去过一次，那次感觉没多少人，进门都没堵，这次去了就那么大的一个塔每层都是人挤死了，下来也都是人，西湖人流量还算正常，睡觉了，明天他们去动物园，我就不过去了，在家休息会，洗洗衣服。', '2023-07-29', '2023-07-30 00:01:28', '2023-07-30 00:01:28', 1);
INSERT INTO `blog_diary` VALUES (1434, 1, '把博客换到了新服务器上面，结果怎样还不清楚，刚上去瞅了一眼，应该是没问题的，然后今天没做啥事情，下午睡觉，晚上玩gta5，真的有点上头，确实好玩，下周继续，突然想起来博客更新还没提交，明天早上看吧。', '2023-07-02', '2023-07-03 00:18:32', '2023-07-03 00:18:32', 1);
INSERT INTO `blog_diary` VALUES (1435, 1, '周日计划搞博客结果数据库脚本没弄回来，只能明天了，然后周二晚上要讲作业管控，明天熟悉下吧，今天把自行车的后货架装好了，驼包也到了，五一一定要去千岛湖，现在还差备胎没买。骑行服就算了吧，感觉穿上有点奇怪，我这就是长途休闲骑。se', '2023-04-02', '2023-04-03 23:20:54', '2023-04-03 23:20:54', 1);
INSERT INTO `blog_diary` VALUES (1436, 1, '今天准备是写文档的接口和界面，但是搞了半天感觉之前写的接口太拉跨了，功能单一，又不好复用，准备重新搞几个文档接口，可能文档的数据库也要修改，毕竟这个是要长久使用的博客，还是开发的一步到位吧，公司项目开发差不多了，下午搞现场的一个问题，最后也是完美完成。', '2023-01-12', '2023-01-12 23:09:00', '2023-01-12 23:09:00', 1);
INSERT INTO `blog_diary` VALUES (1437, 1, '工资到账了，今天没有锻炼，太累了，晚上到家就快十点了，接下来要测mqtt和ftps还有一个tree接口没改。', '2023-05-10', '2023-05-10 23:03:06', '2023-05-10 23:03:06', 1);
INSERT INTO `blog_diary` VALUES (1438, 1, '快乐的发薪日，这个月工资应该是一万多一点，但是今天到账是1.2w多，看了看短信的12026.21，比我预期要多出了2k，难道是涨工资了？要是真涨工资了，那做梦都得笑醒，一次涨2k，还是到手12k，那基础不得13.5k啊，看下个月到手多少钱吧，或者过几天查工资单，今天查没信息，博客今天继续写我的云盘功能，明天应该可以写差不多，最近都是在考虑界面样式，把各种细节的菜单都弄上了，明天就是写上传和修改文件名称，项目要是不忙应该问题不大，最近的bug和我的关系不是很大，下午快下班那会有个设备点位打开异常，报错是我这查询这个点位的设备通道现实离线，我去查数据库，表中设备是在线的，通道离线，所以不是我查询的问题，应该是收到的订阅消息没有更新，稍微看了下是有个版本的原因，明天过去仔细看看，计划这周把新版的博客更新上去，晚上跑步就周一到周四，现在体力还没恢复，就2332这样四天安排，一周十公里，明天晚上下班就不加班了，回家放好东西出去骑车去，刷个四五十公里，这样以后那就是一周加班四天，反正我加班也是学习，也不那么抗拒，今晚回家没玩王国之泪，可能是最近我的探索欲望降低了吧，但是这个游戏我一定要100%进度通关，睡觉。dl', '2023-08-10', '2023-08-10 23:37:46', '2023-08-10 23:37:46', 1);
INSERT INTO `blog_diary` VALUES (1439, 1, '昨天晚上在火车上，很累，所以没有用手机写日记，昨天白天没干活，就学习docker，一直卡在了nacos无法连接MySQL，明天试试怎么解决，也就是昨天的后天。', '2023-09-27', '2023-09-28 23:57:04', '2023-09-28 23:57:04', 1);
INSERT INTO `blog_diary` VALUES (1440, 1, '加班到十点，晚上到家不想睡，打了会游戏就到了现在。se', '2023-11-09', '2023-11-10 00:27:58', '2023-11-10 00:27:58', 1);
INSERT INTO `blog_diary` VALUES (1441, 1, '无主之地存档找回来了，本想着玩一天，结果睡了一下午，明天要是天气好出去骑车。e', '2023-12-17', '2023-12-18 13:33:18', '2023-12-18 13:33:18', 1);
INSERT INTO `blog_diary` VALUES (1442, 1, '五四放假下午小睡一会，晚上搞产线，断电好几次，现在发现这个游戏绿板是真缺啊，然后就是铜线产量跟不上，我都蓝带满载了还是缺，下个档试试三跳铜线产线看看。', '2023-05-04', '2023-05-05 00:46:34', '2023-05-05 00:46:34', 1);
INSERT INTO `blog_diary` VALUES (1443, 1, '总算是放假了，这个大周弄下树莓派。', '2023-09-01', '2023-09-02 00:08:04', '2023-09-02 00:08:04', 1);
INSERT INTO `blog_diary` VALUES (1444, 1, '昨天真是倒霉，到这个点了应该是说前天吧，吃包子有保鲜膜，晚上回家睡觉和吵醒，那几个大妈真烦人，今晚回家准备部署好博客，但是直到现在还是有问题，不知道为啥图片一直上传不了，这个不是早就弄好的功能吗，但是现在出问题了，没搞明白原因，看日志也没有报错，还出现一个问题是卡不开cropper的截图框，测试发现是我版本的问题，还有博客部署文档有问题，文件备份恢复失败，周六看脚本吧，创建文件变成了创建文件夹，应该是小问题，就是奇怪为啥图片上传不了，本地测试一直都是正常的，这块也没出过问题，晚上早下班还没弄好，很烦，先睡觉吧。补充一下，今天还收到了儿童节礼物，有个蜡笔小新手办。', '2023-06-01', '2023-06-02 00:22:06', '2023-06-02 00:22:06', 1);
INSERT INTO `blog_diary` VALUES (1445, 1, '只休息一天是真不够啊，之前都是周六打游戏，周日可能会躺一天，看看动漫，但是单休只有一天休息时间，游戏也没力气打，下午开了一个缺氧坑，估计也玩不了几天，这么多年上学一直都是说的以后就轻松了，结果走下来就没过几天舒坦日子，处理下飞书文件准备睡觉吧，有点好奇死后是什么样子的，应该不会996了吧。e', '2023-11-26', '2023-11-26 23:54:08', '2023-11-26 23:54:08', 1);
INSERT INTO `blog_diary` VALUES (1446, 1, '巡检要加日志功能，也就是一句代码的事情，主要是还要给洪斌代码也加上，明天得仔细看看代码，这周也就这样了，今晚回家就九点半了，小玩一会王国之泪，感觉沙漠这好像卡住了，有个灯上面应该是有土埋住了，用水冲不了，石头砸不碎，不知道怎么处理，但是我肯定不会看攻略，自己摸索着才好玩，明天早回家吧，实在是太想玩游戏了，真的好久没这种探索的感觉了，一下突然来了俩个这么优秀的游戏，睡了。', '2023-07-13', '2023-07-13 23:59:12', '2023-07-13 23:59:12', 1);
INSERT INTO `blog_diary` VALUES (1447, 1, '本来今天是想多写点字数的，但是现在不早了，因为玩星露谷停不下来，现在只好长话短说了，计划今天搬家，但是没搬，然后上午稍微玩了会缺氧，中午吃完饭，然后去西湖骑车溜达一圈，大概20公里吧，晚上出去买炸鸡块回来和人撞了，非要说责任拿都是有的，我骑的稍快点，但是那个速度绝对没上18，那个电瓶车突然左转也是有责任的，好在我撞倒没啥大事，回来照镜子发现额头上破了一道，应该是在绿化带树枝划到了。没事最好了。se', '2023-03-05', '2023-03-06 00:57:34', '2023-03-06 00:57:34', 1);
INSERT INTO `blog_diary` VALUES (1448, 1, '今天也没项目，现场问题那个不知道好没好，之前出问题是因为包不是最新的，换新包之后没回应，博客抄的差不多了，这个博客的笔记部分不太满意，打算改成点进去之后是一个一个笔记本的样子，可以查看自己的笔记和所有人的笔记这样的功能，然后点击笔记本进去是详细页面数据，还有后端展示的操作页面不太满意，要修改成我现在的这个后端样式，主要就是这些，还想加一个照片墙的功能，最好是通过后端来获取照片，这样我就能设置照片的查看权限，昨天看完了《献给阿尔吉侬的花束》，今天开始看《明朝那些事》，上一本书的观后感和去年的数据总结这周完成，今天做五十个俯卧撑和四十个深蹲好累啊，昨天都没这么累，做完之后歇了会，感觉浑身充满了力量最后又做了十个俯卧撑，这几天消化不好，感觉真的有必要去医院看看了，计划周六吗？我也不确定要不要去，这俩天晚上都没吃饭。', '2023-02-14', '2023-02-14 22:48:44', '2023-02-14 22:48:44', 1);
INSERT INTO `blog_diary` VALUES (1449, 1, '一堆bug把能修改的都改完了，剩下几个明天看吧，然后又开始自测，基线好无聊啊，天天改bug，晚上过了风神殿，我一开始以为只能撞，一直躲石头，滑翔下去撞怪物，只要歪了就gg，还要躲龙卷风，本来第一次就差不多要过了，我以为建筑能挡风，没想到不行，直接给我秒杀，差点心态爆炸，一共打六下，我都完成五次了，最后一次错失良机一直没找到再次出手的机会然后就挂了，之后多次打，发现射箭也可以然后就进入林克时间，轻松拿下，甚至我跑怪物下面强杀，简简单单。e', '2023-07-18', '2023-07-19 00:28:46', '2023-07-19 00:28:46', 1);
INSERT INTO `blog_diary` VALUES (1450, 1, '项目也发测了，今天就搞博客，文件服务的功能都做好了，不知道有没有bug，今晚下棋不早了，睡觉吧。', '2023-08-04', '2023-08-05 00:43:04', '2023-08-05 00:43:04', 1);
INSERT INTO `blog_diary` VALUES (1451, 1, '白天加班干活，晚上疲劳驾驶。欧卡模拟器，启动！！！', '2023-10-30', '2023-10-31 00:44:58', '2023-10-31 00:44:58', 1);
INSERT INTO `blog_diary` VALUES (1452, 1, '早下班就是舒服，回家休息舒服了还有心情做起来玩了玩星露谷，虽然只有短短俩天，充分说明我还是有玩游戏的欲望的，只不过是上班太累了，白天公司吃了蛋糕，这个月有我，甚至我们组九个人有四个都是这个月的。se', '2023-10-18', '2023-10-18 23:32:12', '2023-10-18 23:32:12', 1);
INSERT INTO `blog_diary` VALUES (1453, 1, 'centos系统装好了，但是连不上wifi，还没找原因，有线网可以，应该问题不大，明天晚上看看吧，这几天又是bug，又是自动化，今天还有现场项目看日志，真的是累死了，睡觉了。晚上回家游戏都没玩。', '2023-06-27', '2023-06-27 23:32:36', '2023-06-27 23:32:36', 1);
INSERT INTO `blog_diary` VALUES (1454, 1, '公司项目进度正常，今年把对接赛迪平台的设备同步接口完成了，下周还有四个接口，要怎么做还没看，应该可以在年前回家完成。博客最近做文档模块，这块界面搞得有点难看，凑合用吧，晚上回家打星露谷，稍微晚了点，不过明天不上班，至少群里没通知上班，我就当不上班了。', '2023-01-06', '2023-01-06 23:56:40', '2023-01-06 23:56:40', 1);
INSERT INTO `blog_diary` VALUES (1455, 1, '今天稍微搬了几篇文章，是之前的笔记弄到了博客上面，然后家里吃饭上下午都没时间，晚上回来打了打扑克，输了十一块，缺氧造的模块没弄降温措施，感觉还得重新造。', '2023-01-23', '2023-01-23 23:46:40', '2023-01-23 23:46:40', 1);
INSERT INTO `blog_diary` VALUES (1456, 1, '今天没出去，在家休息一天，把该洗的衣服都洗干净了，现在没话说，一天就下棋了，吃饭就开一把，还玩了俩小时gta。se', '2023-07-30', '2023-07-30 23:08:26', '2023-07-30 23:08:26', 1);
INSERT INTO `blog_diary` VALUES (1457, 1, '累了，我怀疑最近可能是三阳，但是没有证据，睡觉。se', '2023-09-12', '2023-09-13 23:05:22', '2023-09-13 23:05:22', 1);
INSERT INTO `blog_diary` VALUES (1458, 1, '今天开会，应该是要准备开发1.1.4的巡检版本了，晚上去推拿，还有王者荣耀比赛，所以今天没跑步。', '2023-08-21', '2023-08-21 23:17:02', '2023-08-21 23:17:02', 1);
INSERT INTO `blog_diary` VALUES (1459, 1, '加班到零点，回家不想睡，稍微打了会游戏。', '2023-12-23', '2023-12-24 02:33:16', '2023-12-24 02:33:16', 1);
INSERT INTO `blog_diary` VALUES (1460, 1, '可算是干完了，今天下班回家十一点多，躺着歇了会起来写日记，最后遗留一个问题是excel点位导入的，因为之前的点位导入是并行的所以有问题，之后要改改。', '2023-11-15', '2023-11-16 00:31:04', '2023-11-16 00:31:04', 1);
INSERT INTO `blog_diary` VALUES (1461, 1, '今天复阳，昨晚一晚上嗓子疼的睡不着，今天上午还能坚持，下午就顶不住了，请假回家，自己做了个核酸检测，确认阳性，睡了一下午，现在稍微好一点了。', '2023-05-25', '2023-05-25 23:38:02', '2023-05-25 23:38:02', 1);
INSERT INTO `blog_diary` VALUES (1462, 1, '昨天还说公司启动不了前端了，没想到今晚重新装了下node，又可以启动了，今天处理巡检的bug，一下子来了八个，好多问题啊，等下周在看，明天上午爬山，等下午或者晚上回来之后先在公司搞搞博客，希望这周就完成文档这块，然后这个版本就基本结束了。', '2023-05-19', '2023-05-20 00:03:22', '2023-05-20 00:03:22', 1);
INSERT INTO `blog_diary` VALUES (1463, 1, 'java环境装起来是真的麻烦，晚上装了几个算是把主要的东西都装好了，还有mysql、redis、nacos，rocketmq等等，可能还得俩个晚上，今晚最后下载node实在是太慢了，一直都是几k每秒。', '2023-12-06', '2023-12-07 00:02:06', '2025-04-29 21:16:51', 1);
INSERT INTO `blog_diary` VALUES (1464, 1, '蒸了一晚上，赶紧睡觉了，今天在公司就整理文档，周一要反串讲。', '2023-10-07', '2023-10-08 00:28:16', '2023-10-08 00:28:16', 1);
INSERT INTO `blog_diary` VALUES (1465, 1, '不早了，我要睡觉，今天因为要放假，在公司也没干啥事情，棒超哥做了个excel表格，崩溃好几个，我重写了好几次，简直无语了。', '2023-04-28', '2023-04-29 00:13:30', '2023-04-29 00:13:30', 1);
INSERT INTO `blog_diary` VALUES (1466, 1, '最近开发好难啊，我以为之前点位这块弄好就不会有其它大问题了，没想到还有高手，太难了。se', '2023-10-24', '2023-10-25 00:08:30', '2023-10-25 00:08:30', 1);
INSERT INTO `blog_diary` VALUES (1467, 1, '昨晚失眠，大概凌晨三点都没睡着，然后今天上午就调休了，但是也没休息好，今晚就早点睡，博客从今天开始做设置功能，今天把界面的工具写的差不多了，最近项目发测了，今天一整天没人找我，也好最近上班休息会，王国之泪玩的是真的上头，每天晚上回来一不注意结束就十二点了，还好今天玩的看时间了，最近肝到了俩块电池，但是一直没找到劳鲁的第五个技能，每次使用都要自己造一次mk2太麻烦了，跑着也挺好用，还有俩块电池不太合适飞一会就掉下来了，王国之泪地下也开50%的图了吧，马上就要结束了，还有点舍不得，先睡觉了。se', '2023-07-24', '2023-07-24 22:31:28', '2023-07-24 22:31:28', 1);
INSERT INTO `blog_diary` VALUES (1468, 1, '今天3080买了一个山地车，下个月搬到杭州郊区，每天上下班骑车，周末也要加强锻炼，今年计划的第一件事已经完成了，然后这个计划的下一步是上班骑行均速要到18km/h，因为还没有实际骑行过，所以第一个目标先给自己定的稍微低一点，今晚打了打王者，电脑刚打开写日记，差不多就这样，还有博客后端管理页面移植也没什么问题，明天下班继续，公司项目开发也很快，感觉这个需求实在是没必要这么长时间，我估计完成之后还能剩俩天时间供我学习，最近这个项目redis和mq都用到了，mq是用已经封装好的方法，和我关系不大，redis是自己百度的1，这个有必要记录下，这个周末应该是要去看新房子，当然搬家也是今天突然决定的，买车也一样，还是因为现在这个房间住的不舒服，阴面还很小，总之就是住的不舒服，想搬家了，租房任性。', '2023-02-20', '2023-02-20 23:09:56', '2023-02-20 23:09:56', 1);
INSERT INTO `blog_diary` VALUES (1469, 1, '昨天主要就是和前端联调bug，改了好几次，现在应该还是有问题，之前业务不熟，现在还算是有些问题吧，但是代码差不多能跑了，我现在也想跑了。', '2024-09-04', '2024-09-05 11:04:48', '2024-09-05 11:04:48', 1);
INSERT INTO `blog_diary` VALUES (1470, 1, '又过了一天，今天面试玩就没办事。', '2024-07-04', '2024-07-04 23:42:36', '2024-07-04 23:42:36', 1);
INSERT INTO `blog_diary` VALUES (1471, 1, '一不小心又晚了，好像最近几天都是零点之后睡觉的。', '2024-02-22', '2024-02-23 00:27:48', '2024-02-23 00:27:48', 1);
INSERT INTO `blog_diary` VALUES (1472, 1, '今天稍微早一点躺下了，具体什么时候睡觉还不确定，说好的今天要学习，但是懒得看了，没啥心情，下午和群友联机玩求生之路，新买的esp8266完整版到了，这个编程还没看要怎么搞，因为我这全套体系都是在我的路由器下面，但是现在路由器还没弄上去，现在也就没法整，可以做的后端开发最近有了新的要开发的功能，但是也不想写，在这个宿舍住的很不舒服，想出去自己租个房间，一个人住着舒服一点，现在也不是很缺钱，周末有时间一个人也看着方便，还想一个人的时候自己做饭，现在在这边吃饭只能点外卖，都是黑色的盒子，吃着就没啥食欲，还有就是今年要配一台电脑，这都年底了，心心念念的40系显卡，当时在杭州的时候就想买了，但是怕离职搬家不方便，就决定到了北京再买，现在到北京了还不能满足自己的这个小愿望，太对不起我自己的，真是自己给自己画饼，我真残忍，想想看能不能抽时间出去联系一个房东，租个差不多的房间。这部分先玩了，刚刚写日记的时候想起来这周周报忘记写了，赶紧出去补上，还好当时写的时候还有九分钟到第二天，给自己省下了五块钱，睡觉，明天还要上班。', '2024-10-27', '2024-10-28 00:04:56', '2024-10-28 00:04:56', 1);
INSERT INTO `blog_diary` VALUES (1473, 1, '和大佬玩七日杀太难了，开了一个超难的mod，一晚上我都死了三十多次，成就直接到手了，简直是噩梦，联机还应该是找萌新玩比较好。', '2024-04-30', '2024-05-01 00:57:02', '2024-05-01 00:57:02', 1);
INSERT INTO `blog_diary` VALUES (1474, 1, '下周一有个面试，感觉公司还算可以，这个周末好好准备。se', '2024-07-12', '2024-07-13 00:05:38', '2024-07-13 00:05:38', 1);
INSERT INTO `blog_diary` VALUES (1475, 1, '喜提周末，这周一定要弄好mqtt这个，其他待定，这周在公司还挺忙的，其实也不能算忙，就是一直有事干，但不是很急。e', '2024-12-27', '2024-12-28 01:07:46', '2024-12-28 01:07:46', 1);
INSERT INTO `blog_diary` VALUES (1476, 1, '昨晚在火车上，周围有一群小孩子，是真吵啊，晚上睡不着，就顺着车厢闲逛，本想着去坐票区看看，结果那边锁门了，不让过去。', '2024-02-14', '2024-02-16 00:23:02', '2024-02-16 00:23:02', 1);
INSERT INTO `blog_diary` VALUES (1477, 1, '今天去公司把显示器带回来了，还有一些垃圾也收拾了下，明天过去是真要开始坐牢了，三天啥事都不用干，但是要坐那，不过好在有工资，最后摸鱼的三天，大华不会是因为我摸鱼导致亏损的吧。', '2024-04-14', '2024-04-15 00:41:14', '2024-04-15 00:41:14', 1);
INSERT INTO `blog_diary` VALUES (1478, 1, '今天周日没投简历，上午去早市买了排骨，也算是早起了，睡了一下午，晚上不怎么瞌睡。se', '2024-05-12', '2024-05-12 23:57:22', '2024-05-12 23:57:22', 1);
INSERT INTO `blog_diary` VALUES (1479, 1, '工资单下来了，这个月工资到手10750，但是没有公积金，公积金要等到转正才会有，今天又忘了给领导发那些文件，明天过去看，然后就是今天主要都在改bug了，明天应该也是改bug，晚上测出来的数据不能根据组织树筛选出了问题还没解决。感觉今天应该是有很多话想写的，但是不知道为啥写不出来，明天再说。', '2024-09-12', '2024-09-13 00:12:38', '2024-09-13 00:12:38', 1);
INSERT INTO `blog_diary` VALUES (1480, 1, '又玩了一天，魂二真的坐牢啊，但是不知道为啥就是想玩。', '2024-04-06', '2024-04-06 21:44:50', '2024-04-06 21:44:50', 1);
INSERT INTO `blog_diary` VALUES (1481, 1, '下午面试了一个外包，感觉面试官就不太专业，问的问题就没水平。', '2024-05-20', '2024-05-21 01:29:48', '2024-05-21 01:29:48', 1);
INSERT INTO `blog_diary` VALUES (1482, 1, '今天好热啊。', '2024-07-20', '2024-07-21 00:46:08', '2024-07-21 00:46:08', 1);
INSERT INTO `blog_diary` VALUES (1483, 1, '今天公司正式放假了，年底绩效考核也出结果了，很不幸我是c，今天年终奖是一毛都没有啊，本以为即使绩效最差也会有五折的年终奖，可惜我高估大华了，你不仁也别怪我不义了，入职说好的十四薪三年了一次都没做到过，今年干脆啥都没，真有你的，我只好摆烂争取下裁员赔偿，24年年后在大华的每一天都要按时下班，不管有任何情况都不会加班，这个是24年在大华的唯一守则，今天学习了51单片机led、按钮开关和led数码管，传感器数据上报也完成了，部署测试正常，不管这个假期的后几天怎么样，至少今天是充实的，上午那会还出去买了一件外套，稍微适当改变下穿衣风格吧，别总一看就是一个傻楞的理科男。', '2024-02-06', '2024-02-07 00:21:16', '2024-02-07 00:21:16', 1);
INSERT INTO `blog_diary` VALUES (1484, 1, '最后决定明天还是直接回家吧，租房子也没啥意思，呆在北京便宜的房子都太破烂了，而且短租的租金也一点都不便宜，还是回家住着舒服，明天上午把被子寄回去，下午准备出发去火车站，之前还想着去看看故宫，还是算了，感觉也没啥意思，一个人消费低一点更好，下一份工作还不知道要找到啥时候。', '2024-11-10', '2024-11-10 22:25:12', '2024-11-10 22:25:12', 1);
INSERT INTO `blog_diary` VALUES (1485, 1, '今天晚上的面试感觉不太行，上来就是问要我写代码，还是有点菜，没写好，其他业务、技术相关的也回答的不太行，最近多认真准备下面试吧。', '2024-03-20', '2024-03-21 00:52:22', '2024-03-21 00:52:22', 1);
INSERT INTO `blog_diary` VALUES (1486, 1, '星舰第四次成功了，再一次见证历史，要是我生在美国就好了，然后家里再有点钱能接受好的教育，可惜人生不能重来。', '2024-06-06', '2024-06-06 21:58:50', '2024-06-06 21:58:50', 1);
INSERT INTO `blog_diary` VALUES (1487, 1, '今天还是改导出表格，没干啥活，但是好累啊。e', '2024-09-20', '2024-09-21 00:15:30', '2024-09-21 00:15:30', 1);
INSERT INTO `blog_diary` VALUES (1488, 1, '今天休息，找超凡出去吃了个饭，第一次去鸟巢，以前都是在电视上看到的。', '2024-10-19', '2024-10-20 00:31:50', '2024-10-20 00:31:50', 1);
INSERT INTO `blog_diary` VALUES (1489, 1, '今天计划没完成，下午过去不想写，勉强做了50%，剩下的文档明天看吧，不过明天想打游戏了，还有该看看单片机，想把mqtt装好，睡觉了吧，不早了。', '2024-01-20', '2024-01-21 00:42:22', '2024-01-21 00:42:22', 1);
INSERT INTO `blog_diary` VALUES (1490, 1, '稍微多玩了半小时，现在一星食物、水电、氧气，啥都不缺了，可以准备挖空全图开二星了。公司项目的那个扫二维码的功能完成开发，明天做一个人员定岗的功能。', '2024-08-06', '2024-08-07 00:37:24', '2024-08-07 00:37:24', 1);
INSERT INTO `blog_diary` VALUES (1491, 1, '昨天补写了前天的日记，然后昨天的日记又忘了，但是昨天也没做啥事情，晚上骑自行车出去转了一会，自行车放那三个月没动都没气了，一直放着估计也快坏了，买又舍不得，放着吧，以后回来就骑一下。', '2024-11-02', '2024-11-03 19:56:58', '2024-11-03 19:56:58', 1);
INSERT INTO `blog_diary` VALUES (1492, 1, '今天开始搬代码，要我出一个计划，然后估一下时间，这个还真有点难度，明天上午做完。', '2024-12-19', '2024-12-19 23:58:14', '2024-12-19 23:58:14', 1);
INSERT INTO `blog_diary` VALUES (1493, 1, '买不到火车票，上班都没心情，所以最近接口文档也不想写。', '2024-01-24', '2024-01-24 23:57:44', '2024-01-24 23:57:44', 1);
INSERT INTO `blog_diary` VALUES (1494, 1, '今天主要还是看数据库，不过这个完全没啥可看的，来来回回数据就那些，看起来还都是造出来的假数据，晚上找领导了解了下系统整体架构，以及我要做的工作，感觉这些都是涉密的数据，而且涉密等级应该不低，要看全国军士的数据，然后旧系统因为缺陷导致数据更新滞后，以及平台数据更新没有和这个在线端平台数据同步，导致数据差异的问题，主要是这俩种情况导致的数据不一致问题，今天还做了政审、犯罪记录、出国记录的好多事情，真有点吓人了，突然参与这么高机密的事情有点一时接受不来，听说过几天还要去客户现场，明天过去主要就先了解新旧系统架构吧，之后也方便梳理下系统，希望之后的数据迁移的工作不会很难。今天就写到这了，晚上十一点才到家，预计接下来一个多月都是这个时间才能回家，虽然最近工作不多，但还是好累啊，好在最近吃饭住宿都是免费的，变相涨工资了属于是。e', '2024-08-02', '2024-08-04 09:53:40', '2024-08-04 09:53:40', 1);
INSERT INTO `blog_diary` VALUES (1495, 1, '今天一天都没弄好数据导入，只要数据导入成功了，其他的事情都是花点时间比对就行，明天休息，在自己电脑上下个人大金仓和Oracle弄一下数据导出和导入，可能跨数据库需要转换下格式，明天再说，今天从部队出来去北海公园走了走，算是今天的一个福利，因为北海公园是收费的，但是从部队过去可以免费，开心。e', '2024-08-10', '2024-08-11 01:36:18', '2024-08-11 01:36:18', 1);
INSERT INTO `blog_diary` VALUES (1496, 1, '周日，爆肝黑魂，太好玩了，已经上头了，一定要白金啊。', '2024-03-24', '2024-03-25 00:14:24', '2024-03-25 00:14:24', 1);
INSERT INTO `blog_diary` VALUES (1497, 1, '又到周末了，这周几乎没投简历，最近可能有点抑郁了，不知道以后该干啥，天天怀疑人生。', '2024-11-29', '2024-11-29 21:47:58', '2024-11-29 21:47:58', 1);
INSERT INTO `blog_diary` VALUES (1498, 1, '现在还在部署博客项目，本以为很快就能弄好，结果现在都好几个小时了还是不行，最开始是docker安装放在脚本里面装完不会自动退出，所以我开始考虑能不能找个安装包，本地安装，但是随便找了一个和我的版本不对，这个只能是有时间慢慢来，先在服务器上测试看，然后再考虑写入脚本，刚刚又出现一个问题脚本还在跑着突然跳出来了，因为进入了docker的容器里面，然后直接中断了脚本执行，需要我自己手动执行，真的服了，怎么这么多问题，这个还没解决又出一个mysql连接问题，不过百度一下解决了，是需要mysql连接公钥的问题，简单修改下替换了服务的镜像文件现在以及可以了，还有一直脚本卡住的问题，直接执行没问题，后台执行就会卡，看日志就是走那没继续下去，现在也不早了，明天晚上回来看吧。手动执行脚本现在以及可以收到树莓派那边发出的心跳了，这样也算是部署成功了吧，先提交一版代码，明天有时间公司看。最近公司项目任务有点多，一个是微件的开发，还有点位导入模板的修改，今天一天努力完成了点位模板的导入导出，本来我给自己估计的时间是三天，没想到一天就完成了，初步调试正常导入导出都可以使用，明天要过去看微件的接口，有个接口很多的微件，不知道明天是要怎么做。服了，说的提交代码，结果着急的直接关机睡觉了，还要再起来提交，好冷啊。提交完成，睡觉。', '2024-02-29', '2024-03-01 01:19:08', '2024-03-01 01:19:08', 1);
INSERT INTO `blog_diary` VALUES (1499, 1, '今天继续修改bug，把机器人的点位校验加上了，明天要讲bug，我这边剩下的都是没办法修改的问题了，晚上新的51单片机回来了，但还是不行，烧录不进去，可能是下载器的问题了吧，晚上找王鹏看也没办法解决，还有我晚上给超凡看问题，发现我这个博客上传文件速度可以，但是下载就很慢了，我的博客真的需要一个oss服务，找时间研究下p2p吧，要是能做一个py的小软件发送文件速度能快不少。', '2024-01-08', '2024-01-09 00:59:40', '2024-01-09 00:59:40', 1);
INSERT INTO `blog_diary` VALUES (1500, 1, '经过一天的努力部署是都正常了，但是有一个无法理解的问题，明明部署成功了，数据库也导入成功了，但是nacos就是获取不到，如果在nacos启动之前我手动查一下数据库那么就可以正常启动nacos，不能理解，还有一个问题，openfeign第一次获取数据也是会请求超时，第二次就好了，这个是单纯的接口流程太慢超时了吗，明天起来继续研究。', '2024-03-08', '2024-03-09 00:25:06', '2024-03-09 00:25:06', 1);
INSERT INTO `blog_diary` VALUES (1501, 1, '假期结束了，虽然我没有，明天就不九点之前去了，稍微晚点过去，反正也不能早下班，今晚还是在魂二迷路，感觉魂二地图是真的不如魂一，迷路了真的不知道去哪，还有也没有像魂一那样的捷径可走，可能是一开始就因为加入传送了吧，我觉得还是带上跑图更有意思，怪稍微少点就好了。', '2024-10-07', '2024-10-08 00:04:18', '2024-10-08 00:04:18', 1);
INSERT INTO `blog_diary` VALUES (1502, 1, '离职的赔偿协议签完了，离职申请也填好了，每天调休一天，然后再回去上班到下周三之后就是自由的假期了，突然就感觉焦虑了，不过好在焦虑是焦虑，但没有压力，没有收入来源但好在有点存款，先回家慢慢找工作吧，下一步干嘛慢慢考虑，已经和刚来杭州那会不一样了，还记得刚到杭州中午特别热，还特别闷感觉空气都是潮湿的，呼吸都费劲，那时候兜里就带着北京打工攒下的五千块钱，还给同学借出去点，第一个月房租都是拖工资发下来才补交的，眨眼间这都三年了，今天大概算了下现在身上有26w左右现金吧，公积金6w多，下个月的十号会发裁员的4.64w赔偿，还有这个月上班到17号的工资，应该能发个5w吧，焦虑是有的，但是有钱就是不一样啊，我要是现在还没有存款回家之后睡觉都不踏实了，希望俩个月可以找到工作，然后今年换一台电脑，之后想要剪剪视频，发点游戏相关的，也不是为了争那点视频收益，最好可以找几个爱好相同的小伙伴一起玩游戏，也不至于现在打游戏联机都找不到人，要是想联机好像可以发小黑盒，今年也慢慢开始使用这类社交软件了，感觉还行吧，希望我可以不再这么社恐。', '2024-04-10', '2024-04-11 00:15:12', '2024-04-11 00:15:12', 1);
INSERT INTO `blog_diary` VALUES (1503, 1, '又活了一天，明天出去。', '2024-06-29', '2024-06-30 00:06:42', '2024-06-30 00:06:42', 1);
INSERT INTO `blog_diary` VALUES (1504, 1, '忙碌一下午总算是把新版的博客部署好了，新版的博客把之前文档不登陆无法登陆的问题修复了，其实在很久之前这个问题就修复了，但是一直没时间部署博客，今天花了一下午的时间算是整体部署好了，因为这次更新修改了一些配置相关的代码，导致这次部署错误还挺多的，主要问题有三处吧，首先就是docker的部署这个上次部署的时候阿里云的镜像不能用，这次部署就没有这个问题，但还是因为使用了上次部署的脚本，失败一次，然后就是树莓派和云服务器上部署都普遍存在的问题，因为win和linux系统存在一个字符的问题需要转换字符，这个也卡了挺长时间的，然后就修改了部署的脚本，加上了字符转换的命令，我记得之前好像就使用过notepad切换过字符格式，但这个印象实在是不深，而且操作复杂，还很容易忘记，这次改完应该就不会有这个问题了，云服务器的整体打包部署算是完成了，树莓派这个暂时不想格式化重新打包，因为最近用树莓派的镜像工具按照我之前的操作流程弄出来的系统好像不太一样，前几天弄树莓派机顶盒测试出来的，也幸好发现了这个问题，不然要是树莓派被格式化了又短时间弄不好，真就亏大了。另外就是今晚QQ群里找的大佬来帮忙看stm32通过esp8266连接mqtt的这个问题还是没弄出结果，现在我都花钱请人看了还是没一点进度，或者明天就再找一个大佬吧，接下来就开始整理一些文章，上一份工作等这样的数据。', '2024-12-07', '2024-12-07 23:20:48', '2024-12-07 23:20:48', 1);
INSERT INTO `blog_diary` VALUES (1505, 1, '昨天又忘了写日记，因为是就住招待所了，没回去，最近应该是就在招待所这边了，偶尔几次可以就住这儿的宾馆，可能是因为不习惯，昨天没睡好。', '2024-08-29', '2024-08-30 13:13:30', '2024-08-30 13:13:30', 1);
INSERT INTO `blog_diary` VALUES (1506, 1, '旧版的dnf算是毕业了，然后群里搞了一个70版本，这个看上去要做的东西有好多，应该要打很久，明天优先准备面试。', '2024-06-10', '2024-06-11 00:34:12', '2024-06-11 00:34:12', 1);
INSERT INTO `blog_diary` VALUES (1507, 1, '明天可算是可以休息了，上午睡个懒觉，下午有精神就看看那个舵机吧，一直不能控制好角度。', '2024-09-27', '2024-09-28 00:13:36', '2024-09-28 00:13:36', 1);
INSERT INTO `blog_diary` VALUES (1508, 1, '博客设备相关的页面至少是能看了，切换也正常，明天主要写docker脚本和学习51吧。', '2024-02-10', '2024-02-11 00:23:54', '2024-02-11 00:23:54', 1);
INSERT INTO `blog_diary` VALUES (1509, 1, '今天第二次和面，比上次熟练不少，投简历继续碰壁，马上五一了，又能有理由的玩几天。', '2024-04-29', '2024-04-30 00:22:16', '2024-04-30 00:22:16', 1);
INSERT INTO `blog_diary` VALUES (1510, 1, '今天没有开发新的功能，昨天就把同步文件这块做好了，只是没测试，今天过去学习了spring的aop切片，还学会了创建自定义注解，真的是大进步啊，之前一直想学，但是不知道怎么下手，也可能之前的水平不够，今天在公司的项目里面学到了，还有把博客的校验错误统一定义返回了，也是一个大进步，因为这个也新增了不少工作量，按照开发、校验、bug各占三分之一来算新增了起码一个月的工作量，完善校验这个不着急，一步一步来，之后接口文档规范化也要开始了，整理好文档，以后修改起来也很方便，这么看博客写文章或者写文档需要一个模板功能，我是真会给自己找事干，才刚刚把功能开发完成，现在又想到了新的主意，不过这个暂时还不能开发，至少要先把硬件的一些传感器玩明白再说吧，现阶段传感器还是只有json数据，要是能做到把视频拉流弄上来那就真的是nb了，简直是抄袭公司的功能，完了我再加一个巡线小车定时巡检家里，挂个摄像头巡检家里的点位，再弄上温度异常报警，无人报警，陌生人报警，我都笑了，草，要是有这个实力一定要做，不然白呆大华这么久了，明天去找王鹏看看硬件问题，睡觉了，今晚没什么精力打游戏，躺着看了会动漫。', '2024-01-12', '2024-01-13 00:26:18', '2024-01-13 00:26:18', 1);
INSERT INTO `blog_diary` VALUES (1511, 1, '今天去电信营业厅恢复公司的手机卡，但是需要我带身份证，所以明天过去看看吧。se', '2024-03-12', '2024-03-12 23:07:42', '2024-03-12 23:07:42', 1);
INSERT INTO `blog_diary` VALUES (1512, 1, 'md，放假了但是一点没有休息，看这些动漫真上天。', '2024-11-17', '2024-11-18 02:26:06', '2024-11-18 02:26:06', 1);
INSERT INTO `blog_diary` VALUES (1513, 1, '数据同步的任务差不多也算是完成了，明天开始了解整个系统的架构，然后开始写技术文档，应该是部署服务的流程吧，要是这个文档是我写的，那这个现场以后要是有问题以后可都要我过来解决问题了，今天还算下班较早，九点左右回来的，晚上继续缺氧，食物的模块差不多完成了，然后开始挖空岩浆区，好在冰霜星岩浆都结块了，直接真空挖进去也不会有太大问题，之后就再不会缺电了，上面还有俩组火山，一并都开发了，要出常温火成岩，亏点电也没啥大问题，今天就这样，后续的博客开发计划今天也做好了，现在就等租房，买电脑，来上班快一个月了甚至还没去过公司。', '2024-08-22', '2024-08-23 00:40:46', '2024-08-23 00:40:46', 1);
INSERT INTO `blog_diary` VALUES (1514, 1, '前台也就是周四，晚上坐飞机赶往杭州，到了宾馆都已经十二点多了，所以就没开电脑，昨天也有事情就到今天来补一下日记，周四大概是下午四点的火车，然后坐火车赶往太原，到了太原接着就继续去飞机场，第二次坐飞机但是才花了三百多，差不多就是火车卧铺的价格，因为是淡季加上是晚上的飞机所以才便宜，去了火车站称行李重量，刚好是19.4公斤，差一点点就要超重了，然后检查行李的时候充电宝没取出来，在检查之前我还检查了一次，打开行李的时候没摸到充电宝，还以为是忘带了，然后就是不知道飞机是在哪个航站楼起飞，就默认是T1，过去托运行李的时候才发现走错了，还好我每次都留足了时间，走到T2航站楼倒是时间也充足，坐飞机感觉还是很爽的，起飞的时候那一下超重的感觉，推背感极强，要是飞机能便宜点我每次回家都坐飞机回去，这次的飞机是晚上的飞上去啥也看不见，而且我也是坐在过道那一边，啥也看不见，真希望下次有机会坐飞机的时候能买到靠窗的位置，到了杭州住的宾馆还有接机服务。不得不说这92块钱花的太值了。e', '2024-12-12', '2024-12-15 00:43:18', '2024-12-15 00:43:18', 1);
INSERT INTO `blog_diary` VALUES (1515, 1, '24年结束了，今年换了俩份工作，目前这个还是很满意的，工作时间很舒服，出差也不用租房，搞错了，这个应该是日记，年终总结过几天写，今天把ESP的测试接口用例写完了，然后因为明天是元旦，所以休息一天，计划明天继续看stm32，真难搞啊，就一个连接mqtt就弄了这么长时间，然后树莓派的这个软件好像真有问题，今天新回来一张内存卡也是烧录失败，然后再用一次就提示卡坏了，所以算是在拼多多白嫖了一个读卡器，最近在看一个动漫，名字没记住，感觉还不错，最后三集了，一会睡觉前看完，2024年再见。', '2024-12-31', '2025-01-01 00:02:28', '2025-01-01 00:02:28', 1);
INSERT INTO `blog_diary` VALUES (1516, 1, '有点怀疑了。', '2024-06-22', '2024-06-23 00:28:08', '2024-06-23 00:28:08', 1);
INSERT INTO `blog_diary` VALUES (1517, 1, '一下午都在对数据，这个看的眼睛疼，剩下六千多条数据，应该是明天过去对完就可以下班了吧，不对，明天是周日，我过去又是加班，应该是对完我就正常可以走了。晚上回来把不死灵庙也探索完成了，现在好像没地方可以去了，之前有俩个门需要王者之证，明天回来之后继续打，感觉一周目快结束了，本体快结束了，还有三个dlc。', '2024-10-12', '2024-10-13 00:49:34', '2024-10-13 00:49:34', 1);
INSERT INTO `blog_diary` VALUES (1518, 1, '今天没收到面试。', '2024-07-08', '2024-07-09 00:10:26', '2024-07-09 00:10:26', 1);
INSERT INTO `blog_diary` VALUES (1519, 1, '回村，没开电脑。', '2024-05-08', '2024-05-11 23:29:10', '2024-05-11 23:29:10', 1);
INSERT INTO `blog_diary` VALUES (1520, 1, '今天睡醒就中午了，一天也没心情写代码，下午缺氧，晚上玩黑魂，好久没玩然后就被暴虐了。se', '2024-09-08', '2024-09-09 00:35:06', '2024-09-09 00:35:06', 1);
INSERT INTO `blog_diary` VALUES (1521, 1, '收到了第一个面试，约的是明天下午四点，先看一下吧，对方公司不是外包，做的也是门禁相关，可以试试。', '2024-04-22', '2024-04-23 00:57:16', '2024-04-23 00:57:16', 1);
INSERT INTO `blog_diary` VALUES (1522, 1, '今天早点关电脑吧，这个房间现在我妹放假了回家住，这都月底了还没消息，我真的是服了，好像是我借了别人钱一样，完全没一点重视的意思。', '2024-11-30', '2024-11-30 21:34:08', '2024-11-30 21:34:08', 1);
INSERT INTO `blog_diary` VALUES (1523, 1, '自从来了北京每天上班都非常疲惫，不知道是什么原因，有时候去了上班一天也没什么事情，一整天就坐那思考人生，然后也是晚上到宿舍之后心累，就是想躺在床上一动不动，是因为我不适合北京工作吗，这感觉和当时在北京实习的时候没啥区别，整天都是上班如上坟，可能是因为每天都是俩小时通勤时间吧，赶紧找下一份工作离职吧，现在这边真的感觉呆不下去了，马上就开始二期开发，到时候四个系统还要在十二月那会上线，之后通宵肯定是少不了的，抓紧这几天面试找工作，每天有俩场面试，上午十点的是北京工作，百度好像的外包性质的类型，然后下午一点半有一个杭州的面试，这个感觉公司挺好的，自研项目，还带一点物联网限制，这种类型的工作我挺喜欢的，主要我也喜欢这些单片机的设备，但是这个需要现场二面，和面试那边说的是可以考虑二面去杭州，但是我肯定不可能过去，一直找工作都是线上找好然后直接去上班，这个现场面试过去万一挂了成本太大了，这边假都不好请，再加上路费和时间，不如试试其他的工作，晚上起来看了一下面试题，也就是字面上说的看了一下，鼠标最近感觉不好用了，滚轮带点漂移，总是不能滚到指定位置，再坚持一段时间，找到新工作再换吧，今晚先睡觉了。', '2024-11-05', '2024-11-06 00:03:56', '2024-11-06 00:03:56', 1);
INSERT INTO `blog_diary` VALUES (1524, 1, '离职第一天，md还挺爽，明天准备搬家，然后准备找工作和继续测试博客已经做好的功能。', '2024-04-18', '2024-04-18 23:41:24', '2024-04-18 23:41:24', 1);
INSERT INTO `blog_diary` VALUES (1525, 1, '今天去了北海北的一个军区，看门口管控好严格，还要报备，未来一周应该都会在那边上班了，还有刘总和我一起去，主要就是数据迁移，今天给我任务就是核对组织树，把俩边不一样的数据整理出来，看军区的组织好复杂，要整理只能是依靠工具来比较了，下午我还准备用excel整理一个表格呢，等整理出来起码半个月，看的眼睛都花了，明天还是去那个军区会议室。', '2024-08-09', '2024-08-09 23:59:48', '2024-08-09 23:59:48', 1);
INSERT INTO `blog_diary` VALUES (1526, 1, '这几天都没继续投简历，最近约的面试都是上周约好的，明天要开始认真准备了，之前给offer的南京华苏这个不打算去，一是因为外包，再就是因为试用期时间太长了，所以我还是再找找其它的工作吧，反正这个这么快就给了offer算是给了我自信，之后就学习下单片机，博客今年也要继续写了，年底把新版的设备功能这个版本发布了。', '2024-11-13', '2024-11-14 01:28:50', '2024-11-14 01:28:50', 1);
INSERT INTO `blog_diary` VALUES (1527, 1, '缺氧二星差不多完成了。', '2024-11-22', '2024-11-23 02:14:42', '2024-11-23 02:14:42', 1);
INSERT INTO `blog_diary` VALUES (1528, 1, '昨天的缺氧档算是彻底放弃了，不过新开的档今天爆肝一天也150周期了，这个新档就慢慢玩吧，我是指游戏进度，我这爆肝程度确实厉害，下午有想法看博客，然后因为没上去网站就算了，博客新功能的开发这个至少也要等到现在这个项目结束，双休之后，我再买个电脑，租好房子之后吧。我的4070还没想好其他配件要买什么样子的，不过今年肯定是要买的。se', '2024-08-18', '2024-08-19 00:21:10', '2024-08-19 00:21:10', 1);
INSERT INTO `blog_diary` VALUES (1529, 1, '抢了一天服务器都没抢到。', '2024-06-25', '2024-06-26 00:29:24', '2024-06-26 00:29:24', 1);
INSERT INTO `blog_diary` VALUES (1530, 1, '今天收到一个杭州的面试，还是觉得北京工作不舒服，能在杭州找一个工作也挺好的。', '2024-10-31', '2024-11-01 00:31:12', '2024-11-01 00:31:12', 1);
INSERT INTO `blog_diary` VALUES (1531, 1, '明天小周，过去写博客吧，总之是不可能干活的。', '2024-03-01', '2024-03-01 23:49:48', '2024-03-01 23:49:48', 1);
INSERT INTO `blog_diary` VALUES (1532, 1, '今晚打的黑魂真憋屈，为了救圣女把那个圣骑士杀了，结果因为那个圣骑士还没下手，导致圣女见面就打我，烦呐。', '2024-03-27', '2024-03-27 23:53:12', '2024-03-27 23:53:12', 1);
