INSERT INTO `blog_diary` VALUES (1534, 1, '今天没干啥事情，晚上也不知道干啥了突然就过去了，上午搭建好了app的开发环境，下午出去骑车，三十公里吧，休闲骑。se', '2024-01-28', '2024-01-29 00:30:04', '2024-01-29 00:30:04', 1);
INSERT INTO `blog_diary` VALUES (1535, 1, '三国杀排位真难打，一晚上上不了几颗星。', '2024-05-19', '2024-05-20 00:02:18', '2024-05-20 00:02:18', 1);
INSERT INTO `blog_diary` VALUES (1536, 1, '今天开始整理接口，感觉这个任务看着没多少，写起来是真慢啊，还好上周五做了一点，不然今天的是真的写不完。', '2024-12-23', '2024-12-24 00:17:56', '2024-12-24 00:17:56', 1);
INSERT INTO `blog_diary` VALUES (1537, 1, '今天面试一个感觉还行，晚上开始学习stm32，之后的单片机都用stm32做了。', '2024-07-24', '2024-07-25 00:56:38', '2024-07-25 00:56:38', 1);
INSERT INTO `blog_diary` VALUES (1538, 1, '今天去工行去修改银行卡信息，跑了第一个是因为周末没有营业，第二个过去了准备改预留信息发现没带身份证，返回又骑车回来拿上身份证，再过去所有东西都准备好了，然后发现银行卡上突然多了四万块，然后打印出交易记录才想起来这个是我上个公司的银行卡，真的是无语了，正好趁这个时间算一下现在有多少钱，微信：40047.21，支付宝：123741.35，招商银行：164892.30，工商银行：47560.88，杭州公积金：54330.65，算了一下总共有430572.39，有四十万了，就算不加公积金也有37w，好像攒够30w和40w都没有当时攒到第一个1w和第一次攒到10w那会有活力了，现在我也对这个钱没太大概念，就知道是越多越好，反正还是继续攒吧，明天去出差的地方上班，今天下午就已经去过一次了，步行大概要走三十分钟，明天8点15出门就可以。e', '2024-12-15', '2024-12-15 23:31:14', '2024-12-15 23:31:14', 1);
INSERT INTO `blog_diary` VALUES (1539, 1, '早上去了招待所，结果要我去中心，然后又赶到中心，中间顺便回了一下家，到了就十一点了。在中心也几乎没我啥事，就在那看着，我这主要弄一个数据同步，现在也没问题了，还测试了定时的数据同步，都没问题，顺便还改了一个bug，明天希望不要去中心了，自己的电脑都用不上。e', '2024-09-19', '2024-09-20 00:10:42', '2024-09-20 00:10:42', 1);
INSERT INTO `blog_diary` VALUES (1540, 1, '相比手游dnf，还是端游更好玩，而且手游都没我最喜欢的奶爸。', '2024-05-28', '2024-05-29 00:24:18', '2024-05-29 00:24:18', 1);
INSERT INTO `blog_diary` VALUES (1541, 1, '明天还是小周，春节前最后一个了，要准备回家过年了。e', '2024-01-19', '2024-01-20 00:55:56', '2024-01-20 00:55:56', 1);
INSERT INTO `blog_diary` VALUES (1542, 1, '总算是放假了，今天上午还在招待所忙了一上午，下午回家躺了一会，然后出门随便走走，明天上午写写代码，想赶紧弄好这个硬件设备，下午出门闲逛去，有点想去洗脚去，第一次尝试，也不知道明天有没有勇气去。', '2024-09-15', '2024-09-15 23:40:48', '2024-09-15 23:40:48', 1);
INSERT INTO `blog_diary` VALUES (1543, 1, '画了一天的图，还好是完成了，差最后几个漏了的问题不大，明天上午一会就补完了，最近不知道改开发啥功能，没灵感了，之前很多突发奇想可以做一些有趣的功能，拿最近就专心优化吧，优化和写文章总结为主。se', '2024-04-02', '2024-04-03 00:01:06', '2024-04-03 00:01:06', 1);
INSERT INTO `blog_diary` VALUES (1544, 1, '最近好像不是很忙了，晚上都可以八点下班了，今天是因为有点事情，我就等到了九点下班，晚上回家继续黑魂二，dlc难度确实有点高，boss和小怪都是太肉了，玩法师根本打不动，只能靠技能一点一点耗血量，dlc3今天好不容易打死boss，然后要我再跑一次图，当时我也不知道怎么想的，打完boss没想着消费一波，直接去了下一个雾门，然后就寄了，7w魂全没了，不然可以生几级再开一个技能格子。', '2024-10-16', '2024-10-17 00:33:20', '2024-10-17 00:33:20', 1);
INSERT INTO `blog_diary` VALUES (1545, 1, '今晚住招待所了，晚上状态不错，把前端页面调整了很多，现在应该可以测试部署了，就是设备控制这块还不行。', '2024-09-23', '2024-09-24 00:50:10', '2024-09-24 00:50:10', 1);
INSERT INTO `blog_diary` VALUES (1546, 1, '今天也是休息了一天，上午醒了就已经十一点了，下午吃饭后又睡到了五点，应该算是休息够了吧，连上这么长时间真的身体受不了，今天魂二算是本体都打完了，之后开始玩dlc的内容，不过dlc3我也已经打完了，就剩俩个dlc，没多久就一周目结束了，之后就准备做全成就。', '2024-10-20', '2024-10-20 23:56:58', '2024-10-20 23:56:58', 1);
INSERT INTO `blog_diary` VALUES (1547, 1, '上午面试了一个都是在问业务细节，感觉我回答的还算可以吧，不知道最后啥结果。se', '2024-05-23', '2024-05-23 23:11:46', '2024-05-23 23:11:46', 1);
INSERT INTO `blog_diary` VALUES (1548, 1, '一天烦死了，下午请假没去公司，本来就是周末还要请假，emo的一天，怀疑自己了。', '2024-03-16', '2024-03-17 00:29:52', '2024-03-17 00:29:52', 1);
INSERT INTO `blog_diary` VALUES (1549, 1, '国庆快过半了，今天突然想到给所有传感器加个开关，然后传感器模板控制应该给每个模板加一个唯一码，不然我数据映射到模板时对应不上，给所有传感器加一个开关我还想真给这个设备断电，但是一个单片机不能接太多传感器，现在想法是加个类似编码器的开关，就可以用一个针脚控制多个传感器，而且还可以实现对传感器断电的操作，但是这个想法我都找不到该买什么设备，可能一个编码器就好了吧，然后通过晶体管控制传感器是否供电，原理上应该是可行的，就是怎么给编码器控制，而且还要对接上单片机，应该是有点难度的，暂时没时间搞，不早了，睡觉了。e', '2024-10-03', '2024-10-04 00:06:10', '2024-10-04 00:06:10', 1);
INSERT INTO `blog_diary` VALUES (1550, 1, '今天的面试估计都凉了，好心累啊，还得被多少面试题，每次都能给我整出新的知识点。', '2024-07-16', '2024-07-16 23:07:30', '2024-07-16 23:07:30', 1);
INSERT INTO `blog_diary` VALUES (1551, 1, '今天的日记写的好早，写完躺下玩会手机吧，下午优化了一下web页面的展示，想着部署完成把服务器上的包也换一下，但是docker部署下载emqx实在是太慢了，我都等了一个多小时还没好，可能就是几k几k的下载，等不及了，睡觉，每天早上可能会看看有没有下载好。', '2024-02-25', '2024-02-25 21:47:14', '2024-02-25 21:47:14', 1);
INSERT INTO `blog_diary` VALUES (1552, 1, '今天面试的这个不走寻常路，问了好多之前都没记过的知识点，还好大概都回答了，没有直接一句话都说不上的。', '2024-06-14', '2024-06-15 01:19:30', '2024-06-15 01:19:30', 1);
INSERT INTO `blog_diary` VALUES (1553, 1, '开始做下周要讲的ppt，就做了一个开头，明天一整天优先做ppt，我讲的主要是模型同步，今天把之前写的环境搭建流程放到ppt上面，明天就画几个图吧，主要就是讲同步的流程，真要说也没啥可讲的，就是项目做的大了，开发的时候动已有功能就是容易引起一些位置问题，今天下班又出现一个，看日志是数据库的问题，但是不止一个环境，应该不会是代码的原因吧，不然怎么能发测的。晚上回家买了一个温度传感器，这周应该就可以学习51单片机，分俩个阶段吧，第一步是先连接好传感器，把数据读取数出来，第二步就是通过网络把数据传到我的树莓派上，第一次做啥都不懂，可能会花不少时间，希望可以通过http协议把数据传出了。晚上继续缺氧，二星把挖全图脚手架都拆干净了，现在挂机整理碎片，今晚是弄不完了，先睡觉了。再记录下博客进度吧，今天也是几乎一整天开发，进度没多少，主要是思考怎么做文件同步功能，现在的解决方案是创建同步的目录，然后这个目录下所有数据都是需要同步的，同步之后在服务器上不删除这个目录和文件的信息（因为之前写的每次查询目录会比较服务器上实际文件与数据库文件，对比保证数据正常，如果不做特殊处理就会把同步的文件或者目录清除）接口简单的测试是正常的，现在就是不知道界面怎么做好看一点，得加点图标吧，我现在虽然能用但是有点太寒酸了，还要给目录加一个同步目录的tag，感觉还是前端比较难一点。', '2024-01-04', '2024-01-05 00:20:44', '2024-01-05 00:20:44', 1);
INSERT INTO `blog_diary` VALUES (1554, 1, '今天感觉也不错，因为今天要放松、打游戏，所以就没做太多事情，但是今天第一次调试WeMos D1板子，测试成功了，连接mqtt、wifi和温湿度都正常，数据也可以正确上报到mqtt上，所以现在的情况就是可以把家里的数据上报到服务器了，至少流程是走通了，下一步要调试接收mqtt数据，实现从服务器控制家里的设备，最近做的真是一天比一天有希望，最终我是不是要画一个板子啊，然后在画的这个板子上做家里的电源总控开关，想法是家庭供电全部来自太阳能，然后太阳能充电接充电宝，不知道充电宝要不要做双电池，边充电边放电可以会有隐患吧，在做一个电池充电的模块用来给家里其他地方的单片机供电，毕竟不能家里四处接线吧。今天下午把gta5故事模式打完了，感觉确实完美啊，而且今天下午电脑很给力，全程80帧，是不是因为家里冷，散热好，所以性能跟上了，睡觉了，明天还要去医院，嗓子不舒服，一直都是有异物感，俩年了吧，去医院之前也是说没啥事，再看一次吧，反正医保报销，然后保险还能再报销。', '2024-01-21', '2024-01-22 00:20:30', '2024-01-22 00:20:30', 1);
INSERT INTO `blog_diary` VALUES (1555, 1, '今天开发兵员信息上报的功能，业务有些绕，好在最好还是理清楚了，明天过去争取一口气做完，然后就开始摸鱼，等周一再开始测试，今天睡觉吧，明天是周六还得去上班，这一个月真是压力到位了。', '2024-08-30', '2024-08-31 00:29:14', '2024-08-31 00:29:14', 1);
INSERT INTO `blog_diary` VALUES (1556, 1, '今天出去打算租个房子在北京多呆几天，但是去了城中村发现还是老实回家吧，虽然可能回去让父母担心，不过这次回去作息规律点，面试题也认真准备下还是可以的吧，下午和晚上都是找超凡散步，我可能离职之后还是会继续焦虑，毕竟我这个人就是这样的，上班996每天生不如死，失业又焦虑没有收入来源想找个班上，我遇到的就没有不加班的工作吗，一直都是让我这样当个卷王，还卷不过别人，现在也有四十万了，接下来准备学习也继续整理面试题，找到工作就过去上班，找不到就当是休息了吧。', '2024-11-09', '2024-11-10 00:08:46', '2024-11-10 00:08:46', 1);
INSERT INTO `blog_diary` VALUES (1557, 1, '一日无事，真的舒服啊，明天开始准备继续投简历了。', '2024-05-04', '2024-05-05 00:14:18', '2024-05-05 00:14:18', 1);
INSERT INTO `blog_diary` VALUES (1558, 1, '今天实在是太冷了，晚上游戏也不想玩，回去躺床上看动漫去了，明天上午有一个面试。se', '2024-11-26', '2024-11-28 00:05:22', '2024-11-28 00:05:22', 1);
INSERT INTO `blog_diary` VALUES (1559, 1, '被通知裁员之后现在都没心情干活了，反正我也呆不了几天了，问题单谁爱看谁看，我按时上下班就好了，这几天就摸鱼写写笔记，然后把各种能变现的都换出来，不能便宜了公司，今天下班回家也懒得打游戏，我觉得还是需要休息了，一直上班生活都没意思，接下来投简历和总结笔记学习一起进行，可能回家之后还想学习硬件相关的，但是硬件这个不着急可以学，但是不能花太多时间，现在已Java为主，找工作还是最优先的，差不多写完看看动漫吧，下周三回家，飞机火车都行，机票六百以下我都可以接受。', '2024-04-09', '2024-04-09 22:33:22', '2024-04-09 22:33:22', 1);
INSERT INTO `blog_diary` VALUES (1560, 1, '熊猫头动漫还挺有意思，看到了现在。', '2024-04-26', '2024-04-27 01:34:52', '2024-04-27 01:34:52', 1);
INSERT INTO `blog_diary` VALUES (1561, 1, '昨晚忘了写日记就睡觉了，最近公司的项目要开始测试了，不过应该是打算以后让我接手这个项目的环境搭建和部署，所以我最近一直是在中心这边，昨天开始写的交换区的环境搭建，感觉主要还是配置这块东西多，就组件部署，搭建完成可以执行没太多复杂，今天过去开始看专网区的环境搭建，这个都不用命令行了，直接上梯度云可视化界面打包镜像开始部署，上午先去招待所，要不今天带上电脑吧，昨天开始继续修改博客，整理了netty这块的代码，现在看着就舒服多了，在中心那边经常晚上我就没啥事情了，一个人想博客怎么修改，笔记都写四页了，之前传感器收集的数据就不要了，新的单片机主板使用stm32，配件慢慢再选择。se', '2024-08-26', '2024-08-27 08:08:36', '2024-08-27 08:08:36', 1);
INSERT INTO `blog_diary` VALUES (1562, 1, '玩了一天，明天有俩场面试。', '2024-12-04', '2024-12-05 00:33:22', '2024-12-05 00:33:22', 1);
INSERT INTO `blog_diary` VALUES (1563, 1, '昨天回家不知道为啥很累，晚上没看电脑，最近晚上下班都挺早的，去军委那边每天都可以早点开溜，回家也就八点左右。', '2024-08-13', '2024-08-14 23:01:52', '2024-08-14 23:01:52', 1);
INSERT INTO `blog_diary` VALUES (1564, 1, '玩了一天缺氧，今天小屏幕好像要坏了，所以把大屏装出来了。se', '2024-07-21', '2024-07-22 01:37:22', '2024-07-22 01:37:22', 1);
INSERT INTO `blog_diary` VALUES (1565, 1, '心情不好，啥都不想干，好烦啊。', '2024-02-05', '2024-02-05 23:00:12', '2024-02-05 23:00:12', 1);
INSERT INTO `blog_diary` VALUES (1566, 1, '玩了一天三国杀，真爽，饥荒每日礼盒都忘记开了。e', '2024-05-21', '2024-05-22 00:44:38', '2024-05-22 00:44:38', 1);
INSERT INTO `blog_diary` VALUES (1567, 1, '明天继续面试。', '2024-05-05', '2024-05-06 01:46:10', '2024-05-06 01:46:10', 1);
INSERT INTO `blog_diary` VALUES (1568, 1, '到明天就刚好毕业三年了，还没找到工作。', '2024-07-05', '2024-07-06 01:07:14', '2024-07-06 01:07:14', 1);
INSERT INTO `blog_diary` VALUES (1569, 1, '今天没投简历，第一天开始整理印象笔记，其实也投了几个简历，只不过后来反应过来今天是周日，大家都放假了，下午没想到璐瑶找我，她想去苏州，但是五一假期去了那不是没事找事吗，人最多的时候，火车票都不好买，最后应该是决定不去了，有这时间不如准备考驾照。', '2024-04-21', '2024-04-22 00:24:20', '2024-04-22 00:24:20', 1);
INSERT INTO `blog_diary` VALUES (1570, 1, '今天参加了一场线上面试，问题主要是业务相关的，感觉回答还行吧，一些概念的问题没答上来，最近dnf确实有点上瘾，真好玩。se', '2024-02-21', '2024-02-22 00:41:10', '2024-02-22 00:41:10', 1);
INSERT INTO `blog_diary` VALUES (1571, 1, '周五躺了一整天，当个废物的感觉还挺不错的，可以我还不能躺平，至少我得给父母养老，今天躺床上看视频，发现一个很有趣的up，然后我就下载了抖音关注了这个up。叫牛仔和他的影子，文采真好，我都写好几年日记了完全没有人家的水平，可能这就是天赋吧，不过他的经历也很让人痛心，十几岁的时候就成了孤儿，现在都流浪七八年了吧，走过很多城市，打过各种各样的零工，活着还真是痛苦，但又不能去结束，无论如何都要去尽力活下去，要是有机会真想给他一点帮助，随然我和流浪汉差距也不是很大，以后我打概也会流浪吧，至少不能让父母看到我以后的狼狈样子。今天有点多愁善感，写的多了点。', '2024-11-01', '2024-11-02 01:19:30', '2024-11-02 01:19:30', 1);
INSERT INTO `blog_diary` VALUES (1572, 1, '三号回家就十一点半了吧，昨天也回去没开电脑，今天不上，周二没和前端测试，但是有一堆bug要改。se', '2024-09-03', '2024-09-05 11:04:54', '2024-09-05 11:04:54', 1);
INSERT INTO `blog_diary` VALUES (1573, 1, '总算是把stm32连接mqtt弄好了，原来是因为波特率错了，改到了115200现在可以连上我的mqtt服务器了，然后今天在上班看代码的时候看到了可以把配置文件的一些配置信息弄到打包文件配置里面，晚上调试了老半天都没好，我都差点奔溃了，最后原因是pom文件中没有资源配置加上，反正测试了很多次，可算是弄好了，明天过去要搬代码，先看网格这块核心的功能。e', '2024-12-18', '2024-12-19 00:24:06', '2024-12-19 00:24:06', 1);
INSERT INTO `blog_diary` VALUES (1574, 1, '昨天的日记，因为搬家，东西搬完都一点半了，感觉没多少，但是好多大件一次就能搬一俩个，最后就懒的写了。', '2024-03-23', '2024-03-25 00:13:42', '2024-03-25 00:13:42', 1);
INSERT INTO `blog_diary` VALUES (1575, 1, '今天还行，下午投了简历，明天继续，等找到工作之后认真写日记吧，每天在家就是下棋、dnf。se', '2024-06-03', '2024-06-04 10:45:36', '2024-06-04 10:45:36', 1);
INSERT INTO `blog_diary` VALUES (1576, 1, '今天面试又给我鸽了，真服了这个电话面试的，明天要整理下家里了，周末都要回来。', '2024-11-28', '2024-11-28 23:33:56', '2024-11-28 23:33:56', 1);
INSERT INTO `blog_diary` VALUES (1577, 1, '明天上午十点有个面试。', '2024-07-03', '2024-07-04 00:10:40', '2024-07-04 00:10:40', 1);
INSERT INTO `blog_diary` VALUES (1578, 1, '又到周一了，今天把arduino读取温湿度传感器的做好了，也可以拿到数据，对接esp8266的时候有点问题，下载不到需要的包，没开发过硬件，真不知道怎么处理，晚上资料好多都是默认安装好了，晚上一直玩缺氧。se', '2024-01-07', '2024-01-08 00:16:22', '2024-01-08 00:16:22', 1);
INSERT INTO `blog_diary` VALUES (1579, 1, '这几天是真的完全沉迷动漫，明天一定要振作起来，上午过去买俩斤排骨。', '2024-05-11', '2024-05-11 23:55:08', '2024-05-11 23:55:08', 1);
INSERT INTO `blog_diary` VALUES (1580, 1, '今天导师离职了，我是周三走，最近在公司是一点都坐不下去了，买的周五回家的车票，之后找工作北京和杭州都可以考虑，主要还是去北京吧，离家近方便点。', '2024-04-15', '2024-04-15 23:47:32', '2024-04-15 23:47:32', 1);
INSERT INTO `blog_diary` VALUES (1581, 1, '我操了啊，干了一下午加一个晚上直到现在都没弄好stm32的消息接收，现在发送是没问题了，看参考的那个项目写了中断接收，但是感觉不对劲啊，明天早点起来继续看吧，今天实在是太晚了。', '2024-12-28', '2024-12-29 01:54:12', '2024-12-29 01:54:12', 1);
INSERT INTO `blog_diary` VALUES (1582, 1, '一天了也没解决dmp文件格式的导入，游戏也没玩。', '2024-08-11', '2024-08-12 00:12:00', '2024-08-12 00:12:00', 1);
INSERT INTO `blog_diary` VALUES (1583, 1, '改了新简历，还没准备。e', '2024-07-11', '2024-07-12 00:00:44', '2024-07-12 00:00:44', 1);
INSERT INTO `blog_diary` VALUES (1584, 1, '面试完了，感觉还行。', '2024-05-15', '2024-05-15 22:39:22', '2024-05-15 22:39:22', 1);
INSERT INTO `blog_diary` VALUES (1585, 1, '今天中午到了杭州，下着小雨，我的雨伞拉在了家里，晚上出去吃饭，但是因为这几天过年，好多饭店都不开门，晚上只能在附件走走看，最后在火炬大道东边的小区旁边吃饭，还有今天公司的手机卡没网了，可能是公司给我停了吧，但是也不应该啊，我现在还没有被离职，手机俩张卡换一下位置还是不行，总不能是我手机的问题吧，也不知道公司啥时候裁我，不过至少也得一个月吧，不能通知之后就让我直接走人，今天还准备网上倒卖游戏账号，看下一个感觉还算不错的原神账号，都下单了，但是因为平台直接扣60%的手续费，卖家不乐意，我觉得也是离谱，限制了最低额度手续费是30块，直接限制了小额交易，也不知道这个平台有多少大额的交易单，今晚就写这些，明天开始继续看视频，好几天没看了，这个假期还有三天，至少把五一单片机的相关内容看完，年后每天都多多少少有些事，做的东西都是年前弄好的，现在各方面进度都感觉差了些，接口文档我估计是写不完了，这个主要是写给我自己看的，等接口稳定之后再说也可以，功能最近也不考虑加了，docker脚本有时间写吧，估计剩下这几天也做不完。', '2024-02-15', '2024-02-16 00:38:00', '2024-02-16 00:38:00', 1);
INSERT INTO `blog_diary` VALUES (1586, 1, '久违的周末，也算是充实吧，今天主要写后端的代码，完成了传感器命令组这块的大部分功能，就剩一个命令组的修改，但是这个修改会很麻烦，接收的数据是通过组装的，所以返回的数据我也得根据不同传感器组装好对应的数据，然后界面展示还要返回对应输入框的参数校验类型，越想越麻烦，有点不想搞修改，但是这个修改用处还是很大的，因为传感器控制参数要慢慢调整，慢慢想办法吧，这个兼容就很麻烦，还有就是因为接收传感器命令组的参数修改了原有的接口，导致之前的单个传感器控制参数没办法保存了，还有修改了很多之前的配置数据和字段，功能也有受到影响，只能说现在慢慢规范数据吧，要修改的功能很多，明天开始把传感器模板的接口先做出来，最近这些都有可以直接从接口中获取数据，页面先不着急。模板是只做控制类的传感器参数模板，主要就是配置对应要使用的接收数据的输入框类型、数量和范围，现在能想到的数据输入框大概有数字的输入框，用来控制舵机还有之后要坐的摄像头控制录制视频时间，开关类型可以控制led和摄像头的拍照和录制视频模式，还有其他能控制的传感器就不清楚了，大部分都是些检测环境产生数据的传感器。晚上玩了会魂二，很久之前打到的熔铁城今天也算是探索完成了，根据好像也没几个场景，地图不是很大，最后的boss也好弱啊，就是boss战的场景太恶心人了，地图中间有个大岩浆坑，之后也不知道还能去哪，很久之前玩的时候我记得有几个地方被石像挡住了，今天应该是拿到了一个怀念香木，记得是龙骑那边有个下水道可以去，等先把废渊点亮再说，睡觉了，边写日记在玩三国杀，思路都断了，明天还得上班。', '2024-09-28', '2024-09-29 01:06:00', '2024-09-29 01:06:00', 1);
INSERT INTO `blog_diary` VALUES (1587, 1, '今天应该是俩个面试，但是上午那个因为开会，所以推迟到明天上午，下午的这个面试不是技术面试，就是简单和项目经理聊了会，感觉还是可以的，说的是有二面，具体时间等他们通知，现在这个情况好像工作要找到天津去了。', '2024-07-15', '2024-07-15 23:36:42', '2024-07-15 23:36:42', 1);
INSERT INTO `blog_diary` VALUES (1588, 1, '阿玛纳祭坛可算是打完了，这个地图是真的阴间，别人的技能那就是追踪导弹，我的法术就是玩具，好在最后还是过了，没给我真心态爆炸，这个图的最终boss是真的简单，最后都没技能了，靠匕首近战拿下，公司的项目今天把bug改差不多了，明天过去有个数据和大平台要确认一下，然后就没其它大问题了。', '2024-10-11', '2024-10-12 00:20:38', '2024-10-12 00:20:38', 1);
INSERT INTO `blog_diary` VALUES (1589, 1, '今天还是去中心，早上过去稍微迟了几分钟，大概十点零几，然后过去我以为政伟没过去，然后我就在警卫室等了一个小时，直到学城过去才告诉我早上开会，很早就到了，然后中午就吃一个汉堡，可能是汉堡有问题，下午就开始喷射了，还好不严重，晚上依旧没饭吃，一直干到了十点半，最近这几天是真累啊，心累、身体也累，明天上午去招待所那边，至少中午饭有着落了，下午去中心估计晚上回来又不早了，今天现在就是刚刚吃完饭，晚上到家是十一点半，下班都迷糊了，地铁坐反了，多走了四站，好在最后没错过最后一趟地铁。晚上买了一个机械硬盘，先用着存点学习资料，之后接到我的树莓派上，通过网站可以上传点资源之类的数据，希望做一个云盘来使用，主要还是要优先把那个文件同步和获取文件这块弄开就可以了，硬盘数据这个上传其实就是和正常文件上传一样，再就是需要开发一下netty的交互数据，和树莓派上面的项目加一个获取目录下文件与文件夹功能通过netty发出去就行，睡觉了，明天还要上班。se', '2024-08-23', '2024-08-24 01:05:06', '2024-08-24 01:05:06', 1);
INSERT INTO `blog_diary` VALUES (1590, 1, '又到了一年的平安夜，今天公司的接口继续开发，抽时间还看了看pyqt5，这个做客户端软件好像更简单一些，明天继续有时间看。', '2024-12-24', '2024-12-25 00:55:00', '2024-12-25 00:55:00', 1);
INSERT INTO `blog_diary` VALUES (1591, 1, 'mmp，总算是部署有了点进步了，这次是因为什么原因，主要还是想一次性测试完成，但是dockerfile的问题比较多，最后排查出因为路径没有配置，jar包的运行脚本格式部署shell的格式，里面\\n\\r的问题，好在最后连接上nacos了，算是阶段性进度，就是docker使用localhost不能配置，这个部署起来也很烦，需要用很多容器的名字来代替localhost，再看看有没有什么比较好的替代方式。', '2024-03-07', '2024-03-08 01:02:44', '2024-03-08 01:02:44', 1);
INSERT INTO `blog_diary` VALUES (1592, 1, '今天也很棒哦，上午有点迷茫不知道该干啥，写功能没啥心情，写文档又懒，完全是因为没买到回家的车票导致的，还好中午突然短信通知我买到了票，虽然有点早是2号晚上的车票，也就请假三天，还是可以接受的，下午看看公司的皮带项目，但是还是没有开发的分支，所以只好继续写功能了，把传感器数据上报博客功能完成了，现在就差控制命令下发了，晚上回来把舵机控制也弄好了，真是万事俱备，只欠放假，这个假期要是可以花一半的时间写代码，等假期结束之后一定会有质的飞跃。', '2024-01-25', '2024-01-26 00:08:34', '2024-01-26 00:08:34', 1);
INSERT INTO `blog_diary` VALUES (1593, 1, '昨天加班到了半夜俩点，准备打车回来的，但是后来放弃了，骑车去天安门前走了走。', '2024-09-07', '2024-09-09 00:33:54', '2024-09-09 00:33:54', 1);
INSERT INTO `blog_diary` VALUES (1594, 1, '到今天为止一共休息了三个半月了，明天是去新公司入职报到第一天，第一个项目就是要出差，所以我先不用去租房子，不过租房是肯定的，就是先推迟几个月，租房预算也没确定多少，但是要租一个有厨房的房子，尽量还是找一个单独厨房的房间比较好。继续写日记，刚了解了下新出的树莓派5，再观望一段时间，如果有新的需求也可以做一个树莓派5上面的项目，不过我现在对树莓派的型号需求不大，现阶段树莓派就是我的一个家庭内部服务器，能装个linux系统就能用，明天早上六点多的火车，去了新公司希望顺利吧，至少我现在感觉这个工作还挺满意的，休息了三个半月，博客项目是一点进展都没有，刚回家那会就开始找工作，面试不顺利，一直再焦虑，想看视频学习，但是看视频学习的时候就会想起来工作的事情，找工作也不可能做到一天都在专心准备这些，结果就是焦虑了三个月，最后找到工作，确定入职的这几天才是我完全放松的时间，新公司这边没有限制内网，晚上加起班来也舒服不少，笔记也不会担心写完会丢，后半年开发重心主要是完善博客已有功能，主要是现在的文件同步功能测试完成，界面尽可能优化下吧，还有就是websocket推送这块也希望尽快用起来，现在只有推送网站数据这些，有点太少了，有想法做个socket的聊天室，不过这块涉及的东西太多了，首先从用户注册完善开始，还有页面开发，好像也不是很多，但还是先不提高这个任务优先级，对了管理页展示也想修改，这个可以优先，今年后半年侧重单片机stm32的学习，最近看来江科大的视频，简单读取传感器数据，控制些应该可以做到，然后就是接口文档的完善，交互协议也制定好，有个规范开发着还是舒服。最后就是今年一定要配一台电脑了，公司说的最近这个出差的项目至少要到九月，所以我的台式装好至少也是国企假期了，4070s，不算显示器预算10k左右，就写这些了，明天早上六点四十的火车，有什么情况明天晚上继续，最近变化大，应该可以写不少日记。', '2024-07-31', '2024-07-31 23:15:14', '2024-07-31 23:15:14', 1);
INSERT INTO `blog_diary` VALUES (1595, 1, '今天服务器到期了，把数据和图片都弄出来了，明天下午还有一个面试，今天去接李雨婷考试，气死我了直接鸽了我。', '2024-06-23', '2024-06-24 00:36:40', '2024-06-24 00:36:40', 1);
INSERT INTO `blog_diary` VALUES (1596, 1, '又盼到了休息日，明天的假期是清明假期，调休了一天，所以如果要是倒霉下周要连上七天班，不过眼前最重要的是明天睡个懒觉。', '2024-04-03', '2024-04-04 01:16:22', '2024-04-04 01:16:22', 1);
INSERT INTO `blog_diary` VALUES (1597, 1, '旧的动漫看完了，又选了一个新的，真上头啊。', '2024-11-16', '2024-11-17 01:41:20', '2024-11-17 01:41:20', 1);
INSERT INTO `blog_diary` VALUES (1598, 1, '好困，眼睛疼，但是看到一个特别好看的动漫，好想看完啊。', '2024-05-01', '2024-05-01 23:40:10', '2024-05-01 23:40:10', 1);
INSERT INTO `blog_diary` VALUES (1599, 1, '今天开始开发公司项目的接口了，虽然现在这边用到的好多技术之前大华没用，写法也不太一样，但是好在今天的接口还是完成了，卡了一天结果是前端给我的二维码解析出来的字符串错了，要不然真用不了这么长时间，晚上回家真的好想玩缺氧，最近找到工作了，玩起游戏来也不会焦虑，这个缺氧存档最近玩的还算可以，今天多玩了半小时，赶快睡觉了。', '2024-08-05', '2024-08-06 00:37:32', '2024-08-06 00:37:32', 1);
INSERT INTO `blog_diary` VALUES (1600, 1, '请假批下来了，后天就要回家了，严格来说是明天，已经过十二点了，明天晚上就不加班了，早点回来收拾东西，今天把上周的骑行记录和昨天的春节礼盒记录了下，最近开发博客传感器功能，开始感觉没啥东西，不就是数据下发吗，做的多了感觉有点复杂了，涉及的表有点多，最有关系比较复杂，要做的接口也很多，不知道最后界面要怎么实现，我现在是已经把界面画好了，当然是在我的笔记本上，不会用电脑画ui，而且我这个也用不着，自己知道怎么做就行，现在博客可以接入的传感器有俩个，过年回去先把这个测试弄好了。在写几句吧，前几天领的雪莲果吃起来没啥味啊，吃起来还很麻烦，要削皮，洗完吃了几口就丢了，主要还是因为晚上尽量不要吃东西吧，希望嗓子这尽快好吧，消化也赶快好，而且好像平时在家没啥感觉，一上班就难受，睡觉了。', '2024-01-31', '2024-02-01 00:37:06', '2024-02-01 00:37:06', 1);
INSERT INTO `blog_diary` VALUES (1601, 1, '今天去找了王鹏还是没处理啊，现在确定了我的d1板子是正常的，是因为我的数据线有问题，8266还是连不上，51单片机俩个都不行，去找王鹏看他也没办法，不知道是板子的问题还是下载器的问题，联系商家之后决定又给我发一个，写的我笑了，花了一个板子的钱商家给我寄回来三个，血赚。', '2024-01-13', '2024-01-14 00:56:44', '2024-01-14 00:56:44', 1);
INSERT INTO `blog_diary` VALUES (1602, 1, ' 玩了一天游戏，明天准备看看硬件，或者准备给博客加一个文章可以上传附件的功能，因为我最近想把游戏存档也保存下来。', '2024-10-26', '2024-10-26 23:12:18', '2024-10-26 23:12:18', 1);
INSERT INTO `blog_diary` VALUES (1603, 1, '魂二也是终于走到王城了，一路上小心翼翼的，太阴险了，把怪刷成雕像类敌人，不打一下和没办法区分，还好我是法爷，远程试错也没太大影响，今晚耻辱退游，突然就给我红灵入侵了，后面还跟着好几个精英敌人，只能alt+f4秒退游，最近这几天就要去中心弄这个数据迁移了，之前还想着迁移数据用我写的sql，结果今天过来说orgid对应上也不一定是同一个组织，那只能是用这个工具来操作了，然后要比较的军衔起算时间和另一个不知道叫啥的数据也不能是这次迁移，因为这个工具也不需要人员的数据，到时候看吧，做不了就是做不了，我就是不粘锅。', '2024-10-08', '2024-10-09 00:24:44', '2024-10-09 00:24:44', 1);
INSERT INTO `blog_diary` VALUES (1604, 1, '又玩了一天，下午投了几个简历，但是都没回复，明天早点起来出去骑车。se', '2024-06-17', '2024-06-18 00:14:04', '2024-06-18 00:14:04', 1);
INSERT INTO `blog_diary` VALUES (1605, 1, '博客数据文件同步功能算是可以上线了，然后树莓派上报设备信息的这块还有一点问题，现在获取内存信息没问题，但是获取cpu、硬盘和网络的信息那个工具就会报错，这样应该不会是权限的问题了吧，在win10上我本地启动这些信息都是可以收集到的，上了树莓派就有问题，现在就是不能完全确认是不是docker的问题，因为内存可以获取到数据，现在接下来也不知道从哪个方向继续看了，明天把ftp数据同步的剩下些整理工作完成，然后就是着手测试云服务器上文件和树莓派之间的互相传送，刚刚等到十二点想看那个数据文件的备份，结果失败了，这个是因为定时任务调用shell脚本失败，发了netty响应但是没生成文件，上云服务器看了一眼果然是没生成文件，那这个问题明天也要看一下。之前找的那个大佬帮我看stm32连接mqtt现在也没消息了，那我就明天继续找群里大佬吧，现在要找代码一定不能占用我的A9、A10这俩个引脚，前些天学会的通过串口工具调试应该就预定了这俩，不然硬件这出了问题真不好调试。', '2024-12-08', '2024-12-09 00:16:10', '2024-12-09 00:16:10', 1);
INSERT INTO `blog_diary` VALUES (1606, 1, '今天去了也没事干，结果早上等了一小时在门外等人，中午等了俩小时等人家睡醒给我登记换出入证，真的烦死了，晚上回家玩缺氧又是专注二星，忘了一星，结果一星又崩了，重新开个新档继续玩吧。', '2024-08-17', '2024-08-18 00:30:18', '2024-08-18 00:30:18', 1);
INSERT INTO `blog_diary` VALUES (1607, 1, '头疼啊，真是服了，esp烧录上去WiFi都扫不到，看板子背面说要装一个驱动，装好了还是扫不到无线，stm32也是根本弄不了，现在非常烦躁啊。se', '2024-12-30', '2024-12-31 00:00:56', '2024-12-31 00:00:56', 1);
INSERT INTO `blog_diary` VALUES (1608, 1, '今天工作终于确定了，下周四过去入职，13k的工资，12%的公积金，真好啊，过去要加一个月的班，先住宿舍，之后再去看房子。', '2024-07-26', '2024-07-27 00:21:06', '2024-07-27 00:21:06', 1);
INSERT INTO `blog_diary` VALUES (1609, 1, '马上中秋假期了，但是不考虑回去，就在宿舍写写代码，或者可以出去骑单车绕北京溜达，中秋节日给自己定个小目标，就是不点外卖，出去找个差不多的餐厅，反正价格也差不了多少，博客部署的话应该是中秋弄不好，才买的新舵机今天才从深圳发货，不知道啥时候能到，没啥想记的，下午去了中心，主要我就是调那个二维码的工作，现在打印出来的也可以扫到了，但是还是反应很慢，明天过去测士兵信息上报的功能，这个弄好久了，总是被打断，明天应该是可以完成。不写了，现在思路有点乱。还有最近没有写博客，一是时间不够用，再就是弄了一个新的项目搭建dubbo、es、ssljob的项目，现在卡在了dubbo，不知道该选择那个版本，想用最新的，又害怕spring boot2.7不兼容。最后就是明天下午四点有个面试，但是明天下午大家都不去中心，我只能悄悄的找个没人的地方偷偷面试了。', '2024-09-13', '2024-09-14 00:22:02', '2024-09-14 00:22:02', 1);
INSERT INTO `blog_diary` VALUES (1610, 1, '最近很火的背包乱斗晚上买下完了一会，开始玩还行，但是一会就无聊了，也就是一个热度的游戏吧，没啥意思，所以就又退款了，然后今天说的要办卡，正好看到公司论坛有类似的贴子，没想到在公司就能补办，现在我的流量又回来啦。', '2024-03-13', '2024-03-13 23:59:42', '2024-03-13 23:59:42', 1);
INSERT INTO `blog_diary` VALUES (1611, 1, '晚上不想睡，白天不想起，明天还有个面试。', '2024-07-09', '2024-07-10 00:52:18', '2024-07-10 00:52:18', 1);
INSERT INTO `blog_diary` VALUES (1612, 1, '晚上给超凡看问题，真的太菜了，简单的问题都要看十几分钟，不过确实也是spring配置相关的了解的少，连spring启动要做些什么都不知道，不过今年还是侧重使用，源码流程这些以后再看，准备面试暂时就先背面试题好了。', '2024-01-18', '2024-01-19 01:10:26', '2024-01-19 01:10:26', 1);
INSERT INTO `blog_diary` VALUES (1613, 1, '今天周六，不去上班，双休的感觉真好啊，休了一天还有一天，今天一整天都在外边闲逛，熟悉一下这个城市，四处骑车走了走感觉城市不是很大，城市更偏向移居吧，要对比我只能是和北京杭州来比较了，这边应该是城管管的松一点，我住的附近这边到处都有小商贩，路上看着也不是很整洁，但是这个感觉就很好，接下来在这个城市工作希望可以顺利些，下午骑车去码头，路过一片拆迁房区，做为一个城市流浪汉我不得不去废墟淘宝了，逛了四个单元40多户找到俩个一毛钱的硬币，还有一个全新的耳机，收获满满，晚上整理手机里的小姐姐，但是视频这东西多了就容易重复，不方便管理，在网上找了又找也没看到一个合适的，所以我就突然有想法用python开发一个视频图片文件管理的一个小工具，需要的功能也就是校验视频与图片，确保管理目录下的这些数据文件没有重复内容，对于图片希望可以加一个识别这个照片是截图还是照片的功能，大概也就这些，应该不算是很复杂吧，去除的大概思路是通过对文件生成sha256来判断文件是否唯一，所以肯定是需要使用数据库的，但是肯定是用文件存储类型的数据库，MySQL这些需要安装软件很不方便，明天就可以开始研究下这些东西。', '2024-12-14', '2024-12-15 01:12:22', '2024-12-15 01:12:22', 1);
INSERT INTO `blog_diary` VALUES (1614, 1, '一天真是啥都没干，今天开始上班的没几个人，多亏我早上还去的那么早，俩个前端八点左右就下班了，我等到了晚上九点，虽然没做啥工作，但是今天还是开始开发前端的页面吧，一个屏幕是有点不太方便，感觉现在stm32那边估计要卡住了，昨天弄了一天最后还是没有控制好那个舵机，还有就是mqtt的固件要找一个。', '2024-09-18', '2024-09-19 00:17:14', '2024-09-19 00:17:14', 1);
INSERT INTO `blog_diary` VALUES (1615, 1, '李雨婷要准备中考了，我今晚得让出房间来。', '2024-06-18', '2024-06-18 21:00:22', '2024-06-18 21:00:22', 1);
INSERT INTO `blog_diary` VALUES (1616, 1, '有俩个面试过了，其中有一个需要二面，另一个还没打电话，这俩个都不是外包，感觉还算可以。', '2024-07-25', '2024-07-26 00:20:22', '2024-07-26 00:20:22', 1);
INSERT INTO `blog_diary` VALUES (1617, 1, '有个996的面试，等面试通知，今天研究一下午异星工场，现在核电可以了，开始研究铁路，铁路这个有点复杂，看看视频。se', '2024-05-27', '2024-05-27 21:43:30', '2024-05-27 21:43:30', 1);
INSERT INTO `blog_diary` VALUES (1618, 1, '今天把数据迁移的那个组织映射文件弄好了，应该是可以了吧，我看之前东方通数据迁移的数据库里面都有这个组织结构映射表，然后通过这个表把数据同步到大平台，然后每天过去做数据同步这个，是要使用一个其它的工具，这个是把大平台的数据拉取到本地的数据库，然后由我们新做的这个系统使用获取到的数据，这个数据同步应该是按天获取数据的，这个延迟是没办法避免的，因为只有一个数据库，还不能互通，希望明天可以早点出来吧。晚上缺氧算是把俩个基地都稳住了，我玩游戏都是在挂机看小人工作，一直都进度很慢，我都因为挂机回档好几次了，之后先把基础设施弄好吧，不然真的玩的太极限了。', '2024-08-16', '2024-08-17 00:55:30', '2024-08-17 00:55:30', 1);
INSERT INTO `blog_diary` VALUES (1619, 1, '因为昨晚就住在了招待所，所以今天一整天都状态不错，晚上也不瞌睡，中午和晚上都继续完善传感器控制的前端页面，这块控制完成之后还要加传感器的模板页面，模板页面好像用处不是很大，但还是加一下吧，今天写的控制传感器用到的一些数据都是希望可以直接从后端获取的，弄一个模板配置方便修改，刚刚想设备的时候他发奇想想把服务器设备的信息也加入我这个设备管理里面，不过这个等后端大升级再说吧，先在这留个记录，睡觉了。se', '2024-09-24', '2024-09-25 00:32:46', '2024-09-25 00:32:46', 1);
INSERT INTO `blog_diary` VALUES (1620, 1, '放假了，明天开始看看硬件，epic送的吸血鬼也玩玩。', '2024-12-20', '2024-12-21 00:35:38', '2024-12-21 00:35:38', 1);
INSERT INTO `blog_diary` VALUES (1621, 1, '今天缺氧新出了dlc，买下体验了一下午，晚上也晚了，感觉还不错，但是一个dlc就一个地图内容还是有点太少了。', '2024-07-19', '2024-07-20 01:15:14', '2024-07-20 01:15:14', 1);
INSERT INTO `blog_diary` VALUES (1622, 1, '离职第二天，今天准备回家，晚上八点的火车票，因为晚上在火车上所以就现在把今天的日记写完吧，下午还没过，上午就收拾打包行李，昨天预约了中铁货运的上门取件，应该是一会就可以到了，现在准备收起电脑然后就忙其他事情了，还要和房东退租，房子押金应该得给我退个500吧，se', '2024-04-19', '2024-04-19 14:33:06', '2024-04-19 14:33:06', 1);
INSERT INTO `blog_diary` VALUES (1623, 1, '收拾完成一个星球，开始下一个星球搬空计划。', '2024-11-23', '2024-11-24 02:12:28', '2024-11-24 02:12:28', 1);
INSERT INTO `blog_diary` VALUES (1624, 1, '说的不想去上班，但还是过去了，没干活，但是做了部署脚本，突破了之前卡着的好几个问题，还算不错。e', '2024-03-02', '2024-03-03 01:37:48', '2024-03-03 01:37:48', 1);
INSERT INTO `blog_diary` VALUES (1625, 1, '今天服务器到期了，明天上午抢购一个便宜点的吧，凑合着能用就行，然后把数据导过去。', '2024-06-24', '2024-06-25 00:11:54', '2024-06-25 00:11:54', 1);
INSERT INTO `blog_diary` VALUES (1626, 1, '因为今天招待所的服务器环境出问题了，所以今天上午和下午的一会时间都在看服务器的问题，之后就是朴实无华的改bug时间，还算是轻松，明天不知道会咋样，晚上回家继续魂二，但是现在不知道该去哪，好几个dlc我找不到，王城应该还要再去几次，但是去王城应该是快通关才去吧，应该先打dlc，今天就开刷冰原的这个图，看的眼睛疼，一次只能玩一会，再就是这个怪也太肉了，我玩法师技能没了，武器坏了还没找到下一个篝火，幸好之前买了些加法术次数的和修武器的道具，最后好不容易找到了火，dlc确实有难度，还有一个根本看不见的boss，也不能锁定，今天就写这些，魂二还是得看攻略玩，不然太受苦了，之后有计划玩近战，法师还是不太行。se', '2024-10-15', '2024-10-16 00:22:20', '2024-10-16 00:22:20', 1);
INSERT INTO `blog_diary` VALUES (1627, 1, '昨天被那个圣女一拳给我打懵逼了，尼玛的，真想上去一刀宰了你，就怕会不会影响我全成就。', '2024-03-28', '2024-03-28 23:35:16', '2024-03-28 23:35:16', 1);
INSERT INTO `blog_diary` VALUES (1628, 1, '今天本来有俩场面试，但是因为上午有事情那个北京的公司就没办法只能鸽了，下午面试杭州那个，感觉回答的不太行，而且在那个小楼梯间听不太清面试官说啥，反正就那样面试的一塌糊涂，晚上本想写一下今天面试不会的题，记录一下，但是实在是不想起来思考，最近不知道为什么状态一直不好。e', '2024-11-06', '2024-11-06 23:49:56', '2024-11-06 23:49:56', 1);
INSERT INTO `blog_diary` VALUES (1629, 1, '又是给hr刷业绩的一天。', '2024-06-28', '2024-06-29 00:34:18', '2024-06-29 00:34:18', 1);
INSERT INTO `blog_diary` VALUES (1630, 1, '今天下午出去五峰山随便找了个山去爬，实在是好累，明天开始要认真周工作了，上午早点起学习51单片机和stm32，下午投简历和复习，最近不怎么想写日记每天都是几句话，新玩的dnf手游我觉得还行啊，充钱是一毛都不可能的，白嫖必须得贯彻到底，打装备也是一种乐趣。', '2024-06-02', '2024-06-02 23:44:20', '2024-06-02 23:44:20', 1);
INSERT INTO `blog_diary` VALUES (1631, 1, '堕落的一天，打扑克，打dnf（没错，我今天又下载回来了）。se', '2024-02-11', '2024-02-12 01:11:48', '2024-02-12 01:11:48', 1);
INSERT INTO `blog_diary` VALUES (1632, 1, '今天算是认真投简历了，明天上下午都有一个面试。', '2024-07-10', '2024-07-11 00:39:22', '2024-07-11 00:39:22', 1);
INSERT INTO `blog_diary` VALUES (1633, 1, '俩天时间真是搞了个寂寞啊，stm32现在只能发，收到了数据但是不会读出来，读数据标志位也不能用，esp8266也就是那个大的esp也是代码看网上教程也写好了，但是一直卡在连接WiFi这一步，不清楚啥原因，可能是因为固件烧录错了吧，真烦呐，俩天时间弄了个寂寞，我甚至都没玩游戏。', '2024-12-29', '2024-12-30 01:11:40', '2024-12-30 01:11:40', 1);
INSERT INTO `blog_diary` VALUES (1634, 1, '晚上买了一个51单片机，不知道会不会弄，有时间学习下，会做简单的功能就行，这个不是吃饭的家伙，博客项目也开始做文件同步这块的功能了，计划就是使用mqtt互相通信，通信收到消息之后使用ftps上传或者下载文件，然后回复结束的消息，但是这样好像有个问题，边缘的设备怎么和树莓派通信呢，http协议可以吗？到时候确定吧，走一步看一步，下午公司来了一个紧急的项目，需要总结每个人负责的模块接口报错信息，和错误之后的解决方案，我的辅助决策接口比较少，总结完成之后给海滨也做了几个，差不多这就是一天的工作了，最近没有开发的任务，下周需要讲ppt，是关于1.1.4开发功能的培训，明天开始要总结整理ppt了。最近晚上都在缺氧，才买的英雄旧忆都好几天没玩了，缺氧这个存档一定不能废弃，现在都挖空俩个星球了，之前一直玩不下去是因为后期太卡了，就十几帧，虽然这次也是一样的，但是可以慢慢来，处理好一个星球之后弄真空，清理杂物，然后再去下一个，希望这样有效果，可以稳定25帧就满意了。', '2024-01-03', '2024-01-04 00:31:20', '2024-01-04 00:31:20', 1);
INSERT INTO `blog_diary` VALUES (1635, 1, '今天有几个面试，不过都是外包，最近好像找自研的项目很少，都是外包的工作。', '2024-06-07', '2024-06-07 22:33:08', '2024-06-07 22:33:08', 1);
INSERT INTO `blog_diary` VALUES (1636, 1, '今天约了一个周四下午的面试，然后今天一整天都在看stm32连接mqtt的教程，现在是esp01s单独连接mqtt和wifi都没问题，但是通过stm32就只能连一个wifi，mqtt是死活都连不上，暂时还不清楚是什么原因，看了一天头晕，睡一觉明天继续看没准一会就解决了。', '2024-12-03', '2024-12-03 23:07:34', '2024-12-03 23:07:34', 1);
INSERT INTO `blog_diary` VALUES (1637, 1, '估计昨天的面试又寄了，明天继续投简历吧，我好菜啊，离职一个月了。', '2024-05-16', '2024-05-16 23:53:46', '2024-05-16 23:53:46', 1);
INSERT INTO `blog_diary` VALUES (1638, 1, '入职第一天，工作就是部队上那个，和想象中的不太一样，工位有点小，不过是去甲方项目上，这个也可以理解，希望这一个多月快点结束吧，之后租房子准备买电脑，最近给我的任务是数据迁移，算是把旧项目上的数据迁移到新的系统中，今天下午就简单的熟悉下数据库，看表结构的关系不是很复杂，但是因为军队的项目，涉及到的表非常多，数据的依赖关联关系还算清晰，不知道下一步要怎么做，今天第一天来了正好赶上公司团队聚餐，晚上直接吃席，今天一天的饭钱都没用我花，明天不知道要做什么，这个项目我还不太熟悉，应该不会用我做太多事情吧，还有就是办公室里面不让用自己电脑，提供的电脑还是内网，真的烦死人，面向百度编程工程师直接爆炸，想百度还得出来用自己电脑搜索，今晚住在公司的宿舍里面，听另一个同事说今年还刚刚裁员，有n+1补偿，这样我就放心的，转正之后就可以适当摆烂，今天就这样了，玩玩手机睡觉。', '2024-08-01', '2024-08-01 23:40:52', '2024-08-01 23:40:52', 1);
INSERT INTO `blog_diary` VALUES (1639, 1, '今天开始了开发博客设备的功能，今天进度是完成了netty离线删除通道和在线注册功能，做的感觉还挺复杂，能用就行吧，晚上把家里收拾了一下，准备回家咯。', '2024-01-29', '2024-01-30 00:58:58', '2024-01-30 00:58:58', 1);
INSERT INTO `blog_diary` VALUES (1640, 1, '新买的机械硬盘到了，感觉还行，3T空间足够我用了，就是意料之外的大，我以为这个硬盘会很小，就像笔记本里面这个一样，总之这个能用就行，存点收藏的动漫，今天一整天都在招待所，不知道每天要不要去中心，去招待所就像今天这样晚上回来就十一点了，中心那边能早回来一个小时，就是中午晚上没饭吃，晚上继续开发netty，这几天主要还是优化原来的数据，整理下文件位置，规范下字段名称，下周应该就可以正常开发netty的数据流程了。还有一件事，今天上午去了招待所，因为我的电脑被那个老师占用了，我以为今天用一上午就行，然后那个老师估计是没保存文件，直接就把电脑给我了，结果下午那会我还没走，只能给老师再找个电脑，从我这拷贝资料的时候发现没保存，真是吓死我了，找了半天结果是文件位置放错了，差点就背一个大锅。', '2024-08-27', '2024-08-28 00:40:20', '2024-08-28 00:40:20', 1);
INSERT INTO `blog_diary` VALUES (1641, 1, '我操了啊，国庆七天无休，真的受不了了，很累。', '2024-09-29', '2024-09-30 00:02:28', '2024-09-30 00:02:28', 1);
INSERT INTO `blog_diary` VALUES (1642, 1, '今天过生日，中午到吃饭的时候我才知道，下午面试了上周约的华苏科技，效率真高，下午直接俩场面试都结束了，晚上就告诉我面试通过了，现在就差我同意就能过去上班干活了，感觉这个公司不太行，网上的评价不高，然后我就要13k还磨磨唧唧的，试用期是六个月，试用期内不交公积金，就算是转正的公积金也就几百块，真恶心呐，拖几天不过我应该是不会去的，再找找其它的机会，今天回家第一天就收到了offer，那我再准备几天那还了得，晚上和群友联机星露谷，基本全程划水。se', '2024-11-12', '2024-11-12 23:36:12', '2024-11-12 23:36:12', 1);
INSERT INTO `blog_diary` VALUES (1643, 1, '今天炖了排骨，中午炒了菜，晚上和面，很充实的一天，投简历有几个会消息的，但是一个需要去现场，其他的还有几个外包，不太想找外包，明天继续整理面试题。', '2024-04-25', '2024-04-26 00:29:46', '2024-04-26 00:29:46', 1);
INSERT INTO `blog_diary` VALUES (1644, 1, '  只因为下午买了黑魂1，然后晚上没了。', '2024-03-17', '2024-03-18 00:16:20', '2024-03-18 00:16:20', 1);
INSERT INTO `blog_diary` VALUES (1645, 1, '大过年的，把传感器页面跳转，数据展示做完了，新增修改删除这些不是很着急，明天继续看单片机了。e', '2024-02-09', '2024-02-10 01:09:46', '2024-02-10 01:09:46', 1);
INSERT INTO `blog_diary` VALUES (1646, 1, '今天也是没啥事情，就该多考虑下博客怎么写，最近都没思路了，晚上回来就想开黑魂，魂二一周目也差不多要结束了，今晚开始刷dlc2，最后在玩dlc1。se', '2024-10-21', '2024-10-22 00:13:16', '2024-10-22 00:13:16', 1);
INSERT INTO `blog_diary` VALUES (1647, 1, ' 终于被裁员了，应该可以拿n+1，怎么说呢开心的是有好多钱，不开心的是万一找不到工作怎么办，慢慢来吧，失业这段时间一定不能焦虑，我现在也不缺钱，就算躺平好几年都没问题，慢慢找下一份工作吧总有瞎的公司看上我，实在不行降点要求，现在还是希望在北京找个16k的工作。', '2024-04-08', '2024-04-08 23:11:42', '2024-04-08 23:11:42', 1);
INSERT INTO `blog_diary` VALUES (1648, 1, '悠闲的一天，公司任务不是很忙，晚上团队聚餐本来还不想去，但是过去之后每人发了俩张彩票，所以今天就欧气爆发，刮到了200块，真开心，就是晚上的饭实在是太辣了，完全吃不了多少。', '2024-02-26', '2024-02-27 00:34:16', '2024-02-27 00:34:16', 1);
INSERT INTO `blog_diary` VALUES (1649, 1, '今天去了宁武芦芽山，没想到山西还有长满树的山，我一直以为山西的山就像我家这边这样的，而且坐火车路过的山都是没树的样子，长见识了，那边还有个万年冰洞，没进去，也不知道啥情况，今天就爬了俩座山。', '2024-06-30', '2024-07-01 00:12:00', '2024-07-01 00:12:00', 1);
INSERT INTO `blog_diary` VALUES (1650, 1, '明天上午还有个面试，这几天就光玩了没准备，今天换了一个桌子，从明天开始我要认真了。', '2024-05-22', '2024-05-22 23:38:04', '2024-05-22 23:38:04', 1);
INSERT INTO `blog_diary` VALUES (1651, 1, '国庆过半了，真是累啊。se', '2024-10-04', '2024-10-04 22:41:38', '2024-10-04 22:41:38', 1);
INSERT INTO `blog_diary` VALUES (1652, 1, '早上晚起来又忘了一个面试，改约到明天。se', '2024-06-13', '2024-06-14 00:40:02', '2024-06-14 00:40:02', 1);
INSERT INTO `blog_diary` VALUES (1653, 1, '小周上班好累，感觉一天都没休息好，上午虽然没去公司，但是心里总是感觉有事，下午上班又不想干活，真是烦人，新买的手机投屏设备也不能用，第二次退货了，下午还不知道发生了什么事情，现在电脑又不能远程连接了，明天再折腾吧。', '2024-03-30', '2024-03-31 00:12:38', '2024-03-31 00:12:38', 1);
INSERT INTO `blog_diary` VALUES (1654, 1, '今天下午参加了公司的年会，啥奖品都没中，所以不想写日记，上午去医院挂号看了看，问题不大。', '2024-01-22', '2024-01-23 00:28:58', '2024-01-23 00:28:58', 1);
INSERT INTO `blog_diary` VALUES (1655, 1, '今天写了公司的周报，准备出去找超凡蹭饭，但是后来实在是太累了，懒得出去，就在家打了一天缺氧，最近这个存档不错，啥都不缺，而且新dlc这个不用去二星都可以永生，完全不卡科技的，缺电我靠火山弥补了，玩了一百多周期很稳定，现在一个火山都没榨干，还有好几个火山都没挖开，新的一周开始了，996真是万恶啊，都没休息时间。下午璐瑶还找我聊天，真是罕见。', '2024-08-04', '2024-08-05 00:03:44', '2024-08-05 00:03:44', 1);
INSERT INTO `blog_diary` VALUES (1656, 1, '考虑一下午，我觉得还是不去那个公司了，外包项目996公积金才给340块，甚至餐补都没有，加班的时候都没有支撑的信念，就这点钱我怎么加班啊。', '2024-05-30', '2024-05-31 01:08:30', '2024-05-31 01:08:30', 1);
INSERT INTO `blog_diary` VALUES (1657, 1, '最近都没啥事情，上午解决了一个bug，是因为mqtt发送心跳重新登陆的时候加锁了，导致修改数据的时候获取不到锁，接口一直等待导致超时，最近开发传感器相关接口了，今天加好了树莓派设备注册相关的功能，页面可能假期回家写吧，不确定，假期主要还是看视频学习硬件，马上就放假了，最近天气不是很好啊，希望别因为下雪火车延期了。', '2024-01-30', '2024-01-31 00:23:14', '2024-01-31 00:23:14', 1);
INSERT INTO `blog_diary` VALUES (1658, 1, '今天上午的面试被鸽了，然后下午开车去了忻州，走的距离比之前远了。', '2024-11-27', '2024-11-28 00:58:04', '2024-11-28 00:58:04', 1);
INSERT INTO `blog_diary` VALUES (1659, 1, '今天博客应该是可以了，因为现在才部署好，明天再观察吧，感觉是没问题，现在因为docker容器隔离的原因，只能是每天0点通过系统的定时任务生成博客的数据文件，然后每天一点定时同步数据到我的树莓派上面，要是可以的话能写一个python脚本，和Java服务建立联系，然后通过接口调用来联系起来，但是这个不是很重要，以后有时间搞，每天开始继续写文档，总结笔记。', '2024-12-09', '2024-12-10 01:21:06', '2024-12-10 01:21:06', 1);
INSERT INTO `blog_diary` VALUES (1660, 1, '这个周末我真的是第一次这么保肝学习啊，周六起来吃完饭，中午出发就去找王鹏看单片机的问题，结果去了也没处理出个结果，不过确定了我的d1板子没有坏，是因为我的三条安卓线都是充电线，没一根是数据线，等下单的数据线回来就可以开始接板子的数据上报了，今天是保肝把docker部署树莓派做好了，踩了不少坑，主要还是因为arm架构的问题，很多都是软件不兼容，最后把博客的mysql版本升级到了8.x，所以下次部署服务器要等很久之后了吧，需要等重写完成博客主题的docker脚本才能开始测试替换，也不知道修改之后稳定性咋样，不过改之后脚本应该会简单点吧，数据也可以集中处理，今天把树莓派这个部署好都是使用的默认配置，还没使用自定义配置，这个也要作为工作量考虑进去，希望在春节假期里完成这些，今天也不早了，一天忙着处理问题，袜子也忘记洗了，游戏也没玩，就处理累了躺着看会动漫，睡觉了。', '2024-01-14', '2024-01-15 01:01:18', '2024-01-15 01:01:18', 1);
INSERT INTO `blog_diary` VALUES (1661, 1, '还要在公司呆坐着三天啊，有点受不了了，好在有钱拿，还得忍着啊。', '2024-04-12', '2024-04-12 23:14:50', '2024-04-12 23:14:50', 1);
INSERT INTO `blog_diary` VALUES (1662, 1, '今天是说的早睡，结果刷深渊真的好上头，就像闪一把，然后就玩到了现在。', '2024-06-12', '2024-06-13 01:27:32', '2024-06-13 01:27:32', 1);
INSERT INTO `blog_diary` VALUES (1663, 1, '今天的组织树算是可以找出不同的组织了，没有用原来的工具，那个公司名想不起来了，晚上玩缺氧，一直关注二星以为一星应该可以活下去了，结果因为抽到了水银，制氧设备坏了，死了一片小人，gg，明天再回档吧，可惜了今天刚造好的五档调谐。se', '2024-08-12', '2024-08-13 00:32:42', '2024-08-13 00:32:42', 1);
INSERT INTO `blog_diary` VALUES (1664, 1, '见证历史了，星舰第三次发射成功了，有生之年可以看到人类移民外太空吗？', '2024-03-14', '2024-03-15 00:18:10', '2024-03-15 00:18:10', 1);
INSERT INTO `blog_diary` VALUES (1665, 1, '明天上午有个面试，谈的工资就10k，还是北京外派，简直了，好事都让你占了，面试也就是走走流程罢了，不考虑这个工作，至少也给我个13k啊，玩了快一个月了，准备规律作息专心找工作和继续开发博客吧。', '2024-05-14', '2024-05-14 22:42:04', '2024-05-14 22:42:04', 1);
INSERT INTO `blog_diary` VALUES (1666, 1, '失业回家了，今天是第一天，火车上也没啥事情，明天整理笔记，更新博客，投简历找工作吧，希望一切顺利。', '2024-04-20', '2024-04-20 23:53:14', '2024-04-20 23:53:14', 1);
INSERT INTO `blog_diary` VALUES (1667, 1, '本以为今天是大周，昨天下班把充电器都带回来了，结果今天中午要过去上班，真是给我个惊喜啊，下午去了那就看博客呗，新创建的pi项目，这个项目是用于树莓派获取家里传感器的数据上报博客，以及存放博客的一些数据文件，感觉还是很不错的一个思路，下午就把netty打通了，应该可以实现我这个想法吧，还没测试过，别到时候因为我这个没有固定的ip连接不上。', '2024-01-06', '2024-01-07 00:29:56', '2024-01-07 00:29:56', 1);
INSERT INTO `blog_diary` VALUES (1668, 1, '今天bug改了挺多的，现在看着能改的差不多都改完了，剩下的就是慢慢调试的过程，晚上继续打黑魂二，王城剩下的地方懒得再探了，等之后一周目准备结束的时候在扫图，去了下一个场景，真的恶心啊，别人的法师全图发射追踪，我的法师完全就是受苦，还有很多隐藏的小怪也是，抓几下我就没了，晚上回来把死亡细胞买下了，全dlc，然后体验了一回，感觉还是不错的，只不过没太多时间玩。', '2024-10-10', '2024-10-11 00:41:18', '2024-10-11 00:41:18', 1);
INSERT INTO `blog_diary` VALUES (1669, 1, '又是测试脚本的一天，一直是因为各种小问题重启，现在应该调试差不多了吧，最后一次重启看看结果怎样，之前做docker部署就是因为使用docker部署上传的压缩包比较小，部署速度快，但是现在服务器测试如果直接从镜像网站下载很容易下载失败，无奈又改成了上传镜像导入，完全没有任何变花嘛，喜报，就在刚刚本地树莓派服务启动成功，本地启动的博客服务收到了来自树莓派的心跳消息，现在那就是树莓派的一键部署完成了，下一步就是等周六把博客主题的一键部署也完成，今晚预计的测试下博客压缩包整体部署，但是一晚上都快三小时了七个镜像文件还没下载好，现在就差最后一个rocketmq，七个镜像总大小估计4g，md看了看以前的压缩包导入下载也就1.2g，简直了反向优化，要不在搞一个下载镜像的脚本吧，今天就这样，等最后一个镜像文件下载完成睡觉，好久没打游戏了，等这周部署完成一定要好好玩一下，dnf现在也戒了，之前dnf占用了太多晚上的时间，现在空出来能干好多事。真是倒霉，又遇上了token过期问题，账号登陆不上，只能重新申请一个token，我申请的权限还挺高的，应该没啥问题吧，不要泄露就行。', '2024-03-06', '2024-03-07 00:38:42', '2024-03-07 00:38:42', 1);
INSERT INTO `blog_diary` VALUES (1670, 1, '最近沉迷动漫，昨晚几乎通宵了。', '2024-05-06', '2024-05-06 23:50:58', '2024-05-06 23:50:58', 1);
INSERT INTO `blog_diary` VALUES (1671, 1, '又活了一天，我真的太厉害了。', '2024-06-20', '2024-06-21 00:09:44', '2024-06-21 00:09:44', 1);
INSERT INTO `blog_diary` VALUES (1672, 1, '昨天晚上到家就不早了，而且晚上都没吃饭，所以就没开电脑，日记也没写。', '2024-08-20', '2024-08-22 00:32:44', '2024-08-22 00:32:44', 1);
INSERT INTO `blog_diary` VALUES (1673, 1, '又杀到不早了，杭州那个工作可能要去了，就是不知道开多少工资。', '2024-12-10', '2024-12-11 01:01:42', '2024-12-11 01:01:42', 1);
INSERT INTO `blog_diary` VALUES (1674, 1, '很忙的一天，也好累啊，对接完功能，晚上改bug，因为人不多，所以把走了的那几个人的功能也分给我了，睡觉了，明天还得加班，应该是可能还要加班一个月。', '2024-09-02', '2024-09-03 00:05:38', '2024-09-03 00:05:38', 1);
INSERT INTO `blog_diary` VALUES (1675, 1, '打了一晚上dnf，最近好像又玩明白了。', '2024-02-20', '2024-02-21 00:57:46', '2024-02-21 00:57:46', 1);
INSERT INTO `blog_diary` VALUES (1676, 1, '今天就继续做笔记，nacos的也得写点了，这个好像用的人还挺多的。', '2024-07-06', '2024-07-06 23:42:44', '2024-07-06 23:42:44', 1);
INSERT INTO `blog_diary` VALUES (1677, 1, 'mqtt接口的数据算是完成了，最近上班没时间写博客，开发工作有点忙，晚上弄esp8266连接mqtt，wifi连接没问题，这个以前就弄好了今天一直连不上mqtt，好烦。', '2024-10-02', '2024-10-03 00:10:54', '2024-10-03 00:10:54', 1);
INSERT INTO `blog_diary` VALUES (1678, 1, ' 打了一天游戏，晚上打杀戮尖塔，打了四五个小时，还好算是过了难度十五了，但是看视频别人过的真简单，可能是流派不一样吧，还有应该是手机版本和电脑的版本有区别，有些牌不太一样。明天应该学习了，今天玩一天。', '2024-02-24', '2024-02-25 00:50:14', '2024-02-25 00:50:14', 1);
INSERT INTO `blog_diary` VALUES (1679, 1, '服了，树莓派这个镜像烧录工具应该是有问题，下了好多版本都是烧录失败，用其他的也是只有命令行页面，下载的镜像都是从官方软件上下载的带可视化页面的镜像文件，真的是傻逼软件啊，我现在是可以保证绝对是软件问题，今天一天都是在忙这个，真浪费时间。', '2024-12-02', '2024-12-03 00:20:20', '2024-12-03 00:20:20', 1);
INSERT INTO `blog_diary` VALUES (1680, 1, '昨天晚上看大爱仙尊，晚上就懒得开电脑写日记了。', '2024-11-19', '2024-11-20 23:47:30', '2024-11-20 23:47:30', 1);
INSERT INTO `blog_diary` VALUES (1681, 1, '该睡觉了，今天早饭没吃，晚上啃了几袋泡面，下午出去骑了会车，也没学习，好烦啊。se', '2024-02-16', '2024-02-18 00:28:32', '2024-02-18 00:28:32', 1);
INSERT INTO `blog_diary` VALUES (1682, 1, '今天下午面试了一个，汗流浃背了，一问三不知，算是给我指出了简历问题吧，明天修改。', '2024-07-02', '2024-07-03 00:23:30', '2024-07-03 00:23:30', 1);
INSERT INTO `blog_diary` VALUES (1683, 1, '明天就开始做笔记。', '2024-05-02', '2024-05-03 01:09:18', '2024-05-03 01:09:18', 1);
INSERT INTO `blog_diary` VALUES (1684, 1, '失业俩个月了，明天继续找工作。', '2024-06-16', '2024-06-17 01:31:04', '2024-06-17 01:31:04', 1);
INSERT INTO `blog_diary` VALUES (1685, 1, '明天就是最后一天了，下午先交了电脑然后回家整理下简历，投了好多都说了项目太少，那我就写点定制参与的项目吧，好在之前有整理过，从博客中选一个写上去，应该是写黄河鑫业的吧，这个参加的时间比较长，做的事情也很多，写上去应该可以提高面试率吧，感觉投了好多都是外包，不行就降点工资要求，14k也行，马上就是最后一天了，心情复杂，大华虽然大小周，感觉还是可以的我入职之后都没有员工主动离职，和之前呆的东方国信不一样，我才实习没多久除了领导其他人几乎换了一遍，好在那边双休，日常工作内容也很少，周五回家之后得上下午准备学习计划，要躺平也要等到三十五，现在找工作还算是好找点，等一会没人要了，我也攒下电钱该躺平就可以放心躺平了，真不敢想有房有车有孩子突然被裁了那该是怎样的心情，我现在只是暂时没工作了，啥时候找到没有经济上的压力，只不过是我个人的焦虑，工作总会有的，我也应该稍微自信点，实在不行我也13k，总能找到吧，现在也只能安慰自己了。', '2024-04-16', '2024-04-17 00:30:26', '2024-04-17 00:30:26', 1);
INSERT INTO `blog_diary` VALUES (1686, 1, '动漫版的大爱仙尊看完了，很上头，所以开始听小说。se', '2024-11-20', '2024-11-20 23:52:54', '2024-11-20 23:52:54', 1);
INSERT INTO `blog_diary` VALUES (1687, 1, '笔记还差好多，明天上午早点起来看看吧，今晚看的一个新动漫还挺好看。', '2024-07-14', '2024-07-15 00:07:34', '2024-07-15 00:07:34', 1);
INSERT INTO `blog_diary` VALUES (1688, 1, '今天就住招待所了，结果要我明天加班，屮。se', '2024-09-14', '2024-09-15 00:58:52', '2024-09-15 00:58:52', 1);
INSERT INTO `blog_diary` VALUES (1689, 1, '有点害怕了，人真的一定要结婚吗，为啥家里父母聊天都是说xxx家里多有钱，xxx一年可以赚几十万，这样活着真的有意思吗，有些害怕，会不会过几年之后我也会变成那个样子，人类都已经进化出可以思考的大脑了，为什么还要重复单调的结婚生孩子的生活，没有孩子有那么严重吗，想得太多真的好累啊，赚到100w就去摆烂，过我想要的生活，当前应该是有31w吧，很久没算我的存款了，当然我说的31w把公积金也算上了，毕竟可以取出来花的。', '2024-02-04', '2024-02-04 23:40:22', '2024-02-04 23:40:22', 1);
INSERT INTO `blog_diary` VALUES (1690, 1, '明天还要早起，晚上把博客那又改了点功能，mqtt这个命令下发有了新思路，我可以直接调用mqtt的注册客户端接口然后通过心跳报到博客，这样就可以准确控制每一个单片机的状态了，精确到传感器现在还没能力，不过也够了。se', '2024-09-30', '2024-10-01 00:24:04', '2024-10-01 00:24:04', 1);
INSERT INTO `blog_diary` VALUES (1691, 1, '数据迁移的那个工作现在只剩下对比数据了，这块工作现在不用我来处理了，剩下的就是我来改bug，今天过去看来又二十几个，我只能说尽力了，能改多少那不由我说了算，晚上差不多把王城探索完成了，本以为王城守门的boss会很强，结果俩个龙骑士来冒充boss，魂二还是探图路上更难一点，今天还被宝箱怪阴到了，这木头箱子我还不能像魂一一样直接来一刀，或者看宝箱怪的呼吸，不过魂二没试过看呼吸，不知道行不行。博客好久没写了，最近是真没时间，明天电脑带过去看看吧，有时间可以写一点。', '2024-10-09', '2024-10-10 00:27:30', '2024-10-10 00:27:30', 1);
INSERT INTO `blog_diary` VALUES (1692, 1, '今天出了点意外，之前一直弄得接口整理要先缓一下，明天优先测试新的接口。', '2024-12-25', '2024-12-26 00:56:56', '2024-12-26 00:56:56', 1);
INSERT INTO `blog_diary` VALUES (1693, 1, '喜提双休，下了一晚上地平线4，晚上都没打游戏。不想写公司的开发了，没啥意思，但是昨晚安全检查被发现光盘留在了外面，被抓到了，然后上午就开会说要重视，现在在公司那边电脑都不让放出来了，非常难受，今天电脑带过去就没掏出来过，之后暂时不带了吧，过一段时间再说。', '2024-10-25', '2024-10-26 00:23:56', '2024-10-26 00:23:56', 1);
INSERT INTO `blog_diary` VALUES (1694, 1, '上午没看51，下午简历倒是投了不少，有几个也联系过了，不知道啥时候能通过筛选。', '2024-06-04', '2024-06-05 00:09:58', '2024-06-05 00:09:58', 1);
INSERT INTO `blog_diary` VALUES (1695, 1, '北京下大雨，然后好多火车都停运了，明天晚上的火车是没戏了，只能八月一号走，明天和hr沟通下我下午过去办理入职。', '2024-07-30', '2024-07-31 00:36:24', '2024-07-31 00:36:24', 1);
INSERT INTO `blog_diary` VALUES (1696, 1, '这个假期黑魂一就白金完成了，提前庆祝。', '2024-04-04', '2024-04-05 01:34:06', '2024-04-05 01:34:06', 1);
INSERT INTO `blog_diary` VALUES (1697, 1, ' 晚上不瞌睡，然后又玩到不早了，魂一二周目了，怪伤害真高。', '2024-03-26', '2024-03-27 01:30:54', '2024-03-27 01:30:54', 1);
INSERT INTO `blog_diary` VALUES (1698, 1, '今晚李雨婷回来了，给让开房间，回我小家去了，明天继续面试。', '2024-05-26', '2024-05-26 21:32:38', '2024-05-26 21:32:38', 1);
INSERT INTO `blog_diary` VALUES (1699, 1, '昨天刚到家，晚上没开始收拾东西，所以就没写日记，昨天北京回来的时候那个出租车司机真坑，网约车都是七十块可以到，但是非要给我打表，收了我九十五块，再不打出租车了，还是网约车便宜点。', '2024-10-30', '2024-11-01 00:30:38', '2024-11-01 00:30:38', 1);
INSERT INTO `blog_diary` VALUES (1700, 1, '休息完回来上班第一天就是九点上班十点下班，整整十三个小时啊，然后还有俩小时的通勤时间，真tm是服了这b公司，赶紧找下家公司然后提离职流程吧，真受不了了，就这样加班领导还要卡转正。', '2024-11-04', '2024-11-05 00:10:38', '2024-11-05 00:10:38', 1);
INSERT INTO `blog_diary` VALUES (1701, 1, '放假，有事明天办。', '2024-01-26', '2024-01-27 01:06:24', '2024-01-27 01:06:24', 1);
INSERT INTO `blog_diary` VALUES (1702, 1, '今天学习stm32控制舵机，现在控制是可以了，但是每次都是转180度，我也不知道是啥原因，下次有时间继续看，晚上打黑魂2，又被打爆了，明天就要上班了。', '2024-09-17', '2024-09-17 23:52:24', '2024-09-17 23:52:24', 1);
INSERT INTO `blog_diary` VALUES (1703, 1, '周五早上六点多就起来赶往公司，公司离飞机场还挺远的，路上走了近俩小时，加上我还迷路，还好准时去了公司，感觉这个公司挺小的，就俩层楼，好像也就俩百多人不到，没办法已经签了合同就一直呆下去吧，预计一年半吧，原本以为的公积金是全额交的，结果签合同才发现是用的杭州最底工资的12%来交公积金，一个月也就600块的公积金，现在工资是13k，试用期三个月，试用期的工资的13k的90%，考虑到这个工作需要出差，而且据说是大部分时间都要出差工作，所以加上出差的每天80块补贴差不多也能接受，而且就算是不出差就在公司上班包午饭和晚饭，也算是好工作了，然后在公司办理完成入职手续，下午就开始出差，买的下午四点的火车票十二点多就火急火燎的从公司赶回宾馆去取行李，然后去杭州东站赶往台州，大概也就俩小时的路程，路上感觉浙江这边的山也很多，坐火车走河南河北的时候一路都是大平原，浙江还有很多穿山隧道，台州感觉城市也还不错，沿海城市但又好像不那么沿海，海滩那边好像都不是城市了（这块就不继续写了，应该写在今天的日记里），大概就是到了台州找到出差的房子，收拾了一下行李也不早了，没取出来电脑写日记。se', '2024-12-13', '2024-12-15 00:55:42', '2024-12-15 00:55:42', 1);
INSERT INTO `blog_diary` VALUES (1704, 1, '手机远程电脑，弄一晚上了还不行，明天再看吧，感觉睡觉。', '2024-03-18', '2024-03-19 01:28:10', '2024-03-19 01:28:10', 1);
INSERT INTO `blog_diary` VALUES (1705, 1, '开了电脑，但是懒得写，看了一天动画。', '2024-05-09', '2024-05-11 23:29:50', '2024-05-11 23:29:50', 1);
INSERT INTO `blog_diary` VALUES (1706, 1, '明天开始就可以晚上六点下班了，但是需要早上九点去了招待所，不过也挺好的，不用加班了，没啥特殊情况晚上大概八点多就回来了，最近bug单又多起来了，主要还是报表的数据问题，今晚算是把dlc2打完了，最后的boss血也太厚了，根本刮不动，有俩个boss，一个是熔铁恶魔，好像是这个名字，我技能都放没了，才掉1/4的血量，打我却是俩刀，另外一个找到了太阳兄弟帮忙过了，这个血也很厚，dlc2最恶心的是有好多怪死了还能复活，这我是真没办法打，死了能复活我玩锤子，只能看看大佬的攻略，dlc2应该还有一个boss没遇到，视频里面经常看到的一个用太刀的boss没找见，刚好有一个篝火也没发现，应该是一起的，可能是我哪块流程没注意忘了，还有就是这个图不仅怪能复活，还给我诅咒，血量上限也给我减，大不了一点，最近买的快递都差不多回来了，最近沉迷游戏不想学习，明天早下班有时间可以看看，新买的那个编码器我可以用这个来控制一些电源的开关，还有买的三极管，型号有很多，就是不知道功能有没有区别，外观是没看出有啥不一样的地方。', '2024-10-22', '2024-10-23 00:14:48', '2024-10-23 00:14:48', 1);
INSERT INTO `blog_diary` VALUES (1707, 1, '从今天上班时间改成了996，我是真服了，既不想晚上让人打车回家，又想要工作满十二小时，国庆之后要离职了，真的是一点都呆不下去，最近过去多准备下面试。今天调试esp8266完成了，at指令都可以正常下发，烧录的时候才发现一共买的这几个都是1M的存储，教程给的第一个文件烧录会提示空间不够，应该是这个原因，然后换了一个8bits的文件烧录可以了，明天开始准备搭一个es、dubbo和xxljob的项目，这个就当学习了，之后找工作把这几个的经验也写进去，睡觉了，明天还要早起，就不凑2k了。', '2024-09-09', '2024-09-10 00:33:48', '2024-09-10 00:33:48', 1);
INSERT INTO `blog_diary` VALUES (1708, 1, '今天工作的项目做花名册功能，顺便也学习了一下，然后晚上写博客前端的页面，弄了一晚上可算是弄好了，很有成就感今天应该是要多写几句的，但是现在不早了，今晚也没回宿舍去，就住在了招待所。', '2024-09-25', '2024-09-26 00:50:30', '2024-09-26 00:50:30', 1);
INSERT INTO `blog_diary` VALUES (1709, 1, '明天就要回家了，明天晚上因为在火车上，所以写不了日记，就用手机代替吧，希望不要因为下大雪火车停运了。家里的电子产品收拾之后感觉我也没多少东西。', '2024-02-01', '2024-02-02 00:01:16', '2024-02-02 00:01:16', 1);
INSERT INTO `blog_diary` VALUES (1710, 1, '今天工资单出了，这个月12k，还算可以吧，没啥支出，2k的加班费，这个是因为有上个月了，5百的节日福利，各方面待遇还算挺好的，公积金也高，就是太累了啊啊，今天也是十点多下班，都晚上了要我去中心。', '2024-10-14', '2024-10-15 00:22:52', '2024-10-15 00:22:52', 1);
INSERT INTO `blog_diary` VALUES (1711, 1, '这几天简历不投，也懒得学习。', '2024-07-18', '2024-07-19 02:49:28', '2024-07-19 02:49:28', 1);
INSERT INTO `blog_diary` VALUES (1712, 1, '拿下废渊，后面到boss附近了迷路半小时，一直没找到路在哪。', '2024-10-05', '2024-10-06 00:57:04', '2024-10-06 00:57:04', 1);
INSERT INTO `blog_diary` VALUES (1713, 1, '今天总结了笔记，下午出去骑车，可以认真准备学习还是得有个规律的作息，今天十二点关机也算是走出了第一步。', '2024-06-27', '2024-06-28 00:14:28', '2024-06-28 00:14:28', 1);
INSERT INTO `blog_diary` VALUES (1714, 1, '我tm真的是绷不住了，docker从服务器上下载好images文件本地解压不行，修改镜像源也不行，没想到那么多难点卡在了下载这一步，真服了啊，手机流量更慢，也不知道今晚挂一晚上能不能下载好，求求你了，别为难我了，就下载三个文件而已。', '2024-02-27', '2024-02-27 23:59:42', '2024-02-27 23:59:42', 1);
INSERT INTO `blog_diary` VALUES (1715, 1, '今天是发薪日，最近的到手工资都不够1w了，这个月才9.6k，最近要开始做1.1.5版本了，这个版本据说要三月三十就验收，但是现在还没开始做，只能说希望开发的业务少一点吧，不然又是无尽的加班，整整一个下午都在思考netty的服务端如何给客户端发送消息，我最开始希望把客户端注册上来的clientId作为客户端的唯一标识，虽然这个确实也是唯一标识，但是这个编码是系统生成的，每次重启客户端这个编码就会变化，我就不能使用这个编码来查找netty客户端，给客户端发送消息，所以这个是没办法修改的，但是我就查了一下午尝试修改这个编码，结果必然是失败了，最后我又加了一个缓存map，从客户端的心跳消息中获取到客户端信息，然后和这个客户端的通道进行绑定，这样我就可以在服务端指定发送的客户端了，但是这样好像多加一个netty客户端就需要修改代码，不过也对，加一个客户端对我来说就是要多加一个树莓派的设备，这样也满足我的需求，晚上就是参加巡检培训，有点听不下去，就坐那发呆，玩手机。', '2024-01-10', '2024-01-10 23:55:28', '2024-01-10 23:55:28', 1);
INSERT INTO `blog_diary` VALUES (1716, 1, '中午脑子一抽想着换一下数据库，结果把本地的数据库都删了，第一次体会到什么交删库跑路，因为我这是新开发的功能还没上线过，所以删了没办法恢复，所以一下午忙活终于又回到了代码开发的起点，然后stm连接8266的这个有偿找了一个大佬来帮忙看看，自己看效率实在是太低了，有时候确实得依靠下别人，晚上七点参加了杭州那个工作的复试，不知道面试结果咋样，明天下午五点还有一个面试，上午起不来，下午有时间继续写写博客文章，一直玩到现在才睡觉是因为三国杀我又下回来了，新出的一个模式玩的真是上头，根本停不下来。', '2024-12-06', '2024-12-07 01:11:48', '2024-12-07 01:11:48', 1);
INSERT INTO `blog_diary` VALUES (1717, 1, '摸鱼一天，都没投简历，闲着真舒服。', '2024-06-19', '2024-06-20 00:47:02', '2024-06-20 00:47:02', 1);
INSERT INTO `blog_diary` VALUES (1718, 1, '上班第一天，公司没通知离职，也没给任务，反正这几天我就慢慢投简历，找工作吧。今天加到了一个女网友，不知道以后会不会找我聊天。e', '2024-02-19', '2024-02-20 00:06:30', '2024-02-20 00:06:30', 1);
INSERT INTO `blog_diary` VALUES (1719, 1, '干到了通宵，现在缺氧这个档的主星不缺水电食物了，半永生。', '2024-08-24', '2024-08-25 02:43:40', '2024-08-25 02:43:40', 1);
INSERT INTO `blog_diary` VALUES (1720, 1, '看了一整天动漫，缺氧顺便也挂机一天，没想到我最重要的特拉瓦尔多挂了，厚葬之后因为规划我只能给挖了坟。', '2024-11-15', '2024-11-16 00:21:56', '2024-11-16 00:21:56', 1);
INSERT INTO `blog_diary` VALUES (1721, 1, '上周导入日记一直没成功今天晚上调试才发现是目录格式问题，修改之后成功导入，现在博客功能一切正常，不能长时间不管，现在没有写日志清理脚本，不管怎么说都是可以正常使用了，公司最近应该是没啥事情，从今天开始就整合硬件了，下午把mqtt和ftps接入了，目前测试都可以正常连接，ftps现在只做了上传文件，应该还会有删除文件，还有就是不知道ftps除了上传和下载还支持什么功能，最后就是客户端的没事干可以看看，这几天先把对接硬件的写好，这周把树莓派的家庭内部文件服务器搭好。', '2024-01-02', '2024-01-03 00:38:10', '2024-01-03 00:38:10', 1);
INSERT INTO `blog_diary` VALUES (1722, 1, '好烦啊，这几天面试不顺利，每天都不能静心学习，天天都在玩。se', '2024-04-28', '2024-04-29 00:39:18', '2024-04-29 00:39:18', 1);
INSERT INTO `blog_diary` VALUES (1723, 1, '今天上午去招待所，下午去军委处理数据，就是有好几百条数据对不上，不知道什么原因，我现在的查询条件是数据库中有当前组织的父id且没有当前组织的id，最后导致总数据差几百条没对应上，最好的情况是加起来正好等于缺少的数据，现在差一百多，我能想到的是因为大平台上那边删除了好多组织，而且是从上往下都删掉了，这样就会导致我只匹配到删除的组织里面最上面一条，下面的就匹配不到了，脑子有点混乱，明天过去再思考吧，理论上应该是完全匹配的，晚上把数据库的人员信息导入了一搬，大概还差150w条左右。', '2024-08-15', '2024-08-16 00:29:22', '2024-08-16 00:29:22', 1);
INSERT INTO `blog_diary` VALUES (1724, 1, '最近要去招待所那边上班了，这下终于不用点外卖了，就是晚上下班要晚到家半个多小时，而且也没有那种进度卡住了，七八点就下班的情况，好在项目快结束了，说的是九月六号，下周末吧，可以的话准备出去租房去，找个郊区一点的吧，住个单间或者楼房里面的单间独卫，今天博客这块弄好了oshi，计划是心跳中带上服务器的内存、cpu、硬盘等数据，可以实时检测服务器状态，最近游戏都不玩了，还是博客优先。', '2024-08-28', '2024-08-29 00:03:10', '2024-08-29 00:03:10', 1);
INSERT INTO `blog_diary` VALUES (1725, 1, '昨天坐火车回家，晚上在火车站所以没写日记，本来想着是把被子这些寄回家里，结果到了中铁快运的地点是一片工地，只能我自己带一大包行李回家了。', '2024-11-11', '2024-11-12 23:32:06', '2024-11-12 23:32:06', 1);
INSERT INTO `blog_diary` VALUES (1726, 1, '最近真忙啊，烦死了，晚上打小隆德遗迹被女鬼抓破防了，就像赶紧通关二周目，但是二周目的伤害真的高，早知道就多刷会了。', '2024-03-29', '2024-03-30 00:20:32', '2024-03-30 00:20:32', 1);
INSERT INTO `blog_diary` VALUES (1727, 1, '玩了一天缺氧，完成了土食和肉食成就。se', '2024-04-24', '2024-04-25 00:28:12', '2024-04-25 00:28:12', 1);
INSERT INTO `blog_diary` VALUES (1728, 1, '喉咙这块好不舒服啊，不知道咋回事，感觉最近又严重了，之前都快没感觉了，但是现在都有点影响正常工作，是不是最近压力大，又上火了，明天过去多喝点水。今天在公司主要就是调试pdf文件的导出，现在数据应该是没太大问题，主要是样式的问题，还有就是要测一下异常的情况，之前写的士兵信息审核上报就测过一次全流程，后来加上了审核通过的人员数据还没有全流程测试过，明天过去也要看下，晚上回来把es整合spring boot弄好了，之前计划的是用spring boot3.x的版本，但是要使用3.x需要更新的jdk，下午尝试装了一下，但还是放弃了，因为我现在就一台电脑，最近也没时间折腾，要是这个环境出了问题就麻烦大了，所以整合es这些的计划都改成了用spring boot2.x的版本，当然是用的2的最后一个版本，晚上测试es各种数据查询都可以正常执行，之后要是用到项目里面肯定还要再学习具体的方法怎么用，计划的博客3.0版本是要把redis、mq等一些各个模块通用的组件封装到一个jar包里面，然后其他模块要使用这些功能既不用配置，又可以使用全功能，这个不知道我的设想可行不可行，我猜应该没问题，这个场景也不罕见，应该会支持的，今天es整合好了，明天可以看看es的一些查询方法要怎么用，还有一件事，要我提供些入职的材料，今天有个领导找我要这些东西，明天一起带上去公司那边准备吧，尽量不浪费在宿舍的自由时间。就这样，睡觉了，发工资之后想先买一个steamdeck，3k感觉也不是很贵，steam的游戏都可以玩，还可以和电脑端同步。', '2024-09-10', '2024-09-11 00:21:48', '2024-09-11 00:21:48', 1);
INSERT INTO `blog_diary` VALUES (1729, 1, '还是好累啊，但是今天请到了假，可以回家休三天再加上周末一共是五天，明天回家的车票都买好了，这次回家把那个显示屏带回去吧，反正也用不到，之后租房还不知道是啥情况，最近想买一个二手的五菱宏光，住车里面我也可以接受，又没啥大的影响，我的行李也很少，洗澡可以去大澡堂，还有就是住车里面想去哪开车就可以直接过去，也可以不用晚上还想着回家时间，只要第二天上班前可以到就行，这几天回家先开车看看，我是觉得没啥问题，现在攒的钱我也可以买个车，二手的也很便宜。', '2024-10-29', '2024-10-30 00:12:00', '2024-10-30 00:12:00', 1);
INSERT INTO `blog_diary` VALUES (1730, 1, '昨天晚上回去也没开电脑，最近博客的进度还算凑合吧，毕竟最近的工作压力这么大，有时间写就不错了，明天又盼来了期待已久的周日，希望这段加班的时间快点结束吧。', '2024-09-06', '2024-09-07 17:05:52', '2024-09-07 17:05:52', 1);
INSERT INTO `blog_diary` VALUES (1731, 1, '今天进度有点慢，就做了五个页面，好在今天午饭和晚饭都是我做的，也算是可以理解吧。e', '2024-02-08', '2024-02-09 00:09:26', '2024-02-09 00:09:26', 1);
INSERT INTO `blog_diary` VALUES (1732, 1, '今天也是俩个接口，不过因为没有对接大平台，现在至只是完成了，自测完成，没有和前端一起联调测试，晚上开始开发几个导出文档的接口，听说政审完成之后要去另一个地方，希望那边不会加班太久，再就是希望伙食好点。se', '2024-08-07', '2024-08-09 23:51:16', '2024-08-09 23:51:16', 1);
INSERT INTO `blog_diary` VALUES (1733, 1, ' 状态不佳，每天都是最不想上班的一天。', '2024-04-07', '2024-04-08 00:17:16', '2024-04-08 00:17:16', 1);
INSERT INTO `blog_diary` VALUES (1734, 1, '下午出去开车去忻州，一路上大概80公里吧，感觉还可以，就是放离合起步还是不习惯，明天下午再去试试，晚上缺氧开始跨星球探索了，先挖空一个星，现在找水星做超冷，然后开氢氧火箭。', '2024-11-24', '2024-11-24 23:59:10', '2024-11-24 23:59:10', 1);
INSERT INTO `blog_diary` VALUES (1735, 1, '妈的好累，今日全是事，项目上要看在线端和离线端，为了一个小的功能要了解整体全部的业务流程，之前开发的人走了，这做起来真绝望，下午面试的感觉一般，明天下午还有一个，然后今天还有一个首钢的面试，但是只能开到10-11k还是在北京，而且还没编制，签第三方公司，妥妥的牛马，其它城市还行，北京拿这个工资一个月都剩不下多少。', '2024-11-07', '2024-11-07 23:59:42', '2024-11-07 23:59:42', 1);
INSERT INTO `blog_diary` VALUES (1736, 1, '发了工资，一共5.07w，但是没在邮箱里面收到离职证明，等下周一我再去问问。', '2024-05-10', '2024-05-11 23:40:20', '2024-05-11 23:40:20', 1);
INSERT INTO `blog_diary` VALUES (1737, 1, '虽说是周末，但是过的也真累啊，去西湖压马路走了走，晚上回家也没什么动力收拾，简单的上传了docker部署的脚本，看看能不能安装好，因为docker下载镜像文件经常失败，是要改镜像解压导入安装吗，或者可以试试配置下docker下载的镜像源，躺下看动漫了，能不能下载好明天再说。', '2024-03-03', '2024-03-03 23:24:08', '2024-03-03 23:24:08', 1);
INSERT INTO `blog_diary` VALUES (1738, 1, '又玩了一天，明天得认真学习准备面试了，下午跑欧卡一千多公里。', '2024-06-01', '2024-06-01 23:53:12', '2024-06-01 23:53:12', 1);
INSERT INTO `blog_diary` VALUES (1739, 1, '今天上午过去体检，之后去拍身份证照片，从南城跑到北城，最后是因为身份证离过期还有段时间，要是今天办还是属于补办，只好下次有机会再办了，下午过去修改了下工商银行的身份信息，取回来了体检报告，今天一一天还挺忙的，明天就收拾家里吧，准备好行李，周三晚上的车票都买好了。se', '2024-07-29', '2024-07-30 00:15:40', '2024-07-30 00:15:40', 1);
INSERT INTO `blog_diary` VALUES (1740, 1, '今日无事，回村、逛街。', '2024-02-12', '2024-02-12 23:55:32', '2024-02-12 23:55:32', 1);
INSERT INTO `blog_diary` VALUES (1741, 1, '明天下午有个面试，上午在准备一下。', '2024-07-22', '2024-07-23 00:26:56', '2024-07-23 00:26:56', 1);
INSERT INTO `blog_diary` VALUES (1742, 1, '飞机到期了，晚上回来换了一个机场，现在这个还有半年和旭福一起买的，v了40。一天也没做太多事情，下午给了一个整理文档的任务，做完就四点多了，然后就优化接口，本来计划今天是整理云盘这块，但是这个功能现在还不是很稳定，等把同步功能做完再说吧，晚上把商家重发的51下载器取回来了，测试了其中一个单片机是正常的，另一个懒得看，睡觉了，最近不知道为啥又开始胃酸，嗓子这还是有异物感，要不再去看看医生吧，是不是因为我平时喝的水少了，最近白天都很渴，一天能喝好几杯。', '2024-01-17', '2024-01-18 00:35:30', '2024-01-18 00:35:30', 1);
INSERT INTO `blog_diary` VALUES (1743, 1, '找群友玩私服dnf，爆肝到了现在，主要是上午和下午都在睡觉，晚上不瞌睡。', '2024-06-08', '2024-06-09 02:08:08', '2024-06-09 02:08:08', 1);
INSERT INTO `blog_diary` VALUES (1744, 1, '干了一天吸血鬼幸存者，真上头。', '2024-12-21', '2024-12-22 00:47:48', '2024-12-22 00:47:48', 1);
INSERT INTO `blog_diary` VALUES (1745, 1, ' 魂一一周目也快结束了，晚上的王城那个boss真难打啊，想挑战下难度较高的打法，结果被虐爆了，好在最后还是过了，然后又下了墓地。e', '2024-03-22', '2024-03-23 01:15:36', '2024-03-23 01:15:36', 1);
INSERT INTO `blog_diary` VALUES (1746, 1, '又是一天，前几天面试的那个外包估计也没戏了，离职一个月了。', '2024-05-17', '2024-05-18 00:00:58', '2024-05-18 00:00:58', 1);
INSERT INTO `blog_diary` VALUES (1747, 1, '睡在睡袋里面还是稍微有点冷，那别人都野外是怎么熬过去的，这几天都没开发任务，明天之后我就准备开发博客的socket相关功能吧。', '2024-12-17', '2024-12-17 23:43:38', '2024-12-17 23:43:38', 1);
INSERT INTO `blog_diary` VALUES (1748, 1, '一天也不知道干了些啥，床上躺了一天还是很累，早知道脱衣服钻被窝了。', '2024-04-13', '2024-04-14 00:30:04', '2024-04-14 00:30:04', 1);
INSERT INTO `blog_diary` VALUES (1749, 1, '又不早了，下班回家就九点多了，休息了一会就开始测试部署脚本，今天还没有jar包测试，先只是简单的压缩包安装，应该是问题不大，添加了几个配置文件，现在看着下载日志还是决定服务器也用导入文件下载docker镜像吧，现在环境上加了三个镜像地址还是会有时候下载不到镜像文件，还是存在点问题，太晚了状态不好，今天一天都没啥进度，下午和晚上都在加班做工作台项目，移植了非常多的文件，还看到公司项目中使用到了LiteFlow，这个也算是学到了把，引擎框架使用不是很难，等之后部署完成可以尝试用用。', '2024-03-05', '2024-03-06 00:42:06', '2024-03-06 00:42:06', 1);
INSERT INTO `blog_diary` VALUES (1750, 1, '写点啥啊，找不到工作，好烦。', '2024-06-21', '2024-06-22 01:38:06', '2024-06-22 01:38:06', 1);
INSERT INTO `blog_diary` VALUES (1751, 1, '今天到家又是不早了，十点四十才下班，差点都赶不上地铁了，晚上回家还算有点精神，稍微开了一会缺氧，明天过去主要是看数据同步，然后就是该xxljob的配置，最近就没啥想写的日记，等之后换电脑吧，都想换好久了，现在是因为没租房子。', '2024-08-21', '2024-08-22 00:34:32', '2024-08-22 00:34:32', 1);
INSERT INTO `blog_diary` VALUES (1752, 1, '前几天网友给的那个mqtt至少是先下载到stm32上面了，接下来调试应该问题不大了吧，明天优先弄接口，测试的用例之后再写。', '2024-12-26', '2024-12-27 00:21:58', '2024-12-27 00:21:58', 1);
INSERT INTO `blog_diary` VALUES (1753, 1, '服了啊，明天周日还要上班，我tm是真的无语了，啥时候是个头啊。', '2024-09-21', '2024-09-22 00:09:16', '2024-09-22 00:09:16', 1);
INSERT INTO `blog_diary` VALUES (1754, 1, ' 黑魂一全成就通关了，虽然最后一个收集的成就借助了网友的力量，但其它都是我手打的，然后晚上购买了黑魂二，不得不说这个操作虽然丝滑了，但是这个使用手柄玩的真累，键鼠由不怎么支持，真烦人。', '2024-04-05', '2024-04-06 00:37:16', '2024-04-06 00:37:16', 1);
INSERT INTO `blog_diary` VALUES (1755, 1, '实在是太难了，一晚上没把程序烧录进去，我开始怀疑是单片机的问题，我都是跟着教程来的，为啥我这不行啊，明天继续看。', '2024-01-05', '2024-01-06 00:38:10', '2024-01-06 00:38:10', 1);
INSERT INTO `blog_diary` VALUES (1756, 1, '黑魂真好玩，我的双手巨剑一刀一个，太爽了。', '2024-03-21', '2024-03-22 00:29:04', '2024-03-22 00:29:04', 1);
INSERT INTO `blog_diary` VALUES (1757, 1, '今晚聚餐，加班一天，三倍工资应该是有了吧，按照我一天500的工资计算，今天得有1500，整个国庆都要加班的话，那能拿到(3*3+2*4)*(10400/22)=8036块，卧槽啊，七天给我干一张4080出来，真开心，今天博客加了http请求mqtt服务器的接口，现在单片机的状态也可以拿到了，博客功能越来越完善了，有时间一定要把stm32的功能完成，今天睡觉了，明天要早点上班，要九点到，出发那得是七点半。', '2024-10-01', '2024-10-02 00:31:16', '2024-10-02 00:31:16', 1);
INSERT INTO `blog_diary` VALUES (1758, 1, '上午有个面试太水了，我都不知道要怎么回答，估计是没戏，下午下棋上头了，就用电脑上的手机模拟器，永恩太强了，不过明天就被削了。', '2024-06-05', '2024-06-05 21:58:02', '2024-06-05 21:58:02', 1);
INSERT INTO `blog_diary` VALUES (1759, 1, '明天双休，约了超凡一起出去玩，总算是可以休息了，最近上班也不忙，今天一整天都是在那发呆，一直到晚上才有事情可做，晚上把几个树人的回忆探索完成了，然后找dlc没找到，去了熔铁城但是打不开门，另一个说是在黑溪谷，但是过去没找见。e', '2024-10-18', '2024-10-19 00:15:32', '2024-10-19 00:15:32', 1);
INSERT INTO `blog_diary` VALUES (1760, 1, '三天看完了俩部动漫，真累啊，明天就继续投简历和学习了。', '2024-11-18', '2024-11-18 22:49:34', '2024-11-18 22:49:34', 1);
INSERT INTO `blog_diary` VALUES (1761, 1, '总算是放假了，明天赶紧把新版的博客部署测试下，今天买了一个土豆兄弟，玩了一会感觉没啥意思又退款了。', '2024-02-23', '2024-02-24 00:16:34', '2024-02-24 00:16:34', 1);
INSERT INTO `blog_diary` VALUES (1762, 1, '今天几乎没啥事情，不过过几天应该所有开发都要去中心改bug了，应该等bug改差不多就可以不加班了吧，今天没做啥事情，主要就是下午听大佬讲es同步大平台数据这块的业务功能，别人写的，一时半会也看不懂，晚上就看着之前的代码照猫画虎写了一点，明天还有时间去理代码流程，就是不知道明天学城会不会给新的任务，晚上回来不想看代码，啥事情都不想看，就一直没开电脑，现在要睡觉了才打开写日记，今天计划是装dubbo的，但是因为看代码了，再就是dubbo好像也涉及到注册中心，现在还没搞清楚dubbo和nacos的区别，应该是可以一起使用的，明天有时间继续研究，最近这边的工作还行，暂时感觉可以不找工作了，还有大家都说的软考，也不知道要不要考，反正写代码也写不了几年，以后也就只能进小公司，更看重实际的业务能力吧，而且我也不会进国企，稍微了解下吧，应该是不回去认真准备去考证的。', '2024-09-11', '2024-09-12 00:23:52', '2024-09-12 00:23:52', 1);
INSERT INTO `blog_diary` VALUES (1763, 1, '今天没做太多事情，一整个上午就处理更新MySQL版本了，开始我还疑惑为啥我习惯装d盘的人把MySQL装到了c盘，结果一上午的测试才知道是因为d盘装不了，公司系统盘是远程的，可以是这个原因导致的安装失败，下午准备写错误校验，整理接口，加了几个注解。晚上开会的时候想了想最近的工作计划，以博客部署脚本为主，在公司没办法写这些脚本，优先更新接口，添加接口参数校验，最近以及之后在公司晚上开发的一段时间就以整理代码为主，准备过年写接口文档，晚上把树莓派安装centos的笔记写上去了，今天没什么想写的东西，最后就把今天晚上整理的开发计划粘上来吧。博客开发优化1. 参数校验 优先级低2. 接口文档 优先级低3. 文章支持添加附件文件 优先级中4. 印象笔记 日常记录笔记总结，写入博客 优先级中5. 博客主题docker脚本编写 优先级高6. pi接入传感器 优先级高7. 博客设置功能开发 优先级中8. 文件云盘目录共享功能 优先级中9. 系统重启后服务重启脚本 优先级中10. 前端日历功能，展示文章文档日记 优先级低11. 前端工作台功能，处理待办事项 优先级低', '2024-01-15', '2024-01-16 00:35:56', '2024-01-16 00:35:56', 1);
INSERT INTO `blog_diary` VALUES (1764, 1, '没事干的日子要结束了，今天开始看皮带项目，准备开发1.1.5版本了。se', '2024-01-23', '2024-01-23 23:49:56', '2024-01-23 23:49:56', 1);
INSERT INTO `blog_diary` VALUES (1765, 1, '下午开车回村里走了一圈，村里路太窄了，走的感觉还有点害怕，今天算是全程开车出去的，从小区门口走了一圈开回了车库门口，可能是今天转弯时就怕碰到，所以一直都是转的大弯，晚上弄树莓派的电视盒子，但是一直是有问题，启动的时候报错了，跟着好几个教程学习的，但是都是有问题，可能是过去时间久了，教程和现在的安装流程有些差距。se', '2024-12-01', '2024-12-01 22:13:04', '2024-12-01 22:13:04', 1);
INSERT INTO `blog_diary` VALUES (1766, 1, '昨晚是真累，晚上回来电脑都没开，一天没啥重要事情，但是晚上回来就是累，下周说的政审完成要去另一个地方处理数据，还不知道是啥情况。', '2024-08-03', '2024-08-04 09:56:32', '2024-08-04 09:56:32', 1);
INSERT INTO `blog_diary` VALUES (1767, 1, '好累啊，头疼了一天，真的不想再上班了，一直就想等国庆加班的工资发下来然后离职，但是真坚持不下去了，反正领导也说我不配合其他人工作，天天工作那么久哪有精力思考那么多，能保证我这块没啥大问题就不错了。', '2024-10-28', '2024-10-28 23:58:52', '2024-10-28 23:58:52', 1);
INSERT INTO `blog_diary` VALUES (1768, 1, '今天下午有个面试，这个是之前约的写文档相关的工作，感觉还行，但是估计也不会要我，晚上随便出去走了会。', '2024-06-11', '2024-06-12 01:42:20', '2024-06-12 01:42:20', 1);
INSERT INTO `blog_diary` VALUES (1769, 1, '明天小周，没想到今天是周五，我一直以为是周四，直到晚上餐厅吃饭才发现周五了，喜提周末，可惜明天小周，今晚把各种游戏都打开玩了一小会，电脑不行了，玩个泰拉都掉帧，赶紧换电脑吧，先面试找到北京的工作，杭州也行，只要涨工资就行，下午还收到一个面试，约的是下周三晚上，说是要做算法题，先稍微看看吧。', '2024-03-15', '2024-03-16 00:06:50', '2024-03-16 00:06:50', 1);
INSERT INTO `blog_diary` VALUES (1770, 1, '今天休息一天，然后明天上一天班，下周还有三天，之后就准备回家吧，周末去公司把显示屏带回来，还有其他该收拾的也拿上，睡了吧，明天还要上班。', '2024-04-11', '2024-04-12 00:42:24', '2024-04-12 00:42:24', 1);
INSERT INTO `blog_diary` VALUES (1771, 1, '停了一天电，今天早点睡，明天上午去练车。', '2024-06-15', '2024-06-16 00:38:02', '2024-06-16 00:38:02', 1);
INSERT INTO `blog_diary` VALUES (1772, 1, '昨天竟然没写日记，可能是聊天忘记了，补一下，但是昨天也没啥事情，最近公司项目发测，要改bug，博客项目就测试下以前写的很多需要服务器的功能。', '2024-03-11', '2024-03-12 23:06:52', '2024-03-12 23:06:52', 1);
INSERT INTO `blog_diary` VALUES (1773, 1, '睡了一下午，晚上又不瞌睡了，晚上买了一个求生之路2，以后有时间再玩，周末过去了，明天继续找工作。e', '2024-07-07', '2024-07-08 00:00:04', '2024-07-08 00:00:04', 1);
INSERT INTO `blog_diary` VALUES (1774, 1, '工作确定了，就去杭州这个公司，没想到转了一圈又会杭州去了，一个月13k，出差一天有80块的补助，然后这次去了杭州直接就在公司入职然后去台州出差去，台州是沿海城市，这次过去看看大海，这么多年第一次看，都块三十了，今晚李雨婷回来了，所以就早点关电脑给让给出这个房间。', '2024-12-11', '2024-12-11 22:00:48', '2024-12-11 22:00:48', 1);
INSERT INTO `blog_diary` VALUES (1775, 1, '罕见啊，今晚回来都懒得开游戏，虽说这几天工作不忙，我这一下午还是一直都是有活干的，主要是八个报表里面数据实在是太多了，数据也没有一个详细的文档指定取哪个字段，所以只能是多次修改，再加上测试还挺费时间的，最近开发博客也没什么计划，下一步硬件上就是要把8266接到stm32上了，软件的开发那就是解析设备的心跳数据，然后用echars图表展示出来，今天前端已经开始了，界面展示也还行吧，不是很难，echars的问题很详细。', '2024-10-24', '2024-10-24 23:47:16', '2024-10-24 23:47:16', 1);
INSERT INTO `blog_diary` VALUES (1776, 1, 'md又开始怀疑人生了，今天开始了投简历，也就看了一会，明天要回村里面。se', '2024-05-07', '2024-05-08 00:55:22', '2024-05-08 00:55:22', 1);
INSERT INTO `blog_diary` VALUES (1777, 1, '今天面试又不太行，我还是暂停下总结笔记吧，笔记里面写的都不是面试要问的东西，整理用处不大，今天问的redis、mysql和netty的面试题都不太懂，每天还是总结背题吧，找工作重要，今天买了七日杀，玩了一下有点晕，还是不太适应，当然决定我退款还是因为跳到了一个房子里面，但是操作太僵硬了，进去出不来，真的无语了能让人进去，结果不允许从内测开门，真的是服了。', '2024-04-23', '2024-04-24 00:20:30', '2024-04-24 00:20:30', 1);
INSERT INTO `blog_diary` VALUES (1778, 1, '终于到家了，现在是半夜一点，把一系列环境搭建好了，但是发现mqtt写入失败，真是无语，还没找到原因。', '2024-02-03', '2024-02-04 01:02:56', '2024-02-04 01:02:56', 1);
INSERT INTO `blog_diary` VALUES (1779, 1, '今天俩个面试都给我鸽了，下午就睡觉了。se', '2024-07-01', '2024-07-02 00:32:24', '2024-07-02 00:32:24', 1);
INSERT INTO `blog_diary` VALUES (1780, 1, '今晚还是忍住了，没有开游戏，今天早点睡觉，这俩周游戏时间太长了。', '2024-03-25', '2024-03-25 23:20:38', '2024-03-25 23:20:38', 1);
INSERT INTO `blog_diary` VALUES (1781, 1, '今天也是睡觉，真的自从入职这家公司天天加班，周末根本休息不过来，请了三天假加上周末一共五天都是在家躺着，今天感觉好多了，但是明天又要开始上班，人活的意义就是为了上班吗，我现在的目标就是攒够差不多的钱，工作到三十五六就开始躺平吧，以后反正程序员也找不到工作，攒够钱吃利息也能活下去，b站上看到了好多流浪的up，不知道是真的流浪还是为了拍视频而展示自己流浪，拍完就回酒店那种，不写了，收拾一下今晚九点十五的火车，明天到北京是早上五点，反正是误不了上班。se', '2024-11-03', '2024-11-03 21:56:24', '2024-11-03 21:56:24', 1);
INSERT INTO `blog_diary` VALUES (1782, 1, '周日休息，住着的这个舍友真恶心人，一下午打游戏一直晃桌子，说了好几次都不停，那我只能是也开始恶心下他了，今天也写了不少代码，下午把设备消息上报流程弄好了，新版的这个消息结构可以适应一个单片机下装很多同类设备然后下发控制，也可以结束多个同类型设备上报的消息，主要是加上了传感器的编码，单片机和传感器的编码我想做成可以自己设置的，因为单片机这些都是通过树莓派类型的设备上报的消息，设备的编码我控制系统生成就行了，还加上了用户名确保唯一，其实这个用户名不加也不会有太大影响，因为32位uuid几乎是不可能重复的，一共三十二位，每位有有三十六个选项，就我这些设备，真的生成重复的uuid，我觉得我可以去买彩票了，下一步应该是处理redis吧，之前一直说的项目中也用到了redis，但是只用来存储生成的token，现在把redis统一之后配置到每一个项目里面，传递消息相比mq更高效一些，还有服务间调用的openfeign和dubbo用来调用接口，具体情况具体使用吧，现在整理下已经写好的业务，写好注释。', '2024-09-01', '2024-09-02 00:54:12', '2024-09-02 00:54:12', 1);
INSERT INTO `blog_diary` VALUES (1783, 1, '买了上古卷轴5，刚下好打开试了下好像没有中文。', '2024-05-25', '2024-05-25 23:25:42', '2024-05-25 23:25:42', 1);
INSERT INTO `blog_diary` VALUES (1784, 1, '讲完ppt咯，好紧张，那么多人看着，还好可以讲一点，然后讨论一会，凑合着算是完成了。缺氧开发硫泉我是真呆啊，早完了才发现弄错了，冷却温度不对，只能重来。明天开发啥功能呢，最近没事干，树莓派的文件同步优先吧，要是可以真想把树莓派带到公司。e', '2024-01-09', '2024-01-10 00:07:12', '2024-01-10 00:07:12', 1);
INSERT INTO `blog_diary` VALUES (1785, 1, '一个人在家就会怀疑人生，不懂为啥要活着，活着有什么意义，生活只有负重前行，真的我要是有能力真想毁灭地球。', '2024-02-17', '2024-02-18 00:30:16', '2024-02-18 00:30:16', 1);
INSERT INTO `blog_diary` VALUES (1786, 1, '离职第一天就没有好好休息，明天先修改简历，投简历和准备收拾东西搬家，还是决定下一份工作去北京吧，杭州实在是太远了，我也不知道吐槽了多少次这个距离了。', '2024-04-17', '2024-04-18 01:27:36', '2024-04-18 01:27:36', 1);
INSERT INTO `blog_diary` VALUES (1787, 1, '昨天的问题解决了，是因为nacos默认的连接时间是1秒，稍微有点网络延迟就连不上了，所以我改成了连接等待十秒钟，这个问题就算是解决了，然后今天继续昨天部署成功的就行测试没想到失败了，最后看nacos的日志排除是因为我docker容器的名字有问题，我的名字中带点就是这个符号(.)，然后连接MySQL的时候把我名字里面的点识别了判定字符，导致识别不到网络，这个修改之后部署就没太大的问题了，下午玩了一会儿游戏，开了一个长途，1300公里，欧卡开太久还是会无聊的，一下午就是测试部署，现在部署一次大概20分钟，有3分钟是在等待服务启动，这个没办法优化，剩下花费时间的主要是下载镜像文件和导入sql文件，这俩个也没办法优化，而且以后博客越用数据越多，sql导入的速度只能是越来越慢，博客就写到这了，明天的任务是调试完成netty连接。明天要是天气好可以出去稍微骑一会车，明天还要修改下简历，工作还是要抓紧时间去找的，简历稍微写的多一点吧，把了解过会用的技术都写上去，一直没拿到offer心里还是会有点失落的，至少得先收到offer然后再去挑。好像写一句，今天天气好，晒了一下午被子，等会睡觉感受下会不会更舒服点。', '2024-03-09', '2024-03-10 00:37:44', '2024-03-10 00:37:44', 1);
INSERT INTO `blog_diary` VALUES (1788, 1, '休息一天，还算可以吧，没打游戏，可能是最近太累了，准备了看视频继续学习51单片机的但是没啥心情，下午就洗洗衣服，把家里的温湿度传感器和舵机控制又连上来了，稍微优化了下控制的代码，玩着感觉还挺开心的。', '2024-03-31', '2024-04-01 00:08:38', '2024-04-01 00:08:38', 1);
INSERT INTO `blog_diary` VALUES (1789, 1, '外包的这个工作还是拒绝了，996估计去了也是后悔。', '2024-05-31', '2024-06-01 01:13:20', '2024-06-01 01:13:20', 1);
INSERT INTO `blog_diary` VALUES (1790, 1, '国庆假期没了，我草泥马啊，是甲方要求强制加班，真尼玛服了，以后再也不找军队的这种项目了，b事真多，晚上回来把传感器控制组页面的接口调用的数据加上了，目前看起来还有那么一点感觉，累了，睡觉。', '2024-09-26', '2024-09-27 00:03:46', '2024-09-27 00:03:46', 1);
INSERT INTO `blog_diary` VALUES (1791, 1, '缺氧加大爱仙尊，一天过去了。', '2024-11-21', '2024-11-22 01:19:56', '2024-11-22 01:19:56', 1);
INSERT INTO `blog_diary` VALUES (1792, 1, '马斯克的星舰都回收成功了，我还在加班，真tm服了，现在都连上十几天了，一下都不让休息，今天对了一天的数据头疼，晚上还要催我改bug，一个人负责这么多，然后还要催我完不成，bug多，这个模块都是五六个人一起开发的，写完一堆屎山都走了，留我一个人看，我的也算是屎山代码，至少这个还没让别人吃，妈的服了啊，这个项目黄了算了，一堆垃圾代码，都他妈舍不得招人，现在的员工就往死里压榨。', '2024-10-13', '2024-10-14 00:07:30', '2024-10-14 00:07:30', 1);
INSERT INTO `blog_diary` VALUES (1793, 1, '今天的笔记写的有点少，就做了Java基础和mybatis，明天得多写点。', '2024-07-13', '2024-07-14 00:25:20', '2024-07-14 00:25:20', 1);
INSERT INTO `blog_diary` VALUES (1794, 1, '求职的若干天，依旧没有希望。', '2024-05-13', '2024-05-13 23:54:14', '2024-05-13 23:54:14', 1);
INSERT INTO `blog_diary` VALUES (1795, 1, ' 服务器重新部署成功，晚上玩七日杀睡的晚了。', '2024-06-26', '2024-06-27 02:22:16', '2024-06-27 02:22:16', 1);
INSERT INTO `blog_diary` VALUES (1796, 1, '原来的位置被占了，晚上没玩电脑，所以日记也没写。e', '2024-05-18', '2024-05-20 00:02:30', '2024-05-20 00:02:30', 1);
INSERT INTO `blog_diary` VALUES (1797, 1, '明天就要上班了，不知道会不会通知我离职，去了再说吧，混一天算一天，最近找北京的工作。', '2024-02-18', '2024-02-19 00:17:14', '2024-02-19 00:17:14', 1);
INSERT INTO `blog_diary` VALUES (1798, 1, '今天家里人全回来了，早点关电脑，晚上就不能打游戏了。', '2024-06-09', '2024-06-09 20:16:04', '2024-06-09 20:16:04', 1);
INSERT INTO `blog_diary` VALUES (1799, 1, '好无聊啊，2024年的第一天就这么烦人吗，游戏不想打，啥也不想干，准备写几篇软件安装的文章，但是因为只有一台电脑不能随便安装截图，等之后买电脑再写吧，反正这个东西跑不了，洗洗睡吧，准备明天上班。今天下午完成了2023年的年终总结，给今年定的学习方向的我的树莓派服务部署，也就是要搞mqtt和ftps了，树莓派的边缘还要搞硬件，也就是接点传感器吧，这个需要花点时间去研究的。', '2024-01-01', '2024-01-01 22:44:16', '2024-01-01 22:44:16', 1);
INSERT INTO `blog_diary` VALUES (1800, 1, '最近一直没状态写博客，偶尔过个周末，但是因为一周太累了，完全没有心情写代码，今天上午和下午都在玩缺氧，晚上稍微有时间看了看stm32，我现在想想我要做一个什么模块，因为我学这个完全是因为需要才学习的，不可能按照教程全部跟着学下来，毕竟吃饭的工具还是Java，做这个只能说是爱好，不能花太多时间在这上面，总体来说想要做个家庭信息检测站，首先就希望每个板子上面都有一个电量检测模块，因为总不能每天去检查这些板子有没有电，剩下的模块就是对应不同板子实现具体功能了，现在优先级最高的一个板子应该就是舵机控制电脑开机这个，代码其实已经做过一次了，之前用到的板子是arduino的wifi板子，王鹏推荐的那一块，现在切换到了stm32，用stm32控制舵机差不多也能做到了，看过了江科大的教程，然后这个板子上还要有一个摄像头用来拍照确认操作是否成功，还有一个模块是光敏电阻模块，这个是将模块对着电脑的机箱开机指示灯，确认关机之后控制拍照，确认电脑成功关机，电脑控制的核心模块就这三个，其它的可以加一些传感器，机箱温度的，机箱噪音大小的，主要就这几个吧，想不到其他模块了，还有那就是stm32接esp8266的功能，一共是六个外接模块，想的是画一个pcb板子，然后把这些东西都接上去，在用建模弄一个壳子，第一个模块就算是完成了，现在是第一步电源电量这个就卡住了，网上看到俩种方法，一个是用模块的adc接口测电源电压，然后就线性拟合，这个精度应该很差，电池电量变化肯定不是线性的，再就是看到用库仑计计算充电总量，放电总量这样，看这个写法那我也完全可以通过大数据计算啊，计算每次各种命令调用的情况，用个几个月大概一个模块电量可以坚持多久完全可以推断一个范围出来，考虑到电池容量会变小，测电池电压还是必须的，模块整体就是这样吧，后端的代码也需要修改，如果要完全实现不得不做一个app出来了，这个有时间在考虑下实现，今天先写这些，睡觉了。', '2024-08-25', '2024-08-26 00:09:26', '2024-08-26 00:09:26', 1);
INSERT INTO `blog_diary` VALUES (1801, 1, '下午没心情学习，开了一下吸血鬼幸存者然后突然就天黑了。se', '2024-12-22', '2024-12-23 01:23:10', '2024-12-23 01:23:10', 1);
INSERT INTO `blog_diary` VALUES (1802, 1, '看动漫有点晚了，不过下午睡了一觉，不瞌睡。', '2024-11-14', '2024-11-15 02:15:40', '2024-11-15 02:15:40', 1);
INSERT INTO `blog_diary` VALUES (1803, 1, '今天真给我整麻了，下午绍哲带着gta5上岛，感觉线上玩的内容比线下多好多，返回弄8266的板子，网上说啥的都有，有的说可以通过arduino uno板子写入8266，也有说用ttl写入的，应该是都可以，但是我俩种都没写入成功，所以现在我还没有自己使用无线模块连接成功，这个放弃了，以后有时间再看，也可能是板子坏了，拼多多买了俩个01s的板子过年回家一定看，之后做d1连接mqtt好在刚刚弄好了，出现各种各样的坑，单片机这个依赖包版本还不兼容，真的离谱，最终做的结果是可以通过mqtt控制舵机的角度，没有把旋转角度写死，这个还算比较满意吧，所以这样我可以通过网站控制家里电灯开关了，过年回家也可以看app至少把app做成可以调用接口的，这样就可以手机开关家里的灯了，过年回去还像学习stm32，时间真不够用啊，今晚就弄一个小功能就花了整整一晚上，真累。', '2024-01-27', '2024-01-28 00:53:12', '2024-01-28 00:53:12', 1);
INSERT INTO `blog_diary` VALUES (1804, 1, '今天真烦，可以说是干啥都不顺利，一下午看那个stm32之前弄得的可能是我操作问题，现在完全是按照那个视频来操作的，但还是有问题，不知道出在哪了，今天的不顺利甚至在游戏上也是，玩啥游戏都是太黑了，心烦啊。', '2024-12-05', '2024-12-06 00:12:10', '2024-12-06 00:12:10', 1);
INSERT INTO `blog_diary` VALUES (1805, 1, '这几天每天都在玩，每天要认真准备复习了。e', '2024-04-27', '2024-04-27 23:32:44', '2024-04-27 23:32:44', 1);
INSERT INTO `blog_diary` VALUES (1806, 1, '说不点外卖，这个是真的难做到，做完出去附近走了走，就没有那种小饭店，二环里面还是太难找了，到处都是京爷，晚上看stm32，好像把这个stlink给烧了，供电有影响，应该没烧坏stm32，因为我使用充电宝直接供电是没有影响的，然后又买了俩个stlink，备用，晚上csdn绝对是崩了，后来就开了游戏。', '2024-09-16', '2024-09-17 01:01:34', '2024-09-17 01:01:34', 1);
INSERT INTO `blog_diary` VALUES (1807, 1, '电脑远程弄好了，暂时不使用吧，得准备好数据备份，万一出了安全问题后悔都来不及，今天把病村探完了，顺便打了一个羊头恶魔，不是很难。', '2024-03-19', '2024-03-20 00:36:58', '2024-03-20 00:36:58', 1);
INSERT INTO `blog_diary` VALUES (1808, 1, '今天六点半下班了，回来把stm32控制舵机弄好了，之前也不知道是什么地方写错了，一直是转最大和最小角度，现在可以精确控制角度了，还有中午没休息在公司把平台上控制命令修改的功能也改好了，测试也没发现太大的问题，还有公司的bug也算是清完了，今天状态很好，晚上改完单片机功能之后开了会车。', '2024-10-23', '2024-10-24 00:10:34', '2024-10-24 00:10:34', 1);
INSERT INTO `blog_diary` VALUES (1809, 1, '今天开始处理数据同的工作，这个还算简单，使用别人做好的功能，我配置就可以了，晚上继续缺氧，这个新档晚起来感觉很顺手。', '2024-08-19', '2024-08-20 00:26:12', '2024-08-20 00:26:12', 1);
INSERT INTO `blog_diary` VALUES (1810, 1, '昨晚在火车上，也没啥可写的东西。', '2024-02-02', '2024-02-04 01:02:12', '2024-02-04 01:02:12', 1);
INSERT INTO `blog_diary` VALUES (1811, 1, '昨天的面试也没消息，估计凉了吧。', '2024-05-24', '2024-05-25 00:25:20', '2024-05-25 00:25:20', 1);
INSERT INTO `blog_diary` VALUES (1812, 1, '今天下午在中心，没啥想写的这工作，真的想休息几天，晚上回来打黑魂，我才发现我只打了三个巨物，剩一个找不到了。', '2024-10-06', '2024-10-07 00:02:48', '2024-10-07 00:02:48', 1);
INSERT INTO `blog_diary` VALUES (1813, 1, '可算是弄好了pi的docker部署，不过因为网速的原因下载还是不行，只好从服务器上导出docker的image文件，然后导入到树莓派，就因为网络的原因走了俩天弯路，好在是完成了，开心，明天修改公司的点位导入模板吧，有时间可以继续看博客主题的docker部署，也不知道今天有没有弄好rocketmq的部署，看日志是正常的，但是也只能看日志，部署可视化页面连接失败了，不知道Java服务能不能连接成功，还有ftp也弄好了，测试连接成功，还能用手机上传和下载文件，感觉挺不错的，今天就写这些，看会动漫睡觉了。', '2024-02-28', '2024-02-29 00:24:30', '2024-02-29 00:24:30', 1);
INSERT INTO `blog_diary` VALUES (1814, 1, '今天开发了不少东西，文件同步现在已经可以了，上传下载都有，剩下就是花点时间慢慢测试，不过最近这几周肯定是没时间去部署，还有树莓派服务是写好了，还得同步写很多脚本，暂时大概要把服务启动需要有docker的服务部署脚本，linux的开机自启动脚本，服务也得有守护线程，日志文件也需要定时清除，云服务器上需要适配数据备份功能的sql到处，文件压缩脚本，总之缺很多脚本需要写，这周研究硬件，去王鹏那边先把51单片机弄好，今晚把之前树莓派部署的操作流程总结了一下，不过这个部署流程以前就有，我只是复习一次，重新操作一次一切正常，就是最后有个操作没看懂，但是当时写了肯定是有原因的吧，找时间百度一下就好了，晚上连接树莓派的时候用无线键盘，按键不太灵，充了一会电，现在操作正常，刚刚操作树莓派和路由器把树莓派的ip固定了，这样就可以放心写硬件了，学习新知识确实可以让人心情舒畅，最近感觉一直不错。e', '2024-01-11', '2024-01-12 00:31:12', '2024-01-12 00:31:12', 1);
INSERT INTO `blog_diary` VALUES (1815, 1, '昨天懒得写日记，下午看视频学stm32，看一会睡一会，感觉现在写个简单的数据读取没问题了。', '2024-07-28', '2024-07-30 00:03:54', '2024-07-30 00:03:54', 1);
INSERT INTO `blog_diary` VALUES (1816, 1, '今天上午开始看公司项目bug了，不过这次修改不会更新到bugfix版本上，所以还好，可以改了，但是不走问题单流程，不测试，还算是不忙吧，还有把ppt提交到项目文档里面，都是些小事，下午就开始优化后端接口，整理接口文档，从今天正式开始吧，每天在公司整理下接口，晚上整理一篇笔记，最近过的非常舒服，刚刚倒盒子，第一次五折倒余额，2块买的，steam出售价扣除胖的手续费到手还有3块。', '2024-01-16', '2024-01-17 00:42:46', '2024-01-17 00:42:46', 1);
INSERT INTO `blog_diary` VALUES (1817, 1, '今天继续学习51单片机，还是很有收获的，下午坐菠萝的车压马路，谈到了些同学，别人为啥都是那么优秀，都是铁饭碗了，我现在还需要不断去卷，开卷也不是我想做的啊，我只想安心那个低保，有个稳定的工作就行，心累，明天起来上午学习51，下午完善接口或接口文档吧，博客文件同步的也尽快。e', '2024-02-07', '2024-02-07 23:37:30', '2024-02-07 23:37:30', 1);
INSERT INTO `blog_diary` VALUES (1818, 1, '终于结束了一个月的忙碌加班，紧接着的九月希望别加一整个月了，今天把新版的设备注册流程改好了，之后就是数据上报和控制命令下发流程，明天尽量多花点时间看看，不求有太大进度，忙一周了，也想休息。se', '2024-08-31', '2024-09-02 00:42:26', '2024-09-02 00:42:26', 1);
INSERT INTO `blog_diary` VALUES (1819, 1, '今天面试了俩场，最近感觉还是可以的，至少笔记做了不少，也可以大部分回答过来了。', '2024-07-23', '2024-07-23 23:42:52', '2024-07-23 23:42:52', 1);
INSERT INTO `blog_diary` VALUES (1820, 1, '开了吧群星，俩个大爹贴脸，完全没有沟通，直接给我干暴毙了，开局发现俩个巨构感觉开始挺好的，可惜了。e', '2024-05-03', '2024-05-04 01:14:54', '2024-05-04 01:14:54', 1);
INSERT INTO `blog_diary` VALUES (1821, 1, '博客的docker部署终于完成了，带上单片机控制的功能，前前后后一共三个月时间吧，后续开发的重点就是单片机这块了，博客主要是对已有功能的优化和bug修复，完成了阶段性目标，今天很开心，晚上修改了简历，下周开始继续找工作。中午吃饭的时候不小心锁了门，还好房东在家，及时联系上给我开了门，不然今天的任务就完成不了了。', '2024-03-10', '2024-03-11 00:05:46', '2024-03-11 00:05:46', 1);
INSERT INTO `blog_diary` VALUES (1822, 1, '上班第一天，感觉真爽啊，下班之后还能有这么长的时间，下班路上走一会就到了，开心，希望出差的时间长一些，越长越好，最近没有想开发的功能，昨天写了博客内容，新开发的发向倒是有很多，就是不想写。', '2024-12-16', '2024-12-16 22:14:34', '2024-12-16 22:14:34', 1);
INSERT INTO `blog_diary` VALUES (1823, 1, 'dnf端游还是玩不明白，改的花里胡哨的完全看不懂，今天贷款业务的继续找我联系了，要是能面试过也可以去，外包就外包吧，加班也行。', '2024-05-29', '2024-05-29 23:40:26', '2024-05-29 23:40:26', 1);
INSERT INTO `blog_diary` VALUES (1824, 1, '今天整理数据迁移的流程算是清楚了，明天上午过去再同步下问题，下午继续去军委，这一步先找到要迁移的组织结构，之前说的要我创建组织的这个流程也不用做了，感觉工作量减少了挺多的。', '2024-08-14', '2024-08-15 00:37:22', '2024-08-15 00:37:22', 1);
INSERT INTO `blog_diary` VALUES (1825, 1, '今天一直在写文档，还有一半多吧，明天也不知道能不能全部完成，洗漱了看动漫吧，这几天不想打游戏。', '2024-04-01', '2024-04-01 23:16:24', '2024-04-01 23:16:24', 1);
INSERT INTO `blog_diary` VALUES (1826, 1, '士兵信息补充的接口算是弄好了，初步测了几下，看着没啥bug，明天过去修改历史的bug，然后有时间就再点点这个功能，还有就是一些细节的过滤参数也加上。', '2024-09-05', '2024-09-06 00:02:40', '2024-09-06 00:02:40', 1);
INSERT INTO `blog_diary` VALUES (1827, 1, '昨天下班回家就2点了，一天都在中心加班，真是烦死了，上周甚至单休都没了，今天周一依然加班。', '2024-09-22', '2024-09-23 21:24:18', '2024-09-23 21:24:18', 1);
INSERT INTO `blog_diary` VALUES (1828, 1, '今天一整个下午都在搞nacos，一直连不上MySQL，搞得我都怀疑人生了，差点有准备换MySQL版本，因为一整个下午都没弄好，所以晚上就加班继续看问题，好在晚上突然开窍了，一口气把nacos和rocketmq都连上了，甚至rocketmq的可视化也好了，还是因为一下午把docker熟练度提高了，每个命令的意思也知道了（全靠百度），今天也算是完美的一天吧，然后晚上打完dnf就卸载了，玩好几周了，差不多也没啥意思了，了解这个版本之后，剩下就是花时间肝，花钱升级装备，我觉得这些没啥意思，dnf还是老样子，一直骗氪，要是日常不氪轻度肝我倒是也能接受，有这个时间去玩，但是玩dnf就跟上班似的，每天六点公司下班，七点dnf上班，真的是无聊了，而且好多团本没打过还不会玩，和别人一起玩自己也难受，队友也难受，好几次挨骂，都是因为不熟悉机制，每天晚上下号都要检查各种任务有没有完成，要不要在处理下，然后半小时又过去了，玩的太受罪了。', '2024-03-04', '2024-03-04 23:58:54', '2024-03-04 23:58:54', 1);
INSERT INTO `blog_diary` VALUES (1829, 1, '今天没怎么打游戏，下午稍微投了几份简历，接下来继续开始找工作吧，还有该写的博客项目争取年前完成。', '2024-11-25', '2024-11-26 00:30:36', '2024-11-26 00:30:36', 1);
INSERT INTO `blog_diary` VALUES (1830, 1, '昨晚回家实在是不早了，然后就随便洗洗睡了。', '2024-08-08', '2024-08-09 23:51:44', '2024-08-09 23:51:44', 1);
INSERT INTO `blog_diary` VALUES (1831, 1, '今天有点累，下午都没写笔记。se', '2024-07-17', '2024-07-18 02:21:58', '2024-07-18 02:21:58', 1);
INSERT INTO `blog_diary` VALUES (1832, 1, '今天算是离职了吧，一年俩次换工作，主要还是实在坚持不下去了，天天都是996，这次也算是试用期没过，也有我自己的原因吧，每次都是任务流程走到别人那边我就默认别人会自己执行，没有一直催进度，所以表现出来的结果就是因为我的原因没让流程继续走下去，下一份工作的时候多注意下这一点，然后明天出去找房子吧，从这边搬出来，先去找一个城中村短租一段时间，暂定就一个月吧，找不到工作之后再回家，我觉得最近投简历约面试的频率还是挺高的，这周没啥准备都面试三四次了，有时候一天俩场找个没人的楼梯间都很困难，在这边差不多包吃住干了三个半月，没啥消费，现在发了2.2w，然后领导说国庆七天的加班费也是有的，那差不多还能发俩万多，今年我觉得差不多攒下十一万多，大华离职就发了五万多，现在这边又拿了四万，然后还有一到三月的工资那每个月也能赞7k，今年虽然工作不稳定，但感觉收入还是可以的，等下周五发了工资我再计算下总的存款，这份工作还是太累了，从杭州来北京的时候就是一直期待北京的双休，结果来了这都三个月多了，没几次双休而且上班通勤时间也好长，可能是因为我还是不适合在北京工作，现在换其它城市也不知道去哪个城市可以生活节奏慢一点，我现在应该有个40w了，在工作五六年就可以退休了，以后再也不写代码了，爱好变成工作确实是一件痛苦的事情，这边办公写代码还是离线编程，好多不会的问题都不能百度，之前还让在门口放自己电脑查一下资料，后来因为要保密不让放了，真是一肚子苦水，不喜欢这边工作，希望下家公司可以好一点，我的命咋这么苦啊，悲催的北漂流浪打工仔。', '2024-11-08', '2024-11-08 23:54:58', '2024-11-08 23:54:58', 1);
INSERT INTO `blog_diary` VALUES (1833, 1, '兵员数据清洗的工作差不多也完成了，我这边数据都准备好了，然后就是去中心那边写入数据库，最近都可以八点下班，感觉稍微轻松起来了，晚上继续黑魂，真是无兄弟，不黑魂啊，玩二代全靠召唤npc帮忙，我玩的法爷，看别人都是秒秒秒，我上去就是被暴打，冰原这个dlc也太难了，感觉怪的法抗特别高，而且都会举盾，那个老虎和白王都是慢慢耗死的，没啥含金量。', '2024-10-17', '2024-10-18 00:25:04', '2024-10-18 00:25:04', 1);
INSERT INTO `blog_diary` VALUES (1834, 1, '在家的最后一天了，今天算是把pi服务的docker脚本测试了一次，应该明天整理一下就可以使用了，然后下午就准备去杭州，不出意外公司是要裁我了，不过裁了也挺好，准备去北京找工作。', '2024-02-13', '2024-02-14 00:11:08', '2024-02-14 00:11:08', 1);
