INSERT INTO `doc_content` VALUES (43, 1, 93, '# 8-11夜间骑行\n西湖进山速降\n## 骑行全程\n![08-11_21-06_全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-00-39_RQnrWn_08-11_21-06_全程.jpg)\n\n## 时速\n![08-11_21-06_时速.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-02-23_TrMSxk_08-11_21-06_时速.jpg)\n\n## 爬升\n![08-11_21-06_高度.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-02-44_GEUGFM_08-11_21-06_高度.jpg)', 0, 0, '2023-08-20 22:22:43', '2023-09-17 10:03:08', 1);
INSERT INTO `doc_content` VALUES (44, 1, 94, '# 8-13下午骑行\n市区骑行\n\n## 全程\n![08-13_18-40_全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-37-51_SOptqh_08-13_18-40_全程.jpg)\n## 时速\n![08-13_21-06_时速.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-38-04_SkvsTL_08-13_21-06_时速.jpg)\n## 爬升\n![08-13_21-06_高度.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-38-16_qDCxaC_08-13_21-06_高度.jpg)', 0, 0, '2023-09-17 10:34:23', '2023-09-17 10:38:45', 1);
INSERT INTO `doc_content` VALUES (45, 1, 96, '# 8-20 下午骑行\n上午去看了牙医，约了洗牙时间，中午出发骑行去下沙，到旭福学校走了走，看了看硕士的实验室，晚上返程，来回也就60公里吧，不是很远。\n\n## 全程\n![08-20_8-44_全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-44-35_fiJFFg_08-20_8-44_全程.jpg)\n![08-20_12-45_全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-44-35_zdOtEZ_08-20_12-45_全程.jpg)\n![08-20_18-31_全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-44-35_ctAjnp_08-20_18-31_全程.jpg)\n\n## 时速\n![08-20_8-44_时速.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-46-07_NMihfk_08-20_8-44_时速.jpg)\n![08-20_12-45_时速.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-46-07_uLgzSH_08-20_12-45_时速.jpg)\n![08-20_18-31_时速.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-46-07_YfHkQu_08-20_18-31_时速.jpg)\n\n## 爬升\n![08-20_8-44_高度.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-46-29_iIIXZa_08-20_8-44_高度.jpg)\n![08-20_12-45_高度.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-46-28_hjuxDI_08-20_12-45_高度.jpg)\n![08-20_18-31_高度.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-46-29_VqNtXa_08-20_18-31_高度.jpg)\n\n## 风景\n返程时桥上拍的，具体是什么桥我也不清楚，就是大华1399附近的那个\n![8-20骑行风景-1.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_10-47-32_GhVCJN_8-20骑行风景-1.jpg)', 0, 0, '2023-09-17 10:39:53', '2023-09-17 10:48:49', 1);
INSERT INTO `doc_content` VALUES (46, 1, 97, '# 9-17 下午骑行\n今天下午约了罗登城一起去骑车，体验非常差，一是不如自己一个人骑车自由，然后就是他骑车太慢了，骑之前说的30公里巡航，结果开始骑了也就15，还和他去修车，下午算是浪费了，要是我一个人可能就去看看亚运会那边怎样，还有六天开幕，下周六，周日可以过去看看。\n## 全程\n![09-17_17-50_全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_22-08-58_eKCXaL_09-17_17-50_全程.jpg)\n\n## 时速\n![09-17_17-50_时速.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_22-09-14_ITGFBN_09-17_17-50_时速.jpg)\n\n## 爬升\n![09-17_17-50_爬升.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_22-09-28_dJTUQS_09-17_17-50_爬升.jpg)', 0, 0, '2023-09-17 22:01:42', '2023-09-17 22:09:36', 1);
INSERT INTO `doc_content` VALUES (47, 1, 99, '# 22年方特旅游\n因为是去年的事情了，所以很多事情我都忘记了，而且当时博客没有这么多功能，正好今天记录千岛湖把这个也记录一下，旅游时间是22年六月18-19两天，日记应该也有记录。\n先上地图，这个是第一天玩的游乐园全图：\n## 东方神话-全图\n![方特地图.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_22-24-06_XQUMvc_方特地图.jpg)\n我是进门左拐走的，门口有很多商铺，奶茶冰激凌、汉服礼品屋，啥的不是我的考虑范围，上面走遇到的第一个就是长城绝恋，这个关门了，因为是戏剧，有开放时间限制，挨着上面就是梨园游记，简单明了的说明下，就是看戏的，比平时看戏稍微高级一点就是座位可以晃，没了，我的评价是浪费时间。之后就去吃饭，周六出发去了宁波慈溪就十一点左右了吧，大概是，去下面的东方美食城，里面的饭花里胡哨的，没啥分量缺死贵，幸好公司管饭，每日一张饭票。天河之恋有没有玩不清楚了，记得当时在那边还坐了好一会，上面的千古蝶恋是历史相关的参观项目，从古至今，各个朝代省份都简单介绍了下，这些都是开胃菜，玩多了容易睡着。\n女娲补天：这个是3D视觉加车摇晃，类似4影院那样吧，让人身临其境，也是我第一次玩游乐园的这些项目，印象还是很深刻的，第二天也有类似的这种项目，后面的就不赘述了，这个里面的坠落，声音相比后面的要好一些。\n纵横华夏没去，下一个玩的是神州塔。\n神州塔：就是跳楼机，只不过这个是修建在楼里面，据说有50多米，因为是在楼里面，所以上去的时候看着墙壁也不会害怕，但是周围人一直在叫，整的我也慌，下坠的时候有一段时间接近自由落体，当时腿都飞起来了，但是身体还在座位上，人肯定是不会飞出去的，全程要是看脚底下就会恐高，看天花板就不会害怕。\n之后就往右边玩，有很多项目都没去看，就写我玩过的那些吧，惊魂之旅也去了。\n惊魂之旅：我表示确实惊魂，这个是过山车类型的，但是建造在地下，而且是在房间里面，全路段伸手不见五指，毕竟主题是地狱之旅，玩了俩次，反正啥也看不见，就坐那把自己绑好，听周围人尖叫也挺好玩的。\n海盗船？这个就不说了吧，首选船尾，最高处可以短暂悬空。疯狂马戏团挺好的。\n疯狂马戏团：这个是大摆钟，带360旋转的那种，玩了俩次，第一次还有点放不开，第二次我直接放手体验，主打一个刺激，但是也就那样，属于可以接受范围内。\n之后排了丛林飞龙、极地快车，也都是过山车，丛林飞龙这个很高，但是他的架子都是木头，总感觉不够安全，然后极地快车，这个有点快，玩到这都三四点了吧，看图这个是从一边最高处冲下来去另一半，然后倒着回来，速度很快，正向还好，返回来的时候有点快，当时就感觉有点不舒服，下来之后就没继续玩刺激的项目。阴差阳错之下走进了七彩王国，这个是小孩玩的，但是因为当时还是处于疫情期间，淡季没啥人，我就一个人发车了，哄小孩的项目，我就不记录了，丢人。\n出来之后就等待去宾馆，这可是我第一次入住五星级宾馆，当晚泡澡一小时多。\n这些都是第一天周六玩到的项目，然后是周日东方欲晓，上面这个是东方神话，里面大部分都是神话主题的。\n\n## 东方欲晓-全图\n![方特-东方欲晓.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_23-02-02_fDgXUo_方特-东方欲晓.jpg)\n第二天去这个人有点太多了，周六那个几乎是我们包场，很多项目都是一个人玩的，东方欲晓这块不知道是因为周日还是这个游乐园更火一点，或者说是因为上午天气不是很热，总之这个去了人好多啊，还有很多老年人旅游团来的，第一天没有拍照，但是这个有拍，先看看大门口：\n![大门口.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_23-05-04_nrvxDY_大门口.jpg)\n里面项目和前一天的也没差多少，游击，突围都是3D场景，突围还可以拿把枪去射击，门口有个致远没去，因为人太多了，懒得排队不知道里面是啥，这个一个过山车很爽，先上图：\n![过山车.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-09-17_23-10-12_xsmwCp_过山车.jpg)\n周日我们是计划下午三点返回杭州的，这个项目也是下午三点才开放，本来是没机会玩的，但是一行好多人都想玩玩，所以就退迟了半小时，玩了一把，这个过山车是真的弹射起步，加速很快，还有好几个旋转，看轨道就可以看出来，最高点也很高，可能是因为玩过其它过山车了，这个虽然速度快，很刺激，但是也没怎么害怕，全程一分钟左右吧，玩完就返程结束。', 0, 0, '2023-09-17 22:13:26', '2023-09-17 23:15:11', 1);
INSERT INTO `doc_content` VALUES (48, 1, 100, '中秋节礼盒发了之后到现在十月中旬才开始记录，没办法真的是时间不多，我的印象笔记上面的数据还没迁移出来，那些都是大学和实习期间记录的笔记，还有不少算法相关的笔记，可惜现在忙工作算法是彻底的丢了，没太多时间看看，上班那就是995+大小周，这周是大周周六放送休息一天，今天就赶紧抽时间记录下这个礼盒和之前千岛湖旅游。\n## 礼盒本体：\n这个中秋节礼盒最有特色的也就是这个盒子了吧，现在正好作为我的收纳盒，没办法90后就是有这些特殊癖好，总喜欢留些零零碎碎的小东西，就需要这样的盒子来装一下\n![中秋节礼盒-23.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_11-37-13_RuKZoK_中秋节礼盒-23.jpg)\n## 礼盒月饼\n月饼国庆下带回家里给我妹吃掉了，现在回想起来我好像是真一口没吃啊，左下角还有个彩色贴纸，这个也是月饼礼盒里面的，因为照片拍的很不清楚，没有那种彩色的赶紧就不上传了。\n![中秋节礼盒月饼-23.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_11-37-22_cksElH_中秋节礼盒月饼-23.jpg)\n## 礼盒眼罩\n带有枕头的眼罩，很适合午休使用，但是我现在午休也不用床了，所以这个也带回家里去了，省的找下一份工作要搬的东西太多。\n![中秋节礼盒眼罩-23.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_11-37-38_cJIotH_中秋节礼盒眼罩-23.jpg)\n\n礼盒差不多就这些东西吧，总感觉还是太敷衍了。', 0, 0, '2023-10-15 11:31:35', '2023-10-15 11:44:41', 1);
INSERT INTO `doc_content` VALUES (49, 1, 101, '# 23年千岛湖旅游\n千岛湖也是一直都想去的地方，奈何没时间，来回肯定得三天，因为我想骑自行车出行，单程就要150公里，只能是等五一国庆玩，但是今年国庆回家了，明天五一会是啥情况还不清楚，反正也去过一次了，骑行出去流浪也不在乎是去哪，只要是骑行就行，去过一次以后也不会后悔，旅游时间是23年9月9-10俩天，就简单的记录下，反正写流水账也是我的拿手好戏，先整理下图片顺序。\n旅游路线：\n这个和游乐园不一样有个地图，这就完全跟着导游走，周六上午从公司1199出发，高速走了俩小时才到，和方特不一样的是这次有一起去玩的小伙伴，说是小伙伴，但是人家孩子都有了，就张崇和我差不多大，以前再学校的时候我永远的年龄最大的，但是工作之后就不一样了，还有建林和熊勇，建立我记得说过是杭州买房了，贷款三十年才还了六年，熊勇好像说的是郑州买房，贷款100w，月供7k，真是吓人，可能他们80后和我的想法不一样吧，不聊这些伤心的事情了，专心记录旅游。到了淳安大概就中午十二点了，找了一个很偏僻的地方吃的午餐，没啥可吃的，也没啥好记录的，就是普普通通的农家乐，下午是淳安某个游乐园，也不算啥大的游乐园，附近还有个啤酒城，游乐园里面只有卡丁车，排队一个小时体验了十几分钟的卡丁车，没有之前团建那个好，这个就是内部的一个小赛道，一次十个人绕着开，先说装备，一个头套为了公共戴头盔，一个全是汗臭味的头盔，一个保护脖子的海绵垫，可能还有手套和背心，印象不深，开车的时候最开始还挺爽的，速度可以稍微快一点，为了安全不太敢弯道超车，所以速度也就那样，短短十分钟，开始玩的还挺开心，但是之后是真的不想玩了，每次路过发车点都看看管理人员，看看有没有到时间，当天下午是真的热，头盔又臭，真怀疑他们每天结束之后头盔都不做保养，就算是洗洗也行啊，体验很差，200+不值得，具体多少钱我是不清楚的。晚上去了开元酒店，下午我们玩的时候有部分人不玩，直接先去了宾馆，然后吐槽这个宾馆基础设施太差了，甚至空调开关都是上世纪那种旋钮的样式，我都做好心里准备了，以为是一个十分脏乱差的酒店，阴暗潮湿且还有蟑螂，没想到去了之后真是让我开眼了，人和人的经历真是的差距太大了，我觉的这个酒店还是很强的，可以说是我住过最好的酒店了，第二应该是方特那次的酒店，可惜那次没拍照，到酒店之后就是自由活动时间了，一直到第二天中午，酒店晚上是自助餐，第二天早上也是，和方特一样，这个开酒店还送一张千岛湖的皮划艇的票，感觉是这次旅游体验最好的项目了，自由划船的范围也挺大，湖水也很清澈，总体就是这些吧，感觉很不错，比我一个人瞎逛好多了，要是天气不冷下下周可以去带个帐篷去流浪，你问我为什么不是下周？因为下周要去爬大明山，是公司部门团建。\n## 酒店湖景\n当时去看真有那种网上酒店度假村的感觉，不过人家确实叫开元酒店度假村，没见过世面，当我我唯一联想到的是生化酒店，还有几张夜间的照片，但是因为晚上太模糊了，就算了吧，手机全责。\n![千岛湖开元酒店.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_11-58-25_ZQnwad_千岛湖开元酒店.jpg)\n## 房间门口\n当时到这个门口感觉还是很惊讶的，我没见过世面，看到这种就觉得以及很豪华了，这俩边的房间都是2k一万，周六晚上出去散步的时候听到有人在这住好几天了，有钱人的世界不是我能理解的。\n![房间门口.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_12-31-29_WhDRHo_房间门口.jpg)\n\n## 千岛湖\n![窗边看千岛湖.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_12-31-56_tMRmtG_窗边看千岛湖.jpg)\n![千岛湖-1.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_12-32-06_TTomgY_千岛湖-1.jpg)\n![千岛湖-2.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_12-32-16_ejnKjv_千岛湖-2.jpg)\n这个就是皮划艇范围\n![千岛湖-3.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_12-32-28_wrgbFp_千岛湖-3.jpg)\n\n# 皮划艇\n万年社恐人员，最后还是上传张自己的照片吧，也算是一个纪念，短短一生还是多些体验吧，别到最好留下遗憾，挖个坑，不知道几十年以后再回来看这个记录是什么心情呢？不想那么多了，现在就应该赶紧把博客这块弄好点，换一个工作。\n![皮划艇.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-15_12-35-26_BWQlQp_皮划艇.jpg)', 0, 0, '2023-10-15 11:45:21', '2023-10-15 12:38:40', 1);
INSERT INTO `doc_content` VALUES (50, 1, 102, '# 10-15 下午骑行\n今天骑行还挺开心的，就是发生了一些不太好的事情，虽然现在不早了，但我还是想完整的把今天的骑行记录记下来，之后要是忘记了可就麻烦了。下午是一点多出门的，出门之前检查了自行车，发现车胎气压不足，然后就去找智康去打气，然后大佬一眼就发现了我自行车车把安反了，我当时还以为是骗我的，直到给我装回来才发现那几个按钮上有图案，所以确实是我第一次装错了，就这样起了半年，调整过来还算习惯吧，现在车前面的线也理顺了，然后就正式出发开始今天的骑行，按照计划就去富春江上的一个岛，从五丰渡口上船，环岛骑行一周，然后去吴家渡口离岛回家，所以要记录的事情就在上五丰渡口发生的，因为之前公司团建去过新沙岛，我就以为汽车上岛和行人电瓶上岛应该会是俩条船，一开始我看到了五丰渡渡口，船上下来好多汽车，所以我以为这个是专门汽车离岛的船，我应该再往前骑一会，所以我就这么做了，骑一段路发现好像不是我想的那样，准备返回去问问路，可能是当时下午太阳强烈，也可能是我没注意对向来的汽车，我看我这边的汽车都走完了，所以我就准备过马路，然后对面驶来的一辆车就撞到我了，虽然车是刹住了，碰到我的时候就轻轻碰了一下，自行车也没倒，甚至都不能算是交通事故，但是我当时还是被吓到了，把车停在旁边路上，回想当时的场景我就眼睁睁的看到那辆车停在我面前，如果要是司机没刹住可能我就交代在这了吧，真是世事无常，细说责任也没啥可说的，如果我看到了那边来车就完全可以避免，即便是他全责我可是全命，不知道当时怎么想的。如果我今天凉了那我确实还是又太多遗憾的，前几天看到一个短片是一只苍蝇只有一分钟的生命，然后他从前辈那接手了一个人生必做的x项事情，从出生到死亡一直都在忙碌，没有思考的为了目标奋斗，当然他也做到了，变成了琥珀让他的生命永远定格在最后一秒，所以今天让我如此近距离的感受到死亡的威胁，为了不让我在人生最后的时刻留下遗憾我也给自己定一些人生比作的事情吧，当然我这个和他并不一样，这是在我有了自己的思考，自己决定的事情。因为是人生比作的目标，所以给自己也稍微定高一点，至少是需要通过努力才能够实现的目标。\n\n1. 最牵挂的还是我的博客系统，现在我写日记，写文档都没啥问题了，算是已经实现了初心，然后下一步就是要把我的博客做成全屋智能管理平台，我理解的全屋智能平台那就是要在我的博客系统中接入摄像头，接入一些信息传感器，要做到可以使用我的手机打开电脑，可以根据土壤湿度给花草浇水，要有一个太阳能电池板给这些系统供电，要有可以远程控制的继电器来控制各个模块的启动情况，挑战目标的话要是能接入可以自动巡检我指定的一些目标点的无人机那就更好了。\n2. 想要自己做一个无人机，涡轮的那种我肯定消费不起，因为门槛太高了，我的经济实力就不允许，万一摔一个发动机我底裤都得赔干净，做一个螺旋桨控制的就行。\n3. 想上天，跳伞，滑翔机都想体验下。\n4. 想出国，程序员肯定不会是一辈子都可以做的工作，等钱攒差不多，就想出国找一个工资一般的工作，体验下世界上的其它地方，即使不能定居，旅游一次也行，代价那就是要学会当地的语言，别去了什么都不懂。\n5. 秘密\n\n## 全程\n![23-10-15全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-29-47_gDLrDx_23-10-15全程.jpg)\n## 时速\n![23-10-15时速.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-29-53_NorKCf_23-10-15时速.jpg)\n## 爬升\n![23-10-15爬升.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-30-05_yVTuNX_23-10-15爬升.jpg)\n\n## 风景\n看地图就可以看出来，四次过江，所以我都记录下来了，从中午到晚上\n![出发时过江.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-30-30_bNCLGb_出发时过江.jpg)\n事故就是这个渡口附近，要伴随我一辈子了吧，会成为我的噩梦吗？至少也长点记性吧，虽然我平时都会很小心，但可能还会有今天这样忘记的时候\n![上岛.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-30-47_LSMdxy_上岛.jpg)\n\n![离岛.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-30-56_LRECcj_离岛.jpg)\n\n![返回时过江.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-31-07_obRlOq_返回时过江.jpg)\n', 0, 0, '2023-10-15 23:46:59', '2023-10-16 00:34:25', 1);
INSERT INTO `doc_content` VALUES (51, 1, 104, '# 微信头像\n这个算是我的一个新坑，记录下从今往后每一个微信头像，上一个就不记录了，从今天开始。\n\n## 23-10-16 来自朝花夕誓\n晚上回家看的这个动漫，起初是看葬送的芙莉莲（下一个头像就换这个），受弹幕推荐就看了这个，电影内容我就不多说了，以后我会有什么样子的人生呢？真希望我是一个局外人，默默的看着地球的岁月变化，以后的世界又会变成什么样子。\n![微信头像-朝花夕誓.png](http://49.232.129.253:9000/blog/1/doc/img/2023-10-16_00-36-45_LGTYvF_微信头像-朝花夕誓.png)\n\n## 23-10-22 来自葬送的芙莉莲\n我以为第二个会换百年孤独的头像呢，结果是真没看懂，第一次看30%了吧，名字完全混了，现在准备看第二次，慢慢看，要更认真一点，这次争取别记混名字。芙莉莲是真的神作啊，动漫也看很多年了，入坑作re0但是没看第二部，不知道第二部质量怎样，别毁了我心中的幻想，然后所有动漫看下来我心中的神作也就是无职转生和这个了吧，最近看完了漫画（漫画还没完结，看到了最新的这），所以觉得可以把头像换成这个了吧。和朝花夕誓一样，都是无限的寿命，想了想我也不知道为什么就是喜欢，可能是每个人物性格形象都很有特色吧，也说不出理由。\n![葬送的芙莉莲.png](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_22-17-21_vQriTU_葬送的芙莉莲.png)\n\n## 24-01-13 来自药物少女的呢喃\n虽然芙莉莲还没更新完成，但也差不多是第二季了，虽然俩季中间没有时间间隔，头像也用了好几个月，差不过该换一个了，这次是药物少女的呢喃，同样是去年十月的新番，制作也很不错，属于追完一集马上想看下一集的类型，能当我头像的动漫差不多也是我认可的优质动漫，肯定是要追完的，剧情的话没感觉有特别明显的主线，几集一个推理小剧情，非要说主线那应该是猫猫和太子的感情线吧，我猜是太子，没看剧透，也没去追漫画，拿来当头像主要是这个动漫看起来很放松，画面制作的也很不错，还有猫猫太可爱了。\n![image.png](http://49.232.129.253:9000/blog/1/doc/img/2024-01-13_21-54-52_AatgZE_image.png)', 0, 0, '2023-10-16 00:35:48', '2024-01-13 21:59:50', 1);
INSERT INTO `doc_content` VALUES (52, 1, 105, '# 10.21大明山团建\n\n先感慨下，去大明山好远，来回要走四小时，本来说的是要下午四点集合回杭州，但是因为我排队一直等不上，一个人耽误了半小时，真的实在是抱歉，虽然我的同事们也看不到我的记录。看地图可以看到是有俩条上山的路线，缆车就不算了，右边橙色的是休闲路线，左边红色的是挑战路线，显然我还年轻气盛必然选择的是挑战路线，几乎全程都是钢架楼梯，楼梯没啥可看的，就没有拍照，全程说的是3.6公里，结果走了四公里多才到缆车那边，本来我是计划一个人慢慢走的，结果路上遇到了技术支持的熟人，（也不怎么熟，就是之前在市场部做的时候支持过些现场问题）就一起走，所以俩个人走就容易开始卷，所以越走越开，单纯是为了打卡才爬山的，不过都有好坏吧，就下午一会的时间把整个景区都逛完了，从钢铁长城走到了悬空吊桥那块，然后返回来坐滑梯+滑板车，因为所有人都是从这儿下山的，就排了很久的队，导致耽误了时间，再次表示歉意。下面就记录我精选的照片了。\n\n## 大明山地图总览\n![大明山地图.png](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_21-08-59_xcYYSE_大明山地图.png)\n对面是悬空栈道，这个修了有好几公里\n![大明山1.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_21-32-30_hKSUth_大明山1.jpg)\n悬空吊桥，第一次走这个也没怎么感觉害怕，可能是这个看起来很安全，其实下面还挺高的，走的时候这个桥上下晃，很容易摔倒\n![大明山2.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_21-34-00_BhpFGf_大明山2.jpg)\n悬空栈道*2，大明山这块之前是矿区，还有很多矿道，下一张就放矿洞里面拍的照片吧，拍的太模糊的我都在犹豫要不要放上来\n![大明山3.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_21-35-53_wWXJTo_大明山3.jpg)\n矿洞拍的一线天，其它的就算了\n![大明山6.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_21-40-24_QhgXTP_大明山6.jpg)\n御笔峰\n![大明山4.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_21-41-39_vDEQZT_大明山4.jpg)\n完赛奖励，公司是真爱给些奖牌、胸针之类的东西\n![大明山5.jpg](http://49.232.129.253:9000/blog/1/doc/img/2023-10-22_21-42-15_AXQFiD_大明山5.jpg)\n\n## 最后感想：\n周六出发之前还很不情愿，结果去了真香，最好玩的还是滑梯，为了确保安全就没有拍照，就是被后面的人踹了好多次，感觉他们后面的人完全不考虑刹车，全靠追尾是吧。看了杭州的山真是不想回北方去了，不知道别的地方怎么样，山西一年四季山上都是光秃秃的，下一份工作考虑广州和杭州吧，北京优先级最低，跑题了，这些吐槽应该写在日记里。\n', 0, 0, '2023-10-22 21:01:36', '2023-10-22 21:50:19', 1);
INSERT INTO `doc_content` VALUES (53, 1, 106, '# 12-31 全天骑行\n  第一次跨市骑行、第一次全天骑行、第一次单次破100公里骑行，总之太多第一次了，但是我觉得以后还是不要这样跨市骑行比较好，这种跨市骑行走的都是国道，国道上大车太多了，还有很多大车就停在路边，想要过去就必须稍微借道，借道就害怕万一后面正好来一辆大车，这个是真的没办法，找路书上的一些林间小道随便骑骑就好了，为了这个冒险真的太不值了，好像上次骑行也是遇到了些麻烦，真的小心谨慎的骑车，去绍兴看了看鲁迅纪念馆，但是我没进去，因为人太多了，而且我主要是出来骑车的，就在外面随便看了看，就算我去过了吧，就为看这一眼我骑了九小时，还丢了一只手套，悲（-_-!）。上图吧：\n\n## 全程\nkeep的界面风格变了，以后应该也还会变吧，没办法毕竟是用别人的软件，不能自己全局掌控\n![全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_11-08-50_wAOpjI_全程.jpg){{{width=\"300\" height=\"auto\"}}}(第一次使用控制图片宽度，但是好像不支持图片居中)\n\n## 时速海拔\n![时速海拔.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_11-13-42_ZrbWup_时速海拔.jpg){{{width=\"300\" height=\"auto\"}}}\n\n## 速度\n![速度.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_11-24-11_UVQEYt_速度.jpg)\n\n## 迎接2024小彩蛋\n![迎接2024.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_11-21-31_eBbkRU_迎接2024.jpg)\n', NULL, NULL, '2024-01-01 10:53:13', '2024-01-01 11:25:58', 1);
INSERT INTO `doc_content` VALUES (54, 1, 107, '去年也就是23年是大华30周年，年底给我们开了30周年活动，还给每个人发了礼盒，在公司园区也举行了活动，总福利差不多是每个人放假一天，中午公司还配置了豪华午餐，外加一个礼盒，确实良心。\n## 礼盒本体\n\n![大华30周年礼盒.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_19-16-47_MIzjod_大华30周年礼盒.jpg)\n\n## 礼盒内部\n\n![大华30周年礼盒内部.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_19-17-01_UEerya_大华30周年礼盒内部.jpg)\n\n## 小物件拼装完成后的效果\n\n![30周年礼盒-1.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_19-17-34_HMbRDy_30周年礼盒-1.jpg)\n\n## 园区活动券\n\n![大华30周年-2.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_19-17-56_xPKkUC_大华30周年-2.jpg)\n\n![大华30周年-3.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-01_19-18-00_XwqCil_大华30周年-3.jpg)\n\n活动举办的挺好的，活动有很多，丰富且有趣，遍及整个园区，我就随便的通过了十个领了一个加湿器奖励，每个活动排队人都很多，想玩一下要排很久。', NULL, NULL, '2024-01-01 19:04:38', '2024-01-01 19:21:16', 1);
INSERT INTO `doc_content` VALUES (55, 1, 109, '## 简要描述\n- 文件上传接口\n\n## 请求url\n- `http://ip:port/file/upload`\n\n## 请求方式\n- POST\n\n## 接口权限\n- `sys:file:user:upload`\n\n## 请求参数\n| 参数名       | 必选 | 类型            | 说明                           | 校验范围                                        |\n| ------------ | ---- | --------------- | ------------------------------ | ----------------------------------------------- |\n| files        | 是   | MultipartFile[] | 上传文件数据                   | 非空                                            |\n| fileTypeCode | 是   | Integer         | 文件类型编码                   | 非空且指定枚举，详见表格                        |\n| filePathCode | 是   | Integer         | 文件存放路径编码               | 非空且指定枚举，详见表格                        |\n| year         | 否   | Integer         | 日记上传使用，备注日记所属年份 | 无                                              |\n| addPath      | 否   | String          | 文件存放路径编码               | 路径需要以/开始且只允许汉字、数字、字母、下划线 |\n\nfileTypeCode文件类型枚举\n| 数值 | 描述         | 允许类型                        |\n| ---- | ------------ | ------------------------------- |\n| 1    | 上传图片     | \"jpg\",\"png\"                     |\n| 2    | 上传文件     | \"zip\",\"7z\"                      |\n| 3    | 自定义文件   | \"jpg\",\"png\", \"txt\", \"zip\", \"7z\" |\n| 4    | 上传日记文件 | \"zip\"                           |\n\nfilePathCode文件上传路径枚举\n| 数值 | 描述                 | 上传路径 |\n| ---- | -------------------- | -------- |\n| 1    | 文章相关文件存放路径 | /article |\n| 2    | 文档相关文件存放路径 | /doc     |\n| 3    | 其它类型文件存放路径 | /other   |\n| 4    | 用户个人文件存放路径 | /user    |\n| 5    | 日记相关文件存放路径 | /diary   |\n\n\n## 请求示例\n```json\n{\n    \"fileTypeCode\": 1, // 表示上传图片类型\n    \"filePathCode\": 1, // 表示文件上传至文章目录下\n    \"files\": \"文件(接口实际调用需要上传文件)\"\n}\n```\n\n## 返回结果\n```json\n{\n    \"code\": \"200\",\n    \"message\": \"成功\",\n    \"result\": [\n        \"http://localhost/files/1/article/img/2024-01-16_19-36-25_f4bc30_1.jpg\",\n        \"http://localhost/files/1/article/img/2024-01-16_19-36-25_5c3ef4_伊雷娜.jpg\"\n    ],\n    \"success\": true\n}\n```\n\n## result数据\n| 参数名 | 类型         | 说明         |\n| ------ | ------------ | ------------ |\n| result | List<String> | 返回文件链接 |\n\n\n## 错误码\n| 错误码编号 | 描述                                          | 解决方法 |\n| ---------- | --------------------------------------------- | -------- |\n| 000001     | 参数校验错误（返回字段message有详细校验信息） | 修改参数 |\n| 000102     | 未知错误                                      | 无       |\n| 050004     | 文件后缀类型禁止                              | 无       |\n\n## 备注', NULL, NULL, '2024-01-16 23:07:53', '2024-01-16 23:08:20', 1);
INSERT INTO `doc_content` VALUES (56, 1, 110, '## 简要描述\n- 根据id查询文章\n\n## 请求url\n- `http://ip:port/content/article/id`\n\n## 请求方式\n- POST\n\n## 接口权限\n- 无\n\n## 请求参数\n| 参数名 | 必选 | 类型    | 说明   | 校验范围        |\n| ------ | ---- | ------- | ------ | --------------- |\n| id     | 是   | Integer | 文章id | 非空，最小值为1 |\n\n\n\n\n## 请求示例\n```json\nlocalhost:9527/content/article/id?id=28\n```\n\n## 返回结果\n```json\n{\n    \"code\": \"200\",\n    \"message\": \"成功\",\n    \"result\": {\n        \"id\": 28,\n        \"userId\": 1,\n        \"title\": \"1188\",\n        \"contentMd\": \"测试数据回滚\",\n        \"contentImg\": \"1\",\n        \"contentMemo\": \"\",\n        \"articleType\": \"5,6\",\n        \"articleLabel\": \"5\",\n        \"articleStatus\": 2,\n        \"browseCount\": 0,\n        \"likeCount\": 0,\n        \"createTime\": \"2024-01-18 16:43:34\",\n        \"updateTime\": \"2024-01-18 16:43:34\",\n        \"articleIds\": null,\n        \"pageSize\": null,\n        \"pageNum\": null,\n        \"type\": null,\n        \"selectUser\": null,\n        \"selectStatus\": null,\n        \"sortType\": null,\n        \"blogUser\": {\n            \"id\": 1,\n            \"username\": \"gszero\",\n            \"password\": null,\n            \"nickname\": \"GSZero\",\n            \"headImg\": \"https://fuss10.elemecdn.com/e/5d/4a731a90594a4af544c0c25941171jpeg.jpeg\",\n            \"email\": \"470687917@qq.com\",\n            \"status\": 1,\n            \"createTime\": \"2022-06-07 00:00:00\",\n            \"updateTime\": \"2022-06-07 02:02:03\"\n        },\n        \"articleLabelList\": null,\n        \"articleTypeList\": null,\n        \"articleTypes\": [\n            {\n                \"id\": 5,\n                \"parentId\": 0,\n                \"typeName\": \"Java\",\n                \"num\": 2,\n                \"node\": 0,\n                \"createUser\": 1,\n                \"createTime\": \"2024-01-18 14:14:58\",\n                \"updateTime\": \"2024-01-18 14:14:58\"\n            },\n            {\n                \"id\": 6,\n                \"parentId\": 5,\n                \"typeName\": \"@Transactional\",\n                \"num\": 2,\n                \"node\": 0,\n                \"createUser\": 1,\n                \"createTime\": \"2024-01-18 14:15:06\",\n                \"updateTime\": \"2024-01-18 14:15:06\"\n            }\n        ],\n        \"articleLabels\": [\n            {\n                \"id\": 5,\n                \"userId\": 1,\n                \"labelType\": 2,\n                \"labelName\": \"注解\",\n                \"articleNum\": 2,\n                \"createTime\": \"2024-01-18 14:15:46\",\n                \"updateTime\": \"2024-01-18 14:15:46\"\n            }\n        ]\n    },\n    \"success\": true\n}\n```\n\n## result数据\n| 参数名          | 类型    | 说明               |\n| --------------- | ------- | ------------------ |\n| result          | Object  | 文章查询数据       |\n| └─id            | Integer | 文章id             |\n| └─userId        | Integer | 文章所属用户id     |\n| └─title         | String  | 文章标题           |\n| └─contentMd     | String  | 文章内容           |\n| └─contentImg    | String  | 文章图片           |\n| └─contentMemo   | String  | 文章简要描述       |\n| └─articleType   | String  | 文章类型字符串     |\n| └─articleLabel  | String  | 文章标签字符串     |\n| └─articleStatus | Integer | 文章状态           |\n| └─browseCount   | Integer | 浏览次数           |\n| └─likeCount     | Integer | 点赞次数           |\n| └─createTime    | Date    | 文章创建时间       |\n| └─updateTime    | Date    | 文章最近修改时间   |\n| └─blogUser      | Object  | 文章所属用户详情   |\n| └─└─id          | Integer | 用户id             |\n| └─└─username    | String  | 用户名             |\n| └─└─nickname    | String  | 用户昵称           |\n| └─└─headImg     | String  | 用户头像           |\n| └─└─email       | String  | 用户邮箱           |\n| └─└─status      | Integer | 用户状态           |\n| └─└─createTime  | Date    | 用户注册时间       |\n| └─└─updateTime  | Date    | 用户最近登录时间   |\n| └─articleTypes  | List    | 文章分类详情       |\n| └─└─id          | Integer | 文章分类id         |\n| └─└─parentId    | Integer | 文章分类上级分类id |\n| └─└─typeName    | String  | 分类名称           |\n| └─└─num         | Integer | 该分类下文章数量   |\n| └─└─node        | Integer |                    |\n| └─└─createUser  | Integer | 创建用户id         |\n| └─└─createTime  | Date    | 创建时间           |\n| └─└─updateTime  | Date    | 最近修改时间       |\n| └─articleLabels | List    | 文章标签详情       |\n| └─└─id          | Integer | 文章标签id         |\n| └─└─userId      | Integer | 创建用户id         |\n| └─└─labelType   | Integer | 标签类型           |\n| └─└─labelName   | String  | 标签名称           |\n| └─└─articleNum  | Integer | 标签下文章数量     |\n| └─└─createTime  | Date    | 标签创建时间       |\n| └─└─updateTime  | Date    | 标签最近修改时间   |\n\n\n\n## 错误码\n| 错误码编号 | 描述                                          | 解决方法 |\n| ---------- | --------------------------------------------- | -------- |\n| 000001     | 参数校验错误（返回字段message有详细校验信息） | 修改参数 |\n| 000102     | 未知错误                                      | 无       |\n\n\n## 备注\n', NULL, NULL, '2024-01-19 00:54:57', '2024-01-19 00:55:11', 1);
INSERT INTO `doc_content` VALUES (57, 1, 111, '## 简要描述\n- 修改文章\n\n## 请求url\n- `http://ip:port/content/article/update`\n\n## 请求方式\n- POST\n\n## 接口权限\n- `sys:article:update`\n\n## 请求参数\n| 参数名        | 必选 | 类型    | 说明         | 校验范围                                                                           |\n| ------------- | ---- | ------- | ------------ | ---------------------------------------------------------------------------------- |\n| id            | 是   | Integer | 文章id       | 非空，最小值为1                                                                    |\n| title         | 是   | String  | 文章标题     | 非空，长度在1-46字符                                                               |\n| contentMd     | 否   | String  | 文章内容     | 无                                                                                 |\n| contentImg    | 否   | String  | 文章图片     | 字符串最长不超过255                                                                |\n| contentMemo   | 否   | String  | 文章简要描述 | 无                                                                                 |\n| articleType   | 否   | String  | 文章分类     | 文章分类id字符串 多个id使用 , 分隔 校验正则表达式 `^$\\|^[0-9]+(,[0-9]+)+\\|[0-9]+$` |\n| articleLabel  | 否   | String  | 文章标签     | 文章标签id字符串 多个id使用 , 分隔 校验正则表达式 `^$\\|^[0-9]+(,[0-9]+)+\\|[0-9]+$` |\n| articleStatus | 是   | Integer | 文章状态     | 非空可选范围是 `文章状态（2：置顶 1：发布 0：草稿）`                               |\n\n\n\n## 请求示例\n```json\n{\n	\"id\": 27,\n	\"title\": \"27\",\n	\"contentMd\": \"测试数据回滚\",\n	\"contentImg\": \"77\",\n	\"contentMemo\": \"\",\n	\"articleType\": \"6\",\n	\"articleLabel\": \"5\",\n	\"articleStatus\": 1\n}\n```\n\n## 返回结果\n```json\n{\n    \"code\": \"200\",\n    \"message\": \"成功\",\n    \"result\": 27,\n    \"success\": true\n}\n```\n\n## result数据\n| 参数名 | 类型    | 说明       |\n| ------ | ------- | ---------- |\n| result | Integer | 修改文章id |\n\n\n## 错误码\n| 错误码编号 | 描述                                          | 解决方法       |\n| ---------- | --------------------------------------------- | -------------- |\n| 000001     | 参数校验错误（返回字段message有详细校验信息） | 修改参数       |\n| 000102     | 未知错误                                      | 无             |\n| 040001     | 文章不存在                                    | 修改文章id     |\n| 040101     | 文章分类不存在                                | 修改文章分类id |\n| 040201     | 文章标签不存在                                | 修改文章标签id |\n\n## 备注\n', NULL, NULL, '2024-01-19 00:55:29', '2024-01-19 00:55:43', 1);
INSERT INTO `doc_content` VALUES (58, 1, 112, '## 简要描述\n- 分页查询文章\n\n## 请求url\n- `http://ip:port/content/article/list`\n\n## 请求方式\n- POST\n\n## 接口权限\n- 无\n\n## 请求参数\n| 参数名       | 必选 | 类型    | 说明                                                         | 校验范围                                                 |\n| ------------ | ---- | ------- | ------------------------------------------------------------ | -------------------------------------------------------- |\n| pageNum      | 是   | Integer | 页数                                                         | 非空    [5-100]                                          |\n| pageSize     | 是   | Integer | 页大小                                                       | 非空 大于 1                                              |\n| type         | 是   | Integer | 接口查询位置，管理页面只能查询自己的文章，且指定用户字段失效 | 0：首页 1：管理页面                                      |\n| selectUser   | 否   | Integer | 查询文章所属用户  默认为0                                    | 0：全部用户 x：指定用户                                  |\n| selectStatus | 是   | String  | 查询文章状态 0：草稿 1：已发布文章 2：置顶 3：已删除         | 非空 多选使用,分隔 校验正则`^[0-3](,[0-3]){0,3}\\|[0-3]$` |\n| sortType     | 否   | String  | 排序方式 0：置顶排序 1：更新时间排序                         | 多选使用,分隔 校验正则`^$\\|^[0-1](,[0-1])\\|[0-1]$`       |\n| articleType  | 否   | String  | 文章分类                                                     | 校验正则 `^$\\|^[0-9]+$`                                  |\n\n\n\n\n\n## 请求示例\n```json\nlocalhost:9527/content/article/list?pageNum=1&pageSize=5&type=0&selectUser=0&selectStatus=1,2,3&sortType=0,1&articleType=6\n```\n\n## 返回结果\n```json\n{\n    \"code\": \"200\",\n    \"message\": \"成功\",\n    \"result\": {\n        \"page\": 1,\n        \"size\": 5,\n        \"total\": 2,\n        \"list\": [\n            {\n                \"id\": 28,\n                \"userId\": 1,\n                \"title\": \"1188\",\n                \"contentMd\": \"测试数据回滚\",\n                \"contentImg\": \"13\",\n                \"contentMemo\": \"\",\n                \"articleType\": \"5,6\",\n                \"articleLabel\": \"5\",\n                \"articleStatus\": 2,\n                \"browseCount\": 0,\n                \"likeCount\": 0,\n                \"createTime\": \"2024-01-18 16:43:34\",\n                \"updateTime\": \"2024-01-18 16:43:34\",\n                \"articleIds\": null,\n                \"pageSize\": null,\n                \"pageNum\": null,\n                \"type\": null,\n                \"selectUser\": null,\n                \"selectStatus\": null,\n                \"sortType\": null,\n                \"blogUser\": {\n                    \"id\": 1,\n                    \"username\": \"gszero\",\n                    \"password\": null,\n                    \"nickname\": \"GSZero\",\n                    \"headImg\": \"https://fuss10.elemecdn.com/e/5d/4a731a90594a4af544c0c25941171jpeg.jpeg\",\n                    \"email\": \"470687917@qq.com\",\n                    \"status\": 1,\n                    \"createTime\": \"2022-06-07 00:00:00\",\n                    \"updateTime\": \"2022-06-07 02:02:03\"\n                },\n                \"articleLabelList\": null,\n                \"articleTypeList\": null,\n                \"articleTypes\": [\n                    {\n                        \"id\": 5,\n                        \"parentId\": 0,\n                        \"typeName\": \"Java\",\n                        \"num\": 2,\n                        \"node\": 0,\n                        \"createUser\": 1,\n                        \"createTime\": \"2024-01-18 14:14:58\",\n                        \"updateTime\": \"2024-01-18 14:14:58\"\n                    },\n                    {\n                        \"id\": 6,\n                        \"parentId\": 5,\n                        \"typeName\": \"@Transactional\",\n                        \"num\": 2,\n                        \"node\": 0,\n                        \"createUser\": 1,\n                        \"createTime\": \"2024-01-18 14:15:06\",\n                        \"updateTime\": \"2024-01-18 14:15:06\"\n                    }\n                ],\n                \"articleLabels\": [\n                    {\n                        \"id\": 5,\n                        \"userId\": 1,\n                        \"labelType\": 2,\n                        \"labelName\": \"注解\",\n                        \"articleNum\": 2,\n                        \"createTime\": \"2024-01-18 14:15:46\",\n                        \"updateTime\": \"2024-01-18 14:15:46\"\n                    }\n                ]\n            },\n            {\n                \"id\": 29,\n                \"userId\": 1,\n                \"title\": \"1188\",\n                \"contentMd\": \"测试数据回滚\",\n                \"contentImg\": \"3\",\n                \"contentMemo\": \"\",\n                \"articleType\": \"5,6\",\n                \"articleLabel\": \"5\",\n                \"articleStatus\": 1,\n                \"browseCount\": 0,\n                \"likeCount\": 0,\n                \"createTime\": \"2024-01-18 16:43:36\",\n                \"updateTime\": \"2024-01-18 16:43:36\",\n                \"articleIds\": null,\n                \"pageSize\": null,\n                \"pageNum\": null,\n                \"type\": null,\n                \"selectUser\": null,\n                \"selectStatus\": null,\n                \"sortType\": null,\n                \"blogUser\": {\n                    \"id\": 1,\n                    \"username\": \"gszero\",\n                    \"password\": null,\n                    \"nickname\": \"GSZero\",\n                    \"headImg\": \"https://fuss10.elemecdn.com/e/5d/4a731a90594a4af544c0c25941171jpeg.jpeg\",\n                    \"email\": \"470687917@qq.com\",\n                    \"status\": 1,\n                    \"createTime\": \"2022-06-07 00:00:00\",\n                    \"updateTime\": \"2022-06-07 02:02:03\"\n                },\n                \"articleLabelList\": null,\n                \"articleTypeList\": null,\n                \"articleTypes\": [\n                    {\n                        \"id\": 5,\n                        \"parentId\": 0,\n                        \"typeName\": \"Java\",\n                        \"num\": 2,\n                        \"node\": 0,\n                        \"createUser\": 1,\n                        \"createTime\": \"2024-01-18 14:14:58\",\n                        \"updateTime\": \"2024-01-18 14:14:58\"\n                    },\n                    {\n                        \"id\": 6,\n                        \"parentId\": 5,\n                        \"typeName\": \"@Transactional\",\n                        \"num\": 2,\n                        \"node\": 0,\n                        \"createUser\": 1,\n                        \"createTime\": \"2024-01-18 14:15:06\",\n                        \"updateTime\": \"2024-01-18 14:15:06\"\n                    }\n                ],\n                \"articleLabels\": [\n                    {\n                        \"id\": 5,\n                        \"userId\": 1,\n                        \"labelType\": 2,\n                        \"labelName\": \"注解\",\n                        \"articleNum\": 2,\n                        \"createTime\": \"2024-01-18 14:15:46\",\n                        \"updateTime\": \"2024-01-18 14:15:46\"\n                    }\n                ]\n            }\n        ]\n    },\n    \"success\": true\n}\n```\n\n## result数据\n| 参数名            | 类型    | 说明                           |\n| ----------------- | ------- | ------------------------------ |\n| result            | Object  | 文章查询数据                   |\n| └─page            | Integer | 当前查询页                     |\n| └─size            | Integer | 当前查询页大小                 |\n| └─total           | Integer | 本次查询条件下查询到的文章总数 |\n| └─list            | List    | 文章数据列表                   |\n| └─└─id            | Integer | 文章id                         |\n| └─└─userId        | Integer | 文章所属用户id                 |\n| └─└─title         | String  | 文章标题                       |\n| └─└─contentMd     | String  | 文章内容                       |\n| └─└─contentImg    | String  | 文章图片                       |\n| └─└─contentMemo   | String  | 文章简要描述                   |\n| └─└─articleType   | String  | 文章类型字符串                 |\n| └─└─articleLabel  | String  | 文章标签字符串                 |\n| └─└─articleStatus | Integer | 文章状态                       |\n| └─└─browseCount   | Integer | 浏览次数                       |\n| └─└─likeCount     | Integer | 点赞次数                       |\n| └─└─createTime    | Date    | 文章创建时间                   |\n| └─└─updateTime    | Date    | 文章最近修改时间               |\n| └─└─blogUser      | Object  | 文章所属用户详情               |\n| └─└─└─id          | Integer | 用户id                         |\n| └─└─└─username    | String  | 用户名                         |\n| └─└─└─nickname    | String  | 用户昵称                       |\n| └─└─└─headImg     | String  | 用户头像                       |\n| └─└─└─email       | String  | 用户邮箱                       |\n| └─└─└─status      | Integer | 用户状态                       |\n| └─└─└─createTime  | Date    | 用户注册时间                   |\n| └─└─└─updateTime  | Date    | 用户最近登录时间               |\n| └─└─articleTypes  | List    | 文章分类详情                   |\n| └─└─└─id          | Integer | 文章分类id                     |\n| └─└─└─parentId    | Integer | 文章分类上级分类id             |\n| └─└─└─typeName    | String  | 分类名称                       |\n| └─└─└─num         | Integer | 该分类下文章数量               |\n| └─└─└─node        | Integer |                                |\n| └─└─└─createUser  | Integer | 创建用户id                     |\n| └─└─└─createTime  | Date    | 创建时间                       |\n| └─└─└─updateTime  | Date    | 最近修改时间                   |\n| └─└─articleLabels | List    | 文章标签详情                   |\n| └─└─└─id          | Integer | 文章标签id                     |\n| └─└─└─userId      | Integer | 创建用户id                     |\n| └─└─└─labelType   | Integer | 标签类型                       |\n| └─└─└─labelName   | String  | 标签名称                       |\n| └─└─└─articleNum  | Integer | 标签下文章数量                 |\n| └─└─└─createTime  | Date    | 标签创建时间                   |\n| └─└─└─updateTime  | Date    | 标签最近修改时间               |\n\n\n\n## 错误码\n| 错误码编号 | 描述                                          | 解决方法       |\n| ---------- | --------------------------------------------- | -------------- |\n| 000001     | 参数校验错误（返回字段message有详细校验信息） | 修改参数       |\n| 000102     | 未知错误                                      | 无             |\n| 040101     | 文章分类不存在                                | 修改文章分类id |\n\n\n## 备注\n', NULL, NULL, '2024-01-19 00:55:56', '2024-01-19 00:56:20', 1);
INSERT INTO `doc_content` VALUES (59, 1, 113, '## 简要描述\n- 删除文章\n\n## 请求url\n- `http://ip:port/content/article/delete`\n\n## 请求方式\n- DELETE\n\n## 接口权限\n- `sys:article:delete`\n\n## 请求参数\n| 参数名     | 必选 | 类型   | 说明         | 校验范围                                                         |\n| ---------- | ---- | ------ | ------------ | ---------------------------------------------------------------- |\n| articleIds | 是   | String | 文章id字符串 | 文章id字符串 多个id使用 , 分隔 校验正则表达式 `^[0-9]+(,[0-9]+)+ | [0-9]+$` |\n\n## 请求示例\n```\nlocalhost:9527/content/article/delete?articleIds=26,27\n```\n\n## 返回结果\n```json\n{\n    \"code\": \"200\",\n    \"message\": \"成功\",\n    \"result\": 2,\n    \"success\": true\n}\n```\n\n## result数据\n| 参数名 | 类型    | 说明         |\n| ------ | ------- | ------------ |\n| result | Integer | 删除文章数量 |\n\n\n## 错误码\n| 错误码编号 | 描述                                          | 解决方法 |\n| ---------- | --------------------------------------------- | -------- |\n| 000001     | 参数校验错误（返回字段message有详细校验信息） | 修改参数 |\n| 000102     | 未知错误                                      | 无       |\n\n## 备注\n', NULL, NULL, '2024-01-19 00:56:34', '2024-01-19 00:56:47', 1);
INSERT INTO `doc_content` VALUES (60, 1, 114, '## 简要描述\n- 新增文章\n\n## 请求url\n- `http://ip:port/content/article/save`\n\n## 请求方式\n- POST\n\n## 接口权限\n- `sys:article:insert`\n\n## 请求参数\n| 参数名        | 必选 | 类型    | 说明         | 校验范围                                                                           |\n| ------------- | ---- | ------- | ------------ | ---------------------------------------------------------------------------------- |\n| title         | 是   | String  | 文章标题     | 非空，长度在1-46字符                                                               |\n| contentMd     | 否   | String  | 文章内容     | 无                                                                                 |\n| contentImg    | 否   | String  | 文章图片     | 字符串最长不超过255                                                                |\n| contentMemo   | 否   | String  | 文章简要描述 | 无                                                                                 |\n| articleType   | 否   | String  | 文章分类     | 文章分类id字符串 多个id使用 , 分隔 校验正则表达式 `^$\\|^[0-9]+(,[0-9]+)+\\|[0-9]+$` |\n| articleLabel  | 否   | String  | 文章标签     | 文章标签id字符串 多个id使用 , 分隔 校验正则表达式 `^$\\|^[0-9]+(,[0-9]+)+\\|[0-9]+$` |\n| articleStatus | 是   | Integer | 文章状态     | 非空可选范围是 `文章状态（2：置顶 1：发布 0：草稿）`                               |\n\n\n\n## 请求示例\n```json\n{\n	\"title\": \"测试数据回滚\",\n	\"contentMd\": \"测试数据回滚\",\n	\"contentImg\": \"\",\n	\"contentMemo\": \"\",\n	\"articleType\": \"6\",\n	\"articleLabel\": \"5\",\n	\"articleStatus\": 1\n}\n```\n\n## 返回结果\n```json\n{\n    \"code\": \"200\",\n    \"message\": \"成功\",\n    \"result\": 20,\n    \"success\": true\n}\n```\n\n## result数据\n| 参数名 | 类型    | 说明       |\n| ------ | ------- | ---------- |\n| result | Integer | 新增文章id |\n\n\n## 错误码\n| 错误码编号 | 描述                                          | 解决方法       |\n| ---------- | --------------------------------------------- | -------------- |\n| 000001     | 参数校验错误（返回字段message有详细校验信息） | 修改参数       |\n| 000102     | 未知错误                                      | 无             |\n| 040101     | 文章分类不存在                                | 修改文章分类id |\n| 040201     | 文章标签不存在                                | 修改文章标签id |\n\n## 备注\n', NULL, NULL, '2024-01-19 00:57:02', '2024-01-19 00:57:17', 1);
INSERT INTO `doc_content` VALUES (61, 1, 117, '收到了大华24年春节礼盒，我的评价是一般。\n## 礼盒本体\n![24年春节礼盒.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-14-29_HlcLxP_24年春节礼盒.jpg)\n\n## 礼盒内部\n一个空的袋子\n![礼盒内部.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-14-52_foaqWW_礼盒内部.jpg)\n\n## 对联\n![对联.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-15-44_xegHeH_对联.jpg)\n\n## 挂饰\n![挂饰.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-15-51_eTZfwu_挂饰.jpg)\n\n## 空的红包\n![红包.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-16-13_oKWBDF_红包.jpg)\n\n充满了廉价的气味，好像去年的春节礼盒也不怎么样，有个玩偶摆件多好，尽发些没用的东西。', NULL, NULL, '2024-01-31 23:12:55', '2024-01-31 23:17:22', 1);
INSERT INTO `doc_content` VALUES (62, 1, 119, '# 01-26下午骑行\n周日看单片机累了，下午出去遛弯。\n\n## 全程\n![全程.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-23-45_sfEguX_全程.jpg){{{width=\\\"300\\\" height=\\\"auto\\\"}}}\n\n## 时速海拔\n![时速海拔.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-26-05_NifLiz_时速海拔.jpg){{{width=\\\"300\\\" height=\\\"auto\\\"}}}\n\n## 速度\n![速度.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-26-20_vaVAER_速度.jpg){{{width=\\\"300\\\" height=\\\"auto\\\"}}}\n\n## 江景\n远望奥体广场，骑过去因为没有预约所以不能进去看看\n![奥体广场远景.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-01-31_23-26-36_bWtXzT_奥体广场远景.jpg)', NULL, NULL, '2024-01-31 23:18:44', '2024-01-31 23:30:32', 1);
INSERT INTO `doc_content` VALUES (63, 1, 122, '# AQS详解 （AbstractQueuedSynchronizer 抽象队列式同步器）\n## 框架：\n![721070-20170504110246211-10684485.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_10-54-45_6efc90_721070-20170504110246211-10684485.png)\nAQS维护了一个volatile int state（代表共享资源）和一个FIFO线程等待队列（多线程争用资源被阻塞时会进入此队列）\nAQS是一个抽象类，主要通过继承方式来使用，它本身没有实现任何的同步接口，仅仅定义了同步状态的获取以及释放的方法来提供自定义的同步组件\nAQS的功能分两种：独占和共享\n- 独占锁：每次只能由一个线程持有锁，如ReentrantLock\n- 共享锁：允许多个线程持有锁，如ReentrantReadWriteLock\n\n## AQS的内部实现：\n![aqs1.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_10-59-20_6ef536_aqs1.png)\nAQS的实现依赖内部的同步队列，也就是FIFO的双向队列，如果当前线程竞争锁失败，那么AQS会把当前线程以及等待状态信息构成一个Node加入到同步队列中，同时再阻塞该线程。当获取锁的线程释放锁之后，会从队列中唤醒一个阻塞的节点线程。\n### 释放锁以及添加线程对于队列的变化：\n#### 添加节点：\n![aqs2.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_11-03-29_b3f71a_aqs2.png)\n过程：\n1. 新的线程封装成Node节点追加到同步队列中，设置prev节点以及修改当前节点的前置节点的next节点指向自己\n2. 通过CAS将tail重新指向新的尾部节点\n\n#### 释放锁移除节点：\n![aqs3.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_11-06-08_c90c25_aqs3.png)\n过程：\n1. 修改head节点指向下一个获得锁的节点\n2. 新的获得锁的节点，将prev的指针指向null\n\n# AQS源码分析：\nSync是一个静态内部类，它继承了AQS这个抽象类，前面说过AQS是一个同步工具，主要用来实现同步控制。我们在利用这个工具的时候，会继承它来实现同步控制功能。\nSync这个类有两个具体的实现，分别是NofairSync(非公平锁),FailSync(公平锁).\n公平锁 表示所有线程严格按照FIFO来获取锁\n非公平锁 表示可以存在抢占锁的功能，也就是说不管当前队列上是否存在其他线程等待，新线程都有机会抢占锁\n\n## lock:\n```java\nfinal void lock() {\n    if (compareAndSetState(0, 1)) //通过cas操作来修改state状态，表示争抢锁的操作\n      setExclusiveOwnerThread(Thread.currentThread());//设置当前获得锁状态的线程\n    else\n      acquire(1); //尝试去获取锁\n}\n```\n1. 由于这里是非公平锁，所以调用lock方法时，先去通过cas去抢占锁\n2. 如果抢占锁成功，保存获得锁成功的当前线程\n3. 抢占锁失败，调用acquire来走锁竞争逻辑\n\n## compareAndSetState:\n```java\nprotected final boolean compareAndSetState(int expect, int update) {\n    // See below for intrinsics setup to support this\n    return unsafe.compareAndSwapInt(this, stateOffset, expect, update);\n}\n```\n通过cas乐观锁的方式来做比较并替换,如果当前内存中的state的值和预期值expect相等，则替换为update。更新成功返回true，否则返回false.\n这个操作是原子的，不会出现线程安全问题，这里面涉及到Unsafe这个类的操作，一级涉及到state这个属性的意义。\n当state=0时，表示无锁状态\n当state>0时，表示已经有了线程获得了锁，即state=1，但是因为ReentrantLock允许重入，所以同一个线程多次获得同步锁的时候，state会递增，比如重入5次，那么state=5，而在释放锁的时候同样需要释放5次知道state=0其它线程才有资格获得锁\n\n## Unsafe：\n不属于Java标准，提供一些低层次操作，如直接内存访问、线程调度\n```java\npublic final native boolean compareAndSwapInt(Object var1, long var2, int var4, int var5);\n```\n这是一个native方法，第一个参数为需要改变的对象，第二个为偏移量（ 即之前求出来的headOffset的值），第三个为预期的值，第四个为更新后的值\n整个方法的作用是如果当前时刻的值等于预期值var4相等，则更新为新的期望值 var5，如果更新成功，则返回true，否则返回false；\n\n## acquire：\nacquire是AQS中的方法，如果CAS操作未成功，说明state不为0，此时继续acquire(1)\n```java\npublic final void acquire(int arg) {\n    if (!tryAcquire(arg) &&\n        acquireQueued(addWaiter(Node.EXCLUSIVE), arg))\n        selfInterrupt();\n}\n```\n![aqs4.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_11-42-06_90f21f_aqs4.png)\n1. 调用自定义同步器的tryAcquire()尝试直接去获取资源，如果成功则直接返回\n2. 没成功，则addWaiter()将该线程加入等待队列的尾部，并标记为独占模式\n3. acquireQueued()使线程在等待队列中休息，有机会时（轮到自己，会被unpark()）会去尝试获取资源。获取到资源后才返回。如果在整个等待过程中被中断过，则返回true，否则返回false\n4. 如果线程在等待过程中被中断过，它是不响应的。只是获取资源后才再进行自我中断selfInterrupt()，将中断补上\n\n## tryAcquire：\n此方法尝试去获取独占资源。如果获取成功，则直接返回true，否则直接返回false。\n```java\nprotected boolean tryAcquire(int arg) {\n    throw new UnsupportedOperationException();\n}\n```\n这里之所以没有定义成abstract，是因为独占模式下只用实现tryAcquire-tryRelease，而共享模式下只用实现tryAcquireShared-tryReleaseShared。如果都定义成abstract，那么每个模式也要去实现另一模式下的接口，可以尽量减少不必要的工作量。\n\n## addWaiter(Node):\n此方法用于将当前线程加入到等待队列的队尾，并返回当前线程所在的结点。\n```java\nprivate Node addWaiter(Node mode) {\n    //以给定的模式构造节点。mode有两种 EXCLUSIVE 独占 和 SHARED 共享\n    Node node = new Node(Thread.currentThread(), mode);\n    // Try the fast path of enq; backup to full enq on failure\n    //尝试快速方式直接放到队尾\n    Node pred = tail;\n    if (pred != null) {\n        node.prev = pred;\n        if (compareAndSetTail(pred, node)) {\n            pred.next = node;\n            return node;\n        }\n    }\n    //上一步失败则通过enq入队\n    enq(node);\n    return node;\n}\n```\n\n## enq(Node)：\n用于将Node加入队尾\n```java\nprivate Node enq(final Node node) {\n    //CAS自旋，直到成功加入队尾\n    for (;;) {\n        Node t = tail;\n        if (t == null) { // 队列为空，创建一个空的标志节点作为head节点，并且tail也指向它\n            if (compareAndSetHead(new Node()))\n                tail = head;\n        } else {    //正常放入队尾\n            node.prev = t;\n            if (compareAndSetTail(t, node)) {\n                t.next = node;\n                return t;\n            }\n        }\n    }\n}\n```\n\n## acquireQueued(Node, int):\n在等待队列中等待，直到其他线程释放资源唤醒该线程\n```java\nfinal boolean acquireQueued(final Node node, int arg) {\n    //标记是否成功拿到资源\n    boolean failed = true;\n    try {\n        //标记等待过程中是否被中断过\n        boolean interrupted = false;\n        //自旋 \n        for (;;) {\n            //拿到前驱\n            final Node p = node.predecessor();\n            //如果前驱是head，即该节点是第二个，那么便有资格去尝试获取资源，可能是head释放玩资源唤醒，\n            //也可能是head倍interrupt\n            if (p == head && tryAcquire(arg)) {\n                //获取资源后,head指向该节点\n                setHead(node); //代码块1\n                //将head的下一个指针置空，方便GC回收\n                p.next = null; \n                //成功获取资源\n                failed = false;\n                //返回等待过程中是否被中断过\n                return interrupted;\n            }\n            //如果可以进入等待状态，就通过park()进入waiting状态，直到被unpark()\n            if (shouldParkAfterFailedAcquire(p, node) &&\n                parkAndCheckInterrupt())\n                //在等待过程中只要被中断过就标记为true\n                interrupted = true;\n        }\n    } finally {\n        //如果等待过程中没有成功获取资源(如timeout或者可中断的情况下被中断了)，那么取消节点在队列中等待\n        if (failed)\n            cancelAcquire(node);\n    }\n}\n\n// 代码块1:\nprivate void setHead(Node node) {\n    head = node;\n    node.thread = null;\n    node.prev = null;\n}\n```\n流程：\n1. 结点进入队尾后，检查状态，找到安全休息点；\n2. 调用park()进入waiting状态，等待unpark()或interrupt()唤醒自己；\n3. 被唤醒后，看自己是不是有资格能拿到号。如果拿到，head指向当前结点，并返回从入队到拿到号的整个过程中是否被中断过；如果没拿到，继续流程1。\n\n## shouldParkAfterFailedAcquire()：\n用于检查状态，判断是否可以休息\n```java\nprivate static boolean shouldParkAfterFailedAcquire(Node pred, Node node) {\n    //拿到前驱的状态\n    int ws = pred.waitStatus;\n    if (ws == Node.SIGNAL)\n        //如果已经告诉前驱节点获取资源后通知，就可以休息了\n        return true;\n    if (ws > 0) {\n        //如果前驱放弃了，那就一直找，直到找到一个正常等待的状态，并排在它后面\n        //放弃的节点会被GC清理\n        do {\n            node.prev = pred = pred.prev;\n        } while (pred.waitStatus > 0);\n        pred.next = node;\n    } else {\n        //如果前驱正常，就将前驱的状态设置为SIGNAl，并且通知前驱获取资源后通知，如果前驱刚刚释放资源会失败\n        compareAndSetWaitStatus(pred, ws, Node.SIGNAL);\n    }\n    return false;\n}\n```\n整个流程中如果前驱节点状态不是SIGNAL就不能去休息\n\n## parkAndCheckInterrupt():\n让线程休息，真正进入等待状态\n```java\nprivate final boolean parkAndCheckInterrupt() {\n    //调用park()使线程进入waiting状态\n    LockSupport.park(this);\n    //如果被唤醒查看自己是不是被中断的\n    return Thread.interrupted();\n}\n    waiting状态下，唤醒线程的方法：\n        1.被unpark()\n        2.被interrupt()\n    Thread.interrupted()会清除当前线程的中断标记位\n\nunLock():\npublic void unlock() {\n    sync.release(1);\n}\n\nrelease():\npublic final boolean release(int arg) {\n    if (tryRelease(arg)) {\n        //找到头节点\n        Node h = head;\n        if (h != null && h.waitStatus != 0)\n            //唤醒等待队列里的下一个线程\n            unparkSuccessor(h);\n        return true;\n    }\n    return false;\n}\n```\n调用tryRelease()释放资源，是根据tryRelease()的返回值判断该线程是否已经完成释放资源\n\n## tryRelease():\n\n```java\nprotected boolean tryRelease(int arg) {\n    throw new UnsupportedOperationException();\n}\n```\n于tryAcquire()一样，这个方法需要独占模式的自定义同步器去实现。一般情况，tryRelease()都会成功，因为这是独占模式，该线程释放资源，必定是已经拿到了资源，直接减掉相应量的资源即可，也不需要考虑线程安全的问题，注意tryRelease()在实现时要有返回值，如果已经彻底释放资源state=0，要返回true，否则返回false\n\n## unparkSuccessor(Node):\n```java\nprivate void unparkSuccessor(Node node) {\n    //node一般为线程所在节点\n    int ws = node.waitStatus;\n    if (ws < 0)\n        //置零当前线程所在的节点状态，允许失败\n        compareAndSetWaitStatus(node, ws, 0);\n    //找到下一个需要唤醒的节点\n    Node s = node.next;\n    //如果为空或取消\n    if (s == null || s.waitStatus > 0) {\n        s = null;\n        //从后向前找\n        for (Node t = tail; t != null && t != node; t = t.prev)\n            // <= 0 的节点都是还有效的节点\n            if (t.waitStatus <= 0)\n                s = t;\n    }\n    if (s != null)\n        //唤醒\n        LockSupport.unpark(s.thread);\n}\n```\n用unpark()唤醒等待队列中最前边的那个未放弃线程\nrelease()是独占模式下线程释放共享资源的顶层入口，会释放指定量的资源，如果彻底释放了，它会唤醒等待队列里的其它线程获取资源\n\n## acquireShared(int):\n此方法是共享模式下线程获取共享资源的顶层入口。它会获取指定量的资源，获取成功则直接返回，获取失败则进入等待队列，直到获取到资源为止，整个过程忽略中断\n```java\npublic final void acquireShared(int arg) {\n    if (tryAcquireShared(arg) < 0)\n        doAcquireShared(arg);\n}\n```\ntryAcquireShared()需要自定义同步器去实现。但是AQS已经定义好了返回值的语义：负值代表获取失败；0代表获取成功，但是没有剩余资源；正数表示获取成功，还有剩余资源，其它线程还可以去获取。流程：\n1. tryAcquireShared()尝试获取资源，成功则直接返回\n2. 失败则通过doAcquireShared()进入等待队列，直到获取到资源才返回\n\n## doAcquireShared():\n```java\nprivate void doAcquireShared(int arg) {\n    //加入队列尾部\n    final Node node = addWaiter(Node.SHARED);\n    //是否成功标志\n    boolean failed = true;\n    try {\n        //等待过程中是否被中断标记\n        boolean interrupted = false;\n        for (;;) {\n            //前驱\n            final Node p = node.predecessor();\n            //因为head是拿到资源的线程，如果到head的下一个，此时线程被唤醒，很可能是head用完资源了\n            if (p == head) {\n                //尝试获取资源\n                int r = tryAcquireShared(arg);\n                //如果获取成功\n                if (r >= 0) {\n                    //将head指向自己，还有剩余的资源可以唤醒之后的线程\n                    setHeadAndPropagate(node, r);\n                    //帮助GC回收内存\n                    p.next = null; // help GC\n                    //如果等待过程中被打断过，此时将中断补上\n                    if (interrupted)\n                        selfInterrupt();\n                    failed = false;\n                    return;\n                }\n            }\n            //判断状态，寻找安全点，进入waiting状态，等待unpark()或interrupt()\n            if (shouldParkAfterFailedAcquire(p, node) &&\n                parkAndCheckInterrupt())\n                interrupted = true;\n        }\n    } finally {\n        if (failed)\n            cancelAcquire(node);\n    }\n}\n```\n跟独占模式比，还有一点需要注意的是，这里只有线程是head.next时（“老二”），才会去尝试获取资源，有剩余的话还会唤醒之后的队友。假如老大用完后释放了5个资源，而老二需要6个，老三需要1个，老四需要2个。老大先唤醒老二，老二一看资源不够，会继续park()等待其他线程释放资源，也更不会去唤醒老三和老四了。独占模式，同一时刻只有一个线程去执行，这样做未尝不可；但共享模式下，多个线程是可以同时执行的，现在因为老二的资源需求量大，而把后面量小的老三和老四也都卡住了。当然，这并不是问题，只是AQS保证严格按照入队顺序唤醒罢了（保证公平，但降低了并发）。\n\n## setHeadAndPropagate(Node, int):\n```java\nprivate void setHeadAndPropagate(Node node, int propagate) {\n    Node h = head; // Record old head for check below\n    //head指向自己\n    setHead(node);\n    //如果还有剩余资源，继续唤醒下一个线程\n    if (propagate > 0 || h == null || h.waitStatus < 0 ||\n        (h = head) == null || h.waitStatus < 0) {\n        Node s = node.next;\n        if (s == null || s.isShared())\n            doReleaseShared();\n    }\n}\n```\n此方法在setHead()的基础上多了一步，就是自己苏醒的同时，如果条件符合（比如还有剩余资源），还会去唤醒后继结点，毕竟是共享模式！\n\n## releaseShared():\n此方法是共享模式下线程释放共享资源的顶层入口。可以释放指定量资源，如果成功释放资源且允许唤醒等待线程，它会唤醒等待队列里的其它线程来获取资源\n```java\npublic final boolean releaseShared(int arg) {\n    //尝试释放资源\n    if (tryReleaseShared(arg)) {\n        //唤醒后继节点\n        doReleaseShared();\n        return true;\n    }\n    return false;\n}\n```\n于独占模式下的release()相似，但有一点稍微需要注意：独占模式下的tryRelease()在完全释放完资源（state=0）才会唤醒其它线程，这主要是基于独占下的可重入考量；而共享模式下的releaseShared()则没这种要求，共享模式本质就是控制一定量的线程并发执行。举个例子：资源总量是13，A（5）和B（7）分别获取到资源并发运行，C（4）来时只剩1个资源就需要等待。A在运行过程中释放掉2个资源量，然后tryReleaseShared(2)返回true唤醒C，C一看只有3个仍不够继续等待；随后B又释放2个，tryReleaseShared(2)返回true唤醒C，C一看有5个够自己用了，然后C就可以跟A和B一起运行。而ReentrantReadWriteLock读锁的tryReleaseShared()只有在完全释放掉资源（state=0）才返回true，所以自定义同步器可以根据需要决定tryReleaseShared()的返回值。\n\n## doReleaseShared():\n方法用于唤醒后继\n```java\nprivate void doReleaseShared() {\n    for (;;) {\n        Node h = head;\n        if (h != null && h != tail) {\n            int ws = h.waitStatus;\n            if (ws == Node.SIGNAL) {\n                if (!compareAndSetWaitStatus(h, Node.SIGNAL, 0))\n                    continue;            // loop to recheck cases\n                //唤醒后继\n                unparkSuccessor(h);\n            }\n            else if (ws == 0 &&\n                     !compareAndSetWaitStatus(h, 0, Node.PROPAGATE))\n                continue;                // loop on failed CAS\n        }\n        if (h == head)                   // loop if head changed\n            break;\n    }\n}\n```', NULL, NULL, '2024-04-21 10:54:00', '2024-04-21 14:34:35', 1);
INSERT INTO `doc_content` VALUES (64, 1, 123, '# Java锁\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n# Synchronized\nsynchronized用的锁是存储在Java对象头里面。如果对象是数组类型，则虚拟机用三个字宽存储对象头，如果是非数组类型，则用两个字宽存储对象头。在32位虚拟机中1字宽等于4字节，即32bit\n    \n## Java对象头内容：\n\n1. Mark Word： 1字宽，存储对象的hashCode或锁信息\n2. Class Metedata Address： 1字宽，存储到对象类型的数据指针\n3. Array length： 1字宽，数组的长度（不是数组类型则没有）\n    \nJava对象头里面的Mark Word 默认存储对象的HashCode(25bit)，对象分代年龄(4bit)，是否使用偏向锁(1bit)，锁标志位(2bit)\n    \n在运行期间，Mark Word里存储的数据会随锁标志位变化而变化\n1. 无锁状态：对象的hashCode(25bit),对象分代年龄(4bit),是否使用偏向锁(1bit),锁标志位(2bit)\n2. 偏向锁：线程ID(23bit),Epoch(2bit),对象分代年龄(4bit),是否使用偏向锁(1bit),锁标志位(2bit)\n3. 轻量级锁：指向栈中锁记录的指针(30bit),锁标志位(2bit)\n4. 重量级锁：指向互斥量(重量级锁)的指针(30bit),锁标志位(2bit)\n5. GC标记：空(30bit),锁标志位(2bit)\n\n![Synchronized.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_15-17-20_112936_Synchronized.jpg)\n\n## 偏向锁：\nJavaSE 1.6中，锁有4个状态，级别从低到高依次是：无锁状态，偏向锁状态，轻量级锁状态和重量级锁状态，这几个状态会随着竞争升级，但不会降级\nEpoch表示一个偏向锁的时间戳，用来解决两个线程(一前一后)不存在竞争的情况。引入偏向锁可以降低同一线程锁重入的代价\n锁重入：在已经获得锁的同步方法或者同步代码块内部可以调用锁定对象的其他同步方法，不需要重新获取锁\n### 偏向锁的竞争与释放：\n1. 首先检查对象的Mark Word是否位偏向锁状态，锁标志位01，偏向锁标志位位1\n2. 检查对象头中的线程ID是否为测试线程ID，如果是，进入步骤5，如果不是进入步骤3\n3. 如果对象头中的线程ID不为测试线程ID，测试线程执行CAS操作替换Mark Word。如果替换成功，则执行步骤5,否则，执行步骤4\n4. 如果CAS获取偏向锁失败，则表示存在竞争。当到达全局安全点时获得偏向锁的线程被挂起，偏向锁升级为轻量级锁，被挂起的线程恢复继续执行\n5. 执行同步块代码\n### 偏向锁的优势：\n大多数情况下，锁不存在多线程竞争，总是由同一线程多次获得，为了让线程获得锁的代价更低而引入了偏向锁。当一个线程访问同步块时，会在对象头里记录获得偏向锁的线程ID，以后该线程进入或退出同步块时不需要再通过CAS操作来加锁和解锁，只需要简单测试一下对象头中的线程ID是否和当前竞争锁的线程ID相同。\n## 轻量级锁：\n### 轻量级锁加锁过程：\n1. 线程在执行同步块之前，JVM会先在当前线程的栈中创建一块用于存储锁记录的空间，并将对象头的Mark Word复制到锁记录中，官方称为Displaced Mark Word。\n2. 线程尝试使用CAS操作尝试将Mark Word设置为指向锁记录的指针。如果设置成功，执行步骤3，否则执行步骤4。\n3. 设置成功后，表示当前线程获得了该对象的锁，并将锁标志位设为00。\n4. 如果设置失败，表示其他线程竞争锁，当前线程自旋获取锁。获取失败，轻量级锁升级为重量级锁。自旋：循环一定次数获取锁，可以不阻塞当前线程。\n### 轻量级锁解锁过程：\n使用CAS操作将Displaced Mark Word替换回到对象头，如果成功，则表示没有发生竞争。如果失败，表示当前锁存在竞争，轻量级锁膨胀升级为重量级锁。\n\n## 重量级锁：\n重量锁在JVM中又叫对象监视器（Monitor），它至少包含一个竞争锁的队列，和一个信号阻塞队列（wait队列），前者负责做互斥，后一个用于做线程同步。监视器锁本质又是依赖于底层的操作系统的Mutex Lock来实现的。而操作系统实现线程之间的切换这就需要从用户态转换到核心态，这个成本非常高，状态之间的转换需要相对比较长的时间，这就是为什么Synchronized效率低的原因。    \n## 锁的对比：\n- 偏向锁：优点：加锁和解锁不需要额外的开销。缺点：如果线程间存在竞争，会存在锁撤销的开销。适用场景：适用于只有一个线程访问同步块的场景。\n- 轻量级锁：优点：竞争锁的线程不会阻塞，提高了程序的响应速度。缺点：如果竞争锁的线程始终得不到锁，自旋消耗CPU。适用场景：追求响应时间，同步块执行时间非常快，线程交替执行同步块的情况，如果存在同一时间访问同一锁的情况，就会导致轻量级锁膨胀为重量级锁。。\n- 重量级锁：优点：线程竞争使用自旋，不会消耗CPU。缺点：线程阻塞，响应时间长。使用场景：追求吞吐量的场景。', NULL, NULL, '2024-04-21 15:11:54', '2024-11-14 11:31:16', 1);
INSERT INTO `doc_content` VALUES (65, 1, 124, '# HashMap原理\njdk 1.8 之前： 数据结构是链表散列\njdk 1.8 之后：\n- Node链表的节点数超过了8个会由链表转为红黑树\n- 数据结构变成了 数组 + 红黑树\n- 减少了搜索时间\n   \n由Key计算 hashCode 与右移 16 位的 hashCode 按位异或（使哈希值更加均匀，不容易碰撞）再 (length-1)&hash 计算下标按位异或得到的哈希值对数组长度 取余 操作对于 除数是2的幂次方等价于与其除数 -1 的与操作\n即：  hash%length == hash&(legth-1) 这就是为什么hashmap数组长度为2的幂次方\n\n## 哈希冲突：\n判断当前确定的索引位置是否存在相同hashcode和相同key的元素\nkey相同覆盖旧值，并返回旧值\nkey不同就产生了 hash冲突\n发生hash冲突就会产生链 并向链尾部添加\nHashMap可以存储一个键为空，多个值为空的对象。  \n\n## hash扩容：\nloadFactor  = 0.75\n数组总大小 * loadFactor = 临界值\n元素个数超过临界值会发生扩容（数组扩大2倍）\n   \n## 为什么hashmap线程不安全：\n俩个线程A,B假如A获取了插入位置为x，但是还未插入，此时B也计算出待插入位置为x，则不论AB插入的先后顺序肯定有一个会丢失\n   \n## hashmap死循环：\n1. 原先的hashmap链是 a->b->c\n2. 线程1 执行（Entry<K,V> next = e.next;）后。读取了a 和a.next=b之后线程时间片用完，调用线程2\n3. 线程2 完整的执行整个rehash操作，使hashmap得链变成了c->b->a（jdk1.7中hashmap的rehash用的是头插法）\n4. 继续执行线程1 的循环操作\n- 第一次循环：线程1中的newTable变成了a->null\n- 第二次循环：线程1中的newTable变成了b->a\n- 第三次循环：线程1中的newTable变成了a->b->a\n是基于哈希表的Map接口实现哈希表的作用是用来保证键的唯一性\n   \n## 属性：\nK key\nV value\nEntry<K, V> next\nint hash\n\n## 构造方法：\n|方法名|说明|\n|--|--|\n|HashMap()|构造一个具有默认初始容量 (16) 和默认加载因子 (0.75) 的空 HashMap|\n|HashMap(int initialCapacity)|构造一个带指定初始容量和默认加载因子 (0.75) 的空 HashMap|\n|HashMap(int initialCapacity, float loadFactor)|构造一个带指定初始容量和加载因子的空 HashMap|\n|HashMap(Map<? extends K, ? extends V> m)|构造一个映射关系与指定 Map 相同的新 HashMap|\n\n## 方法摘要：\n|返回值|方法名|说明|\n|--|--|--|\n|void|clear()|从此映射中移除所有映射关系|\n|Object|clone()|返回此 HashMap 实例的浅表副本：并不复制键和值本身|\n|boolean|containsKey(Object key)|如果此映射包含对于指定键的映射关系，则返回 true|\n|boolean|containsValue(Object value)|如果此映射将一个或多个键映射到指定值，则返回 true|\n|Set<Map.Entry<K,V>>|entrySet()|返回此映射所包含的映射关系的 Set 视图|\n|V|get(Object key)|返回指定键所映射的值；如果对于该键来说，此映射不包含任何映射关系，则返回 null|\n|boolean|isEmpty()|如果此映射不包含键-值映射关系，则返回 true|\n|Set<K>|keySet()|返回此映射中所包含的键的 Set 视图|\n|V|put(K key, V value)|在此映射中关联指定值与指定键|\n|void|putAll(Map<? extends K,? extends V> m)|将指定映射的所有映射关系复制到此映射中，这些映射关系将替换此映射目前针对指定映射中所有键的所有映射关系|\n|V|remove(Object key)|从此映射中移除指定键的映射关系（如果存在）|\n|int|size()|返回此映射中的键-值映射关系数|\n|Collection<V>|values()|返回此映射所包含的值的 Collection 视图|\n\n# 源码理解HashMap：\n## HashMap jdk1.7版本：\n### 成员变量：\n![HashMap1.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_17-20-29_e0770d_HashMap1.jpg)\n1. 初始化桶大小，因为底层是数组，所以这是数组默认的大小。\n2. 桶最大值，数组最大的大小。\n3. 默认的负载因子（0.75）\n4. table 真正存放数据的数组。\n5. Map 存放数量的大小。\n6. 桶大小，可在初始化时显式指定。\n7. 负载因子，可在初始化时显式指定。\n\n### 负载因子：\n```java\npublic HashMap() {\n    this(DEFAULT_INITIAL_CAPACITY, DEFAULT_LOAD_FACTOR);\n}\n\npublic HashMap(int initialCapacity, float loadFactor) {\n    if (initialCapacity < 0)\n        throw new IllegalArgumentException(\"Illegal initial capacity: \" + initialCapacity);\n    if (initialCapacity > MAXIMUM_CAPACITY)\n        initialCapacity = MAXIMUM_CAPACITY;\n    if (loadFactor <= 0 || Float.isNaN(loadFactor))\n        throw new IllegalArgumentException(\"Illegal load factor: \" + loadFactor);\n    this.loadFactor = loadFactor;\n    threshold = initialCapacity;\n    init();\n}\n```\n负载因子默认是0.75，即HashMap中数据存放到75%时，会进行扩容（变为原来存储容量的二倍），扩容会将之前所有的key重新计算hash码，即rehash操作，以及复制数据等操作，所以非常消耗性能。\nHashMap中用来存放数据的时Entry类， transient Entry<K,V>[] table = (Entry<K,V>[]) EMPTY_TABLE;\n![HashMap2.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-04-21_18-33-59_7ee852_HashMap2.jpg)\n1. key 就是写入时的键。\n2. value 自然就是值。    \n3. 开始的时候就提到 HashMap 是由数组和链表组成，所以这个 next 就是用于实现链表结构。\n4. hash 存放的是当前 key 的 hashcode。\n\n### put方法\n```java\npublic V put(K key, V value) {\n    if (table == EMPTY_TABLE) {\n        inflateTable(threshold);        //空数组要进行初始化，代码块①\n    }\n    if (key == null)                    //HashMap支持Key == null\n        return putForNullKey(value);\n    int hash = hash(key);                //计算 key 的hash值\n     \n    // 根据hash值，和表当前的长度，得到一个在数组中的下标。重点关注一下indexFor方法的实现。\n    // 该算法主要返回一个索引，0 - table.length-1的数组下标。\n    int i = indexFor(hash, table.length);     //代码块②\n       \n    //接下来，找到 table[i]处，以及该处的数据链，看是否存在相同的key;判断key想到，首先判断hash值\n    //是否相等，然后再 判断key的equals方法是否相等\n    for (Entry<K,V> e = table[i]; e != null; e = e.next) {\n        Object k;\n        if (e.hash == hash && ((k = e.key) == key || key.equals(k))) {\n            V oldValue = e.value;\n            e.value = value;\n            e.recordAccess(this);\n            return oldValue;\n        }\n    }\n\n    modCount++;\n    addEntry(hash, key, value, i);        //代码块③\n    return null;\n}\n```\n#### 代码块①：\n```java\n/**\n* Inflates the table.\n*/\nprivate void inflateTable(int toSize) {\n    // 首先计算容量, toSize 容量为 threshold,在构造方法中，threshold默认等于初始容量，也就是16\n    int capacity = roundUpToPowerOf2(toSize);\n    // 然后重新算成 threshold的值，默认为 capacity * loadFactor\n    threshold = (int) Math.min(capacity * loadFactor, MAXIMUM_CAPACITY + 1);\n    //初始化数组 容量为 capacity\n    table = new Entry[capacity];\n    initHashSeedAsNeeded(capacity);\n}\n\nprivate static int roundUpToPowerOf2(int number) {\n    //Integer.highestOneBit 函数，其作用为保留高位的第一个1，其他全部为0,所以返回值永远是2的幂\n    return number >= MAXIMUM_CAPACITY ? MAXIMUM_CAPACITY : (number > 1) ? Integer.highestOneBit((number - 1) << 1) : 1;\n}\n```\n#### 代码块②：\n```java\n/**\n* Returns index for hash code h.\n*/\n// 该算法主要返回一个索引，0 - table.length-1的数组下标。\nstatic int indexFor(int h, int length) {\n   // assert Integer.bitCount(length) == 1 : \"length must be a non-zero power of 2\";\n   return h & (length-1);\n}\n```\n#### 代码块③：\n```java\n/**\n* Adds a new entry with the specified key, value and hash code to\n* the specified bucket.  It is the responsibility of this\n* method to resize the table if appropriate.\n*\n* Subclass overrides this to alter the behavior of put method.\n*/\nvoid addEntry(int hash, K key, V value, int bucketIndex) {\n   // 是否需要扩容的判断\n   if ((size >= threshold) && (null != table[bucketIndex])) {  \n      // JDK1.7以后的扩容条件；size大于等于threshold,并且新添加元素所在的索引值\n      // 不等为空，也就是当size达到或超过threshold,新增加元素，只要不会引起hash冲突\n      // 则不扩容;JDK1.7之前，只要超过threshold，就扩容。如果需要扩容，长度增长到原来\n      // 的两倍。接下来关注一下 resize方法的实现\n      resize(2 * table.length);\n      hash = (null != key) ? hash(key) : 0;\n      bucketIndex = indexFor(hash, table.length);\n    }\n    createEntry(hash, key, value, bucketIndex);    //代码块④\n}\n\n//resize 方法元素的复制，在transfer方法中实现，并重新计算 threshold值。\nvoid resize(int newCapacity) {  \n   Entry[] oldTable = table;\n   int oldCapacity = oldTable.length;\n   if (oldCapacity == MAXIMUM_CAPACITY) {\n       threshold = Integer.MAX_VALUE;\n       return;\n   }\n   Entry[] newTable = new Entry[newCapacity];\n   transfer(newTable, initHashSeedAsNeeded(newCapacity));\n   table = newTable;\n   threshold = (int)Math.min(newCapacity * loadFactor, MAXIMUM_CAPACITY + 1);\n}\n\n/**\n* Transfers all entries from current table to newTable.\n*  table数组及链表的复制。\n*/\nvoid transfer(Entry[] newTable, boolean rehash) {\n   int newCapacity = newTable.length;\n   // 遍历 table 数组\n   for (Entry<K,V> e : table) {  \n       while(null != e) { // 如果e 不等为空\n           // 先找到该节点的下一个节点\n           Entry<K,V> next = e.next;  \n               if (rehash) {\n                   e.hash = null == e.key ? 0 : hash(e.key);\n               }\n               // 重新计算该节点在新数组中的索引\n               int i = indexFor(e.hash, newCapacity);\n               // 然后将新位置处的元素，当成新加入元素的下一个节点，再该节点放入到i的位置。\n               e.next = newTable[i];                                      \n               newTable[i] = e;\n               //然后继续遍历 e 节点原先的后继节点。\n               e = next;                                                        \n           }\n       }\n   }\n```\n#### 代码块④：\n```java\n/**\n * Like addEntry except that this version is used when creating entries\n * as part of Map construction or \"pseudo-construction\" (cloning,\n * deserialization).  This version needn\'t worry about resizing the table.\n *\n * Subclass overrides this to alter the behavior of HashMap(Map),\n * clone, and readObject.\n */\nvoid createEntry(int hash, K key, V value, int bucketIndex) {\n    //首先获取 索引处的值，把这个值当成新节点的next。\n    Entry<K,V> e = table[bucketIndex];\n    table[bucketIndex] = new Entry<>(hash, key, value, e);\n    size++;\n}\n```\n###  Get方法：\n```java\npublic V get(Object key) {\n    if (key == null)\n        return getForNullKey();\n    Entry<K,V> entry = getEntry(key);\n\n    return null == entry ? null : entry.getValue();\n}\n\nfinal Entry<K,V> getEntry(Object key) {\n    if (size == 0) {\n        return null;\n    }\n\n    int hash = (key == null) ? 0 : hash(key);\n    for (Entry<K,V> e = table[indexFor(hash, table.length)]; e != null; e = e.next) {\n        Object k;\n        if (e.hash == hash && ((k = e.key) == key || (key != null && key.equals(k))))\n            return e;\n    }\n    return null;\n}\n```\n1. 首先也是根据 key 计算出 hashcode，然后定位到具体的桶中。\n2. 判断该位置是否为链表。\n3. 不是链表就根据 key、key 的 hashcode 是否相等来返回值。\n4. 为链表则需要遍历直到 key 及 hashcode 相等时候就返回值。\n5. 啥都没取到就直接返回 null 。\n\n### HashMap的遍历：\n```java\n//首先关注HashMap中一个属性\nprivate transient Set<Map.Entry<K,V>> entrySet = null;\npublic Set<Map.Entry<K,V>> entrySet() {\n    return entrySet0();\n}\nprivate Set<Map.Entry<K,V>> entrySet0() {\n    Set<Map.Entry<K,V>> es = entrySet;\n    return es != null ? es : (entrySet = new EntrySet());\n}\n```\n以上代码关键点是 new EntrySet();\nEntrySet是HashMap中的静态内部类，该类继承AbstractSet类，本身就是一个集合\n```java\nprivate final class EntrySet extends AbstractSet<Map.Entry<K,V>> {\n    public Iterator<Map.Entry<K,V>> iterator() {\n        return new EntryIterator();\n    }\n    public boolean contains(Object o) {\n        if (!(o instanceof Map.Entry))\n            return false;\n        Map.Entry<K,V> e = (Map.Entry<K,V>) o;\n        Entry<K,V> candidate = getEntry(e.getKey());\n        return candidate != null && candidate.equals(e);\n    }\n    public boolean remove(Object o) {\n        return removeMapping(o) != null;\n    }\n    public int size() {\n        return size;\n    }\n    public void clear() {\n        HashMap.this.clear();\n    }\n}\nprivate final class EntryIterator extends HashIterator<Map.Entry<K,V>> {\n    public Map.Entry<K,V> next() {\n        return nextEntry();\n    }\n}\n```\n```java\nprivate abstract class HashIterator<E> implements Iterator<E> {\n    // next entry to return    \n    // 下一个元素，因为我们知道，HashMap内部的  Map.Entry<K,V>[] table内的元素是非连续\n    // 的。所以访问下一元素，不能简单的用table[++index]这个概念。\n    Entry<K,V> next;\n    // For fast-fail 遍历时，HashMap结构变化的次数，如果在遍历期间modCount发生变化\n    // 则直接报错，并结束遍历      \n    int expectedModCount;  \n    // current slot   当前位置\n    int index;      \n    // current entry   当前元素                  \n    Entry<K,V> current;      \n    HashIterator() {\n        // 设置开始遍历时，记录HashMap结构调整的次数\n        expectedModCount = modCount;                                \n        if (size > 0) {\n            // advance to first entry\n            // 在构造方法时，先在table数组中找到第一不为空的元素，存入next属性中。\n            Entry[] t = table;\n            while (index < t.length && (next = t[index++]) == null);\n        }\n    }\n    public final boolean hasNext() {  \n        //判断是否有下一个可迭代元素，只需要判断 next是否为空即可。\n        return next != null;\n    }\n    // 遍历的核心算法\n    final Entry<K,V> nextEntry() {                                                  \n        //如果在遍历过程，有新增元素，删除元素动作，就直接抛异常。\n        if (modCount != expectedModCount)                              \n            throw new ConcurrentModificationException();\n        Entry<K,V> e = next;\n           \n        // 如果下一个元素为空，直接报元素异常\n        if (e == null)\n            throw new NoSuchElementException();\n\n        // nextEntry,主要实现思路是：将next的值，赋值给当前元素，\n        // 然后尝试获取下一个非空Map.Entry元素,找到后，赋值给next元素\n        if ((next = e.next) == null) {                                            \n            // 这句很关键，作用，先将 要本次返回的元素 next返回【开始遍历链表了】\n            // 如果该元素的next为空，\n            // 说明该元素下面没有链表，说明该hash没有冲突，然后再遍历table数组\n            // 找到下一个非空元素。\n            Entry[] t = table;\n            while (index < t.length && (next = t[index++]) == null);\n        }\n        current = e;\n        return e;\n    }\n\n    public void remove() {\n        // 将迭代器 中current所存储的元素，对应的key，删除，然后将current域设置为空，并重新设置\n        // expectedModCount的值等于modCount,,而current的赋值操作，发送在 next方法中，故 \n        //  故，如过在遍历过程中，想删除当前元素，it.remove()方法要在it.next()方法之后调用。\n        if (current == null)\n            throw new IllegalStateException();\n \n        if (modCount != expectedModCount)\n            throw new ConcurrentModificationException();\n           \n        Object k = current.key;\n        current = null;\n        HashMap.this.removeEntryForKey(k);\n        expectedModCount = modCount;\n    }\n}\n```\n验证在遍历HashMap时，remove方法与next方法的使用：\n```java\npublic static void main(String[] args) {\n    // TODO Auto-generated method stub\n    HashMap<String, String> a = new HashMap();\n    a.put(\"a\", \"a\");\n    a.put(\"b\", \"b\");\n    a.put(\"c\", \"c\");\n    a.put(\"d\", \"d\");\n    a.put(\"e\", \"e\");\n    a.put(\"f\", \"f\");\n    int i = 0;\n    for (Iterator<Map.Entry<String, String>> it = a.entrySet().iterator(); it.hasNext();) {\n        if(i == 2) {  // 如果 修改为 i == 0,,则会抛出异常 IllegalStateException 异常。\n            it.remove();\n        }\n        Map.Entry<String, String> entry = it.next();\n        System.out.println(entry.getKey() + \":\" + entry.getValue());\n        i ++;\n    }\n    System.out.println(a);\n}\n```\n\n## HashMap jdk1.8版本：\n优化jdk1.7版本HashMap中hash碰撞严重时链表变长，查询效率时间复杂度下降为O(N)\n将链表改为红黑树\n```java\n/**\n * The default initial capacity - MUST be a power of two.\n */\n// 1左移4位，变为16， 即HashMap默认大小为16\nstatic final int DEFAULT_INITIAL_CAPACITY = 1 << 4; // aka 16\n\n/**\n * The maximum capacity, used if a higher value is implicitly specified\n * by either of the constructors with arguments.\n * MUST be a power of two <= 1<<30.\n */\n// int类型占4个字节，即32位，最左边的一位表示符号，所以hashmap最大即为左移30位\nstatic final int MAXIMUM_CAPACITY = 1 << 30;\n\n\n/**\n * The load factor used when none specified in constructor.\n */\n// 默认负载因子 0.75\nstatic final float DEFAULT_LOAD_FACTOR = 0.75f;\n\n\n/**\n * The bin count threshold for using a tree rather than list for a\n * bin.  Bins are converted to trees when adding an element to a\n * bin with at least this many nodes. The value must be greater\n * than 2 and should be at least 8 to mesh with assumptions in\n * tree removal about conversion back to plain bins upon\n * shrinkage.\n */\n// 链表长度大于8时，链表会进化为红黑树\nstatic final int TREEIFY_THRESHOLD = 8;\n\n\n/**\n * The bin count threshold for untreeifying a (split) bin during a\n * resize operation. Should be less than TREEIFY_THRESHOLD, and at\n * most 6 to mesh with shrinkage detection under removal.\n */\n//在哈希表扩容时，如果发现链表长度小于 6，则会由树重新退化为链表。\nstatic final int UNTREEIFY_THRESHOLD = 6;\n\n\n/**\n * The smallest table capacity for which bins may be treeified.\n * (Otherwise the table is resized if too many nodes in a bin.)\n * Should be at least 4 * TREEIFY_THRESHOLD to avoid conflicts\n * between resizing and treeification thresholds.\n */\n// 链表进化红黑树的另一个判断方法，即hashmap容量必须大于64\nstatic final int MIN_TREEIFY_CAPACITY = 64;\n\n\n/**\n * The table, initialized on first use, and resized as\n * necessary. When allocated, length is always a power of two.\n * (We also tolerate length zero in some operations to allow\n * bootstrapping mechanics that are currently not needed.)\n */\n// HashMap 真正存放数据的对象\ntransient Node<K,V>[] table;\n\n\n/**\n * Holds cached entrySet(). Note that AbstractMap fields are used\n * for keySet() and values().\n */\n// 用于返回hashmap的数据\ntransient Set<Map.Entry<K,V>> entrySet;\n\n\n/**\n * The number of key-value mappings contained in this map.\n */\n// 记录hashmap中存放数据的条数\ntransient int size;\n\n\n/**\n * The number of times this HashMap has been structurally modified\n * Structural modifications are those that change the number of mappings in\n * the HashMap or otherwise modify its internal structure (e.g.,\n * rehash).  This field is used to make iterators on Collection-views of\n * the HashMap fail-fast.  (See ConcurrentModificationException).\n */\n// modCount是记录修改次数，出现在集合类（线程不安全）中的增、删函数中\ntransient int modCount;\n\n\n/**\n * The next size value at which to resize (capacity * load factor).\n *\n * @serial\n */\n// (The javadoc description is true upon serialization.\n// Additionally, if the table array has not been allocated, this\n// field holds the initial array capacity, or zero signifying\n// DEFAULT_INITIAL_CAPACITY.)\n// 当HashMap的size大于threshold时会执行resize操作\nint threshold;\n\n\n/**\n * The load factor for the hash table.\n *\n * @serial\n */\n// 负载因子\nfinal float loadFactor;\n```\ntransient 表示易变的意思，在 Java 中，被该关键字修饰的变量不会被默认的序列化机制序列化。\n桶数组 table 是 HashMap 底层重要的数据结构，不序列化的话，别人还怎么还原呢？\nHashMap 并没有使用默认的序列化机制，而是通过实现 readObject/writeObject 两个方法自定义了序列化的内容。HashMap 中存储的内容是键值对，只要把键值对序列化了，就可以根据键值对数据重建 HashMap。\n序列化 table 不是可以一步到位，后面直接还原不就行了吗？但序列化 table 存在着两个问题：\n1. table 多数情况下是无法被存满的，序列化未使用的部分，浪费空间\n2. 同一个键值对在不同 JVM 下，所处的桶位置可能是不同的，在不同的 JVM 下反序列化 table 可能会发生错误。\n\n以上两个问题中，第一个问题比较好理解，第二个问题解释一下。HashMap 的 get/put/remove 等方法第一步就是根据 hash 找到键所在的桶位置，但如果键没有覆写 hashCode 方法，计算 hash 时最终调用 Object 中的 hashCode 方法。但 Object 中的 hashCode 方法是 native 型的，不同的 JVM 下，可能会有不同的实现，产生的 hash 可能也是不一样的。也就是说同一个键在不同平台下可能会产生不同的 hash，此时再对在同一个 table 继续操作，就会出现问题。\n\n### 更新内容：\n- 新加入的 TREEIFY_THRESHOLD 用于判断链表合适转变为红黑树。\n- HashEntry修改为Node。\n\n### Node 节点对象：\n```java\n/**\n * Basic hash bin node, used for most entries.  (See below for\n * TreeNode subclass, and in LinkedHashMap for its Entry subclass.)\n */\nstatic class Node<K,V> implements Map.Entry<K,V> {\n   final int hash;\n   final K key;\n   V value;\n   Node<K,V> next;\n\n\n   Node(int hash, K key, V value, Node<K,V> next) {\n       this.hash = hash;\n       this.key = key;\n       this.value = value;\n       this.next = next;\n   }\n\n   public final K getKey()        { return key; }\n   public final V getValue()      { return value; }\n   public final String toString() { return key + \"=\" + value; }\n   \n    //返回key的hash与value的hash异或的结果\n   public final int hashCode() {\n       return Objects.hashCode(key) ^ Objects.hashCode(value);\n   }\n\n   public final V setValue(V newValue) {\n       V oldValue = value;\n       value = newValue;\n       return oldValue;\n   }\n\n    //判断相等，1 同一个对象 2 Map.Entry的一个实例，并且key和value相等\n   public final boolean equals(Object o) {\n       if (o == this)\n           return true;\n       if (o instanceof Map.Entry) {\n           Map.Entry<?,?> e = (Map.Entry<?,?>)o;\n           if (Objects.equals(key, e.getKey()) &&\n               Objects.equals(value, e.getValue()))\n               return true;\n       }\n       return false;\n   }\n}\n```\n\n### hash的计算：\n```java\n/**\n * Computes key.hashCode() and spreads (XORs) higher bits of hash\n * to lower.  Because the table uses power-of-two masking, sets of\n * hashes that vary only in bits above the current mask will\n * always collide. (Among known examples are sets of Float keys\n * holding consecutive whole numbers in small tables.)  So we\n * apply a transform that spreads the impact of higher bits\n * downward. There is a tradeoff between speed, utility, and\n * quality of bit-spreading. Because many common sets of hashes\n * are already reasonably distributed (so don\'t benefit from\n * spreading), and because we use trees to handle large sets of\n * collisions in bins, we just XOR some shifted bits in the\n * cheapest possible way to reduce systematic lossage, as well as\n * to incorporate impact of the highest bits that would otherwise\n * never be used in index calculations because of table bounds.\n */\nstatic final int hash(Object key) {\n    int h;\n    return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);\n}\n```\n^ : 按位异或\n>>> : 无符号右移\n计算hash使用hashCode()返回的int型数字与其无符号右移16位做异或运算,得到的值为hash\nint 占4个字节,32位,这样运算是为了使key算出的hash高位也可以影响该Node存在Map的位置\n\n### Put方法：\n```java\npublic V put(K key, V value) {\n   return putVal(hash(key), key, value, false, true);\n}\n\nfinal V putVal(int hash, K key, V value, boolean onlyIfAbsent, boolean evict) {\n   Node<K,V>[] tab; Node<K,V> p; int n, i;\n   if ((tab = table) == null || (n = tab.length) == 0)    //table 为空初始化数组\n       n = (tab = resize()).length;\n   if ((p = tab[i = (n - 1) & hash]) == null)             //根据hash算出的数组为空，进行new\n       tab[i] = newNode(hash, key, value, null);\n   else {\n       Node<K,V> e; K k;\n       if (p.hash == hash &&\n           ((k = p.key) == key || (key != null && key.equals(k)))) //判断新插入的key\n           e = p;\n       else if (p instanceof TreeNode)\n           e = ((TreeNode<K,V>)p).putTreeVal(this, tab, hash, key, value);\n       else {\n           for (int binCount = 0; ; ++binCount) {\n               if ((e = p.next) == null) {\n                   p.next = newNode(hash, key, value, null);\n                   // 已经加上了节点，判断是否要将链表升级位红黑树\n                   if (binCount >= TREEIFY_THRESHOLD - 1) // -1 for 1st\n                       treeifyBin(tab, hash);\n                   break;\n               }\n               if (e.hash == hash &&\n                   ((k = e.key) == key || (key != null && key.equals(k))))\n                   break;\n               p = e;\n           }\n       }\n       if (e != null) { // existing mapping for key\n           V oldValue = e.value;\n           if (!onlyIfAbsent || oldValue == null)\n               e.value = value;\n           afterNodeAccess(e);\n           return oldValue;\n       }\n   }\n   ++modCount;\n   if (++size > threshold)\n       resize();\n   afterNodeInsertion(evict);\n   return null;\n}\n\n// Create a regular (non-tree) node\nNode<K,V> newNode(int hash, K key, V value, Node<K,V> next) {\n    return new Node<>(hash, key, value, next);\n}\n```\n![HashMap3.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-04-22_08-55-53_dce618_HashMap3.jpg)\n\n1. 判断当前桶是否为空，空的就需要初始化（resize 中会判断是否进行初始化）。\n2. 根据当前 key 的 hashcode 定位到具体的桶中并判断是否为空，为空表明没有 Hash 冲突就直接在当前位置创建一个新桶即可。\n3. 如果当前桶有值（ Hash 冲突），那么就要比较当前桶中的 key、key 的 hashcode 与写入的 key 是否相等，相等就赋值给 e,在第 8 步的时候会统一进行赋值及返回。\n4. 如果当前桶为红黑树，那就要按照红黑树的方式写入数据。\n5. 如果是个链表，就需要将当前的 key、value 封装成一个新节点写入到当前桶的后面（形成链表）。\n6. 接着判断当前链表的大小是否大于预设的阈值，大于时就要转换为红黑树。\n7. 如果在遍历过程中找到 key 相同时直接退出遍历。\n8. 如果 e != null 就相当于存在相同的 key,那就需要将值覆盖。\n9. 最后判断是否需要进行扩容。\n\n### Get方法：\n```java\npublic V get(Object key) {\n    Node<K,V> e;\n    return (e = getNode(hash(key), key)) == null ? null : e.value;\n}\n\nfinal Node<K,V> getNode(int hash, Object key) {\n    Node<K,V>[] tab; Node<K,V> first, e; int n; K k;\n    if ((tab = table) != null && (n = tab.length) > 0 && (first = tab[(n - 1) & hash]) != null) {\n        if (first.hash == hash && // always check first node\n            ((k = first.key) == key || (key != null && key.equals(k))))\n            return first;\n        if ((e = first.next) != null) {\n            if (first instanceof TreeNode)\n                return ((TreeNode<K,V>)first).getTreeNode(hash, key);\n            do {\n                if (e.hash == hash && ((k = e.key) == key || (key != null && key.equals(k))))\n                    return e;\n            } while ((e = e.next) != null);\n        }\n    }\n    return null;\n}\n```\n1. 首先将 key hash 之后取得所定位的桶。\n2. 如果桶为空则直接返回 null 。\n3. 否则判断桶的第一个位置(有可能是链表、红黑树)的 key 是否为查询的 key，是就直接返回 value。\n4. 如果第一个不匹配，则判断它的下一个是红黑树还是链表。\n5. 红黑树就按照树的查找方式返回值。\n6. 不然就按照链表的方式遍历匹配返回值。\nput与get方法的修改使查询效率时间复杂度提高到了O(logN)\n\n### HashMap遍历方法：\n```java\n    Iterator<Map.Entry<String, Integer>> entryIterator = map.entrySet().iterator();\n    while (entryIterator.hasNext()) {\n        Map.Entry<String, Integer> next = entryIterator.next();\n        System.out.println(\"key=\" + next.getKey() + \" value=\" + next.getValue());\n    }\n\n    Iterator<String> iterator = map.keySet().iterator();\n    while (iterator.hasNext()){\n        String key = iterator.next();\n        System.out.println(\"key=\" + key + \" value=\" + map.get(key));\n    }\n```\n建议使用第一种方法遍历，因为第一种直接取出key和value\n第二种先取出key由key又查找value\n\n### HashMap扩容：\n```java\nfinal Node<K,V>[] resize() {\n   Node<K,V>[] oldTab = table;\n   int oldCap = (oldTab == null) ? 0 : oldTab.length;\n   int oldThr = threshold;\n   int newCap, newThr = 0;\n   if (oldCap > 0) {    //原来的容量大于0，即此处是对table数组的扩容\n       if (oldCap >= MAXIMUM_CAPACITY) {    //数组已经最大无法扩容，改变阈值大小\n           threshold = Integer.MAX_VALUE;\n           return oldTab;\n       }            \n       else if ((newCap = oldCap << 1) < MAXIMUM_CAPACITY &&\n                oldCap >= DEFAULT_INITIAL_CAPACITY)    //正常扩容，容量阈值都扩大2倍\n           newThr = oldThr << 1; // double threshold\n   }\n    //table为空时，使用用户自定义阈值初始化table数组大小\n   else if (oldThr > 0) // initial capacity was placed in threshold\n        //talbe没有初始化时，threshold使用用户指定容量\n       newCap = oldThr;   \n   else {               // zero initial threshold signifies using defaults\n       //默认地大小 容量 负载因子，即HashMap默认的构造函数\n       newCap = DEFAULT_INITIAL_CAPACITY;\n       newThr = (int)(DEFAULT_LOAD_FACTOR * DEFAULT_INITIAL_CAPACITY);\n   }\n    //阈值为0设置新的阈值\n   if (newThr == 0) {\n       float ft = (float)newCap * loadFactor;\n       //设置新的阈值，如果容量已达最大，阈值也改为最大\n       newThr = (newCap < MAXIMUM_CAPACITY && ft < (float)MAXIMUM_CAPACITY ?\n                 (int)ft : Integer.MAX_VALUE);\n   }\n   threshold = newThr;\n   @SuppressWarnings({\"rawtypes\",\"unchecked\"})\n    //初始化新的table\n   Node<K,V>[] newTab = (Node<K,V>[])new Node[newCap];\n   table = newTab;\n    //将旧table中的数据移入新的table\n   if (oldTab != null) {\n       for (int j = 0; j < oldCap; ++j) {\n           Node<K,V> e;\n           if ((e = oldTab[j]) != null) {\n               oldTab[j] = null;\n               //单个节点直接rehash定位\n               if (e.next == null)\n                   newTab[e.hash & (newCap - 1)] = e;\n                //TreeNode节点采用红黑树的rehash\n               else if (e instanceof TreeNode)\n                   ((TreeNode<K,V>)e).split(this, newTab, j, oldCap);\n               //链表的rehash\n               else { // preserve order\n                   Node<K,V> loHead = null, loTail = null;\n                   Node<K,V> hiHead = null, hiTail = null;\n                   Node<K,V> next;\n                   do {\n                       next = e.next;\n                       //hash和原来大小与运算为0，说明hash&(newCap-1)与hash&(oldCap-1)相等，\n                        //索引不变的列表\n                       if ((e.hash & oldCap) == 0) {\n                           if (loTail == null)\n                               loHead = e;\n                           else\n                               loTail.next = e;\n                           loTail = e;\n                       }\n                       //索引改变的列表\n                       else {\n                           if (hiTail == null)\n                               hiHead = e;\n                           else\n                               hiTail.next = e;\n                           hiTail = e;\n                       }\n                   } while ((e = next) != null);\n                   //索引不变的列表尾部指针置空\n                   if (loTail != null) {\n                       loTail.next = null;\n                       newTab[j] = loHead;\n                   }\n                   //索引改变的列表尾部置空\n                   if (hiTail != null) {\n                       hiTail.next = null;\n                       //新的位置一定为 当前索引位置 + 当前table长度，  与二进制有关\n                       newTab[j + oldCap] = hiHead;\n                   }\n               }\n           }\n       }\n   }\n   return newTab;\n}\n```\n\n\n\n\n\n', NULL, NULL, '2024-04-21 15:29:44', '2024-04-22 10:40:07', 1);
INSERT INTO `doc_content` VALUES (66, 1, 127, '# TreeMap 原理简介\n\nTreeMap 键是红黑树结构，可以保证键的排序和唯一性\nTreeMap 的 Key 的排序：  \n- 自然排序：TreeMap 的所有的 Key 必须实现 Comparable 接口，而且所有的 Key 应该是同一个类的对象，否则将会抛出 ClasssCastException\n- 定制排序：创建 TreeMap 时，传入一个 Comparator 对象，该对象负责对TreeMap 中的所有 key 进行排序。此时不需要 Map 的 Key 实现Comparable 接口\n\nTreeMap判断两个key相等的标准：两个key通过compareTo()方法或者compare()方法返回0。\n\n## 构造方法：\n|方法名|说明|\n|--|--|\n|TreeMap()|使用键的自然顺序构造一个新的、空的树映射|\n|TreeMap(Comparator<? super K> comparator)|构造一个新的、空的树映射，该映射根据给定比较器进行排序|\n|TreeMap(Map<? extends K,? extends V> m)|构造一个与给定映射具有相同映射关系的新的树映射，该映射根据其键的自然顺序 进行排序|\n|TreeMap(SortedMap<K,? extends V> m)|构造一个与指定有序映射具有相同映射关系和相同排序顺序的新的树映射|\n\n## 方法摘要：\n|返回值|方法名|说明|\n|--|--|--|\n|Map.Entry<K,V>|ceilingEntry(K key)|返回一个键-值映射关系，它与大于等于给定键的最小键关联；如果不存在这样的键，则返回 null|\n|K|ceilingKey(K key)|返回大于等于给定键的最小键；如果不存在这样的键，则返回 null|\n|void|clear()|从此映射中移除所有映射关系|\n|Object|clone()|返回此 TreeMap 实例的浅表副本|\n|Comparator<? super K>|comparator()|返回对此映射中的键进行排序的比较器；如果此映射使用键的自然顺序，则返回 null|\n|boolean|containsKey(Object key)|如果此映射包含指定键的映射关系，则返回 true|\n|boolean|containsValue(Object value)|如果此映射为指定值映射一个或多个键，则返回 true|\n|NavigableSet<K>|descendingKeySet()|返回此映射中所包含键的逆序 NavigableSet 视图|\n|NavigableMap<K,V>|descendingMap()|返回此映射中所包含映射关系的逆序视图|\n|Set<Map.Entry<K,V>>|entrySet()|返回此映射中包含的映射关系的 Set 视图|\n|Map.Entry<K,V>|firstEntry()|返回一个与此映射中的最小键关联的键-值映射关系；如果映射为空，则返回 null|\n|K|firstKey()|返回此映射中当前第一个（最低）键|\n|Map.Entry<K,V>|floorEntry(K key)|返回一个键-值映射关系，它与小于等于给定键的最大键关联；如果不存在这样的键，则返回 null|\n|K|floorKey(K key)|返回小于等于给定键的最大键；如果不存在这样的键，则返回 null|\n|V|get(Object key)|返回指定键所映射的值，如果对于该键而言，此映射不包含任何映射关系，则返回 null|\n|SortedMap<K,V>|headMap(K toKey)|返回此映射的部分视图，其键值严格小于 toKey|\n|NavigableMap<K,V>|headMap(K toKey, boolean inclusive)|返回此映射的部分视图，其键小于（或等于，如果 inclusive 为 true）toKey|\n|Map.Entry<K,V>|higherEntry(K key)|返回一个键-值映射关系，它与严格大于给定键的最小键关联；如果不存在这样的键，则返回 null|\n|K|higherKey(K key)|返回严格大于给定键的最小键；如果不存在这样的键，则返回 null|\n|Set<K>|keySet()|返回此映射包含的键的 Set 视图|\n|Map.Entry<K,V>|lastEntry()|返回与此映射中的最大键关联的键-值映射关系；如果映射为空，则返回 null|\n|K|lastKey()|返回映射中当前最后一个（最高）键|\n|Map.Entry<K,V>|lowerEntry(K key)|返回一个键-值映射关系，它与严格小于给定键的最大键关联；如果不存在这样的键，则返回 null|\n|K|lowerKey(K key)|返回严格小于给定键的最大键；如果不存在这样的键，则返回 null|\n|NavigableSet<K>|navigableKeySet()|返回此映射中所包含键的 NavigableSet 视图|\n|Map.Entry<K,V>|pollFirstEntry()|移除并返回与此映射中的最小键关联的键-值映射关系；如果映射为空，则返回 null|\n|Map.Entry<K,V>|pollLastEntry()|移除并返回与此映射中的最大键关联的键-值映射关系；如果映射为空，则返回 null|\n|V|put(K key, V value)|将指定值与此映射中的指定键进行关联|\n|void|putAll(Map<? extends K,? extends V> map)|将指定映射中的所有映射关系复制到此映射中|\n|V|remove(Object key)|如果此 TreeMap 中存在该键的映射关系，则将其删除|\n|int|size()|返回此映射中的键-值映射关系数|\n|NavigableMap<K,V>|subMap(K fromKey, boolean fromInclusive, K toKey, boolean toInclusive)|返回此映射的部分视图，其键的范围从 fromKey 到 toKey|\n|SortedMap<K,V>|subMap(K fromKey, K toKey)|返回此映射的部分视图，其键值的范围从 fromKey（包括）到 toKey（不包括）|\n|SortedMap<K,V>|tailMap(K fromKey)|返回此映射的部分视图，其键大于等于 fromKey|\n|NavigableMap<K,V>|tailMap(K fromKey, boolean inclusive)|返回此映射的部分视图，其键大于（或等于，如果 inclusive 为 true）fromKey|\n|Collection<V>|values()|返回此映射包含的值的 Collection 视图|\n\n\n# TreeMap源码分析:\n\n```java\n//TreeMap可以自动排序的，默认情况下comparator为null，这个时候按照key的自然顺序进行排序\n//然而并不是所有情况下都可以直接使用key的自然顺序，\n//想让Map的自动排序按照自己的规则，这个时候你就需要传递Comparator的实现类\nprivate final Comparator<? super K> comparator;\n//TreeMap的存储结构既然是红黑树，那么必然会有唯一的根节点\nprivate transient Entry<K,V> root;\n//Map中key-val对的数量，也即是红黑树中节点Entry的数量\nprivate transient int size = 0;\n//红黑树结构的调整次数\nprivate transient int modCount = 0;\n\nprivate transient EntrySet entrySet;\nprivate transient KeySet<K> navigableKeySet;\nprivate transient NavigableMap<K,V> descendingMap;\n```\n\n## Entry类源码：\n```java\nstatic final class Entry<K,V> implements Map.Entry<K,V> {\n    //key，val存储数据\n    K key;\n    V value;\n    \n    //节点的左孩子\n    Entry<K,V> left;\n\n    //节点的右孩子\n    Entry<K,V> right;\n\n    //节点的父节点\n    Entry<K,V> parent;\n\n    //默认颜色为黑色\n    boolean color = BLACK;\n\n    //构造器\n    Entry(K key, V value, Entry<K,V> parent) {\n        this.key = key;\n        this.value = value;\n        this.parent = parent;\n    }\n\n    //获取节点的key\n    public K getKey() {\n        return key;\n    }\n\n    //获取节点的val\n    public V getValue() {\n        return value;\n    }\n\n    //设置新的val值\n    public V setValue(V value) {\n        V oldValue = this.value;\n        this.value = value;\n        return oldValue;\n    }\n\n    //\n    public boolean equals(Object o) {\n        if (!(o instanceof Map.Entry))\n            return false;\n        Map.Entry<?,?> e = (Map.Entry<?,?>)o;\n        return valEquals(key,e.getKey()) && valEquals(value,e.getValue());\n    }\n\n\n    public int hashCode() {\n        int keyHash = (key==null ? 0 : key.hashCode());\n        int valueHash = (value==null ? 0 : value.hashCode());\n        return keyHash ^ valueHash;\n    }\n\n\n    public String toString() {\n        return key + \"=\" + value;\n    }\n}\n```\n\n## TreeMap构造方法：\n```java\n//默认构造函数，key按照自然顺序排列\npublic TreeMap() {\n    comparator = null;\n}\n\n//传递Comparator具体实现，按照该实现规则进行排序\npublic TreeMap(Comparator<? super K> comparator) {\n    this.comparator = comparator;\n}\n\n//传递一个map实体构建TreeMap，按照默认规则排序\npublic TreeMap(Map<? extends K, ? extends V> m) {\n    comparator = null;\n    putAll(m);\n}\n\n//传递一个map实体构建TreeMap，按照传递的map的规则进行排序\npublic TreeMap(SortedMap<K, ? extends V> m) {\n    comparator = m.comparator();\n    try {\n        buildFromSorted(m.size(), m.entrySet().iterator(), null, null);\n    } catch (java.io.IOException cannotHappen) {\n    } catch (ClassNotFoundException cannotHappen) {\n    }\n}\n```\n\n## Put方法：\n```java\npublic V put(K key, V value) {\n    Entry<K,V> t = root;\n    //如果根节点都为null，还没建立起来红黑树，我们先new Entry并赋值给root把红黑树建立起来，\n    //这个时候红黑树中已经有一个节点了，同时修改操作+1\n    if (t == null) {\n        compare(key, key); \n        root = new Entry<>(key, value, null);\n        size = 1;\n        modCount++;\n        return null;\n    }\n    //如果节点不为null,定义一个cmp，这个变量用来进行二分查找时的比较\n    //定义parent，是new Entry时必须要的参数\n    int cmp;\n    Entry<K,V> parent;\n    //cpr表示有无自己定义的排序规则，分两种情况遍历执行\n    Comparator<? super K> cpr = comparator;\n    if (cpr != null) {\n        //从root节点开始遍历，通过二分查找逐步向下找 \n        //第一次循环：从根节点开始，这个时候parent就是根节点，然后通过自定义的排序算法 \n        //cpr.compare(key, t.key)比较传入的key和根节点的key值，如果传入的key<root.key，那么 \n        //继续在root的左子树中找，从root的左孩子节点（root.left）开始：如果传入的key>root.key, \n        //那么继续在root的右子树中找，从root的右孩子节点（root.right）开始;如果恰好key==root.key， \n        //那么直接根据root节点的value值即可。 \n        //后面的循环规则一样，当遍历到的当前节点作为起始节点，逐步往下找 \n        //需要注意的是：这里并没有对key是否为null进行判断，建议自己的实现Comparator时应该要考虑在内\n        do {\n            parent = t;\n            cmp = cpr.compare(key, t.key);\n            if (cmp < 0)\n                t = t.left;\n            else if (cmp > 0)\n                t = t.right;\n            else\n                return t.setValue(value);\n        } while (t != null);\n    }\n    else {\n        //默认排序key不能为null\n        if (key == null)\n            throw new NullPointerException();\n        @SuppressWarnings(\"unchecked\")\n            Comparable<? super K> k = (Comparable<? super K>) key;\n        do {\n            parent = t;\n            cmp = k.compareTo(t.key);\n            if (cmp < 0)\n                t = t.left;\n            else if (cmp > 0)\n                t = t.right;\n            else\n                return t.setValue(value);\n        } while (t != null);\n    }\n    //能执行到这里，说明前面并没有找到相同的key,节点已经遍历到最后了，我们只需要new一个Entry放到 \n    //parent下面即可，但放到左子节点上还是右子节点上，就需要按照红黑树的规则来\n    Entry<K,V> e = new Entry<>(key, value, parent);\n    if (cmp < 0)\n        parent.left = e;\n    else\n        parent.right = e;\n    //节点加进去了，并不算完，我们在前面红黑树原理章节提到过，一般情况下加入节点都会对红黑树的结构造成 \n    //破坏，我们需要通过一些操作来进行自动平衡处置，如【变色】【左旋】【右旋】\n    fixAfterInsertion(e);\n    size++;\n    modCount++;\n    return null;\n}\n```\n\n### 节点插入自平衡：\n```java\nprivate void fixAfterInsertion(Entry<K,V> x) {\n    //新插入的节点为红色节点\n    x.color = RED;\n    //我们知道父节点为黑色时，并不需要进行树结构调整，只有当父节点为红色时，才需要调整\n    while (x != null && x != root && x.parent.color == RED) {\n    //如果父节点是左节点，对应上表中情况1和情况2\n        if (parentOf(x) == leftOf(parentOf(parentOf(x)))) {\n            Entry<K,V> y = rightOf(parentOf(parentOf(x)));\n            //如果叔父节点为红色，对应于“父节点和叔父节点都为红色”，此时通过变色即可实现平衡\n            //此时父节点和叔父节点都设置为黑色，祖父节点设置为红色\n            if (colorOf(y) == RED) {\n                setColor(parentOf(x), BLACK);\n                setColor(y, BLACK);\n                setColor(parentOf(parentOf(x)), RED);\n                x = parentOf(parentOf(x));\n            } else {\n                //如果插入节点是黑色，插入的是右子节点，通过【左右节点旋转】（这里先进行父节点左旋）\n                if (x == rightOf(parentOf(x))) {\n                    x = parentOf(x);\n                    rotateLeft(x);\n                }\n                //设置父节点和祖父节点颜色\n                setColor(parentOf(x), BLACK);\n                setColor(parentOf(parentOf(x)), RED);\n                //进行祖父节点右旋（这里【变色】和【旋转】并没有严格的先后顺序，达成目的就行）\n                rotateRight(parentOf(parentOf(x)));\n            }\n        } else {\n            //父节点是右节点的情况\n            Entry<K,V> y = leftOf(parentOf(parentOf(x)));\n            //对应于“父节点和叔父节点都为红色”，此时通过变色即可实现平衡\n            if (colorOf(y) == RED) {\n                setColor(parentOf(x), BLACK);\n                setColor(y, BLACK);\n                setColor(parentOf(parentOf(x)), RED);\n                x = parentOf(parentOf(x));\n            } else {\n                //如果插入节点是黑色，插入的是左子节点，通过【右左节点旋转】（这里先进行父节点右旋）\n                if (x == leftOf(parentOf(x))) {\n                    x = parentOf(x);\n                    rotateRight(x);\n                }\n                setColor(parentOf(x), BLACK);\n                setColor(parentOf(parentOf(x)), RED);\n                //进行祖父节点左旋（这里【变色】和【旋转】并没有严格的先后顺序，达成目的就行）\n                rotateLeft(parentOf(parentOf(x)));\n            }\n        }\n    }\n    //根节点必须为黑色\n    root.color = BLACK;\n}\n```\n\n### 左旋：\n```java\nprivate void rotateLeft(Entry<K,V> p) {\n    if (p != null) {\n        //断开当前节点p与其右子节点的关联，重新将节点p的右子节点的地址指向节点p的右子节点的左子节点\n        //这个时候节点r没有父节点\n        Entry<K,V> r = p.right;\n        p.right = r.left;\n        //将节点p作为节点r的父节点\n        if (r.left != null)\n            r.left.parent = p;\n        //将节点p的父节点和r的父节点指向同一处\n        r.parent = p.parent;\n        //p的父节点为null，则将节点r设置为root\n        if (p.parent == null)\n            root = r;\n        //如果节点p是左子节点，则将该左子节点替换为节点r\n        else if (p.parent.left == p)\n            p.parent.left = r;\n        //如果节点p为右子节点，则将该右子节点替换为节点r\n        else\n            p.parent.right = r;\n        //重新建立p与r的关系\n        r.left = p;\n        p.parent = r;\n    }\n}\n```\n\n## get方法：\n```java\npublic V get(Object key) {\n    Entry<K,V> p = getEntry(key);\n    return (p==null ? null : p.value);\n}\n\n//从root节点开始遍历，通过二分查找逐步向下找\n//第一次循环：从根节点开始，这个时候parent就是根节点，然后通过k.compareTo(p.key)比较传入的key和\n//根节点的key值；\n//如果传入的key<root.key, 那么继续在root的左子树中找，从root的左孩子节点（root.left）开始；\n//如果传入的key>root.key, 那么继续在root的右子树中找，从root的右孩子节点（root.right）开始;\n//如果恰好key==root.key，那么直接根据root节点的value值即可。\n//后面的循环规则一样，当遍历到的当前节点作为起始节点，逐步往下找\n//默认排序情况下的查找\nfinal Entry<K,V> getEntry(Object key) {\n    \n    if (comparator != null)\n        return getEntryUsingComparator(key);\n    if (key == null)\n        throw new NullPointerException();\n    @SuppressWarnings(\"unchecked\")\n    Comparable<? super K> k = (Comparable<? super K>) key;\n    Entry<K,V> p = root;\n    while (p != null) {\n        int cmp = k.compareTo(p.key);\n        if (cmp < 0)\n            p = p.left;\n        else if (cmp > 0)\n            p = p.right;\n        else\n            return p;\n    }\n    return null;\n}\n\n//从root节点开始遍历，通过二分查找逐步向下找\n//第一次循环：从根节点开始，这个时候parent就是根节点，然后通过自定义的排序算法\n//cpr.compare(key, t.key)比较传入的key和根节点的key值，如果传入的key<root.key，那么\n//继续在root的左子树中找，从root的左孩子节点（root.left）开始：如果传入的key>root.key,\n//那么继续在root的右子树中找，从root的右孩子节点（root.right）开始;如果恰好key==root.key，\n//那么直接根据root节点的value值即可。\n//后面的循环规则一样，当遍历到的当前节点作为起始节点，逐步往下找\n\n//自定义排序规则下的查找\nfinal Entry<K,V> getEntryUsingComparator(Object key) {\n    @SuppressWarnings(\"unchecked\")\n    K k = (K) key;\n    Comparator<? super K> cpr = comparator;\n    if (cpr != null) {\n        Entry<K,V> p = root;\n        while (p != null) {\n            int cmp = cpr.compare(k, p.key);\n            if (cmp < 0)\n                p = p.left;\n            else if (cmp > 0)\n                p = p.right;\n            else\n                return p;\n        }\n    }\n    return null;\n}\n```\n\n## remove方法:\n```java\npublic V remove(Object key) {\n    Entry<K,V> p = getEntry(key);\n    if (p == null)\n        return null;\n    V oldValue = p.value;\n    deleteEntry(p);\n    return oldValue;\n}\n\n\nprivate void deleteEntry(Entry<K,V> p) {\n    modCount++;\n    size--;\n    //当左右子节点都不为null时，通过successor(p)遍历红黑树找到前驱或者后继\n    if (p.left != null && p.right != null) {\n        Entry<K,V> s = successor(p);\n        //将前驱或者后继的key和value复制到当前节点p中，然后删除节点s(通过将节点p引用指向s)\n        p.key = s.key;\n        p.value = s.value;\n        p = s;\n    }\n    Entry<K,V> replacement = (p.left != null ? p.left : p.right);\n    //至少有一个子节点不为null，直接用这个有值的节点替换掉当前节点，给replacement的parent属性赋值,给\n    //parent节点的left属性和right属性赋值，同时要记住叶子节点必须为null,然后用fixAfterDeletion方法\n    //进行自平衡处理\n    if (replacement != null) {\n        //将待删除节点的子节点挂到待删除节点的父节点上\n        replacement.parent = p.parent;\n        if (p.parent == null)\n            root = replacement;\n        else if (p == p.parent.left)\n            p.parent.left  = replacement;\n        else\n            p.parent.right = replacement;\n        p.left = p.right = p.parent = null;\n//p如果是红色节点的话，那么其子节点replacement必然为红色的，并不影响红黑树的结构\n//但如果p为黑色节点的话，那么其父节点以及子节点都可能是红色的，那么很明显可能会存在红色相连的情\n//况，因此需要进行自平衡的调整\n        if (p.color == BLACK)\n            fixAfterDeletion(replacement);\n    } else if (p.parent == null) {\n        root = null;\n    } else {\n\n//如果p节点为黑色，那么p节点删除后，就可能违背每个节点到其叶子节点路径上黑色节点数量一致的规则，\n//因此需要进行自平衡的调整\n\n        if (p.color == BLACK)\n            fixAfterDeletion(p);\n        if (p.parent != null) {\n            if (p == p.parent.left)\n                p.parent.left = null;\n            else if (p == p.parent.right)\n                p.parent.right = null;\n            p.parent = null;\n        }\n    }\n}\n```\n\n### 删除节点后红黑树自平衡：\n```java\nprivate void fixAfterDeletion(Entry<K,V> x) {\n//当x不是root节点且颜色为黑色时\n    while (x != root && colorOf(x) == BLACK) {\n//首先分为两种情况，当前节点x是左节点或者当前节点x是右节点，这两种情况下面都是四种场景,这里通过\n//代码分析一下x为左节点的情况，右节点可参考左节点理解，因为它们非常类似\n        if (x == leftOf(parentOf(x))) {\n            Entry<K,V> sib = rightOf(parentOf(x));\n//场景1：当x是左黑色节点，兄弟节点sib是红色节点\n//兄弟节点由红转黑，父节点由黑转红，按父节点左旋，\n//左旋后树的结构变化了，这时重新赋值sib，这个时候sib指向了x的兄弟节点\n            if (colorOf(sib) == RED) {\n                setColor(sib, BLACK);\n                setColor(parentOf(x), RED);\n                rotateLeft(parentOf(x));\n                sib = rightOf(parentOf(x));\n            }\n//场景2：节点x、x的兄弟节点sib、sib的左子节点和右子节点都为黑色时，需要将该节点sib由黑变\n//红，同时将x指向当前x的父节点\n            if (colorOf(leftOf(sib))  == BLACK &&\n                colorOf(rightOf(sib)) == BLACK) {\n                setColor(sib, RED);\n                x = parentOf(x);\n            } else {\n//场景3：节点x、x的兄弟节点sib、sib的右子节点都为黑色，sib的左子节点为红色时，\n//需要将sib左子节点设置为黑色，sib节点设置为红色，同时按sib右旋，再将sib指向x的\n//兄弟节点\n                if (colorOf(rightOf(sib)) == BLACK) {\n                    setColor(leftOf(sib), BLACK);\n                    setColor(sib, RED);\n                    rotateRight(sib);\n                    sib = rightOf(parentOf(x));\n                }\n//场景4：节点x、x的兄弟节点sib都为黑色，而sib的左右子节点都为红色或者右子节点为红色、\n//左子节点为黑色，此时需要将sib节点的颜色设置成和x的父节点p相同的颜色，\n//设置x的父节点为黑色，设置sib右子节点为黑色，左旋x的父节点p，然后将x赋值为root\n                setColor(sib, colorOf(parentOf(x)));\n                setColor(parentOf(x), BLACK);\n                setColor(rightOf(sib), BLACK);\n                rotateLeft(parentOf(x));\n                x = root;\n            }\n//x是右节点的情况\n        } else {\n            Entry<K,V> sib = leftOf(parentOf(x));\n            if (colorOf(sib) == RED) {\n                setColor(sib, BLACK);\n                setColor(parentOf(x), RED);\n                rotateRight(parentOf(x));\n                sib = leftOf(parentOf(x));\n            }\n            if (colorOf(rightOf(sib)) == BLACK &&\n                colorOf(leftOf(sib)) == BLACK) {\n                setColor(sib, RED);\n                x = parentOf(x);\n            } else {\n                if (colorOf(leftOf(sib)) == BLACK) {\n                    setColor(rightOf(sib), BLACK);\n                    setColor(sib, RED);\n                    rotateLeft(sib);\n                    sib = leftOf(parentOf(x));\n                }\n                setColor(sib, colorOf(parentOf(x)));\n                setColor(parentOf(x), BLACK);\n                setColor(leftOf(sib), BLACK);\n                rotateRight(parentOf(x));\n                x = root;\n            }\n        }\n    }\n    setColor(x, BLACK);\n}\n```\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-04-23 11:20:49', '2024-04-23 11:48:19', 1);
INSERT INTO `doc_content` VALUES (67, 1, 130, '# redis面试题（一）\n\n## redis相比其他key-value产品的优点：\n- Redis 支持数据的持久化，可以将内存中的数据保存在磁盘中，重启的时候可以再次加载进行使用\n- Redis 不仅仅支持简单的 key-value 类型的数据，同时还提供 list，set，zset，hash 等数据结构的存储\n- Redis 支持数据的备份，即 master-slave 模式的数据备份\n\n## redis 优势：\n- 性能极高 \n- 丰富的数据类型 （5种数据结构）\n- 原子 – Redis 的所有操作都是原子性的，意思就是要么成功执行要么失败完全不执行。单个操作是原子性的。多个操作也支持事务，即原子性，通过 MULTI 和 EXEC指令包起来\n- 丰富的特性 – Redis 还支持 publish/subscribe, 通知, key 过期等等特性\n\n## redis 数据类型：\nRedis 支持五种数据类型：string（字符串），hash（哈希），list（列表），set（集合）及 zsetsorted set：有序集合)\nstring，hash 比较常用\n\n## redis 对比 Memcached 的优势：\n- Memcached 所有的值均是简单的字符串，redis 作为其替代者，支持更为丰富的数据类\n- redis 速度更快\n- redis 可以持久化数据\n\n## Redis 的持久化机制是什么？各自的优缺点？\n### 1. RDB(Redis DataBase)持久化方式：\n是指用数据集快照的方式半持久化模式)记录 redis 数据库的所有键值对,在某个时间点将数据写入一个临时文件，持久化结束后，用这个临时文件替换上次持久化的文件，达到数据恢复。\n\n优点：\n- 只有一个文件 dump.rdb，方便持久化。\n- 容灾性好，一个文件可以保存到安全的磁盘。\n- 性能最大化，fork 子进程来完成写操作，让主进程继续处理命令，所以是 IO最大化。使用单独子进程来进行持久化，主进程不会进行任何 IO 操作，保证了 redis的高性能)\n- 相对于数据集大时，比 AOF 的启动效率更高。\n\n缺点：\n数据安全性低。RDB 是间隔一段时间进行持久化，如果持久化之间 redis 发生故障，会发生数据丢失。所以这种方式更适合数据要求不严谨的时候\n\n### 2. AOF(Append-only file) 持久化方式：\n是指所有的命令行记录以 redis 命令请求协议的格式完全持久化存储)保存为 aof 文件。\n优点：\n- 数据安全，aof 持久化可以配置 appendfsync 属性，有 always，每进行一次命令操作就记录到 aof 文件中一次。\n- 通过 append 模式写文件，即使中途服务器宕机，可以通过 redis-check-aof工具解决数据一致性问题。\n- AOF 机制的 rewrite 模式。AOF 文件没被 rewrite 之前（文件过大时会对命令进行合并重写），可以删除其中的某些命令（比如误操作的 flushall）)\n\n缺点：\n- AOF 文件比 RDB 文件大，且恢复速度慢。\n- 数据集大的时候，比 rdb 启动效率低。\n\n## redis 过期键的删除策略：\n- 定时删除: 在设置键的过期时间的同时，创建一个定时器 timer。\n让定时器在键的过期时间来临时，立即执行对键的删除操作。\n- 惰性删除: 放任键过期不管，但是每次从键空间中获取键时，都检查取得的键是否过期，如果过期的话，就删除该键;如果没有过期，就返回该键。\n- 定期删除: 每隔一段时间程序就对数据库进行一次检查，删除里面的过期键。至于要删除多少过期键，以及要检查多少个数据库，则由算法决定。\n\n## redis 事务：\n- 事务是一个单独的隔离操作：事务中的所有命令都会序列化、按顺序地执行。事务在执行的过程中，不会被其他客户端发送来的命令请求所打断\n- 事务是一个原子操作：事务中的命令要么全部被执行，要么全部都不执行\n\n## redis 数据淘汰策略：\n- volatile-lru：从已设置过期时间的数据集（server.db[i].expires）中挑选最近最少使用的数据淘汰\n- volatile-ttl：从已设置过期时间的数据集（server.db[i].expires）中挑选将要过期的数据淘汰\n- volatile-random：从已设置过期时间的数据集（server.db[i].expires）中任意选择数据淘汰\n- allkeys-lru：从数据集（server.db[i].dict）中挑选最近最少使用的数据淘汰\n- allkeys-random：从数据集（server.db[i].dict）中任意选择数据淘汰\n- no-enviction（驱逐）：禁止驱逐数据\n\n## redis 缓存穿透、缓存击穿和缓存雪崩：\n### 缓存穿透：\n\n描述：穿过redis和数据库，缓存和数据库中都没有数据\n当 Redis 和数据库中都没有我们想要的数据时，就需要考虑是否存在缓存穿透问题\n\n解决方案：\n1. 缓存空结果：不能缓存太长时间，否则可能影响数据时效性\n2. 用户合法性校验：拦截恶意重复请求\n3. 布隆过滤器：用于检索一个元素是否在一个集合中。它的优点是空间效率和查询时间都比一般的算法要好的多，缺点是有一定的误识别率和删除困难\n\n### 缓存击穿\n\n描述：redis中们没有数据且数据库中有数据，查询数据库时由于并发量大导致数据库压力瞬间增大\n\n解决方案：\n1. 热点数据不过期\n2. 接口限流、熔断与降级\n3. 互斥锁\n![redis-互斥锁.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-26_11-42-29_0902e8_redis-互斥锁.png)\n\n优点：\n- 没有额外的内存消耗\n- 保证一致性\n- 实现简单\n\n缺点：\n- 线程需要等待，性能受到影响\n- 可能有死锁的风险\n\n![redis-互斥锁1.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-26_12-28-35_adcfcc_redis-互斥锁1.png)\n\n1. 缓存中有数据，直接走上述代码13行后就返回结果了\n2. 缓存中没有数据，第1个进入的线程，获取锁并从数据库去取数据，没释放锁之前，其他并行进入的线程会等待100ms，再重新去缓存取数据。这样就防止都去数据库重复取数据，重复往缓存中更新数据情况出现\n3. 当然这是简化处理，理论上如果能根据key值加锁就更好了，就是线程A从数据库取key1的数据并不妨碍线程B取key2的数据，上面代码明显做不到这点\n\n### 缓存雪崩\n\n缓存雪崩是指缓存中数据大批量到过期时间，而查询数据量巨大，引起数据库压力过大甚至down机。和缓存击穿不同的是，        缓存击穿指并发查同一条数据，缓存雪崩是不同数据都过期了，很多数据都查不到从而查数据库。\n\n#### 解决方案：\n- 缓存数据的过期时间设置随机，防止同一时间大量数据过期现象发生\n- 如果缓存数据库是分布式部署，将热点数据均匀分布在不同搞得缓存数据库中\n- 设置热点数据永远不过期\n\n## redis多线程问题\n### redis 6 之前\nRedis 在处理客户端的请求时，包括获取 (socket 读)、解析、执行、内容返回 (socket 写) 等都由一个顺序串行的主线程处理，这就是所谓的单线程。除了主线程外，它也有后台线程在处理一些较为缓慢的操作，例如清理脏数据、无用连接的释放、大 key 的删除等等。\n\n### redis 6 为什么要改为支持多线程 \n- 为了解决在分布式架构中对数据进行分区并采用多个服务器\n- 可以充分利用服务器 CPU 资源，目前主线程只能利用一个核\n- 多线程任务可以分摊 Redis 同步 IO 读写负荷\n\n## redis 集群\n### 集群模式\n#### redis 集群搭建有几种模式\n- 主从模式\n\nRedis 虽然读写速度非常快，但是也会产生性能瓶颈，特别是在读压力上，为了分担压力，Redis 支持主从复制。Redis 的主从结构一主一从，一主多从或级联结构，复制类型可以根据是否是全量而分为全量同步和增量同步。\n![20210915004402460.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-26_16-34-48_84403a_20210915004402460.png)\n\n- 哨兵模式\n\n在主从复制实现之后，如果想对 master 进行监控，Redis 提供了一种哨兵机制，哨兵的含义就是监控 Redis 系统的运行状态，通过投票机制，从 slave 中选举出新的 master 以保证集群正常运行。\n还可以启用多个哨兵进行监控以保证集群足够稳健，这种情况下，哨兵不仅监控主从服务，哨兵之间也会相互监控。\n![20210915004448949.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-26_16-35-06_02bd5d_20210915004448949.png)\n\n- 集群模式\n\n集群由多个Redis主从组成，每一个主从代表一个节点，每个节点负责一部分数据，他们之间通过一种特殊的二进制协议交互集群信息。\n![20210915004424387.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-26_16-35-16_d4944f_20210915004424387.png)\n\n## Redis 通讯协议\n\n## Redis 命令处理流程\n\n## Redis事件机制\n\n时间事件： 是由定时器或周期调度产生的事件\n文件事件： 是普通的增删改查命令产生的事件\n\n\n## Redis 和 MySQL 数据保持一致\n\n缓存的数据源来自于数据库, 而数据库发生变化时缓存没有同步, 此时就会有一致性问题存在，解决方案：\n\n- 先删除缓存，再更新数据库（这种方法在并发下最容易出现长时间的脏数据，不可取）\n\n- 先更新数据库，删除缓存（Cache Aside Pattern）\n\n- 只更新缓存，由缓存自己同步更新数据库（Read/Write Through Pattern）\n\n- 只更新缓存，由缓存自己异步更新数据库（Write Behind Cache Pattern）\n\n\n**先删除缓存，再更新数据库：**\n在并发读写的情况下容易出现缓存不一致的问题\n![20240706134955105.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-25_13-21-56_4b1f2f_20240706134955105.png)\n\n最后缓存中的数据 A 跟数据库中的数据 A 是不一致的，缓存中的数据A是旧的脏数据。\n\n**先更新数据库，再让缓存失效：**\n在并发读写的情况下，也可能会出现短暂缓存不一致的问题\n![20240706134956106.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-25_13-23-20_087fb6_20240706134956106.png)\n最后缓存中的数据A和数据库中的数据 A 是一致的，理论上可能会出现一小段时间数据不一致，不过这种概率也比较低，大部分的业务也不会有太大的问题。\n\n**只更新缓存，由缓存自己同步更新数据库：**\n![20240706134956107.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-25_13-25-11_8def12_20240706134956107.png)\n\n\n**只更新缓存，由缓存自己异步更新数据库：**\n![20240706134956108.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-25_13-40-25_d83a69_20240706134956108.png)\n\n读写的性能都非常好，基本上只要操作完内存后就返回给客户端了，但是其是非强一致性，存在丢失数据的情况。\n如果在缓存异步将数据更新到数据库中时，缓存服务挂了，此时未更新到数据库中的数据就丢失了。\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-04-25 15:10:59', '2024-07-25 13:40:56', 1);
INSERT INTO `doc_content` VALUES (68, 1, 131, '# 布隆过滤器\n## 什么是布隆过滤器\n\n布隆过滤器（Bloom Filter）是1970年由布隆提出的。它实际上是一个很长的二进制向量和一系列随机映射函数。布隆过滤器可以用于检索一个元素是否在一个集合中。它的优点是空间效率和查询时间都比一般的算法要好的多，缺点是有一定的误识别率和删除困难。\n\n可以把布隆过滤器理解为一个set集合，我们可以通过add往里面添加元素，通过contains来判断是否包含某个元素。\n\n### 布隆过滤器的优点：\n\n- 时间复杂度低，增加和查询元素的时间复杂为O(N)，（N为哈希函数的个数，通常情况比较小）\n- 保密性强，布隆过滤器不存储元素本身\n- 存储空间小，如果允许存在一定的误判，布隆过滤器是非常节省空间的（相比其他数据结构如Set集合）\n\n### 布隆过滤器的缺点：\n\n- 有点一定的误判率，但是可以通过调整参数来降低\n- 无法获取元素本身\n- 很难删除元素\n\n## 布隆过滤器的使用场景\n布隆过滤器用于判断某个数据一定不存在或者可能存在（由于存在误判）\n\n- redis 缓存穿透问题\n- 邮件过滤，使用布隆过滤器来做邮件黑名单过滤\n- 对爬虫网址进行过滤，爬过的不再爬\n- 解决新闻推荐过的不再推荐(类似抖音刷过的往下滑动不再刷到)\n\n## 布隆过滤器原理\n### 数据结构\n布隆过滤器它实际上是一个很长的二进制向量和一系列随机映射函数。以Redis中的布隆过滤器实现为例，Redis中的布隆过滤器底层是一个大型位数组（二进制数组）+ 多个无偏hash函数。\n\n一个大型位数组（二进制数组）：\n\n![redis-1.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-25_20-12-46_f36331_redis-1.png)\n\n多个无偏hash函数：\n\n无偏hash函数就是能把元素的hash值计算的比较均匀的hash函数，能使得计算后的元素下标比较均匀的映射到位数组中。\n如下就是一个简单的布隆过滤器示意图，其中k1、k2代表增加的元素，a、b、c即为无偏hash函数，最下层则为二进制数组。\n![redis-2.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-26_10-57-16_8ce1fd_redis-2.png)\n\n### 空间计算\n在布隆过滤器增加元素之前，首先需要初始化布隆过滤器的空间，也就是上面说的二进制数组，除此之外还需要计算无偏hash函数的个数。布隆过滤器提供了两个参数，分别是预计加入元素的大小n，运行的错误率f。布隆过滤器中有算法根据这两个参数会计算出二进制数组的大小l，以及无偏hash函数的个数k。\n\n它们之间的关系比较简单：\n\n- 错误率越低，位数组越长，控件占用较大\n- 错误率越低，无偏hash函数越多，计算耗时较长\n\n### 增加元素\n往布隆过滤器增加元素，添加的key需要根据k个无偏hash函数计算得到多个hash值，然后对数组长度进行取模得到数组下标的位置，然后将对应数组下标的位置的值置为1\n\n通过k个无偏hash函数计算得到k个hash值\n依次取模数组长度，得到数组索引\n将计算得到的数组索引下标位置数据修改为1\n例如，key = Liziba，无偏hash函数的个数k=3，分别为hash1、hash2、hash3。三个hash函数计算后得到三个数组下标值，并将其值修改为1.\n如图所示：\n![redis-3.png](http://49.232.129.253:9000/blog/1/doc/img/2024-04-26_11-01-17_6b1073_redis-3.png)\n\n### 查询元素\n布隆过滤器最大的用处就在于判断某样东西一定不存在或者可能存在，而这个就是查询元素的结果。其查询元素的过程如下：\n\n- 通过k个无偏hash函数计算得到k个hash值\n- 依次取模数组长度，得到数组索引\n- 判断索引处的值是否全部为1，如果全部为1则存在（这种存在可能是误判），如果存在一个0则必定不存在\n\n关于误判，其实非常好理解，hash函数在怎么好，也无法完全避免hash冲突，也就是说可能会存在多个元素计算的hash值是相同的，那么它们取模数组长度后的到的数组索引也是相同的，这就是误判的原因。', NULL, NULL, '2024-04-25 20:06:22', '2024-04-26 11:05:54', 1);
INSERT INTO `doc_content` VALUES (69, 1, 133, '# netty面试题（一）\n\n## netty的优势\n\n- 使用简单：封装了 Java 原生 NIO 类库繁琐的 API，使用起来更加高效；\n- 功能强大：预置多种编码能力，支持多种主流协议。同时通过 ChannelHandler 可以进行灵活的拓展，支持很强的定制能力\n- 高性能：与其它业界主流 NIO 框架相比，Netty 综合更优。主要体现在吞吐量更高、延迟更低、减少资源消耗以及最小化不必要的内存复制\n- 社区活跃与稳定：版本更新周期短，BUG 修复速度快，让开发者可以专注业务本身\n\n## netty的特点\n\n- 高并发：Netty 是一款基于 NIO（Nonblocking I/O，非阻塞IO）开发的网络通信框架。\n- 传输快：Netty 使用零拷贝特性，尽量减少不必要的内存拷贝，实现更快的传输效率。\n- 封装好：Netty 封装了 NIO 操作的很多细节，提供易于使用的 API。\n\n## Netty 的高性能体现在\n- IO 线程模型：NIO同步非阻塞\n- 零拷贝：尽量做到不必要的内存拷贝\n- 内存池设计：使用直接内存，并且可重复利用\n- 串行化处理读写：避免使用锁带来的额外开销\n- 高性能序列化协议：支持 protobuf 等高性能序列化协议\n\n## BIO. NIO. AIO 分别是什么\n\n- BIO（同步阻塞 IO）\n\n服务器实现模式为一个连接一个线程，即客户端有连接请求时服务器端就需要启动一个线程进行处理，如果这个连接不做任何事情会造成不必要的线程开销，当然可以通过线程池机制改善。BIO 方式适用于连接数目比较小且固定的架构，这种方式对服务器资源要求比较高，并发局限于应用中，JDK 1.4 以前的唯一选择，但程序直观简单易理解。\n\n- NIO（同步非阻塞 IO）\n\n服务器实现模式为一个请求一个线程，即客户端发送的连接请求都会注册到多路复用器上，多路复用器轮询到连接有 IO 请求时才启动一个线程进行处理。NIO 方式适用于连接数目多且连接比较短（轻操作）的架构，比如聊天服务器，并发局限于应用中，编程比较复杂，JDK 1.4 开始支持。\n\n- AIO（异步非阻塞 IO）\n\n服务器实现模式为一个有效请求一个线程，客户端的 IO 请求都是由 OS 先完成了再通知服务器应用去启动线程进行处理。 AIO 方式使用于连接数目多且连接比较长（重操作）的架构，比如相册服务器，充分调用 OS 参与并发操作，编程比较复杂，JDK 1.7 开始支持。\n\n## Netty的核心组件是什么？\n\nNetty的核心组件包括以下几个主要部分：\n\n- Channel（通道）： Channel是Netty中用于处理数据的通道。它负责所有的I/O操作，包括读取、写入、连接和绑定等。Netty提供了不同类型的Channel，用于支持TCP、UDP等不同的传输协议。\n\n- EventLoop（事件循环）： EventLoop是Netty异步事件处理的核心。每个Channel都与一个EventLoop关联，它负责处理该Channel上的所有事件。EventLoop采用单线程或多线程的方式，负责处理I/O事件、执行任务和定时任务等。\n\n- ChannelPipeline（通道管道）： ChannelPipeline是一个由一系列ChannelHandler组成的处理链。每个Channel都有一个关联的ChannelPipeline，用于处理入站和出站的数据。ChannelHandler负责处理特定类型的事件，如数据编解码、业务逻辑处理等。\n\n- ChannelHandler（通道处理器）： ChannelHandler是用于处理I/O事件的组件。开发者可以编写自定义的ChannelHandler来实现特定的业务逻辑，例如数据编解码、业务处理等。ChannelHandler可添加到ChannelPipeline中，形成一个处理链。\n\n- ByteBuf（字节缓冲区）： ByteBuf是Netty中用于存储和操作字节数据的缓冲区。它提供了灵活的API，支持池化、切片等高级特性，有助于提高性能和内存管理效率。\n\n- ChannelFuture（通道未来）： ChannelFuture表示异步操作的结果，例如I/O操作的成功、失败或取消。通过ChannelFuture，开发者可以注册监听器以处理操作完成时的回调。\n\n- Bootstrap（引导类）： Bootstrap是Netty用于启动客户端的引导类。它负责配置和启动Netty的客户端组件，包括设置Channel类型、EventLoop组、ChannelPipeline等。\n\n- ServerBootstrap（服务器引导类）： ServerBootstrap是Netty用于启动服务器的引导类。它包含了一些服务器独有的配置选项，如处理客户端连接请求、设置TCP参数等。\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-04-26 16:40:38', '2024-07-15 13:43:28', 1);
INSERT INTO `doc_content` VALUES (70, 1, 135, '# MySQL面试题（一）`优化相关`\n\n## 1. sql调优步骤\n\n### 排查慢SQL\n\n```sql\n# 查看慢查询次数：\nshow status like \'slow_queries\';\n# 开启慢查询\nset global slow_query_log=on;\n```\n\n### 基础优化\n\n- 定期清理数据\n- 选择合适的存储引擎\n  - MyISAM：适合读取频繁，写入较少的场景\n  - InnoDB：适合并发写入的场景\n\n### 表设计优化\n\n- 遵循三个范式\n  - 属性不可再分、表必须有且只有一个主键、非主键列必须直接依赖于主键\n- 数据类型优化 使用合理的字段类型\n\n### 索引优化\n\n- 尽量匹配全值\n- 优先使用左前缀\n- 主键尽量有序\n\n### sql优化\n\n1. 开启缓存查询\n```sql\n<!-- 设置缓存内存 -->\nset global query_cache_size = 600000;\n<!-- 开启查询缓存 -->\nset session query_cache_type = ON;\n```\n2. EXPLAIN SELECT查询语句\n\n分析查询语句或是表结构的性能瓶颈\n\n3. 只要一行数据时使用LIMIT1\n4. 为搜索字段建索引\n5. 在Join表的时候使用相同类型的例，并将其索引\n\n使用JOIN查询时应该确认两个表中Join的字段是被建过索引的。这样MySQL内部会启动优化Join的SQL语句的机制\n\n6. 避免 SELECT *\n7. 枚举类型使用ENUM而不是VARCHAR\n8. 拆分大的DELETE或INSERT语句\n\n', NULL, NULL, '2024-04-27 18:50:35', '2024-06-18 16:53:00', 1);
INSERT INTO `doc_content` VALUES (71, 1, 136, '# InnoDB原理\n\n## InnoDB页结构\n\n在MySQL底层，需要通过InnoDB引擎将数据从磁盘中读取到内存中，或者是将内存中的数据持久化到磁盘中，那么在InnoDB中，规定是：将数据分为若干个页，然后以页为单位作为磁盘和内存交互的单位。在InnoDB中一个页单位大小一般为16KB。\n\n一个页一般是16KB，当记录中的数据太多，当前页放不下的时候，会把多余的数据存储到其他页中，这种现象称为行溢出。\n\n\n## InnoDB行格式\n\nInnoDB将以16KB大小的页来作为内存和磁盘的交互基本单位，MySQL中的数据存储到磁盘中是以 行格式 方式存储\n\n在InnoDB中有4中行格式：\n\n1. Compact行格式\n2. Redundant行格式\n3. Dynamic行格式\n4. Compressed行格式\n\n每个行格式都分为两部分：记录的额外信息、记录的真实信息。\n\n## InnoDB数据页结构\n\n在InnoDB数据页结构中，被划分为了7个部分\n\n最重要的就是：\n\n- 用户记录（User Records）\n- 页面目录（Page Directory）\n- 页面头部（File Header）\n- 空闲空间（Free Space）\n\n通常，MySQL真实数据是存储在用户记录部分的。但是在一开始生成页的时候，是不存在用户记录部分的，每当插入一条记录时，都会从Free Space分配部分空间给User Records，待Free Space空间分配完了，也就意味着\n当前页使用完了，数据以及填充满了，如果还有新的记录插入的话，就需要去申请新的页了，这就是页分裂过程。\n\n\n## B+树索引\n\n### InnoDB中B+树索引原理\n\n在InnoDB中，会将B+树叶子节点中一个页记录链表头对应的最小主键值记录在一个目录项中，一条目录项包含了最小主键值以及该主键值对应的页数，而在B+树叶子节点中会存有多个数据页，并且是作为双向链表连接起来的数据页。\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-06-14 16:01:06', '2024-06-14 16:40:27', 1);
INSERT INTO `doc_content` VALUES (72, 1, 137, '# MySQL面试题（二） `基础相关`\n\n## 1. MySQL 七种索引类型\n\n- 主键索引\n数据列不允许重复，不允许为NULL，一个表只能有一个主键。\nALTER TABLE table_name ADD PRIMARY KEY (column);\n\n- 普通索引\nMySQL中基本索引类型，没有什么限制，允许在定义索引的列中插入重复值和NULL值。一个表允许多个列创建普通索引。\nALTER TABLE table_name ADD INDEX index_name (column);\n\n- 唯一索引\n索引列中的值必须是唯一的，但是允许NULL值。建立唯一索引的目的大部分时候都是为了该属性列的数据的唯一性，而不是为了查询效率。一个表允许多个列创建唯一索引。\nALTER TABLE table_name ADD UNIQUE (column);\n\n- 全文索引\n主要是为了快速检索大文本数据中的关键字的信息。字段长度比较大时，如果创建普通索引，在进行like模糊查询时效率比较低，这时可以创建全文索引，基于倒排索引，类似于搜索引擎。MyISAM存储引擎支持全文索引，InnoDB 存储引擎在 MySQL 5.6.4 版本中也开始支持全文索引。\nALTER TABLE table_name ADD FULLTEXT (column);\n\n- 组合索引\n指多个字段上创建的索引，只有在查询条件中使用了创建索引时的第一个字段，索引才会被使用。使用组合索引时遵循最左前缀原则。\n主键索引、普通索引、唯一索引等都可以使用多个字段形成组合索引。例如，ALTER TABLE table_name ADD INDEX index_name ( column1, column2, column3 );\n\n- 前缀索引\n在文本类型如BLOB、TEXT或者很长的VARCHAR列上创建索引时，可以使用前缀索引，数据量相比普通索引更小，可以指定索引列的长度，但是数值类型不能指定。\nALTER TABLE table_name ADD KEY(column_name(prefix_length));\n\n- 空间索引\nMySQL在5.7之后的版本支持了空间索引，而且支持OpenGIS几何数据模型。MySQL在空间索引这方面遵循OpenGIS几何数据模型规则。\n\n## 2. MySQL事务\n事务是访问和更新数据库的程序执行单元；事务中可能包含一个或多个sql语句，这些语句要么都执行，要么都不执行。\nMySQL中服务器层不管理事务，事务是由存储引擎实现的。MySQL支持事务的存储引擎有InnoDB、NDB Cluster等。\n\n1. 事务提交和回滚\n```sql\nstart transaction;\n……  #一条或多条sql语句\ncommit;\n```\n其中start transaction标识事务开始，commit提交事务，将执行结果写入到数据库。如果sql语句执行出现问题，会调用rollback，回滚所有已经执行成功的sql语句。\n\n2. ACID特性\nACID是衡量事务的四个特性：\n- 原子性（Atomicity，或称不可分割性）\n  - 原子性是指一个事务是一个不可分割的工作单位，其中的操作要么都做，要么都不做；如果事务中一个sql语句执行失败，则已执行的语句也必须回滚，数据库退回到事务前的状态。\n- 一致性（Consistency）\n  - 一致性是指事务执行结束后，数据库的完整性约束没有被破坏，事务执行的前后都是合法的数据状态\n- 隔离性（Isolation）\n  - 保证事务执行尽可能不受其他事务影响\n- 持久性（Durability）\n  - 保证事务提交后不会因为宕机等原因导致数据丢失\n\n3. 事务隔离级别\n\n- 脏读是指在一个事务处理过程里读取了另一个未提交的事务中的数据。\n- 不可重复读是指在对于数据库中的某行记录，一个事务范围内多次查询却返回了不同的数据值，这是由于在查询间隔，另一个事务修改了数据并提交了。\n- 幻读是当某个事务在读取某个范围内的记录时，另外一个事务又在该范围内插入了新的记录。对幻读的正确理解是一个事务内的读取操作的结论不能支撑之后业务的执行。假设事务要新增一条记录，主键为id，在新增之前执行了select，没有发现id为xxx的记录，但插入时出现主键冲突，这就属于幻读，读取不到记录却发现主键冲突是因为记录实际上已经被其他的事务插入了，但当前事务不可见。\n\n|隔离级别|脏读（Dirty Read）|不可重复读（NonRepeatable Read）|幻读（Phantom Read） |\n|-|-|-| - |		\n|读未提交(Read uncommitted）	|可能	|可能	|可能\n|读已提交（Read committed）	|不可能	|可能	|可能\n|可重复读（Repeatable read）	|不可能	|不可能	|可能\n|可串行化（Serializable ）	|不可能	|不可能	|不可能\n\n不可重复读和脏读的区别是，脏读是某一事务读取了另一个事务未提交的脏数据，而不可重复读则是读取了前一事务提交的数据。\n\nMySQL是如何避免幻读？\n- 在快照读情况下，MySQL通过mvcc来避免幻读。\n- 在当前读情况下，MySQL通过next-key来避免幻读（加行锁和间隙锁来实现的）。\n\nMVCC是什么？\nmvcc，也就是多版本并发控制，是为了在读取数据时不加锁来提高读取效率和并发性的一种手段。\n\nmvcc所提到的读是快照读，也就是普通的select语句。快照读在读写时不用加锁，不过可能会读到历史数据。\n\nMySQL数据库为我们提供的四种隔离级别：\n- Serializable (串行化)：通过强制事务排序，使之不可能相互冲突，从而解决幻读问题。\n- Repeatable read (可重复读)：MySQL的默认事务隔离级别，它确保同一事务的多个实例在并发读取数据时，会看到同样的数据行，解决了不可重复读的问题。\n- Read committed (读已提交)：一个事务只能看见已经提交事务所做的改变。可避免脏读的发生。\n- Read uncommitted (读未提交)：所有事务都可以看到其他未提交事务的执行结果。\n\n## 3. MySQL数据类型\n- 数值类型 整数类型: TINYINT、SMALLINT、MEDIUMINT、INT、BIGINT 小数类型: FLOAT、DOUBLE、DECIMAL\n  - 任何整数类型都可以加上 UNSIGNED 属性，表示无符号整数\n  - 任何整数类型都可以指定长度，但它不会限制数据的合法长度，仅仅限制了显示长度\n- 字符串类型: VARCHAR、CHAR、TEXT、BLOB\n  - CHAR 定长，VARCHAR 变长 (不超过65535字节)\n  - CHAR 会根据声明的字符串长度分配空间，并会使用空格对字符串右边进行尾部填充 所以最后一个是空格会被删除\n  - VARCHAR 数据开头使用额外 1~2 个字节存储字符串长度（列长度小于 255 字节时使用 1 字节表示，否则 2 字节），在结尾使用 1 字节表示字符串结束\n  - CHAR 对英文字符（ASCII）占用 1 字节，对一个汉字使用用 2 字节。而 VARCHAR 对每个字符均使用 2 字节\n  - 对于经常变更的数据来说，CHAR 比 VARCHAR更好，因为 CHAR 不容易产生碎片\n  - 尽量避免使用 TEXT/BLOB 类型，查询时会使用临时表，导致严重的性能开销\n- 日期和时间类型: DATETIME、DATE 和 TIMESTAMP\n  - 尽量使用 TIMESTAMP，空间效率高于 DATETIME\n\n## 4. 三大范式\n第一范式（1NF）：字段（或属性）是不可分割的最小单元，即不会有重复的列，体现原子性\n第二范式（2NF）：满足 1NF 前提下，存在一个候选码，非主属性全部依赖该候选码，即存在主键，体现唯一性，专业术语则是消除部分函数依赖\n第三范式（3NF）：满足 2NF 前提下，非主属性必须互不依赖，消除传递依赖\n\n## 5. 范式和反范式\n范式: 范式化的表减少了数据冗余，数据表更新操作快、占用存储空间少。但是查询时通常需要多表关联查询，更难进行索引优化\n反范式: 反范式的过程就是通过冗余数据来提高查询性能，可以减少表关联和更好进行索引优化。但是存在大量冗余数据，并且数据的维护成本更高\n\n## 6. MySQL有哪些锁？\n按锁粒度分类，有行级锁、表级锁和页级锁。\n\n1. 行级锁是mysql中锁定粒度最细的一种锁。表示只针对当前操作的行进行加锁。行级锁能大大减少数据库操作的冲突，其加锁粒度最小，但加锁的开销也最大。行级锁的类型主要有三类：\n   - Record Lock，记录锁，也就是仅仅把一条记录锁上；\n   - Gap Lock，间隙锁，锁定一个范围，但是不包含记录本身；\n   - Next-Key Lock：Record Lock + Gap Lock 的组合，锁定一个范围，并且锁定记录本身。\n2. 表级锁是mysql中锁定粒度最大的一种锁，表示对当前操作的整张表加锁，它实现简单，资源消耗较少，被大部分mysql引擎支持。最常使用的MyISAM与InnoDB都支持表级锁定。\n3. 页级锁是 MySQL 中锁定粒度介于行级锁和表级锁中间的一种锁。表级锁速度快，但冲突多，行级冲突少，但速度慢。因此，采取了折衷的页级锁，一次锁定相邻的一组记录。\n\n按锁级别分类，有共享锁、排他锁和意向锁。\n1. 共享锁又称读锁，是读取操作创建的锁。其他用户可以并发读取数据，但任何事务都不能对数据进行修改（获取数据上的排他锁），直到已释放所有共享锁。\n2. 排他锁又称写锁、独占锁，如果事务T对数据A加上排他锁后，则其他事务不能再对A加任何类型的封锁。获准排他锁的事务既能读数据，又能修改数据。\n3. 意向锁是表级锁，其设计目的主要是为了在一个事务中揭示下一行将要被请求锁的类型。InnoDB 中的两个表锁：\n\n## 7. MySQL架构\n\nMySQL主要分为 Server 层和存储引擎层：\n- Server 层：主要包括连接器、查询缓存、分析器、优化器、执行器等，所有跨存储引擎的功能都在这一层实现，比如存储过程、触发器、视图，函数等，还有一个通用的日志模块 binglog 日志模块。\n- 存储引擎： 主要负责数据的存储和读取。server 层通过api与存储引擎进行通信。\n\nServer 层基本组件\n\n连接器： 当客户端连接 MySQL 时，server层会对其进行身份认证和权限校验。\n查询缓存: 执行查询语句的时候，会先查询缓存，先校验这个 sql 是否执行过，如果有缓存这个 sql，就会直接返回给客户端，如果没有命中，就会执行后续的操作。\n分析器: 没有命中缓存的话，SQL 语句就会经过分析器，主要分为两步，词法分析和语法分析，先看 SQL 语句要做什么，再检查 SQL 语句语法是否正确。\n优化器： 优化器对查询进行优化，包括重写查询、决定表的读写顺序以及选择合适的索引等，生成执行计划。\n执行器： 首先执行前会校验该用户有没有权限，如果没有权限，就会返回错误信息，如果有权限，就会根据执行计划去调用引擎的接口，返回结果。\n\n\n## 主从复制\n\n**为什么要做主从复制：**\n- 在复杂的业务操作中，经常会有操作导致锁行甚至锁表的情况，如果读写不解耦，会很影响运行中的业务，使用主从复制，让主库负责写，从库负责读。\n- 保证数据的热备份，主库宕机后能够及时替换主库，保障业务可用性。\n- 架构的演进：业务量扩大，I/O访问频率增高，单机无法满足，主从复制可以做多库方案，降低磁盘I/O访问的频率，提高单机的I/O性能。\n- 本质上也是分治理念，主从复制、读写分离即是压力分拆的过程。\n\n**主从复制的原理：**\n1. 创建I/O线程连接主库\n2. 主库创建Binlog Dump线程读取数据库事件并发送给I/O线程\n3. I/O线程获取到事件数据后更新到从库的中继日志Relay Log中去\n4. 从库上的SQL线程读取中继日志Relay Log中更新的数据库事件并应用，\n\n![mysql-1.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-15_08-53-02_c9aa96_mysql-1.png)\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-06-18 16:53:31', '2024-07-15 12:55:08', 1);
INSERT INTO `doc_content` VALUES (73, 1, 140, '', NULL, NULL, '2024-06-27 15:03:33', NULL, 3);
INSERT INTO `doc_content` VALUES (74, 1, 143, '# @Bean 注解解析\n\n## @Bean 基础声明\n在Spring框架中，Bean是一个被Spring容器所管理的对象。Spring中的对象的创建、组装和管理是通过IOC思想和DI机制来完成的，而这些对象就被称为Bean。\n\nBean就是一个由Spring容器初始化、管理和维护的普通的Java对象。通过Spring容器，我们可以方便的创建和获取这些对象，并且可以配置它们的行为与属性。\n\nSpringIOC 容器管理一个或者多个bean，这些bean都需要在@Configuration注解下进行创建，在一个方法上使用@Bean注解就表明这个方法需要交给Spring进行管理。\n\n## @Bean 基本构成及其使用\n\n@Bean 注解源码\n```java\n@Target({ElementType.METHOD, ElementType.ANNOTATION_TYPE})\n@Retention(RetentionPolicy.RUNTIME)\n@Documented\npublic @interface Bean {\n    @AliasFor(\"name\")\n    String[] value() default {};\n\n    @AliasFor(\"value\")\n    String[] name() default {};\n\n    /** @deprecated */\n    @Deprecated\n    Autowire autowire() default Autowire.NO;\n\n    boolean autowireCandidate() default true;\n\n    String initMethod() default \"\";\n\n    String destroyMethod() default \"(inferred)\";\n}\n```\n@Bean不仅可以作用在方法上，也可以作用在注解类型上，在运行时提供注册\n\nvalue： name属性的别名，在不需要其他属性时使用，也就是说value 就是默认值\nname： 此bean 的名称，或多个名称，主要的bean的名称加别名。如果未指定，则bean的名称是带注解方法的名称。如果指定了，方法的名称就会忽略，如果没有其他属性声明的话，bean的名称和别名可能通过value属性配置\n\n## @Bean 注解生命周期\n\n![@Bean注解生命周期.png](http://49.232.129.253:9000/blog/1/doc/img/2024-06-27_15-22-06_4479b7_@Bean注解生命周期.png)\n\n### Bean的生命周期之五步分析法\n![439deaea784b0feb27579fd75f5e9fb5.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-41-23_59c5de_439deaea784b0feb27579fd75f5e9fb5.png)\n\n```java\npackage com.bjpowernode.spring.bean;\n \npublic class User {\n    private String username;\n \n    public void setUsername(String username) {\n        System.out.println(\"第二步：给对象的属性赋值\");\n        this.username = username;\n    }\n \n    public User() {\n        System.out.println(\"第一步：实例化Bean，无参数构造方法执行了\");\n    }\n \n    // 初始化Bean，需要自己写，自己配，方法名随意\n    public void initBean(){\n        System.out.println(\"第三步：初始化Bean\");\n    }\n \n    // 销毁Bean，需要自己写，自己配，方法名随意\n    public void destroyBean(){\n        System.out.println(\"第五步：销毁Bean\");\n    }\n \n    @Override\n    public String toString() {\n        return \"User{\" +\n                \"username=\'\" + username + \'\\\'\' +\n                \'}\';\n    }\n}\n```\n\n```xml\n<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<beans xmlns=\"http://www.springframework.org/schema/beans\"\n       xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\"\n       xsi:schemaLocation=\"http://www.springframework.org/schema/beans http://www.springframework.org/schema/beans/spring-beans.xsd\">\n \n    <bean id=\"user\" class=\"com.bjpowernode.spring.bean.User\"\n          init-method=\"initBean\" destroy-method=\"destroyBean\">\n          <!--给属性赋值-->\n         <property name=\"username\" value=\"张三\"/>\n    </bean>\n</beans>\n```\n\n测试程序：\n```java\npackage com.bjpowernode.spring.test;\n \nimport com.bjpowernode.spring.bean.User;\nimport org.junit.Test;\nimport org.springframework.context.ApplicationContext;\nimport org.springframework.context.support.ClassPathXmlApplicationContext;\n \npublic class BeanLifecycleTest {\n    @Test\n    public void testBeanLifeCycleFive(){\n        ApplicationContext applicationContext = new ClassPathXmlApplicationContext(\"spring.xml\");\n        User user = applicationContext.getBean(\"user\", User.class);\n        System.out.println(\"第四步：使用Bean\"+user);\n \n        // 需要手动关闭Spring容器\n        ClassPathXmlApplicationContext context = (ClassPathXmlApplicationContext) applicationContext;\n        context.close();\n    }\n}\n```\n![57cdf265b0d84f61a3acb43bd101c61c.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-44-12_10ad74_57cdf265b0d84f61a3acb43bd101c61c.png)\n\n总结要点：\n\n1. 只有正常关闭spring容器(调用close方法)，bean的销毁方法才会被调用。\n\n2. ClassPathXmlApplicationContext类才有close()方法，ApplicationContext中没有。\n\n3. 配置文件中的init-method指定初始化方法，destroy-method指定销毁方法。\n\n### Bean生命周期之七步分析法\n\n在以上的5步中，第3步是初始化Bean，如果你还想在初始化前和初始化后添加代码，可以加入“Bean后处理器”；需要编写一个类实现BeanPostproccessor接口，并重写里面的befor和after方法。\n\n![493a1201dd839499d7fd739bd2d1749e.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-46-51_b7bce8_493a1201dd839499d7fd739bd2d1749e.png)\n\n\n编写一个类实现BeanPostProcessor类，并且重写before和after方法\n\n方法中有两个参数：第一个参数是创建的Bean对象、第二个参数是Bean的名字\n\n```java\npackage com.bjpowernode.spring.test;\n \nimport org.springframework.beans.BeansException;\nimport org.springframework.beans.factory.config.BeanPostProcessor;\n \npublic class LogBeanPostProcessor implements BeanPostProcessor {\n    @Override\n    public Object postProcessBeforeInitialization(Object bean, String beanName) throws BeansException {\n        System.out.println(\"Bean后处理器的before方法执行，即将开始初始化\");\n        return BeanPostProcessor.super.postProcessBeforeInitialization(bean, beanName);\n    }\n \n    @Override\n    public Object postProcessAfterInitialization(Object bean, String beanName) throws BeansException {\n        System.out.println(\"Bean后处理器的after方法执行，已完成初始化\");\n        return BeanPostProcessor.super.postProcessAfterInitialization(bean, beanName);\n    }\n}\n```\n\n### Bean生命周期之十步分析法\n\n1. 在“Bean后处理器”before方法之前干了什么事儿？\n检查Bean是否实现了Aware相关的接口，如果实现了接口则调用这些接口中的方法；调用这些方法的目的是为了给你传递一些数据，让你更加方便使用。\n\n2. 在“Bean后处理器”before方法之后干了什么事儿？\n检查Bean是否实现了InitializingBean接口，如果实现了，则调用接口中的方法。\n\n3. 使用Bean之后，或者说销毁Bean之前干了什么事儿？\n检查Bean是否实现了DisposableBean接口，如果实现了，则调用接口中的方法。\n\n总结：添加的这三个点位的特点，都是在检查你这个Bean是否实现了某些特定的接口，如果实现了这些接口，则Spring容器会调用这个接口中的方法！\n\n![3a15ca07491713fc878cdd3a88c968c6.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-49-39_a326e7_3a15ca07491713fc878cdd3a88c968c6.png)\n\n\nAware相关的接口包括：BeanNameAware、BeanClassLoaderAware、BeanFactoryAware\n\n1. 当Bean实现了BeanNameAware，Spring会将Bean的名字传递给Bean。\n\n2. 当Bean实现了BeanClassLoaderAware，Spring会将加载该Bean的类加载器传递给Bean。\n\n3. 当Bean实现了BeanFactoryAware，Spring会将Bean工厂对象传递给Bean。\n\n\n```java\npackage com.bjpowernode.spring.bean;\n \nimport org.springframework.beans.BeansException;\nimport org.springframework.beans.factory.*;\n \n \npublic class User implements\n        BeanNameAware, BeanClassLoaderAware, BeanFactoryAware,\n        InitializingBean, DisposableBean{\n    private String username;\n \n    public void setUsername(String username) {\n        System.out.println(\"第二步：给对象的属性赋值\");\n        this.username = username;\n    }\n \n    public User() {\n        System.out.println(\"第一步：实例化Bean，无参数构造方法执行了\");\n    }\n \n    // 初始化Bean，需要自己写，自己配，方法名随意\n    public void initBean(){\n        System.out.println(\"第四步：初始化Bean\");\n    }\n \n    // 销毁Bean，需要自己写，自己配，方法名随意\n    public void destroyBean(){\n        System.out.println(\"第七步：销毁Bean\");\n    }\n \n    @Override\n    public String toString() {\n        return \"User{\" +\n                \"username=\'\" + username + \'\\\'\' +\n                \'}\';\n    }\n \n    @Override\n    public void setBeanClassLoader(ClassLoader classLoader) {\n        System.out.println(\"类加载器：\" + classLoader);\n    }\n \n    @Override\n    public void setBeanFactory(BeanFactory beanFactory) throws BeansException {\n        System.out.println(\"Bean工厂：\" + beanFactory);\n    }\n \n    @Override\n    public void setBeanName(String name) {\n        System.out.println(\"Bean的名字：\" + name);\n    }\n \n    @Override\n    public void destroy() throws Exception {\n        System.out.println(\"DisposableBean destroy方法执行了\");\n    }\n \n    @Override\n    public void afterPropertiesSet() throws Exception {\n        System.out.println(\"InitializingBean afterPropertiesSet方法执行了\");\n    }\n}\n```\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-06-27 15:05:20', '2024-07-23 16:53:22', 1);
INSERT INTO `doc_content` VALUES (75, 1, 144, '# Java如何避免死锁\n\n## 什么是死锁\n\njava中的死锁是一种编程情况，其中两个或多个线程被永久阻塞，Java死锁情况出现至少两个线程和两个或更多资源。\n\n## 如何排插死锁\n\n1. 首先通过 jps 命令获取进程号\n2. 通过 jstack -l 进程号 得到结果\n\n## 死锁产生的必要条件\n\n1. 互斥： 某种资源一次只允许一个进程访问，即该资源一旦分配给某个进程，其他进程就不能再访问，直到该进程访问结束。\n2. 占有且等待： 一个进程本身占有资源（一种或多种），同时还有资源未得到满足，正在等待其他进程释放该资源。\n3. 不可抢占： 资源被一个线程占有时，不可以再次被抢占。\n4. 循环等待： 在发生死锁时必然存在一个进程等待队列{P1,P2,…,Pn},其中P1等待P2占有的资源，P2等待P3占有的资源，…，Pn等待P1占有的资源，形成一个进程等待环路，环路中每一个进程所占有的资源同时被另一个申请，也就是前一个进程占有后一个进程所深情地资源。\n\n## 避免产生死锁\n\n### 预防死锁 \n- 破坏死锁产生的条件\n\n1. 破坏“占有且等待”条件\n```\n方法1：所有的进程在开始运行之前，必须一次性地申请其在整个运行过程中所需要的全部资源。\n优点：简单易实施且安全。\n缺点：因为某项资源不满足，进程无法启动，而其他已经满足了的资源也不会得到利用，严重降低了资源的利用率，造成资源浪费。使进程经常发生饥饿现象。\n\n方法2：允许进程只获得运行初期需要的资源，便开始运行，在运行过程中逐步释放掉分配到的已经使用完毕的资源，然后再去请求新的资源。\n这样的话，资源的利用率会得到提高，也会减少进程的饥饿问题。\n```\n\n2. 破坏“不可抢占”条件\n当一个已经持有了一些资源的进程在提出新的资源请求没有得到满足时，它必须释放已经保持的所有资源，待以后需要使用的时候再重新申请。\n\n3. 破坏“循环等待”条件\n通过定义资源类型的线性顺序来预防，可将每个资源编号，当一个进程占有编号为i的资源时，那么它下一次申请资源只能申请编号大于i的资源。\n\n![死锁-循环等待.png](http://49.232.129.253:9000/blog/1/doc/img/2024-06-27_16-44-30_783678_死锁-循环等待.png)\n\n### 避免死锁 \n- 在使用前进行判断，只允许不会产生死锁的进程申请资源\n\n\n1. 如果一个进程的请求会导致死锁，则不启动该进程\n2. 如果一个进程的增加资源请求会导致死锁 ，则拒绝该申请。\n\n避免死锁的具体实现通常利用银行家算法\n\n#### 银行家算法\n\n当一个进程申请使用资源的时候，银行家算法通过先 试探 分配给该进程资源，然后通过安全性算法判断分配后的系统是否处于安全状态，若不安全则试探分配作废，让该进程继续等待。\n\n![银行家算法.png](http://49.232.129.253:9000/blog/1/doc/img/2024-06-27_16-51-46_77f550_银行家算法.png)\n\n- 首先是银行家算法中的进程：\n  包含进程Pi的需求资源数量（也是最大需求资源数量，MAX）\n  已分配给该进程的资源A（Allocation）\n  还需要的资源数量N（Need=M-A）\n\n- Available为空闲资源数量，即资源池（注意：资源池的剩余资源数量+已分配给所有进程的资源数量=系统中的资源总量）\n\n假设资源P1申请资源，银行家算法先试探的分配给它（当然先要看看当前资源池中的资源数量够不够），若申请的资源数量小于等于Available，然后接着判断分配给P1后剩余的资源，能不能使进程队列的某个进程执行完毕，若没有进程可执行完毕，则系统处于不安全状态（即此时没有一个进程能够完成并释放资源，随时间推移，系统终将处于死锁状态）。\n\n若有进程可执行完毕，则假设回收已分配给它的资源（剩余资源数量增加），把这个进程标记为可完成，并继续判断队列中的其它进程，若所有进程都可执行完毕，则系统处于安全状态，并根据可完成进程的分配顺序生成安全序列（如{P0，P3，P2，P1}表示将申请后的剩余资源Work先分配给P0–>回收（Work+已分配给P0的A0=Work）–>分配给P3–>回收（Work+A3=Work）–>分配给P2–>······满足所有进程）。\n\n\n\n\n\n', NULL, NULL, '2024-06-27 16:30:34', '2024-07-01 13:50:22', 1);
INSERT INTO `doc_content` VALUES (76, 1, 145, '# @Autowired和@Resource注解的区别和联系\n\n## 联系 \n\n1. @Autowired和@Resource注解都是作为bean对象注入的时候使用的\n2. 两者都可以声明在字段和setter方法上\n\n## 区别\n\n1. @Autowired注解是Spring提供的，而@Resource注解是J2EE本身提供的\n2. @Autowird注解默认通过byType方式注入，而@Resource注解默认通过byName方式注入\n3. @Autowired注解注入的对象需要在IOC容器中存在，否则需要加上属性required=false，表示忽略当前要注入的bean，如果有直接注入，没有跳过，不会报错\n\nbyName就是变量名去匹配bean的id属性，而byType则是变量类型去匹配bean的class属性\n\n```java\n@Autowired\nprivate UserService userService;\n```\n此处byName就是拿变量名userService去匹配IOC容器的iduserService，匹配成功；而byType就是拿变量类型UserService去匹配IOC容器的idcom.test.UserService.UserServiceImpl，因为UserServiceImpl是UserService实现，所以也匹配成功\n\n## @Autowird注解的使用\n\n@Autowird默认的注入方式为byType，也就是根据类型匹配，当有多个实现时，则通过byName注入，也可以通过配合@Qualifier注解来显式指定name值，指明要使用哪个具体的实现类\n\n```java\n@Service\npublic class UserServiceImpl1 implements UserService\n\n@Service\npublic class UserServiceImpl2 implements UserService\n\n// 通过 @Autowired 注入使用\n@Autowired\nprivate UserService userService;\n```\n\n根据上面的步骤，可以很容易判断出，直接这么使用是会报错的\n原因：首先通过byType注入，判断UserService类型有两个实现，无法确定具体是哪一个，于是通过byName方式，这里的变量名userService也无法匹配IOC容器中id（此处指的userServiceImpl1和userServiceImpl2），于是报错。\n\n\n解决方案\n\n方式一：\n```java\n// 方式一：改变变量名\n@Autowired\nprivate UserService userServiceImpl1;\n```\n\n方式二：\n```java\n// 方式二：配合@Qualifier注解来显式指定name值\n@Autowired\n@Qualifier(value = \"userServiceImpl1\")\nprivate UserService userService;\n```\n\n## @Resource注解的使用\n@Resource默认通过byName注入，如果没有匹配则通过byType注入\n\n```java\n@Service\npublic class UserServiceImpl1 implements UserService\n\n@Service\npublic class UserServiceImpl2 implements UserService\n\n// 通过 @Resource 注入使用\n@Resource\nprivate UserService userService;\n```\n\n首先通过byName匹配，变量名userService无法匹配IOC容器中任何一个id（这里指的userServiceImpl1和userServiceImpl2），于是通过byType匹配，发现类型UserService的实现类有两个，仍然无法确定，于是报错。\n\n@Resource还有两个重要的属性：name和type，用来显式指定byName和byType方式注入\n\n```java\n// 1. 默认方式：byName\n@Resource  \nprivate UserService userDao; \n\n// 2. 指定byName\n@Resource(name=\"userService\")  \nprivate UserService userService; \n\n// 3. 指定byType\n@Resource(type=UserService.class)  \nprivate UserService userService; \n\n// 4. 指定byName和byType\n@Resource(name=\"userService\",type=UserService.class)  \nprivate UserService userService; \n```\n\n1. 既没指定name属性，也没指定type属性：默认通过byName方式注入，如果byName匹配失败，则使用byType方式注入（也就是上面的那个例子）\n2. 指定name属性：通过byName方式注入，把变量名和IOC容器中的id去匹配，匹配失败则报错\n3. 指定type属性：通过byType方式注入，在IOC容器中匹配对应的类型，如果匹配不到或者匹配到多个则报错\n4. 同时指定name属性和type属性：在IOC容器中匹配，名字和类型同时匹配则成功，否则失败\n\n', NULL, NULL, '2024-06-27 16:53:44', '2024-06-27 17:09:14', 1);
INSERT INTO `doc_content` VALUES (77, 1, 147, '# linux 系统命令\n\n## 目录管理命令\n\n1. ls - 列出目录内容\n```\nls [选项] [目录]\n\n常用选项：\n-l：使用长格式列出文件信息。\n-a：显示所有文件，包括隐藏文件。\n-h：以人类可读的格式显示文件大小。\n-R：递归列出目录及其子目录中的内容。\n\n```\n\n2. cd - 更改当前工作目录\n```\ncd [目录]\n```\n\n3. pwd - 显示当前工作目录\n```\npwd\n```\n\n4. cp - 复制文件或目录\n```\ncp [选项] 源文件 目标文件\ncp [选项] 源文件... 目标目录\n\n常用选项：\n-r：递归复制目录及其内容。\n-i：在覆盖文件前提示确认。\n-u：仅在源文件比目标文件新或目标文件不存在时复制。\n```\n\n5. mv - 移动或重命名文件或目录\n```\nmv [选项] 源文件 目标文件\nmv [选项] 源文件... 目标目录\n\n常用选项：\n-i：在覆盖文件前提示确认。\n-u：仅在源文件比目标文件新或目标文件不存在时移动。\n```\n\n6. rm - 删除文件或目录\n```\nrm [选项] 文件...\n\n常用选项：\n-r：递归删除目录及其内容。\n-f：强制删除，不提示确认。\n-i：删除前逐个文件提示确认。\n```\n\n\n7. mkdir - 创建目录\n```\nmkdir [选项] 目录...\n\n常用选项：\n-p：递归创建目录，包括必要的父目录。\n```\n\n8. find - 查找文件或目录\n```\nfind [路径] [选项] [表达式]\n\n常用选项：\n-name：按名称查找文件。\n-type：按类型查找（f为文件，d为目录）。\n-size：按大小查找文件。\n-mtime：按修改时间查找文件。\n-exec：对查找到的文件执行指定的命令。\n\n示例：\nfind /home -name \"*.txt\"\nfind /var/log -type f -size +1M\nfind /tmp -mtime -1\nfind / -type f -name \"*.log\" -exec rm -f {} \\;\n```\n\n9. touch - 创建空文件或更新文件的时间戳\n```\ntouch [选项] 文件...\n\n常用选项：\n-a：仅更新访问时间。\n-m：仅更新修改时间。\n```\n\n## 文件内容操作命令\n\n1. vi 和 vim \n```\n- 命令模式\n命令模式是 vi 和 vim 的默认模式。在此模式下，可以执行各种命令来导航、删除、复制、粘贴文本等。\n\n特点：\n导航：可以使用 h、j、k、l 键来移动光标。\n删除文本：例如，使用 x 删除当前字符，使用 dd 删除当前行。\n复制文本：例如，使用 yy 复制当前行。\n粘贴文本：例如，使用 p 粘贴文本。\n切换模式：可以通过按 i、a、o 等命令进入插入模式，或者按 : 进入底行模式。\n\n\n- 插入模式\n插入模式用于插入和编辑文本。进入插入模式后，所有键入的字符都会直接插入到文本中。\n\n特点：\n插入文本：可以在光标当前位置、光标后面、新行等位置插入文本。\n退出模式：按 Esc 键可以退出插入模式，返回命令模式。\n\n\n- 底行模式\n底行模式用于执行文件保存、退出、搜索、替换等命令。进入底行模式后，光标移动到编辑器底部，显示一个命令提示符。\n\n特点：\n文件操作：保存文件、退出编辑器等。\n搜索文本：在文件中搜索特定文本。\n替换文本：在文件中替换特定文本。\n执行命令：按 Enter 键执行命令。\n```\n\n2. cat - 连接并显示文件内容\n```\ncat [选项] 文件...\n\n常用选项：\n-n：显示行号。\n-b：对非空输出行编号。\n-s：压缩连续的空行。\n-E：在每行末尾显示 $。\n```\n\n3. more - 分页显示文件内容\n```\nmore [选项] 文件...\n\n常用选项：\n-d：显示\"Press space to continue...\"提示。\n-num：指定每页显示的行数 （使用时数字代替num）。\n-s：压缩连续的空行。\n```\n\n4. less - 分页显示文件内容（功能比more更强大）\n```\nless [选项] 文件...\n\n常用选项：\n-N：显示行号。\n-I：忽略搜索时的大小写。\n-S：禁止自动换行。\n```\n\n5. head - 显示文件的前几行\n```\nhead [选项] 文件...\n\n常用选项：\n-n：指定显示的行数。\n-c：指定显示的字节数。\n```\n\n6. tail - 显示文件的后几行\n```\ntail [选项] 文件...\n\n常用选项：\n-n：指定显示的行数。\n-c：指定显示的字节数。\n-f：实时显示文件内容，常用于查看日志文件。\n-r：倒序显示文件内容。\n```\n\n7. grep - 在文件中搜索文本\n```\ngrep [选项] 模式 文件...\n\n常用选项：\n-i：忽略大小写。\n-r：递归搜索目录。\n-v：显示不匹配的行。\n-n：显示行号。\n-l：只显示包含匹配的文件名。\n-c：显示匹配的行数。\n-H：显示匹配的文件名。\n-o：只输出匹配部分。\n\n示例：\ngrep \"search_term\" file1.txt\ngrep -i \"search_term\" file1.txt\ngrep -r \"search_term\" /var/log/\ngrep -v \"search_term\" file1.txt\ngrep -n \"search_term\" file1.txt\ngrep -l \"search_term\" *\n```\n8. wc - 统计文件的行数、字数和字符数\n```\nwc [选项] 文件...\n\n常用选项：\n-l：显示行数。\n-w：显示字数。\n-c：显示字节数。\n-m：显示字符数。\n```\n\n## 文件权限管理命令\n\n1. chmod - 修改文件或目录的权限\n```\nchmod [who][operation][permission] file\nchmod [mode] file\n\n其中： \nwho：权限修改对象，u（用户），g（组），o（其他），a（所有）。\noperation：+（添加权限），-（移除权限），=（设置权限）。\npermission：r（读），w（写），x（执行）。\n\nmode 是一个三位的八进制数，每位代表不同的权限：\n读（r）：4\n写（w）：2\n执行（x）：1\n\n示例：\nchmod u+x file.txt     # 为文件所有者添加执行权限\nchmod g-w file.txt     # 移除组的写权限\nchmod o=r file.txt     # 设置其他用户只读权限\nchmod a+r file.txt     # 为所有用户添加读权限\n```\n2. chown - 修改文件的所有者和组\n```\nchown [选项] [新所有者][:新组] 文件\n\nchown user file.txt            # 修改文件所有者为 user\nchown user:group file.txt      # 修改文件所有者为 user，组为 group\nchown :group file.txt          # 仅修改文件所属组为 group\nchown -R user:group /path/to/dir # 递归修改目录及其子文件夹和文件的所有者和组\n```\n\n## 进程管理命令\n\n1. ps：显示当前运行的进程\n```\nps [选项]\n\n常用选项：\n-e 或 -A：显示所有进程。\n-f：显示完整格式的输出，包括PPID、C、STIME、TTY、TIME、CMD。\n-u 用户：显示特定用户的进程。\n-p PID：显示指定PID的进程。\n\n示例：\nps -ef   # 显示所有进程的完整格式\nps -aux  # 显示所有进程，包括详细信息\n```\n\n2. top：实时显示系统资源使用情况\n```\ntop\n\n常用操作：\nq：退出 top。\nh：显示帮助。\nk：终止一个进程。\nr：重新调整进程的优先级（renice）。\n```\n\n3. kill：终止进程\n```\nkill [选项] PID\n\n常用选项：\n-9：强制终止进程。\n-15：发送TERM信号（默认），请求进程终止。\n```\n\n## 压缩和归档命令\n\n1. tar：创建归档文件并支持压缩\n```\ntar [选项] [归档文件] [文件或目录]\n\n常用选项：\n-c：创建新的归档文件。\n-x：解压归档文件。\n-t：列出归档文件内容。\n-v：显示详细信息。\n-f：指定归档文件名。\n-z：使用 gzip 压缩或解压缩。\n-j：使用 bzip2 压缩或解压缩。\n-J：使用 xz 压缩或解压缩。\n-C：指定解压到的目录。\n\n示例：\n# 创建 tar 归档文件\ntar -cvf archive.tar file1 file2 directory/\n\n# 创建 gzip 压缩的 tar 归档文件\ntar -czvf archive.tar.gz file1 file2 directory/\n \n# 创建 bzip2 压缩的 tar 归档文件\ntar -cjvf archive.tar.bz2 file1 file2 directory/\n \n# 创建 xz 压缩的 tar 归档文件\ntar -cJvf archive.tar.xz file1 file2 directory/\n \n# 解压 tar 归档文件\ntar -xvf archive.tar\n \n# 解压 gzip 压缩的 tar 归档文件\ntar -xzvf archive.tar.gz\n \n# 解压 bzip2 压缩的 tar 归档文件\ntar -xjvf archive.tar.bz2\n \n# 解压 xz 压缩的 tar 归档文件\ntar -xJvf archive.tar.xz\n \n# 列出 tar 归档文件内容\ntar -tvf archive.tar\n \n# 解压到指定目录\ntar -xvf archive.tar -C /path/to/directory\n```\n\n2. gzip：文件压缩工具\n```\ngzip [选项] [文件]\n\n常用选项：\n-d：解压文件。\n-k：保留原文件。\n-r：递归压缩目录中的所有文件。\n\n示例：\n# 压缩文件\ngzip file\n\n# 解压文件\ngzip -d file.gz\n \n# 压缩并保留原文件\ngzip -k file\n \n# 递归压缩目录中的所有文件\ngzip -r directory/\n```\n3. bzip2：高效文件压缩工具\n```\nbzip2 [选项] [文件]\n\n常用选项：\n-d：解压文件。\n-k：保留原文件。\n```\n\n4. xz：高效文件压缩工具\n```\nxz [选项] [文件]\n\n常用选项：\n-d：解压文件。\n-k：保留原文件。\n-z：压缩文件（默认行为）。\n-T：指定使用的线程数。\n```\n\n5. zip：创建压缩归档文件\n```\nzip [选项] [归档文件] [文件或目录]\n\n常用选项：\n-r：递归压缩目录。\n-d：从归档文件中删除文件。\n-u：更新归档文件中的文件。\n-m：压缩后删除原文件。\n\n示例：\n# 创建 zip 归档文件\nzip archive.zip file1 file2 directory/\n \n# 递归压缩目录\nzip -r archive.zip directory/\n \n# 从归档文件中删除文件\nzip -d archive.zip file1\n \n# 更新归档文件中的文件\nzip -u archive.zip file1\n \n# 压缩后删除原文件\nzip -m archive.zip file1\n```\n6. unzip：解压缩 zip 归档文件\n```\nunzip [选项] [归档文件]\n\n常用选项：\n-d：指定解压到的目录。\n-l：列出归档文件内容。\n-o：覆盖已存在的文件。\n\n示例：\n# 解压 zip 归档文件\nunzip archive.zip\n \n# 解压到指定目录\nunzip archive.zip -d /path/to/directory\n \n# 列出 zip 归档文件内容\nunzip -l archive.zip\n \n# 覆盖已存在的文件\nunzip -o archive.zip\n```\n\n## 用户管理命令\n\n1. who：显示当前登录的用户\n```\nwho [选项]\n\n常用选项：\n-H：显示列标题。\n-q：显示登录用户的数量和名称。\n-b：显示系统最后的启动时间。\n```\n\n2. useradd：添加新用户\n```\nuseradd [选项] 用户名\n\n常用选项：\n-m：创建用户的主目录。\n-d 目录：指定用户的主目录。\n-s shell：指定用户的登录 shell。\n-g 组：指定用户的主组。\n-G 组1,组2,...：指定用户的附加组。\n-u 用户ID：指定用户ID。\n-c \"描述\"：添加用户描述信息。\n```\n\n3. usermod：修改用户信息\n```\nusermod [选项] 用户名\n\n常用选项：\n-l 新用户名：更改用户名。\n-d 新目录：更改用户主目录。\n-m：移动用户主目录到新位置。\n-s 新shell：更改用户的登录 shell。\n-g 新组：更改用户的主组。\n-G 新组1,新组2,...：更改用户的附加组。\n-u 新用户ID：更改用户ID。\n-c \"新描述\"：更改用户描述信息。\n```\n4. userdel：删除用户\n```\nuserdel [选项] 用户名\n\n常用选项：\n-r：删除用户的主目录和邮件池。\n```\n\n5. groupadd：添加新组\n```\ngroupadd [选项] 组名\n\n常用选项：\n-g 组ID：指定组ID。\n```\n\n6. groupdel：删除组\n```\ngroupdel 组名\n```\n\n7. passwd：修改用户密码\n```\npasswd [用户名]\n```\n\n8. su：切换用户\n```\nsu [选项] [用户名]\n\n常用选项：\n-：切换到用户并加载该用户的环境变量。\n```\n\n9. sudo：以超级用户权限执行命令\n```\nsudo [选项] 命令\n\n常用选项：\n-u 用户：以指定用户的身份执行命令。\n-s：启动交互式 shell。\n```\n\n10. id：显示用户和组信息\n```\nid [选项] [用户名]\n\n常用选项：\n-u：显示用户ID。\n-g：显示组ID。\n-G：显示所有组ID。\n-n：显示名称而不是数字ID。\n```\n\n## 网络管理命令\n\n1. ifconfig：配置网络接口\n```\nifconfig [接口] [选项]\n\n常用选项：\nup：启动网络接口。\ndown：关闭网络接口。\ninet 地址：设置接口的IP地址。\nnetmask 地址：设置接口的子网掩码。\nbroadcast 地址：设置接口的广播地址。\n```\n\n2. ip：显示和操作路由、设备、策略路由等\n```\nip [选项] 对象 命令\n\n常用对象和命令：\naddr：管理IP地址。\n    show：显示地址。\n    add：添加地址。\n    del：删除地址。\n\nlink：管理网络接口。\n    show：显示接口。\n    set：设置接口状态（up/down）。\n\nroute：管理路由表。\n    show：显示路由。\n    add：添加路由。\n    del：删除路由。\n\n示例：\n# 显示所有网络接口的信息\nip addr show\n \n# 显示接口 eth0 的信息\nip addr show eth0\n \n# 启动网络接口 eth0\nip link set eth0 up\n \n# 关闭网络接口 eth0\nip link set eth0 down\n \n# 添加IP地址到接口 eth0\nip addr add 192.168.1.100/24 dev eth0\n \n# 删除接口 eth0 上的IP地址\nip addr del 192.168.1.100/24 dev eth0\n \n# 显示路由表\nip route show\n \n# 添加默认网关\nip route add default via 192.168.1.1\n \n# 删除默认网关\nip route del default\n```\n\n3. ping：检查网络连通性\n```\nping [选项] 目标\n\n常用选项：\n-c 次数：指定发送的ICMP请求数。\n-i 间隔：指定每次请求间的间隔时间。\n-s 大小：指定ICMP数据包的大小。\n```\n\n4. traceroute：跟踪路由路径\n```\ntraceroute [选项] 目标\n\n说明：\ntraceroute 命令用于显示数据包到目标主机的路径\n\n常用选项：\n-n：使用IP地址而非主机名。\n-m 最大跳数：设置最大跳数。\n```\n\n5. netstat：显示网络连接、路由表、接口状态等\n```\nnetstat [选项]\n\n常用选项：\n-a：显示所有连接和监听端口。\n-t：显示TCP连接。\n-u：显示UDP连接。\n-n：以数字形式显示地址和端口。\n-r：显示路由表。\n-i：显示网络接口信息。\n```\n\n## 磁盘管理命令\n1. df：显示文件系统的磁盘空间使用情况\n```\ndf [选项] [文件]\n\n常用选项：\n-h：以人类可读的格式显示磁盘使用情况。\n-T：显示文件系统类型。\n```\n\n2. fdisk：磁盘分区管理\n```\nfdisk [选项] 设备\n\n常用选项：\n-l：列出所有磁盘及其分区信息。\n-u：显示分区大小以扇区为单位。\n```\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-06-27 17:11:47', '2024-06-28 15:49:00', 1);
INSERT INTO `doc_content` VALUES (78, 1, 151, '# RocketMQ面试题（一）\n\n1. RocketMQ角色和组成\n\n|角色|作用|\n|----|----|\n|Nameserver|无状态，动态列表；这也是和zookeeper的重要区别之一。zookeeper是有状态的。|\n|Producer|消息生产者，负责发消息到Broker。|\n|Broker|就是MQ本身，负责收发消息、持久化消息等。|\n|Consumer|消息消费者，负责从Broker上拉取消息进行消费，消费完进行ack。|\n\n2. RocketMQ Broker中的消息被消费后会立即删除吗？\n不会，每条消息都会持久化到CommitLog中，每个Consumer连接到Broker后会维持消费进度信息，当有消息消费后只是当前Consumer的消费进度（CommitLog的offset）更新了。\n\n- 那么消息会堆积吗？什么时候清理过期消息？\n会指定时间删除不再使用的CommitLog文件\n\n3. ', NULL, NULL, '2024-06-28 16:01:50', '2024-06-28 17:24:05', 1);
INSERT INTO `doc_content` VALUES (79, 1, 153, '# Spring Boot 面试题\n\n## Spring Boot 中自动配置原理是什么？\n\nSpring Boot的自动配置原理基于@SpringBootApplication注解，它是@Configuration、@EnableAutoConfiguration和@ComponentScan的组合。自动配置通过@EnableAutoConfiguration注解实现，这个注解利用Spring Factories机制，从classpath中的META-INF/spring.factories文件加载AutoConfiguration类。\n\n```java\n@SpringBootApplication\npublic class MyApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(MyApplication.class, args);\n    }\n}\n```\n\n## Spring 和 Spring boot 的区别\n\nSpring是一个轻量级的控制反转（IOC）和面向切面编程（AOP）的容器框架，解决了企业应用开发的复杂性。Spring框架的核心思想是依赖注入，它使得应用程序的组件可以更加松散地耦合在一起，提高了代码的可重用性和可测试性。Spring框架还提供了丰富的功能，如数据访问、事务管理、安全性等，使得开发者可以更加专注于业务逻辑的实现。\n\nSpring Boot 则是简化Spring应用的初始搭建以及开发过程。Spring Boot的核心理念是“约定优于配置”，它通过一系列默认配置简化了Spring应用的开发流程。\n\n- 主要区别\n  - 配置方式\nSpring框架的配置相对复杂，涉及XML、JavaConfig等多种方式。开发者需要手动配置各种Bean、数据源、事务管理器等组件。Spring框架还需要开发者手动管理依赖关系，以确保组件之间的正确协作。\nSpring Boot 通过引入自动配置机制，极大地简化了配置过程。\n\n  - 开发效率\n  Spring框架的配置复杂性，开发者在搭建和开发Spring应用时需要花费较多的时间和精力。\n  Spring Boot通过简化配置和提供默认配置，使得开发者可以更加专注于业务逻辑的实现。Spring Boot还集成了许多常用的工具和库。\n\n## Spring-IOC、DI、AOP概念\n\n- IOC（控制反转）\n  - IOC 是 Spring 框架的核心原则之一。传统的编程模型中，对象的创建、生命周期管理和依赖关系的管理都由开发人员手动完成。而在 Spring 中，IOC 的思想是将这些职责交给容器来完成。也就是说，当一个对象需要依赖其他对象时，它不会自己创建这些依赖的对象，而是通过容器来获取依赖的实例。这样做的好处是降低了对象之间的耦合性，使得应用更加灵活，易于维护和扩展。\n\n- DI（依赖注入）\n  - DI 是 IOC 的一种实现方式。在 Spring 中，使用 DI 可以将对象之间的依赖关系交给容器来管理。依赖注入分为三种常见的方式：构造函数注入、属性注入和set方法注入。通过 DI，开发人员不需要手动创建对象之间的依赖关系，而是定义好对象的依赖关系，在需要使用对象时，容器会自动将相关的依赖注入到对象中。这样可以提高代码的可读性、可维护性和可测试性。\n    - 属性注入： @Autowired、@Resource 以及 @Inject 等注解注入。    \n    - 构造函数注入： 类中有多个构造方法，需要添加上 @Autowired 来明确指定使用哪个构造方法\n    - set方法注入：不建议\n```java\n// 构造函数注入\n@Service\npublic class AService {\n    BService bService;\n    @Autowired\n    public AService(BService bService) {\n        this.bService = bService;\n    }\n}\n\n// set方法注入\n@Service\npublic class BService {\n    AService aService;\n\n    @Autowired\n    public void setaService(AService aService) {\n        this.aService = aService;\n    }\n}\n```\n\n- AOP（面向切面编程）\n  - AOP 是一种在不修改原始代码的情况下，动态地添加功能的编程范式。在传统的编程模型中，系统的功能通常分散在各个业务逻辑中，导致代码的重复和难以维护。而利用 AOP，可以将这些横切关注点（如日志记录、事务管理等）独立出来，以切面的方式进行管理。在 Spring 中，AOP 提供了一种将切面与应用程序结合的机制，开发人员可以通过声明的方式将切面织入到目标对象的方法中，实现对目标方法的增强功能。\n\n## BeanFactory 和 ApplicationContext有什么区别？\n\nBeanFactory： 是spring最底层的接口，包含各种Bean的定义和Bean的管理。\nApplicationContext： 作为BeanFactory的派生，除了有BeanFactory的功能以外，还提供了更多的功能。\n\n**区别：**\n- BeanFactroy采用的是延迟加载形式来注入Bean的，使用到bean才会加载。ApplicationContext一次性加载所有bean。\n- BeanFactory需要手动注册，而ApplicationContext则是自动注册。\n- BeanFactory不支持国际化，ApplicationContext支持国际化(实现MessageSource接口)。\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-01 14:17:29', '2024-07-15 20:31:45', 1);
INSERT INTO `doc_content` VALUES (80, 1, 156, '# Mybatis 面试题（一）\n\n## 1. Mybatis 启动流程\n![Mybatis-1.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-13_10-52-29_8f87e2_Mybatis-1.png)\n1. **加载配置文件：**\nMyBatis 的启动首先是从加载 MyBatis 的配置文件开始的，通常是 mybatis-config.xml。\n这个配置文件包含了 MyBatis 的全局配置信息，如环境配置、数据库连接信息、事务管理器等。\n\n2. **创建 SqlSessionFactory：**\n使用 SqlSessionFactoryBuilder 类来读取 mybatis-config.xml 配置文件，并创建一个 SqlSessionFactory 实例。\nSqlSessionFactory 是 MyBatis 的核心接口，用于创建 SqlSession。\n\n3. **创建 SqlSession：**\n通过 SqlSessionFactory 实例创建 SqlSession 对象。\nSqlSession 提供了执行 SQL、获取映射器（Mapper）等方法。\n\n4. **获取 Mapper：**\n使用 SqlSession 的 getMapper 方法获取 Mapper 接口的实例。\nMapper 接口通常包含了与数据库交互的方法，这些方法对应着 SQL 语句。\n\n5. **执行操作：**\n通过 Mapper 接口实例调用方法来执行 SQL 语句。\nMyBatis 会根据方法的注解或 XML 映射文件中的配置，找到对应的 SQL 语句并执行。\n\n6. **关闭 SqlSession：**\n操作完成后，需要关闭 SqlSession 以释放资源。\n\n\n## 2. MyBatis 执行流程\n\n1. **接收请求：**\n客户端发送请求，通常是调用 Mapper 接口的方法。\n\n2. **查找 SQL 语句：**\nMyBatis 根据 Mapper 接口方法的签名（如方法名和参数类型）查找对应的 SQL 语句。\n这个 SQL 语句可以是注解在 Mapper 接口方法上的，也可以是 XML 映射文件中的。\n\n3. **参数处理：**\n如果 SQL 语句需要参数，MyBatis 会将方法的参数转换为 JDBC 能够理解的类型，并设置到 SQL 语句中。\n\n4. **执行 SQL：**\nMyBatis 使用 JDBC 执行 SQL 语句，并将结果集（ResultSet）返回。\n\n5. **结果映射：**\nMyBatis 将结果集映射为 Java 对象。这通常是通过在 XML 映射文件中定义 <resultMap> 来完成的。\n如果 SQL 语句返回的是单条记录，MyBatis 会将结果映射为一个 Java 对象；如果返回的是多条记录，MyBatis 会将结果映射为一个 Java 对象列表。\n\n6. **返回结果：**\nMyBatis 将映射后的 Java 对象返回给客户端。\n\n7. **关闭连接：**\n在完成所有操作后，MyBatis 会关闭与数据库的连接。\n\n\n## 3. Mybatis如何找到对应xml文件？\n@MapperScan注解扫描mapper接口\nmybatis.mapper-locations: 在配置文件中备注xml文件位置\n\n## 4. Mybatis缓存\n\n1. 一级缓存 SqlSession级别\n2. 二级缓存 Mapper级别\n3. 三级自定义缓存\n\n## 5. #{}和${}的区别是什么\n${}是字符串替换，#{}是预处理；\nMybatis在处理时，就是把{}直接替换成变量的值。而Mybatis在处理#{}时，会对sql语句进行预处理，将sql中的#{}替换为？号，调用PreparedStatement的set方法来赋值；\n使用#{}可以有效的防止SQL注入，提高系统安全性。\n\n## 6. Mybatis是如何进行分页的？分页插件的原理是什么？\nMybatis使用RowBounds对象进行分页，它是针对ResultSet结果集执行的**内存分页**，而非物理分页。可以在sql内直接书写带有物理分页的参数来完成物理分页功能，也可以使用分页插件来完成物理分页。\n\n## 7. Mybatis动态sql有什么用？执行原理？有哪些动态sql？\nMybatis动态sql可以在Xml映射文件内，以标签的形式编写动态sql，执行原理是根据表达式的值 完成逻辑判断 并动态拼接sql的功能。\nMybatis提供了9种动态sql标签：trim | where | set | foreach | if | choose | when | otherwise | bind。\nMybatis全标签\n![mybatis-2.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-13_19-39-14_80d0b3_mybatis-2.png)\n\n\n## 8. 为什么说Mybatis是半自动ORM映射工具？它与全自动的区别在哪里？\nHibernate属于全自动ORM映射工具，使用Hibernate查询关联对象或者关联集合对象时，可以根据对象关系模型直接获取，所以它是全自动的。\n而Mybatis在查询关联对象或关联集合对象时，需要手动编写sql来完成，所以，称之为半自动ORM映射工具。\n\n## 9. JDBC编程有哪些不足之处，MyBatis是如何解决这些问题的？\n1、数据库连接创建、释放频繁造成系统资源浪费从而影响系统性能，如果使用数据库链接池可解决此问题。\n解决：在mybatis-config.xml中配置数据链接池，使用连接池管理数据库连接。\n\n2、Sql语句在代码中硬编码，造成代码不易维护，实际应用sql变化的可能较大，sql变动需要改变java代码。\n解决：将Sql语句配置在XXXXmapper.xml文件中与java代码分离。\n\n3、使用PreparedStatement向占有位符号传参数存在硬编码，因为sql语句的where条件不一定，可能多也可能少，修改sql还要修改代码，系统不易维护。\n解决： Mybatis自动将java对象映射至sql语句。\n\n4、对结果集解析存在硬编码（查询列名），sql变化导致解析代码变化，系统不易维护，如果能将数据库记录封装成pojo对象解析比较方便。\n解决：Mybatis自动将sql执行结果映射至java对象。\n\n\n## 10. MyBatis接口绑定的几种方式\n1. 使用注解，在接口的方法上面添加@Select@Update等注解，里面写上对应的SQL语句进行SQL语句的绑定。\n2. 通过映射文件xml方式进行绑定，指定xml映射文件中的namespace对应的接口的全路径名\n\n## 11. Mybatis优缺点\n\n与传统的数据库访问技术相比，ORM有以下优点：\n- 基于SQL语句编程，相当灵活，不会对应用程序或者数据库的现有设计造成任何影响，SQL写在XML里，解除sql与程序代码的耦合，便于统一管理；提供XML标签，支持编写动态SQL语句，并可重用\n- 与JDBC相比，减少了50%以上的代码量，消除了JDBC大量冗余的代码，不需要手动开关连接\n- 很好的与各种数据库兼容（因为MyBatis使用JDBC来连接数据库，所以只要JDBC支持的数据库MyBatis都支持）\n- 提供映射标签，支持对象与数据库的ORM字段关系映射；提供对象关系映射标签，支持对象关系组件维护\n- 能够与Spring很好的集成\n\n缺点\n- SQL语句的编写工作量较大，尤其当字段多、关联表多时，对开发人员编写SQL语句的功底有一定要求\n- SQL语句依赖于数据库，导致数据库移植性差，不能随意更换数据库\n\n## 12. 为什么需要预编译\n\n1. 定义：\nSQL 预编译指的是数据库驱动在发送 SQL 语句和参数给 DBMS 之前对 SQL 语句进行编译，这样 DBMS 执行 SQL 时，就不需要重新编译。\n\n2. 为什么需要预编译\nJDBC 中使用对象 PreparedStatement 来抽象预编译语句，使用预编译。预编译阶段可以优化 SQL 的执行。预编译之后的 SQL 多数情况下可以直接执行，DBMS 不需要再次编译，越复杂的SQL，编译的复杂度将越大，预编译阶段可以合并多次操作为一个操作。同时预编译语句对象可以重复利用。把一个 SQL 预编译后产生的 PreparedStatement 对象缓存下来，下次对于同一个SQL，可以直接使用这个缓存的 PreparedState 对象。Mybatis默认情况下，将对所有的 SQL 进行预编译。\n\n## 13. Mybatis都有哪些Executor执行器？它们之间的区别是什么？\n- SimpleExecutor是最简单的执行器，根据对应的sql直接执行，执行完毕即关闭；\n- BatchExecutor执行器，通过批量操作来优化性能。通常需要注意的是批量更新操作，由于内部有缓存的实现，使用完成后记得调用flushStatements来清除缓存。\n- ReuseExecutor 可重用的执行器，重用的对象是Statement，也就是说该执行器会缓存同一个sql的Statement，省去Statement的重新创建，优化性能。内部的实现是通过一个HashMap来维护Statement对象的。由于当前Map只在该session中有效，所以使用完成后记得调用flushStatements来清除Map。\n\n## 14. Mybatis中如何指定使用哪一种Executor执行器？\n\n- 在Mybatis配置文件中，在设置（settings）可以指定默认的ExecutorType执行器类型\n```xml\n<configuration>\n  <settings>\n    <setting name=\"defaultExecutorType\" value=\"SIMPLE\"/>\n  </settings>\n  <!-- 其他配置项 -->\n</configuration>\n```\n- DefaultSqlSessionFactory的创建SqlSession的方法传递ExecutorType类型参数\n```java\nSqlSession sqlSession = sqlSessionFactory.openSession(ExecutorType.SIMPLE);\n```\n\n配置默认的执行器。SIMPLE 就是普通的执行器；REUSE 执行器会重用预处理语句（prepared statements）； BATCH 执行器将重用语句并执行批量更新。\n\n## 15. 使用MyBatis的mapper接口调用时有哪些要求？\n\n- Mapper接口方法名和mapper.xml中定义的每个sql的id相同。\n- Mapper接口方法的输入参数类型和mapper.xml中定义的每个sql 的parameterType的类型相同。\n- Mapper接口方法的输出参数类型和mapper.xml中定义的每个sql的resultType的类型相同。\n- Mapper.xml文件中的namespace即是mapper接口的类路径。\n\n\n## 16. Mybatis是如何进行分页的\n\n- 使用 limit，需要自己处理分页逻辑\n- 拦截StatementHandler\n- 使用PageHelper插件\n\n## 17. MyBatis实现一对一，一对多有几种方式，怎么操作的？\n有联合查询和嵌套查询。\n- 联合查询是几个表联合查询，只查询一次，通过在resultMap里面的association，collection节点配置一对一，一对多的类就可以完成 \n- 嵌套查询是先查一个表，根据这个表里面的结果的外键id，去再另外一个表里面查询数据，也是通过配置association，collection，但另外一个表的查询通过select节点配置。\n\n## 18. Dao接口里面方法能重载吗？\n能在Dao层重载，xml映射文件中是不能重载\n重载就是方法名相同，参数类型和参数个数不同\nxml文件中mapper属性，如果mapper属性下面配置了namesapce值，那么你执行的增，删，改和查询所使用的id就是唯一的，不能重复\n一般情况下我们是把Dao接口的方法名作为id，如果你在xml映射文件中使用了重载，那么我们只会使用相同的id，所以就会报错\n\n\n', NULL, NULL, '2024-07-03 15:34:53', '2024-07-13 21:21:02', 1);
INSERT INTO `doc_content` VALUES (81, 1, 157, '# Mybatis 三级缓存\n\n缓存为了减少Mybatis与SQL数据库的I/O交互, 提升查询效率。\n\n## 一级缓存 SqlSession级别\n\nMybaits 中一级缓存也就做本地缓存，一级缓存是在会话也就是SqlSession层面实现的，一级缓存的作用范围是在同一个SqlSession中,不同的SqlSession及时查询相同的数据也不会走缓存。\n\n### 1. 如何开启缓存\n一级缓存是默认开启的， 需要开启事务。不加事务每次查询都会创建SqlSession。\n- 只需要@EnableTransactionManagement和@Transactional两个注解即可开启事务\n  - @EnableTransactionManagement 添加在启动类上\n  - Service 上添加 @Transactional(rollbackFor = RuntimeException.class)\n\n### 2. 什么时候清除缓存\n- 当执行增删改方法时会清除缓存。\n- MyBatis全局配置属性localCacheScope配置为**STATEMENT**时，那么完成一次查询就会清除缓存。\n  - 配置参数localCacheScope：用于控制一级缓存的级别，该参数的取值为SESSION、STATEMENT。\n**SESSION：** 缓存对整个SqlSession有效，只有执行DML语句（更新语句）时，缓存才会被清除。\n**STATEMENT：** 缓存仅对当前执行的语句有效，当语句执行完毕后，缓存就会被清空。\n- 是否配置了flushCache=true属性，如果配置了则会清除一级缓存。\n\n### 3. 什么时候缓存失效\n- SqlSession 需要开启事务才会生效。否则每次查询都坏创建一个新的SqlSession\n- 不同的SqlSession 对应不同的缓存\n- 同一个 SqlSession 查询条件不同 也会不走缓存\n- 手动清空缓存,调用SqlSession clearCache()方法\n\n### 4. 存在的问题\n在同一个SqlSession中 两次相同条件查询中，第一次查询后 然后手动修改表数据或者另一个SqlSession对象修改了数据库或者分布式情况下数据发生了修改 那么第二次查询是直接走缓存，查询结果依旧相同，会存在数据不一致问题。\n\n## 二级缓存 Mapper级别\nMybatis 二级缓存是mapper级别的 需要手动开启，他的作用范围更广也就是mapper文件的一个命名空间（namespace）中。\n实现二级缓存的时候，MyBatis要求返回的POJO必须是可序列化的\n\n### 1. 开启二级缓存\n\n\n## 三级缓存 全局缓存\n三级缓存是全局缓存，对所有的mapper都有效。MyBatis并未直接提供接口支持全局缓存，但是可以通过整合Ehcache，Redis等工具来实现。\n\n\n## 总结\n通过MyBatis的三级缓存，可以大大提高我们对数据库的查询效率，但是也需要注意，缓存也可能会导致脏读、幻读等问题，这些都需要在实际开发中去考虑和权衡。\n\n\n\n\n\n', NULL, NULL, '2024-07-03 17:37:11', '2024-07-05 10:16:30', 1);
INSERT INTO `doc_content` VALUES (82, 1, 160, '# WebSocket面试题（一）\n\n## 1. WebSocket 协议和 HTTP 协议区别\n\n- 连接方式：WebSocket 提供持久的连接，通过握手过程建立连接后保持打开状态，而 HTTP 是无状态的，每次请求都需要重新建立连接。\n- 数据格式：WebSocket 支持文本和二进制数据的传输，而 HTTP 主要是传输文本数据。\n- 数据传输方式：WebSocket 实现了全双工通信，客户端和服务器可以同时发送和接收数据，而 HTTP 是单向的，客户端发起请求，服务器响应数据。\n- 协议标识：WebSocket 使用 ws:// 或 wss:// 前缀标识，而 HTTP 使用 http:// 或 https://\n\n## 2. WebSocket 的优势和使用场景\n\n- 实时性：WebSocket 提供了低延迟的实时通信能力，能够在服务器端有新数据时立即推送给客户端。\n- 双向通信：WebSocket 支持客户端和服务器之间的双向通信，可以实现实时聊天、实时数据更新等场景。\n- 较低的网络开销：WebSocket 使用长连接，相对于频繁的短连接请求，减少了网络开销。\n- 更高的性能：由于减少了 HTTP 请求的开销，WebSocket 在性能上更高效。\n- 跨域支持：WebSocket 具备跨域通信的能力，可以跨域进行实时通信。\n\n## 3. WebSocket 的连接建立过程是怎样的？\n\n- 客户端发送 WebSocket 握手请求，请求头包含 Upgrade 和 Connection 字段，指定协议升级和建立连接。\n- 服务器收到握手请求后，验证请求头的字段，并返回握手响应，响应头包含 Upgrade 和 Connection 字段，以及一个随机的 Sec-WebSocket-Key 字段。\n- 客户端收到握手响应后，验证响应头的字段，并生成一个 Sec-WebSocket-Accept 值进行验证。\n- 验证通过后，WebSocket 连接建立成功，客户端和服务器可以开始进行实时通信。\n\n## 4. WebSocket 的事件有哪些？\n\n- open：当 WebSocket 连接成功建立时触发的事件。可以在此事件中执行初始化操作或向服务器发送初始数据。\n- message：当从服务器接收到新消息时触发的事件。可以在此事件中处理接收到的数据。\n- error：当出现连接错误时触发的事件。错误可能包括连接失败、数据传输错误等。可以在此事件中处理错误并采取适当的措施。\n- close：当 WebSocket 连接关闭时触发的事件。关闭可能是由服务器或客户端发起的，可以在此事件中执行清理操作或重新连接等操作。\n\n## 5. WebSocket 的性能如何优化？\n\n- 减少数据量：合理控制发送的数据量大小，避免不必要的数据传输。\n- 心跳机制：通过定时发送心跳消息，保持连接的活跃状态，防止连接被关闭。\n- 数据压缩：可以使用压缩算法对数据进行压缩，减少网络传输的数据量。\n- 服务器端优化：合理配置服务器端的连接数和资源管理，以支持更多的并发连接。\n\n## 6. WebSocket 和长轮询相比，各自有什么优缺点？\n\nWebSocket 的优点：\n- 实时性：WebSocket 建立一次连接后可以进行持久通信，实时性较高。\n- 双向通信：WebSocket 支持客户端和服务器之间的双向通信。\n- 较低的网络开销：WebSocket 使用长连接，减少了网络开销。\n\nWebSocket 的缺点：\n- 兼容性：部分老旧的浏览器可能不支持 WebSocket，需要进行兼容处理。\n- 服务器支持：服务器需要支持 WebSocket 协议和相关处理逻辑。\n\n长轮询的优点：\n- 兼容性：长轮询可以在所有支持 HTTP 的浏览器中使用。\n- 简单实现：相对于 WebSocket，长轮询的实现较为简单。\n\n长轮询的缺点：\n- 延迟较高：由于需要不断发起轮询请求，延迟相对较高。\n- 频繁的请求：长轮询需要频繁地发送请求，增加了服务器的负载。\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-06 17:18:51', '2024-07-06 17:43:40', 1);
INSERT INTO `doc_content` VALUES (83, 1, 161, '# MySQL索引\n\n## 1. 索引的几种类型或分类\n\n### 物理结构分类\n- 聚簇索引: 指索引的键值的逻辑顺序与表中相应行的物理顺序一致，即每张表只能有一个聚簇索引，也就是我们常说的主键索引；\n- 非聚簇索引: 的逻辑顺序则与数据行的物理顺序不一致。\n\n### 应用上分类\n- 普通索引：MySQL 中的基本索引类型，没有什么限制，允许在定义索引的列中插入重复值和空值，纯粹为了提高查询效率。通过 ALTER TABLE table_name ADD INDEX index_name (column) 创建；\n\n- 唯一索引：索引列中的值必须是唯一的，但是允许为空值。通过 ALTER TABLE table_name ADD UNIQUE index_name (column) 创建；\n\n- 主键索引：特殊的唯一索引，也成聚簇索引，不允许有空值，并由数据库帮我们自动创建；\n\n- 组合索引：组合表中多个字段创建的索引，遵守最左前缀匹配规则；\n\n- 全文索引：只支持 CHAR、VARCHAR、TEXT 类型字段上使用。\n\n## 2. 索引的优缺点\n\n优点:\n- 通过创建唯一性索引，可以保证数据库表中每一行数据的唯一性。\n- 可以大大加快数据的检索速度，这也是创建索引的最主要的原因。\n- 可以加速表和表之间的连接，特别是在实现数据的参考完整性方面特别有意义。\n- 在使用分组和排序子句进行数据检索时，同样可以显著减少查询中分组和排序的时间。\n- 通过使用索引，可以在查询的过程中，使用优化隐藏器，提高系统的性能。\n\n缺点：\n- 创建和维护索引需要耗费时间，这种时间随着数据量的增加而增加，这样就降低了数据的维护速度。\n- 索引需要占物理空间，除了数据表占数据空间之外，每一个索引还要占一定的物理空间。如果要建立聚簇索引，那么需要的空间就会更大。\n\n## 3. 索引设计原则\n- 选择唯一性索引；\n唯一性索引的值是唯一的，可以更快速的通过该索引来确定某条记录。\n\n- 为常作为查询条件的字段建立索引；\n如果某个字段经常用来做查询条件，那么该字段的查询速度会影响整个表的查询速度。因此，为这样的字段建立索引，可以提高整个表的查询速度。\n\n- 为经常需要排序、分组和联合操作的字段建立索引；\n经常需要 ORDER BY、GROUP BY、DISTINCT 和 UNION 等操作的字段，排序操作会浪费很多时间。如果为其建立索引，可以有效地避免排序操作。\n\n- 限制索引的数目；\n每个索引都需要占⽤用磁盘空间，索引越多，需要的磁盘空间就越大，修改表时，对索引的重构和更新很麻烦。\n\n- 小表不建议索引（如数量级在百万以内）；\n由于数据较小，查询花费的时间可能比遍历索引的时间还要短，索引可能不会产生优化效果。\n\n- 尽量使用数据量少的索引；\n如果索引的值很长，那么查询的速度会受到影响。此时尽量使用前缀索引。\n\n- 删除不再使用或者很少使用的索引。\n\n\n## 4. 索引的数据结构\n\n- Hash 索引底层就是 Hash 表，进行查询时调用 Hash 函数获取到相应的键值（对应地址），然后回表查询获得实际数据.\n\n- B+ 树索引底层实现原理是多路平衡查找树，对于每一次的查询都是从根节点出发，查询到叶子节点方可以获得所查键值，最后查询判断是否需要回表查询\n\n## 5. Hash 和 B+ 树索引的区别？\n\nHash\n- Hash 进行等值查询更快，但无法进行范围查询。因为经过 Hash 函数建立索引之后，索引的顺序与原顺序无法保持一致，故不能支持范围查询。同理，也不支持使用索引进行排序。\n- Hash 不支持模糊查询以及多列索引的最左前缀匹配,因为 Hash 函数的值不可预测，如 AA 和 AB 的算出的值没有相关性。\n- Hash 任何时候都避免不了回表（通过索引定位到对应页，然后再根据行的物理地址找到所需的数据行）查询数据.\n- 虽然在等值上查询效率高，但性能不稳定，因为当某个键值存在大量重复时，产生 Hash 碰撞，此时查询效率反而可能降低。\n\nB+ Tree\n- B+ 树本质是一棵查找树，自然支持范围查询和排序。\n- 在符合某些条件（聚簇索引、覆盖索引等）时候可以只通过索引完成查询，不需要回表。\n- 查询效率比较稳定，因为每次查询都是从根节点到叶子节点，且为树的高度。\n\n## 6. 为何使用 B+ 树而非 B 树做索引？\n在此之前，先来了解一下 B+ 树和 B 树的区别：\n- B 树非叶子结点和叶子结点都存储数据，因此查询数据时，时间复杂度最好为 O(1)，最坏为 O(log n)。而 B+ 树只在叶子结点存储数据，非叶子结点存储关键字，且不同非叶子结点的关键字可能重复，因此查询数据时，时间复杂度固定为 O(log n)。\n- B+ 树叶子结点之间用链表相互连接，因而只需扫描叶子结点的链表就可以完成一次遍历操作，B 树只能通过中序遍历。\n\n## 7. 索引会影响写入性能吗\n会\n索引确实会影响写入性能。 这是因为索引不仅存储数据表的记录位置信息，还需要在数据发生变化时进行维护。当进行INSERT、UPDATE或DELETE操作时，数据库除了要更新数据表中的记录外，还必须更新相应的索引信息，这增加了操作的复杂性和时间成本。特别是对于聚集索引，由于数据需要按照索引键值排序存储，所以在插入、更新或删除记录时，可能需要重新排序数据，进一步增加了写入操作的开销。‌\n为了减轻这种影响，可以采取一些策略，如延迟创建索引直到数据写入完成，或者选择合适的索引列以减少不必要的索引维护。此外，对于不经常变动的数据或少量数据，可以考虑不建立索引，以避免不必要的性能开销。‌\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-06 19:31:03', '2024-07-25 19:17:19', 1);
INSERT INTO `doc_content` VALUES (84, 1, 162, '# Java 设计模式\n\n## 1. 设计模式7大基本原则\n\n1. 单一职责原则\n一个类只应该负责一项职责\n\n2. 接口隔离原则\n一个类不应该依赖它不需要的接口，对另一个类的依赖应该建立在最少接口上\n\n3. 依赖倒置原则\n高层模块不应该依赖低层模块，二者都应该依赖其抽象（接口或抽象类），不要去依赖具体的子类\n\n4. 里式替换原则\n对于基类A实现的方法，其子类B.C等都可以完全替换A类来实现，但不影响原有的代码功能\n子类可以扩展父类的功能，但不能改变父类原有的功能\n\n5. 开放封闭原则\n一个类的模块和函数应该是对扩展开放、对修改封闭。用抽象构建框架，用实现扩展细节\n\n6. 最少知道原则\n一个对象应该对其他对象保持最少的了解；类与类关系越密切，耦合度越大\n\n7. 合成复用原则\n尽量采用合成/聚合的方式，而不是使用继承\n\n##  设计模式\n\n设计模式分为3大类\n- 1.创建型模式（5种）：单例模式、抽象工厂模式、原型模式、建造者模式、工厂模式。\n- 2.结构型模式（7种）：适配器模式、桥接模式、装饰器模式、组合模式、外观模式、享元模式、代理模式\n- 3.行为型模式（11种）：模板方法模式、命令模式、访问者模式、迭代器模式、观察者模式、中介模式、备忘录模式、解释器模式（interpreter模式）、状态模式、策略模式、责任链模式。\n\n\n\n1. **单例模式**\n单例（Singleton）模式：某个类只能生成一个实例，该类提供了一个全局访问点供外部获取该实例，其拓展是有限多例模式。\n这样的模式有几个好处：\n- 某些类创建比较频繁，对于一些大型的对象，这是一笔很大的系统开销。\n- 省去了new操作符，降低了系统内存的使用频率，减轻GC压力。\n- 有些类如交易所的核心交易引擎，控制着交易流程，如果该类可以创建多个的话，系统完全乱了。所以只有使用单例模式，才能保证核心交易服务器独立控制整个流程。\n\n优点：只有一个实例，节约了内存资源，提高了系统性能\n缺点：\n- 没有抽象层，不能扩展\n- 职责过重，违背了单一性原则\n\n2. **工厂模式**\n定义了个创建对象的抽象方法，由子类决定要实例化的类。工厂方法模式是将对象的实例化推迟到了子类\n\n3. **抽象工厂模式**\n抽象工厂模式（Abstract Factory Pattern）是围绕一个超级工厂创建其他工厂。该超级工厂又称为其他工厂的工厂。\n\n4. **原型模式**\n原型模式（Prototype Pattern）是用于创建重复的对象，同时又能保证性能。\n创建一个对象,然后再通过克隆的方式复制出多个相同的对象,这就是原型模式的设计思想。\n\n5. **建造者模式**\n需要创建出一个很复杂的对象，但是这个对象的创建有一个固定的步骤，并且每个步骤中会涉及到多个组件对象，这个时候就可以考虑使用建造者模式。\n\n6. **装饰器模式**\n装饰模式（Decorator）,动态地给一个对象添加一些额外的职责，就增加功能来说，装饰模式比生成子类更为灵活。\n优点：\n- 装饰类和被装饰类可以独立发展，不会相互耦合。\n- 装饰模式是继承的一个替代模式，装饰模式可以动态扩展一个实现类的功能。\n缺点：\n- 多层装饰比较复杂。\n使用场合：\n- 希望在无需修改代码的情况下即可使用对象，且希望在运行时为对象新增额外的行为。\n- 用继承来扩展对象行为的方案难以实现或者根本不可行。\n\n7. **代理模式**\n使用代理对象来代替对真实对象(real object)的访问，这样就可以在不修改原目标对象的前提下，提供额外的功能操作，扩展目标对象的功能。\n\n8. **模板方法模式**\n在一个抽象类中公开定义了执行它的模板方法，它的子类可以按需要重写方法实现，但调用将以抽象类中的定义来进行\n\n9. **观察者模式**\n定义了一种一对多的依赖关系，当一个对象的状态发生改变时，其所有依赖者都会收到通知并自动更新。\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-10 15:09:41', '2024-07-10 18:49:05', 1);
INSERT INTO `doc_content` VALUES (85, 1, 165, '# Java IO 面试题（一）\n\n## 1. Java 中有几种类型的流？\n\n1. 按照流的方向（输出输入都是站在程序所在内存的角度划分的）\n   - 输入流：只能从中读取数据【主要由InputStream和Reader作为基类】\n   - 输出流：只能向其写入数据【主要由outputStream和Writer作为基类】\n\n2. 按照流的操作颗粒度划分\n   - 字节流：以字节为单元，可操作任何数据【主要由InputStream和outPutStream作为基类】\n   - 字符流：以字符为单元，只能操作纯字符数据，比较方便【主要由Reader和Writer作为基类】\n\n3. 按照流的角色划分\n   - 节点流：可以从/向一个特定的IO设备（如磁盘，网络）读/写数据的流，也叫【低级流，主要由】\n   - 处理流：用于对一个已存在的流进行连接和封装，通过封装后的流来实现数据的读/写功能，也叫【高级流】\n\n\n## 2. Java IO 使用了什么设计模式\n单一职责原则（Single Responsibility Principle）： 在Java IO中，不同的类负责不同的I/O操作，如InputStream负责读取字节，OutputStream负责写入字节，这符合单一职责原则。\n\n装饰器模式（Decorator Pattern）： Java IO中的缓冲流（如BufferedReader和BufferedWriter）以及过滤流（如GZIPInputStream和GZIPOutputStream）采用了装饰器模式。这些类通过组合来增强I/O流的功能，而不是通过继承来扩展。\n```java\nBufferedReader br = new BufferedReader(new FileReader(\"file.txt\"));\n```\n\n策略模式（Strategy Pattern）： Java IO库中的Charset和CharsetEncoder/CharsetDecoder类采用了策略模式。它们允许你根据不同的字符编码策略来进行字符编码和解码。\n```java\nCharset utf8 = Charset.forName(\"UTF-8\");\nCharsetEncoder encoder = utf8.newEncoder();\n```\n\n## 3. Java NIO BIO AIO\n\nJava NIO ： 同步非阻塞，服务器实现模式为一个请求一个线程，即客户端发送的连接请求都会注册到多路复用器上，多路复用器轮询到连接有I/O请求时才启动一个线程进行处理。\n\nJava BIO ： 同步并阻塞，服务器实现模式为一个连接一个线程，即客户端有连接请求时服务器端就需要启动一个线程进行处理，如果这个连接不做任何事情会造成不必要的线程开销，当然可以通过线程池机制改善。\n\nJava AIO(NIO.2) ： 异步非阻塞，服务器实现模式为一个有效请求一个线程，客户端的I/O请求都是由OS先完成了再通知服务器应用去启动线程进行处理。\n\n\n## 4. BIO、NIO、AIO三者区别以及适用场景？\nBIO（Blocking I/O）：\n阻塞模型： BIO是基于阻塞模型的I/O操作，意味着当一个线程执行I/O操作时，它将一直阻塞，直到操作完成。\n同步性： 在BIO中，所有I/O操作都是同步的，一个线程对一个连接进行读或写，直到完成。\n适用性： 适用于连接数量较少且每个连接的数据交互频繁的情况，但在高并发环境下性能不佳。\n\nNIO（Non-blocking I/O）：\n非阻塞模型： NIO采用了非阻塞模型，允许一个线程管理多个通道（连接）。\n选择器（Selector）： NIO引入了选择器（Selector）的概念，通过选择器一个线程可以监听多个通道上的事件，如读就绪、写就绪等。\n缓冲区（Buffer）： NIO使用缓冲区来存储数据，可以提高I/O效率。\n适用性： 适用于需要处理大量连接且连接数较多，但每个连接的数据交互相对较少的情况，如Web服务器。\n\nAIO（Asynchronous I/O）：\n异步模型： AIO采用异步模型，允许一个线程在进行I/O操作时不被阻塞，当操作完成后会通知应用程序。\n回调机制： AIO使用回调机制来处理I/O操作完成的通知。\n适用性： 适用于需要处理大量连接且每个连接的数据交互较少，且希望充分利用CPU的多核性能的情况。\n\n总结各种I/O模型的适用场景：\nBIO适用于连接数较少，且每个连接的数据交互频繁的情况，但不适用于高并发环境。\nNIO适用于需要处理大量连接，但每个连接的数据交互相对较少的情况，具有更好的性能和资源利用率。\nAIO适用于需要处理大量连接，且每个连接的数据交互较少，同时希望充分利用CPU多核性能的情况。\n选择适当的I/O模型取决于应用程序的特性和需求，不同的模型提供了不同的性能和可伸缩性。\n\n## 5. 什么是 java序列化?\n序列化是一种处理对象流的机制。所谓对象流，就是流化对象的内容。流化后的对象可以读写，也可以在网络之间传输。序列化是为了解决对象流读写操作中引起的问题。\n\n## 6. 如何实现 java 序列化?\n实现序列化将需要实现序列化类Serializable, implements Serializable 只是为了标记对象可以序列化，然后使用输出流(如:File Output Stream)来构造一个 Object Output Stream(对象流)对象，然后，使用 Object Output Stream 对象的 write Object(Object obj)该方法可以将参数为 obj 对象写出(即保存其状态)，如果要恢复，则使用输入流。\n\n## 7. Filter流是什么?\nFilter Stream是IO流的主要功能，用于为存在的流量增加一些额外的功能，如向目标文件添加源文件中不存在的行数或复制性能。\n\n## 8. Filter流有哪些可用?\n在http://java.主要由四个可用的filter包组成 Stream。两个字节filter stream，两个字符filter stream. 分别是Filter Input Stream, Filter Output Stream, Filter Reader and Filter Writer.这些类别是抽象的，不能实例化。\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-12 16:48:34', '2024-07-14 14:31:19', 1);
INSERT INTO `doc_content` VALUES (86, 1, 167, '# Java 多线程（一）\n\n## 并发编程三要素是什么？\n原子性：一个操作是不可分割的，要么全部执行成功要么全部执行失败。\n可见性：一个线程对共享变量的值进行修改后，另一个线程能够立刻看到修改的值。（synchronized,volatile）\n有序性：程序执行的顺序按照代码的先后顺序执行。（处理器可能会对指令进行指令重排）\n\n## 并行、并发、串行的区别\n串行：串行在时间上不可能发生重叠，前一个任务没有执行结束，下一个任务就不会开始\n并行：并行在时间上是重叠的，两个任务在同一时刻互不干扰的同时执行\n并发：多个任务在同一个 CPU 核上，按细分的时间片轮流(交替)执行，同一时间点，只有一个任务执行，任务交替执行\n\n## 什么是线程和进程\n进程：程序的⼀次执⾏过程，是系统运⾏程序的基本单位。进程是动态的，系统运⾏⼀个程序即是⼀个进程从创建，运⾏到消亡的过程。\n线程：线程是进程划分成的更⼩的运⾏单位，进程中的一个执行任务，⼀个进程在其执⾏的过程中可以产⽣多个线程，在程序里独立执行。一个进程至少有一个线程，一个进程可以运行多个线程，多个线程可共享进程中的数据。\n\n## 对线程安全的理解\n当多个线程访问一个对象时，如果不用进行额外的同步控制或其他的协调操作，调用这个对象的行为都可以获得正确的结果，我们就说这个对象是线程安全的。\n\n在每个进程的内存空间中都会有一块特殊的公共区域，通常称为堆(内存)。进程内的所有线程都可以访问到该区域，这就是造成线程安全的潜在原因。\n\n## 如何保证线程安全\n- 使用安全类，比如 java.util.concurrent 下的类，使用原子类AtomicInteger\n- 使用JVM提供的自动锁 synchronized。\n- 使用JDK提供的手动锁 Lock。\n\n## 多线程状态切换\n\n![多线程状态切换.jpg](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_14-31-25_e4e3c2_多线程状态切换.jpg)\n\n**Java中线程的状态分为6种：**\n- 初始(NEW) ：新创建了一个线程对象，但还没有调用start()方法。\n- 运行(RUNNABLE) ：Java线程中将就绪（ready）和运行中（running）两种状态笼统的称为“运行”。线程对象创建后，其他线程(比如main线程）调用了该对象的start()方法。该状态的线程位于可运行线程池中，等待被线程调度选中，获取CPU的使用权，此时处于就绪状态（ready）。就绪状态的线程在获得CPU时间片后变为运行中状态（running）。\n- 阻塞(BLOCKED) ：表示线程阻塞于锁。\n- 等待(WAITING) ：进入该状态的线程需要等待其他线程做出一些特定动作（通知或中断）。\n- 超时等待(TIMED_WAITING) ：该状态不同于WAITING，它可以在指定的时间后自行返回。\n- 终止(TERMINATED) ：表示该线程已经执行完毕。\n\n\n**初始状态(NEW)：**\n实现Runnable接口和继承Thread可以得到一个线程类，new一个实例出来，线程就进入了初始状态\n\n**就绪状态(RUNNABLE之READY)：**\n- 就绪状态只是说你资格运行，调度程序( Cpu )没有挑选到你，你就永远是就绪状态。\n- 调用线程的start()方法，此线程进入就绪状态。\n- 当前线程sleep()方法结束，其他线程join()结束，等待用户输入完毕，某个线程拿到对象锁，这些线程也将进入就绪状态。\n- 当前线程时间片用完了，调用当前线程的yield()方法，当前线程进入就绪状态。\n- 锁池里的线程拿到对象锁后，进入就绪状态。\n\n**运行中状态(RUNNABLE之RUNNING)：**\n线程调度程序从可运行池中选择一个线程作为当前线程时线程所处的状态。这也是线程进入运行状态的唯一的一种方式。\n\n**阻塞状态(BLOCKED)：**\n阻塞状态是线程阻塞在进入synchronized关键字修饰的方法或代码块(获取锁)时的状态。\n\n**等待(WAITING)：**\n处于这种状态的线程不会被分配CPU执行时间，它们要等待被显式地唤醒，否则会处于无限期等待的状态。\n\n**超时等待(TIMED_WAITING)：**\n处于这种状态的线程不会被分配CPU执行时间，不过无须无限期等待被其他线程显示地唤醒，在达到一定时间后它们会自动唤醒。\n\n**终止状态(TERMINATED)：**\n- 当线程的run()方法完成时，或者主线程的main()方法完成时，我们就认为它终止了。这个线程对象也许是活的，但是它已经不是一个单独执行的线程。线程一旦终止了，就不能复生。\n- 在一个终止的线程上调用start()方法，会抛出java.lang.IllegalThreadStateException异常。\n\n# Java中wait和sleep区别\n\n- sleep属于Thread类中的static方法；wait属于Object类的方法\n- sleep时线程状态进入TIMED_WAITING（计时等待），时间到了后自动被唤醒；wait时线程状态进入WAITING（等待），需要手动唤醒\n- sleep方法在线程持有锁时候执行，不会释放锁资源；wait方法执行后会释放锁资源\n- sleep可以在持有锁或者不持有锁时执行；wait方法必须在持有锁时执行\n\n![248296f4607142acbb36df07d8962bd5.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_14-39-47_ee22b5_248296f4607142acbb36df07d8962bd5.png)\n\n\n', NULL, NULL, '2024-07-12 17:04:15', '2024-07-23 14:40:33', 1);
INSERT INTO `doc_content` VALUES (87, 1, 168, '# 多线程关键字\n\n## synchronized\n\n- 修饰一个代码块\n   - 被修饰的代码块称为同步语句块，其作用的范围是大括号{} 括起来的代码，作用的对象是调用这个代码块的对象;\n   - synchronized(object) 表示进入同步代码库前要获得 给定对象的锁。\n   - synchronized(类.class) 表示进入同步代码前要获得 给定 Class 的锁\n```java\nsynchronized(this) {\n	if(null == this.searchByOrigPhone(encryPhone)) {\n		//存在相同的openId,先删除原来的信息\n		this.deleteByOpenId(mUser.getOpenId());\n		this.save(mUser.encryptSelf());	\n	};\n}\n```\n- 修饰一个方法\n  - 被修饰的方法称为同步方法，其作用的范围是整个方法，作用的对象是调用这个方法的对象;\n```java\npublic synchronized void method(){\n// 代码\n}\n```\n\n- 修饰一个静态的方法\n  - 其作用的范围是整个静态方法，作用的对象是这个类的 所有对象;\n```java\npublic static synchronized void method(){\n    // 代码\n}\n```\n\n- 修饰一个类\n  - 其作用的范围是synchronized后面括号括起来的部分，作用对象是这个类的所有对象。\n\nsynchronized的特点：\n\n- 原子性：确保线程互斥的访问同步代码。synchronized保证只有一个线程拿到锁，进入同步代码块操作共享资源，因此具有原子性。\n\n- 可见性：保证共享变量的修改能够及时可见。执行 synchronized时，会对应执行 lock 、unlock原子操作。lock操作，就会清空工作空间该变量的值；执行unlock操作之前，必须先把变量同步回主内存中。\n\n- 有序性：synchronized内的代码和外部的代码禁止排序，至于内部的代码，则不会禁止排序，但是由于只有一个线程进入同步代码块，因此在同步代码块中相当于是单线程的，根据 as-if-serial 语义，即使代码块内发生了重排序，也不会影响程序执行的结果。\n\n- 悲观锁：synchronized是悲观锁。每次使用共享资源时都认为会和其他线程产生竞争，所以每次使用共享资源都会上锁。\n\n- 独占锁（排他锁）：synchronized是独占锁（排他锁）。该锁一次只能被一个线程所持有，其他线程被阻塞。\n\n- 非公平锁：synchronized是非公平锁。线程获取锁的顺序可以不按照线程的阻塞顺序。允许线程发出请求后立即尝试获取锁。\n\n- 可重入锁：synchronized是可重入锁。持锁线程可以再次获取自己的内部的锁。\n\n## Lock\nLock是个接口，有个实现类是ReentrantLock。\n```java\npublic interface Lock {\n \n    /**\n     * 获取锁，调用该方法的线程会获取锁，当获取到锁之后会从该方法但会\n     */\n    void lock();\n \n    /**\n     * 可响应中断。即在获取锁的过程中可以中断当前线程\n     */\n    void lockInterruptibly() throws InterruptedException;\n \n    /**\n     * 尝试非阻塞的获取锁，调用该方法之后会立即返回，如果获取到锁就返回true否则返回false\n     */\n    boolean tryLock();\n \n    /**\n     * 超时的获取锁，下面的三种情况会返回\n     * ①当前线程在超时时间内获取到了锁\n     * ②当前线程在超时时间内被中断\n     * ③超时时间结束，返回false\n     */\n    boolean tryLock(long time, TimeUnit unit) throws InterruptedException;\n \n    /**\n     * 释放锁\n     */\n    void unlock();\n \n    /**\n     * 获取等待通知组件，该组件和当前锁绑定，当前线程只有获取到了锁才能调用组件的wait方法，调用该方法之后会释放锁\n     */\n    Condition newCondition();\n}\n```\n\nLock使用\n```java\nLock lock = new ReentrantLock();\nlock.lock();\ntry{\n    //处理任务\n}catch(Exception ex){\n     \n}finally{\n    lock.unlock();   //释放锁\n}\n```\n\n\n## volatile\nvolatile是Java提供的一种轻量级的同步机制。volatile只用来修饰变量。并且与synchronized、ReentrantLock等重量级锁不同的是，volatile更轻量级，因为它不会引起线程上下文的切换和调度。\n\n```java\npublic class Singleton {\n    // 使用volatile修饰，赋值后，其他线程能立即感知到\n    private static volatile Singleton instance;\n \n    private Singleton() {\n    }\n \n    public static Singleton getInstance() {\n        if (instance == null) {\n            synchronized (Singleton.class) {\n                if (instance == null) {\n                    instance = new Singleton();\n                }\n            }\n        }\n        return instance;\n    }\n \n}\n```\n\n## 各种同步机制的关系和区别：\n原理：\n- synchronized关键字属于JVM层面的，通过monitorenter,monitorexit指令实现，底层是通过monitor对象来完成，其实wait notify等方法也依赖monitor对象，只有同步块或者同步方法中才能调用wait,notify等方法；\n- Lock是具体类（java.utils.concurrent.locks.Lock）是API层面的锁\n\n使用方法：\n- synchronized不许要显式手动的获得和释放锁，系统会自动让线程释放对锁的占用\n- ReectrantLock：需要显式的获得和释放锁，如果没有正确的释放锁，有可能导致死锁；\n\n等待是否可以中断\n- synchronized不可以中断，除非抛出异常或者正常运行完成\n- ReentrantLock可以中断，1.设置超时时间tryLock(timeout) 2.lockInterruptibly放在代码块中，调用interrupter()方法可以中断\n\n加锁是否公平：\n- synchronzed是非公平锁\n- ReentrantLock两者都可以，默认为非公平锁，构造方法传入boolean值，true为公平锁\nReentrantLock:实现分组唤醒需要唤醒的线程们，可以实现精确唤醒，而不是像synchronized要么随机唤醒一个线程，要么唤醒所有的线程；\n\n## 锁的分类：\n悲观锁 or 乐观锁：是否一定要锁\n共享锁 or 独占锁（排他锁）：是否可以有多个线程同时拿锁\n公平锁 or 非公平锁：是否按阻塞顺序拿锁\n可重入锁 or 不可重入锁：拿锁线程是否可以多次拿锁 一个线程试图获取一个已经被该线程所持有的锁\n', NULL, NULL, '2024-07-12 17:21:08', '2024-11-14 11:55:47', 1);
INSERT INTO `doc_content` VALUES (88, 1, 169, '# Spring Boot 常用注解\n\n在使用SpringBoot的过程中，几乎没有了XML配置，采用注解+JavaConfig方式开发，这样做的好处是：\n\n- 采用纯java代码，不在需要配置繁杂的xml文件\n- 在配置中也可享受面向对象带来的好处\n- 类型安全对重构可以提供良好的支持\n- 减少复杂配置文件的同时亦能享受到springIoC容器提供的功能\n\n## @SpringBootApplication\n这个注解很常见了，每次在启动SpringBoot项目的时候，都会见到它，它作用在类上，标识该类为SpringBoot项目启动类。\n并且让SpringBoot自动给程序进行必要的配置，等同于@Configuration、@EnableAutoConfiguration、@ComponentScan这三个注解。\n\n## @Configuration\n相当于传统Spring的xml配置文件。\n如果第三方库需要用到xml文件，建议通过@Configuration类作为项目的配置主类，可以使用@ImportResource注解加载xml配置文件。\n\n## @EnableAutoConfiguration\nSpringBoot自动配置(auto-configuration)，尝试根据你添加的启动器(starter)自动配置你的SpringBoot应用。\n你可以将@EnableAutoConfiguration注解或者@SpringBootApplication注解添加到一个@Configuration类上来选择自动配置。\n如果发现应用了你不想要的特定自动配置类，你可以使用@EnableAutoConfiguration注解的排除属性来禁用它们。\n\n## @ComponentScan\n如果某个类加上@ComponentScan注解，则该类会自动发现扫描组件。\n也就是说，如果扫描到有@Component、@Controller、@Service等这些注解的类，并注册为Bean，可以自动收集所有的Spring组件，包括@Configuration类。\n我们经常使用@ComponentScan注解搜索beans，并结合@Autowired注解导入。如果没有配置的话，SpringBoot会扫描启动类所在包下以及子包下的使用了@Component、@Controller、@Service、@Repository等注解的类。\n\n## @Controller\n@Controller注解用于定义控制器类，在SpringBoot中由控制器负责将用户发来的URL请求转发到对应的服务接口(Controller层)。\n一般这个注解用在类上，控制器方法需要加上@RequestMapping注解。\n\n## @ResponseBody\n如果控制器方法加上@ResponseBody注解，该方法的返回结果将直接写入HTTP response body中，一般在异步获取数据时使用，用于构建RESTful的api。\n在使用@RequestMapping后，返回值通常解析为跳转路径，加上@esponsebody后返回结果不会被解析为跳转路径，而是直接写入HTTP response body中。\n比如异步获取json数据，加上@Responsebody后，会直接返回json数据。该注解一般会配合@RequestMapping一起使用。\n\n## @RestController\n@RestController注解是@Controller和@ResponseBody的合集。\n使用在类上，表示该类是控制器，并且类中所有控制器方法的返回值直接填入HTTP响应体中，是RESTful风格的控制器，控制器方法返回JSON数据。\n\n## @RequestMapping\n提供路由信息，负责URL到Controller中的具体方法的映射。\n\n@Service\n一般用于修饰service层的组件\n\n@Bean\n用@Bean标注方法等价于XML中配置的bean，意思是产生一个bean，并交给SpringBoot管理。\n\n@AutoWired\n自动导入依赖的bean。byType方式。把配置好的Bean拿来用，完成属性、方法的组装，它可以对类成员变量、方法及构造函数进行标注，完成自动装配的工作。当加上（required=false）时，就算找不到bean也不报错。\n\n@Resource(name=”name”,type=”type”)\n没有括号内内容的话，默认byName。与@Autowired干类似的事。\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-13 10:28:29', '2024-07-13 10:44:28', 1);
INSERT INTO `doc_content` VALUES (89, 1, 170, '# Nacos 面试题（一）\n\n**Nacos：**\n作为微服务的注册中心，提供服务的注册与发现功能\n作为微服务的分布式配置中心，提供统一配置管理，动态配置修改等功能\n\n## 1. 注册中心\n\n**作用：**\n- 服务注册：服务提供者在启动时将自己的信息（比如 IP 地址、端口号、服务名称等）注册到注册中心。nacos服务将这些信息保存到内存或数据库中。\n- 服务发现：服务消费者通过向注册中心查询服务信息，获取可用的服务实例列表。才能做进一步的调用\n- 健康检查：注册中心通过服务端临时实例定期上报或向永久实例主动调用了解服务的健康状态\n\n**注册中心的机制：**\n- 服务实例启动时通过引用的nacos的sdk主动向注册中心登记自己的地址信息（服务名、IP地址、端口等），nacos保存这些信息（临时实例保存到内存，永久实例保存到磁盘）\n- 客户端启动时从nacos获取服务端列表\n- 服务实例停止运行的时候，主动让注册中心销毁自己的信息\n- 服务实例不是主动停止，而是因为故障等原因死掉的，注册中心会通过心跳机制发现示例异常，对其清理\n\n**Nacos两种健康检查模式：**\n```\n# 微服务注册为临时实例,默认false\nspring:\n  cloud:\n    nacos:\n      discovery:\n        ephemeral: false   //false:持久化实例，使用 CP架构;true:临时实例，使用 AP架构\n```\n**适用场景**\n- 临时实例：适合于存在突发流量暴增可能的互联网项目，可以实现弹性扩容，正常生产中的环境就是这样；\n- 持久实例：保护阈值，比如说服务A有100个实例，那么当有98个不可用时：\n  - 如果是临时实例，则只会返回两个服务，那么大并发量请求这两个服务肯定会造成雪崩的，造成整个服务不可用；\n  - 如果是持久实例，实例会全部返回，虽然有98个不可用，消费者可能会请求失败，但不至于剩下的两个健康实例崩溃；\n\n- 对于临时实例，微服务每5秒发送一次心跳信息（服务是否正常运行、负载情况、资源消耗等）到nacos，如果超过15秒没有发送，就会标记为不健康状态，超过30秒后没有发送，就会将该服务标记为不可用状态\n- 对于永久实例，nocos默认20s主动探知客户端健康状态，如果失败，会设置为不健康状态\n\n## 2. 配置中心\n\n**提供的功能:**\n- 动态更新：可以通过操作界面或 API 进行动态更新，无需重启服务就可以应用最新的配置信息。\n- 配置信息共享：将配置集中在配置中心中，不同的服务实例可以共享同一套配置信息。\n- 信息追溯：支持配置版本管理、历史记录等管理功能。\n\n**分布式配置中心概念**\n服务的多个实例或多个服务都使用同一个配置文件，而不是每个实例或服务都使用自己独有的配置；使用分布式配置中心对于需要修改配置时，不用繁琐的修改每个配置并重启实例，直接修改一个配置文件即可。\n\n**nacos配置实时更新原理**\n\n当客户端启动时，它会向Nacos服务器发送请求，以拉取初始的配置信息。\n\nNacos配置的动态更新采用了长轮询机制。客户端会向服务器发起一个轮询请求，然后保持这个连接打开，等待服务器端的响应。如果服务器端的配置没有发生任何变更，这个连接会一直保持打开状态，直到配置发生变更或者连接超时为止。\n\n服务器端的配置信息发生变化时，Nacos服务器会通过建立的长连接主动通知客户端。客户端接收到配置变化的通知，会重新从Nacos服务器获取最新的配置信息，并更新自己的运行环境。\n\n**长轮询连接的特点**\n当服务端有配置更新时，会立即将数据传递给客户端并断开连接。此时，客户端在接收到配置更新后会重新发起一个新的长轮询请求。\n\n**长轮询连接超时**\n如果一直没有数据变动，连接也会到指定时间而超时，这时客户端会重新发起长轮询请求。其他情况导致的连接中断或超时也会进行重新建立连接\n\n', NULL, NULL, '2024-07-14 13:32:57', '2024-07-14 14:18:25', 1);
INSERT INTO `doc_content` VALUES (90, 1, 172, '# IO多路复用\n\nIO多路复用（Input/Output Multiplexing）是一种在单个线程中管理多个输入/输出通道的技术。它允许一个线程同时监听多个输入流（例如网络套接字、文件描述符等），并在有数据可读或可写时进行相应的处理，而不需要为每个通道创建一个独立的线程。\n\n## IO 多路复用的优缺点\n\nIO多路复用的优点包括：\n- 高效性：通过单个线程同时管理多个IO通道，减少了线程的创建和销毁开销，提高了系统的并发性能。\n- 资源节约：相比每个通道创建一个独立的线程，IO多路复用可以使用更少的线程来处理大量的IO通道，节约了系统资源。\n- 简化编程模型：使用IO多路复用可以将异步IO操作转换为同步的事件驱动模型，简化了编程逻辑和代码复杂度。\n- 可扩展性：由于使用了事件驱动模型，IO多路复用可以轻松地扩展到更多的IO通道，而不需要修改大量的代码。\n\n缺点：\n- 学习曲线较陡：相比于传统的多线程或多进程模型，IO多路复用的概念和使用方式可能需要一些学习和理解。\n- 对编程模型的要求较高：使用IO多路复用需要合理地设计和处理事件驱动的逻辑，否则可能会导致代码复杂、难以维护。\n- 不适用于CPU密集型任务：IO多路复用适用于IO密集型任务，而对于CPU密集型任务，使用多线程或多进程模型可能更为合适。\n\n## IO 多路复用的原理\n\n- 多路复用：多路复用是指通过一个线程同时监听多个IO事件的就绪状态。在传统的阻塞IO模型中，每个IO操作都需要一个独立的线程来处理，当有大量的IO操作时，会导致线程数量的增加，从而带来线程切换和上下文切换的开销。而多路复用通过使用一个线程来监听多个IO事件，避免了线程数量的增加，减少了线程切换和上下文切换的开销。\n\n- IO事件就绪通知：多路复用机制通过操作系统提供的系统调用（如select、poll、epoll等）来监听多个IO事件的就绪状态。当有任何一个IO事件就绪时，操作系统会通知应用程序，告知哪些IO事件已经准备好可以进行读取或写入操作。\n\n- 非阻塞IO：多路复用机制通常与非阻塞IO配合使用。在非阻塞IO模型中，当一个IO操作无法立即完成时，不会阻塞线程，而是立即返回一个错误码或特定的状态，应用程序可以继续处理其他IO操作或其他任务，提高了系统的并发性能。\n\n- 事件循环：多路复用机制通过事件循环来处理就绪的IO事件。事件循环会不断地监听IO事件的就绪状态，当有IO事件就绪时，会调用相应的回调函数来处理该事件。通过事件循环的方式，可以高效地处理多个IO操作。\n\n## IO 多路复用的实现\n\n**select：**\nselect是最古老的IO多路复用机制，它使用一个文件描述符集合来监听多个IO事件的就绪状态。应用程序需要将需要监听的文件描述符添加到集合中，然后调用select函数进行监听。当有文件描述符就绪时，select函数会返回，并告知哪些文件描述符已经准备好进行读取或写入操作。然后应用程序可以通过遍历文件描述符集合来处理就绪的IO事件。\n\n**poll：**\npoll是select的改进版本，它也使用一个文件描述符集合来监听多个IO事件的就绪状态。与select不同的是，poll不需要每次调用都将文件描述符集合传递给内核，而是使用一个pollfd结构体数组来传递。应用程序需要将需要监听的文件描述符和事件类型添加到pollfd数组中，然后调用poll函数进行监听。当有文件描述符就绪时，poll函数会返回，并告知哪些文件描述符已经准备好进行读取或写入操作。然后应用程序可以通过遍历pollfd数组来处理就绪的IO事件。\n\n**epoll：**\nepoll是Linux特有的IO多路复用机制，它使用一个内核事件表来管理和监听多个IO事件的就绪状态。应用程序需要将需要监听的文件描述符添加到内核事件表中，然后调用epoll_wait函数进行监听。当有文件描述符就绪时，epoll_wait函数会返回，并告知哪些文件描述符已经准备好进行读取或写入操作。与select和poll不同的是，epoll使用回调函数来处理就绪的IO事件，而不需要应用程序遍历事件列表。\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-14 14:31:30', '2024-07-14 14:44:16', 1);
INSERT INTO `doc_content` VALUES (91, 1, 174, '# 分布式设计思想\n\n## 对分布式系统的理解\n\n为了解决传统单体服务架构带来的各种问题（代码数量庞大，迭代测试维护困难），可能因为一处改动测试不到位造成整个服务瘫痪等问题，分布式系统就是将一个大的服务拆分成几十个甚至上百个微小的服务。\n\n比如阿里的 Dubbo，还有 Spring 全家桶里的 Spring Cloud，都是解决分布式微服务架构的优秀框架。\n\n\n## 分布式系统环境下各自有什么优缺点？\n\n**优点：**\n- 系统可用性提升\n  - 传统的集中式计算或集中式存储在遇见单点故障时很容易造成整个服务不可用，分布式下的服务体系，单台机器有故障，不致于造成整个服务不可用。\n\n- 系统并发能力提升\n  - 请求通过 Nginx 负载均衡被分发到不同的服务器上，运行同样代码的服务器可以有 1 台或 N 台，通常情况下会根据实际用户访问量随时增加机器，无论是数据库或者服务，都可以做到随时水平扩展。\n\n- 系统容错能力提升\n  - 会将请求发送到未发生故障的节点\n\n- 低延迟 \n  - 服务器会根据用户的 IP 选择距离自己最近的机房，降低网络延迟。 \n\n**缺点：**\n- 分布式服务依赖网络\n  - 服务器间通讯依赖网络，不可靠网络包括网络延时，丢包、中断、异步，一个完整的服务请求依赖一连串服务调用，任意一个服务节点网络出现问题，都可能造成本次请求失败。\n- 维护成本高\n  - 分布式服务系统被拆分成若干个小服务，服务从 1 变为几十个上百个服务后，增加运维成本。\n\n- 一致性，可用性，分区容错性无法同时满足\n  - 这个是最主要的，这三种特性就是平时说的 CAP 定理，在分布式系统中，这三种特性最多只能满足两种，无法同时满足。\n\n## 分布式系统和微服务什么关系\n关于分布式系统和微服务，两者都只是一种概念。如果你采用微服务，就意味着系统一定是分布式的，分布式系统具有的优缺点在微服务理都会体现，个人理解微服务是分布式系统的一种具体落地方案。\n\n## CAP\nCAP原则又称CAP原理，指的是在一个分布式系统，当涉及读写操作时，只能保证一致性（Consistency）、可用性（Availability）、分区容错性（Partition Tolerance）三者中的两个，另外一个必须被牺牲。\n\n- 一致性（C）：在分布式系统中的所有数据备份，在同一时刻是否有同样的值，即写操作之后的读操作，必须返回该值。\n\n  - 这里的一致性指的是强一致性，也就是数据更新完，访问任何节点看到的数据完全一致，要和弱一致性，最终一致性区分开来。\n\n- 高可用性（A）：在集群中一部分节点故障后，集群整体是否还能响应客户端的读写请求。\n\n- 分区容忍性（P）：是指在分布式系统遇到网络分区的情况下，仍然可以响应用户的请求\n  - 网络分区是指因为网络故障导致网络不连通，不同节点分布在不同的子网络中，各个子网络内网络正常。在电商系统中，假设 C 与 A 和 B 的网络都不通了，A 和 B 是相通的。也就是说，形成了两个分区{A, B}和{C}，在这种情况下，系统仍能响应用户请求。', NULL, NULL, '2024-07-15 08:56:09', '2024-07-15 12:39:12', 1);
INSERT INTO `doc_content` VALUES (92, 1, 175, '# 分布式面试题（一）\n\n## 分布式事务解决方案', NULL, NULL, '2024-07-15 12:39:34', '2024-07-15 12:58:23', 1);
INSERT INTO `doc_content` VALUES (93, 1, 176, '# 分布式事务解决方案\n\n## XA 两阶段提交协议\n\n两阶段提交协议（Two-phase commit protocol，简称2PC）是一种分布式事务处理协议，旨在确保参与分布式事务的所有节点都能达成一致的结果。此协议被广泛应用于许多分布式关系型数据管理系统，以完成分布式事务。\n\n这一种强一致性设计，引入一个事务协调者的角色来协调管理各参与者的提交和回滚，二阶段分别指的是准备（投票）和提交两个阶段。\n\n\n## XA三阶段提交\n\n三阶段提交协议（Three-phase commit protocol，3PC），是二阶段提交（2PC）的改进版本。与两阶段提交不同的是，三阶段提交有两个改动点：在协调者和参与者中都引入超时机制，同时引入了预提交阶段。\n\n3PC 把 2PC 的准备阶段再次一分为二，这样三阶段提交就有 CanCommit、PreCommit、DoCommit 三个阶段。\n\n\n##  MQ事务\n利用消息中间件来异步完成事务的后半部分更新，实现系统的最终一致性。\n\n## TCC事务\n\n\n- Try阶段：主要是对业务系统做检测及资源预留。（执行2、3步骤）\n- Confirm阶段：确认执行业务操作。如果Try阶段成功，则执行Confirm操作，提交事务。（执行4、5步骤）\n- Cancel阶段：取消执行业务操作。如果Try阶段失败或超时，则执行Cancel操作，回滚事务。（执行4、5步骤）\n\n## 最终补偿机制，同于MQ事务\n\n对于发送成功，消费失败的消息，使用单独的作业服务进行独立处理，比如重新发送死信消息进行消费，避免生产和消费的不一致，保证了最终的原子性、一致性。', NULL, NULL, '2024-07-15 12:58:36', '2024-07-15 13:04:39', 1);
INSERT INTO `doc_content` VALUES (94, 1, 178, '# RabbitMQ面试题（一）\n\n## 消息丢失处理\n消息丢失的场景主要分为：消息在生产者丢失，消息在RabbitMQ丢失，消息在消费者丢失。\n\n- 消息在生产者丢失\n消息生产者发送消息成功，但是MQ没有收到该消息，消息在从生产者传输到MQ的过程中丢失，一般是由于网络不稳定的原因。\nRabbitMQ 发送方消息确认模式有以下三种：普通确认模式，批量确认模式，异步监听确认模式。\nspring整合RabbitMQ后只使用了异步监听确认模式。\n在发送消息前添加异步确认监听器\n\n- 消息在RabbitMQ丢失\n消息成功发送到MQ，消息还没被消费却在MQ中丢失，比如MQ服务器宕机或者重启会出现这种情况\n持久化交换机，队列，消息，确保MQ服务器重启时依然能从磁盘恢复对应的交换机，队列和消息。\n\n- 消息在消费者丢失\n消息已经在MQ被删除但是消费者的业务处理出现异常或者消费者服务宕机，就会导致该消息没有处理成功从而导致该条消息丢失。\n设置为手动回复MQ服务器\n\n## 有序消费消息\n\n- 场景一\n当RabbitMQ采用work Queue模式，此时只会有一个Queue但是会有多个Consumer,同时多个Consumer直接是竞争关系，此时就会出现MQ消息乱序的问题。\n![MQ乱序1.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-15_13-26-58_06b0c8_MQ乱序1.png)\n\n解决：\n![场景1解决方案.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-15_13-27-38_2e8d02_场景1解决方案.png)\n\n- 场景二\n当RabbitMQ采用简单队列模式的时候,如果消费者采用多线程的方式来加速消息的处理,此时也会出现消息乱序的问题。\n\n![MQ乱序2.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-15_13-28-59_46a0da_MQ乱序2.png)\n\n解决：\n![场景2解决方案.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-15_13-29-50_e84461_场景2解决方案.png)\n\n## 重复消费\n\n为了防止消息在消费者端丢失，会采用手动回复MQ的方式来解决，同时也引出了一个问题，消费者处理消息成功，手动回复MQ时由于网络不稳定，连接断开，导致MQ没有收到消费者回复的消息，那么该条消息还会保存在MQ的消息队列，由于MQ的消息重发机制，会重新把该条消息发给和该队列绑定的消息者处理，这样就会导致消息重复消费。而有些操作是不允许重复消费的，比如下单，减库存，扣款等操作。\n\n**解决方案：**\n如果消费消息的业务是幂等性操作（同一个操作执行多次，结果不变）就算重复消费也没问题，可以不做处理，如果不支持幂等性操作，如：下单，减库存，扣款等，那么可以在消费者端每次消费成功后将该条消息id保存到数据库，每次消费前查询该消息id，如果该条消息id已经存在那么表示已经消费过就不再消费否则就消费。本方案采用redis存储消息id，因为redis是单线程的，并且性能也非常好，提供了很多原子性的命令，本方案使用setnx命令存储消息id。\n\n## RabbitMQ支持的消息模式\n- 简单队列（Simple Queue）\n  - 一个生产者发送消息至一个特定的队列，只有一个消费者从该队列接收并处理消息。\n- 工作队列（Work Queue）\n  - 多个消费者竞争消费来自同一队列的消息，每条消息只会被一个消费者获取并处理。这种模式实现了任务的负载均衡，确保消息在消费者之间公平分配。\n- 发布/订阅（Publish/Subscribe, Pub/Sub）\n  - 生产者向一个交换机发布消息，消息携带指定的路由键。交换机会根据路由键将消息投递到所有绑定到该交换机且匹配路由键的队列上。每个队列都有一个或多个消费者订阅，消息会被所有订阅队列的消费者接收到。\n- 主题模式（Topics）\n  - 类似于发布/订阅模式，但使用更复杂的路由键规则（包含通配符*和#）。生产者仍然向交换机发布消息，但消费者可以通过订阅具有通配符的路由键来接收匹配特定模式的消息。\n- 路由模式（Direct）\n- 头部交换（Headers）\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-15 13:11:22', '2024-07-25 15:10:32', 1);
INSERT INTO `doc_content` VALUES (95, 1, 180, '# Spring Boot 启动流程\n\nspring boot 启动流程总结：\n\n1、运行 SpringApplication.run() 方法;\n2、确定应用程序类型;\n3、加载所有的初始化器(springboot自带初始化器，从从 META-INF/spring.factories 配置文件中加载; spring.factories文件里面，看到开头是 org.springframework.context.ApplicationContextInitializer 接口就是初始化器了.);\n4、加载所有的监听器(加载监听器也是从 META-INF/spring.factories 配置文件中加载的，监听器加载的是实现了ApplicationListener接口的类.);\n5、设置程序运行的主类(deduceMainApplicationClass(); 这个方法仅仅是找到main方法所在的类,为后面的扫包作准备,deduce是推断的意思,所以准确地说,这个方法作用是推断出主方法所在的类);\n6、开启计时器(计算springboot启动花了多长时间；程序运行到这里，就已经进入了run方法的主体了，第一步调用的run方法是静态方法，那个时候还没实例化SpringApplication对象，现在调用的run方法是非静态的，是需要实例化后才可以调用的，进来后首先会开启计时器);\n   // 实例化计时器\n   StopWatch stopWatch = new StopWatch(); \n   // 开始计时\n   stopWatch.start();\n7、将java.awt.headless设置为true(表示运行在服务器端，在没有显示器?和鼠标键盘的模式下照样可以工作，模拟输入输出设备功能;即使没有检测到显示器,也允许其启动.对于服务器来说,是不需要显示器的,所以要这样设置.);\n8、获取并启用监听器(通过监听器来实现初始化的的基本操作做了2件事情: 1、创建所有Spring运行监听器并发布应用启动事件；2、启用监听器；);\n9、设置应用程序参数(将执行run方法时传入的参数封装成一个对象;这个参数是从哪来的呢？其实就是main方法里面执行静态run方法传入的参数。);\n10、准备环境变量(准备环境变量，包含系统属性和用户配置的属性，执行的代码块在 prepareEnvironment 方法内。);\n11、忽略bean信息(这个方法configureIgnoreBeanInfo() 这个方法是将 spring.beaninfo.ignore 的默认值设为true，意思是跳过beanInfo的搜索，其设置默认值的原理和第7步一样);\n12、打印banner信息(他在哪里打印的呢？他在SpringBootBanner.java里面打印的，这个类实现了Banner接口;banner信息是直接在代码里面写死的;如果想要改成自定义banner信息，该怎么办呢?只需要在resources目录下添加一个 banner.txt 的文件即可);\n13、创建应用程序的上下文(实例化应用程序的上下文， 调用 createApplicationContext() 方法，这里就是用反射创建对象);\n14、实例化异常报告器(异常报告器是用来捕捉全局异常使用的，当springboot应用程序在发生异常时，异常报告器会将其捕捉并做相应处理，在spring.factories 文件里配置了默认的异常报告器。需要注意的是，这个异常报告器只会捕获启动过程抛出的异常，如果是在启动完成后，在用户请求时报错，异常报告器不会捕获请求中出现的异常。);\n15、准备上下文环境;\n15.1、实例化单例的beanName生成器\n      在 postProcessApplicationContext(context); 方法里面。使用单例模式创建 了BeanNameGenerator 对象，其实就是beanName生成器，用来生成bean对象的名称;\n15.2、执行初始化方法\n      初始化方法有哪些呢？还记得第3步里面加载的初始化器嘛？其实是执行第3步加载出来的所有初始化器，实现了ApplicationContextInitializer 接口的类;\n15.3、将启动参数注册到容器中\n      这里将启动参数以单例的模式注册到容器中，是为了以后方便拿来使用，参数的beanName 为 ：springApplicationArguments;\n16、刷新上下文(刷新上下文已经是spring的范畴了，自动装配和启动 tomcat就是在这个方法里面完成的);\n17、刷新上下文后置处理(afterRefresh方法是启动后的一些处理，留给用户扩展使用，目前这个方法里面是空的。);\n18、结束计时器(springboot其实就已经完成了，计时器会打印启动springboot的时长。);\n \n![springboot启动流程.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-14-29_13bc03_springboot启动流程.png)\n\n## 1. 运行 SpringApplication.run() 方法;\n\n## 2. 确定应用程序类型\n在SpringApplication的构造方法内，首先会通过 WebApplicationType.deduceFromClasspath()； 方法判断当前应用程序的容器，默认使用的是Servlet 容器，除了servlet之外，还有NONE 和 REACTIVE （响应式编程）；\n![1c601577a6ef4d21a71ae453411c7e46.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-33-11_ed4a94_1c601577a6ef4d21a71ae453411c7e46.png)\n\n## 3. 加载所有的初始化器\n这里加载的初始化器是springboot自带初始化器，从 META-INF/spring.factories 配置文件中加载的，这个文件自带有2个，分别在源码的jar包的 spring-boot-autoconfigure 项目 和 spring-boot 项目里面各有一个\n![bb62de45cfd14bb18a1f64a94eb85a95.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-44-58_586056_bb62de45cfd14bb18a1f64a94eb85a95.png)\n\nspring.factories文件里面，看到开头是 org.springframework.context.ApplicationContextInitializer 接口就是初始化器了 \n![1147bcffe25d4ed1acf88ddba3797cce.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-45-30_5e71d3_1147bcffe25d4ed1acf88ddba3797cce.png)\n\n也可以自己实现一个自定义的初始化器：实现 ApplicationContextInitializer接口既可\n\n**自定义初始化器：**\n\n```java\npackage com.spring.application;\nimport org.springframework.context.ApplicationContextInitializer;\nimport org.springframework.context.ConfigurableApplicationContext;\n/** * 自定义的初始化器 */\npublic class MyApplicationContextInitializer implements ApplicationContextInitializer<ConfigurableApplicationContext> { \n\n    @Override\n    public void initialize(ConfigurableApplicationContext configurableApplicationContext) { \n\n        System.out.println(\"我是初始化的 MyApplicationContextInitializer...\");\n    }\n}\n\n```\n\n在resources目录下添加 META-INF/spring.factories 配置文件，内容如下，将自定义的初始化器注册进去；\n\n```java\norg.springframework.context.ApplicationContextInitializer=\\\ncom.spring.application.MyApplicationContextInitializer\n```\n![2651e76dbb9e4a5a9d6139eac365e68c.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-47-18_3a302a_2651e76dbb9e4a5a9d6139eac365e68c.png)\n![69871ec5c67e406aa1879004495f354a.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-47-35_41aed5_69871ec5c67e406aa1879004495f354a.png)\n\n\n## 4. 加载所有的监听器\n\n加载监听器也是从 META-INF/spring.factories 配置文件中加载的，与初始化不同的是，监听器加载的是实现了 ApplicationListener 接口的类\n\n![49abf0a54c44493c89d5991267c68d6d.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-48-06_2da016_49abf0a54c44493c89d5991267c68d6d.png)\n\n自定义监听器也跟初始化器一样 实现 ApplicationListener ,然后加入 spring.factories 文件\n\n## 5. 设置程序运行的主类\n\ndeduceMainApplicationClass(); 这个方法仅仅是找到main方法所在的类，为后面的扫包作准备，deduce是推断的意思，所以准确地说，这个方法作用是推断出主方法所在的类；\n![372cccd0f6384ef8b317d881eb2535c3.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-50-02_8cf861_372cccd0f6384ef8b317d881eb2535c3.png)\n\n## 6. 开启计时器\n第一步调用的run方法是静态方法，那个时候还没实例化SpringApplication对象，现在调用的run方法是非静态的，是需要实例化后才可以调用的，进来后首先会开启计时器，计算springboot启动花了多长时间；关键代码如下：\n\n```java\n// 实例化计时器\nStopWatch stopWatch = new StopWatch(); \n// 开始计时\nstopWatch.start();\n```\n![a811406efc9443c2ae015ed6bbe85b30.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-52-26_21ba85_a811406efc9443c2ae015ed6bbe85b30.png)\n\n## 7. 将java.awt.headless设置为true\n将java.awt.headless设置为true，表示运行在服务器端，在没有显示器器和鼠标键盘的模式下照样可以工作，模拟输入输出设备功能\n\n**方法主体如下：**\n```java\nprivate void configureHeadlessProperty() { \n  System.setProperty(SYSTEM_PROPERTY_JAVA_AWT_HEADLESS, System.getProperty(\n  SYSTEM_PROPERTY_JAVA_AWT_HEADLESS, Boolean.toString(this.headless)));\n}\n```\n\n## 8. 获取并启用监听器\n\n通过监听器来实现初始化的的基本操作，这一步做了2件事情\n1. 创建所有Spring运行监听器并发布应用启动事件；\n2. 启用监听器；\n\n![f87c2a67cb264e36a96d409e4e5f55bd.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-55-33_217cfd_f87c2a67cb264e36a96d409e4e5f55bd.png)\n\n## 9. 设置应用程序参数\n\n将执行run方法时传入的 args 参数封装成一个对象\n![8436928be6e04094ae8ce6d873da2677.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-56-08_ba19fc_8436928be6e04094ae8ce6d873da2677.png)\n\n## 10. 准备环境变量\n\n准备环境变量，包含系统属性和用户配置的属性，执行的代码块在 prepareEnvironment 方法内\n\n![1b77a70eacae451eb68eabfff038dc5c.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-57-18_884765_1b77a70eacae451eb68eabfff038dc5c.png)\n\n打了断点之后可以看到，它将maven和系统的环境变量都加载进来了。\n![a1c81856b3664c6dab9b6c8c7a715377.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-57-40_014e92_a1c81856b3664c6dab9b6c8c7a715377.png)\n\n## 11. 忽略bean信息\n\n这个方法configureIgnoreBeanInfo() 这个方法是将 spring.beaninfo.ignore 的默认值设为true，意思是跳过beanInfo的搜索，其设置默认值的原理和第7步一样；\n\n```java\nprivate void configureIgnoreBeanInfo(ConfigurableEnvironment environment) { \n    if (System.getProperty(CachedIntrospectionResults.IGNORE_BEANINFO_PROPERTY_NAME) == null) { \n        Boolean ignore = environment.getProperty(\"spring.beaninfo.ignore\",Boolean.class, Boolean.TRUE);\n        System.setProperty(CachedIntrospectionResults.IGNORE_BEANINFO_PROPERTY_NAME,ignore.toString());\n    }\n}\n```\n可以在配置文件中添加以下配置来设为false\n\n```xml\nspring.beaninfo.ignore=false\n```\n\n\n## 12. 打印 banner 信息\n\n![1e7e209fbb7e4b41920998360c6a8b08.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-59-43_d6a1e0_1e7e209fbb7e4b41920998360c6a8b08.png)\n\n![95a7f7d9e8694cae9d175f1e4273b916.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_15-59-54_cf86e3_95a7f7d9e8694cae9d175f1e4273b916.png)\n\n**修改banner：**\n在resources目录下添加一个 banner.txt 的文件\n![3f43bc64fdd2496dbfcbdb8662056dd7.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-00-49_4747e1_3f43bc64fdd2496dbfcbdb8662056dd7.png)\n\n只需要加一个文件即可，其他什么都不用做，然后直接启动springboot，就可以看到效果了。\n\n## 13. 创建应用程序的上下文\n\n实例化应用程序的上下文， 调用 createApplicationContext() 方法，这里就是用反射创建对象\n\n![58eaa84ee0b24e32a7990ea929e7d9d7.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-01-47_594ee8_58eaa84ee0b24e32a7990ea929e7d9d7.png)\n\n## 14. 实例化异常报告器\n\n异常报告器是用来捕捉全局异常使用的，当springboot应用程序在发生异常时，异常报告器会将其捕捉并做相应处理，在spring.factories 文件里配置了默认的异常报告器。\n\n![7d1dba331cac4c51a096cdab8200a8de.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-02-12_187ef5_7d1dba331cac4c51a096cdab8200a8de.png)\n\n这个异常报告器只会捕获启动过程抛出的异常，如果是在启动完成后，在用户请求时报错，异常报告器不会捕获请求中出现的异常。\n\n![e35f33d57c4e4545a3bce0b783a5457a.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-02-49_ac1491_e35f33d57c4e4545a3bce0b783a5457a.png)\n\n\n**配置自定义的异常报告器：**\n继承 SpringBootExceptionReporter 接口\n\n```java\npackage com.spring.application;\nimport org.springframework.boot.SpringBootExceptionReporter;\nimport org.springframework.context.ConfigurableApplicationContext;\npublic class MyExceptionReporter implements SpringBootExceptionReporter { \n\n    private ConfigurableApplicationContext context;\n    // 必须要有一个有参的构造函数，否则启动会报错\n    MyExceptionReporter(ConfigurableApplicationContext context) { \n\n        this.context = context;\n    }\n    @Override\n    public boolean reportException(Throwable failure) { \n\n        System.out.println(\"进入异常报告器\");\n        failure.printStackTrace();\n        // 返回false会打印详细springboot错误信息，返回true则只打印异常信息 \n        return false;\n    }\n}\n```\n在 spring.factories 文件中注册异常报告器\n\n```xml\n# Error Reporters 异常报告器\norg.springframework.boot.SpringBootExceptionReporter=\\\ncom.spring.application.MyExceptionReporter\n```\n\n![fd1d69396c9f47e98682035053ef982a.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-04-53_2502e7_fd1d69396c9f47e98682035053ef982a.png)\n\n![eb1de56557274bc386fde970063b893b.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-06-00_3d5a05_eb1de56557274bc386fde970063b893b.png)\n\n\n## 15. 准备上下文环境\n\n准备的上下文环境是为了下一步刷新做准备的，里面还做了一些额外的事情\n![51f7326cc569451fb91189525c6867f9.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-06-46_3a3bb9_51f7326cc569451fb91189525c6867f9.png)\n\n\n1. 实例化单例的beanName生成器\n在 postProcessApplicationContext(context); 方法里面。使用单例模式创建 了BeanNameGenerator 对象，其实就是beanName生成器，用来生成bean对象的名称\n\n2. 执行初始化方法\n执行第3步加载出来的所有初始化器，实现了ApplicationContextInitializer 接口的类\n\n3. 将启动参数注册到容器中\n将启动参数以单例的模式注册到容器中，是为了以后方便拿来使用，参数的beanName 为 ：springApplicationArguments\n\n\n## 16. 刷新上下文\n自动装配和启动 tomcat就是在这个方法里面完成的，还有其他的spring自带的机制\n![af8bed9c0cde4ed19c669f5fcbb29973.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-09-27_635eda_af8bed9c0cde4ed19c669f5fcbb29973.png)\n\n## 17. 刷新上下文后置处理\nafterRefresh 方法是启动后的一些处理，留给用户扩展使用，目前这个方法里面是空的。\n\n## 18. 结束计时器\n![3fe5ce9897d34ae788b5b1e58b0c4028.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-10-05_cc7e3b_3fe5ce9897d34ae788b5b1e58b0c4028.png)\n\n## 19. 发布上下文准备就绪事件\n告诉应用程序，已经准备好了，可以开始工作了\n![5e68c5cb3b6d40a1ad52ab716a1b3c67.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-10-26_0baa14_5e68c5cb3b6d40a1ad52ab716a1b3c67.png)\n\n## 20. 执行自定义的run方法\n这是一个扩展功能，callRunners(context, applicationArguments) 可以在启动完成后执行\n\n自定义的run方法；有2中方式可以实现：\n1. 实现 ApplicationRunner 接口\n2. 实现 CommandLineRunner 接口\n\n接下来我们验证一把，为了方便代码可读性，我把这2种方式都放在同一个类里面\n \n```java\npackage com.spring.init;\nimport org.springframework.boot.ApplicationArguments;\nimport org.springframework.boot.ApplicationRunner;\nimport org.springframework.boot.CommandLineRunner;\nimport org.springframework.stereotype.Component;\n/** * 自定义run方法的2种方式 */\n@Component\npublic class MyRunner implements ApplicationRunner, CommandLineRunner { \n\n    @Override\n    public void run(ApplicationArguments args) throws Exception { \n\n        System.out.println(\" 我是自定义的run方法1，实现 ApplicationRunner 接口既可运行\"        );\n    }\n    \n    @Override\n    public void run(String... args) throws Exception { \n\n        System.out.println(\" 我是自定义的run方法2，实现 CommandLineRunner 接口既可运行\"        );\n    }\n}\n\n```\n\n![690cbb5e84c041c284f160a51021dc65.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_16-14-15_d15011_690cbb5e84c041c284f160a51021dc65.png)\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-15 20:32:05', '2024-07-23 16:14:19', 1);
INSERT INTO `doc_content` VALUES (96, 1, 182, '# MQTT面试题\n\n## MQTT是什么\nMQTT（Message Queuing Telemetry Transport，消息队列遥测传输协议）是一种轻量级的、基于发布/订阅模式的通讯协议。它被设计用于有限的带宽和不稳定网络环境中，非常适合物联网（IoT）设备之间的通信。\n\n- 轻量级：MQTT的消息头部很小，可以减少设备的带宽和功耗，适合在嵌入式设备上使用。\n- 发布/订阅模式：允许一个设备通过发布消息到一个主题，同时多个设备可以订阅这个主题来接收消息。\n- 可靠性：支持三种不同的服务质量（QoS）级别，确保消息的可靠传输。\n- 异步通信：发布者和订阅者不需要同时在线，消息会被存储在服务器上，直到订阅者成功接收。\n- 简单易用：协议简单，易于实现，支持多种编程语言。\n\n##  MQTT与HTTP的区别\n\n- 通信模式：\n  - MQTT基于发布/订阅模式，允许一个设备（发布者）发送消息到主题，而多个设备（订阅者）可以订阅这些主题来接收消息。\n  - HTTP基于请求/响应模式，客户端发送请求到服务器，服务器返回响应。\n- 用途和场景：\n  - MQTT专为物联网（IoT）设计，适用于带宽有限、延迟敏感和不稳定的网络环境，如移动通信、嵌入式设备等。\n  - HTTP主要用于网页浏览、文件传输和API服务，适用于稳定、高带宽的网络环境。\n- 消息大小和开销：\n  - MQTT协议头很小，消息开销低，适合传输小消息。\n  - HTTP协议头相对较大，适合传输较大数据，如文件、图片等。\n- 服务质量（QoS）：\n  - MQTT支持三种不同的服务质量级别，可以根据需要选择不同级别的消息传递可靠性。\n  - HTTP没有内建的消息服务质量级别，但可以通过实现特定的错误处理和重试机制来提高可靠性。\n- 连接模型：\n  - MQTT保持长连接，客户端与服务器之间保持持久的会话，直到客户端显式断开连接。\n  - HTTP使用短连接，每个请求完成后连接通常会被关闭，虽然HTTP/1.1支持持久连接（keep-alive），但每次请求/响应交互后，连接可能会处于空闲状态。\n- 实时性：\n  - MQTT设计用于实时通信，延迟低，适合需要即时响应的应用。\n  - HTTP的实时性不如MQTT，尽管有WebSocket等协议可以提供实时通信功能，但HTTP本身更适合非实时应用。\n- 资源消耗：\n  - MQTT由于轻量级设计，对设备资源的要求较低。\n  - HTTP通常需要更多的资源，尤其是在移动或嵌入式设备上。\n\n## MQTT中有哪些消息质量（Qos）等级\n\nMQTT协议定义了三种消息质量等级（Quality of Service, QoS），用于指定消息传递的可靠性。这些QoS等级如下：\n\n- QoS 0 - 至多一次（At Most Once）：\n  - 这是最低的QoS等级，消息最多被传递一次。\n  - 发布者将消息发送给代理（Broker），不会等待任何确认。\n  - 如果订阅者在线并能够接收消息，它将收到消息；否则，消息可能会丢失。\n  - 这个等级适用于可以容忍消息丢失的场景，例如实时监控或传感器数据，其中最新的数据比旧数据更重要。\n- QoS 1 - 至少一次（At Least Once）：\n  - 在这个等级，消息至少被传递一次。\n  - 发布者发送消息后，会等待代理的确认（PUBACK）。\n  - 如果代理没有收到确认，它会尝试重新发送消息。\n  - 订阅者在接收到消息后，需要向代理发送确认（PUBACK）。\n  - 这个等级适用于不能容忍消息丢失，但可以容忍重复传递的场景。\n- QoS 2 - 正好一次（Exactly Once）：\n  - 这是最高等级的QoS，确保消息精确地被传递一次。\n  - 发布者发送消息，并等待代理的确认（PUBREC）。\n  - 代理在收到消息后，发送PUBREC给发布者，并等待发布者的响应（PUBREL）。\n  - 发布者收到PUBREC后，发送PUBREL给代理。\n  - 代理收到PUBREL后，发送最终的确认（PUBCOMP）给发布者。\n  - 订阅者在接收到消息后，也需要向代理发送确认（PUBACK）。\n  - 这个等级适用于那些需要确保消息不丢失、不重复传递的重要数据，如计费系统或财务交易。', NULL, NULL, '2024-07-16 10:16:28', '2024-07-16 10:21:34', 0);
INSERT INTO `doc_content` VALUES (97, 1, 183, '# JVM 面试题（一）\n\n## JVM的组织架构\n\n![b62aced5c1056005e5cc9c10b2778852.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-16_11-37-50_b7ae13_b62aced5c1056005e5cc9c10b2778852.png)\n\n1. JVM 大致可以划分为三个部门：类加载器、运行时数据区和执行引擎。\n\n2. 类加载器：负责从文件系统、网络或其他来源加载 Class 文件，将 Class 文件中的二进制数据读入到内存当中。\n\n3. 运行时数据区： JVM 在执行 Java 程序时，需要在内存中分配空间来处理各种数据，这些内存区域主要包括方法区、堆、栈、程序计数器和本地方法栈。\n\n4. 执行引擎： 执行引擎是 JVM 的心脏，负责执行字节码。它包括一个虚拟处理器，还包括即时编译器（JIT Compiler）和垃圾回收器（Garbage Collector）。\n\n## JVM的内存区域是什么\n\n![4fca59659ac0bf36bfd7a2136082047f.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-16_11-39-30_ead693_4fca59659ac0bf36bfd7a2136082047f.png)\n\n**堆：**\n1. Java 堆（Java Heap）是虚拟机所管理的内存中最大的一块，被所有线程共享，在虚拟机启动时创建。\n2. Java 堆中经常会出现新生代、老年代、Eden空间、From Survivor空间、To Survivor空间等名词\n\n![0231f1f0d4dbcf2c59152c93c9e2a336.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-16_11-41-00_11141b_0231f1f0d4dbcf2c59152c93c9e2a336.png)\n\n**方法区：**\n1. 方法区是一块比较特别的区域，和堆类似，也是各个线程共享的内存区域，用于存储已被虚拟机加载的类型信息、常量、静态变量、即时编译器编译后的代码缓存等。\n2. Java 虚拟机规范对它的约束非常宽松，所以方法区的具体实现历经了许多变迁，例如 JDK 1.7 时，方法区被永久代（Permanent Generation）所代替，而在 JDK 1.8 时，永久代被彻底移除，取而代之的是元空间（Metaspace）。\n\n**程序计数器**\n1. 程序计数器（Program Counter Register）也被称为 PC 寄存器，是一块较小的内存空间。它可以看作是当前线程所执行的字节码行号指示器。\n\n**Java虚拟机栈**\n1. Java 虚拟机栈（Java Virtual Machine Stack），通常指的就是“栈”，它的生命周期与线程相同。\n2. Java 虚拟机栈（JVM 栈）中是一个个栈帧，每个栈帧对应一个被调用的方法。当线程执行一个方法时，会创建一个对应的栈帧，并将栈帧压入栈中。当方法执行完毕后，将栈帧从栈中移除。\n\n**本地方法栈**\n1. 本地方法栈（Native Method Stacks）与虚拟机栈相似\n2. 区别在于虚拟机栈是为虚拟机执行 Java 方法服务的，而本地方法栈是为虚拟机使用到的本地（Native）方法服务的。\n\n## 堆和栈的区别是什么？\n- 堆属于线程共享的内存区域，几乎所有的对象都在对上分配，生命周期不由单个方法调用所决定，可以在方法调用结束后继续存在，直到不在被任何变量引用，然后被垃圾收集器回收。\n- 栈就是前面提到的 JVM 栈（主要存储局部变量、方法参数、对象引用等），属于线程私有，通常随着方法调用的结束而消失，也就无需进行垃圾收集。\n\n## 内存泄露和内存溢出是什么意思？\n内存泄露：申请的内存空间没有被正确释放，导致内存被白白占用。\n内存溢出：申请的内存超过了可用内存，内存不够了。\n\n## 内存泄漏的原因？\n\n- 静态集合类：静态集合的生命周期和 JVM 一致，所以静态集合引用的对象不能被释放。\n- 单例模式：单例对象在初始化后会以静态变量的方式在 JVM 的整个生命周期中存在。如果单例对象持有外部的引用，那么这个外部对象将不能被 GC 回收，导致内存泄漏。\n- 连接（IO/数据）未释放：创建的连接不再使用时，需要调用 close 方法关闭连接，只有连接被关闭后，GC 才会回收对应的对象（Connection，Statement，ResultSet，Session）。忘记关闭这些资源会导致持续占有内存，无法被 GC 回收。\n- 变量作用域过大：一个变量的定义作用域大于其使用范围，很可能存在内存泄漏；或不再使用对象没有及时将对象设置为 null，很可能导致内存泄漏的发生。\n- hash值发生改变：对象 Hash 值改变，使用 HashMap、HashSet 等容器中时候，由于对象修改之后的 Hah 值和存储进容器时的 Hash 值不同，所以无法找到存入的对象，自然也无法单独删除了，这也会造成内存泄漏。说句题外话，这也是为什么 String 类型被设置成了不可变类型。\n- ThreadLocal使用不当：使用完 ThreadLocal 一定要记得使用 remove 方法来进行清除。\n\n## 如何判断对象仍然存活？\n\n**引用计数算法：**\n- 引用计数器：在对象中添加一个引用计数器，每当有一个地方引用它时，计数器值就加一；\n- 当引用失效时，计数器值就减一；任何时刻计数器为零的对象就是不可能再被使用的。\n\n**可达性分析算法：**\n- 将一系列 GC Roots 作为初始的存活对象合集（Gc Root Set），然后从该合集出发，探索所有能够被该集合引用到的对象，并将其加入到该集合中，\n- 这个过程我们也称之为标记（mark）。最终，未被探索到的对象便是死亡的，是可以回收的\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-16 11:28:14', '2024-07-23 12:40:34', 1);
INSERT INTO `doc_content` VALUES (98, 1, 184, '# Java 反射\n\n## 反射定义\n\nJava反射就是在运行状态中，可以获取任意一个类的所有属性和方法（包括私有）并且调用它们；也可以改变它的属性（包括私有）\n\n## 反射优缺点\n优点：可以代码更加灵活（毕竟可以获取任一个类的所有属性和方法），为各种框架提供开箱即用的功能提供了便利；\n缺点：\n- 在运行时有了分析操作类的能力，也增加了安全问题，比如可以无视泛型参数的安全检查（泛型参数的安全检查发生在编译时，而我们在运行时可以分析、修改类）\n- 反射的性能比较差（但对于框架而言，影响不大）\n\n## 反射作用\n反射机制允许程序在运行时获取任意一个已知名称的class的内部信息（含private），包括其modifiers（修饰符）、fields（属性）、methods（方法）等，并可在运行时改变fields内容或调用methods。我们就可以灵活的编写代码，而不需在组件之间进行源代码的衔接，降低代码的耦合度。动态代理的实现，就依赖于反射！但反射不当会造成很大的资源消耗。\n\n## 反射的具体实现\n\n**创建一个基本类：**\n```java\npackage com.ys.reflex;\npublic class Person {\n    //私有属性\n    private String name = \"Tom\";\n    //公有属性\n    public int age = 18;\n    //构造方法\n    public Person() {\n    }\n    //私有方法\n    private void say(){\n        System.out.println(\"private say()...\");\n    }\n    //公有方法\n    public void work(){\n        System.out.println(\"public work()...\");\n    }\n}\n```\n\n**通过反射，调用Class的三种方式:**\n\n1. 通过对象调用 getClass() 方法来获取,通常应用在：比如你传过来一个 Object类型的对象，而我不知道你具体是什么类，用这种方法；\n\n2. 直接通过 类名.class 的方式得到,该方法最为安全可靠，程序性能更高这说明任何一个类都有一个隐含的静态成员变量 class；\n\n3. 通过 Class 对象的 forName() 静态方法来获取，用的最多，但可能抛出 ClassNotFoundException 异常\n\n```java\n//1、通过对象调用 getClass() 方法来获取,通常应用在：比如你传过来一个 Object类型的对象p1\n    Person p1 = new Person();\n//  而我不知道你具体是什么类，用这种方法\n　　Class c1 = p1.getClass();\n \n//2、直接通过 类名.class 的方式得到,该方法最为安全可靠，程序性能更高\n//  这说明任何一个类都有一个隐含的静态成员变量 class\n　　Class c2 = Person.class;\n \n//3、通过 Class 对象的 forName() 静态方法来获取，用的最多，\n//   但可能抛出 ClassNotFoundException 异常\n　　Class c3 = Class.forName(\"com.ys.reflex.Person\");\n```\n\n一个类在 JVM 中只会有一个 Class 实例,即我们对上面获取的 c1,c2,c3进行 equals 比较，发现都是true\n\n**反射得到的Class 类获取成员变量、成员方法、接口、超类、构造方法等:**\n\n```java\n    getName()：获得类、方法、属性、构造器的完整名字。\n　　getFields()：获得类的public类型的属性。\n　　getDeclaredFields()：获得类的所有属性。包括private 声明的和继承类\n　　getMethods()：获得类的public类型的方法。\n　　getDeclaredMethods()：获得类的所有方法。包括private 声明的和继承类\n　　getMethod(String name, Class[] parameterTypes)：获得类的特定方法，name参数指定方法的名字，parameterTypes 参数指定方法的参数类型。\n　　getConstructors()：获得类的public类型的构造方法。\n　　getConstructor(Class[] parameterTypes)：获得类的特定构造方法，parameterTypes 参数指定构造方法的参数类型。\n　　newInstance()：通过类的不带参数的构造方法创建这个类的一个对象。\n```\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-16 14:15:35', '2024-07-24 15:16:54', 1);
INSERT INTO `doc_content` VALUES (99, 1, 185, '# @Transactional注解详解\n\n## 什么是事务？\n事务（Transaction）是数据库管理系统执行过程中的一个逻辑单位，由一个有限的数据库操作序列构成。这些操作要么全部执行，要么全部不执行，是一个不可分割的工作单位。事务的主要目的是简化失败恢复并保持数据的完整性。\n\n## 事务的一些基本特性：\n\n- 原子性（Atomicity）：事务作为一个整体被执行，包含在其中的对数据库的操作要么全部被执行，要么全部不执行。\n\n- 一致性（Consistency）：事务必须使数据库从一个一致性状态变换到另一个一致性状态。也就是说，一个事务执行之前和执行之后都必须处于一致性状态。\n\n- 隔离性（Isolation）：在事务开始到事务结束期间，它对数据库所做的修改，使得其他事务和该事务隔离起来，即其他事务不会看到事务中间某一时刻的数据。\n\n- 持久性（Durability）：事务完成后，它对数据库的修改是永久性的，即使系统出现故障也不会丢失。\n\n## 事务的操作：\n\n- 开启事务（一组操作开始前，开启事务）：start transaction / begin ;\n- 提交事务（这组操作全部成功后，提交事务）：commit ;\n- 回滚事务（中间任何一个操作出现异常，回滚事务）：rollback ;\n\n## @Transactional的两个重要属性\n\nrollbackFor：\n默认情况下，只有出现 RuntimeException 才回滚异常。rollbackFor属性用于控制出现何种异常类型，回滚事务。\n可以在rollbackFor属性中指定什么异常进行回滚。\n\npropagation：\n事务传播行为：指的就是当一个事务方法被另一个事务方法调用时，这个事务方法应该如何进行事务控制。\nREQUIRED ：大部分情况下都是用该传播行为即可。\nREQUIRES_NEW ：当我们不希望事务之间相互影响时，可以使用该传播行为。比如：下订单前需要记录日志，不论订单保存成功与否，都需要保证日志记录能够记录成功。\n\n## @Transactional 失效情况\n\n- 未指定回滚异常\n\n@Transactional注解默认的回滚异常类型是运行时异常（RuntimeException），如果自定义了一个异常直接继承了Exception当程序中抛出CustomException异常则不会回滚\n```java\n    @Transactional\n    public void insert() throws CustomException {\n        Notice notice = new Notice();\n        notice.setId(UUID.randomUUID().toString());\n        notice.setTitle(\"《发布关于新版本更新的通知》\");\n        notice.setAuthor(\"管理员\");\n        notice.setContent(\"******\");\n        History history = new History();\n        history.setId(UUID.randomUUID().toString());\n        history.setContent(notice.toString());\n        noticeMapper.insert(notice);\n        historyMapper.insert(history);\n        throw new CustomException();\n    }\n```\n需要在@Transactional指定回滚异常的类型，遇到异常就要回滚：@Transactional(rollbackFor = Exception.class)\n\n- 异常被捕获\n\n当抛出的异常被try-catch捕获时，事务也会失效，具体看代码：\n```java\n    @Transactional(rollbackFor = Exception.class)\n    public void insert(){\n        try {\n            Notice notice = new Notice();\n            notice.setId(UUID.randomUUID().toString());\n            notice.setTitle(\"《发布关于新版本更新的通知》\");\n            notice.setAuthor(\"管理员\");\n            notice.setContent(\"******\");\n            History history = new History();\n            history.setId(UUID.randomUUID().toString());\n            history.setContent(notice.toString());\n            noticeMapper.insert(notice);\n            historyMapper.insert(history);\n            throw new CustomException();\n        }catch (Exception e){\n            e.printStackTrace();\n        }\n    }\n```\n需要主动将此异常抛出： throws CustomException。\n修改catch包裹的代码\n```java\n        catch (Exception e){\n            e.printStackTrace();\n            TransactionAspectSupport.currentTransactionStatus().setRollbackOnly();\n        }\n```\n\n- 方法内部直接调用\n\n在Spring的Aop代理下，只有目标方法在外部进行调用，目标方法才会由Spring生成的代理对象来进行管理，如果是其他不包含@Transactional注解的方法中调用包含@Transactional注解的方法时候，有@Transactional注解的方法的事务会被忽略，则不会发生回滚。\n\n```java\n    public void insert() throws CustomException {\n        doSomething();\n    }\n\n    @Transactional(rollbackFor = Exception.class)\n    public void doSomething() throws CustomException {\n        Notice notice = new Notice();\n        notice.setId(UUID.randomUUID().toString());\n        notice.setTitle(\"《发布关于新版本更新的通知》\");\n        notice.setAuthor(\"管理员\");\n        notice.setContent(\"******\");\n        History history = new History();\n        history.setId(UUID.randomUUID().toString());\n        history.setContent(notice.toString());\n        noticeMapper.insert(notice);\n        historyMapper.insert(history);\n        throw new CustomException();\n    }\n```\n只要在insert方法上面加上@Transactional注解即可，doSomething的方法上面可以去掉了，因为同处于一个数据库链接当中。\n\n```java\n    @Transactional(rollbackFor = Exception.class)    \n    public void insert() throws CustomException {\n        doSomething();\n    }\n\n    public void doSomething() throws CustomException {\n        Notice notice = new Notice();\n        notice.setId(UUID.randomUUID().toString());\n        notice.setTitle(\"《发布关于新版本更新的通知》\");\n        notice.setAuthor(\"管理员\");\n        notice.setContent(\"******\");\n        History history = new History();\n        history.setId(UUID.randomUUID().toString());\n        history.setContent(notice.toString());\n        noticeMapper.insert(notice);\n        historyMapper.insert(history);\n        throw new CustomException();\n    }\n```\n\n- 异步多线程\n\n```java\n    @Async\n    public void save(Notice notice) throws CustomException, InterruptedException {\n        System.out.println(\"异步任务开始...\");\n        History history = new History();\n        history.setId(UUID.randomUUID().toString());\n        history.setContent(notice.toString());\n        historyMapper.insert(history);\n        Thread.sleep(5000);\n        System.out.println(\"异步任务结束...\");\n    }\n\n\n    @Transactional(rollbackFor = Exception.class)\n    public void insert() throws CustomException, InterruptedException {\n        Notice notice = new Notice();\n        notice.setId(UUID.randomUUID().toString());\n        notice.setTitle(\"《发布关于新版本更新的通知》\");\n        notice.setAuthor(\"管理员\");\n        notice.setContent(\"******\");\n\n        noticeMapper.insert(notice);\n\n        myService2.save(notice);\n\n        int a = 1/0;\n\n    }\n\n// 结果：notice没有入库，history入库了\n```\n因为@Async注解使用的是独立线程和独立的事务，和notice的不处于同一个事务当中，所以notice回滚了，但是history入库了。\n\n\n将 @Transactional和@Async绑定在一起进行使用，事务才是生效的\n\n- 使用了错误的事务传播机制\n\n|名称|描述|\n|-|-|\n|PROPAGATION_REQUIRED|	如果当前存在事务，则加入该事务；如果当前没有事务，则创建一个新的事务|\n|PROPAGATION_SUPPORTS|	如果当前存在事务，则加入该事务；如果没有事务，则以非事务方式继续运行|\n|PROPAGATION_MANDATORY|	必须运行在已存在的事务中，否则抛出异常|\n|PROPAGATION_REQUIRES_NEW|	创建一个新事务，如果已经存在一个事务，则把当前事务挂起|\n|PROPAGATION_NOT_SUPPORTED|	以非事务方式运行,如果当前存在事务，则把当前事务挂起|\n|PROPAGATION_NEVER|	以非事务方式运行，如果当前存在事务，则抛出异常。|\n|PROPAGATION_NESTED|	如果当前存在事务，则创建一个事务作为当前事务的嵌套事务来运行;如果当前没有事务，则等同于PROPAGATION_REQUIRED|\n\n\n- 方法被private或者final修饰 \n```java\n    @Transactional(rollbackFor = Exception.class)\n    private void insert() throws CustomException {\n\n    }\n\n    @Transactional(rollbackFor = Exception.class)\n    public final void insert() throws CustomException {\n\n    }\n```\n\n- 当前类没有被Spring容器托管\n在当前实体类上面要打上@Service注解，否则项目启动时也会报错。\n\n- 数据库不支持事务\n比如Mysql的Myisam存储引擎是不支持事务的，只有innodb存储引擎才支持\n\n\n', NULL, NULL, '2024-07-16 14:21:53', '2024-07-24 15:32:45', 1);
INSERT INTO `doc_content` VALUES (100, 1, 187, '# HashMap \n\n## HashMap的底层实现\nJDK1.7及其之前的版本是数组+链表，JDK1.8是数组+链表/红黑树\n\n## HashMap的数组的初始化长度\n默认的初始容量值是16\n\n## hash()函数的作用\n在计算index之前，会对key的hashCode()值，做一个hash(key)再次哈希的运算，这样可以使得Entry对象更加散列的存储到table中\nkey.hashCode() ^（异或） key.Code()>>>16; 因为这样可以使得hashCode的高16位信息也能参与到运算中来\n\n## HashMap的数组长度为什么一定要是2的幂次方\n因为2的n次方-1的二进制值是前面都0，后面几位都是1，这样的话，与hash进行&运算的结果就能保证在[0,table.length-1]范围内，而且是均匀的\n\n## HashMap的数组什么时候扩容\n\nJDK1.7版：当要添加新Entry对象时发现（1）size达到threshold（2）table[index]!=null时，两个条件同时满足会扩容\nJDK1.8版：当要添加新Entry对象时发现（1）size达到threshold（2）当table[index]下的结点个数达到8个但是table.length又没有达到64。两种情况满足其一都会导致数组扩容\n\n## JDK1.8的HashMap什么时候树化？\n当table[index]下的结点个数达到8个且table.length已经达到64\n\n## JDK1.8的HashMap什么时候反树化？\n- 当删除table[index]下的树结点时，最后这个根结点的左右结点有null，或根结点的左结点的左结点为null，会反树化\n- 当table[index]下的树结点个数少于等于6个后，又重新添加新的映射关系到map中，导致了map重新扩容了，这个时候如果table[index]下面还是小于等于6的个数，那么会反树化\n\n## 已经存储到HashMap中的key的对象属性是否可以修改\n不能修改。因为一旦修改hashCode()已经不是原来的值。\n而存储到HashMap中时，key的hashCode()–>hash()–>hash已经确定了，不会重新计算。用新的hashCode值再查询get(key)/删除remove(key)时，算的hash值与原来不一样就不找不到原来的映射关系了。\nkey的类型一般用String和Integer\n\n## table[0]中存储的是是否只有key为null的键值对？\nhashCode值不为0，但是hash(key) & table.length-1 结果是0，也是存在table[0]中\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n', NULL, NULL, '2024-07-17 11:24:15', '2024-07-17 13:17:08', 1);
INSERT INTO `doc_content` VALUES (101, 1, 188, '# HashTable\n\n## 基本介绍\n1. 存放的元素是k-v键值对。\n\n2. hashtable的键key和值value都不能为null。\n\n3. hashtable使用方法基本上和HashMap一样。\n\n4. hashtable是线程安全的，hashMap是线程不安全的。\n\n## Hashtable类 底层机制分析\n- 底层有数组Hashtable$Entry[]，初始化大小为11。\n\n- 临界值threshold为8（11 * 0.75）。\n\n- 扩容：按照自己的扩容机制来进行即可。\n\n- 执行方法addEntry(hash, key，value, index)；添加k-v封装到Entry。\n\n- 当if (count >= threshold）满足时，就进行扩容。\n\n- 按照int newCapacity =(oldCapacity << 1）+ 1的大小扩容。', NULL, NULL, '2024-07-21 15:47:15', '2024-07-23 11:52:17', 1);
INSERT INTO `doc_content` VALUES (102, 1, 189, '# HashMap 与 HashTable 对比\n\n## 两者父类不同\nHashMap是继承于AbstractMap类，而Hashtable是继承于Dictionary类，不过他们都实现了map、Coneable、Serializable接口。\n\n## 对null的支持不同\nHashtable：key和value都不能为null。\nHashMap：key可以为null，但是这样的key只能有一个，必须保证key的唯一性，可以有多个key的value为null。\n\n## 线程安全性不同\n- HashMap是非线程安全的，在多线程并发环境下，可能会产生死锁问题。\n- Hashtable是线程安全的，它的所有方法上都使用了synchronized关键字，因此可以用于多线程场景。\n- HashMap是非线程安全的，但是它的运行效率高于Hashtable，大部分单线程场景中应该使用HashMap。需要多线程操作的时候也可以使用线程安全的ConcurrentHashMap。\n- ConcurrentHashMap虽然是线程安全的，但是它的效率高于Hashtable，因为ConcurrentHashMap底层使用了分段锁，没有对整体数据进行锁定。\n\n\n## 初始容量和扩容机制不同\n- HashMap的默认初始容量为16，当需要扩容时以两倍的容量进行扩容。\n- Hashtable的默认初始容量为11，当需要扩容时以两倍+1的容量进行扩容。\n\n## 计算hash值的方法不同\n\n**HashMap的hash值计算：**\n```java\n1. 重新计算hash值\nstatic final int hash(Object key) {\n    int h;\n    return (key == null) ? 0 : (h = key.hashCode()) ^ (h >>> 16);\n}\n\n2.hash坐标的计算\n\nfinal V putVal(int hash, K key, V value, boolean onlyIfAbsent,\n                   boolean evict) {\n        Node<K,V>[] tab; Node<K,V> p; int n, i;\n        if ((tab = table) == null || (n = tab.length) == 0)\n            n = (tab = resize()).length;\n        if ((p = tab[i = (n - 1) & hash]) == null)\n        //下面的代码省略，注意上面一行\n```\n\n**Hashtable的hash值计算：**\n\n```java\npublic synchronized V put(K key, V value) {\n    // Make sure the value is not null\n    if (value == null) {\n        throw new NullPointerException();\n    }\n\n    // Makes sure the key is not already in the hashtable.\n    Entry<?,?> tab[] = table;\n    int hash = key.hashCode();\n    int index = (hash & 0x7FFFFFFF) % tab.length; //注意这里\n    //下面的代码省略，注意上面一行\n}\n```\n\n\n\n\n\n', NULL, NULL, '2024-07-23 11:52:39', '2024-07-23 11:59:52', 1);
INSERT INTO `doc_content` VALUES (103, 1, 190, '# Java 基础面试题（一）\n\n## hashCode 以及 hashCode()与equals()的联系\n\nhashCode就是对象的散列码，是根据对象的某些信息推导出的一个整数值，默认情况下表示是对象的存储地址。通过散列码，可以提高检索的效率，主要用于在散列存储结构中快速确定对象的存储地址，如Hashtable、hashMap中。\n\n**equals()与hashCode()的联系：**\nJava的超类Object类已经定义了equals()和hashCode()方法，在Obeject类中，equals()比较的是两个对象的内存地址是否相等，而hashCode()返回的是对象的内存地址。所以hashCode主要是用于查找使用的，而equals()是用于比较两个对象是否相等的。\n\n- 如果两个对象的equals()结果为true，那么这两个对象的hashCode一定相同；\n\n- 两个对象的hashCode()结果相同，并不能代表两个对象的equals()一定为true，只能够说明这两个对象在一个散列存储结构中。\n\n- 如果对象的equals()被重写，那么对象的hashCode()也要重写。\n\n\n**为什么重写equals()的同时要重写hashCode()方法：**\n\n重写了对象的equals()，但是不重写hashCode()方法，由于超类Object中的hashcode()方法始终返回的是一个对象的内存地址，而不同对象的这个内存地址永远是不相等的。即使重写了equals()方法也不能确保两个equals()结果为true的两个对象会被散列在同一个存储区域，即 obj1.equals(obj2) 的结果为true，但是不能保证 obj1.hashCode() == obj2.hashCode() 表达式的结果也为true；这种情况，就会导致数据出现不唯一，因为如果连hashCode()都不相等的话，就不会调用equals方法进行比较了，所以重写equals()就没有意义了。\n\n## 深拷贝和浅拷贝的区别\n\n浅拷贝（Shallow Copy） 创建一个新的对象，但只复制原始对象的基本数据类型的字段或引用（地址），而不复制引用指向的对象。如果原始对象中的字段是基本数据类型，那么这些字段会被复制到新对象中，而如果字段是引用类型，则新对象和原始对象的对应字段将引用同一个对象。对新对象所做的修改可能会影响到原始对象，因为它们共享相同的引用。‌\n\n深拷贝（Deep Copy） 创建一个新的对象，并且递归地复制原始对象的所有字段和引用指向的对象，而不仅仅是复制引用本身。深拷贝会递归复制整个对象结构，包括对象内部的对象，确保新对象和原始对象之间的所有关系都是独立的。这意味着对新对象所做的修改不会影响到原始对象，因为它们拥有彼此独立的副本。\n\n## java 关键字\n\n### final\n\n**不可变的类:**\n使用final修饰一个类时，意味着这个类不能被继承，也就是说，它是一个终结类，不允许其他类再来继承它。这样做的好处是防止其他类修改或扩展该类，保护了类的完整性。\n\n**不可变的方法：**\n在方法级别，final关键字表示该方法不能被子类重写。这对于确保某些方法的逻辑不被修改是非常有用的，尤其是一些关键的算法或者安全性相关的方法\n\n**不可变的变量：**\n在变量层面，final关键字用于声明常量，一旦被赋值，就无法再修改。这有助于提高代码的可读性和可维护性，同时也避免了一些潜在的bug\n\n**参数**\nfinal修饰的参数有一个只读的属性，即可以读取该参数，但是无法更改参数的值，同修饰变量一样，当参数为基本类型时，该参数的值不可改变；当参数为引用类型时，参数的引用地址不可改变。\n\n\n\n### static\n\n**类级别的属性：**\n使用static修饰的成员变量，称之为类变量。这意味着不再属于实例，而是属于整个类。无论创建了多少个类的实例，它们都共享同一个类变量 \n\n**类级别的方法：**\n在方法层面，使用static修饰的方法是类级别的方法，不依赖于类的实例而直接通过类名调用。常见的例子就是main方法\n\n**静态代码块：**\n此外，static还可以用于静态代码块，它在类加载时执行，用于初始化类级别的资源\n\n\n### volatile：多线程时的变量同步保障\nvolatile主要用于修饰变量，确保多线程情况下的可见性和有序性\n\n**可见性**\n在多线程环境下，一个线程对共享变量的修改，其他线程并不一定能立即看到。而使用volatile修饰的变量，保证了当一个线程修改了该变量的值，其他线程能够立即看到最新的值\n\n**有序性**\nvolatile还能够保证变量的有序性，防止指令重排序。在多线程环境下，由于指令重排序的存在，有时可能会导致意外的结果。而使用volatile关键字修饰的变量，可以避免这种情况\n\n![volatile.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-24_15-44-48_b97026_volatile.png)\n如果不使用volatile修饰x和y，由于指令重排序的原因，可能会导致在read()方法中输出\"重新排列!\"。而使用volatile关键字修饰后，保证了写入操作的有序性，避免了这种情况。', NULL, NULL, '2024-07-23 12:01:53', '2024-07-24 15:46:20', 1);
INSERT INTO `doc_content` VALUES (104, 1, 191, '# Java 无锁编程 \n\n## 无锁编程的理解：\n\n- 非阻塞算法：无锁编程通常使用非阻塞算法，这些算法通过不断检查条件是否满足，而不是进入阻塞状态来实现同步。\n\n- 原子操作：利用原子操作类（如java.util.concurrent.atomic包中的类）来保证单个操作的原子性，例如AtomicInteger。\n\n- CAS操作：无锁编程经常使用CAS操作来实现线程安全的数据结构。CAS操作包括比较一个值和交换一个值，这两个步骤是原子执行的。\n\n- 内存屏障：无锁编程可能需要使用内存屏障来保证操作的内存顺序性，确保在多处理器系统中内存的一致性。\n\n- 避免死锁：由于没有使用锁，无锁编程自然避免了死锁的问题，但这要求开发者更加小心地设计数据结构和同步策略。\n\n- 活锁和饥饿：虽然避免了死锁，但无锁编程需要特别注意活锁（即线程不断地尝试执行操作但总是失败）和饥饿（线程长时间无法获得所需资源）的问题。\n\n## 常见的无锁数据结构：\n\n- 原子变量：如AtomicBoolean、AtomicInteger、AtomicLong等，它们提供了基本的原子操作。\n\n- 原子数组：如AtomicIntegerArray、AtomicLongArray等，它们是原子变量的数组形式。\n\n- 原子引用：AtomicReference可以对对象引用进行原子操作。\n\n- 并发集合：如ConcurrentLinkedQueue、ConcurrentSkipListMap等，它们利用了无锁的算法来实现线程安全的集合。\n\n- StampedLock：这是一种新的锁机制，它通过在锁中增加一个版本号（stamp）来减少锁的竞争。\n  - StampedLock（印戳锁）是对ReentrantReadWriteLock读写锁的一种改进，主要的改进为：在没有写只有读的场景下，StampedLock支持不用加读锁而是直接进行读操作，最大程度提升读的效率，只有在发生过写操作之后，再加读锁才能进行读操作\n- LongAdder和LongAccumulator：这些类用于进行数值的累加操作，它们在多线程环境下不需要同步，利用了无锁技术来提高性能。\n\n- 无锁环形缓冲区：Disruptor是一个高性能的框架，它使用无锁环形缓冲区来实现线程间的消息传递。\n\n- 其他第三方库：一些第三方库，如AQSF（AbstractQueuedSynchronizer for Free），提供了基于无锁编程的同步器实现。\n\n## CAS\n\nCAS算法的过程:包含3个参数CAS(V,E,N)。V表示要更新的变量，E表示预期值，N表示新值。仅当V 值等于E值时，才会将V的值设为N，如果V值和E值不同，则说明已经有其他线程做了更新，则当前线程什么都不做。最后，CAS返回当前V的真实值。CAS操作是抱着乐观的态度进行的，它总是认为自己可以成功完成操作。当多个线程同时使用CAS操作一个变量时，只有一个会胜出，并成功更新，其余均会失败。失败的线程 不会被挂起，仅是被告知失败，并且允许再次尝试，当然也允许失败的线程放弃操作。基于这样的原理，CAS 操作即时没有锁，也可以发现其他线程对当前线程的干扰，并进行恰当的处理。\n\nCAS是一个原子操作，是由一条cpu指令完成的。\n\n**CAS 主要存在如下三个问题：**\n- ABA 问题：如果变量 V 的值原先是 A，然后被其他线程改为 B，然后又改回 A，这时CAS操作会误认为自从上次读取以来 V 没有被修改过，从而可能产生错误的操作结果。\n- 循环时间过长问题：CAS操作如果长时间不成功，会不断进行重试，这可能会导致线程长时间处于忙等（Busy-Wait）状态，从而导致 CPU 长时间做无效操作。\n- 多变量原子问题：CAS 只能保证一个变量的原子操作。\n\n**ABA 问题**\nCAS 需要检查操作值有没有发生改变，如果没有发生改变则更新。但是存在这样一种情况：一个变量原来的值为 A，后来被某个线程改为 B，再后来又被改回 A。在这种情况下，使用 CAS 进行比较时，会发现变量的值仍然为 A，从而认为这个变量没有被修改过，导致CAS 操作会成功。然而，实际上这个变量经历了 A->B->A的变化，其状态已经发生了变化，可能会导致一些逻辑上的错误。\n为了解决 ABA 问题，一种常用的方法是使用版本号，即每次更新变量时，除了改变变量的值，还会更新一个附加的版本号，这样，即使一个变量的值被改回原来的值，它的版本号也会不同。\n\n**循环时间过长问题**\nCAS 如果长时间操作不成功，则会让 CPU 在那里空转，会增加 CPU 的消耗。针对这个问题我们一般通过减少失败次数和优化重试机制来实现。\n- 退避策略：在高并发情况下，如果 CAS 操作失败，我们不用立刻就重试，而是让线程暂时“退避”，比如休眠一段时间，这样可以减少竞争线程的数量。如果失败次数增加了，我们可以逐渐增加休眠时间，比如失败小于 10 次，休眠 500毫秒，10~20次休眠 1000 毫秒这样逐步递增。\n- 限制重试次数：不能让线程一直都在那里重试，我们可以设置一个阈值，超过这个阈值，线程可能需要放弃竞争这个资源，比如报个错之类的。\n- 自适应：为了应对更加复杂的场景，我们可以采用自适应的策略来动态调整退避时间或重试策略。比如，根据当前系统的负载、CAS 操作的成功率和失败次数等因素，动态调整策略参数。这种方式实现难度比较大，容易采坑。\n\n**多变量原子问题**\nCAS 只能保证一个变量的原子操作。对于多个变量是无法做到原则操作的。我们一般有如下几种方案：\n- 使用锁：这是最直接的方案，直接放弃 CAS，采用锁机制来解决多变量原则问题。\n- 使用 AtomicReference：将多个变量封装成一个 Java 对象，然后使用 AtomicReference 对这个对象进行原子操作。\n\n## Java反射\n反射是运行中的 Java 程序获取自身的信息，并且可以操作类或对象的内部属性。\n\n**Java反射的核心概念包括以下几个方面：**\n\n- Class对象：每个加载到JVM中的类都有一个对应的Class对象，它是反射操作的基础入口点。\n\n- 获取类信息：通过Class对象，可以获取类的包名、父类、接口、注解、字段（包括静态和非静态）、方法（包括公共、保护、私有和默认访问权限的方法）等详细信息。\n\n- 实例化对象：即使没有显式知道类名，也可以通过Class.forName()方法加载类并使用newInstance()方法无参构造一个类的实例。如果需要调用带参数的构造函数，则需通过getConstructor()或getDeclaredConstructor()方法获得构造器，并调用其newInstance()方法。\n\n- 操作字段和方法：反射允许你在运行时查找、访问、修改类的字段值，以及调用方法，即使这些字段或方法是私有的也是如此。\n\n- 动态代理：Java反射机制也支持动态生成代理类，这在实现AOP（面向切面编程）框架时非常有用。\n\n\n', NULL, NULL, '2024-07-23 12:14:04', '2024-07-23 12:38:39', 1);
INSERT INTO `doc_content` VALUES (105, 1, 192, '# JVM 内存模型面试题（一）\n\n## String的两种创建方式的区别\n\n```java\nString str1 = \"abc\";\nString str2 = new String(\"abc\");\nSystem.out.println(str1 = str2);//false\n```\n第一种方式是从常量池中获取对象，第二种方式是直接在堆内存中创建一个新的对象。\n![5ee9fd67eb7823eab26162d0bec672cb.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_12-41-42_a71089_5ee9fd67eb7823eab26162d0bec672cb.png)\n\n## String 字符串拼接\n\n```java\nString str1 = \"str\";\nString str2 = \"ing\";\n \nString str3 = \"str\" + \"ing\";//常量池中的对象\nString str4 = str1 + str2; //在堆上创建的新的对象     \nString str5 = \"string\";//常量池中的对象\nSystem.out.println(str3 == str4);//false\nSystem.out.println(str3 == str5);//true\nSystem.out.println(str4 == str5);//false\n```\n![15343354457731785326691a50108d8d.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_12-42-45_0442ba_15343354457731785326691a50108d8d.png)\n\n##  String s1 = new String(\"abc\"); 创建了几个对象 \n2个\n先有字符串 “abc” 放入常量池，然后 new 了一份字符串 “abc” 放入 Java 堆（字符串常量 “abc” 在编译期就已经确定放入常量池，而 Java 堆上的 “abc” 是在运行期初始化阶段才确定），然后 Java 栈的 s1 指向 Java 堆上的 “abc”。\n\n总结：\n常量赋值存于池\n常量相加存于池\n变量相加存于堆\n\n```java\nString s1 = new String(\"abc\");// 堆内存的地值值\nString s2 = \"abc\";\nSystem.out.println(s1 == s2);// 输出false,因为一个是堆内存，一个是常量池的内存，故两者是不同的。\nSystem.out.println(s1.equals(s2));// 输出true\n\n \nString str1 = new String(\"abc\"); // 栈中的地址指向最新的new出来的堆地址\nString str2 = \"abc\"; // 存入常量池\nSystem.out.println(str1.equals(str2)); // String重写了\"equals\"是判断值是否相同所以true\nSystem.out.println(str1 == str2); // \"==\"是判断地址所以 false\n```\n\n## 八种基本类型的包装类和常量池\n\n Java基本类型的包装类的大部分都实现了常量池技术，即Byte、Integer、Long、Character、Boolean;这5种包装类型默认创建了数值[-128，127]的相应类型的缓存数据\n两种浮点数类型的包装类Float、Double 并没有实现常量池技术。\n```java\nInteger i1 = 33;\nInteger i2 = 33;\nSystem.out.println(i1 == i2);// 输出true\nInteger i11 = 333;\nInteger i22 = 333;\nSystem.out.println(i11 == i22);// 输出false\nDouble i3 = 1.2;\nDouble i4 = 1.2;\nSystem.out.println(i3 == i4);// 输出false\n```\n\n\n', NULL, NULL, '2024-07-23 12:41:03', '2024-07-23 12:47:54', 1);
INSERT INTO `doc_content` VALUES (106, 1, 193, '# redis数据使用场景\n\n## Redis ZSet 的几种使用场景\n延时队列、排行榜、限流\n\n- 延时队列\nzset 会按 score 进行排序，如果 score 代表想要执行时间的时间戳。在某个时间将它插入 zset 集合中，它变会按照时间戳大小进行排序，也就是对执行时间前后进行排序。\n\n起一个死循环线程不断地进行取第一个 key 值，如果当前时间戳大于等于该 key 值的 score 就将它取出来进行消费删除，可以达到延时执行的目的。\n![redis延时队列.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_12-53-14_5d134a_redis延时队列.png)\n- 排行榜\n以当前小时的时间戳作为 zset 的 key，把贴子ID 作为 member ，点击数评论数等作为 score，当 score 发生变化时更新 score。利用 ZREVRANGE 或者 ZRANGE 查到对应数量的记录。\n![redis排行榜.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_12-57-22_076d93_redis排行榜.png)\n- 限流\n\n把一个用户的 ID 作为 key 来定义一个 zset ，member 或者 score 可以都为访问时的时间戳。我们只需统计某个 key 下在指定时间戳区间内的个数，就能得到这个用户滑动窗口内访问频次，与最大通过次数比较，来决定是否允许通过。', NULL, NULL, '2024-07-23 12:49:19', '2024-07-23 12:59:19', 1);
INSERT INTO `doc_content` VALUES (107, 1, 195, '# Nginx 面试题（一）\n\n## nginx正向代理、反向代理 \n\n正向代理：是帮助内网客户端访问外网服务器的，正向代理代理的是客户端，一般是客户端部署的\n反向代理，是把外网客户端的请求转发给内网服务器。反向代理代理的是服务器，反向代理一般是服务器端部署的\n\n## Nginx 反向代理\n\n![cfba1bab6678f2a4e3de30445a6f46f4.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_13-22-42_0c7927_cfba1bab6678f2a4e3de30445a6f46f4.png)\n\n## 负载均衡\n\n- Nginx提供的负载均衡策略有2种：内置策略和扩展策略。\n- 内置策略为轮询，加权轮询，Ip hash。\n\n**轮询**\n![c5e2d4e3e235efc0fb5291e6748ee685.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_13-23-38_331145_c5e2d4e3e235efc0fb5291e6748ee685.png)\n\n**加权轮询**\n![12c6ebbec2351bb68f61651c549649de.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_13-24-04_281177_12c6ebbec2351bb68f61651c549649de.png)\n\niphash\n![80e932e973b38984240fea1dafacd848.png](http://49.232.129.253:9000/blog/1/doc/img/2024-07-23_13-24-15_57bea4_80e932e973b38984240fea1dafacd848.png)\n有n台 tomcat 服务器，则有n个 session，如何实现session共享？【实际开发使用的是redis】\nnginx 提供的方法是：ip进行hash运行，从而固定的ip访问固定的某台服务器。', NULL, NULL, '2024-07-23 13:01:25', '2024-07-23 13:25:02', 1);
INSERT INTO `doc_content` VALUES (108, 1, 197, '# Tomcat面试题（一）\n\n## 多个Tomcat之间实现Session共享\n\n', NULL, NULL, '2024-07-23 13:25:30', '2024-07-23 13:30:09', 1);
INSERT INTO `doc_content` VALUES (109, 1, 199, '# 网络请求面试题（一）\n\n## RESTful 是什么\nRESTful 的风格其实是一种规范，用来规范我们在写接口时的命名，用于前端与后端、项目与项目之间来传递数据。RESTful 可以使我们的接口更加简洁、快捷高效、透明。\n\n**RESTful有哪些类型：**\n- Get 获取资源\n- Put 更新资源\n- Patch 更新部分属性\n- Delete 删除资源\n- Post 创建资源\n\n## RESTful 和 HTTP 的区别\n- URL表达形式不同：\n  - HTTP接口调用的URL表达形式可以不遵循任何标准格式。\n  -  RESTful调用的URL表达形式必须遵循RESTful架构风格的URL格式规范。\n- 请求方法不同：\n  - HTTP接口调用可以使用GET、POST、PUT等HTTP请求方法。\n  - RESTful调用只能使用GET、POST、PUT、DELETE四种HTTP请求方法。\n- 数据传输格式不同：\n  - HTTP接口调用可以使用任意数据格式，如form、json、xml等。\n  - RESTful调用通常使用JSON或XML数据格式进行数据传输。\n- 资源定义不同：\n  - HTTP接口调用不依赖于任何具体的资源定义。\n  - RESTful调用的资源和API请求对应，需要在URL中对资源进行定义。\n\nRESTful调用的特点：\n- 资源标准化：RESTful是基于HTTP协议的，HTTP协议定义的URL必须是符合URI（Uniform Resource Identifier）标准的标识符。URI由协议、主机、资源路径、查询字符串和片段组成。故而RESTful要求每个资源都有一个唯一的标识符URI。\n- 无状态：因为HTTP是一种无状态协议，所以RESTful也是“无状态”的。即服务器不会保存任何客户端请求的历史信息。每个请求都是独立的，服务器不会在请求之间保留会话状态以便将来使用（如TCP连接常见的使用形式——WebSocket，当连接断开就不能使用，这种连接称为有状态的）。\n- 缓存机制：由于RESTful是基于HTTP标准定义的，因此具有HTTP缓存机制。客户端可以在收到数据后将其存储在本地缓存中，在下一次请求相同资源时可以减少网络传输，提高性能。\n', NULL, NULL, '2024-07-23 14:41:11', '2024-07-23 14:55:35', 1);
INSERT INTO `doc_content` VALUES (110, 1, 200, '# Java集合面试题\n\n## Queue 中 poll()和 remove()的区别\n\n从数据结构的角度来看，Queue 可以被看作是一个线性表，具有两个端点：队尾和队首。新元素被添加到队尾，而老元素则从队首被移除。这样保证了先进队列的元素会先被移出，实现了 FIFO 的特性。\n除了继承自 Collection 接口的方法外，Queue 接口还定义了几个重要的方法，包括：\n\n- add(element)：将指定的元素插入到队尾，如果成功则返回 true，如果队列已满则抛出异常。\n- offer(element)：将指定的元素插入到队尾，如果成功则返回 true，如果队列已满则返回 false。\n- remove()：移除并返回队首的元素，如果队列为空则抛出异常。\n- poll()：移除并返回队首的元素，如果队列为空则返回 null。\n- element()：返回队首的元素，但不移除它，如果队列为空则抛出异常。\n- peek()：返回队首的元素，但不移除它，如果队列为空则返回 null。\n', NULL, NULL, '2024-07-23 15:00:21', '2024-07-23 15:04:03', 1);
