INSERT INTO `doc_content` VALUES (121, 1, 220, '# 2024年行程\n\n## 赶往杭州上班 12月12日\n\n![image.png](http://49.232.129.253:9000/blog/1/doc/img/2025-01-15_19-18-47_f5b76f_image.png)\n\n### 飞往杭州\n![image.png](http://49.232.129.253:9000/blog/1/doc/img/2025-01-15_19-20-16_da6f1c_image.png)\n\n![8727d751150f9c278f0a13061188669.jpg](http://49.232.129.253:9000/blog/1/doc/img/2025-01-15_19-19-04_ab0aec_8727d751150f9c278f0a13061188669.jpg)\n\n![7b695c61418e9f94f989649dd8648c4.jpg](http://49.232.129.253:9000/blog/1/doc/img/2025-01-15_19-19-12_f5cad6_7b695c61418e9f94f989649dd8648c4.jpg)\n\n![1df415009780c62f277f0fab515dc92.jpg](http://49.232.129.253:9000/blog/1/doc/img/2025-01-15_19-19-15_af09e7_1df415009780c62f277f0fab515dc92.jpg)\n\n![619034a1ea0eff3f1f56536242887b6.jpg](http://49.232.129.253:9000/blog/1/doc/img/2025-01-15_19-19-34_65b03e_619034a1ea0eff3f1f56536242887b6.jpg)\n下飞机后住的宾馆，只住了一晚上，公司报道当天下午就出差去台州\n\n## 赶往台州 12月-13日\n![image.png](http://49.232.129.253:9000/blog/1/doc/img/2025-01-15_19-26-41_0cfb7c_image.png)', NULL, NULL, '2025-01-15 19:04:31', '2025-01-15 19:27:11', 1);
